# SECTION: Fresh start after Reset All Settings
# ============================================================================
# WARNING: the fallback numbers below must match SINGLE_INSTANCE_WAIT_SECONDS and FRESH_START_WAIT_FOR_OLD_APP_SECONDS in performance_governor.py; they are used only when that module fails to import.
_SINGLE_INSTANCE_WAIT_S = performance_governor.SINGLE_INSTANCE_WAIT_SECONDS if performance_governor is not None else 3.0
_FRESH_START_WAIT_FOR_OLD_APP_S = performance_governor.FRESH_START_WAIT_FOR_OLD_APP_SECONDS if performance_governor is not None else 30.0
FRESH_START_MARKER_NAME = "fresh_start_pending.json"
_FRESH_START_ROOT_FILES = ("retro_config.json", "emulator_config.json")
_FRESH_START_LOGS_FILES = ("playback_runtime.json", "playback_runtime.json.tmp", "_probe_inflight.json",
                           "retro_config.json.tmp", os.path.join("controllers", "emulator_config.json"))
_FRESH_START_MAIN_FILES = (os.path.join("media_library", "library.sqlite3"), os.path.join("media_library", "library.sqlite3-wal"),
                           os.path.join("media_library", "library.sqlite3-shm"), os.path.join("media_library", "library.sqlite3-journal"))
_FRESH_START_MAIN_FOLDERS = ("loudness", "captions", "visualizer_analysis")


def _fresh_start_marker_path():
    """logs\\fresh_start_pending.json: written by Reset All Settings, read and removed by the next start."""
    return os.path.join(_app_logs_dir(), FRESH_START_MARKER_NAME)


def _wait_for_old_app_to_close(pid, seconds):
    """Waits until the copy of the app that asked for the reset has closed (outside Windows; on Windows the single-instance guard already waited); False when it is still running."""
    if os.name == "nt" or not pid or pid == os.getpid():
        return True
    _end = time.time() + seconds
    while time.time() < _end:
        try:
            os.kill(int(pid), 0)
        except OSError:
            return True
        time.sleep(0.2)
    return False


def _fresh_start_remove(path, removed, failed):
    """Deletes one file or folder of saved data; a failure is written as one line in `failed`."""
    import shutil as _shutil
    try:
        if os.path.isdir(path) and not os.path.islink(path):
            _shutil.rmtree(path)
        elif os.path.lexists(path):
            os.remove(path)
        else:
            return
        removed.append(path)
    except Exception as e:
        failed.append("could not delete %s: %s" % (path, e))


def _wipe_saved_data_for_fresh_start(root_dir, logs_dir, main_dir, config_missing=False):
    """Runs at the start after Reset All Settings: deletes every setting and saved fact the app keeps (settings, file facts, guide and loudness data, captions, visualizer analysis, station positions, core and controller settings, game saves and the core and BIOS copies older versions made), never the user's own files or the files the app ships with; returns (removed, failed) or None when no reset was asked."""
    marker = os.path.join(logs_dir, FRESH_START_MARKER_NAME)
    # WARNING: no retro_config.json beside the exe is a fresh first boot exactly like Reset All Settings (owner 2026-11-05): config_missing runs the same wipe with no marker and no old app to wait for, and no backup is ever restored in its place.
    if not os.path.isfile(marker) and not config_missing:
        return None
    import json as _json
    removed, failed = [], []
    request = {}
    if os.path.isfile(marker):
        try:
            with open(marker, "r", encoding="utf-8") as fp:
                request = _json.load(fp)
            if not isinstance(request, dict):
                request = {}
        except Exception as e:
            failed.append("could not read %s (%s); wiping anyway" % (marker, e))
            request = {}
        if not _wait_for_old_app_to_close(request.get("old_app_pid"), _FRESH_START_WAIT_FOR_OLD_APP_S):
            failed.append("the app that asked for the reset was still running after %.0f s; wiping anyway" % _FRESH_START_WAIT_FOR_OLD_APP_S)
    for name in _FRESH_START_ROOT_FILES:
        _fresh_start_remove(os.path.join(root_dir, name), removed, failed)
    for name in _FRESH_START_LOGS_FILES:
        _fresh_start_remove(os.path.join(logs_dir, name), removed, failed)
    for name in _FRESH_START_MAIN_FILES:
        _fresh_start_remove(os.path.join(main_dir, name), removed, failed)
    for name in _FRESH_START_MAIN_FOLDERS:
        _fresh_start_remove(os.path.join(main_dir, name), removed, failed)
    roms_dir = os.path.join(main_dir, "roms")
    try:
        consoles = sorted(os.listdir(roms_dir)) if os.path.isdir(roms_dir) else []
    except OSError as e:
        consoles = []
        failed.append("could not list %s: %s" % (roms_dir, e))
    for console in consoles:
        _fresh_start_remove(os.path.join(roms_dir, console, "saves"), removed, failed)
    cores_dir = os.path.normcase(os.path.abspath(os.path.join(main_dir, "cores")))
    for path in request.get("old_tool_copies", []) or []:
        _abs = os.path.abspath(str(path))
        # WARNING: only files inside main\\cores are ever deleted from this list; anything else in it is left alone.
        if os.path.normcase(_abs).startswith(cores_dir + os.sep) and os.path.isfile(_abs):
            _fresh_start_remove(_abs, removed, failed)
    _fresh_start_remove(marker, removed, failed)
    return removed, failed


# ============================================================================
# SECTION: Process lifetime: single instance, job object & hard exit
# ============================================================================


def _acquire_single_instance():
    global _SINGLE_INSTANCE_HANDLE
    if os.name != "nt":
        return True
    try:
        import ctypes
        from ctypes import wintypes
        ERROR_ALREADY_EXISTS = 183
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        # WARNING: set restype so the 64-bit HANDLE is not truncated to a 32-bit int.
        kernel32.CreateMutexW.restype = wintypes.HANDLE
        kernel32.CreateMutexW.argtypes = [ctypes.c_void_p, wintypes.BOOL, wintypes.LPCWSTR]
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        mutex_name = "RetroTVEmulator_SingleInstance_Mutex"
        import time as _time
        _deadline = _time.time() + (_FRESH_START_WAIT_FOR_OLD_APP_S if os.path.isfile(_fresh_start_marker_path()) else _SINGLE_INSTANCE_WAIT_S)
        while True:
            handle = kernel32.CreateMutexW(None, True, mutex_name)
            last_err = ctypes.get_last_error()
            if not handle:
                return True
            if last_err != ERROR_ALREADY_EXISTS:
                _SINGLE_INSTANCE_HANDLE = handle
                return True
            kernel32.CloseHandle(handle)
            if _time.time() >= _deadline:
                return False
            _time.sleep(0.2)
    except Exception as _e:
        log.warning("[SINGLE INSTANCE] guard failed (%s) -- launching anyway", _e)
        return True

if __name__ == "__main__":
    if not _acquire_single_instance():
        log.info("[SINGLE INSTANCE] Another instance is already running -- exiting this duplicate launch.")
        sys.exit(0)
    try:
        _fresh_start_result = _wipe_saved_data_for_fresh_start(
            _app_root_dir(), _app_logs_dir(), resolve_main_dir(),
            config_missing=not os.path.exists(os.path.join(_app_root_dir(), "retro_config.json")))
    except Exception as _fresh_start_error:
        _fresh_start_result = None
        log.warning("[FRESH START] the wipe stopped early: %s", _fresh_start_error)
    if _fresh_start_result is not None:
        log.info("[FRESH START] deleted %d saved file(s) and folder(s); the user's own files were not touched", len(_fresh_start_result[0]))
        for _fresh_line in _fresh_start_result[1]:
            log.warning("[FRESH START] %s", _fresh_line)


# ============================================================================
# SECTION: Unclean-exit notice
# ============================================================================
def _run_marker_path():
    return os.path.join(_log_output_dir(), "running.marker")


_previous_run_unclean = False


def _check_previous_run_exit():
    """Logs when the previous run left its running marker behind, then writes the marker for this run."""
    global _previous_run_unclean
    try:
        _path = _run_marker_path()
        if os.path.exists(_path):
            _previous_run_unclean = True
            try:
                with open(_path, "r", encoding="utf-8") as _f:
                    _started = _f.read().strip() or "unknown"
            except Exception as _swallowed_error:
                _log_swallowed("_check_previous_run_exit: with open(_path, 'r', encoding='utf-8') as _f:", _swallowed_error)
                _started = "unknown"
            log.warning("[BOOT] The previous run (started %s) did not exit cleanly: it ended by a crash, a task kill, a power loss or a forced exit, not by a quit. "
                        "Look in %s: crash_log.txt (kept when the app relaunched itself) or crash_log_previous.txt (moved there when the app was started by hand), "
                        "and vlc-debug_previous.log.", _started, _log_output_dir())
        with open(_path, "w", encoding="utf-8") as _f:
            _f.write(broadcast_clock.now().replace(tzinfo=None).isoformat())
    except Exception as _marker_err:
        log.warning("[BOOT] running marker could not be written: %s", _marker_err)


def _clear_run_marker():
    """Removes this run's running marker; called only on a clean quit."""
    try:
        os.remove(_run_marker_path())
    except FileNotFoundError:
        pass
    except Exception as _swallowed_error:
        _log_swallowed("_clear_run_marker: os.remove(_run_marker_path())", _swallowed_error)



# ============================================================================
# SECTION: Tester report
# ============================================================================


def _tester_report_tail_lines(path, max_bytes):
    """Returns the lines in the last max_bytes of a text file, or None when the file does not exist."""
    try:
        with open(path, "rb") as _f:
            _f.seek(0, os.SEEK_END)
            _size = _f.tell()
            _f.seek(max(0, _size - max_bytes))
            _data = _f.read()
    except FileNotFoundError:
        return None
    _lines = _data.decode("utf-8", errors="replace").splitlines()
    if _size > max_bytes and _lines:
        _lines = _lines[1:]
    return _lines


def _write_tester_report(reason):
    """Writes temp/tester_report.txt: build and PC facts, whether the previous run ended uncleanly, both crash files and the latest warning, error and failure lines of app_log.txt; returns whether the file was written."""
    try:
        _dir = _log_output_dir()
        _script = os.path.abspath(sys.argv[0])
        try:
            _built = datetime.datetime.fromtimestamp(os.path.getmtime(_script)).replace(microsecond=0).isoformat()
        except OSError as _swallowed_error:
            _log_swallowed("_write_tester_report: _built = datetime.datetime.fromtimestamp(os.path.getmtime(_script))...", _swallowed_error)
            _built = "unknown"
        _out = [
            "RETRO TV TESTER REPORT",
            "written: %s (%s)" % (broadcast_clock.now().replace(tzinfo=None).isoformat(), reason),
            "script: %s, last modified %s" % (os.path.basename(_script), _built),
            "python: %s" % sys.version.split()[0],
            "machine: %s" % _boot_environment_text,
            "previous run ended uncleanly: %s" % ("yes" if _previous_run_unclean else "no"),
        ]
        for _name in ("crash_log.txt", "crash_log_previous.txt"):
            _lines = _tester_report_tail_lines(os.path.join(_dir, _name), _TESTER_REPORT_LOG_TAIL_BYTES)
            _out += ["", "=== %s (last %d lines) ===" % (_name, _TESTER_REPORT_MAX_CRASH_LINES)]
            _out += ["(none) - an empty or missing crash file means the app did not crash"] if not _lines else _lines[-_TESTER_REPORT_MAX_CRASH_LINES:]
        _lines = _tester_report_tail_lines(os.path.join(_dir, "app_log.txt"), _TESTER_REPORT_LOG_TAIL_BYTES)
        _out += ["", "=== app_log.txt warnings, errors and failures (latest %d) ===" % _TESTER_REPORT_MAX_LOG_LINES]
        _kept = [l for l in (_lines or []) if " [WARNING] " in l or " [ERROR] " in l or " [CRITICAL] " in l]
        _out += ["(none)"] if not _kept else _kept[-_TESTER_REPORT_MAX_LOG_LINES:]
        _health_lines = [l for l in (_lines or []) if " [HEALTH" in l and " [WARNING] " not in l]
        _out += ["", "=== app_log.txt health report (latest %d lines) ===" % _TESTER_REPORT_MAX_HEALTH_LINES]
        _out += ["(none)"] if not _health_lines else _health_lines[-_TESTER_REPORT_MAX_HEALTH_LINES:]
        _final = os.path.join(_dir, "tester_report.txt")
        with open(_final + ".tmp", "w", encoding="utf-8") as _f:
            _f.write("\n".join(_out) + "\n")
        os.replace(_final + ".tmp", _final)
        return True
    except Exception as _swallowed_error:
        _log_swallowed("_write_tester_report: writing temp/tester_report.txt", _swallowed_error)
        return False


def _flush_app_log():
    """Waits until every queued log line has reached app_log.txt; lines logged after this are not written."""
    _log_listener.stop()


if __name__ == "__main__":
    _check_previous_run_exit()
    _write_tester_report("start")

_CHILD_PROCESS_JOB_HANDLE = None

def _setup_child_process_job_object():
    """Tie every child process this app spawns to this process's lifetime with a Windows Job Object (KILL_ON_JOB_CLOSE)."""
    global _CHILD_PROCESS_JOB_HANDLE
    if os.name != "nt":
        return
    try:
        import ctypes
        from ctypes import wintypes

        JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = 0x2000
        JOB_OBJECT_LIMIT_BREAKAWAY_OK = 0x0800
        JobObjectExtendedLimitInformation = 9

        class _IO_COUNTERS(ctypes.Structure):
            _fields_ = [
                ("ReadOperationCount", ctypes.c_uint64),
                ("WriteOperationCount", ctypes.c_uint64),
                ("OtherOperationCount", ctypes.c_uint64),
                ("ReadTransferCount", ctypes.c_uint64),
                ("WriteTransferCount", ctypes.c_uint64),
                ("OtherTransferCount", ctypes.c_uint64),
            ]

        class _JOBOBJECT_BASIC_LIMIT_INFORMATION(ctypes.Structure):
            _fields_ = [
                ("PerProcessUserTimeLimit", ctypes.c_int64),
                ("PerJobUserTimeLimit", ctypes.c_int64),
                ("LimitFlags", wintypes.DWORD),
                ("MinimumWorkingSetSize", ctypes.c_size_t),
                ("MaximumWorkingSetSize", ctypes.c_size_t),
                ("ActiveProcessLimit", wintypes.DWORD),
                ("Affinity", ctypes.c_size_t),
                ("PriorityClass", wintypes.DWORD),
                ("SchedulingClass", wintypes.DWORD),
            ]

        class _JOBOBJECT_EXTENDED_LIMIT_INFORMATION(ctypes.Structure):
            _fields_ = [
                ("BasicLimitInformation", _JOBOBJECT_BASIC_LIMIT_INFORMATION),
                ("IoInfo", _IO_COUNTERS),
                ("ProcessMemoryLimit", ctypes.c_size_t),
                ("JobMemoryLimit", ctypes.c_size_t),
                ("PeakProcessMemoryUsed", ctypes.c_size_t),
                ("PeakJobMemoryUsed", ctypes.c_size_t),
            ]

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateJobObjectW.restype = wintypes.HANDLE
        kernel32.CreateJobObjectW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR]
        kernel32.SetInformationJobObject.argtypes = [
            wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD]
        kernel32.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
        kernel32.GetCurrentProcess.restype = wintypes.HANDLE

        job = kernel32.CreateJobObjectW(None, None)
        if not job:
            log.warning("[SHUTDOWN GUARD] CreateJobObjectW failed (err=%s) -- "
                        "orphaned ffmpeg processes will NOT be "
                        "cleaned up automatically on exit.", ctypes.get_last_error())
            return

        info = _JOBOBJECT_EXTENDED_LIMIT_INFORMATION()
        info.BasicLimitInformation.LimitFlags = (
            JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE | JOB_OBJECT_LIMIT_BREAKAWAY_OK
        )
        if not kernel32.SetInformationJobObject(
                job, JobObjectExtendedLimitInformation,
                ctypes.byref(info), ctypes.sizeof(info)):
            log.warning("[SHUTDOWN GUARD] SetInformationJobObject failed (err=%s) -- "
                        "orphaned ffmpeg processes will NOT be "
                        "cleaned up automatically on exit.", ctypes.get_last_error())
            kernel32.CloseHandle(job)
            return

        if not kernel32.AssignProcessToJobObject(job, kernel32.GetCurrentProcess()):
            log.warning("[SHUTDOWN GUARD] AssignProcessToJobObject failed (err=%s) -- "
                        "orphaned ffmpeg processes will NOT be "
                        "cleaned up automatically on exit.", ctypes.get_last_error())
            kernel32.CloseHandle(job)
            return

        _CHILD_PROCESS_JOB_HANDLE = job
        log.info("[SHUTDOWN GUARD] Child-process job object active -- ffmpeg/ffprobe "
                  "and emulator child processes will be force-killed if this app "
                  "exits for any reason.")
    except Exception as e:
        log.warning("[SHUTDOWN GUARD] Failed to set up child-process job object: %s -- "
                    "orphaned ffmpeg processes will NOT be cleaned up "
                    "automatically on exit.", e)

def _hard_exit_process(code):
    """Terminate this process immediately, bypassing Windows' DLL unload sequence (unlike os._exit() / sys.exit())."""
    # WARNING: code 0 is a clean quit and removes the running marker; every other code leaves it so the next start reports an unclean exit.
    if code == 0:
        # WARNING: settings are written by the SettingsWriter thread up to 2 s after a change; a clean quit must write the waiting save here, before the process is ended, or the last changes are lost.
        try:
            _exit_db = globals().get("db")
            if _exit_db is not None and hasattr(_exit_db, "flush_settings"):
                _exit_db.flush_settings()
        except Exception as _flush_error:
            log.warning("[QUIT] _hard_exit_process: writing the waiting settings save failed: %s", _flush_error)
        _clear_run_marker()
    try:
        _exit_health = globals().get("health_monitor")
        if _exit_health is not None:
            _exit_health.final_report("exit code %s" % code)
    except Exception as _health_exit_error:
        log.warning("[QUIT] _hard_exit_process: the health summary failed: %s", _health_exit_error)
    try:
        _flush_app_log()
    except Exception as _swallowed_error:
        _log_swallowed("_hard_exit_process: _flush_app_log()", _swallowed_error)
        pass
    try:
        _write_tester_report("exit code %s" % code)
    except Exception as _swallowed_error:
        _log_swallowed("_hard_exit_process: _write_tester_report('exit code %s' % code)", _swallowed_error)
        pass
    try:
        if os.name == "nt":
            _k32 = ctypes.windll.kernel32
            _k32.TerminateProcess(_k32.GetCurrentProcess(), code)
    except Exception as _swallowed_error:
        _log_swallowed("_hard_exit_process: if os.name == 'nt':", _swallowed_error)
        pass
    os._exit(code)


