if os.name == "nt":
    import ctypes as _ctypes
    import ctypes.wintypes as _ctwt
    import threading as _hook_threading

    _SUPPRESSED_VKS = frozenset({
        0x70, 0x71, 0x72, 0x73,
        0x74, 0x75, 0x76, 0x77,
        0x78, 0x79, 0x7A, 0x7B,
        0xAD,
        0xAE,
        0xAF,
        0xB0,
        0xB1,
        0xB2,
        0xB3,
        0xA6,
        0xA7,
        0xA8,
        0xA9,
        0xAA,
        0xAB,
        0xAC,
        0xB4,
        0xB5,
        0xB6,
        0xB7,
    })

    _WH_KEYBOARD_LL  = 13
    _WM_KEYDOWN      = 0x0100
    _WM_KEYUP        = 0x0101
    _WM_SYSKEYDOWN   = 0x0104
    _WM_SYSKEYUP     = 0x0105

    _SDLK_MASK = 0x40000000
    _VK_TO_SDL_SC = {
        0x70: 58,
        0x71: 59,
        0x72: 60,
        0x73: 61,
        0x74: 62,
        0x75: 63,
        0x76: 64,
        0x77: 65,
        0x78: 66,
        0x79: 67,
        0x7A: 68,
        0x7B: 69,
        0xAD: 127,
        0xAE: 129,
        0xAF: 128,
        0xB0: 258,
        0xB1: 259,
        0xB2: 260,
        0xB3: 261,
        0xA6: 270,
        0xA7: 271,
        0xA8: 273,
        0xA9: 272,
        0xAA: 274,
        0xAB: 275,
        0xAC: 269,
        0xB4: 265,
        0xB5: 263,
        0xB6: 266,
        0xB7: 267,
    }

    _KbdHookProcType = _ctypes.WINFUNCTYPE(
        _ctypes.c_ssize_t,
        _ctypes.c_int,
        _ctypes.c_size_t,
        _ctypes.c_ssize_t,
    )

    _u32 = _ctypes.windll.user32
    _u32.SetWindowsHookExW.restype  = _ctypes.c_void_p
    _u32.SetWindowsHookExW.argtypes = [
        _ctypes.c_int,
        _ctypes.c_void_p,
        _ctypes.c_void_p,
        _ctypes.c_ulong,
    ]
    _u32.CallNextHookEx.restype  = _ctypes.c_ssize_t
    _u32.CallNextHookEx.argtypes = [
        _ctypes.c_void_p,
        _ctypes.c_int,
        _ctypes.c_size_t,
        _ctypes.c_ssize_t,
    ]
    _u32.GetMessageW.restype  = _ctypes.c_int
    _u32.GetMessageW.argtypes = [
        _ctypes.c_void_p,
        _ctypes.c_void_p,
        _ctypes.c_uint,
        _ctypes.c_uint,
    ]
    _u32.TranslateMessage.argtypes  = [_ctypes.c_void_p]
    _u32.DispatchMessageW.argtypes  = [_ctypes.c_void_p]
    _u32.UnhookWindowsHookEx.argtypes = [_ctypes.c_void_p]
    _u32.PostThreadMessageW.restype  = _ctypes.c_int
    _u32.PostThreadMessageW.argtypes = [
        _ctypes.c_ulong,
        _ctypes.c_uint,
        _ctypes.c_size_t,
        _ctypes.c_ssize_t,
    ]

    def _kbd_hook_callback(nCode, wParam, lParam):
        try:
            if (nCode >= 0
                    and lParam
                    and wParam in (_WM_KEYDOWN, _WM_SYSKEYDOWN,
                                   _WM_KEYUP,   _WM_SYSKEYUP)):
                vk = _ctypes.c_ulong.from_address(lParam).value
                is_down = wParam in (_WM_KEYDOWN, _WM_SYSKEYDOWN)
                if vk in _SUPPRESSED_VKS:
                    sc = _VK_TO_SDL_SC.get(vk)
                    if not sc:
                        sc = 400 + vk
                    pk = sc | _SDLK_MASK
                    if is_down:
                        pygame.event.post(pygame.event.Event(
                            pygame.KEYDOWN,
                            key=pk, scancode=sc, mod=0, unicode=""))
                    else:
                        pygame.event.post(pygame.event.Event(
                            pygame.KEYUP,
                            key=pk, scancode=sc, mod=0, unicode=""))
                    return 1
        except Exception as _hcb_err:
            log.warning(f"[KBD HOOK] callback error (key passed through): {_hcb_err}")
        return _u32.CallNextHookEx(None, nCode, wParam, lParam)

    # WARNING: keep this reference; the hook callback must not be garbage collected.
    _KBD_HOOK_PROC_PTR = _KbdHookProcType(_kbd_hook_callback)
    _kbd_hook_handle   = None
    _kbd_hook_thread_id = None
    _WM_HOOK_REINSTALL = 0x8001

    def _kbd_hook_reinstall_on_pump_thread():
        """Installs a fresh hook, then drops the old one; must run on the pump thread, the only thread that reads messages."""
        global _kbd_hook_handle
        old_handle = _kbd_hook_handle
        new_handle = _u32.SetWindowsHookExW(
            _WH_KEYBOARD_LL, _KBD_HOOK_PROC_PTR, None, 0)
        if new_handle:
            _kbd_hook_handle = new_handle
            if old_handle:
                _u32.UnhookWindowsHookEx(old_handle)
        else:
            _log_warn_throttled("rtv_kbd_hook_reinstall", "[KBD HOOK] reinstall returned NULL -- keeping the existing hook")

    def _kbd_hook_request_reinstall():
        """Asks the hook's own thread for a fresh hook; safe from any thread."""
        _tid = _kbd_hook_thread_id
        if _tid:
            _u32.PostThreadMessageW(_tid, _WM_HOOK_REINSTALL, 0, 0)

    def _kbd_hook_pump():
        global _kbd_hook_handle, _kbd_hook_thread_id
        try:
            _kbd_hook_thread_id = _ctypes.windll.kernel32.GetCurrentThreadId()
            _kbd_hook_handle = _u32.SetWindowsHookExW(
                _WH_KEYBOARD_LL, _KBD_HOOK_PROC_PTR, None, 0)
            if not _kbd_hook_handle:
                print("[KBD HOOK] SetWindowsHookExW returned NULL — hook inactive.", flush=True)
                return
            msg = _ctwt.MSG()
            while _u32.GetMessageW(_ctypes.byref(msg), None, 0, 0) != 0:
                if msg.message == _WM_HOOK_REINSTALL:
                    _kbd_hook_reinstall_on_pump_thread()
                    continue
                _u32.TranslateMessage(_ctypes.byref(msg))
                _u32.DispatchMessageW(_ctypes.byref(msg))
        except Exception as _kbd_err:
            log.warning(f"[KBD HOOK] thread error: {_kbd_err}")

    _hook_threading.Thread(
        target=_kbd_hook_pump, daemon=True, name="OsKeyHookPump"
    ).start()
    print("[BOOT] OS interrupt-key suppression active (F1-F12, volume, media, mail, browser).", flush=True)

    # WARNING: the fallback numbers below must match KEY_HOOK_REINSTALL_SECONDS in performance_governor.py; they are used only when that module fails to import.
    _HOOK_REINSTALL_SEC = performance_governor.KEY_HOOK_REINSTALL_SECONDS if performance_governor is not None else 45

    # WARNING: a low-level hook is only called while its installing thread reads messages; reinstalling from this sleeping thread left a hook that never answered, so Windows handled the volume and mute keys itself. The pump thread does the install.
    def _kbd_hook_watchdog():
        while True:
            time.sleep(_HOOK_REINSTALL_SEC)
            try:
                _kbd_hook_request_reinstall()
            except Exception as _wd_err:
                _log_warn_throttled("rtv_L611", f"[KBD HOOK WATCHDOG] Reinstall attempt failed: {_wd_err}")

    _hook_threading.Thread(
        target=_kbd_hook_watchdog, daemon=True, name="OsKeyHookWatchdog"
    ).start()

    _EVENT_OBJECT_SHOW    = 0x8002
    _EVENT_OBJECT_CREATE  = 0x8000
    _WINEVENT_OUTOFCONTEXT = 0x0000
    _SW_HIDE = 0
    _OSD_HOST_CLASS_NAMES = {"NativeHWNDHost"}

    _u32.SetWinEventHook.restype  = _ctypes.c_void_p
    _u32.SetWinEventHook.argtypes = [
        _ctypes.c_uint, _ctypes.c_uint, _ctypes.c_void_p, _ctypes.c_void_p,
        _ctypes.c_uint, _ctypes.c_uint, _ctypes.c_uint,
    ]
    _u32.GetClassNameW.restype  = _ctypes.c_int
    _u32.GetClassNameW.argtypes = [_ctypes.c_void_p, _ctypes.c_wchar_p, _ctypes.c_int]
    _u32.ShowWindow.restype  = _ctypes.c_int
    _u32.ShowWindow.argtypes = [_ctypes.c_void_p, _ctypes.c_int]

    _WinEventProcType = _ctypes.WINFUNCTYPE(
        None,
        _ctypes.c_void_p,
        _ctypes.c_uint,
        _ctypes.c_void_p,
        _ctypes.c_long,
        _ctypes.c_long,
        _ctypes.c_uint,
        _ctypes.c_uint,
    )

    def _volume_osd_event_callback(hWinEventHook, event, hwnd, idObject, idChild, idEventThread, dwmsEventTime):
        try:
            if not hwnd:
                return
            _buf = _ctypes.create_unicode_buffer(64)
            _u32.GetClassNameW(hwnd, _buf, 64)
            if _buf.value in _OSD_HOST_CLASS_NAMES:
                _u32.ShowWindow(hwnd, _SW_HIDE)
        except Exception as _swallowed_error:
            _log_swallowed("_volume_osd_event_callback: hiding the volume overlay window", _swallowed_error)

    _VOLUME_OSD_PROC_PTR = _WinEventProcType(_volume_osd_event_callback)

    def _volume_osd_watcher_pump():
        try:
            hook = _u32.SetWinEventHook(
                _EVENT_OBJECT_CREATE, _EVENT_OBJECT_SHOW,
                None, _VOLUME_OSD_PROC_PTR, 0, 0, _WINEVENT_OUTOFCONTEXT)
            if not hook:
                print("[VOLUME OSD GUARD] SetWinEventHook returned NULL — OSD suppression inactive.", flush=True)
                return
            print("[VOLUME OSD GUARD] active -- native volume/mute flyout will be hidden on appearance.", flush=True)
            msg = _ctwt.MSG()
            while _u32.GetMessageW(_ctypes.byref(msg), None, 0, 0) != 0:
                _u32.TranslateMessage(_ctypes.byref(msg))
                _u32.DispatchMessageW(_ctypes.byref(msg))
        except Exception as _osd_err:
            log.warning(f"[VOLUME OSD GUARD] thread error: {_osd_err}")

    _hook_threading.Thread(
        target=_volume_osd_watcher_pump, daemon=True, name="VolumeOsdGuard"
    ).start()


