def _active_menu_bezel_shrink():
    """(shrink_x, shrink_y) for the currently-active Bezel style; no shrink while the Bezel is off."""
    # WARNING: the Bezel image path stays cached after the Bezel is turned off, so the stem alone must never decide this.
    if db is None or not db.config.get("fake_43_border_enabled", False):
        return _MENU_BEZEL_SHRINK_DEFAULT
    stem = _active_bezel_stem()
    if stem is not None:
        hit = _MENU_BEZEL_SHRINK.get(stem)
        if hit is not None:
            if db is not None and not _setting_on("warp_screen_enabled"):
                return (hit[0] * _MENU_WARP_OFF_EXTRA_SHRINK,
                        hit[1] * _MENU_WARP_OFF_EXTRA_SHRINK)
            return hit
    return _MENU_BEZEL_SHRINK_DEFAULT


