_watermark_cache = {"path": None, "raw": None, "target_w": None, "surface": None}

_watermark_transition_state = {}
# WARNING: the fallback numbers below must match WATERMARK_JUMP_TOLERANCE_PX, WATERMARK_REPOSITION_HIDE_MS, WATERMARK_ALPHA, WATERMARK_WIDTH_FRAC, WATERMARK_MARGIN_FRAC in performance_governor.py; they are used only when that module fails to import.
_WATERMARK_JUMP_TOLERANCE_PX = performance_governor.WATERMARK_JUMP_TOLERANCE_PX if performance_governor is not None else 2
_WATERMARK_REPOSITION_HIDE_MS = performance_governor.WATERMARK_REPOSITION_HIDE_MS if performance_governor is not None else 450
_WATERMARK_ALPHA = performance_governor.WATERMARK_ALPHA if performance_governor is not None else 150
_WATERMARK_WIDTH_FRAC = performance_governor.WATERMARK_WIDTH_FRAC if performance_governor is not None else 0.091
_WATERMARK_MARGIN_FRAC = performance_governor.WATERMARK_MARGIN_FRAC if performance_governor is not None else 0.12

# WARNING: the fallback numbers below must match WATERMARK_BEZEL_EXTRA_OFFSET in performance_governor.py; they are used only when that module fails to import.
_WATERMARK_BEZEL_EXTRA_OFFSET = performance_governor.WATERMARK_BEZEL_EXTRA_OFFSET if performance_governor is not None else { "bezel": (10, 10), "bezel1": (10, 10), "bezel2": (10, 10), }


def _is_live_tv_broadcast_channel(ch):
    """Return True for the real over-the-air TV channels (05-44), False for ch03 and ch04."""
    # WARNING: static noise, reception lines and the watermark all share this one test; keep it that way so they never disagree on what counts as live TV.
    try:
        return ch not in ("03", "04") and 5 <= int(ch) <= 44
    except (TypeError, ValueError) as _swallowed_error:
        _log_swallowed("_is_live_tv_broadcast_channel: return ch not in ('03', '04') and 5 <= int(ch) <= 44", _swallowed_error)
        return False


def _channel_watermark_path(channel):
    """Return the channel's watermark: the remembered image where it sits, else watermark.png in the channel's folder (found case-insensitively)."""
    channel_name = str(channel or "").zfill(2)
    if not channel_name:
        return ""
    _remembered = (db.channels_db.get(channel_name, {}) if db is not None else {}).get("watermark_path", "")
    if _remembered and os.path.isfile(_remembered):
        return _remembered
    try:
        for entry in os.listdir(WATERMARK_BASE_DIR):
            if entry.lower() == f"channel {channel_name}".lower():
                folder = os.path.join(WATERMARK_BASE_DIR, entry)
                candidate = os.path.join(folder, "watermark.png")
                if os.path.isfile(candidate):
                    return candidate
    except OSError as _swallowed_error:
        _log_swallowed("_channel_watermark_path: for entry in os.listdir(WATERMARK_BASE_DIR):", _swallowed_error)
        pass
    return ""


def _draw_watermark(screen, bounds_rect=None, apply_bezel_offset=True, state_key="main"):
    """Draw the current channel's per-channel watermark in the bottom-right corner."""
    channel = app_state.get("current_channel", "") if app_state is not None else ""
    ch_info = db.channels_db.get(str(channel).zfill(2), {}) if db is not None else {}
    if not ch_info.get("watermark_enabled", False):
        return
    path = _channel_watermark_path(channel)
    if not path or not os.path.isfile(path):
        return
    try:
        if bounds_rect is not None:
            ox, oy, sw, sh = bounds_rect.x, bounds_rect.y, bounds_rect.width, bounds_rect.height
        else:
            ox, oy = 0, 0
            sw, sh = screen.get_size()
        if sw <= 0 or sh <= 0:
            return

        _wm_state = _watermark_transition_state.setdefault(
            state_key, {"last_rect": None, "hide_until": 0})
        _wm_now = pygame.time.get_ticks()
        _wm_cur_rect = (ox, oy, sw, sh)
        _wm_prev_rect = _wm_state["last_rect"]
        if _wm_prev_rect is not None and any(
                abs(_wm_cur_rect[i] - _wm_prev_rect[i]) > _WATERMARK_JUMP_TOLERANCE_PX
                for i in range(4)):
            _wm_state["hide_until"] = _wm_now + _WATERMARK_REPOSITION_HIDE_MS
        _wm_state["last_rect"] = _wm_cur_rect
        if _wm_now < _wm_state["hide_until"]:
            return

        target_w = max(24, int(sw * _WATERMARK_WIDTH_FRAC))
        cache = _watermark_cache

        if cache["path"] != path:
            loaded = None
            try:
                loaded = pygame.image.load(path).convert_alpha()
            except Exception as _load_err:
                try:
                    _decoded = pygame.image.load(path)
                    loaded = _decoded.convert_alpha()
                except Exception as _load_err2:
                    print(f"[WATERMARK] Failed to load watermark image "
                          f"'{os.path.basename(path)}': {_load_err2}")
                    log.warning("[WATERMARK] Could not load %s: %s (retry: %s)",
                                path, _load_err, _load_err2)
            # WARNING: record the attempt even on failure; cache["raw"] is False marks a known-bad image, and without it the load is retried every frame.
            cache["raw"] = loaded if loaded is not None else False
            cache["path"] = path
            cache["target_w"] = None

        raw = cache["raw"]
        if raw is False:
            return
        if cache["target_w"] != target_w or cache["surface"] is None:
            raw_w, raw_h = raw.get_size()
            if raw_w <= 0 or raw_h <= 0:
                return
            target_h = max(1, int(raw_h * (target_w / raw_w)))
            scaled = pygame.transform.smoothscale(raw, (target_w, target_h))
            faded = scaled.copy()
            alpha_arr = pygame.surfarray.pixels_alpha(faded)
            alpha_arr[:] = (alpha_arr.astype(np.uint16) * _WATERMARK_ALPHA // 255).astype(np.uint8)
            del alpha_arr
            cache["surface"] = faded
            cache["target_w"] = target_w

        margin_x = max(6, int(sw * _WATERMARK_MARGIN_FRAC))
        margin_y = max(6, int(sh * _WATERMARK_MARGIN_FRAC))
        extra_x = 0.0
        extra_y = 0.0
        if apply_bezel_offset:
            _stem = _active_bezel_stem_if_on()
            if _stem is not None:
                extra_x, extra_y = _WATERMARK_BEZEL_EXTRA_OFFSET.get(_stem, (0, 0))
        wm_rect = cache["surface"].get_rect(bottomright=(
            ox + sw - margin_x - int(extra_x),
            oy + sh - margin_y - int(extra_y),
        ))
        screen.blit(cache["surface"], wm_rect)
    except Exception as e:
        log.warning("_draw_watermark: draw failed: %s", e)


_STARTUP_REG_PATH = r"Software\Microsoft\Windows NT\CurrentVersion\Winlogon"
_STARTUP_REG_NAME = "Shell"
_DEFAULT_SHELL = "explorer.exe"

_LEGACY_STARTUP_REG_PATH = r"Software\Microsoft\Windows\CurrentVersion\Run"
_LEGACY_STARTUP_REG_NAME = "RetroTVEmulator"


# ============================================================================
# SECTION: Start-on-boot & deferred settings save
# ============================================================================


def _get_startup_command():
    if getattr(sys, "frozen", False):
        return f'"{sys.executable}" --as-shell'
    return f'"{sys.executable}" "{os.path.abspath(__file__)}" --as-shell'


def _windows_system_exe(name, subfolder=""):
    """Full path of a program that ships with Windows (explorer.exe in the Windows folder, shutdown.exe in System32), so a file of the same name in the app folder is never started instead; the bare name when the Windows folder is unknown."""
    # WARNING: Windows looks for a program started by its bare name in the app's own folder first; always start these two by full path.
    _windows_root = os.environ.get("SystemRoot") or os.environ.get("windir") or ""
    if not _windows_root:
        return name
    return os.path.join(_windows_root, subfolder, name) if subfolder else os.path.join(_windows_root, name)


def _launch_explorer_fallback():
    if os.name != "nt":
        return
    try:
        subprocess.Popen([_windows_system_exe("explorer.exe")])
    except Exception as e:
        log.warning(f"[STARTUP] Could not launch explorer.exe fallback: {e}")


def _read_registry_text(path, name):
    """Returns the text of one value under HKEY_CURRENT_USER, or None when the key or value does not exist; it only reads."""
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, path, 0, winreg.KEY_READ) as key:
            value, _kind = winreg.QueryValueEx(key, name)
        return str(value)
    except FileNotFoundError:
        return None
    except Exception as e:
        log.warning("[STARTUP] Could not read registry value %s\\%s: %s", path, name, e)
        return None


def _set_start_on_boot(enabled):
    if os.name != "nt":
        print("[STARTUP] Not running on Windows — start-on-boot toggle has no effect here.")
        return False
    try:
        import winreg
        # WARNING: shell mode writes to the registry only when the owner turns it on in Advanced Settings; turning it off (or Reset Settings) writes only when the registry still holds this app's own entry, so a PC that never used shell mode is never touched.
        _shell_is_ours = bool(enabled)
        _legacy_text = None
        if not enabled:
            _shell_is_ours = "--as-shell" in (_read_registry_text(_STARTUP_REG_PATH, _STARTUP_REG_NAME) or "")
            _legacy_text = _read_registry_text(_LEGACY_STARTUP_REG_PATH, _LEGACY_STARTUP_REG_NAME)
            if not _shell_is_ours and _legacy_text is None:
                log.info("[STARTUP] Shell mode is off and the registry holds no Retro TV entry -- nothing written.")
                return True
        if enabled or _legacy_text is not None:
            try:
                with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _LEGACY_STARTUP_REG_PATH, 0, winreg.KEY_SET_VALUE) as legacy_key:
                    try:
                        winreg.DeleteValue(legacy_key, _LEGACY_STARTUP_REG_NAME)
                    except FileNotFoundError:
                        pass
            except FileNotFoundError:
                pass

        if _shell_is_ours:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _STARTUP_REG_PATH, 0, winreg.KEY_SET_VALUE) as key:
                if enabled:
                    winreg.SetValueEx(key, _STARTUP_REG_NAME, 0, winreg.REG_SZ, _get_startup_command())
                else:
                    winreg.SetValueEx(key, _STARTUP_REG_NAME, 0, winreg.REG_SZ, _DEFAULT_SHELL)
        return True
    except Exception as e:
        log.warning(f"[STARTUP] Failed to {'enable' if enabled else 'disable'} start-on-boot: {e}")
        return False


def _mark_settings_dirty():
    now = pygame.time.get_ticks()
    if not app_state.get("_settings_dirty", False):
        app_state["_settings_dirty_first"] = now
    app_state["_settings_dirty"] = True
    app_state["_settings_dirty_since"] = now


def _flush_settings_if_dirty(force=False):
    if db is None or not app_state.get("_settings_dirty", False):
        return
    now = pygame.time.get_ticks()
    quiet_elapsed = now - app_state.get("_settings_dirty_since", now)
    total_elapsed = now - app_state.get("_settings_dirty_first", now)
    if force or quiet_elapsed > 400 or total_elapsed > 1500:
        db.save_settings_async(force=force)
        app_state["_settings_dirty"] = False


