_gamepad_streak_signature = None
_gamepad_streak_consumed  = False

# WARNING: the fallback numbers below must match MISSING_MEDIA_BANNER_REARM_MS in performance_governor.py; they are used only when that module fails to import.
_MISSING_MEDIA_BANNER_REARM_MS = performance_governor.MISSING_MEDIA_BANNER_REARM_MS if performance_governor is not None else 5 * 60 * 1000

_missing_media_streak_signature = None
_missing_media_streak_consumed  = False
_missing_media_streak_consumed_at = None
_missing_media_streak_label = None

_missing_media_live_report = None

_SERVER_BANNER_REARM_MS = 5 * 60 * 1000
_server_streak_signature = None
_server_streak_consumed = False
_server_streak_consumed_at = None


# ============================================================================
# SECTION: Drive-failure detection
# ============================================================================


def _report_missing_media(signature, label):
    """Hand the current missing-media condition, or None, to the shared status-banner system."""
    global _missing_media_live_report
    _missing_media_live_report = (signature, label) if signature is not None else None


_status_banner_current    = None
_status_banner_started_at = None
_caption_memory_refusal_pending = False
_caption_memory_banner_pending = False


def _on_caption_memory_refused(total_gb, available_gb, needed_gb):
    """Called from any thread when the caption model is refused for lack of memory; the main loop does the rest."""
    global _caption_memory_refusal_pending
    _caption_memory_refusal_pending = True


def _apply_caption_memory_refusal():
    """Main thread: switches Live Captions off and starts the red banner after the caption model was refused for lack of memory."""
    global _caption_memory_refusal_pending, _caption_memory_banner_pending, _caption_prewarm_started
    if not _caption_memory_refusal_pending:
        return
    _caption_memory_refusal_pending = False
    if db is not None:
        _was_on = bool(db.config.get("tv_captions_enabled", False)) or bool(db.config.get("dvd_captions_enabled", False))
        db.config["tv_captions_enabled"] = False
        db.config["dvd_captions_enabled"] = False
        try:
            db.save_settings()
        except Exception as e:
            log.warning("[ASR MEMORY] could not save the captions-off setting: %s", e)
        if game_deck is not None:
            try:
                game_deck.refresh_from_config(db.config)
            except Exception as e:
                log.warning("[ASR MEMORY] game deck refresh failed: %s", e)
        if not _was_on:
            return
    with _caption_prewarm_lock:
        _caption_prewarm_started = False
    try:
        _release_tv_caption_state_when_off("not enough memory for live captions")
    except Exception as e:
        log.warning("[ASR MEMORY] could not clear the caption state: %s", e)
    _caption_memory_banner_pending = True
    log.warning("[ASR MEMORY] Live Captions switched off: not enough free memory to load the caption model")


def _drive_banner_roots():
    """Returns the drive roots the banner names: the drive the channel on screen went to Static for, or on Channel 03 the drive a game, DVD or media player launch failed from."""
    # WARNING: a drive that is only flagged slow never counts here; the banner waits for a real failure, or a playing movie from a slow-flagged drive shows a false banner.
    _cur_ch = str(globals().get("app_state", {}).get("current_channel", "")).zfill(2)
    roots = set()
    if _cur_ch == "04":
        return roots
    if _cur_ch == "03":
        _gd = globals().get("game_deck")
        if _gd is not None:
            roots.update(_gd.drive_launch_failures())
        return roots
    for _dead_map in (
            globals().get("_station_confirmed_dead_drive", {}),
            globals().get("_visualizer_confirmed_dead_drive", {})):
        _root = _dead_map.get(_cur_ch)
        if _root:
            roots.add(_root)
    return roots


def _channel_failure_is_drive_wide(ch_key, entry):
    """Return whether a failure entry belongs to a confirmed-dead drive."""
    if not entry:
        return False
    if str(entry.get("reason", "")).strip().lower() == "drive not responding":
        return True
    _file_path = entry.get("file_path")
    if not _file_path:
        return False
    try:
        _root = media._drive_root_of(_file_path)
        if not _root:
            return False
        return (
            globals().get("_station_confirmed_dead_drive", {}).get(ch_key) == _root
            or globals().get("_visualizer_confirmed_dead_drive", {}).get(ch_key) == _root
        )
    except Exception as _swallowed_error:
        _log_swallowed("_channel_failure_is_drive_wide: _root = media._drive_root_of(_file_path)", _swallowed_error)
        return False


# ============================================================================
# SECTION: Status banners
# ============================================================================


def _advance_status_banner_streaks():
    _apply_caption_memory_refusal()
    global _drive_streak_signature, _drive_streak_consumed, _drive_streak_consumed_at
    global _gamepad_streak_signature, _gamepad_streak_consumed
    global _missing_media_streak_signature, _missing_media_streak_consumed
    global _missing_media_streak_consumed_at, _missing_media_streak_label
    global _server_streak_signature, _server_streak_consumed
    global _server_streak_consumed_at

    _mm = _missing_media_live_report
    if _mm is None:
        _missing_media_streak_signature = None
        _missing_media_streak_consumed = False
        _missing_media_streak_consumed_at = None
        _missing_media_streak_label = None
    else:
        _mm_sig, _mm_label = _mm
        if _mm_sig != _missing_media_streak_signature:
            _missing_media_streak_signature = _mm_sig
            _missing_media_streak_consumed = False
            _missing_media_streak_consumed_at = None
        elif (_missing_media_streak_consumed and _missing_media_streak_consumed_at is not None
                and pygame.time.get_ticks() - _missing_media_streak_consumed_at >= _MISSING_MEDIA_BANNER_REARM_MS):
            _missing_media_streak_consumed = False
            _missing_media_streak_consumed_at = None
        _missing_media_streak_label = _mm_label

    _app = globals().get("app_state", {})
    _remote = _app.get("active_remote_server")
    _remote_status = _app.get("remote_server_status")
    _locked_failures = ()
    try:
        if db is not None:
            _locked_failures = tuple(sorted(
                ch_key for ch_key in _channel_playback_failures
                if db.channels_db.get(ch_key, {}).get("server_locked", False)
            ))
    except Exception as _swallowed_error:
        _log_swallowed("_advance_status_banner_streaks: if db is not None:", _swallowed_error)
        _locked_failures = ()
    if _remote is not None and (_remote_status == "offline" or _locked_failures):
        _server_sig = (
            str(_remote.get("name", _remote.get("host", "server"))),
            _remote_status if _remote_status == "offline" else "media",
            _locked_failures,
        )
        if _server_sig != _server_streak_signature:
            _server_streak_signature = _server_sig
            _server_streak_consumed = False
            _server_streak_consumed_at = None
        elif (_server_streak_consumed
              and _server_streak_consumed_at is not None
              and pygame.time.get_ticks() - _server_streak_consumed_at >= _SERVER_BANNER_REARM_MS):
            _server_streak_consumed = False
            _server_streak_consumed_at = None
    else:
        _server_streak_signature = None
        _server_streak_consumed = False
        _server_streak_consumed_at = None

    roots = frozenset(_drive_banner_roots())
    if roots:
        _cur_ch = str(_app.get("current_channel", "")).zfill(2)
        _cur_failure = _channel_playback_failures.get(_cur_ch)
        if (_cur_failure is not None
                and not _channel_failure_is_drive_wide(_cur_ch, _cur_failure)
                and pygame.time.get_ticks() - _cur_failure.get("shown_at", 0) < CHANNEL_FAILURE_MESSAGE_MS):
            roots = frozenset()
    if not roots:
        _drive_streak_signature = None
        _drive_streak_consumed = False
        _drive_streak_consumed_at = None
    elif roots != _drive_streak_signature:
        _drive_streak_signature = roots
        _drive_streak_consumed = False
        _drive_streak_consumed_at = None
    elif (_drive_streak_consumed and _drive_streak_consumed_at is not None
            and pygame.time.get_ticks() - _drive_streak_consumed_at >= _DRIVE_BANNER_REARM_MS):
        _drive_streak_consumed = False
        _drive_streak_consumed_at = None

    try:
        import game_deck
        path = game_deck.gamepad_permission_denied_path()
    except Exception as _swallowed_error:
        _log_swallowed("_advance_status_banner_streaks: import game_deck", _swallowed_error)
        path = None
    if not path:
        _gamepad_streak_signature = None
        _gamepad_streak_consumed = False
    elif path != _gamepad_streak_signature:
        _gamepad_streak_signature = path
        _gamepad_streak_consumed = False


def _status_banner_is_active(name):
    if name == "captions_memory":
        return _caption_memory_banner_pending
    if name == "server":
        return _server_streak_signature is not None
    if name == "drive":
        return _drive_streak_signature is not None
    if name == "gamepad":
        return _gamepad_streak_signature is not None
    if name == "missing_media":
        return _missing_media_streak_signature is not None
    return False


def _status_banner_is_consumed(name):
    if name == "captions_memory":
        return False
    if name == "server":
        return _server_streak_consumed
    if name == "drive":
        return _drive_streak_consumed
    if name == "gamepad":
        return _gamepad_streak_consumed
    if name == "missing_media":
        return _missing_media_streak_consumed
    return True


def _mark_status_banner_consumed(name):
    global _drive_streak_consumed, _drive_streak_consumed_at, _gamepad_streak_consumed
    global _missing_media_streak_consumed, _missing_media_streak_consumed_at
    global _server_streak_consumed, _server_streak_consumed_at, _caption_memory_banner_pending
    if name == "captions_memory":
        _caption_memory_banner_pending = False
    elif name == "server":
        _server_streak_consumed = True
        _server_streak_consumed_at = pygame.time.get_ticks()
    elif name == "drive":
        _drive_streak_consumed = True
        _drive_streak_consumed_at = pygame.time.get_ticks()
    elif name == "gamepad":
        _gamepad_streak_consumed = True
    elif name == "missing_media":
        _missing_media_streak_consumed = True
        _missing_media_streak_consumed_at = pygame.time.get_ticks()


def _drive_banner_label(roots):
    """Returns the status banner text naming the drives that are not responding."""
    return "CHECK YOUR DRIVE — " + ", ".join(r.rstrip("\\") for r in sorted(roots)) + " isn't responding"


def _status_banner_duration_ms(name):
    """How long a shared status banner stays up."""
    return CAPTION_MEMORY_BANNER_MS if name == "captions_memory" else STATUS_BANNER_DURATION_MS


def _status_banner_label(name):
    if name == "captions_memory":
        return CAPTION_MEMORY_BANNER_LABEL
    if name == "server" and _server_streak_signature is not None:
        server_name = _server_streak_signature[0]
        return f"SERVER OFFLINE — {server_name}"
    if name == "drive" and _drive_streak_signature is not None:
        return _drive_banner_label(_drive_streak_signature)
    if name == "gamepad" and _gamepad_streak_signature is not None:
        return "CONTROLLER NOT READABLE — add your user to the 'input' group and restart"
    if name == "missing_media" and _missing_media_streak_signature is not None:
        return _missing_media_streak_label
    return None


def _draw_status_banner_bar(screen, label):
    """Draw a shared status banner onto the virtual frame."""
    sw, sh = screen.get_size()
    picture_rect = pygame.Rect(0, 0, sw, sh)
    font_size = 18
    pad_x = 14
    pad_y = 8
    margin = 12
    border_w = 2

    font = _cached_sys_font("Arial", font_size, bold=True)
    text_surf = font.render(label, True, COLOR_BANNER_TEXT)
    bar_w = text_surf.get_width() + pad_x * 2
    bar_h = text_surf.get_height() + pad_y * 2
    bar_w = min(bar_w, picture_rect.width)
    bar_surf = pygame.Surface((bar_w, bar_h), pygame.SRCALPHA)
    bar_surf.fill(COLOR_BANNER_FILL)
    pygame.draw.rect(bar_surf, COLOR_BANNER_EDGE, bar_surf.get_rect(), width=border_w)
    bar_surf.blit(text_surf, (pad_x, pad_y))
    bar_x = picture_rect.x + (picture_rect.width - bar_w) // 2
    bar_y = picture_rect.bottom - bar_h - margin
    screen.blit(bar_surf, (bar_x, bar_y))


def _draw_status_banners(screen):
    global _status_banner_current, _status_banner_started_at
    try:
        _advance_status_banner_streaks()
        now = pygame.time.get_ticks()
        order = ("captions_memory", "server", "drive", "gamepad", "missing_media")

        if _caption_memory_banner_pending and _status_banner_current != "captions_memory":
            _status_banner_current = "captions_memory"
            _status_banner_started_at = now

        if _status_banner_current is not None:
            if not _status_banner_is_active(_status_banner_current):
                _status_banner_current = None
                _status_banner_started_at = None
            elif now - _status_banner_started_at >= _status_banner_duration_ms(_status_banner_current):
                _mark_status_banner_consumed(_status_banner_current)
                _status_banner_current = None
                _status_banner_started_at = None

        if _status_banner_current is None:
            for name in order:
                if _status_banner_is_active(name) and not _status_banner_is_consumed(name):
                    _status_banner_current = name
                    _status_banner_started_at = now
                    break

        if _status_banner_current is None:
            return
        _draw_status_banner_bar(screen, _status_banner_label(_status_banner_current))
    except Exception as e:
        log.warning("_draw_status_banners: draw failed: %s", e)


# ============================================================================
# SECTION: Captions overlay (TV station & visualizer)
# ============================================================================

_tv_caption_cache = {"path": None, "cues": [], "pending_path": None, "resolved_at": 0.0,
                     "live_session": None, "channel": None}

_tv_caption_prefetch = {"path": None, "session": None, "channel": None}

# WARNING: the fallback numbers below must match TV_CAPTION_RETRY_SECONDS in performance_governor.py; they are used only when that module fails to import.
_TV_CAPTION_RETRY_SECONDS = performance_governor.TV_CAPTION_RETRY_SECONDS if performance_governor is not None else 8.0


# WARNING: the fallback numbers below must match CAPTION_MAX_HOLD_MS in performance_governor.py; they are used only when that module fails to import.
_CAPTION_MAX_HOLD_MS = performance_governor.CAPTION_MAX_HOLD_MS if performance_governor is not None else 7000
# WARNING: the fallback numbers below must match CAPTION_MIN_FIRST_SHOW_MS in performance_governor.py; they are used only when that module fails to import.
_CAPTION_MIN_FIRST_SHOW_MS = performance_governor.CAPTION_MIN_FIRST_SHOW_MS if performance_governor is not None else 600
_caption_first_sight = {"key": None, "skip": False}
_caption_last_path = {"path": None}


def _tv_caption_color_rgb():
    """Resolve the persisted tv_captions_color config value to an RGB triple."""
    from game_deck import LIST_TEXT_COLOR_RGB
    name = db.config.get("tv_captions_color", "white") if db is not None else "white"
    return LIST_TEXT_COLOR_RGB.get(name, COLOR_CAPTION_DEFAULT)


def _stop_tv_live_caption_session():
    """Stop the LiveCaptionSession running for the currently cached path, if any."""
    live = _tv_caption_cache.get("live_session") if isinstance(_tv_caption_cache, dict) else None
    if live is not None:
        try:
            live.stop()
        except Exception as e:
            log.warning("_stop_tv_live_caption_session: live.stop() failed: %s", e)


def _stop_tv_caption_prefetch():
    """Stop and clear the lookahead caption session for the next file on this channel, if any."""
    global _tv_caption_prefetch
    session = _tv_caption_prefetch.get("session") if isinstance(_tv_caption_prefetch, dict) else None
    if session is not None:
        try:
            session.stop()
        except Exception as e:
            log.warning("_stop_tv_caption_prefetch: session.stop() failed: %s", e)
    _tv_caption_prefetch = {"path": None, "session": None, "channel": None}


def _unload_caption_model(reason):
    """Frees the Whisper model once no caption session needs it, and lets the next captions-on pre-warm it again."""
    global _caption_prewarm_started
    if media.release_whisper_model(reason):
        with _caption_prewarm_lock:
            _caption_prewarm_started = False


def _maybe_unload_caption_model_after_show(reason):
    """Frees the Whisper model unless the cached or prefetched show is already being transcribed."""
    if (_tv_caption_cache.get("live_session") is None
            and _tv_caption_cache.get("pending_path") is None
            and _tv_caption_prefetch.get("session") is None
            and not _tv_caption_prefetch.get("path")):
        _unload_caption_model(reason)


# WARNING: stop() is permanent; the cache must be reset with it, or turning captions back on reuses the dead session.
def _release_tv_caption_state_when_off(reason="captions off"):
    global _tv_caption_cache
    _caption_last_path["path"] = None
    live = _tv_caption_cache.get("live_session")
    prefetch_session = _tv_caption_prefetch.get("session")
    if (live is None and prefetch_session is None
            and _tv_caption_cache.get("path") is None
            and _tv_caption_cache.get("pending_path") is None
            and not _tv_caption_prefetch.get("path")):
        _unload_caption_model(reason)
        return
    _stop_tv_live_caption_session()
    _stop_tv_caption_prefetch()
    _tv_caption_cache = {"path": None, "cues": [], "pending_path": None,
                          "resolved_at": 0.0, "live_session": None, "channel": None}
    if live is not None or prefetch_session is not None:
        log.info("[TV CAPTIONS] %s -- live transcription stopped, caption state cleared", reason)
    _unload_caption_model(reason)


_caption_prewarm_lock = threading.Lock()
_caption_prewarm_started = False


def _start_caption_model_prewarm(reason):
    """Load and warm the Whisper model on a background thread; later calls do nothing."""
    global _caption_prewarm_started
    with _caption_prewarm_lock:
        if _caption_prewarm_started:
            return
        _caption_prewarm_started = True

    def _job():
        try:
            time.sleep(0.5)
            _t0 = time.monotonic()
            _model = media._get_whisper_model()
            if _model is None:
                log.warning("[ASR] caption model NOT loaded (%s) -- auto-captioning is unavailable this session", reason)
            else:
                log.info("[ASR] caption model pre-warmed (%s) in %.1fs", reason, time.monotonic() - _t0)
        except Exception as _e:
            log.warning("[ASR] caption model pre-warm failed (%s): %s", reason, _e)

    threading.Thread(target=_job, daemon=True, name="caption-model-prewarm").start()


def _maybe_start_tv_caption_prefetch(ch, current_path):
    """Start transcribing the next file scheduled on this channel once the current live caption session has caught up."""
    if _tv_caption_prefetch.get("session") is not None or _tv_caption_prefetch.get("path"):
        return
    if db is None or not ch or not current_path:
        return
    try:
        ch_info = db.channels_db.get(ch, {})
        if not ch_info or not ch_info.get("active", True):
            return
        next_path = None
        tl_upcoming = None
        if ch_info.get("commercials_enabled", False):
            tl_upcoming = _next_n_from_block_timeline(ch, current_path, n=2)
        if tl_upcoming and len(tl_upcoming) > 1:
            next_path = tl_upcoming[1].get("path")
        else:
            ordered, block_key = _get_channel_ordered_content(ch, ch_info)
            if ordered and block_key:
                upcoming = _next_n_from_ordered(ordered, current_path, n=2)
                if len(upcoming) > 1:
                    for p in _paths_from_entry(upcoming[1]):
                        next_path = p
                        break
        if not next_path or not os.path.exists(next_path):
            return
        next_path = os.path.normpath(next_path)
        if next_path.lower() == os.path.normpath(current_path).lower():
            return
    except Exception as _swallowed_error:
        _log_swallowed("_maybe_start_tv_caption_prefetch: ch_info = db.channels_db.get(ch, {})", _swallowed_error)
        return

    _tv_caption_prefetch["path"] = next_path
    _tv_caption_prefetch["channel"] = ch
    _tv_caption_prefetch["session"] = None

    def _prefetch_job():
        session = None
        try:
            info = resolve_caption_source(next_path)
            if info.get("kind") is None and info.get("mtime") is not None and not asr_known_unavailable():
                session = LiveCaptionSession(next_path, start_sec=0.0).start()
        except Exception as e:
            log.warning("[TV CAPTIONS] prefetch resolve failed for %s: %s", next_path, e)
        if _tv_caption_prefetch.get("path") == next_path:
            _tv_caption_prefetch["session"] = session
        elif session is not None:
            session.stop()

    threading.Thread(target=_prefetch_job, daemon=True, name="TVCaptionPrefetch").start()


def _caption_cues_for(path):
    """Return the current cue list for path, or [] while resolution runs on a background thread."""
    # WARNING: must always return a list, never raise and never block the caller; path may be None.
    global _tv_caption_cache, _tv_caption_prefetch
    if not path:
        _stop_tv_live_caption_session()
        _stop_tv_caption_prefetch()
        _tv_caption_cache = {"path": None, "cues": [], "pending_path": None,
                              "resolved_at": 0.0, "live_session": None, "channel": None}
        return []
    ch = str(app_state.get("current_channel", "")).zfill(2)
    if _tv_caption_cache.get("path") == path:
        live = _tv_caption_cache.get("live_session")
        if live is not None:
            if live.ready:
                _maybe_start_tv_caption_prefetch(ch, path)
                return live.snapshot()
            return []
        cues = _tv_caption_cache.get("cues") or []
        if cues:
            _maybe_start_tv_caption_prefetch(ch, path)
            return cues
        if time.monotonic() - _tv_caption_cache.get("resolved_at", 0.0) < _TV_CAPTION_RETRY_SECONDS:
            return []
        if _tv_caption_cache.get("pending_path") == path:
            return []
    elif _tv_caption_cache.get("pending_path") == path:
        return []
    else:
        prefetch = _tv_caption_prefetch
        if (_tv_caption_cache.get("channel") == ch and prefetch.get("channel") == ch
                and prefetch.get("path") == path and prefetch.get("session") is not None):
            _stop_tv_live_caption_session()
            promoted = prefetch["session"]
            promoted.attach_playback(_tv_playback_seconds, _tv_playback_seconds() or 0.0)
            _tv_caption_prefetch = {"path": None, "session": None, "channel": None}
            _tv_caption_cache = {"path": path, "cues": [], "pending_path": None,
                                  "resolved_at": time.monotonic(),
                                  "live_session": promoted, "channel": ch}
            return promoted.snapshot() if promoted.ready else []
        _stop_tv_live_caption_session()
        _stop_tv_caption_prefetch()

    _tv_caption_cache["pending_path"] = path

    def _resolve_job_impl():
        cues = []
        live_session = None
        _resolved_kind = [None]
        try:
            info = resolve_caption_source(path)
            _resolved_kind[0] = info.get("kind")
            if info.get("kind") == "baked":
                log.info("[TV CAPTIONS] %s has captions baked into the picture -- overlay off for this file",
                         os.path.basename(path))
            srt_path = info.get("srt_path")
            if info.get("kind") == "embedded" and not srt_path:
                out_path = os.path.join(
                    resolve_captions_dir(),
                    f"tv_{abs(hash(os.path.normpath(path).lower()))}.srt",
                )
                if _extract_embedded_subtitle_to_file(path, info["stream_index"], out_path):
                    srt_path = out_path
                    media.note_caption_source(path, "embedded", out_path)
            if srt_path:
                cues = parse_caption_cues(srt_path)
            elif info.get("kind") is None and info.get("mtime") is not None and not asr_known_unavailable():
                start_sec = 0.0
                try:
                    now_state = _get_probe_now_state(ch) if ch else {}
                    sched_file = now_state.get("file", "")
                    sched_seek = now_state.get("seek", 0) or 0
                    if (sched_file and sched_seek > 0
                            and os.path.normpath(sched_file).lower() == os.path.normpath(path).lower()):
                        start_sec = float(sched_seek)
                except Exception as _swallowed_error:
                    _log_swallowed("_caption_cues_for._resolve_job_impl: now_state = _get_probe_now_state(ch) if ch else {}", _swallowed_error)
                if start_sec <= 0.0:
                    try:
                        pos_sec = _tv_playback_seconds()
                        if pos_sec is not None and pos_sec > 0:
                            start_sec = pos_sec
                    except Exception as _swallowed_error:
                        _log_swallowed("_caption_cues_for._resolve_job_impl: pos_sec = _tv_playback_seconds()", _swallowed_error)
                live_session = LiveCaptionSession(
                    path, start_sec=start_sec, position_fn=_tv_playback_seconds).start()
        except Exception as e:
            log.warning("[TV CAPTIONS] cue resolve failed for %s: %s", path, e)
            cues = []
        global _tv_caption_cache
        if _tv_caption_cache.get("pending_path") == path:
            _tv_caption_cache = {"path": path, "cues": cues, "pending_path": None,
                                  "resolved_at": time.monotonic(),
                                  "live_session": live_session, "channel": ch,
                                  "kind": _resolved_kind[0]}
        elif live_session is not None:
            live_session.stop()
        if live_session is None:
            _maybe_unload_caption_model_after_show("next show has no live transcription")

    def _resolve_job():
        with _governor_priority_scope():
            _resolve_job_impl()

    threading.Thread(target=_resolve_job, daemon=True, name="TVCaptionResolve").start()
    return []


def _tv_playback_seconds():
    """Current playback position of the TV player in FILE seconds, or None if it can't be read."""
    try:
        vlc = globals().get("vlc_engine")
        if vlc is None or vlc.player is None:
            return None
        ms = vlc.player.get_time()
        if ms is None or ms < 0:
            return None
        return ms / 1000.0
    except Exception as _swallowed_error:
        _log_swallowed("_tv_playback_seconds: vlc = globals().get('vlc_engine')", _swallowed_error)
        return None


def _current_tv_caption_path():
    """The plain-file path currently loaded on vlc_engine, or None."""
    try:
        vlc = globals().get("vlc_engine")
        if vlc is None or vlc.player is None:
            return None
        media = vlc.player.get_media()
        if media is None:
            return None
        mrl = media.get_mrl()
        if not mrl or not mrl.startswith("file:///"):
            return None
        from urllib.parse import unquote
        return os.path.normpath(unquote(mrl.replace("file:///", "")))
    except Exception as _swallowed_error:
        _log_swallowed("_current_tv_caption_path: vlc = globals().get('vlc_engine')", _swallowed_error)
        return None


def _vis_card_font_that_fits(strs, base_size, max_w, min_size=8):
    """Largest Courier New bold size, down to min_size, at which every string in `strs` fits within max_w pixels."""
    size = max(min_size, base_size)
    while size > min_size:
        f = _cached_sys_font("Courier New", size, bold=True)
        if all(f.size(s)[0] <= max_w for s in strs):
            return f, size
        size -= 1
    return _cached_sys_font("Courier New", min_size, bold=True), min_size


def _vis_card_truncate_to_width(font, s, max_w):
    """Truncates a title with a trailing ellipsis so it fits the given width."""
    if font.size(s)[0] <= max_w:
        return s
    t = s
    while t and font.size(t + "...")[0] > max_w:
        t = t[:-1]
    return (t + "...") if t else s[:1]


def _clean_song_display_title(raw_title):
    """Thin wrapper over media.clean_music_display_title()."""
    return media.clean_music_display_title(raw_title)


def _visualizer_title_path(channel_key, fallback_path):
    """The file whose name is shown as the song title: the song the hub says is on air for this station right now, or the given path when the hub has no music answer."""
    try:
        _state = calculate_slotted_playback_state(str(channel_key).zfill(2))
        if isinstance(_state, dict) and _state.get("mode") == "Visualizer" and _state.get("file"):
            return _state["file"]
    except Exception as _e:
        _log_warn_throttled("viz_title_" + str(channel_key), "[VISUALIZER TITLE] ch%s: the hub could not name the song, the playing file's name is shown: %s", channel_key, _e)
    return fallback_path


def _title_y_on_screen(aligned_y, line_gap, last_line_height, screen_height):
    """The top of the song title's first line: the channel number's top when both lines fit on the screen from there, else moved up just far enough, never above the top edge."""
    _lowest = screen_height - (line_gap + last_line_height) - 2
    return int(max(0, min(aligned_y, _lowest)))


def _picture_row_of_window_row(window_y, geom):
    """The row of the picture (before the bezel scales it into its cutout) that lands on window row `window_y`."""
    src_rect, _scale_x, scale_y, _dest_x, dest_y, _draw_w, _draw_h = geom
    if scale_y <= 0:
        return window_y
    return src_rect.y + (window_y - dest_y) / scale_y


def _draw_visualizer_song_card(screen):
    """Draws the visualizer channel's song-name/style card."""
    # WARNING: the card keeps rendering and counting down its burn-in timeout while a menu covers it; never skip it.
    text = app_state.get("_vis_card_text")
    if not text:
        return

    if (app_state.get("show_splash", False)
            or app_state.get("show_quit_confirm", False)
            or app_state.get("show_restart_confirm", False)
            or app_state.get("file_explorer_active", False)):
        return

    line1, line2 = text

    sw, sh = screen.get_size()
    geom = _bezel_composite_geometry(sw, sh, ignore_package_aspect=_vis_ignores_package_aspect(sw, sh))
    if geom is not None:
        src_rect, scale_x, scale_y, _dest_x, _dest_y, _draw_w, _draw_h = geom
        picture_rect = src_rect
        _inv_scale_x = 1.0 / scale_x if scale_x > 0 else 1.0
        _inv_scale_y = 1.0 / scale_y if scale_y > 0 else 1.0
    else:
        picture_rect = pygame.Rect(0, 0, sw, sh)
        _inv_scale_x = 1.0
        _inv_scale_y = 1.0

    ref = max(1, picture_rect.height)
    line_gap = max(2, round(ref * 0.045))
    base_font_size = max(8, round(ref * 0.026))

    _MARGIN_X_PX = max(1, round(48 * _inv_scale_x))
    _MARGIN_Y_PX = max(1, round(64 * _inv_scale_y))

    import colorsys as _card_colorsys
    _hue = (db.config.get("theme_ui_hue", 140) / 360.0) if db is not None else (140 / 360.0)
    _hr, _hg, _hb = _card_colorsys.hsv_to_rgb(_hue, 0.9, 1.0)
    theme_green_color = (int(_hr * 255), int(_hg * 255), int(_hb * 255))

    max_text_width = max(10, picture_rect.width - _MARGIN_X_PX * 2)
    font, _fitted_size = _vis_card_font_that_fits((line1, line2), base_font_size, max_text_width)
    line1 = _vis_card_truncate_to_width(font, line1, max_text_width)
    line2 = _vis_card_truncate_to_width(font, line2, max_text_width)

    line1_y = picture_rect.y + _MARGIN_Y_PX
    line1_x = picture_rect.x + _MARGIN_X_PX

    _picture_right = picture_rect.x + picture_rect.width
    _surf1 = font.render(line1, True, theme_green_color)
    _surf2 = font.render(line2, True, theme_green_color)
    # WARNING: the title lines up with the channel number's top (the bezel LED readout or the on-picture number, whichever is drawn), which sits in a different place on each bezel; it is pulled up or down only as far as needed to keep both lines on the screen.
    _aligned_y = app_state.get("_ch_num_generic_osd_y")
    if isinstance(_aligned_y, (int, float)):
        if app_state.get("_ch_num_osd_in_window", False) and geom is not None:
            _aligned_y = _picture_row_of_window_row(_aligned_y, geom)
        _pic_top, _pic_bottom = (picture_rect.y, picture_rect.bottom) if geom is not None else (0, sh)
        _lowest = _pic_bottom - (line_gap + _surf2.get_height()) - 2
        line1_y = int(max(_pic_top, min(_aligned_y, _lowest)))
    line2_y = line1_y + line_gap
    _line1_x = min(line1_x, _picture_right - _surf1.get_width())
    _line2_x = min(line1_x, _picture_right - _surf2.get_width())
    screen.blit(_surf1, (_line1_x, line1_y))
    screen.blit(_surf2, (_line2_x, line2_y))


def _wrap_caption_to_two_lines(font, text, max_w):
    """Greedily word-wrap `text` into at most two lines that each fit max_w real pixels at `font`'s size."""
    words = text.split()
    if not words:
        return "", ""
    if font.size(text)[0] <= max_w:
        return text, ""
    line1_words = []
    i = 0
    while i < len(words):
        candidate = " ".join(line1_words + [words[i]])
        if not line1_words or font.size(candidate)[0] <= max_w:
            line1_words.append(words[i])
            i += 1
        else:
            break
    line1 = _vis_card_truncate_to_width(font, " ".join(line1_words), max_w)
    remaining = " ".join(words[i:])
    if not remaining:
        return line1, ""
    return line1, _vis_card_truncate_to_width(font, remaining, max_w)


_native_sub_state = {"path": None, "until_ms": 0, "next_ms": 0}
# WARNING: the fallback numbers below must match NATIVE_SUB_WATCH_MS, NATIVE_SUB_POLL_MS in performance_governor.py; they are used only when that module fails to import.
_NATIVE_SUB_WATCH_MS = performance_governor.NATIVE_SUB_WATCH_MS if performance_governor is not None else 20000
_NATIVE_SUB_POLL_MS = performance_governor.NATIVE_SUB_POLL_MS if performance_governor is not None else 400


def _suppress_native_subtitles(path, kind):
    """Switches VLC's own subtitle track off when the overlay owns the captions for this file or the picture already has them baked in, checking the player for a short window after each new file."""
    if not path or kind not in ("sidecar", "embedded", "cache", "baked"):
        return
    now = pygame.time.get_ticks()
    state = _native_sub_state
    if state["path"] != path:
        state["path"] = path
        state["until_ms"] = now + _NATIVE_SUB_WATCH_MS
        state["next_ms"] = 0
    if now > state["until_ms"] or now < state["next_ms"]:
        return
    state["next_ms"] = now + _NATIVE_SUB_POLL_MS
    try:
        vlc = globals().get("vlc_engine")
        if vlc is None or vlc.player is None:
            return
        if getattr(vlc, "is_dvd_iso", False):
            return
        spu = vlc.player.video_get_spu()
        if spu is not None and spu >= 0:
            vlc.player.video_set_spu(-1)
            log.info("[TV CAPTIONS] VLC's own subtitle track switched off for %s (%s)",
                     os.path.basename(path), kind)
    except Exception as e:
        log.warning("_suppress_native_subtitles failed (non-fatal): %s", e)


def _draw_caption_overlay(screen, content_rect=None):
    """Draws the current caption cue (if any) for TV-station / visualizer channels."""
    # WARNING: line 2 is hard-clamped so it never paints over the Water Mark badge.
    try:
        if db is None or not _setting_on("tv_captions_enabled"):
            _release_tv_caption_state_when_off()
            return
        ch = str(app_state.get("current_channel", "")).zfill(2)
        if ch in ("03", "04"):
            _release_tv_caption_state_when_off("guide / ch03 entered")
            return

        # WARNING: all three guards below are required, or a cue from the outgoing file can show over the transition or the new channel's loading fill.
        now_ticks = pygame.time.get_ticks()
        if (now_ticks < app_state.get("channel_switch_black_until", 0)
                or app_state.get("_pending_channel_activation") is not None
                or not app_state.get("_had_first_frame_this_tune", False)):
            return

        path = _current_tv_caption_path()
        cues = _caption_cues_for(path)
        _suppress_native_subtitles(path, _tv_caption_cache.get("kind") if _tv_caption_cache.get("path") == path else None)
        _finished_path = _caption_last_path["path"]
        if path != _finished_path:
            _caption_last_path["path"] = path
            if _finished_path:
                _maybe_unload_caption_model_after_show("show ended")
        if not cues:
            return

        vlc = globals().get("vlc_engine")
        if vlc is None or vlc.player is None:
            return
        now_ms = vlc.player.get_time()
        if now_ms is None or now_ms < 0:
            return

        active_text = None
        active_cue = None
        for start_ms, end_ms, text in cues:
            shown_until_ms = min(end_ms, start_ms + _CAPTION_MAX_HOLD_MS)
            if start_ms <= now_ms <= shown_until_ms:
                active_text = text
                active_cue = (start_ms, end_ms, text)
                break
            if start_ms > now_ms:
                break
        if active_cue is None:
            _caption_first_sight["key"] = None
        else:
            _first_key = (path, active_cue[0])
            if _caption_first_sight["key"] != _first_key:
                _caption_first_sight["key"] = _first_key
                _remain_ms = min(active_cue[1], active_cue[0] + _CAPTION_MAX_HOLD_MS) - now_ms
                _caption_first_sight["skip"] = _remain_ms < _CAPTION_MIN_FIRST_SHOW_MS
                if _caption_first_sight["skip"]:
                    log.info("[CAPTION] cue not shown: first ready with %d ms left (minimum %d ms): %r",
                             _remain_ms, _CAPTION_MIN_FIRST_SHOW_MS, active_text)
            if _caption_first_sight["skip"]:
                active_text = None
                active_cue = None
        if not active_text:
            return

        # WARNING: do not use the decoded picture's aspect-fit rect for captions; it moves when the aspect ratio changes.
        if content_rect is None:
            sw, sh = screen.get_size()
            content_rect = _compute_content_rect(sw, sh)
        caption_rect = content_rect
        _cap_side_gap = max(2, round(caption_rect.width * 0.02))
        if caption_rect.width > _cap_side_gap * 2:
            caption_rect = caption_rect.inflate(-_cap_side_gap * 2, 0)

        ref = max(1, caption_rect.height)
        font_size = max(10, round(ref * (38.0 / 720.0)))
        pad_x = max(2, round(ref * (14.0 / 720.0)))
        pad_y = max(1, round(ref * (6.0 / 720.0)))

        _wm_margin_y = max(6, round(ref * _WATERMARK_MARGIN_FRAC))
        _wm_extra_y = 0.0
        _wm_stem = _active_bezel_stem_if_on()
        if _wm_stem is not None:
            _wm_extra_y = _WATERMARK_BEZEL_EXTRA_OFFSET.get(_wm_stem, (0, 0))[1]
        margin = max(2, round((_wm_margin_y + _wm_extra_y) / 2.0))

        font = _cached_sys_font("Arial", font_size, bold=True)
        max_text_width = max(10, round(caption_rect.width * 0.8) - pad_x * 2)
        one_line = " ".join(active_text.split())
        line1_text, line2_text = _wrap_caption_to_two_lines(font, one_line, max_text_width)
        if not line1_text:
            return

        color = _tv_caption_color_rgb()
        surf1 = font.render(line1_text, True, color)
        surf2 = font.render(line2_text, True, color) if line2_text else None

        line1_y = caption_rect.bottom - surf1.get_height() - pad_y - margin
        line_gap = max(1, round(pad_y / 2))

        _wm_enabled = db is not None and db.channels_db.get(str(app_state.get("current_channel", "")).zfill(2), {}).get("watermark_enabled", False)
        _wm_raw = _watermark_cache.get("raw")
        if _wm_enabled and _wm_raw not in (None, False):
            _wm_target_w = max(24, round(caption_rect.width * _WATERMARK_WIDTH_FRAC))
            _wm_raw_w, _wm_raw_h = _wm_raw.get_size()
            _wm_target_h = (max(1, round(_wm_raw_h * (_wm_target_w / _wm_raw_w)))
                             if _wm_raw_w > 0 else 0)
            line2_bottom_limit = (caption_rect.bottom - (_wm_margin_y + _wm_extra_y)
                                   - _wm_target_h - pad_y)
        else:
            line2_bottom_limit = caption_rect.bottom - pad_y
        # WARNING: badge avoidance must never raise line 2's limit above line 1's own box; line 1 always draws.
        line2_bottom_limit = max(line2_bottom_limit, line1_y + surf1.get_height() + pad_y)

        # WARNING: line 1 never moves.
        if surf2 is not None:
            _room_below = (caption_rect.bottom - 1) - (line1_y + surf1.get_height())
            if _room_below < surf2.get_height() + line_gap:
                line_gap = max(0, _room_below - surf2.get_height())

        _outline_px = max(1, round(ref * (2.0 / 720.0)))
        _outline_color = (0, 0, 0)

        def _blit_outlined(surf_color, text, x, y):
            outline_surf = font.render(text, True, _outline_color)
            for _dx in range(-_outline_px, _outline_px + 1):
                for _dy in range(-_outline_px, _outline_px + 1):
                    if _dx == 0 and _dy == 0:
                        continue
                    screen.blit(outline_surf, (x + _dx, y + _dy))
            screen.blit(surf_color, (x, y))

        line_widths = [surf1.get_width()] + ([surf2.get_width()] if surf2 is not None else [])
        _block_w = max(line_widths)
        block_x = caption_rect.x + (caption_rect.width - _block_w) // 2

        if surf2 is None:
            _blit_outlined(surf1, line1_text, block_x + (_block_w - surf1.get_width()) // 2, line1_y)
        else:
            line2_y = line1_y + surf1.get_height() + line_gap
            _blit_outlined(surf1, line1_text, block_x + (_block_w - surf1.get_width()) // 2, line1_y)
            _blit_outlined(surf2, line2_text, block_x + (_block_w - surf2.get_width()) // 2, line2_y)
    except Exception as e:
        log.warning("_draw_caption_overlay: draw failed: %s", e)


_channel_playback_failures = {}

_playback_attempt_ids = itertools.count(1)

_PLAYBACK_PENDING = object()
# WARNING: returned by play_file_segmented for a load the viewer has already left; it is not a failure, so nothing is marked broken and no Static is shown for it.
_PLAYBACK_STALE = object()

_last_attempt_reason = {}

_visualizer_confirmed_dead_drive = {}

_station_confirmed_dead_drive = {}

_watchdog_consecutive_errors = {}
# WARNING: the fallback numbers below must match WATCHDOG_ERROR_BAIL_AFTER in performance_governor.py; they are used only when that module fails to import.
_WATCHDOG_ERROR_BAIL_AFTER = performance_governor.WATCHDOG_ERROR_BAIL_AFTER if performance_governor is not None else 2

_watchdog_consecutive_spurious_resumes = {}
# WARNING: the fallback numbers below must match WATCHDOG_SPURIOUS_RESUME_BAIL_AFTER, WATCHDOG_SPURIOUS_RESUME_WINDOW_MS in performance_governor.py; they are used only when that module fails to import.
_WATCHDOG_SPURIOUS_RESUME_BAIL_AFTER = performance_governor.WATCHDOG_SPURIOUS_RESUME_BAIL_AFTER if performance_governor is not None else 3
_WATCHDOG_SPURIOUS_RESUME_WINDOW_MS = performance_governor.WATCHDOG_SPURIOUS_RESUME_WINDOW_MS if performance_governor is not None else 20000

_drive_ever_confirmed_unresponsive = set()

_dead_drive_probe_file = {}


# ============================================================================
# SECTION: Dead-drive tracking & channel playback failures
# ============================================================================


def _remember_dead_drive_probe_file(root, file_path):
    """Record `file_path` as the file to real-read-probe for `root`'s recovery."""
    if root and file_path:
        _dead_drive_probe_file[root] = file_path


def _drive_confirmed_recovered(root):
    """True once `root` is confirmed recovered, by the root check or by reading real bytes back from the file that failed."""
    if root is None:
        return False
    _now_bad = set(_unresponsive_drive_roots())
    _drive_ever_confirmed_unresponsive.update(_now_bad)
    if root in _drive_ever_confirmed_unresponsive and root not in _now_bad:
        _dead_drive_probe_file.pop(root, None)
        return True
    _probe_file = _dead_drive_probe_file.get(root)
    if _probe_file and media.probe_file_level_recovery(root, _probe_file) is True:
        log.info(
            "[DRIVE HEALTH] %s confirmed recovered via file-level probe of "
            "%s (root-level check never flagged this drive -- this is the "
            "fast-rejection failure mode)", root, _probe_file,
        )
        _dead_drive_probe_file.pop(root, None)
        return True
    return False


_last_dead_drive_sweep_ticks = 0
# WARNING: the fallback numbers below must match DEAD_DRIVE_SWEEP_INTERVAL_MS in performance_governor.py; they are used only when that module fails to import.
_DEAD_DRIVE_SWEEP_INTERVAL_MS = performance_governor.DEAD_DRIVE_SWEEP_INTERVAL_MS if performance_governor is not None else 2000


def _sweep_all_recovered_dead_drives():
    """Clears every channel's dead-drive latch whose drive has recovered, whether or not that channel is on screen."""
    global _last_dead_drive_sweep_ticks
    _now = pygame.time.get_ticks()
    if _now - _last_dead_drive_sweep_ticks < _DEAD_DRIVE_SWEEP_INTERVAL_MS:
        return
    _last_dead_drive_sweep_ticks = _now

    for _ch_key, _root in list(_station_confirmed_dead_drive.items()):
        if _drive_confirmed_recovered(_root):
            _station_confirmed_dead_drive.pop(_ch_key, None)
            _clear_broken_files_for_root(_root)
            log.info("[DRIVE HEALTH] ch%s: %s confirmed recovered by background "
                      "sweep, cleared without waiting for a visit to this channel", _ch_key, _root)

    for _ch_key, _root in list(_visualizer_confirmed_dead_drive.items()):
        if _drive_confirmed_recovered(_root):
            _visualizer_confirmed_dead_drive.pop(_ch_key, None)
            log.info("[DRIVE HEALTH] ch%s (visualizer): %s confirmed recovered by "
                      "background sweep, cleared without waiting for a visit to this channel", _ch_key, _root)

    _gd = globals().get("game_deck")
    if _gd is not None:
        try:
            for _root, _failed_path in _gd.drive_launch_failures().items():
                _remember_dead_drive_probe_file(_root, _failed_path)
                if _drive_confirmed_recovered(_root):
                    _gd.clear_drive_launch_failure(_root)
                    log.info("[DRIVE HEALTH] ch03: %s confirmed recovered by background sweep, "
                              "game and DVD launch failure cleared", _root)
        except Exception as _e:
            log.warning("[DRIVE HEALTH] _sweep_all_recovered_dead_drives: game launch failure check failed: %s", _e)


