def _start_guide_preview_load(hl_ch, hl_state):
    """Starts a guide-preview VLC load of hl_ch/hl_state's file, or registers the failure for a confirmed-dead channel."""
    _gp_dead_root = _station_confirmed_dead_drive.get(hl_ch)
    if _gp_dead_root is not None and _drive_confirmed_recovered(_gp_dead_root):
        _station_confirmed_dead_drive.pop(hl_ch, None)
        _clear_broken_files_for_root(_gp_dead_root)
        _gp_dead_root = None
    if _gp_dead_root is not None:
        app_state["loaded_preview_path_cache"] = hl_state["file"]
        app_state["guide_preview_loading"] = False
        _register_channel_playback_failure(
            hl_ch, hl_state["file"],
            duration=hl_state.get("duration"), block=hl_state.get("block"),
        )
        return
    try:
        vlc_engine.player.audio_set_mute(True)
    except Exception as _swallowed_error:
        _log_swallowed("_start_guide_preview_load: vlc_engine.player.audio_set_mute(True)", _swallowed_error)
    app_state["_video_pending_unmute"] = True
    vlc_engine.stop()
    # WARNING: do not add a fixed startup pad to the seek; buffering time varies, so it would make every guide preview seek inaccurate (the real VLC position is read when the start is confirmed).
    _gp_on_confirmed = _make_live_playback_start_callback(
        hl_ch, hl_state, "guide_preview_open_failed"
    )

    app_state["last_video_play_started_at"] = pygame.time.get_ticks()
    _gp_file, _gp_seek = hl_state["file"], hl_state["seek"]
    _gp_gain = _lookup_file_gain(hl_ch, _gp_file)

    def _gp_open():
        vlc_engine.play_file_segmented(
            _gp_file,
            _gp_seek,
            gain=_gp_gain,
            defer_unmute=True,
            on_confirmed=_gp_on_confirmed,
            follow_clock=True,
        )

    # WARNING: owner 2026-11-03: the picture box is scanned first and then the preview opens, never on the screen thread; the open runs on the same worker as a channel change, so the guide keeps drawing and taking keys while a scan runs (owner log: the guide froze 5.6 s in the pre-show scan).
    _dispatch_content_activation(_gp_open)
    _mute_guard_log("ARM (guide preview load)", ch=hl_ch, filepath=hl_state["file"])
    app_state["loaded_preview_path_cache"] = hl_state["file"]
    app_state["guide_preview_loading"] = True
    app_state["guide_preview_load_started_ms"] = pygame.time.get_ticks()


def _arm_warm_transition_shield(engine, burst_ms):
    """Covers a guide warm-continuation switch (ch05 <-> the guide previewing ch05) with the configured Transition Type, without touching playback."""
    try:
        engine.player.audio_set_mute(True)
    except Exception as _swallowed_error:
        _log_swallowed("_arm_warm_transition_shield: engine.player.audio_set_mute(True)", _swallowed_error)

    def _do_unmute():
        time.sleep(max(0, burst_ms - 1) / 1000.0)
        try:
            engine.player.audio_set_mute(False)
        except Exception as _swallowed_error:
            _log_swallowed("_arm_warm_transition_shield._do_unmute: engine.player.audio_set_mute(False)", _swallowed_error)

    import threading as _t
    _t.Thread(target=_do_unmute, daemon=True).start()


def _arm_guide_preview_transition():
    _transition_style = _configured_transition_style()
    if _transition_style == "static":
        app_state["guide_preview_black_until"] = 0
        app_state["guide_preview_static_until"] = pygame.time.get_ticks() + STATIC_TRANSITION_MS
    else:
        app_state["guide_preview_static_until"] = 0
        app_state["guide_preview_black_until"] = pygame.time.get_ticks() + GUIDE_PREVIEW_SETTLE_MS
    app_state["guide_preview_settle_until"] = pygame.time.get_ticks() + GUIDE_PREVIEW_SETTLE_MS

    app_state["loaded_preview_path_cache"] = ""
    app_state["guide_preview_loading"] = False
    app_state["guide_preview_load_started_ms"] = 0

    if pygame.mixer.music.get_busy():
        pygame.mixer.music.stop()
    app_state["music_owner"] = ""
    app_state["guide_preview_music_track"] = ""

    if vlc_engine is not None and getattr(vlc_engine, "player", None) is not None:
        try:
            vlc_engine.player.audio_set_mute(True)
        except Exception as _swallowed_error:
            _log_swallowed("_arm_guide_preview_transition: vlc_engine.player.audio_set_mute(True)", _swallowed_error)
    app_state["_video_pending_unmute"] = True
    _governor_note_event("guide_row_switch")
    _mute_guard_log("ARM (guide row switch)", ch=app_state.get("highlighted_guide_channel"))


def _capture_guide_preview_position(ch_key):
    """Save the exact position of the preview before surfing to another row."""
    ch_key = str(ch_key).zfill(2)
    if ch_key != str(app_state.get("_live_playback_channel", "")).zfill(2):
        return
    if vlc_engine is None or getattr(vlc_engine, "player", None) is None:
        return
    try:
        current_ms = vlc_engine.player.get_time()
        current_media = vlc_engine.player.get_media()
        current_mrl = current_media.get_mrl() if current_media else ""
        if current_ms is None or current_ms < 0 or not current_mrl:
            return
        from urllib.parse import unquote as _unquote_preview
        current_file = os.path.normpath(
            _unquote_preview(current_mrl.replace("file:///", "")))
        # WARNING: only save a position when the engine is playing the file this channel was last confirmed on; during a deferred open the engine already holds the next channel's file.
        _confirmed_anchor = (db.channels_db.get(ch_key, {}).get("playback_anchor") or {}) if db is not None else {}
        _confirmed_file = _confirmed_anchor.get("file") if isinstance(_confirmed_anchor, dict) else None
        if (not _confirmed_file
                or os.path.normcase(os.path.normpath(str(_confirmed_file))) != os.path.normcase(current_file)
                or not _file_in_channel_schedule(ch_key, _confirmed_file)):
            return
        now_ticks = pygame.time.get_ticks()
        preview_cache = app_state.setdefault("_guide_preview_position_cache", {})
        preview_cache[ch_key] = {
            "file": current_file,
            "seek": current_ms / 1000.0,
            "duration": max(1.0, (vlc_engine.player.get_length() or 0) / 1000.0),
            "captured_ticks": now_ticks,
        }
    except Exception as _preview_snapshot_err:
        log.debug("guide preview position snapshot unavailable: %s", _preview_snapshot_err)


def _get_guide_hl_playback_state(ch_key, slot="hl"):
    """Return the scheduled playback state for a guide channel."""
    return calculate_slotted_playback_state(str(ch_key).zfill(2))


_visualizer_track_analyzer = None
_visualizer_track_analyzer_lock = threading.Lock()


def _get_visualizer_track_analyzer():
    """The one shared visualizer song analyzer, created on first use."""
    global _visualizer_track_analyzer
    if _visualizer_track_analyzer is None:
        from assets import audio_analysis
        with _visualizer_track_analyzer_lock:
            if _visualizer_track_analyzer is None:
                _visualizer_track_analyzer = audio_analysis.TrackAnalyzer(
                    media._resolve_ffmpeg_path, resolve_main_dir, log=log)
    return _visualizer_track_analyzer


def _visualizer_analysis_prefetch():
    """Keeps the next songs of every reactive visualizer channel analyzed ahead in Standard and Performance: the first 3 with no pause, the rest up to 10 songs ahead at the fast scan pace, refilled once fewer than 5 of the next songs are analyzed."""
    if db is None or performance_governor is None:
        return
    if performance_governor.get_mode() not in ("standard", "performance"):
        return
    analyzer = None
    items = []
    window = int(performance_governor.MUSIC_SCAN_FAST_AHEAD_SONGS)
    for i in range(5, 45):
        ch_str = str(i).zfill(2)
        ch_info = db.channels_db.get(ch_str, {})
        if (not ch_info or not ch_info.get("active", True) or not ch_info.get("is_visualizer", False)
                or ch_info.get("server_locked", False) or not ch_info.get("reactive_visualizer_enabled", True)):
            continue
        _snap_rec = _scan_snapshot_channel(ch_str)
        if _snap_rec is None or not _snap_rec["ordered"]:
            continue
        songs = []
        for entry in _next_n_from_ordered(_snap_rec["ordered"], _snap_rec["current_file"], n=window + 1)[1:]:
            for p in _paths_from_entry(entry):
                if p and _cached_path_exists(p):
                    songs.append(os.path.normpath(p))
        if not songs:
            continue
        if analyzer is None:
            analyzer = _get_visualizer_track_analyzer()
        ahead = 0
        for p in songs:
            if not analyzer.is_analyzed(p):
                break
            ahead += 1
        _key = "analysis ch" + ch_str
        behind = performance_governor.music_scan_falling_behind(_music_scan_behind.get(_key, True), ahead)
        if behind != _music_scan_behind.get(_key):
            log.info("[VISUALIZER ANALYSIS] ch%s: %d next songs analyzed, %s", ch_str, ahead,
                     "analyzing ahead" if behind else "far enough ahead")
            _music_scan_behind[_key] = behind
        if not behind:
            continue
        for distance, p in enumerate(songs, start=1):
            if analyzer.is_analyzed(p):
                continue
            items.append((distance, p))
    if analyzer is None:
        return
    items.sort(key=lambda it: it[0])
    analyzer.analyze_ahead([
        (p, _scan_class_pace_seconds(performance_governor.music_analysis_class(distance, True), MUSIC_PRECACHE_BETWEEN_TRACKS_SECONDS))
        for distance, p in items])


def _visualizer_reactive_frame(track_file):
    """Returns the real-music numbers for the song the mixer is playing right now, or None to keep the Lite fake motion (Lite mode, song not analyzed yet, or no usable position)."""
    try:
        mode = performance_governor.get_mode() if performance_governor is not None else "lite"
        if mode not in ("standard", "performance") or not track_file or db is None:
            return None
        if os.path.normpath(str(track_file)) != app_state.get("_vis_react_track"):
            return None
        mixer_ms = pygame.mixer.music.get_pos()
        if mixer_ms < 0 or not pygame.mixer.music.get_busy():
            return None
        from assets import audio_analysis
        analysis = _get_visualizer_track_analyzer().get(app_state["_vis_react_track"])
        position = app_state.get("_vis_react_seek", 0.0) + mixer_ms / 1000.0
        reactive = audio_analysis.reactive_frame(
            analysis, position, app_state.setdefault("_vis_react_state", {}), mode == "performance")
        ch_key = str(app_state.get("current_channel", "")).zfill(2)
        ch_info = db.channels_db.get(ch_key, {}) if db is not None else {}
        if not ch_info.get("reactive_visualizer_enabled", True):
            return None
        strength = max(0.0, min(1.0, int(ch_info.get("reactive_visualizer_strength", 50)) / 100.0))
        if strength < 1.0 and reactive:
            reactive = dict(reactive)
            reactive["level"] *= strength
            reactive["bands"] = [value * strength for value in reactive.get("bands", [])]
            reactive["spectrum"] = [value * strength for value in reactive.get("spectrum", [])] if reactive.get("spectrum") else None
            reactive["beat"] *= strength
        return reactive
    except Exception as _react_err:
        log.debug("visualizer reactive frame unavailable: %s", _react_err)
        return None


def _render_visualizer_frame(surface, theme, amplitude, style_override=None, reactive=None):
    """Draw one visualizer frame through the shared deck path."""
    visualizer_deck.render_active_engine(
        surface,
        theme,
        mock_amplitude=amplitude,
        style_override=style_override,
        reactive=reactive,
    )


