HWND_TOPMOST    = -1
HWND_NOTOPMOST  = -2
SWP_NOMOVE      = 0x0002
SWP_NOSIZE      = 0x0001
SWP_SHOWWINDOW  = 0x0040
SW_RESTORE      = 9
_WINDOW_COMMAND_EVENT = pygame.USEREVENT + 17


