def _fe_add_selected_to_queue():
    items      = app_state.get("file_explorer_items", [])
    sel        = app_state.get("file_explorer_selection", set())
    context    = app_state.get("file_explorer_context", {})
    valid_exts = app_state.get("file_explorer_exts", set())
    if context.get("mode", "") in _FE_SINGLE_PICK_MODES:
        checked = []
        app_state["file_explorer_checked"] = checked
    else:
        checked = app_state.setdefault("file_explorer_checked", [])
    checked_set = set(checked)
    dirs_to_expand = []
    for idx in sorted(sel):
        if not (0 <= idx < len(items)):
            continue
        item = items[idx]
        p    = item["path"]
        if item["type"] == "dir":
            dirs_to_expand.append(p)
        elif item["type"] == "file":
            fp = os.path.normpath(p)
            if fp not in checked_set:
                checked_set.add(fp)
                checked.append(fp)
    app_state["file_explorer_selection"] = set()
    if dirs_to_expand:
        app_state["file_explorer_expand_request_id"] += 1
        req_id = app_state["file_explorer_expand_request_id"]
        session_id = app_state.get("file_explorer_session_id", 0)
        if app_state.get("file_explorer_expand_pending", 0) == 0:
            app_state["file_explorer_expand_started_ms"] = pygame.time.get_ticks()
            app_state["file_explorer_expand_progress"] = (0, time.monotonic())
        app_state["file_explorer_expand_pending"] += 1
        threading.Thread(
            target=_fe_expand_worker,
            args=(req_id, "add", dirs_to_expand, valid_exts, session_id),
            daemon=True,
        ).start()


def _fe_add_selected_rom_folder():
    items   = app_state.get("file_explorer_items", [])
    sel     = app_state.get("file_explorer_selection", set())
    context = app_state.get("file_explorer_context", {})
    ck      = context.get("console_key", "")

    picked_dir = None
    for idx in sorted(sel):
        if 0 <= idx < len(items) and items[idx]["type"] == "dir":
            picked_dir = items[idx]["path"]
            break
    if not picked_dir:
        return

    from game_deck import ROM_EXTENSIONS
    exts = set(ROM_EXTENSIONS.get(ck, []))
    n_found = 0
    try:
        if _is_drive_responsive(picked_dir):
            with os.scandir(picked_dir) as it:
                for entry in it:
                    if entry.is_file() and os.path.splitext(entry.name.lower())[1] in exts:
                        n_found += 1
    except Exception as _se:
        log.warning(f"[GAMES] Could not count ROMs in {picked_dir}: {_se}")

    context["picked_rom_folder"] = picked_dir
    context["picked_rom_count"]  = n_found
    app_state["file_explorer_checked"]   = [""] * n_found
    app_state["file_explorer_selection"] = set()
    print(f"[GAMES] {ck}: {n_found} ROM(s) found in {picked_dir}")


def _fe_add_selected_scan_folder():
    """"Scan For Roms" folder pick: marks the picked folder and gives a cheap depth-1 preview of matching console subfolders."""
    items   = app_state.get("file_explorer_items", [])
    sel     = app_state.get("file_explorer_selection", set())
    context = app_state.get("file_explorer_context", {})

    picked_dir = None
    for idx in sorted(sel):
        if 0 <= idx < len(items) and items[idx]["type"] == "dir":
            picked_dir = items[idx]["path"]
            break
    if not picked_dir:
        return

    from game_deck import match_console_for_folder_name
    n_matched = 0
    try:
        if _is_drive_responsive(picked_dir):
            base_name = os.path.basename(picked_dir.rstrip("\\/"))
            if match_console_for_folder_name(base_name):
                n_matched = 1
            else:
                with os.scandir(picked_dir) as it:
                    for entry in it:
                        if entry.is_dir() and match_console_for_folder_name(entry.name):
                            n_matched += 1
    except Exception as _se:
        log.warning(f"[GAMES] Could not preview {picked_dir}: {_se}")

    context["picked_rom_folder"] = picked_dir
    context["picked_rom_count"]  = n_matched
    app_state["file_explorer_checked"]   = ["x"]
    app_state["file_explorer_selection"] = set()
    print(f"[GAMES] Scan For Roms: {picked_dir} selected "
          f"({n_matched} console-named folder(s) matched at top level)")


def _fe_add_selected_scan_cores_folder():
    """"Scan For Cores" folder pick: cheap depth-2 preview of *_libretro.dll files in the picked folder or one level down."""
    items   = app_state.get("file_explorer_items", [])
    sel     = app_state.get("file_explorer_selection", set())
    context = app_state.get("file_explorer_context", {})

    picked_dir = None
    for idx in sorted(sel):
        if 0 <= idx < len(items) and items[idx]["type"] == "dir":
            picked_dir = items[idx]["path"]
            break
    if not picked_dir:
        return

    n_matched = 0
    try:
        if _is_drive_responsive(picked_dir):
            with os.scandir(picked_dir) as it:
                for entry in it:
                    if entry.is_file() and entry.name.lower().endswith("_libretro.dll"):
                        n_matched += 1
                    elif entry.is_dir() and not entry.name.startswith((".", "$")):
                        try:
                            with os.scandir(entry.path) as it2:
                                for entry2 in it2:
                                    if entry2.is_file() and entry2.name.lower().endswith("_libretro.dll"):
                                        n_matched += 1
                        except Exception as _swallowed_error:
                            _log_swallowed("_fe_add_selected_scan_cores_folder: with os.scandir(entry.path) as it2:", _swallowed_error)
    except Exception as _se:
        log.warning(f"[GAMES] Could not preview {picked_dir}: {_se}")

    context["picked_rom_folder"] = picked_dir
    context["picked_rom_count"]  = n_matched
    app_state["file_explorer_checked"]   = ["x"]
    app_state["file_explorer_selection"] = set()
    print(f"[GAMES] Scan For Cores: {picked_dir} selected "
          f"({n_matched} core .dll(s) found within 2 levels)")


def _fe_expand_worker(req_id, op, dir_paths, valid_exts, session_id=0):
    ignored_dirs = {
        "sample", "samples", "extras", "extra", "bonus", "featurettes",
        "behind the scenes", "trailers", "trailer", "subs", "subtitles",
        "loudness",
    }
    found = []
    seen = set()
    _walk_t0 = time.monotonic()
    app_state["file_explorer_expand_progress"] = (0, _walk_t0)
    _folders = [0]

    def _folder_seen(dir_path):
        _folders[0] += 1
        app_state["file_explorer_expand_progress"] = (len(found), time.monotonic())
        return _is_drive_responsive(dir_path)

    for p in dir_paths:
        if not _is_drive_responsive(p):
            continue
        for fp in media.iter_files_resolving_shortcuts(
                p, ignored_dir_names=ignored_dirs, valid_exts=valid_exts,
                is_drive_responsive=_folder_seen):
            fp = os.path.normpath(fp)
            if fp not in seen:
                seen.add(fp)
                found.append(fp)
                app_state["file_explorer_expand_progress"] = (len(found), time.monotonic())
    media.note_paths_present(found)
    log.info("[FILE EXPLORER] folder walk (%s): %d file(s) in %d folder(s) from %d picked folder(s) in %.1fs",
             op, len(found), _folders[0], len(dir_paths), time.monotonic() - _walk_t0)
    with app_state["file_explorer_expand_lock"]:
        app_state["file_explorer_expand_result"] = (op, found, session_id)


# ============================================================================
# SECTION: Library facts & part-group gains
# ============================================================================


def _get_part_group_key(norm_path):
    if not norm_path:
        return None
    info = _movie_part_info({"path": norm_path})
    if info is None:
        return None
    base, _num = info
    return f"{os.path.dirname(norm_path).lower()}::{base}"


def _read_part_group_gain(group_key):
    """The saved gain of a multi-part title as a dict (anchor_path, gain and the settings it was measured under), or None when the library has none or it was measured under other settings."""
    hub = _get_gain_hub()
    if hub is None or not group_key:
        return None
    record = hub.read_group(group_key)
    if record and _library_gain_is_current(record):
        return record
    return None


def _set_part_group_anchor_gain(group_key, norm_path, gain):
    """Saves the gain of a multi-part title's first scanned part in the library with the settings it was measured under, so its other parts reuse it; a failure to save is logged."""
    if not group_key or gain is None:
        return
    hub = _get_gain_hub()
    _is_music = os.path.splitext(str(norm_path))[1].lower() in _MUSIC_FILE_EXTS
    if hub is None or not hub.note_group(group_key, norm_path, gain,
                                         target_lufs=media.MUSIC_TARGET_LUFS if _is_music else media.TARGET_LUFS,
                                         scan_version=media.LOUDNESS_GAIN_SCAN_VERSION,
                                         convergence_db=media.LOUDNESS_CONVERGENCE_DB):
        log.warning("[GAIN HUB] the multi-part title gain from '%s' was not saved because the library could not hold it, so its other parts are measured on their own", os.path.basename(str(norm_path)))


_gain_hub_singleton = None
_gain_hub_failed = False
_gain_hub_lock = threading.Lock()


def _get_gain_hub():
    """Returns the shared gain reader on the persistent library, or None when the library cannot be opened (logged once)."""
    global _gain_hub_singleton, _gain_hub_failed
    if _gain_hub_singleton is not None or _gain_hub_failed:
        return _gain_hub_singleton
    with _gain_hub_lock:
        if _gain_hub_singleton is None and not _gain_hub_failed:
            try:
                import media_library as _ml
                _gain_hub_singleton = _ml.shared_gain_hub()
            except Exception as _hub_error:
                _gain_hub_failed = True
                log.warning("[GAIN HUB] the library gain reader could not start, gains are not read from the library: %s", _hub_error)
    return _gain_hub_singleton


def _library_gain_is_current(record):
    """True when a stored scan was measured under today's loudness targets, convergence and scan version; a stamp an older version never wrote counts as current, and the owner's own gain always counts."""
    version = record.get("scan_version")
    if version == media.OWNER_GAIN_SCAN_VERSION:
        return True
    if version is not None and version != media.LOUDNESS_GAIN_SCAN_VERSION:
        return False
    target = record.get("target_lufs")
    if target is not None and not any(abs(float(target) - float(t)) < 1e-9 for t in (media.TARGET_LUFS, media.MUSIC_TARGET_LUFS)):
        return False
    convergence = record.get("convergence_db")
    if convergence is not None and abs(float(convergence) - float(media.LOUDNESS_CONVERGENCE_DB)) >= 1e-9:
        return False
    return True


def _get_library_gain(norm_path):
    """The scanned gain the library holds for a file, or None when it has none or it was measured under other settings."""
    hub = _get_gain_hub()
    if hub is None or not norm_path:
        return None
    try:
        record = hub.read(norm_path)
    except Exception as _swallowed_error:
        _log_swallowed("_get_library_gain: reading the file's gain from the library", _swallowed_error)
        return None
    if record["gain"] and _library_gain_is_current(record):
        return record["gain"]
    return None


def _store_loudness_gain(norm_path, gain):
    """Saves a measured gain in the library with the settings it was measured under. Returns False when the library cannot hold it, and the caller logs a line."""
    hub = _get_gain_hub()
    if hub is None:
        return False
    _is_music = os.path.splitext(str(norm_path))[1].lower() in _MUSIC_FILE_EXTS
    stored = bool(hub.note_gain(norm_path, gain,
                                target_lufs=media.MUSIC_TARGET_LUFS if _is_music else media.TARGET_LUFS,
                                scan_version=media.LOUDNESS_GAIN_SCAN_VERSION,
                                convergence_db=media.LOUDNESS_CONVERGENCE_DB,
                                checked=_take_gain_double_checked(norm_path),
                                windows=_take_gain_windows(norm_path)))
    if db is not None:
        learned_offset = _take_learned_offset_applied(norm_path)
        if stored:
            owner_row = True
            try:
                owner_row = hub.read(norm_path)["scan_version"] == media.OWNER_GAIN_SCAN_VERSION
            except Exception as _swallowed_error:
                _log_swallowed("_store_loudness_gain: reading the saved row", _swallowed_error)
            if not owner_row:
                _learning_write(os.path.normpath(norm_path), learn_applied_db=float(learned_offset) if learned_offset else None)
    return stored


def _library_gain_first(ch_key):
    """True when the library's scanned gain outranks a schedule entry's gain; a channel streamed from a connected Server keeps its own entry gains first."""
    return ch_key is None or not _channel_is_server_streamed(ch_key)


def _get_library_dims(norm_path):
    """The picture size (width, height) the library holds for a file, or None when it has none."""
    hub = _get_gain_hub()
    if hub is None or not norm_path:
        return None
    try:
        return hub.read_dims(norm_path)
    except Exception as _swallowed_error:
        _log_swallowed("_get_library_dims: reading the file's picture size from the library", _swallowed_error)
        return None


def _read_file_probe_facts(norm_path):
    """What the library holds for one file as a dict with only the fields on record: duration (measured length), gain (scanned gain measured under today's settings) and dims (picture size)."""
    facts = {}
    if not norm_path:
        return facts
    duration_hub = media.get_duration_hub()
    if duration_hub is not None:
        try:
            seconds, kind = duration_hub.read(norm_path)
            if kind == media.DURATION_MEASURED and seconds:
                facts["duration"] = seconds
        except Exception as _swallowed_error:
            _log_swallowed("_read_file_probe_facts: reading the file's length from the library", _swallowed_error)
    gain = _get_library_gain(norm_path)
    if gain is not None:
        facts["gain"] = gain
    dims = _get_library_dims(norm_path)
    if dims is not None:
        facts["dims"] = list(dims)
    return facts


def _save_file_probe_facts(norm_path, duration=None, gain=None, dims=None):
    """Saves a measured length, scanned gain and picture size in the library; a value the library cannot key (a file that is gone or still being copied) is not kept and a line in the log says so."""
    if not norm_path:
        return
    name = os.path.basename(str(norm_path))
    if duration and duration > 0:
        if not _hub_note_measured_duration(norm_path, duration):
            log.warning("[LIBRARY] the library could not save the measured length of %s", name)
    if gain:
        if not _store_loudness_gain(norm_path, gain):
            log.warning("[LIBRARY] the library could not save the scanned gain of %s", name)
    if dims and len(dims) == 2 and dims[0] and dims[1]:
        _dims_hub = _get_gain_hub()
        if _dims_hub is None or not _dims_hub.note_dims(norm_path, dims[0], dims[1]):
            log.warning("[LIBRARY] the library could not save the picture size of %s", name)


# ============================================================================
# SECTION: Changed-file sweep
# ============================================================================

# WARNING: the fallback numbers below must match CHANGED_FILE_SWEEP_INTERVAL_S in performance_governor.py; they are used only when that module fails to import.
_CHANGED_FILE_SWEEP_INTERVAL_S = performance_governor.CHANGED_FILE_SWEEP_INTERVAL_S if performance_governor is not None else 1800


def _forget_changed_files():
    """Makes every hub forget the files it has been asked about whose size or modified time changed on disk since the library keyed them, so the next look-up re-keys the file and measures it again."""
    if db is None:
        return 0
    library = _get_probe_library()
    paths = set()
    for hub in (media.get_duration_hub(), _get_gain_hub(), media.get_file_facts_hub()):
        if hub is not None:
            paths.update(hub.known_paths())
    changed = [p for p in paths if library.file_changed_on_disk(p)]
    for path in changed:
        _hub_forget_path(path)
    if changed:
        log.info("[DURATION PROVENANCE] %d file(s) changed on disk since the library last measured them -- the hubs forgot them so they get measured again: %s",
                 len(changed), [os.path.basename(p) for p in changed[:5]])
    return len(changed)


def _changed_file_sweep_loop():
    """Background sweep that periodically runs _forget_changed_files()."""
    if _app_shutting_down.wait(_background_scan_pace_seconds(_CHANGED_FILE_SWEEP_INTERVAL_S)):
        return
    while True:
        while _python_heavy_should_pause():
            if _app_shutting_down.wait(2.0):
                return
        try:
            _forget_changed_files()
        except Exception as e:
            log.warning(f"[CHANGED FILE SWEEP] sweep iteration failed: {e}")
        if _app_shutting_down.wait(_background_scan_pace_seconds(_CHANGED_FILE_SWEEP_INTERVAL_S)):
            return


# ============================================================================
# SECTION: One-time purge of removed scan data
# ============================================================================


def _purge_removed_scan_data():
    """Delete the stored renorm ledger left in the saved config."""
    if db is None:
        return
    removed_ledger = 0
    ledger = db.config.pop("_renorm_sweep_processed", None)
    if ledger is not None:
        removed_ledger = len(ledger) if hasattr(ledger, "__len__") else 1
    if ledger is None:
        return
    log.info("[CONFIG PURGE] removed old renorm ledger (%d entr%s)",
             removed_ledger, "y" if removed_ledger == 1 else "ies")
    try:
        db.save_settings()
    except Exception as e:
        log.warning(f"[CONFIG PURGE] save after purge failed: {e}")


# WARNING: the fallback numbers below must match LOUDNESS_TIMEOUT_BACKOFF_SECONDS in performance_governor.py; they are used only when that module fails to import.
_LOUDNESS_TIMEOUT_BACKOFF_S = performance_governor.LOUDNESS_TIMEOUT_BACKOFF_SECONDS if performance_governor is not None else (600, 1800, 7200, 21600)


# ============================================================================
# SECTION: Loudness probe cooldowns, probe claims & guarded probes
# ============================================================================


def _loudness_backoff_seconds(streak):
    idx = min(max(streak, 1) - 1, len(_LOUDNESS_TIMEOUT_BACKOFF_S) - 1)
    return _LOUDNESS_TIMEOUT_BACKOFF_S[idx]


def _loudness_probe_in_cooldown(norm_path):
    if not norm_path:
        return False
    facts = media.file_facts(norm_path)
    next_retry = facts["loudness_next_retry_ts"]
    if not next_retry:
        return False
    _in_cooldown = time.time() < next_retry
    if _in_cooldown:
        _log_warn_throttled(
            f"loudness_cooldown_{norm_path}",
            "[LOUDNESS PROBE] Skipping '%s' -- still in post-timeout cooldown "
            "for %.0fs more (streak %s)",
            os.path.basename(norm_path), next_retry - time.time(),
            facts["loudness_timeout_streak"] or "?",
            interval=60.0,
        )
    return _in_cooldown


def _record_loudness_timeout(norm_path):
    if not norm_path:
        return
    streak = (media.file_facts(norm_path)["loudness_timeout_streak"] or 0) + 1
    backoff = _loudness_backoff_seconds(streak)
    _hub = media.get_file_facts_hub()
    if _hub is None or not _hub.note(norm_path, loudness_timeout_streak=streak, loudness_next_retry_ts=time.time() + backoff):
        log.warning("[LOUDNESS PROBE] the library could not save the retry timer for %s; it will be retried without a cooldown", os.path.basename(norm_path))
    log.warning(f"[LOUDNESS PROBE] {os.path.basename(norm_path)}: timed out on every "
          f"window (streak {streak}) -- backing off {backoff}s before retrying")


def _clear_loudness_timeout_streak(norm_path):
    if not norm_path:
        return
    facts = media.file_facts(norm_path)
    if facts["loudness_timeout_streak"] or facts["loudness_next_retry_ts"]:
        _hub = media.get_file_facts_hub()
        if _hub is not None:
            _hub.clear(norm_path, "loudness_timeout_streak", "loudness_next_retry_ts")


# WARNING: the fallback numbers must match PROBE_MARKER_RENAME_* in performance_governor.py; they are used only when that module fails to import.
PROBE_MARKER_RENAME_ATTEMPTS = performance_governor.PROBE_MARKER_RENAME_ATTEMPTS if performance_governor is not None else 6
PROBE_MARKER_RENAME_STEP_SECONDS = performance_governor.PROBE_MARKER_RENAME_STEP_SECONDS if performance_governor is not None else 0.02

_probe_dispatch_lock = threading.Lock()
_probe_dispatch_inflight = set()


def _probe_marker_path():
    """Path to the tiny standalone "currently probing this" marker file."""
    if db is None:
        return None
    _dir = os.path.join(db.base_dir, LOGS_FOLDER_NAME)
    os.makedirs(_dir, exist_ok=True)
    return os.path.join(_dir, "_probe_inflight.json")


def _write_probe_marker(norm_p, field):
    """Records on disk that a probe is about to start, so a crash mid-probe leaves proof of which file and field was in flight."""
    # WARNING: the marker is fsync'd and atomically renamed; a half-written marker must never be possible.
    marker_path = _probe_marker_path()
    if not marker_path:
        return
    try:
        import json as _json
        tmp_path = marker_path + ".tmp"
        with open(tmp_path, "w") as f:
            _json.dump({"path": norm_p, "field": field, "ts": time.time()}, f)
            f.flush()
            os.fsync(f.fileno())
        # WARNING: on Windows a virus scanner or another reader can hold the file for a moment and os.replace then fails with access denied (WinError 5); a few short retries get past it and the marker stays atomic.
        _last_err = None
        for _attempt in range(PROBE_MARKER_RENAME_ATTEMPTS):
            try:
                os.replace(tmp_path, marker_path)
                _last_err = None
                break
            except PermissionError as _perm:
                _last_err = _perm
                time.sleep(PROBE_MARKER_RENAME_STEP_SECONDS * (_attempt + 1))
        if _last_err is not None:
            raise _last_err
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] failed to write probe-in-progress marker: {e}")


def _clear_probe_marker(norm_p, field):
    """Removes the in-flight marker once a probe finishes."""
    marker_path = _probe_marker_path()
    if not marker_path or not os.path.exists(marker_path):
        return
    try:
        import json as _json
        with open(marker_path, "r") as f:
            marker = _json.load(f)
        if marker.get("path") == norm_p and marker.get("field") == field:
            os.remove(marker_path)
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] failed to clear probe-in-progress marker: {e}")


def _note_probe_started(norm_p, field):
    """Breadcrumb of whatever's actively being probed right now."""
    if db is None:
        return
    db.config["_last_probe_started"] = {"path": norm_p, "field": field, "ts": time.time()}
    _write_probe_marker(norm_p, field)


def _note_probe_finished(norm_p, field):
    if db is None:
        return
    marker = db.config.get("_last_probe_started")
    if marker and marker.get("path") == norm_p and marker.get("field") == field:
        db.config.pop("_last_probe_started", None)
    _clear_probe_marker(norm_p, field)


def _claim_probe(norm_p, field):
    key = (norm_p, field)
    with _probe_dispatch_lock:
        if key in _probe_dispatch_inflight:
            return False
        _probe_dispatch_inflight.add(key)
        _note_probe_started(norm_p, field)
        return True


def _release_probe(norm_p, field):
    with _probe_dispatch_lock:
        _probe_dispatch_inflight.discard((norm_p, field))
        _note_probe_finished(norm_p, field)


def _header_facts(norm_p):
    """The shared header read for one file: {ok, duration, width, height, has_audio}, read once per file by the media library and reused by every lane. None when the library is unavailable."""
    try:
        lib = _get_probe_library()
        return lib.header_facts(norm_p) if lib is not None else None
    except Exception as e:
        _log_warn_throttled("header_facts", "[MEDIA LIBRARY] shared header read unavailable (%s); using separate reads", e)
        return None


media.set_header_facts_provider(_header_facts)


def _probe_duration_guarded(norm_p):
    if not _claim_probe(norm_p, "duration"):
        return None
    try:
        facts = _header_facts(norm_p)
        if facts is not None and facts.get("ok"):
            # WARNING: the library's duration already went through the VLC plausibility fallback; do not open the file in VLC again here.
            return facts.get("duration")
        return get_media_duration(norm_p)
    finally:
        _release_probe(norm_p, "duration")


def _probe_duration_gated(norm_p, lane="probe_and_duration"):
    """Background batch duration probe, admitted by the governor's probe lane (a music scan passes the music lane)."""
    with media._gov_gate(lane, label="header_duration(%s)" % os.path.basename(norm_p)):
        return _probe_duration_guarded(norm_p)


def _probe_dims_gated(norm_p):
    """Background batch dimension probe, admitted by the governor's probe lane."""
    with media._gov_gate("probe_and_duration", label="dims(%s)" % os.path.basename(norm_p)):
        return _probe_dims_guarded(norm_p)


def _probe_dims_guarded(norm_p):
    if not _claim_probe(norm_p, "dims"):
        return None
    try:
        return get_media_video_dimensions(norm_p)
    finally:
        _release_probe(norm_p, "dims")


def _governor_nullscope():
    import contextlib as _ctx
    return _ctx.nullcontext()


def _governor_priority_scope():
    """Runs first-scan work (duration, dimensions, loudness of a file about to play) without throttling; a no-op if the governor is missing."""
    if performance_governor is not None:
        return performance_governor.priority_scope()
    import contextlib as _ctx
    return _ctx.nullcontext()


def _probe_duration_and_dims_combined(norm_p):
    """Step 8: boot pre-warm / first-scan header probe -- priority scope around the original."""
    with _governor_priority_scope():
        return _probe_duration_and_dims_combined_impl(norm_p)


def _probe_duration_and_dims_combined_impl(norm_p):
    """One media_library.combined_header_probe() call that returns both duration and dimensions."""
    # WARNING: duration must still go through probe_duration_with_fallback's VLC sanity check.
    facts = _header_facts(norm_p)
    if facts is not None and facts.get("ok"):
        w, h = facts.get("width"), facts.get("height")
        return facts.get("duration"), ((int(w), int(h)) if w and h else None)
    try:
        import media_library as _ml
        result = _ml.combined_header_probe(norm_p)
    except Exception as e:
        log.warning("[MEDIA PRECACHE] combined header probe failed for %s, "
                    "falling back to separate duration/dims probes: %s",
                    os.path.basename(norm_p), e)
        result = None
    if result is None or not result.ok:
        return _probe_duration_seconds_fast(norm_p), _probe_dims_guarded(norm_p)
    try:
        duration, _source = _ml.probe_duration_with_fallback(norm_p, result)
    except Exception as e:
        log.warning("[MEDIA PRECACHE] duration fallback check failed for %s: %s",
                    os.path.basename(norm_p), e)
        duration = result.duration
    dims = (result.width, result.height) if result.width and result.height else None
    return duration, dims


# WARNING: the fallback numbers below must match PENDING_SCHEDULE_PROBE_PARALLEL and PENDING_PROBE_RESTORE_HOLD_SECONDS in performance_governor.py; used only when that module fails to import.
_PENDING_SCHEDULE_PROBE_PARALLEL = (performance_governor.PENDING_SCHEDULE_PROBE_PARALLEL
                                    if performance_governor is not None else 2)
_PENDING_PROBE_RESTORE_HOLD_SECONDS = (performance_governor.PENDING_PROBE_RESTORE_HOLD_SECONDS
                                       if performance_governor is not None else 60.0)


def _probe_pending_schedule_one(norm_path):
    """Probes one pending file for duration and dimensions; returns (norm_path, duration, dims) or None when it has nothing to store."""
    cached = _read_file_probe_facts(norm_path)
    if cached.get("duration") and cached.get("dims"):
        return None
    try:
        duration, dimensions = _probe_duration_and_dims_combined(norm_path)
    except Exception as exc:
        log.warning("[SCHEDULER] immediate duration/dimensions probe failed for %s: %s",
                    os.path.basename(norm_path), exc)
        return None
    if duration and duration > 0:
        return norm_path, duration, dimensions
    return None


# ============================================================================
# SECTION: Pending-file probe, one file at a time in the background
# ============================================================================
_PENDING_PROBE_RETRY_SECONDS = (performance_governor.PENDING_SCHEDULE_PROBE_RETRY_SECONDS
                                if performance_governor is not None else 5.0)
_PENDING_PROBE_REQUEST_STALE_SECONDS = (performance_governor.PENDING_SCHEDULE_PROBE_REQUEST_STALE_SECONDS
                                        if performance_governor is not None else 30.0)
# WARNING: the fallback must match PENDING_PROBE_URGENT_COUNT in performance_governor.py; used only when that module fails to import.
_PENDING_PROBE_URGENT_COUNT = (performance_governor.PENDING_PROBE_URGENT_COUNT
                               if performance_governor is not None else 4)
# WARNING: this dict is the only state of the pending probe; the probe threads never touch the database, only the PendingStore thread stores results (never the screen thread: owner log 2026-11-03, stores made from the scheduler call held the screen 200 to 480 ms). A path in "awaiting_store" has a result waiting in "results" and must not be probed again until it is stored, or the same result is stored several times.
_pending_probe_state = {"lock": threading.Lock(), "wake": threading.Event(), "requests": {},
                        "results": [], "in_flight": set(), "retry_at": {}, "threads": [], "active": 0,
                        "urgent_active": 0, "last_backlog": 0.0, "awaiting_store": set(), "stored": set(),
                        "last_store": {}, "store_wake": threading.Event(), "store_thread": None}
# WARNING: the fallback must match PENDING_PROBE_STORE_BATCH_SECONDS in performance_governor.py; used only when that module fails to import.
_PENDING_PROBE_STORE_BATCH_S = (performance_governor.PENDING_PROBE_STORE_BATCH_SECONDS
                                if performance_governor is not None else 15.0)


def _stored_length_held(path):
    """True when the length hub already holds a measured length for this path (read from what it holds, never from disk)."""
    hub = media.get_duration_hub()
    peek = getattr(hub, "peek", None) if hub is not None else None
    held = peek(path) if peek is not None else None
    return bool(held and held[0])


def _pending_probe_worker():
    """Probes the requested pending files one at a time. What airs soonest on every channel goes first (every channel's next file before any channel's second), at priority; the long backlog behind it is paced by the governor and only runs while the PC is calm."""
    # WARNING: the old worker ran every pending file of a block back to back inside a priority scope that the governor never throttles, so adding hundreds of files hammered the disk while a channel was opening. Only the first PENDING_PROBE_URGENT_COUNT files of a request are urgent now.
    state = _pending_probe_state
    while True:
        item = None
        urgent = True
        with state["lock"]:
            now_m = time.monotonic()
            best = None
            for key, request in list(state["requests"].items()):
                if now_m - request["seen"] > _PENDING_PROBE_REQUEST_STALE_SECONDS:
                    del state["requests"][key]
                    continue
                for rank, path in enumerate(request["paths"]):
                    # WARNING: a file stored a moment ago is not probed and stored again even when the length hub has not shown it yet (owner log 2026-11-06: 1,700 of 8,161 stores were the same files again, 1,436 of them in 0.00 s).
                    if (path in state["in_flight"] or path in state["awaiting_store"]
                            or (path in state.get("stored", ()) and _stored_length_held(path)) or state["retry_at"].get(path, 0.0) > now_m
                            or now_m - state.get("stored_at", {}).get(path, -1e9) < _PENDING_PROBE_RESTORE_HOLD_SECONDS):
                        continue
                    if best is None or rank < best[0]:
                        best = (rank, key, path)
                    break
            if best is not None:
                _rank, _key, _path = best
                urgent = _rank < _PENDING_PROBE_URGENT_COUNT
                if urgent or _pending_backlog_may_run(state, now_m):
                    item = (_key, _path)
                    state["in_flight"].add(_path)
                    state["active"] += 1
                    if urgent:
                        state["urgent_active"] = state.get("urgent_active", 0) + 1
                        if state["urgent_active"] == 1:
                            set_live_playback_priority(True)
                    else:
                        state["last_backlog"] = now_m
        if item is None:
            state["wake"].wait(1.0)
            state["wake"].clear()
            continue
        key, path = item
        started = time.monotonic()
        result = None
        try:
            if urgent:
                with _governor_priority_scope():
                    result = _probe_pending_schedule_one(path)
            else:
                with _scan_thread_slot("pending", SCAN_CLASS_DEEP) as _slot_ok:
                    if _slot_ok:
                        result = _probe_pending_schedule_one(path)
        except Exception as exc:
            log.warning("[SCHEDULER] background probe of %s failed: %s", os.path.basename(path), exc)
        finally:
            with state["lock"]:
                state["in_flight"].discard(path)
                state["active"] -= 1
                if state["active"] <= 0:
                    state["active"] = 0
                if urgent:
                    state["urgent_active"] = max(0, state.get("urgent_active", 1) - 1)
                    if state["urgent_active"] == 0:
                        set_live_playback_priority(False)
                state["retry_at"][path] = time.monotonic() + _PENDING_PROBE_RETRY_SECONDS
                if result is not None:
                    state["results"].append((key, result, time.monotonic() - started, urgent))
                    state["awaiting_store"].add(path)
            if result is not None:
                state["store_wake"].set()


def _pending_backlog_may_run(state, now_m):
    """True when a backlog (not-needed-soon) file may be probed now: the background scans are not paused and no live open is in flight."""
    if media._LIVE_PLAYBACK_PRIORITY.is_set():
        return False
    if _background_scan_should_pause():
        return False
    return True


def _store_pending_probe_results():
    """Stores the finished pending-probe lengths of every block that is due: a block with a length needed soon at once, any other block once every _PENDING_PROBE_STORE_BATCH_S; returns how many were stored. Runs on the PendingStore thread."""
    state = _pending_probe_state
    with state["lock"]:
        # WARNING: every stored length makes that block's lineup be built again, so a block's backlog lengths are stored together once every _PENDING_PROBE_STORE_BATCH_S; a length needed soon (an urgent probe) stores its whole block at once (owner log 2026-11-03: lineups rebuilt 50 to 64 s of every minute while lengths came in).
        _now_store = time.monotonic()
        _last_store = state.setdefault("last_store", {})
        _due_keys = {r[0] for r in state["results"]
                     if (len(r) > 3 and r[3]) or _now_store - _last_store.get(r[0], 0.0) >= _PENDING_PROBE_STORE_BATCH_S}
        finished = [r[:3] for r in state["results"] if r[0] in _due_keys]
        state["results"] = [r for r in state["results"] if r[0] not in _due_keys]
        for _due in _due_keys:
            _last_store[_due] = _now_store
        state["awaiting_store"].difference_update(item[0] for _key, item, _took in finished)
        # WARNING: a file in two channels' lists is probed once; the other channel's request still names it until that channel resolves again (owner log 2026-11-02: 190 files stored twice, N10).
        state.setdefault("stored", set()).update(item[0] for _key, item, _took in finished if item[1])
        _stored_at = state.setdefault("stored_at", {})
        for _key, item, _took in finished:
            if item[1]:
                _stored_at[item[0]] = _now_store
        waiting = {key: len(request.get("paths", [])) for key, request in state["requests"].items()}
    for result_key, item, took in finished:
        norm_path, duration, dimensions = item
        _patch_probed_gain("channel", result_key[0], result_key[2], norm_path,
                           duration=duration,
                           dims=dimensions)
        log.info("[SCHEDULER] ch%s %s: background probe stored %s (%.0fs long) in %.2fs; %d pending file(s) of this block still waiting.",
                 result_key[0], result_key[2], os.path.basename(norm_path), duration, took, max(0, waiting.get(result_key, 1) - 1))
    if finished:
        try:
            db.save_settings_async()
        except Exception as exc:
            log.warning("[SCHEDULER] could not persist background duration probes: %s", exc)
    return len(finished)


def _pending_store_worker():
    """PendingStore thread: stores the pending probe's finished lengths off the screen thread, woken by each finished probe and once a second for the blocks whose batch falls due."""
    state = _pending_probe_state
    while not _app_shutting_down.is_set():
        state["store_wake"].wait(1.0)
        state["store_wake"].clear()
        try:
            _store_pending_probe_results()
        except Exception as e:
            log.warning("[SCHEDULER] storing background duration probes failed (tried again next pass): %s", e)


def _priority_probe_pending_schedule(ch_key, container_key, sub_key, pending_tracks):
    """Hands a channel's pending files to the one-at-a-time background probe and wakes the PendingStore thread for the results that have finished; it never waits for a probe and never stores anything itself."""
    if db is None or _channel_is_server_streamed(ch_key):
        return
    state = _pending_probe_state
    key = (ch_key, container_key, sub_key)
    norm_paths = []
    for track in pending_tracks or []:
        path = track.get("path") if isinstance(track, dict) else None
        if path:
            norm_path = os.path.normpath(path)
            if norm_path not in norm_paths:
                norm_paths.append(norm_path)
    with state["lock"]:
        if norm_paths:
            request = state["requests"].get(key)
            if request is None:
                state["requests"][key] = {"paths": norm_paths, "seen": time.monotonic()}
            else:
                request["paths"] = norm_paths
                request["seen"] = time.monotonic()
        else:
            state["requests"].pop(key, None)
        state["threads"] = [t for t in state["threads"] if t.is_alive() or t.ident is None]
        # WARNING: new probe threads are made and counted while the lock is held, so two callers at once cannot both see a missing thread and start one each (owner log 2026-11-06 showed PendingProbe x2 with one allowed).
        missing_workers = (max(1, _PENDING_SCHEDULE_PROBE_PARALLEL) - len(state["threads"])) if norm_paths else 0
        _new_workers = []
        for _ in range(max(0, missing_workers)):
            _w = threading.Thread(target=_pending_probe_worker, name="PendingProbe", daemon=True)
            state["threads"].append(_w)
            _new_workers.append(_w)
        _store_thread = state.get("store_thread")
        start_store = (_store_thread is None or not _store_thread.is_alive()) and bool(norm_paths or state["results"])
        if start_store:
            state["store_thread"] = threading.Thread(target=_pending_store_worker, name="PendingStore", daemon=True)
            _store_thread = state["store_thread"]
    if start_store:
        _store_thread.start()
    if _new_workers:
        initialize_vlc_on_demand()
        for worker in _new_workers:
            worker.start()
    if norm_paths:
        state["wake"].set()
    if state["results"]:
        state["store_wake"].set()


# WARNING: the fallback numbers below must match SHOW_SMOOTH_TOLERANCE_DB in performance_governor.py; they are used only when that module fails to import.
SHOW_SMOOTH_TOLERANCE_DB = performance_governor.SHOW_SMOOTH_TOLERANCE_DB if performance_governor is not None else 0.3
_show_loudness_floor = {}
_show_loudness_floor_lock = threading.Lock()


def _get_show_smoothing_key(norm_path):
    if not norm_path:
        return None
    parent = os.path.basename(os.path.dirname(norm_path))
    info = _season_folder_base(parent)
    if info:
        return info[1]
    if _bare_season_number(parent) is not None:
        grandparent = os.path.basename(os.path.dirname(os.path.dirname(norm_path)))
        return _normalize_show_key(grandparent) if grandparent else None
    return None


def _apply_show_loudness_smoothing(norm_p, gain, shortfall_info):
    show_key = _get_show_smoothing_key(norm_p)
    if show_key is None or not shortfall_info:
        return gain
    achieved = shortfall_info.get("achieved_lufs")
    measured = shortfall_info.get("measured_lufs")
    peak_capped = shortfall_info.get("peak_capped")
    if achieved is None or measured is None:
        return gain
    with _show_loudness_floor_lock:
        floor = _show_loudness_floor.get(show_key)
        if peak_capped:
            if floor is None or achieved < floor:
                _show_loudness_floor[show_key] = achieved
            return gain
        if floor is not None and achieved > floor + SHOW_SMOOTH_TOLERANCE_DB:
            _smoothed_gain = min(gain, 10 ** ((floor - measured) / 20.0))
            print(f"[LOUDNESS PROBE] *** SHOW SMOOTHED *** {os.path.basename(norm_p)}: "
                  f"would land at {achieved:.1f} LUFS (uncapped) but a peak-limited sibling "
                  f"in this show already established a {floor:.1f} LUFS floor -- "
                  f"matched down to x{_smoothed_gain:.2f} so this episode doesn't stand out "
                  f"louder than its neighbors")
            return _smoothed_gain
    return gain


# ============================================================================
# SECTION: Learned series loudness offset (F3)
# ============================================================================

# WARNING: the fallback numbers below must match LOUDNESS_LEARN_MIN_FILES, LOUDNESS_LEARN_AGREE_DB, LOUDNESS_LEARN_SINGLE_CHANGE_DB, LOUDNESS_LEARN_MAX_OFFSET_DB, LOUDNESS_LEARN_SETTLE_SECONDS in performance_governor.py; they are used only when that module fails to import.
LOUDNESS_LEARN_MIN_FILES = performance_governor.LOUDNESS_LEARN_MIN_FILES if performance_governor is not None else 3
LOUDNESS_LEARN_AGREE_DB = performance_governor.LOUDNESS_LEARN_AGREE_DB if performance_governor is not None else 2.0
LOUDNESS_LEARN_SINGLE_CHANGE_DB = performance_governor.LOUDNESS_LEARN_SINGLE_CHANGE_DB if performance_governor is not None else 3.0
LOUDNESS_LEARN_MAX_OFFSET_DB = performance_governor.LOUDNESS_LEARN_MAX_OFFSET_DB if performance_governor is not None else 12
LOUDNESS_LEARN_SETTLE_SECONDS = performance_governor.LOUDNESS_LEARN_SETTLE_SECONDS if performance_governor is not None else 5.0

_loudness_learning_lock = threading.RLock()
_learned_offset_pending = {}
_owner_gain_learning_pending = {}
_owner_gain_learning_worker = {"thread": None}


_LEARN_FIELDS = ("learn_series_key", "learn_change_db", "learn_change_at", "learn_baseline_db", "learn_applied_db")


def _learning_read(norm_path):
    """The file's loudness-learning fields from its library row ({} when the library cannot read them yet)."""
    hub = _get_gain_hub()
    if hub is None or not norm_path:
        return {}
    return hub.read_file_fields(norm_path, _LEARN_FIELDS) or {}


def _learning_write(norm_path, **fields):
    """Writes loudness-learning fields into the file's library row; one line in the log when the library cannot hold them yet."""
    hub = _get_gain_hub()
    if hub is None or not hub.note_file_fields(norm_path, **fields):
        log.warning("[LOUDNESS LEARN] %s: the library could not save the learned loudness (%s), it is not kept",
                    os.path.basename(str(norm_path)), ", ".join(sorted(fields)))
        return False
    return True


def _series_offset_from_changes(changes):
    """The series offset in whole dB from the owner's counted changes, oldest first, held to LOUDNESS_LEARN_MAX_OFFSET_DB: the newest change when it is bigger than LOUDNESS_LEARN_SINGLE_CHANGE_DB; otherwise the middle of the last LOUDNESS_LEARN_MIN_FILES changes when they all go the same way and sit within LOUDNESS_LEARN_AGREE_DB of each other; 0 otherwise."""
    values = [float(change) for change, _at in changes]
    if not values:
        return 0
    if abs(values[-1]) > LOUDNESS_LEARN_SINGLE_CHANGE_DB:
        offset = values[-1]
    else:
        recent = values[-LOUDNESS_LEARN_MIN_FILES:]
        if (len(recent) < LOUDNESS_LEARN_MIN_FILES or not (all(v > 0 for v in recent) or all(v < 0 for v in recent))
                or max(recent) - min(recent) > LOUDNESS_LEARN_AGREE_DB):
            return 0
        offset = _middle_value(recent)
    return int(max(-LOUDNESS_LEARN_MAX_OFFSET_DB, min(LOUDNESS_LEARN_MAX_OFFSET_DB, round(offset))))


def _series_offset_for_key(show_key):
    """The whole dB offset learned for one series from the owner's own gain changes on its files, 0 when they give none."""
    hub = _get_gain_hub()
    if hub is None or show_key is None:
        return 0
    return _series_offset_from_changes(hub.read_series_changes(show_key))


def _learned_series_offset(norm_path):
    """The whole dB offset learned for the file's series, or 0 when the series has none."""
    if db is None:
        return 0
    return _series_offset_for_key(_get_show_smoothing_key(norm_path))


def _learned_offset_applied(norm_path):
    """The dB offset that was added to this file's saved scanned gain, or 0 when none was."""
    if db is None:
        return 0
    value = _learning_read(norm_path).get("learn_applied_db")
    return int(round(float(value))) if value else 0


def _season_others_middle_db(norm_path):
    """The middle scanned dB of the other episodes in the file's season folder, without learned offsets, or None until enough of them are scanned."""
    hub = _get_gain_hub()
    if hub is None:
        return None
    others = []
    for member in _gain_bundle_members(norm_path):
        if member == norm_path:
            continue
        member_db = _gain_check_db(hub, member)
        if member_db is not None:
            others.append(member_db)
    if len(others) < media.GAIN_CHECK_BUNDLE_MIN_SCANNED - 1:
        return None
    return _middle_value(others)


# WARNING: the fallback numbers must match SEASON_GUESS_* in performance_governor.py; they are used only when that module fails to import.
SEASON_GUESS_MIN_SCANNED = performance_governor.SEASON_GUESS_MIN_SCANNED if performance_governor is not None else 2
SEASON_GUESS_GAIN_SPREAD_DB = performance_governor.SEASON_GUESS_GAIN_SPREAD_DB if performance_governor is not None else 2.0
SEASON_GUESS_PICTURE_RECT_TOLERANCE = performance_governor.SEASON_GUESS_PICTURE_RECT_TOLERANCE if performance_governor is not None else 0.02
SEASON_GUESS_PICTURE_ASPECT_TOLERANCE = performance_governor.SEASON_GUESS_PICTURE_ASPECT_TOLERANCE if performance_governor is not None else 0.02
SEASON_GUESS_CACHE_SECONDS = performance_governor.SEASON_GUESS_CACHE_SECONDS if performance_governor is not None else 30.0

_season_guess_cache = {}
_season_guess_boxes = {}
_season_guess_lock = threading.Lock()


_season_guess_pending = {}
_season_guess_worker = [None]


def _season_guess_run_pending():
    """Works out every queued season guess, the newest request first, and stores each answer; runs on the SeasonGuess thread and ends when the queue is empty."""
    while True:
        with _season_guess_lock:
            if not _season_guess_pending:
                _season_guess_worker[0] = None
                return
            key = next(reversed(_season_guess_pending))
            compute = _season_guess_pending.pop(key)
            _before = _season_guess_cache.get(key)
            _season_guess_cache[key] = (time.monotonic(), _before[1] if _before is not None else None)
        try:
            value = compute()
        except Exception as _swallowed_error:
            _log_swallowed("_season_guess_run_pending: working out a season guess", _swallowed_error)
            value = None
        with _season_guess_lock:
            if len(_season_guess_cache) > 2000:
                _season_guess_cache.clear()
            _season_guess_cache[key] = (time.monotonic(), value)


def _season_guess_cached(kind, norm_path, compute):
    """The season guess worked out for one file, or None until it is. It never works anything out on the calling thread (it would list a folder and read the library on a channel change): a guess older than SEASON_GUESS_CACHE_SECONDS, or none yet, is queued for the SeasonGuess thread and the last answer is returned meanwhile."""
    # WARNING: this is called on the tune path; it must stay free of disk reads and gate waits (owner log 2026-11-06: hashing the season's files here waited 20 s behind the scans and the load was set aside).
    key = (kind, norm_path)
    with _season_guess_lock:
        held = _season_guess_cache.get(key)
        if held is not None and time.monotonic() - held[0] < SEASON_GUESS_CACHE_SECONDS:
            return held[1]
        _season_guess_pending.pop(key, None)
        _season_guess_pending[key] = compute
        _worker = _season_guess_worker[0]
        if _worker is None:
            _worker = _season_guess_worker[0] = threading.Thread(target=_season_guess_run_pending, daemon=True, name="SeasonGuess")
            _start = True
        else:
            _start = False
    if _start:
        _worker.start()
    return held[1] if held is not None else None


def _season_guess_warm(norm_path):
    """Queues the season guesses (loudness and picture box) of a file that is about to air, so they are ready when its channel opens it."""
    if norm_path:
        norm = os.path.normpath(str(norm_path))
        _season_guess_gain(norm)
        _season_guess_picture_box(norm)


def _season_guess_gain(norm_path):
    """The linear gain an unscanned episode plays with until its own scan lands: the middle scanned gain of the other episodes in its season folder plus the series' learned offset, only when at least SEASON_GUESS_MIN_SCANNED of them are scanned and sit within SEASON_GUESS_GAIN_SPREAD_DB of each other; None otherwise. Never saved in the library, so the scans still run and the scan bar never counts it."""
    def compute():
        hub = _get_gain_hub()
        if hub is None or _get_part_group_key(norm_path) or _get_library_gain(norm_path) is not None:
            return None
        member_dbs = []
        for member in _gain_bundle_members(norm_path):
            if member != norm_path:
                member_db = _gain_check_db(hub, member)
                if member_db is not None:
                    member_dbs.append(member_db)
        middle = media.season_values_agree(member_dbs, SEASON_GUESS_GAIN_SPREAD_DB, SEASON_GUESS_MIN_SCANNED)
        if middle is None:
            return None
        return min(10 ** ((middle + _learned_series_offset(norm_path)) / 20.0), LOUDNESS_GAIN_CEILING)
    return _season_guess_cached("gain", norm_path, compute)


def _season_guess_picture_box(norm_path):
    """The picture box an unscanned episode is drawn with until its own scan lands: a copy of the box of the other scanned episodes in its season folder, only when at least SEASON_GUESS_MIN_SCANNED of them are scanned under today's detector and agree on kind, picture shape and rectangle; None otherwise. The copy is marked guessed, is never saved in the library and never counts on the scan bar."""
    def compute():
        import media_library as _ml
        lib = _get_probe_library()
        if lib is None:
            return None
        boxes = []
        for member in _gain_bundle_members(norm_path):
            if member == norm_path:
                continue
            entry = lib.get_cached_known(member)
            box = entry.get("picture_box") if entry else None
            if (box and (entry.get("picture_box_detector_version") or 0) >= _ml.PICTURE_BOX_DETECTOR_VERSION
                    and box.get("reason") and box.get("norm") and box.get("picture_aspect")):
                boxes.append(box)
        if len(boxes) < SEASON_GUESS_MIN_SCANNED:
            return None
        first = boxes[0]
        for other in boxes[1:]:
            if (other["reason"] != first["reason"]
                    or abs(float(other["picture_aspect"]) - float(first["picture_aspect"])) > SEASON_GUESS_PICTURE_ASPECT_TOLERANCE
                    or len(other["norm"]) != len(first["norm"])
                    or any(abs(float(a) - float(b)) > SEASON_GUESS_PICTURE_RECT_TOLERANCE for a, b in zip(other["norm"], first["norm"]))):
                return None
        guess = dict(first)
        guess["guessed"] = True
        with _season_guess_lock:
            if len(_season_guess_boxes) > 2000:
                _season_guess_boxes.clear()
            _season_guess_boxes[norm_path] = guess
        return guess
    return _season_guess_cached("box", norm_path, compute)


def _season_seeds_first(deep_items):
    """Moves the first SEASON_GUESS_MIN_SCANNED files of every season ahead of the rest of the backlog (the rest keep their order), so the season has the scanned episodes its other episodes borrow from."""
    seeds, rest, taken = [], [], {}
    for item in deep_items:
        guess_class, season_key = media._guess_class(item[3])
        if guess_class == "episode" and taken.get(season_key, 0) < SEASON_GUESS_MIN_SCANNED:
            taken[season_key] = taken.get(season_key, 0) + 1
            seeds.append(item)
        else:
            rest.append(item)
    return seeds + rest


def _series_scan_is_outlier(norm_path, raw_db):
    """True when enough of the season is already scanned and this file's own scanned dB is GAIN_CHECK_NEIGHBOR_DB or more from the middle of the others, the same test the season check uses."""
    middle = _season_others_middle_db(norm_path)
    return middle is not None and round(abs(raw_db - middle), 2) >= media.GAIN_CHECK_NEIGHBOR_DB


def _apply_learned_series_offset(norm_path, gain):
    """Adds the series' learned offset to a freshly scanned gain unless this file's own scan is off from its siblings; that file is left without the offset until the season check scans it again and confirms it. The offset used is held until the gain is saved."""
    norm = os.path.normpath(norm_path)
    offset = _learned_series_offset(norm)
    applied = 0
    if offset and gain and gain > 0:
        if _series_scan_is_outlier(norm, 20.0 * math.log10(gain)):
            log.info("[LOUDNESS LEARN] %s scanned differently from the rest of its series, so the learned %+d dB was left off it until it is scanned again",
                     os.path.basename(norm), offset)
        else:
            applied = offset
    with _loudness_learning_lock:
        _learned_offset_pending[norm] = applied
    return gain * 10 ** (applied / 20.0) if applied else gain


def _apply_offset_once_confirmed(norm_path, gain, middle_db):
    """After a file was scanned again at new places: adds the learned offset only if its new scanned dB now sits within GAIN_CHECK_NEIGHBOR_DB of its siblings' middle, otherwise leaves it without."""
    norm = os.path.normpath(norm_path)
    offset = _learned_series_offset(norm)
    applied = 0
    if offset and gain and gain > 0:
        if round(abs(20.0 * math.log10(gain) - middle_db), 2) < media.GAIN_CHECK_NEIGHBOR_DB:
            applied = offset
            log.info("[LOUDNESS LEARN] %s now scans like the rest of its series, so the learned %+d dB was added", os.path.basename(norm), offset)
        else:
            log.info("[LOUDNESS LEARN] %s still scans differently from the rest of its series, so the learned %+d dB stays off it", os.path.basename(norm), offset)
    with _loudness_learning_lock:
        _learned_offset_pending[norm] = applied
    return gain * 10 ** (applied / 20.0) if applied else gain


def _take_learned_offset_applied(norm_path):
    """The offset held for the scan being saved for this file, once; 0 when none is held."""
    with _loudness_learning_lock:
        return _learned_offset_pending.pop(os.path.normpath(norm_path), 0)


def _owner_gain_baseline_db(norm_path, hub):
    """The file's own scanned dB, without any learned offset, kept from the owner's first change to it; None when the file has no current scan to compare the change with."""
    held = _learning_read(norm_path).get("learn_baseline_db")
    if held is not None:
        try:
            return float(held)
        except (TypeError, ValueError) as _swallowed_error:
            _log_swallowed("_owner_gain_baseline_db: return float(held)", _swallowed_error)
            return None
    try:
        if hub.read(norm_path)["scan_version"] == media.OWNER_GAIN_SCAN_VERSION:
            return None
    except Exception as _swallowed_error:
        _log_swallowed("_owner_gain_baseline_db: reading the file's gain row", _swallowed_error)
        return None
    gain = _get_library_gain(norm_path)
    if gain is None or gain <= 0:
        return None
    return 20.0 * math.log10(gain) - _learned_offset_applied(norm_path)


def _series_members(norm_path):
    """The video files of the file's whole series: every season folder beside its own that belongs to the same show; empty when the file is not in a season folder or the drive is slow."""
    show_key = _get_show_smoothing_key(norm_path)
    if show_key is None:
        return []
    show_folder = os.path.dirname(os.path.dirname(norm_path))
    if _is_drive_degraded(show_folder):
        return []
    try:
        with os.scandir(show_folder) as seasons:
            season_dirs = sorted(e.path for e in seasons if e.is_dir())
    except OSError as e:
        log.warning("[LOUDNESS LEARN] could not list the show folder %s: %s", show_folder, e)
        return []
    members = []
    for season_dir in season_dirs:
        if _get_show_smoothing_key(os.path.join(season_dir, "_")) == show_key:
            members.extend(_gain_bundle_members(os.path.join(season_dir, "_")))
    return members


def _apply_series_offset_to_scanned(norm_path, offset):
    """Gives every scanned episode of the file's series its own scan plus the series' learned offset; the owner's own gains, joined multi-part titles, episodes not scanned under the current settings and episodes whose scan sits far from their season are left as they are. Returns how many files changed."""
    hub = _get_gain_hub()
    if hub is None:
        return 0
    changed = 0
    for member in _series_members(norm_path):
        raw_db = _gain_check_db(hub, member)
        if raw_db is None:
            continue
        applied = 0 if _series_scan_is_outlier(member, raw_db) else int(offset)
        if applied == _learned_offset_applied(member):
            continue
        if hub.note_learned_gain(member, 10 ** ((raw_db + applied) / 20.0), applied):
            changed += 1
        else:
            log.warning("[LOUDNESS LEARN] %s: the library could not save the series' learned %+d dB", os.path.basename(member), applied)
    return changed


def _learn_from_owner_gain(norm_path, baseline_db, total_db):
    """Records in the file's library row how far the owner moved this file from its own scan and works out the series' offset from the owner's counted changes (_series_offset_from_changes). A change to an episode whose own scan sits GAIN_CHECK_NEIGHBOR_DB or more from its season is kept for that episode only and not counted. When the offset changes, every scanned episode of the series is given it."""
    if baseline_db is None or db is None:
        return
    show_key = _get_show_smoothing_key(norm_path)
    if show_key is None:
        return
    delta = int(round(total_db - baseline_db))
    middle = _season_others_middle_db(norm_path)
    one_off = middle is not None and round(abs(baseline_db - middle), 2) >= media.GAIN_CHECK_NEIGHBOR_DB
    old_offset = _series_offset_for_key(show_key)
    with _loudness_learning_lock:
        _learning_write(norm_path, learn_series_key=show_key,
                        learn_change_db=None if one_off else float(delta),
                        learn_change_at=None if one_off else time.time(),
                        learn_baseline_db=float(baseline_db), learn_applied_db=None)
    if one_off:
        log.info("[LOUDNESS LEARN] %s scans %+.1f dB from the rest of its season, so the owner's %+d dB is kept for this episode only (it now sits %+.1f dB from the others)",
                 os.path.basename(norm_path), baseline_db - middle, delta, total_db - middle)
        return
    new_offset = _series_offset_for_key(show_key)
    if new_offset != old_offset:
        changed = _apply_series_offset_to_scanned(norm_path, new_offset)
        log.info("[LOUDNESS LEARN] series '%s': learned offset changed from %+d dB to %+d dB after the owner changed %s by %+d dB; %d scanned episodes updated",
                 show_key, old_offset, new_offset, os.path.basename(norm_path), delta, changed)


def _queue_owner_gain_learning(norm_path, baseline_db, total_db):
    """Hands the owner's gain change to the learning thread, which learns from it once the owner has stopped pressing for LOUDNESS_LEARN_SETTLE_SECONDS; the baseline from the first press is kept."""
    with _loudness_learning_lock:
        held = _owner_gain_learning_pending.get(norm_path)
        _owner_gain_learning_pending[norm_path] = (held[0] if held else baseline_db, total_db, time.monotonic())
        worker = _owner_gain_learning_worker["thread"]
        if worker is None or not worker.is_alive():
            worker = threading.Thread(target=_owner_gain_learning_loop, name="LoudnessLearn", daemon=True)
            _owner_gain_learning_worker["thread"] = worker
            worker.start()


def _owner_gain_learning_loop():
    """Learns from each owner gain change once it has settled; stops when nothing is waiting."""
    while not _app_shutting_down.is_set():
        due = None
        with _loudness_learning_lock:
            if not _owner_gain_learning_pending:
                _owner_gain_learning_worker["thread"] = None
                return
            now = time.monotonic()
            for path, (baseline_db, total_db, at) in _owner_gain_learning_pending.items():
                if now - at >= LOUDNESS_LEARN_SETTLE_SECONDS:
                    due = (path, baseline_db, total_db)
                    break
            if due is not None:
                del _owner_gain_learning_pending[due[0]]
        if due is None:
            _app_shutting_down.wait(0.5)
            continue
        try:
            _learn_from_owner_gain(*due)
        except Exception as e:
            log.warning("[LOUDNESS LEARN] learning from the owner's change to %s failed: %s", os.path.basename(due[0]), e)


def _probe_loudness_guarded(norm_p, out_shortfall=None, apply_learned_offset=True, **kwargs):
    """Governed loudness probe; out_shortfall, if given, receives the raw measurement behind the returned gain; apply_learned_offset False leaves the series' learned offset off the result."""
    # WARNING: owner/manual gain rows are authoritative; a queued safety scan must never replace them.
    _existing_hub = _get_gain_hub()
    if _existing_hub is not None:
        try:
            _existing_record = _existing_hub.read(norm_p)
            if (_existing_record.get("scan_version") == media.OWNER_GAIN_SCAN_VERSION
                    or _existing_record.get("manual_gain_db")):
                return _existing_record.get("gain") or 1.0
        except Exception as _swallowed_error:
            _log_swallowed("_probe_loudness_guarded: reading manual gain protection", _swallowed_error)
    _group_key = _get_part_group_key(norm_p)
    if _group_key:
        _group_entry = _read_part_group_gain(_group_key)
        if _group_entry and os.path.normpath(_group_entry.get("anchor_path", "")) != norm_p:
            print(f"[LOUDNESS PROBE] '{os.path.basename(norm_p)}' is part of the same "
                  f"title as already-scanned '{os.path.basename(_group_entry.get('anchor_path', ''))}' "
                  f"-- reusing its gain x{_group_entry.get('gain', 1.0):.2f} instead of "
                  f"re-measuring this part independently.")
            if out_shortfall is not None:
                out_shortfall["measured_lufs"] = None
            return _group_entry.get("gain", 1.0)

    if not _claim_probe(norm_p, "gain"):
        return None
    try:
        _shortfall_info = {}
        _gain = get_media_loudness_gain(norm_p, shortfall_out=_shortfall_info, db=db, **kwargs)
        if _gain is not None:
            _set_gain_double_checked(norm_p, bool(_shortfall_info.get("double_checked")))
            _set_gain_windows(norm_p, _shortfall_info.get("windows"))
            _gain = _apply_show_loudness_smoothing(norm_p, _gain, _shortfall_info)
            if apply_learned_offset:
                _gain = _apply_learned_series_offset(norm_p, _gain)
            else:
                with _loudness_learning_lock:
                    _learned_offset_pending[os.path.normpath(norm_p)] = 0
        if _group_key and _gain is not None:
            _set_part_group_anchor_gain(_group_key, norm_p, _gain)
        if out_shortfall is not None:
            out_shortfall.update(_shortfall_info)
        return _gain
    finally:
        _release_probe(norm_p, "gain")


# ============================================================================
# SECTION: Gain double-check
# ============================================================================

_gain_double_checked_pending = set()
_gain_windows_pending = {}
_gain_check_lock = threading.Lock()
_gain_check_tried = set()
_gain_check_folder_seen = {}

# WARNING: the fallback numbers below must match GAIN_CHECK_FOLDER_REVISIT_S in performance_governor.py; they are used only when that module fails to import.
_GAIN_CHECK_FOLDER_REVISIT_S = performance_governor.GAIN_CHECK_FOLDER_REVISIT_S if performance_governor is not None else 600


def _set_gain_double_checked(norm_path, checked):
    """Remembers whether the scan just measured for a file was double-checked, so the save that follows marks the saved gain as checked."""
    with _gain_check_lock:
        if checked:
            _gain_double_checked_pending.add(norm_path)
        else:
            _gain_double_checked_pending.discard(norm_path)


def _take_gain_double_checked(norm_path):
    """True once when the scan being saved for this file was double-checked."""
    with _gain_check_lock:
        if norm_path in _gain_double_checked_pending:
            _gain_double_checked_pending.discard(norm_path)
            return True
    return False


def _set_gain_windows(norm_path, windows):
    """Remembers the sample windows behind the scan just measured for a file, so the save that follows keeps them with the gain."""
    with _gain_check_lock:
        if windows:
            _gain_windows_pending[norm_path] = [tuple(w) for w in windows]
        else:
            _gain_windows_pending.pop(norm_path, None)


def _take_gain_windows(norm_path):
    """The sample windows remembered for the scan being saved for this file, once; empty when there are none."""
    with _gain_check_lock:
        return _gain_windows_pending.pop(norm_path, [])


def _gain_bundle_members(norm_path):
    """The video files in the same season folder as norm_path as normalised paths; empty when the file is not in a season folder or the drive is slow."""
    if _get_show_smoothing_key(norm_path) is None:
        return []
    folder = os.path.dirname(norm_path)
    if _is_drive_degraded(folder):
        return []
    try:
        with os.scandir(folder) as entries:
            return sorted(os.path.normpath(e.path) for e in entries
                          if e.is_file() and os.path.splitext(e.name)[1].lower() in media.VIDEO_DISPLAY_EXTS)
    except OSError as e:
        log.warning("[LOUDNESS CHECK] could not list the season folder %s: %s", folder, e)
        return []


def _gain_check_db(hub, norm_path):
    """A file's scanned gain in dB for the season comparison, or None when it has none on record, the owner changed it, or it belongs to a joined multi-part title."""
    if _get_part_group_key(norm_path):
        return None
    record = hub.read(norm_path)
    if record["scan_version"] == media.OWNER_GAIN_SCAN_VERSION or record["manual_gain_db"]:
        return None
    gain = _get_library_gain(norm_path)
    if gain is None or gain <= 0:
        return None
    return 20.0 * math.log10(gain) - _learned_offset_applied(norm_path)


def _middle_value(values):
    """The middle number of a non-empty list."""
    ordered = sorted(values)
    mid = len(ordered) // 2
    return ordered[mid] if len(ordered) % 2 else (ordered[mid - 1] + ordered[mid]) / 2.0


def _gain_neighbor_check(norm_path, force=False):
    """After-the-fact gain check for the season folder of one file: once enough of the season is scanned, a file whose gain is GAIN_CHECK_NEIGHBOR_DB or more from the middle gain of the rest is scanned again once with more windows at new places, its gain is worked out from every window together, and the new gain replaces the old one. Returns how many files were scanned again."""
    hub = _get_gain_hub()
    if hub is None or db is None:
        return 0
    folder = os.path.dirname(norm_path)
    now = time.monotonic()
    with _gain_check_lock:
        if not force and now - _gain_check_folder_seen.get(folder, -1e9) < _GAIN_CHECK_FOLDER_REVISIT_S:
            return 0
        _gain_check_folder_seen[folder] = now
    members = _gain_bundle_members(norm_path)
    if len(members) < media.GAIN_CHECK_BUNDLE_MIN_SCANNED:
        return 0
    rescanned = 0
    try:
        for _round in range(len(members)):
            if _app_shutting_down.is_set() or _LOUDNESS_PRIORITY_PENDING.is_set():
                break
            scanned = {}
            for member in members:
                member_db = _gain_check_db(hub, member)
                if member_db is not None:
                    scanned[member] = member_db
            if len(scanned) < media.GAIN_CHECK_BUNDLE_MIN_SCANNED:
                break
            worst = None
            for member, member_db in scanned.items():
                if member in _gain_check_tried or hub.is_checked(member):
                    continue
                length = _read_file_probe_facts(member).get("duration") or 0
                if media._lufs_sample_windows(length) is None:
                    continue
                middle = _middle_value([v for other, v in scanned.items() if other != member])
                off = abs(member_db - middle)
                if round(off, 2) >= media.GAIN_CHECK_NEIGHBOR_DB and (worst is None or off > worst[1]):
                    worst = (member, off, middle, member_db)
            if worst is None:
                break
            member, off, middle, was_db = worst
            with _gain_check_lock:
                _gain_check_tried.add(member)
            new_gain = _probe_loudness_guarded(member, treat_fallback_as_unknown=True,
                                               prior_windows=hub.read_windows(member), apply_learned_offset=False)
            if new_gain:
                new_gain = _apply_offset_once_confirmed(member, new_gain, middle)
            if not new_gain or not _store_loudness_gain(member, new_gain):
                log.warning("[LOUDNESS CHECK] %s is %.1f dB from this season's middle gain but the scan at new places gave no saved result", os.path.basename(member), off)
                continue
            rescanned += 1
            log.info("[LOUDNESS CHECK] %s: gain %+.1f dB was %.1f dB from this season's middle gain (%+.1f dB); scanned again at new places with %d windows compared, now %+.1f dB",
                     os.path.basename(member), was_db, off, middle, len(hub.read_windows(member)), 20.0 * math.log10(new_gain))
    except Exception as e:
        log.warning("[LOUDNESS CHECK] season check for %s stopped: %s", folder, e)
    return rescanned


def _probe_music_loudness_guarded(norm_p, out_shortfall=None, **kwargs):
    """Music counterpart to _probe_loudness_guarded, used only by _music_precache_worker()."""
    if not _claim_probe(norm_p, "gain"):
        return None
    try:
        _shortfall_info = {}
        _gain = get_music_loudness_gain(norm_p, shortfall_out=_shortfall_info, db=db, **kwargs)
        if out_shortfall is not None:
            out_shortfall.update(_shortfall_info)
        return _gain
    finally:
        _release_probe(norm_p, "gain")


# WARNING: the fallback numbers below must match UNPLAYABLE_STRIKE_THRESHOLD in performance_governor.py; they are used only when that module fails to import.
UNPLAYABLE_STRIKE_THRESHOLD = performance_governor.UNPLAYABLE_STRIKE_THRESHOLD if performance_governor is not None else 3


