def _register_unplayable_strike(norm_path, reason):
    if not norm_path:
        return 0
    _hub = media.get_file_facts_hub()
    count = _hub.add_unplayable_strike(norm_path, reason, UNPLAYABLE_STRIKE_THRESHOLD) if _hub is not None else None
    if count is None:
        log.warning("[PLAYABILITY PROBE] the library could not save a strike for %s (%s)", os.path.basename(norm_path), reason)
        return 0
    print(f"[PLAYABILITY PROBE] Strike {count}/{UNPLAYABLE_STRIKE_THRESHOLD} for "
          f"'{os.path.basename(norm_path)}' -- {reason}")
    return count


def _mark_confirmed_no_audio(norm_path, reason):
    if not norm_path:
        return
    _hub = media.get_file_facts_hub()
    if _hub is None or not _hub.note(norm_path, confirmed_no_audio=True, no_audio_reason=reason):
        log.warning("[PLAYABILITY PROBE] the library could not record no audible content for %s (%s)", os.path.basename(norm_path), reason)
        return
    print(f"[PLAYABILITY PROBE] Confirmed no audible content in "
          f"'{os.path.basename(norm_path)}' -- {reason}")


def _register_probe_batch(batch_id, ch_key, container_key, sub_key, remaining_paths):
    """Records a batch probe pass so it can be resumed if the app goes down mid-pass."""
    if db is None:
        return
    batches = db.config.setdefault("_active_probe_batches", {})
    batches[batch_id] = {
        "ch": ch_key,
        "container": container_key,
        "sub": sub_key,
        "remaining": list(remaining_paths),
        "ts": time.time(),
    }


def _update_probe_batch_progress(batch_id, remaining_paths):
    if db is None:
        return
    batches = db.config.get("_active_probe_batches")
    if batches is not None and batch_id in batches:
        batches[batch_id]["remaining"] = list(remaining_paths)
        batches[batch_id]["ts"] = time.time()


def _clear_probe_batch(batch_id):
    if db is None:
        return
    batches = db.config.get("_active_probe_batches")
    if batches is not None:
        batches.pop(batch_id, None)


def _clear_interrupted_probe_value(norm_p, field):
    """Clears the one value (duration, picture size or gain) the library holds for a file whose probe was cut off, so the re-probe replaces it; returns True when there was a value to clear."""
    columns = {"duration": ("duration",), "dims": ("width", "height"), "gain": ("gain",)}.get(field)
    if not columns:
        return False
    had_value = bool(_read_file_probe_facts(norm_p).get(field))
    if had_value and _get_probe_library().clear_scan_values(norm_p, *columns):
        _hub_forget_path(norm_p)
        return True
    return False


def _report_interrupted_probe_marker():
    """Startup check: finds the file and field that were in flight when the last run died mid-probe."""
    # WARNING: whatever is cached for that file and field is untrusted, even if a value already reached the cache.
    if db is None:
        return
    db.config.pop("_last_probe_started", None)

    marker_path = _probe_marker_path()
    if not marker_path or not os.path.exists(marker_path):
        return

    try:
        import json as _json
        with open(marker_path, "r") as f:
            marker = _json.load(f)
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] could not read leftover probe marker "
                    f"(removing it): {e}")
        try:
            os.remove(marker_path)
        except FileNotFoundError:
            pass
        except Exception as _swallowed_error:
            _log_swallowed("_report_interrupted_probe_marker: os.remove(marker_path)", _swallowed_error)
        return

    path = marker.get("path")
    field = marker.get("field")

    try:
        os.remove(marker_path)
    except FileNotFoundError:
        pass
    except Exception as _swallowed_error:
        _log_swallowed("_report_interrupted_probe_marker: os.remove(marker_path)", _swallowed_error)

    if not path or not field:
        return

    norm_p = os.path.normpath(path)
    had_cached_value = _clear_interrupted_probe_value(norm_p, field)

    log.warning(
        f"[MEDIA PRECACHE] Last run was interrupted mid-probe on "
        f"'{os.path.basename(path)}' ({field})" +
        (" -- had a cached value already, but clearing it since a probe "
         "that got cut off mid-parse can't be trusted; queuing a clean "
         "re-probe." if had_cached_value else
         " -- no cached value yet; queuing a probe.")
    )

    def _requeue():
        try:
            if field == "duration":
                _probe_duration_guarded(norm_p)
            elif field == "dims":
                _probe_dims_guarded(norm_p)
            elif field == "gain":
                if _is_drive_degraded(norm_p):
                    log.warning("[MEDIA PRECACHE] not re-probing gain for %s right now -- "
                                "its drive looks degraded (%s)",
                                os.path.basename(norm_p), _drive_latency_summary(norm_p))
                else:
                    _probe_loudness_guarded(norm_p)
        except Exception as e:
            log.warning(f"[MEDIA PRECACHE] re-probe of interrupted file "
                        f"'{os.path.basename(norm_p)}' ({field}) failed: {e}")

    threading.Thread(target=_requeue, daemon=True).start()


def _resume_interrupted_probe_batches():
    """Startup check: resumes batch probe passes that were still in progress when the app last went down."""
    if db is None:
        return
    batches = db.config.get("_active_probe_batches", {})
    if not batches:
        return
    for batch_id, info in list(batches.items()):
        remaining = info.get("remaining") or []
        if not remaining:
            _clear_probe_batch(batch_id)
            continue
        
        threading.Thread(
            target=_probe_and_patch_durations,
            args=(info.get("ch"), info.get("container"), info.get("sub"), remaining),
            kwargs={"_resume_batch_id": batch_id},
            daemon=True,
        ).start()


