def _fe_remove_selected_from_queue():
    items      = app_state.get("file_explorer_items", [])
    sel        = app_state.get("file_explorer_selection", set())
    checked    = app_state.get("file_explorer_checked", [])
    valid_exts = app_state.get("file_explorer_exts", set())
    context    = app_state.get("file_explorer_context", {})
    locked_path = _fe_locked_playing_path(context)
    to_remove  = set()
    dirs_to_expand = []
    _blocked_live = False
    for idx in sorted(sel):
        if not (0 <= idx < len(items)):
            continue
        item = items[idx]
        p    = item["path"]
        if item["type"] == "dir":
            dirs_to_expand.append(p)
        elif item["type"] == "file":
            np_ = os.path.normpath(p)
            if locked_path and np_ == locked_path:
                _blocked_live = True
                continue
            to_remove.add(np_)
    if _blocked_live:
        print(f"[FILE EXPLORER] Skipped removing {os.path.basename(locked_path)} -- "
              f"it's currently playing live on this channel.")
    app_state["file_explorer_checked"]  = [f for f in checked if f not in to_remove]
    app_state["file_explorer_selection"] = set()
    if dirs_to_expand:
        app_state["file_explorer_expand_request_id"] += 1
        req_id = app_state["file_explorer_expand_request_id"]
        session_id = app_state.get("file_explorer_session_id", 0)
        if app_state.get("file_explorer_expand_pending", 0) == 0:
            app_state["file_explorer_expand_started_ms"] = pygame.time.get_ticks()
        app_state["file_explorer_expand_pending"] += 1
        threading.Thread(
            target=_fe_expand_worker,
            args=(req_id, "remove", dirs_to_expand, valid_exts, session_id),
            daemon=True,
        ).start()


def _fe_apply_bios_selection(ck, checked):
    """Copies the picked BIOS file into the console's own BIOS folder (unless it is already there) and remembers that file as the console's active BIOS."""
    if not (ck and checked):
        return
    picked = os.path.abspath(_copy_tool_for_console(os.path.abspath(checked[0]), ck, True))
    db.config.setdefault("active_bios", {})[ck] = picked
    db.save_settings_async()
    print(f"[GAMES] Active BIOS for {ck} is: {picked}")
    if game_deck is not None:
        game_deck.refresh_from_config(db.config)


_BIOS_KNOWN_PRIORITY = [
    "scph5501",
    "scph7001",
    "scph1001",
    "scph5502",
    "scph7002",
    "scph1002",
    "scph5500",
    "scph7000",
    "scph1000",
]


def _bios_region_rank(fname):
    """Ranks a BIOS filename 0=USA, 1=PAL, 2=Japan, 3=unrecognized, for files not in _BIOS_KNOWN_PRIORITY."""
    lower = fname.lower()
    if "usa" in lower or "ntsc-u" in lower or "(u)" in lower:
        return 0
    if "pal" in lower or "europe" in lower or "(e)" in lower:
        return 1
    if "japan" in lower or "ntsc-j" in lower or "(j)" in lower:
        return 2
    base = re.sub(r"[^a-z0-9]", "", os.path.splitext(lower)[0])
    if base == "scph7003":
        return 0
    m = re.fullmatch(r"scph(\d{3,4})", base)
    if m:
        last_digit = m.group(1)[-1]
        if last_digit == "1":
            return 0
        if last_digit == "2":
            return 1
        if last_digit == "0":
            return 2
    return 3


def _bios_priority_key(fname):
    """Sort key for auto-picking the best BIOS file available in a folder -- lower sorts first / wins."""
    base = re.sub(r"[^a-z0-9]", "", os.path.splitext(fname.lower())[0])
    if base in _BIOS_KNOWN_PRIORITY:
        return (0, _BIOS_KNOWN_PRIORITY.index(base), base)
    return (1, _bios_region_rank(fname), base)


def _read_emulator_config():
    """Reads emulator_config.json, or {} when it is missing or unreadable."""
    import json as _json
    from game_deck import resolve_emulator_config_path
    try:
        with open(resolve_emulator_config_path(), "r", encoding="utf-8") as fp:
            return _json.load(fp)
    except FileNotFoundError:
        return {}
    except Exception as _swallowed_error:
        _log_swallowed("_read_emulator_config: open emulator_config.json", _swallowed_error)
        return {}


def _write_emulator_config(cfg):
    """Writes emulator_config.json and has the game deck reload it."""
    import json as _json
    from game_deck import resolve_emulator_config_path
    cfg_path = resolve_emulator_config_path()
    try:
        os.makedirs(os.path.dirname(cfg_path), exist_ok=True)
        with open(cfg_path, "w", encoding="utf-8") as fp:
            _json.dump(cfg, fp, indent=2)
    except Exception as e:
        log.warning(f"[GAMES] Could not save {cfg_path}: {e}")
        return False
    if game_deck is not None and hasattr(game_deck, "reload_emulator_config"):
        game_deck.reload_emulator_config()
    return True


def _fe_active_core_path(console_key):
    """The core file this console actually plays with right now, wherever it sits, else None."""
    from game_deck import resolve_active_core_path
    return resolve_active_core_path(console_key, _read_emulator_config().get(console_key),
                                    os.path.join(resolve_main_dir(), "cores"))


def _fe_active_bios_path(console_key):
    """The BIOS file this console actually boots with right now, wherever it sits, else None."""
    from game_deck import resolve_active_bios_path
    saved = db.config.get("active_bios", {}).get(console_key, "") if db is not None else ""
    return resolve_active_bios_path(console_key, saved, base_dir)


def _tool_copy_paths():
    """The core and BIOS files the app itself copied into main/cores; Clear Cores, Clear BIOS and Reset All Settings delete these files and nothing else."""
    if db is None:
        return []
    cores_dir = os.path.normcase(os.path.abspath(os.path.join(resolve_main_dir(), "cores")))
    return [str(p) for p in (db.config.get("old_tool_copies", []) or [])
            if p and os.path.normcase(os.path.abspath(str(p))).startswith(cores_dir + os.sep)]


def _tool_copy_is_bios(path):
    """True for a copy in a console's system folder (a BIOS file), False for a core .dll in the console's own folder."""
    return os.path.basename(os.path.dirname(str(path))).lower() == "system"


def _record_tool_copies(paths):
    """Remembers files the app has just copied into main/cores, so the clear buttons and Reset All Settings can delete them again."""
    if db is None or not paths:
        return
    known = list(db.config.get("old_tool_copies", []) or [])
    seen = {os.path.normcase(os.path.abspath(str(p))) for p in known}
    for p in paths:
        key = os.path.normcase(os.path.abspath(str(p)))
        if key not in seen:
            seen.add(key)
            known.append(os.path.abspath(str(p)))
    db.config["old_tool_copies"] = known
    db.save_settings_async()


def _copy_tool_for_console(source, console_key, want_bios):
    """Puts a picked core (main/cores/<console>) or BIOS file (main/cores/<console>/system) into the console's own folder and remembers the copy; returns the path to remember. A file already in that folder is not copied, so picking another file there just switches the live one; when the copy fails the file is remembered where it sits."""
    from game_deck import copy_tool_into, get_bios_dir_for_console
    dest_dir = get_bios_dir_for_console(base_dir, console_key) if want_bios else os.path.join(resolve_main_dir(), "cores", console_key)
    if not dest_dir:
        return os.path.abspath(str(source))
    try:
        kept, made = copy_tool_into(source, dest_dir)
    except OSError as e:
        log.warning(f"[GAMES] {console_key}: could not copy {source} into {dest_dir} ({e}); it is remembered where it sits")
        return os.path.abspath(str(source))
    if made:
        _record_tool_copies([kept])
        print(f"[GAMES] {console_key}: copied {os.path.basename(kept)} into {os.path.dirname(kept)}")
    return kept


def _delete_tool_copies(want_bios):
    """Deletes the app's own copies of BIOS files (want_bios) or of cores, only files inside main/cores; returns (deleted, could not delete). A copy that cannot be deleted, a core still loaded, stays on the list."""
    import stat
    if db is None:
        return 0, 0
    cores_dir = os.path.normcase(os.path.abspath(os.path.join(resolve_main_dir(), "cores")))
    keep, deleted, failed = [], 0, 0
    for p in list(db.config.get("old_tool_copies", []) or []):
        ap = os.path.abspath(str(p))
        if _tool_copy_is_bios(ap) != bool(want_bios) or not os.path.normcase(ap).startswith(cores_dir + os.sep):
            keep.append(p)
            continue
        if not os.path.isfile(ap):
            continue
        try:
            os.chmod(ap, stat.S_IREAD | stat.S_IWRITE)
            os.remove(ap)
            deleted += 1
        except OSError as e:
            failed += 1
            keep.append(p)
            log.warning(f"[GAMES] could not delete {ap}: {e}")
    db.config["old_tool_copies"] = keep
    return deleted, failed


def _old_tool_copies_on_disk(cores_root):
    """Every core .dll in main/cores/<console> and every file in main/cores/<console>/system: the copies older versions made."""
    found = []
    try:
        consoles = sorted(os.listdir(cores_root)) if os.path.isdir(cores_root) else []
    except OSError as e:
        log.warning(f"[GAMES] Could not list {cores_root}: {e}")
        return found
    for console in consoles:
        folder = os.path.join(cores_root, console)
        for sub, keep in ((folder, lambda f: f.lower().endswith(".dll")), (os.path.join(folder, "system"), lambda f: True)):
            try:
                names = sorted(os.listdir(sub)) if os.path.isdir(sub) else []
            except OSError as e:
                log.warning(f"[GAMES] Could not list {sub}: {e}")
                continue
            found.extend(os.path.abspath(os.path.join(sub, n)) for n in names if keep(n) and os.path.isfile(os.path.join(sub, n)))
    return found


def _remember_old_core_and_bios_copies():
    """One time only: remembers, by full path, the cores and BIOS files earlier versions copied into main/cores, so they keep working now that nothing is copied, and lists them for Reset All Settings to delete."""
    if db is None or db.config.get("remembered_tools_v1"):
        return
    if getattr(db, "config_was_missing", False):
        # WARNING: a fresh start (first install or after Reset All Settings) has no old copies; files found in main/cores then were put there by hand and must be added again, never picked up here.
        db.config["remembered_tools_v1"] = True
        db.config["old_tool_copies"] = []
        db.save_settings()
        return
    from game_deck import (CONSOLE_ORDER, BIOS_REQUIRED_CONSOLES, is_console_core_key,
                           resolve_active_core_path, resolve_active_bios_path,
                           resolve_preferred_core_filename, get_bios_dir_for_console)
    cores_root = os.path.join(resolve_main_dir(), "cores")
    db.config["old_tool_copies"] = _old_tool_copies_on_disk(cores_root)
    cfg = _read_emulator_config()
    cfg_changed = False
    for console in CONSOLE_ORDER:
        if not is_console_core_key(console):
            continue
        path = resolve_active_core_path(console, cfg.get(console), cores_root)
        if path is None:
            folder = os.path.join(cores_root, console)
            try:
                dlls = [f for f in os.listdir(folder) if f.lower().endswith(".dll")]
            except OSError:
                dlls = []
            best = resolve_preferred_core_filename(console, dlls)
            path = os.path.join(folder, best) if best else None
        if path and cfg.get(console) != os.path.abspath(path):
            cfg[console] = os.path.abspath(path)
            cfg_changed = True
            print(f"[GAMES] {console}: remembered core {cfg[console]}")
    if cfg_changed:
        _write_emulator_config(cfg)
    active_bios = db.config.setdefault("active_bios", {})
    for console in BIOS_REQUIRED_CONSOLES:
        path = resolve_active_bios_path(console, active_bios.get(console), base_dir)
        if path is None:
            folder = get_bios_dir_for_console(base_dir, console)
            try:
                files = [f for f in os.listdir(folder) if os.path.isfile(os.path.join(folder, f))]
            except (OSError, TypeError):
                files = []
            path = os.path.join(folder, min(files, key=_bios_priority_key)) if files else None
        if path:
            active_bios[console] = os.path.abspath(path)
            print(f"[GAMES] {console}: remembered BIOS {active_bios[console]}")
    db.config["remembered_tools_v1"] = True
    db.save_settings()


def _drop_media_from_pool(ch_key, sub_key, norm_p, reason, container_key=None):
    containers = [container_key] if container_key else ["schedules", "holiday_schedules"]
    for _ck in containers:
        entries = db.channels_db.get(ch_key, {}).get(_ck, {}).get(sub_key, [])
        if not entries:
            continue
        kept = [e for e in entries
                if not (isinstance(e, dict)
                        and os.path.normpath(e.get("path", e.get("file", ""))) == norm_p)]
        if len(kept) == len(entries):
            continue
        db.channels_db[ch_key][_ck][sub_key] = kept
        log.warning("[SCHEDULE] ch%s %s %s: removed %s from the schedule: %s", ch_key, _ck, sub_key, os.path.basename(norm_p), reason)
        return True
    return False


def _drop_pair_from_pool(ch_key, sub_key, norm_p1, norm_p2, reason, container_key=None):
    """Same removal as _drop_media_from_pool, for a two-file paired entry (matched on both pair paths)."""
    containers = [container_key] if container_key else ["schedules", "holiday_schedules"]
    for _ck in containers:
        entries = db.channels_db.get(ch_key, {}).get(_ck, {}).get(sub_key, [])
        if not entries:
            continue
        kept = [e for e in entries
                if not (isinstance(e, dict) and e.get("is_pair")
                        and os.path.normpath(e.get("pair_ep1_path", "")) == norm_p1
                        and os.path.normpath(e.get("pair_ep2_path", "")) == norm_p2)]
        if len(kept) == len(entries):
            continue
        db.channels_db[ch_key][_ck][sub_key] = kept
        log.warning("[SCHEDULE] ch%s %s %s: removed the pair %s + %s from the schedule: %s", ch_key, _ck, sub_key, os.path.basename(norm_p1), os.path.basename(norm_p2), reason)
        return True
    return False


def _probe_and_patch_durations(ch_key, container_key, sub_key, items_pool, _resume_batch_id=None):
    import time as _time
    if _channel_is_server_streamed(ch_key):
        return
    initialize_vlc_on_demand()
    pygame.time.wait(300)
    save_counter = 0
    pool_size = len(items_pool)
    batch_size = 5 if pool_size < 50 else 25
    COMMERCIAL_MAX_SECONDS = media.COMMERCIAL_MAX_SECONDS
    _is_commercial_block = (container_key == "schedules" and sub_key == "Commercials")
    _removed_long_commercials = 0
    _removed_silent_commercials = 0
    _removed_unplayable = 0
    batch_id = _resume_batch_id or f"{ch_key}:{container_key}:{sub_key}:{_time.time()}"
    _register_probe_batch(batch_id, ch_key, container_key, sub_key, items_pool)
    try:
        for i, item_path in enumerate(items_pool):
            norm_p = os.path.normpath(item_path)
            if _get_probe_library().file_changed_on_disk(norm_p):
                log.info(
                    "[DURATION PROVENANCE] %s changed on disk since it was last "
                    "measured -- the hubs forgot its saved numbers and it is "
                    "re-probed", os.path.basename(norm_p),
                )
                _hub_forget_path(norm_p)
            _cached = _read_file_probe_facts(norm_p)
            probed = _cached.get("duration")
            probed_gain = _cached.get("gain")
            # WARNING: this check of newly saved commercial and holiday files is scan work like any other: it waits while the background scans are paused and takes a shared scan thread in the commercial class, so the scan turns can put it ahead of far-off work (audit stage 2, 2026-11-02).
            while _background_scan_should_pause():
                if _app_shutting_down.wait(DURATION_PRECACHE_PAUSE_RECHECK_SECONDS):
                    return
            with _scan_thread_slot("commercial_check", SCAN_CLASS_COMMERCIAL) as _slot_ok:
                if not _slot_ok:
                    return
                if probed is None:
                    try:
                        probed = _probe_duration_guarded(norm_p)
                    except Exception as _swallowed_error:
                        _log_swallowed("_probe_and_patch_durations: probed = _probe_duration_guarded(norm_p)", _swallowed_error)
                        probed = None
                if probed_gain is None:
                    try:
                        if _is_drive_degraded(norm_p):
                            raise LoudnessProbeTimeoutError(norm_p)
                        probed_gain = _probe_loudness_guarded(
                            norm_p, raise_on_no_audio=True,
                            treat_fallback_as_unknown=True,
                            raise_on_unplayable=True)
                    except NoAudioStreamError as _naerr:
                        _drop_media_from_pool(ch_key, sub_key, norm_p,
                                               getattr(_naerr, "reason", "no audio track"),
                                               container_key=container_key)
                        _removed_silent_commercials += 1
                        _save_file_probe_facts(norm_p, duration=probed)
                        _update_probe_batch_progress(batch_id, items_pool[i + 1:])
                        continue
                    except UnplayableMediaError as _uerr:
                        _strikes = _register_unplayable_strike(norm_p, _uerr.reason)
                        _save_file_probe_facts(norm_p, duration=probed)
                        if _strikes >= UNPLAYABLE_STRIKE_THRESHOLD:
                            _drop_media_from_pool(ch_key, sub_key, norm_p,
                                                   f"confirmed unplayable ({_uerr.reason}, "
                                                   f"{_strikes} strikes)",
                                                   container_key=container_key)
                            _removed_unplayable += 1
                        _update_probe_batch_progress(batch_id, items_pool[i + 1:])
                        continue
                    except Exception as _swallowed_error:
                        _log_swallowed("_probe_and_patch_durations: if _is_drive_degraded(norm_p):", _swallowed_error)
                        probed_gain = None
            if _is_commercial_block and probed and probed > COMMERCIAL_MAX_SECONDS:
                if _drop_media_from_pool(ch_key, sub_key, norm_p,
                                          f"{int(probed)}s > {COMMERCIAL_MAX_SECONDS}s, too long to be a commercial",
                                          container_key=container_key):
                    _removed_long_commercials += 1
                _save_file_probe_facts(norm_p, duration=probed, gain=probed_gain)
                _update_probe_batch_progress(batch_id, items_pool[i + 1:])
                continue
            if (not probed or probed <= 0) and not probed_gain:
                _update_probe_batch_progress(batch_id, items_pool[i + 1:])
                continue
            _patch_probed_gain("channel", ch_key, sub_key, norm_p,
                                gain=probed_gain, duration=probed)
            save_counter += 1
            _update_probe_batch_progress(batch_id, items_pool[i + 1:])
            if save_counter % batch_size == 0:
                try: db.save_settings_async()
                except Exception as e: log.warning("Periodic settings save failed during duration probe for %s/%s: %s", container_key, sub_key, e)
            if i < 2:
                _time.sleep(0.05)
            elif i < 15:
                _time.sleep(0.2)
            else:
                _time.sleep(0.8 if pool_size > 100 else 0.4)
    finally:
        _scan_report_head("commercial_check")
        _clear_probe_batch(batch_id)
    try: db.save_settings_async()
    except Exception as e: log.warning("Final settings save failed after duration probe for %s/%s: %s", container_key, sub_key, e)
    _drop_summary = ""
    if _removed_long_commercials or _removed_silent_commercials or _removed_unplayable:
        _drop_summary = (f" (dropped {_removed_long_commercials} too-long, "
                          f"{_removed_silent_commercials} no-audio, "
                          f"{_removed_unplayable} unplayable)")
    print(f"[DURATION PROBE] {container_key}/{sub_key} for ch {ch_key} -> probed {save_counter}/{pool_size} file(s){_drop_summary}")


def _dedupe_incoming_files(existing_entries, incoming_paths):
    seen_names = {os.path.basename(e.get("path", "")) for e in existing_entries if isinstance(e, dict)}
    out = []
    for p in incoming_paths:
        name = os.path.basename(p)
        if name in seen_names:
            continue
        seen_names.add(name)
        out.append(p)
    return out


# ============================================================================
# SECTION: File explorer: close, bulk scan, events & rendering
# ============================================================================


def _fe_close(commit):
    """Close the explorer, committing queued files to their destination if commit=True."""
    if commit:
        media.listing_cache_invalidate()
        checked = app_state.get("file_explorer_checked", [])
        context = app_state.get("file_explorer_context", {})
        mode    = context.get("mode", "schedule")
        ch_key  = context.get("ch", "")
        block   = context.get("block", "")
        hkey    = context.get("hkey", "")
        if mode == "rom_folder_relocate":
            ck = context.get("console_key", "")
            picked = context.get("picked_rom_folder", "") or app_state.get("file_explorer_cwd", "")
            if ck and picked and os.path.isdir(picked):
                if game_deck is not None:
                    game_deck.console_rom_dir[ck] = picked
                db.config.setdefault("console_rom_dir", {})[ck] = picked
                db.save_settings_async()
                print(f"[GAMES] {ck} ROM folder relocated to: {picked}")
                if game_deck is not None:
                    game_deck.refresh_from_config(db.config)
        elif mode in ("schedule", "commercial", "holiday"):
            # WARNING: an empty checked list means remove everything and must still be committed.
            _locked_path = _fe_locked_playing_path(context)
            _final_checked = list(checked)
            if _locked_path and _locked_path not in _final_checked:
                # WARNING: never let a commit remove the file that is live right now.
                _final_checked.append(_locked_path)
                print(f"[FILE EXPLORER] Currently-playing file can't be removed "
                      f"while it's live -- keeping it scheduled: "
                      f"{os.path.basename(_locked_path)}")
            if mode == "schedule":
                explorer_queue.put({"ch": ch_key, "block": block, "files": _final_checked})
            elif mode == "commercial" and ch_key and block:
                ch_data  = db.channels_db.setdefault(ch_key, {})
                existing = ch_data.setdefault("schedules", {}).get(block, [])
                entries, new_paths, removed_n, dupe_n = _reconcile_schedule_entries(existing, _final_checked)
                ch_data["schedules"][block] = entries
                db.save_settings_async()
                print(f"[FILE EXPLORER] {block} -> {len(entries)} file(s) for ch {ch_key} "
                      f"(+{len(new_paths)} new, -{removed_n} removed"
                      + (f", {dupe_n} exact-name duplicate(s) skipped" if dupe_n else "") + ")")
                _note_scan_work_added()
                if new_paths:
                    _warm_new_file_lengths(new_paths)
                    threading.Thread(
                        target=_probe_and_patch_durations,
                        args=(ch_key, "schedules", block, list(new_paths)),
                        daemon=True
                    ).start()
                if str(app_state.get("current_channel", "")).zfill(2) == str(ch_key).zfill(2):
                    _plog = ch_data.setdefault("playback_log", {})
                    _plog["sched_block_key"] = ""
                    _set_saved_lineup(_plog, [], {}, groups=None)
            elif mode == "holiday" and ch_key and hkey:
                ch_data  = db.channels_db.setdefault(ch_key, {})
                existing = ch_data.setdefault("holiday_schedules", {}).get(hkey, [])
                entries, new_paths, removed_n, dupe_n = _reconcile_schedule_entries(existing, _final_checked)
                ch_data["holiday_schedules"][hkey] = entries
                db.save_settings_async()
                print(f"[FILE EXPLORER] Holiday {hkey} -> {len(entries)} file(s) for ch {ch_key} "
                      f"(+{len(new_paths)} new, -{removed_n} removed"
                      + (f", {dupe_n} exact-name duplicate(s) skipped" if dupe_n else "") + ")")
                _note_scan_work_added()
                if new_paths:
                    _warm_new_file_lengths(new_paths)
                    threading.Thread(
                        target=_probe_and_patch_durations,
                        args=(ch_key, "holiday_schedules", hkey, list(new_paths)),
                        daemon=True
                    ).start()
                if str(app_state.get("current_channel", "")).zfill(2) == str(ch_key).zfill(2):
                    _plog = ch_data.setdefault("playback_log", {})
                    _plog["sched_block_key"] = ""
                    _set_saved_lineup(_plog, [], {}, groups=None)
        elif mode == "scan_for_roms":
            picked = context.get("picked_rom_folder", "") or app_state.get("file_explorer_cwd", "")
            if not picked:
                pass
            elif not _is_drive_responsive(picked):
                print("[GAMES] Scan For Roms: drive not responding — try again once it's connected")
                app_state["_games_menu_flash_msg"] = "SCAN FOR ROMS: DRIVE NOT RESPONDING"
                app_state["_games_menu_flash_at"]  = pygame.time.get_ticks()
            elif os.path.isdir(picked) and game_deck is not None and hasattr(game_deck, "bulk_scan_for_roms"):
                app_state["file_explorer_bulkscan_pending"]    = True
                app_state["file_explorer_bulkscan_started_ms"] = pygame.time.get_ticks()
                with app_state["file_explorer_bulkscan_lock"]:
                    app_state["file_explorer_bulkscan_id"]        += 1
                    _bs_scan_id = app_state["file_explorer_bulkscan_id"]
                    app_state["file_explorer_bulkscan_cancel"]     = False
                    app_state["file_explorer_bulkscan_committing"] = False
                    app_state["file_explorer_bulkscan_result"]   = None
                    app_state["file_explorer_bulkscan_progress"] = (0, 0)
                threading.Thread(
                    target=_fe_bulkscan_worker,
                    args=(picked, _bs_scan_id),
                    daemon=True,
                ).start()
                # WARNING: return here; _fe_poll_bulkscan() finishes the close once the background scan reports back.
                return
        elif mode == "scan_for_cores":
            picked = context.get("picked_rom_folder", "") or app_state.get("file_explorer_cwd", "")
            if not picked:
                pass
            elif not _is_drive_responsive(picked):
                print("[GAMES] Scan For Cores: drive not responding — try again once it's connected")
                app_state["_games_menu_flash_msg"] = "SCAN FOR CORES: DRIVE NOT RESPONDING"
                app_state["_games_menu_flash_at"]  = pygame.time.get_ticks()
            elif os.path.isdir(picked) and game_deck is not None and hasattr(game_deck, "bulk_scan_for_cores"):
                results, unresponsive_roots = game_deck.bulk_scan_for_cores(picked)
                _scan_copies = list(getattr(game_deck, "last_scan_copies", []) or [])
                _record_tool_copies(_scan_copies)
                if hasattr(game_deck, "reload_emulator_config"):
                    game_deck.reload_emulator_config()
                total_found = sum(n for n, _set in results.values())
                if results:
                    per_console = ", ".join(
                        f"{ck}: {n}" + (" (now active)" if set_now else "")
                        for ck, (n, set_now) in sorted(results.items())
                    )
                    summary = (f"Scan For Cores: found {total_found} core(s) for "
                               f"{len(results)} console(s) ({per_console})")
                else:
                    summary = "Scan For Cores: no matching cores found"
                    app_state["_games_menu_flash_msg"] = "SCAN FOR CORES: NOTHING FOUND"
                    app_state["_games_menu_flash_at"]  = pygame.time.get_ticks()
                if _scan_copies:
                    summary += f"; copied {len(_scan_copies)} core file(s) into the consoles' own folders"
                if unresponsive_roots:
                    summary += ("; skipped unreadable drive(s): "
                                + ", ".join(r.rstrip("\\") for r in unresponsive_roots))
                print(f"[GAMES] {summary}")
        elif mode == "add_roms":
            ck = context.get("console_key", "")
            if ck and game_deck is not None:
                existing = list(game_deck.console_roms_manual.get(ck, []))
                existing_norm = {os.path.normpath(p) for p in existing if p}
                checked_norm = []
                seen = set()
                for p in checked:
                    np_ = os.path.normpath(p)
                    if np_ not in seen:
                        seen.add(np_)
                        checked_norm.append(np_)
                brand_new = [np_ for np_ in checked_norm if np_ not in existing_norm]
                n_new, n_dupe = (0, 0)
                if brand_new and hasattr(game_deck, "add_manual_roms"):
                    n_new, n_dupe = game_deck.add_manual_roms(ck, brand_new)
                final_list = [
                    p for p in game_deck.console_roms_manual.get(ck, [])
                    if os.path.normpath(p) in checked_norm
                ]
                removed_n = len(existing_norm - set(checked_norm))
                game_deck.console_roms_manual[ck] = final_list
                db.config.setdefault("console_roms_manual", {})[ck] = list(final_list)
                db.save_settings_async()
                _dupe_note = f", {n_dupe} duplicate(s) skipped" if n_dupe else ""
                print(f"[GAMES] {ck}: {len(final_list)} manually-added rom(s) total "
                      f"(+{n_new} new, -{removed_n} removed{_dupe_note})")
        elif mode == "ch03_menu_music":
            existing = db.config.get("ch03_menu_music", [])
            entries, new_paths, removed_n, dupe_n = _reconcile_schedule_entries(existing, checked)
            _default_dropped = False
            if new_paths and len(existing) == 1 and _ch03_entry_is_default_music(existing[0]):
                _without_default = [e for e in entries if not _ch03_entry_is_default_music(e)]
                if _without_default and len(_without_default) < len(entries):
                    entries = _without_default
                    _default_dropped = True
                    removed_n += 1
                    app_state["ch03_menu_music_idx"] = 0
                    if _ch03_entry_is_default_music(app_state.get("ch03_menu_music_track", "")):
                        _stop_ch03_menu_music()
            db.config["ch03_menu_music"] = entries
            db.save_settings_async()
            print(f"[GAMES] Menu music -> {len(entries)} track(s) total "
                  f"(+{len(new_paths)} new, -{removed_n} removed"
                  + (f", {dupe_n} exact-name duplicate(s) skipped" if dupe_n else "")
                  + (", default track dropped" if _default_dropped else "") + ")")
            if (app_state.get("current_channel") == "03"
                    and game_deck is not None
                    and getattr(game_deck, "mode", "BROWSE") == "BROWSE"
                    and not getattr(game_deck, "dvd_playback_active", False)):
                if not entries:
                    _stop_ch03_menu_music()
                else:
                    _start_ch03_menu_music()
        elif checked:
            if mode == "libretro_core":
                ck      = context.get("console_key", "")
                chosen  = checked[0] if checked else ""
                if chosen and ck:
                    cfg = _read_emulator_config()
                    cfg[ck] = os.path.abspath(_copy_tool_for_console(chosen, ck, False))
                    if _write_emulator_config(cfg):
                        print(f"[GAMES] Libretro core for {ck} set to: {cfg[ck]}")
            elif mode == "add_bios":
                _fe_apply_bios_selection(context.get("console_key", ""), checked)
            elif mode == "console_splash":
                ck     = context.get("console_key", "DVD")
                chosen = checked[0] if checked else ""
                if chosen:
                    dest = os.path.abspath(chosen)
                    if ck == "DVD":
                        db.config["dvd_splash_path"] = dest
                    else:
                        db.config.setdefault("console_splash_path", {})[ck] = dest
                    db.save_settings_async()
                    print(f"[GAMES] {ck} splash screen set to: {dest}")
                    if game_deck is not None:
                        game_deck.refresh_from_config(db.config)
            elif mode == "menu_bg":
                chosen = checked[0] if checked else ""
                if chosen:
                    dest = os.path.abspath(chosen)
                    db.config["menu_bg_path"] = dest
                    db.save_settings_async()
                    print(f"[GAMES] Menu background set to: {dest}")
                    if game_deck is not None:
                        game_deck.refresh_from_config(db.config)
            elif mode == "watermark_select":
                chosen = checked[0] if checked else ""
                if chosen:
                    _wm_channel = str(context.get("channel", app_state.get("current_channel", "05"))).zfill(2)
                    dest = os.path.abspath(chosen)
                    _wm_channel_info = db.channels_db.setdefault(_wm_channel, {})
                    _wm_channel_info["watermark_enabled"] = True
                    _wm_channel_info["watermark_path"] = dest
                    db.save_settings_async()
                    print(f"[WATERMARK] Channel {_wm_channel} watermark image set to: {dest}")
                    _watermark_cache["path"] = None
                    _watermark_cache["raw"] = None
                    _watermark_cache["surface"] = None

    _fe_finish_close()


def _fe_finish_close():
    """The tail end of _fe_close(): remember the last folder browsed and actually hide the picker."""
    _ck  = _fe_context_key(app_state.get("file_explorer_context", {}))
    _cwd = app_state.get("file_explorer_cwd")
    if _ck and _cwd and db is not None:
        db.config.setdefault("fe_last_cwd", {})[_ck] = _cwd
        db.save_settings_async()

    app_state["file_explorer_banner"]  = None
    app_state["file_explorer_active"]  = False
    app_state["file_explorer_checked"] = []
    app_state["file_explorer_done_requested"] = False
    app_state["file_explorer_items"]   = []
    pygame.mouse.set_visible(False)
    if app_state.get("show_menu", False):
        app_state["last_input_time"] = pygame.time.get_ticks()


def _fe_bulkscan_worker(picked_folder, scan_id):
    """Background thread body for the deferred scan_for_roms commit (see _fe_close)."""
    def _report_progress(done, total):
        with app_state["file_explorer_bulkscan_lock"]:
            app_state["file_explorer_bulkscan_progress"] = (done, total)

    def _cancelled():
        return app_state.get("file_explorer_bulkscan_cancel", False) or app_state.get("file_explorer_bulkscan_id", 0) != scan_id

    def _commit():
        with app_state["file_explorer_bulkscan_lock"]:
            if app_state.get("file_explorer_bulkscan_cancel", False) or app_state.get("file_explorer_bulkscan_id", 0) != scan_id:
                return False
            app_state["file_explorer_bulkscan_committing"] = True
            return True

    try:
        results, unresponsive_roots = game_deck.bulk_scan_for_roms(
            picked_folder, progress_cb=_report_progress, cancel_cb=_cancelled, commit_cb=_commit
        )
    except Exception as e:
        log.warning("bulk_scan_for_roms failed for %r: %s", picked_folder, e)
        results, unresponsive_roots = {}, []
    with app_state["file_explorer_bulkscan_lock"]:
        if app_state.get("file_explorer_bulkscan_id", 0) == scan_id:
            app_state["file_explorer_bulkscan_result"] = (results, unresponsive_roots)


def _fe_cancel_bulkscan():
    """Stops a Scan For Roms that is still looking; refused for that moment when it has already started adding ROMs."""
    with app_state["file_explorer_bulkscan_lock"]:
        if app_state.get("file_explorer_bulkscan_committing", False):
            return False
        app_state["file_explorer_bulkscan_cancel"] = True
    print("[GAMES] Scan For Roms: cancelled, no ROMs added")
    app_state["file_explorer_bulkscan_pending"] = False
    _fe_finish_close()
    return True


def _fe_poll_bulkscan():
    """Polled every frame while the file explorer is open (same as _fe_poll_scan/_fe_poll_expand)."""
    if not app_state.get("file_explorer_bulkscan_pending", False):
        return

    with app_state["file_explorer_bulkscan_lock"]:
        result = app_state["file_explorer_bulkscan_result"]
        if result is not None:
            app_state["file_explorer_bulkscan_result"] = None

    if result is None:
        started_ms = app_state.get("file_explorer_bulkscan_started_ms", 0)
        timeout_ms = app_state.get("file_explorer_bulkscan_timeout_ms", 120000)
        if started_ms and (pygame.time.get_ticks() - started_ms) > timeout_ms:
            log.warning("[GAMES] Scan For Roms: background scan timed out -- closing picker anyway")
            app_state["file_explorer_bulkscan_pending"] = False
            _fe_finish_close()
        return

    app_state["file_explorer_bulkscan_pending"] = False
    results, unresponsive_roots = result

    if results:
        db.config.setdefault("console_roms_manual", {})
        for ck in results:
            db.config["console_roms_manual"][ck] = list(
                game_deck.console_roms_manual.get(ck, [])
            )
        db.save_settings_async()
    total_added = sum(n for n, _s in results.values())
    if results:
        per_console = ", ".join(
            f"{ck}: +{n}" + (f" ({s} dup)" if s else "")
            for ck, (n, s) in sorted(results.items())
        )
        summary = (f"Scan For Roms: added {total_added} rom(s) across "
                   f"{len(results)} console(s) ({per_console})")
    else:
        summary = "Scan For Roms: no matching console folders/roms found"
        app_state["_games_menu_flash_msg"] = "SCAN FOR ROMS: NOTHING FOUND"
        app_state["_games_menu_flash_at"]  = pygame.time.get_ticks()
    if unresponsive_roots:
        summary += ("; skipped unreadable drive(s): "
                    + ", ".join(r.rstrip("\\") for r in unresponsive_roots))
    print(f"[GAMES] {summary}")

    _fe_finish_close()


def _fe_get_btn_rects(fx, fy, fw, fh):
    footer_y = fy + fh - _FE_FOOTER_H
    btn_y    = footer_y + _FE_FOOTER_H - _FE_BTN_H - 12
    widths   = [_FE_BTN_W_SM, _FE_BTN_W, _FE_BTN_W, _FE_BTN_W_SM]
    keys     = ["cancel", "remove_sel", "add_sel", "done"]
    total_w  = sum(widths)
    gap      = (fw - total_w) // (len(widths) + 1)
    x        = fx + gap
    rects    = []
    for w, key in zip(widths, keys):
        rects.append((pygame.Rect(x, btn_y, w, _FE_BTN_H), key))
        x += w + gap
    return rects


def _fe_scrollbar_thumb_rect(sb_x, items_y, items_h, n_items, visible, scroll):
    thumb_y, thumb_h = menu_nav.explorer_thumb(items_y, items_h, n_items, visible, scroll)
    return pygame.Rect(sb_x, thumb_y, menu_nav.EXPLORER_SB_WIDTH, thumb_h)


def _fe_handle_event(event):
    """Route a pygame event to the file explorer (mouse-driven, Windows-style)."""
    if event.type in (pygame.KEYDOWN, pygame.MOUSEBUTTONDOWN, pygame.MOUSEWHEEL):
        app_state["last_input_time"] = pygame.time.get_ticks()

    if app_state.get("file_explorer_bulkscan_pending", False):
        _bs_key_action = menu_nav.key_to_action(event.key) if event.type == pygame.KEYDOWN else None
        if _bs_key_action == menu_nav.BACK or (event.type == pygame.MOUSEBUTTONDOWN and getattr(event, "button", 1) == 3):
            _fe_cancel_bulkscan()
        return

    # WARNING: the file explorer is mouse driven; Escape is its only key, and going up a folder is the toolbar's up button.
    _fe_key_action = menu_nav.key_to_action(event.key) if event.type == pygame.KEYDOWN else None
    if _fe_key_action == menu_nav.BACK:
        if app_state.get("file_explorer_done_requested", False):
            return
        _fe_close(False)
        return

    fe_rect = app_state.get("file_explorer_rect")
    if not fe_rect:
        return
    fx, fy, fw, fh = fe_rect

    content_y  = fy + _FE_HEADER_H
    content_h  = fh - _FE_HEADER_H - _FE_FOOTER_H
    right_x    = fx + _FE_LEFT_W + 1
    right_w    = fw - _FE_LEFT_W - 1 - _FE_ADDLOC_PANEL_W - 1
    rp_x       = right_x + right_w + 1
    rp_w       = _FE_ADDLOC_PANEL_W
    items_y    = content_y + _FE_COL_H
    items_h    = content_h - _FE_COL_H
    footer_y   = fy + fh - _FE_FOOTER_H
    tb_y       = fy + _FE_TITLE_H

    left_rect   = pygame.Rect(fx, content_y, _FE_LEFT_W, content_h)
    items_rect  = pygame.Rect(right_x, items_y, right_w - 12, items_h)
    footer_rect = pygame.Rect(fx, footer_y, fw, _FE_FOOTER_H)
    up_rect     = pygame.Rect(fx + 6, tb_y + (_FE_TOOLBAR_H - _FE_UP_H) // 2, _FE_UP_W, _FE_UP_H)
    addloc_rect = _fe_get_addloc_rect(rp_x, rp_w, content_y, content_h)
    rows_top    = _fe_get_saved_rows_top(content_y)
    rp_rows_rect = pygame.Rect(rp_x, rows_top, rp_w, (content_y + content_h) - rows_top)

    items  = app_state.get("file_explorer_items", [])
    scroll = app_state.get("file_explorer_scroll", 0)
    sel    = app_state.get("file_explorer_selection", set())

    visible_rows = menu_nav.explorer_visible_rows(items_h, _FE_ROW_H)

    if event.type in (pygame.MOUSEBUTTONDOWN, pygame.MOUSEWHEEL) and app_state.get("file_explorer_expand_pending", 0) > 0:
        # WARNING: nothing in the explorer takes a click while the add bar is up; Done is usable only once the found files are counted and shown (owner 2026-11-02, N3).
        return

    if event.type == pygame.MOUSEBUTTONDOWN:
        mx, my = _real_to_virtual_pos(event.pos)
        btn = event.button
        app_state["last_input_time"] = pygame.time.get_ticks()

        _wheel_scroll = menu_nav.explorer_wheel_button(btn, scroll, len(items), visible_rows)
        if _wheel_scroll is not None:
            app_state["file_explorer_scroll"] = _wheel_scroll
            return
        if btn != 1:
            return

        if menu_nav.explorer_hit(up_rect, mx, my):
            _fe_go_up()
            return

        if menu_nav.explorer_hit(addloc_rect, mx, my):
            _fe_add_saved_location()
            return

        if menu_nav.explorer_hit(rp_rows_rect, mx, my):
            saved_locs = _fe_get_saved_locations()
            # WARNING: cast to int; Bezel scaling can make mouse coordinates floats.
            idx = menu_nav.explorer_row(my, rows_top, _FE_LEFT_ROW_H)
            if 0 <= idx < len(saved_locs):
                p = saved_locs[idx]
                if menu_nav.explorer_in_remove_zone(mx, rp_x + rp_w, _FE_LEFT_REMOVE_W):
                    _fe_remove_saved_location(p)
                else:
                    _fe_navigate(p)
            return

        if menu_nav.explorer_hit(left_rect, mx, my):
            rows1, rows2 = _fe_left_layout(content_h)
            pc_items     = _fe_get_this_pc_items()
            qa_items     = _fe_get_quick_access_items()
            sec1_items_y = content_y + _FE_LEFT_ROW_H
            sec1_items_h = rows1 * _FE_LEFT_ROW_H
            sec2_hdr_y   = sec1_items_y + sec1_items_h
            sec2_items_y = sec2_hdr_y + _FE_LEFT_ROW_H

            idx = menu_nav.explorer_list_pick(my, sec1_items_y, rows1, _FE_LEFT_ROW_H, len(pc_items), app_state.get("file_explorer_left_scroll_pc", 0))
            if idx is not None:
                if idx >= 0:
                    app_state["file_explorer_left_sel"] = pc_items[idx]["path"]
                    _fe_navigate(pc_items[idx]["path"])
                return
            idx = menu_nav.explorer_list_pick(my, sec2_items_y, rows2, _FE_LEFT_ROW_H, len(qa_items), app_state.get("file_explorer_left_scroll_qa", 0))
            if idx is not None:
                if idx >= 0:
                    app_state["file_explorer_left_sel"] = qa_items[idx]["path"]
                    _fe_navigate(qa_items[idx]["path"])
                return

        if menu_nav.explorer_hit(footer_rect, mx, my):
            key = menu_nav.explorer_button_at(_fe_get_btn_rects(fx, fy, fw, fh), mx, my)
            if key is not None:
                if key == "cancel":
                    _fe_close(False)
                elif key == "remove_sel":
                    _ctx = app_state.get("file_explorer_context", {})
                    if _ctx.get("mode") in ("rom_folder_relocate", "scan_for_roms", "scan_for_cores"):
                        _ctx.pop("picked_rom_folder", None)
                        _ctx.pop("picked_rom_count", None)
                        app_state["file_explorer_checked"] = []
                    else:
                        _fe_remove_selected_from_queue()
                elif key == "add_sel":
                    _ctx = app_state.get("file_explorer_context", {})
                    if _ctx.get("mode") == "rom_folder_relocate":
                        _fe_add_selected_rom_folder()
                    elif _ctx.get("mode") == "scan_for_roms":
                        _fe_add_selected_scan_folder()
                    elif _ctx.get("mode") == "scan_for_cores":
                        _fe_add_selected_scan_cores_folder()
                    else:
                        _fe_add_selected_to_queue()
                elif key == "done":
                    if (app_state.get("file_explorer_expand_pending", 0) <= 0
                            and not app_state.get("file_explorer_scan_pending", False)):
                        _fe_close(True)
                    else:
                        app_state["file_explorer_done_requested"] = True
                return

        sb_x = right_x + right_w - 10
        if menu_nav.explorer_hit(menu_nav.explorer_scrollbar_track(sb_x, items_y, items_h), mx, my):
            _new_scroll, _grab_offset = menu_nav.explorer_scrollbar_press(mx, my, sb_x, items_y, items_h, len(items), visible_rows, scroll)
            if _new_scroll is not None:
                app_state["file_explorer_scroll"] = _new_scroll
            app_state["file_explorer_sb_drag"] = _grab_offset
            return

        if menu_nav.explorer_hit(items_rect, mx, my):
            idx = menu_nav.explorer_row_at(my, items_rect.y, items_rect.bottom, _FE_ROW_H, scroll)
            shift, ctrl = menu_nav.explorer_modifiers(pygame.key.get_mods())
            app_state["file_explorer_selection"], app_state["file_explorer_sel_anchor"] = menu_nav.explorer_select(
                idx, len(items), sel, app_state.get("file_explorer_sel_anchor", 0), shift, ctrl)
            if not (0 <= idx < len(items)) and not (shift or ctrl) and items:
                # WARNING: a press on the empty space under the last file starts a drag from the last file, the row nearest the press; keeping the old anchor made a drag select from the top of the list (owner 2026-11-02, N9).
                app_state["file_explorer_sel_anchor"] = len(items) - 1
            if 0 <= idx < len(items):
                now = pygame.time.get_ticks()
                if menu_nav.explorer_double_click(now, app_state.get("file_explorer_last_click_ms", 0),
                                                  app_state.get("file_explorer_last_click_idx", -1), idx):
                    item = items[idx]
                    if item["type"] == "dir":
                        _fe_navigate(item["path"])
                        return
                app_state["file_explorer_last_click_ms"]  = now
                app_state["file_explorer_last_click_idx"] = idx

            app_state["file_explorer_drag_start"] = (mx, my)
            app_state["file_explorer_drag_cur"]   = (mx, my)

    elif event.type == pygame.MOUSEMOTION:
        _sb_grab = app_state.get("file_explorer_sb_drag")
        if event.buttons[0] and _sb_grab is not None:
            _mx, _my = _real_to_virtual_pos(event.pos)
            app_state["file_explorer_scroll"] = menu_nav.explorer_scrollbar_drag(
                _my, _sb_grab, items_y, items_h, len(items), visible_rows)
            return
        if event.buttons[0] and app_state.get("file_explorer_drag_start"):
            mx, my = _real_to_virtual_pos(event.pos)
            app_state["file_explorer_drag_cur"] = (mx, my)
            if menu_nav.explorer_drag_moved(app_state["file_explorer_drag_start"], mx, my):
                _last_t = app_state.get("_fe_drag_scroll_t", 0)
                _cur_sc, app_state["file_explorer_selection"], _drag_t = menu_nav.explorer_drag_step(
                    my, items_rect.y, items_rect.bottom, _FE_ROW_H, len(items), visible_rows,
                    app_state.get("file_explorer_scroll", 0), app_state.get("file_explorer_sel_anchor", 0),
                    _last_t, pygame.time.get_ticks())
                if _drag_t != _last_t:
                    app_state["file_explorer_scroll"] = _cur_sc
                    app_state["_fe_drag_scroll_t"]    = _drag_t

    elif event.type == pygame.MOUSEBUTTONUP and event.button == 1:
        app_state["file_explorer_drag_start"] = None
        app_state["file_explorer_drag_cur"]   = None
        app_state["file_explorer_sb_drag"]    = None

    elif event.type == pygame.MOUSEWHEEL:
        _wmx, _wmy = _real_to_virtual_pos(pygame.mouse.get_pos())
        if menu_nav.explorer_hit(left_rect, _wmx, _wmy):
            _rows1, _rows2 = _fe_left_layout(content_h)
            _n1 = len(_fe_get_this_pc_items())
            _n2 = len(_fe_get_quick_access_items())
            _sec1_items_y = content_y + _FE_LEFT_ROW_H
            _sec1_items_h = _rows1 * _FE_LEFT_ROW_H
            _sec2_items_y = _sec1_items_y + _sec1_items_h + _FE_LEFT_ROW_H
            _sec2_items_h = _rows2 * _FE_LEFT_ROW_H
            if menu_nav.explorer_in_band(_wmy, _sec1_items_y, _sec1_items_h):
                app_state["file_explorer_left_scroll_pc"] = menu_nav.explorer_wheel(
                    app_state.get("file_explorer_left_scroll_pc", 0), _n1, _rows1, event.y)
            elif menu_nav.explorer_in_band(_wmy, _sec2_items_y, _sec2_items_h):
                app_state["file_explorer_left_scroll_qa"] = menu_nav.explorer_wheel(
                    app_state.get("file_explorer_left_scroll_qa", 0), _n2, _rows2, event.y)
        else:
            app_state["file_explorer_scroll"] = menu_nav.explorer_wheel(scroll, len(items), visible_rows, event.y)


def _fe_render(screen, active_theme, fe_rect):
    """Render the Windows-style file explorer overlay."""
    import colorsys as _fecs
    fx, fy, fw, fh = fe_rect
    app_state["file_explorer_rect"] = fe_rect

    ui_hue   = db.config.get("theme_ui_hue", 140) / 360.0 if db else 0.39
    bg_hue   = db.config.get("theme_bg_hue", 220) / 360.0 if db else 0.61
    _r,_g,_b = _fecs.hsv_to_rgb(ui_hue, 0.88, 1.0)
    UI_C     = (int(_r*255), int(_g*255), int(_b*255))
    _r,_g,_b = _fecs.hsv_to_rgb(bg_hue, 0.55, 0.10)
    BG_C     = (int(_r*255), int(_g*255), int(_b*255))
    _r,_g,_b = _fecs.hsv_to_rgb(bg_hue, 0.45, 0.16)
    PANEL_C  = (int(_r*255), int(_g*255), int(_b*255))
    _r,_g,_b = _fecs.hsv_to_rgb(ui_hue, 0.65, 0.50)
    SEL_C    = (int(_r*255), int(_g*255), int(_b*255))
    _r,_g,_b = _fecs.hsv_to_rgb(bg_hue, 0.35, 0.14)
    ITEM_BG  = (int(_r*255), int(_g*255), int(_b*255))
    WHITE    = COLOR_TEXT_WHITE
    GREY     = COLOR_FE_TEXT_GREY
    ADDED_C  = UI_C
    LOCKED_C = COLOR_FE_LOCKED

    bg_alpha = min(255, int((db.config.get("menu_opacity", 50) / 100.0) * 255) + 90) if db else 235

    content_y = fy + _FE_HEADER_H
    content_h = fh - _FE_HEADER_H - _FE_FOOTER_H
    right_x   = fx + _FE_LEFT_W + 1
    right_w   = fw - _FE_LEFT_W - 1 - _FE_ADDLOC_PANEL_W - 1
    rp_x      = right_x + right_w + 1
    rp_w      = _FE_ADDLOC_PANEL_W
    items_y   = content_y + _FE_COL_H
    items_h   = content_h - _FE_COL_H
    footer_y  = fy + fh - _FE_FOOTER_H
    tb_y      = fy + _FE_TITLE_H
    visible   = max(1, items_h // _FE_ROW_H)

    items    = app_state.get("file_explorer_items", [])
    scroll   = app_state.get("file_explorer_scroll", 0)
    sel      = app_state.get("file_explorer_selection", set())
    checked  = app_state.get("file_explorer_checked", [])
    cwd      = app_state.get("file_explorer_cwd")
    title    = app_state.get("file_explorer_title", "FILE BROWSER")
    left_sel = app_state.get("file_explorer_left_sel", -1)
    drag_s   = app_state.get("file_explorer_drag_start")
    drag_c   = app_state.get("file_explorer_drag_cur")
    mx, my   = _real_to_virtual_pos(pygame.mouse.get_pos(), screen)

    bg = pygame.Surface((fw, fh), pygame.SRCALPHA)
    bg.fill(BG_C + (bg_alpha,))
    screen.blit(bg, (fx, fy))

    tb_surf = pygame.Surface((fw, _FE_TITLE_H), pygame.SRCALPHA)
    tb_surf.fill(UI_C + (80,))
    screen.blit(tb_surf, (fx, fy))
    f_title = _cached_sys_font("Courier New", 20, bold=True)
    t_lbl   = f_title.render(title, True, WHITE)
    screen.blit(t_lbl, (fx + 12, fy + (_FE_TITLE_H - t_lbl.get_height()) // 2))

    pygame.draw.rect(screen, COLOR_FE_BAR_BG, (fx, tb_y, fw, _FE_TOOLBAR_H))
    up_rect = pygame.Rect(fx + 6, tb_y + (_FE_TOOLBAR_H - _FE_UP_H) // 2, _FE_UP_W, _FE_UP_H)
    is_up   = up_rect.collidepoint(mx, my)
    pygame.draw.rect(screen, UI_C if is_up else COLOR_FE_UP_BUTTON, up_rect)
