    addloc_rect = _fe_get_addloc_rect(rp_x, rp_w, content_y, content_h)
    is_addloc_hov = addloc_rect.collidepoint(mx, my)
    addloc_bc = COLOR_FE_ADD_BUTTON_HOVER if is_addloc_hov else COLOR_FE_ADD_BUTTON
