_TRACK_FIELDS = ("audio_track_id", "audio_track_name", "audio_track_index")


def _get_saved_audio_track(filepath):
    """(VLC track id, VLC label) of the owner's chosen audio track for a file from its library row, or None when none is saved."""
    hub = _get_gain_hub()
    if hub is None or not filepath:
        return None
    fields = hub.read_file_fields(os.path.normpath(filepath), _TRACK_FIELDS) or {}
    if fields.get("audio_track_id") is None and not fields.get("audio_track_name"):
        return None
    return fields.get("audio_track_id"), fields.get("audio_track_name") or ""


def _save_audio_track_pref(filepath, track_id, track_name, track_index=None):
    """Remembers the owner's audio track for a file in its library row: VLC's track id and label, and its place among the file's audio tracks (0 = first) so the loudness scan measures the same track."""
    hub = _get_gain_hub()
    if hub is None or not filepath or not hub.note_file_fields(
            os.path.normpath(filepath), audio_track_id=track_id, audio_track_name=track_name,
            audio_track_index=None if track_index is None else int(track_index)):
        log.warning("[AUDIO TRACK] the library could not save the chosen track for %s, it is not remembered",
                    os.path.basename(str(filepath)))


_TRACK_NUMBER_RE = re.compile(r"^\s*Track\s+(\d+)\b", re.I)


def _scan_audio_track_for_file(filepath, streams):
    """Which audio stream (0 = first) the loudness scan should measure for a file: the owner's saved track, by its saved place or by the number in VLC's 'Track N' label; None when nothing is saved, so the scan uses the same English-first rule as playback."""
    hub = _get_gain_hub()
    if hub is None or not filepath:
        return None
    fields = hub.read_file_fields(os.path.normpath(filepath), _TRACK_FIELDS) or {}
    if fields.get("audio_track_index") is not None:
        return int(fields["audio_track_index"])
    match = _TRACK_NUMBER_RE.match(str(fields.get("audio_track_name") or ""))
    if match and streams and 1 <= int(match.group(1)) <= len(streams):
        return int(match.group(1)) - 1
    return None


media.set_audio_track_resolver(_scan_audio_track_for_file)


def _carry_config_file_data_into_hub():
    """Background, once per boot: moves per-file data an older version kept in the settings file (chosen audio tracks, loudness learning) into each file's library row and removes each entry from the settings file once its row holds it; an entry whose file the library cannot key yet (drive asleep, file gone) stays for the next boot."""
    if db is None:
        return
    hub = _get_gain_hub()
    if hub is None:
        return
    moved = kept = 0
    prefs = db.config.get("audio_track_prefs")
    if isinstance(prefs, dict) and prefs:
        left = {}
        for path, entry in list(prefs.items()):
            if isinstance(entry, dict) and hub.note_file_fields(
                    os.path.normpath(path), audio_track_id=entry.get("track_id"), audio_track_name=entry.get("track_name"),
                    audio_track_index=entry.get("audio_index")):
                moved += 1
            else:
                left[path] = entry
        kept += len(left)
        if left:
            db.config["audio_track_prefs"] = left
        else:
            db.config.pop("audio_track_prefs", None)
    learning = db.config.get("loudness_learning")
    if isinstance(learning, dict):
        per_file = {}
        for path, value in (learning.get("baselines") or {}).items():
            per_file.setdefault(path, {})["learn_baseline_db"] = float(value)
        for path, value in (learning.get("applied") or {}).items():
            per_file.setdefault(path, {})["learn_applied_db"] = float(value) if value else None
        for show_key, record in (learning.get("series") or {}).items():
            for path, change in ((record or {}).get("changes") or {}).items():
                if isinstance(change, dict) and change.get("delta_db"):
                    per_file.setdefault(path, {}).update(learn_series_key=show_key, learn_change_db=float(change["delta_db"]),
                                                         learn_change_at=float(change.get("at") or 0.0))
        left_paths = set()
        for path, fields in per_file.items():
            if hub.note_file_fields(os.path.normpath(path), **fields):
                moved += 1
            else:
                left_paths.add(path)
        kept += len(left_paths)
        if left_paths:
            db.config["loudness_learning"] = {
                "baselines": {p: v for p, v in (learning.get("baselines") or {}).items() if p in left_paths},
                "applied": {p: v for p, v in (learning.get("applied") or {}).items() if p in left_paths},
                "series": {k: {"changes": {p: c for p, c in ((r or {}).get("changes") or {}).items() if p in left_paths}}
                           for k, r in (learning.get("series") or {}).items()},
            }
        else:
            db.config.pop("loudness_learning", None)
    if moved or kept:
        log.info("[GAIN HUB] moved %d file record(s) of chosen tracks and loudness learning from the settings file into the library; %d wait for their files to be readable",
                 moved, kept)
        try:
            db.save_settings_async()
        except Exception as e:
            log.warning("[GAIN HUB] saving the settings file after the move into the library failed: %s", e)

_track_gain_memo = {}
_track_gain_memo_lock = threading.Lock()


def _store_track_gains(norm_path, primary, gains):
    """Keeps the scanned gain of every audio track of a file in the library and in memory, so switching tracks plays the new track at its own level."""
    record = {"primary": int(primary), "version": media.LOUDNESS_GAIN_SCAN_VERSION, "gains": {int(k): float(v) for k, v in gains.items()}}
    with _track_gain_memo_lock:
        _track_gain_memo[os.path.normpath(norm_path)] = record
    hub = _get_gain_hub()
    if hub is None or not hub.note_track_gains(norm_path, primary, gains, media.LOUDNESS_GAIN_SCAN_VERSION):
        log.warning("[GAIN HUB] the per-track gains of '%s' were not saved because the library could not hold them", os.path.basename(str(norm_path)))
        return
    log.info("[GAIN HUB] %s: gains for %d audio tracks saved (%s)", os.path.basename(str(norm_path)), len(record["gains"]),
             ", ".join("track %d %+.1f dB" % (k + 1, 20 * math.log10(v)) for k, v in sorted(record["gains"].items())))


media.set_track_gains_sink(_store_track_gains)


def _load_track_gains(norm_path):
    """Background: reads a file's per-track gains from the library into memory. Never call on the UI thread."""
    hub = _get_gain_hub()
    record = hub.read_track_gains(norm_path) if hub is not None else None
    with _track_gain_memo_lock:
        _track_gain_memo[os.path.normpath(norm_path)] = record
    return record


def _playing_track_gain(norm_path):
    """The scanned gain of the audio track playing now for the file on the main player, when that track is not the one the file's saved gain was measured on; None otherwise. Reads memory only."""
    engine = vlc_engine
    if engine is None or not norm_path:
        return None
    try:
        if os.path.normpath(getattr(engine, "current_filepath", "") or "") != norm_path:
            return None
    except Exception as e:
        _log_warn_throttled("playing_track_gain", "[AUDIO TRACK] reading the playing file to pick its track gain failed: %s" % e)
        return None
    index = getattr(engine, "_audio_index", None)
    if index is None:
        return None
    with _track_gain_memo_lock:
        record = _track_gain_memo.get(norm_path)
    if not record or record.get("version") != media.LOUDNESS_GAIN_SCAN_VERSION or index == record.get("primary"):
        return None
    gain = record.get("gains", {}).get(int(index))
    return float(gain) if gain and gain > 0 else None


def _get_manual_audio_gain_db(filepath):
    if db is None or not filepath:
        return 0
    value = None
    hub = _get_gain_hub()
    if hub is not None:
        try:
            value = hub.read(filepath)["manual_gain_db"]
        except Exception as _swallowed_error:
            _log_swallowed("_get_manual_audio_gain_db: reading the manual dB from the library", _swallowed_error)
    if value is None:
        value = 0
    try:
        return max(-12, min(12, int(round(float(value)))))
    except (TypeError, ValueError) as _swallowed_error:
        _log_swallowed("_get_manual_audio_gain_db: return max(-12, min(12, int(round(float(value)))))", _swallowed_error)
        return 0


def _get_audio_gain_db(filepath, ch_key=None):
    """Return the displayed total gain in whole dB: exactly the gain playback applies to this file, so the menu shows the number the file plays with."""
    if db is None or not filepath:
        return 0
    if ch_key is None:
        ch_key = app_state.get("audio_track_source_channel") or app_state.get("current_channel") or ""
    applied = _lookup_file_gain(ch_key, filepath)
    if not applied or applied <= 0:
        return 0
    return max(-12, min(12, int(round(20.0 * math.log10(applied)))))


def _save_audio_gain_db(filepath, total_db):
    """Saves the owner's chosen total gain in dB as the file's one gain in the library; a file the library cannot key saves nothing and a line in the log says so."""
    if db is None or not filepath:
        return
    value = max(-12, min(12, int(total_db)))
    hub = _get_gain_hub()
    norm_path = os.path.normpath(filepath)
    baseline_db = _owner_gain_baseline_db(norm_path, hub) if hub is not None else None
    if hub is not None and hub.note_owner_gain(filepath, value):
        _queue_owner_gain_learning(norm_path, baseline_db, value)
        return
    log.warning("[LIBRARY] the library could not save the owner's gain for %s, so the change was not kept", os.path.basename(str(filepath)))


_AUDIO_HEADER_STREAM_RE = re.compile(r"Stream #\d+:(\d+)(?:\[[^\]]*\])?(?:\(([^)]*)\))?[^\n]*?: Audio: ([^\n]*)")
_AUDIO_LABEL_LANGUAGE_RE = re.compile(r"\[([^\]]+)\]")
_audio_header_stream_cache = {}
_audio_header_stream_cache_lock = threading.Lock()


def _gov_audio_track_value(name, fallback):
    """One audio-track number or list from the governor table, or the fallback when the governor is missing."""
    if performance_governor is None:
        return fallback
    return getattr(performance_governor, name, fallback)


def _audio_header_streams(filepath):
    """The audio streams of the file on air in order as dicts (language code, description) read from ffmpeg's stream listing as priority work, cached per file; [] when it cannot be read. Never call on the UI thread."""
    if not filepath:
        return []
    try:
        _st = os.stat(filepath)
        key = (os.path.normpath(filepath), _st.st_size, _st.st_mtime_ns)
    except OSError as e:
        _log_warn_throttled("audio_header_stat", "[AUDIO TRACK] could not read %s to list its audio tracks: %s" % (os.path.basename(str(filepath)), e))
        return []
    with _audio_header_stream_cache_lock:
        hit = _audio_header_stream_cache.get(key)
    if hit is not None:
        return hit
    try:
        # WARNING: this lists the tracks of the file on air (the English-first pick and the Audio Track menu); as background work it waited up to 60 s at the gate while the wrong language played (L11), so it runs as priority work.
        if performance_governor is not None:
            with performance_governor.priority_scope():
                text, timed_out = media._dialogue_header_text(filepath)
        else:
            text, timed_out = media._dialogue_header_text(filepath)
    except Exception as e:
        log.warning("[AUDIO TRACK] reading the stream list of %s failed: %s", os.path.basename(filepath), e)
        return []
    if timed_out:
        log.warning("[AUDIO TRACK] reading the stream list of %s timed out", os.path.basename(filepath))
        return []
    streams = [{"lang": (m.group(2) or "").strip().lower(), "desc": m.group(3).strip()}
               for m in _AUDIO_HEADER_STREAM_RE.finditer(text or "")]
    with _audio_header_stream_cache_lock:
        if len(_audio_header_stream_cache) > 256:
            _audio_header_stream_cache.clear()
        _audio_header_stream_cache[key] = streams
    return streams


def _audio_language_is_preferred(text):
    """True when a track label or language code names one of the preferred languages (English first by default)."""
    if not text:
        return False
    preferred = [str(p).lower() for p in _gov_audio_track_value("AUDIO_TRACK_PREFERRED_LANGUAGES", ("english", "eng", "en"))]
    words = re.findall(r"[a-z]+", str(text).lower())
    return any(p in words for p in preferred)


def _vlc_track_language(label):
    """The language VLC names in a track label such as 'Track 2 - [English]', or ''."""
    match = _AUDIO_LABEL_LANGUAGE_RE.search(label or "")
    return match.group(1).strip() if match else ""


def _audio_track_rows(tracks, header_streams):
    """The picker rows as (track id, label): the track name exactly as VLC gives it ("Track 1", "Track 2 - [English]"), or "Track N" when VLC gives none; header_streams is not shown."""
    return [(tid, label or "Track %s" % tid) for tid, label in tracks]


def _pick_preferred_audio_track(tracks, header_streams, current_id):
    """(track id, why) of the track a file with no saved choice should play: the first track in the preferred language, judged by VLC's label or, when VLC names no language, by the file's own stream list in the same order; (None, why) when the playing track is already right or no track is in the preferred language."""
    if not tracks:
        return None, "no tracks listed"
    same_count = len(header_streams) == len(tracks)
    for index, (tid, label) in enumerate(tracks):
        lang = _vlc_track_language(label)
        if not lang and same_count:
            lang = header_streams[index].get("lang", "")
        if _audio_language_is_preferred(lang) or (not lang and _audio_language_is_preferred(label)):
            if tid == current_id:
                return None, "the playing track %s is already %s" % (tid, lang or label)
            return tid, "track %s is %s" % (tid, lang or label)
    return None, "no track in a preferred language"


def _refresh_audio_track_picker(filepath, started_at):
    """Background: re-reads the track list while the Audio Track menu is open for this file, so a track VLC lists late still appears; keeps the highlighted row on the same item and logs when the list changes."""
    refresh_s = float(_gov_audio_track_value("AUDIO_TRACK_PICKER_REFRESH_SECONDS", 15.0))
    interval_s = float(_gov_audio_track_value("AUDIO_TRACK_PICKER_REFRESH_INTERVAL_SECONDS", 0.5))
    try:
        header = _audio_header_streams(filepath)
        while time.monotonic() - started_at < refresh_s:
            if (app_state.get("menu_layer") != "AUDIO_TRACK_PICKER" or app_state.get("audio_track_context") != "channel"
                    or vlc_engine is None or getattr(vlc_engine, "current_filepath", None) != filepath):
                return
            rows = _audio_track_rows(vlc_engine.get_audio_tracks(), header)
            old = app_state.get("audio_track_list", [])
            if rows and rows != old:
                _row = app_state.get("sub_menu_row_index", 0)
                if _row >= len(old):
                    app_state["sub_menu_row_index"] = _row + (len(rows) - len(old))
                app_state["audio_track_list"] = rows
                log.info("[AUDIO TRACK] menu list for %s now %d track(s): %s",
                         os.path.basename(filepath), len(rows), "; ".join(label for _t, label in rows))
            if header and len(header) > len(rows):
                _log_warn_throttled("audio_track_missing_" + os.path.basename(filepath),
                                    "[AUDIO TRACK] %s has %d audio streams but VLC lists %d: %s" % (
                                        os.path.basename(filepath), len(header), len(rows),
                                        "; ".join("%s %s" % (h.get("lang") or "?", h.get("desc", "")[:30]) for h in header)))
            time.sleep(interval_s)
    except Exception as e:
        log.warning("[AUDIO TRACK] refreshing the menu's track list for %s failed: %s", os.path.basename(str(filepath)), e)


def _open_audio_track_picker(target_ch_str):
    is_live = str(app_state.get("current_channel", "")).zfill(2) == target_ch_str
    if not is_live or vlc_engine is None:
        print(f"[AUDIO TRACK] Channel {target_ch_str} isn't the one currently on screen -- "
              f"tune to it first, then use this option.")
        return

    tracks = vlc_engine.get_audio_tracks()
    if not tracks:
        print(f"[AUDIO TRACK] No audio track info available yet for channel {target_ch_str} "
              f"(the file may still be loading) -- try again in a moment.")
        return

    current_id = vlc_engine.get_current_audio_track()
    try:
        highlight = next(i for i, (tid, _n) in enumerate(tracks) if tid == current_id)
    except StopIteration:
        highlight = 0

    _picker_file = getattr(vlc_engine, "current_filepath", None)
    app_state["audio_track_list"] = tracks
    app_state["audio_track_source_channel"] = target_ch_str
    app_state["audio_track_active_id"] = current_id
    app_state["audio_track_gain_db"] = _get_audio_gain_db(_picker_file, target_ch_str)
    app_state["visualizer_gain_db"] = _get_audio_gain_db(app_state.get("_vis_target_filepath", ""), target_ch_str)
    app_state["audio_track_context"] = "channel"
    app_state["menu_layer"] = "AUDIO_TRACK_PICKER"
    app_state["sub_menu_row_index"] = highlight
    app_state["sub_menu_col_index"] = 0
    log.info("[AUDIO TRACK] menu opened for %s: VLC lists %d track(s): %s (playing %s)",
             os.path.basename(str(_picker_file)), len(tracks), "; ".join(label for _t, label in tracks), current_id)
    if _picker_file:
        threading.Thread(target=_refresh_audio_track_picker, args=(_picker_file, time.monotonic()),
                         daemon=True, name="AudioTrackMenuRefresh").start()


def _open_dvd_audio_track_picker():
    if dvd_engine is None:
        print("[AUDIO TRACK] DVD player isn't active -- nothing to list tracks for.")
        return

    tracks = dvd_engine.get_audio_tracks()
    if not tracks:
        print("[AUDIO TRACK] No audio track info available yet for the DVD player "
              "(the video may still be loading) -- try again in a moment.")
        return

    current_id = dvd_engine.get_current_audio_track()
    try:
        highlight = next(i for i, (tid, _n) in enumerate(tracks) if tid == current_id)
    except StopIteration:
        highlight = 0

    app_state["audio_track_list"] = tracks
    app_state.pop("audio_track_source_channel", None)
    app_state["audio_track_active_id"] = current_id
    app_state["audio_track_context"] = "dvd"
    app_state["menu_layer"] = "AUDIO_TRACK_PICKER"
    app_state["sub_menu_row_index"] = highlight
    app_state["sub_menu_col_index"] = 0


_VSNPRINTF_UNRESOLVED = object()
_vsnprintf_cache = _VSNPRINTF_UNRESOLVED


# ============================================================================
# SECTION: VLC logging, audio filters & stereo mode
# ============================================================================


def _get_vsnprintf_cached():
    global _vsnprintf_cache
    if _vsnprintf_cache is _VSNPRINTF_UNRESOLVED:
        _vsnprintf_cache = _resolve_vsnprintf()
    return _vsnprintf_cache


def _resolve_vsnprintf():
    import ctypes.util

    candidates = [
        (lambda: ctypes.cdll.ucrtbase, "vsnprintf"),
        (lambda: ctypes.cdll.msvcrt, "vsnprintf"),
        (lambda: ctypes.cdll.msvcrt, "_vsnprintf"),
        (lambda: ctypes.CDLL(ctypes.util.find_library("c") or "libc.so.6"), "vsnprintf"),
    ]
    misses = []
    for get_lib, name in candidates:
        try:
            lib = get_lib()
            fn = getattr(lib, name)
            fn.restype = ctypes.c_int
            fn.argtypes = [ctypes.c_char_p, ctypes.c_size_t, ctypes.c_char_p, ctypes.c_void_p]
            return fn
        except Exception as _miss_error:
            misses.append("%s: %s" % (name, _miss_error))
            continue
    _log_swallowed("native crash stack: resolving vsnprintf in a C library", RuntimeError("no candidate worked (%s)" % "; ".join(misses)))
    return None


_vlc_log_cb_refs = []

_VLC_LOG_LEVEL_NAMES = {0: "debug", 1: "notice", 2: "warning", 3: "error"}


def _make_vlc_log_callback(vlc_module):
    vsnprintf = _get_vsnprintf_cached()
    if vsnprintf is None:
        log.warning(
            "_make_vlc_log_callback: no usable vsnprintf found -- VLC log "
            "timestamping disabled for this session. initialize_vlc_on_demand "
            "should already have added a native --file-logging fallback (see "
            "its 'NATIVE --file-logging FALLBACK' comment) so vlc-debug.log "
            "still gets written, just without per-line timestamps.")
        return None

    LogCb = ctypes.CFUNCTYPE(
        None, ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p, ctypes.c_char_p, ctypes.c_void_p)

    _ctx_state = {"tried": False, "fn": None}

    def _resolve_get_ctx():
        """Finds libvlc_log_get_context in the VLC library itself, because python-vlc's wrapper for it takes fewer arguments than the C function."""
        dll = getattr(vlc_module, "dll", None)
        fn = getattr(dll, "libvlc_log_get_context", None) if dll is not None else None
        if fn is None:
            return None
        fn.restype = None
        fn.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_char_p), ctypes.POINTER(ctypes.c_char_p), ctypes.POINTER(ctypes.c_uint)]
        return fn

    def _callback(data, level, ctx, fmt, args):
        try:
            buf = ctypes.create_string_buffer(4096)
            n = vsnprintf(buf, 4096, fmt, args)
            if n < 0:
                return
            msg = buf.raw[:min(n, 4095)].decode("utf-8", errors="replace")

            module_name = "main"
            try:
                # WARNING: a failure here switches the module name off for the rest of the session and logs once; it must never repeat per VLC log line.
                if not _ctx_state["tried"]:
                    _ctx_state["tried"] = True
                    _ctx_state["fn"] = _resolve_get_ctx()
                get_ctx = _ctx_state["fn"]
                if get_ctx is not None:
                    mod_p = ctypes.c_char_p()
                    file_p = ctypes.c_char_p()
                    line_no = ctypes.c_uint()
                    get_ctx(ctx, ctypes.byref(mod_p), ctypes.byref(file_p), ctypes.byref(line_no))
                    if mod_p.value:
                        module_name = mod_p.value.decode("utf-8", errors="replace")
            except Exception as _ctx_error:
                _ctx_state["fn"] = None
                _log_swallowed("_make_vlc_log_callback._callback: get_ctx = getattr(vlc_module, 'libvlc_log_get_context', None)", _ctx_error)

            level_name = _VLC_LOG_LEVEL_NAMES.get(level, "debug")
            now = broadcast_clock.now().replace(tzinfo=None)
            line_text = "[{}.{:03d}] {} {}: {}".format(
                now.strftime("%H:%M:%S"), now.microsecond // 1000, module_name, level_name, msg)
            try:
                _vlc_log_queue.put_nowait(line_text)
            except queue.Full:
                pass
        except Exception as _swallowed_error:
            _log_swallowed("_make_vlc_log_callback._callback: buf = ctypes.create_string_buffer(4096)", _swallowed_error)

    _cb_ref = LogCb(_callback)
    _vlc_log_cb_refs.append(_cb_ref)
    return _cb_ref


_VLCEngineWrapperClass = None


def _compressor_filter_args():
    """The live dynamics compressor's libvlc args, from the current loudness_scan_enabled setting."""
    # WARNING: computed fresh on every call; never bake the result into a closure.
    if db is not None and db.config.get("loudness_scan_enabled", True):
        return [
            "--audio-filter=compressor",
            f"--compressor-attack={COMPRESSOR_ATTACK_MS}",
            f"--compressor-release={COMPRESSOR_RELEASE_MS}",
            f"--compressor-threshold={COMPRESSOR_THRESHOLD_DB}",
            f"--compressor-ratio={COMPRESSOR_RATIO}",
            f"--compressor-knee={COMPRESSOR_KNEE_DB}",
            f"--compressor-makeup-gain={COMPRESSOR_MAKEUP_DB}",
        ]
    return []


def _stereo_mode_args():
    """The Mono/Stereo toggle's libvlc args, from the current audio_stereo setting."""
    # WARNING: libvlc reads --stereo-mode only when vlc.Instance() is constructed, so a toggle flip must go through the engine rebuild.
    if db is not None and not db.config.get("audio_stereo", True):
        return ["--stereo-mode=mono"]
    return []


# WARNING: these must match the libvlc_audio_output_channel_t values.
_VLC_CHANNEL_STEREO = 1
_VLC_CHANNEL_MONO = 7
_last_stereo_reassert_mono = 0.0
# WARNING: the fallback numbers below must match STEREO_TOGGLE_MUTE_SECONDS in performance_governor.py; they are used only when that module fails to import.
_STEREO_TOGGLE_MUTE_SEC = performance_governor.STEREO_TOGGLE_MUTE_SECONDS if performance_governor is not None else 0.2


def _desired_vlc_channel():
    """Mono when the Mono/Stereo toggle says so, otherwise plain Stereo."""
    mono = db is not None and not db.config.get("audio_stereo", True)
    return _VLC_CHANNEL_MONO if mono else _VLC_CHANNEL_STEREO


def _apply_live_stereo_mode(reason="toggle"):
    """Switch the running VLC players between mono and stereo IN PLACE."""
    want = _desired_vlc_channel()
    label = "mono" if want == _VLC_CHANNEL_MONO else "stereo"
    changed = 0
    _muted_by_us = []
    if reason == "toggle":
        # WARNING: mute before the switch so the device close/reopen pop is never heard.
        for name, eng in (("main", vlc_engine), ("dvd", dvd_engine)):
            if eng is None or getattr(eng, "_closed", False):
                continue
            try:
                if eng.player.audio_get_mute() != 1:
                    eng.player.audio_set_mute(True)
                    _muted_by_us.append((name, eng))
            except Exception as _swallowed_error:
                _log_swallowed("_apply_live_stereo_mode: if eng.player.audio_get_mute() != 1:", _swallowed_error)
        if _muted_by_us:
            log.info("[SETTINGS] Stereo toggle: muted %s for %.2fs to hide audio-device restart",
                     "+".join(n for n, _ in _muted_by_us), _STEREO_TOGGLE_MUTE_SEC)
    for name, eng in (("main", vlc_engine), ("dvd", dvd_engine)):
        if eng is None or getattr(eng, "_closed", False):
            continue
        player = getattr(eng, "player", None)
        if player is None:
            continue
        try:
            cur = player.audio_get_channel()
        except Exception as _swallowed_error:
            _log_swallowed("_apply_live_stereo_mode: cur = player.audio_get_channel()", _swallowed_error)
            cur = None
        if reason != "toggle" and cur == want:
            continue
        # WARNING: VLC answers 0 (no mode set) for every new file, and its own default for 0 is the file's normal stereo; switching it to Stereo then restarts the sound output, which VLC fills with half a second of silence (N17, owner logs 2026-11-03: every "playing silence" followed this reassert). Only a real difference is switched.
        if reason != "toggle" and cur == 0 and want == _VLC_CHANNEL_STEREO:
            continue
        # WARNING: VLC has no audio output to switch until a file plays (audio_set_channel answers -1), so the reassert waits for playback instead of retrying every 2 s.
        if reason != "toggle" and not player.is_playing():
            continue
        try:
            rc = player.audio_set_channel(want)
        except Exception as e:
            log.warning("[SETTINGS] Live stereo-mode apply (%s engine) failed: %s", name, e)
            continue
        if rc == 0:
            changed += 1
        log.info("[SETTINGS] Live stereo-mode apply (%s engine, %s): channel=%s (%s) "
                 "was=%s rc=%s -- no engine rebuild, playback untouched",
                 name, reason, want, label, cur, rc)
    if _muted_by_us:
        def _unmute_after_toggle(_engines=list(_muted_by_us)):
            time.sleep(_STEREO_TOGGLE_MUTE_SEC)
            # WARNING: respect the user's Mute setting and an in-progress channel-switch mute; do not unmute over them.
            _user_muted = bool(db.config.get("is_muted", False)) if db is not None else False
            _switching = bool(app_state.get("_video_pending_unmute", False))
            for _n, _e in _engines:
                try:
                    if getattr(_e, "_closed", False):
                        continue
                    if _switching:
                        log.info("[SETTINGS] Stereo toggle: %s unmute skipped (channel switch owns mute)", _n)
                        continue
                    _e.player.audio_set_mute(_user_muted)
                    log.info("[SETTINGS] Stereo toggle: %s audio restored (muted=%s) after %.2fs",
                             _n, _user_muted, _STEREO_TOGGLE_MUTE_SEC)
                except Exception as _err:
                    log.warning("[SETTINGS] Stereo toggle unmute (%s) failed: %s", _n, _err)
        threading.Thread(target=_unmute_after_toggle, daemon=True,
                         name="stereo-toggle-unmute").start()
    return changed


def _reassert_live_stereo_mode_throttled():
    """Once-per-frame hook that re-applies the chosen channel mode to running players about every 2 s."""
    global _last_stereo_reassert_mono
    _t = time.monotonic()
    if _t - _last_stereo_reassert_mono < 2.0:
        return
    _last_stereo_reassert_mono = _t
    try:
        _apply_live_stereo_mode(reason="reassert")
    except Exception as _swallowed_error:
        _log_swallowed("_reassert_live_stereo_mode_throttled: _apply_live_stereo_mode(reason='reassert')", _swallowed_error)


DVD_FILE_HW_DECODE = True


def _main_video_hw_decode_allowed():
    """True when the main video engine asks VLC to decode each file on the graphics card (the governor's GPU rating decides)."""
    if performance_governor is None:
        return False
    try:
        return bool(performance_governor.vlc_hw_decode_allowed())
    except Exception as _hw_err:
        _log_warn_throttled("main_video_hw_decode", "[VIDEO DECODE] graphics card check failed, the CPU decodes: %s", _hw_err)
        return False


# ============================================================================
# SECTION: VLC engine initialization
# ============================================================================


def initialize_vlc_on_demand():
    global vlc_engine, dvd_engine, vlc_boot_requested, VLC_DEBUG_LOG_PATH
    if vlc_engine is None and not vlc_boot_requested:
        vlc_boot_requested = True
        print("VLC initialization triggered synchronously.")
        _vlc_start_t0 = time.perf_counter()
        try:
            import vlc
            _vlc_import_s = time.perf_counter() - _vlc_start_t0
            import ctypes
            
            try:
                _vlc_debug_log_path = os.path.join(_app_log_dir, "vlc-debug.log")
            except Exception:
                _vlc_debug_log_path = os.path.join(
                    _log_output_dir(), "vlc-debug.log")
            VLC_DEBUG_LOG_PATH = _vlc_debug_log_path
            _vlc_decoder_threads = 2
            try:
                if performance_governor is not None:
                    _vlc_decoder_threads = performance_governor.vlc_decoder_threads()
            except Exception as _vlc_thr_err:
                log.warning("[VLC] decoder thread count from the governor failed, using 2: %s", _vlc_thr_err)
            log.info("[VLC] --avcodec-threads=%d", _vlc_decoder_threads)
            vlc_args = [
                "--ignore-config",
                "--no-video-title-show",
                "--verbose=2",
                "--avcodec-hw=any",
                "--aout=directsound",
                "--file-caching=400",
                f"--avcodec-threads={_vlc_decoder_threads}",
                "--dvdnav-menu",
                "--clock-jitter=60000",
            ]

            if _get_vsnprintf_cached() is None:
                log.warning(
                    "initialize_vlc_on_demand: vsnprintf unavailable on this "
                    "machine -- falling back to native --file-logging for "
                    "vlc-debug.log (lines will be untimestamped). See the "
                    "NATIVE --file-logging FALLBACK comment for why.")
                _vlc_log_native_fallback_active = True
                vlc_args = vlc_args + [
                    "--extraintf=logger",
                    "--file-logging",
                    "--logfile=" + _vlc_debug_log_path,
                    "--log-verbose=2",
                ]
            else:
                _vlc_log_native_fallback_active = False

            global _vlc_base_args_main, _vlc_base_args_dvd
            _vlc_base_args_main = list(vlc_args)
            _vlc_base_args_dvd = [a for a in vlc_args if not a.startswith("--avcodec-hw")] + ["--avcodec-hw=none"]

            vlc_args = vlc_args + _compressor_filter_args() + _stereo_mode_args()
            vlc_args_dvd = _vlc_base_args_dvd + _compressor_filter_args() + _stereo_mode_args()

            class VLCEngineWrapper:
                def __init__(self, instance_args=None, engine_label="main"):
                    self.instance = vlc.Instance(*(instance_args if instance_args is not None else vlc_args))
                    self.player = self.instance.media_player_new()
                    self._vlc_debug_log_path = _vlc_debug_log_path
                    self.engine_label = engine_label

                    self._wedged = False
                    self._closed = False

                    _vlc_log_path_status = "unknown"
                    try:
                        _vlc_log_cb = _make_vlc_log_callback(vlc)
                        if _vlc_log_cb is not None:
                            self._vlc_log_cb_ref = _vlc_log_cb
                            self.instance.log_set(_vlc_log_cb, None)
                            _vlc_log_path_status = "callback (timestamped)"
                        elif _vlc_log_native_fallback_active:
                            _vlc_log_path_status = "native --file-logging (untimestamped)"
                        else:
                            _vlc_log_path_status = "UNAVAILABLE (no callback, no native fallback armed)"
                    except Exception as _e:
                        _vlc_log_path_status = f"FAILED ({_e})"
                        log.warning("VLCEngineWrapper.__init__: log_set failed: %s", _e)

                    _boot_marker = "[{}] main info: === {} engine boot: VLC log path = {} ===".format(
                        broadcast_clock.now().strftime("%H:%M:%S.%f")[:-3],
                        engine_label, _vlc_log_path_status)
                    try:
                        _vlc_log_queue.put_nowait(_boot_marker)
                    except queue.Full:
                        pass
                    log.info("VLCEngineWrapper.__init__ (%s): VLC log path = %s",
                             engine_label, _vlc_log_path_status)

                    _decode_res = db.config.get("vlc_decode_res", "sd") if db else "sd"
                    # WARNING: the DVD engine's target aspect is always 16:9; it never follows the main aspect_ratio.
                    if engine_label == "dvd":
                        self.target_aspect = "16:9"
                    else:
                        self.target_aspect = db.config.get("aspect_ratio", "16:9") if db else "16:9"
                    self.width, self.height = _video_decode_canvas_size(_decode_res)

                    self.buf_size = self.width * self.height * 4
                    self.raw_buffer = (ctypes.c_ubyte * self.buf_size)()
                    self.pixel_pointer = ctypes.cast(self.raw_buffer, ctypes.c_void_p).value
                    self._decode_buffer = None
                    self._decode_w, self._decode_h = self.width, self.height
                    self._letterbox_offset_x = 0
                    self._letterbox_offset_y = 0
                    self._dim_probe_cache = {}
                    self._dim_probe_inflight = set()
                    self._frame_ready = False
                    self._warmup_skip = 0
                    self.file_gain = 1.0
                    self._frame_lock = threading.Lock()
                    self.is_dvd_iso = False
                    self._dvd_src_dims = None

                    self._native_dims_pending = False
                    self._native_dims_deadline_ms = 0

                    self._current_title = -1
                    self._current_length = -1
                    self._seek_generation = 0
                    self._pending_seek_ms = 0
                    self._pending_seek_generation = None
                    self._pending_seek_at = 0.0
                    self._media_end_tracking = {}
                    self._state_cond = threading.Condition()
                    self._dvd_title_menu_flags = None


                    self._DVD_ACTIVATE_GRACE_MS = 75000
                    self._DVD_MENU_SIGNAL_WINDOW_MS = 4000
                    self._dvd_sig_last_active_tick = -10**9
                    self._dvd_sig_last_active_source = None
                    self._dvd_sig_ever_seen = False
                    self._dvd_title_entered_at = 0
                    self._dvd_menu_active_last_logged = None
                    self._dvd_menu_active_last_reason = None
                    self._dvd_sig_confirmed_title = None
                    self._dvd_sig_confirmed_title_source = None

                    self._DVD_VETO_OVERRIDE_COUNT = 3
                    self._DVD_VETO_OVERRIDE_WINDOW_MS = 4000
                    self._dvd_sig_veto_evidence = {}
                    self._dvd_flag_override_titles = set()

                    def _on_title_changed(event):
                        with self._state_cond:
                            try:
                                self._current_title = self.player.get_title()
                            except Exception as _swallowed_error:
                                _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.__init__._on_title_changed: self._current_title = self.player.get_title()", _swallowed_error)
                            self._state_cond.notify_all()
                        self._dvd_title_entered_at = pygame.time.get_ticks()

                    def _on_length_changed(event):
                        with self._state_cond:
                            try:
                                self._current_length = self.player.get_length()
                            except Exception as _swallowed_error:
                                _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.__init__._on_length_changed: self._current_length = self.player.get_length()", _swallowed_error)
                            self._state_cond.notify_all()

                    self._on_title_changed = _on_title_changed
                    self._on_length_changed = _on_length_changed
                    _em = self.player.event_manager()
                    _em.event_attach(vlc.EventType.MediaPlayerTitleChanged, self._on_title_changed)
                    _em.event_attach(vlc.EventType.MediaPlayerLengthChanged, self._on_length_changed)

                    self._current_chapter = -1

                    self._current_state = None

                    def _on_state_changed(event):
                        with self._state_cond:
                            try:
                                self._current_state = self.player.get_state()
                            except Exception as _swallowed_error:
                                _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.__init__._on_state_changed: self._current_state = self.player.get_state()", _swallowed_error)
                            self._state_cond.notify_all()

                    self._on_state_changed = _on_state_changed
                    for _evt in (vlc.EventType.MediaPlayerPlaying,
                                 vlc.EventType.MediaPlayerPaused,
                                 vlc.EventType.MediaPlayerEndReached,
                                 vlc.EventType.MediaPlayerEncounteredError,
                                 vlc.EventType.MediaPlayerStopped,
                                 vlc.EventType.MediaPlayerOpening):
                        _em.event_attach(_evt, self._on_state_changed)

                    self._lock_cb = vlc.CallbackDecorators.VideoLockCb(self._vid_lock_callback)
                    self._unlock_cb = vlc.CallbackDecorators.VideoUnlockCb(self._vid_unlock_callback)
                    self._display_cb = vlc.CallbackDecorators.VideoDisplayCb(self._vid_display_callback)
                        
                    self.player.video_set_callbacks(self._lock_cb, self._unlock_cb, self._display_cb, None)
                    self.player.video_set_format("BGRA", self.width, self.height, self.width * 4)

                    self.ready_flag = True

                def _vid_lock_callback(self, opaque, planes):
                    _lock_t0 = time.perf_counter()
                    self._frame_lock.acquire()
                    _lock_wait = time.perf_counter() - _lock_t0
                    # WARNING: only waits over 1 ms are counted; counting every picture would take a lock on VLC's picture thread for each frame.
                    if _lock_wait > 0.001 and health_monitor is not None:
                        health_monitor.note("VLC picture hand-off waits over 1 ms", _lock_wait)
                    planes[0] = self.pixel_pointer
                    return None

                def _vid_unlock_callback(self, opaque, picture, planes):
                    self._frame_lock.release()

                def _vid_display_callback(self, opaque, picture):
                    if self._warmup_skip > 0:
                        self._warmup_skip -= 1
                        return None
                    self._frame_ready = True

                    try:
                        if getattr(self, "is_dvd_iso", False):
                            now = pygame.time.get_ticks()
                            if now >= getattr(self, "_spu_diag_next_tick", 0):
                                self._spu_diag_next_tick = now + 400
                                buf = bytes(self.raw_buffer)
                                checksum = sum(buf[::997]) & 0xFFFFFFFF
                                hl_display = getattr(self, "_dvd_sig_highlight_display", None)
                                hl_button = getattr(self, "_dvd_sig_highlight_button", None)
                                prev_checksum = getattr(self, "_spu_diag_last_checksum", None)
                                prev_button = getattr(self, "_spu_diag_last_button", None)
                                if checksum != prev_checksum or hl_button != prev_button:
                                    log.info(
                                        "[DVD SPU DIAG] frame_checksum=%s prev_checksum=%s "
                                        "(%s) highlight_display=%s highlight_button=%s "
                                        "prev_button=%s blend_active=%s vout_opens=%s",
                                        checksum, prev_checksum,
                                        "CHANGED" if checksum != prev_checksum else "SAME",
                                        hl_display, hl_button, prev_button,
                                        getattr(self, "_dvd_sig_blend_active", None),
                                        getattr(self, "_dvd_sig_vout_open_count", 0),
                                    )
                                self._spu_diag_last_checksum = checksum
                                self._spu_diag_last_button = hl_button
                    except Exception as e:
                        log.warning("[DVD SPU DIAG] failed (non-fatal): %s", e)

                    return None

                def _set_crop_geometry(self, geometry):
                    try:
                        self.player.video_set_crop_geometry(geometry)
                    except Exception as _cg_err:
                        log.warning(f"[VLC] Could not set crop geometry ({geometry!r}): {_cg_err}")

                def _configured_screen_mode(self):
                    """Returns the screen-mode setting for this VLC pipeline."""
                    # WARNING: do not decide from is_dvd_iso alone; a plain video on the DVD engine must use dvd_screen_mode, not the global Video-tab mode.
                    _key = "dvd_screen_mode" if self.engine_label == "dvd" else "screen_mode"
                    return db.config.get(_key, "normal") if db is not None else "normal"

                def _configure_decode_target(self, target_w, target_h):
                    target_w = max(2, int(target_w))
                    target_h = max(2, int(target_h))
                    if target_w == self.width and target_h == self.height:
                        self._decode_buffer = None
                        self.pixel_pointer = ctypes.cast(self.raw_buffer, ctypes.c_void_p).value
                    else:
                        _buf_size = target_w * target_h * 4
                        self._decode_buffer = (ctypes.c_ubyte * _buf_size)()
                        self.pixel_pointer = ctypes.cast(self._decode_buffer, ctypes.c_void_p).value
                    self._decode_w, self._decode_h = target_w, target_h
                    try:
                        self.player.video_set_format("BGRA", target_w, target_h, target_w * 4)
                    except Exception as e:
                        log.warning("_configure_decode_target: video_set_format failed: %s", e)

                def _configure_letterbox_for_source(self, src_w, src_h):
                    canvas_w, canvas_h = self.width, self.height
                    if not src_w or not src_h or src_w <= 0 or src_h <= 0:
                        self._configure_decode_target(canvas_w, canvas_h)
                        self._letterbox_offset_x = 0
                        self._letterbox_offset_y = 0
                        return
                    src_ratio = src_w / float(src_h)
                    canvas_ratio = canvas_w / float(canvas_h)
                    if abs(src_ratio - canvas_ratio) < 0.01:
                        self._configure_decode_target(canvas_w, canvas_h)
                        self._letterbox_offset_x = 0
                        self._letterbox_offset_y = 0
                        return
                    if src_ratio > canvas_ratio:
                        fit_w = canvas_w
                        fit_h = int(round(canvas_w / src_ratio))
                    else:
                        fit_h = canvas_h
                        fit_w = int(round(canvas_h * src_ratio))
                    fit_w = max(2, fit_w - (fit_w % 2))
                    fit_h = max(2, fit_h - (fit_h % 2))
                    self._configure_decode_target(fit_w, fit_h)
                    self._letterbox_offset_x = (canvas_w - fit_w) // 2
                    self._letterbox_offset_y = (canvas_h - fit_h) // 2

                def _composite_letterboxed_frame(self):
                    # WARNING: the picture is copied with one call, never one call per row: every ctypes.memmove lets other threads run, and with background scans busy a row-by-row copy waited for its turn hundreds of times and stalled the picture for 200 to 600 ms (owner logs 2026-11-05).
                    try:
                        fit_w, fit_h = self._decode_w, self._decode_h
                        off_x, off_y = self._letterbox_offset_x, self._letterbox_offset_y
                        row_bytes = fit_w * 4
                        canvas_stride = self.width * 4
                        if off_x == 0 and fit_w == self.width:
                            src_base = ctypes.cast(self._decode_buffer, ctypes.c_void_p).value
                            dst_base = ctypes.cast(self.raw_buffer, ctypes.c_void_p).value
                            ctypes.memmove(dst_base + off_y * canvas_stride, src_base, row_bytes * fit_h)
                        else:
                            _src = np.frombuffer(self._decode_buffer, dtype=np.uint8, count=row_bytes * fit_h).reshape(fit_h, row_bytes)
                            _dst = np.frombuffer(self.raw_buffer, dtype=np.uint8).reshape(self.height, canvas_stride)
                            _dst[off_y:off_y + fit_h, off_x * 4:off_x * 4 + row_bytes] = _src
                    except Exception as e:
                        _log_warn_throttled("letterbox_composite_failed", "Letterbox frame compositing failed: %s", e)

                def _log_dvd_transition(self, tag):
                    pass

                def _dump_dvd_title_map(self, timeout_ms=8000):
                    import time as _tm
                    try:
                        import vlc
                    except Exception as _swallowed_error:
                        _log_swallowed("DVD debug: writing the title map", _swallowed_error)
                        return
                    deadline = pygame.time.get_ticks() + timeout_ms
                    while pygame.time.get_ticks() < deadline:
                        try:
                            if self.player.get_state() in (vlc.State.Playing,
                                                           vlc.State.Paused):
                                break
                        except Exception as _swallowed_error:
                            _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._dump_dvd_title_map: if self.player.get_state() in (vlc.State.Playing, vlc.State.Paused):", _swallowed_error)
                        _tm.sleep(0.05)
                    try:
                        descs = self.player.get_full_title_descriptions()
                        
                        for i, d in enumerate(descs or []):
                            pass
                    except Exception as e:
                        log.warning(f"[DVD TRACE] TITLE-MAP failed: {e!r}")
                    self._log_dvd_transition("OPEN")

                def _fill_full_canvas(self):
                    if self._decode_buffer is not None or (self._decode_w, self._decode_h) != (self.width, self.height):
                        self._configure_decode_target(self.width, self.height)
                        self._letterbox_offset_x = 0
                        self._letterbox_offset_y = 0

                def _apply_screen_mode_geometry(self, is_dvd_iso, src_dims=None):
                    """Applies the VLC-level crop/letterbox geometry for the current target_aspect and Screen Mode to an already-open player without reopening it."""
                    if is_dvd_iso:
                        if self.target_aspect == "4:3":
                            self._fill_full_canvas()
                            self._set_crop_geometry("4:3")
                            log.info("[SCREEN MODE GEOMETRY:%s] is_dvd_iso=True target_aspect=4:3 branch=dvd_crop_4:3 canvas=%sx%s", self.engine_label, self.width, self.height)
                        else:
                            self._set_crop_geometry(None)
                            _dvd_mode = self._configured_screen_mode()
                            if _dvd_mode in ("normal", "crop", "panscan") and src_dims:
                                self._configure_letterbox_for_source(*src_dims)
                                log.info("[SCREEN MODE GEOMETRY:%s] is_dvd_iso=True screen_mode='%s' branch=dvd_letterbox_for_source(%s,%s) canvas=%sx%s decode=%sx%s offset=(%s,%s)", self.engine_label, _dvd_mode, src_dims[0], src_dims[1], self.width, self.height, getattr(self, "_decode_w", None), getattr(self, "_decode_h", None), getattr(self, "_letterbox_offset_x", None), getattr(self, "_letterbox_offset_y", None))
                            else:
                                self._fill_full_canvas()
                                log.info("[SCREEN MODE GEOMETRY:%s] is_dvd_iso=True screen_mode='%s' branch=dvd_fill_full_canvas(src_dims=%s) canvas=%sx%s", self.engine_label, _dvd_mode, src_dims, self.width, self.height)
                        return

                    _screen_mode = self._configured_screen_mode()

                    self._set_crop_geometry(None)
                    if src_dims:
                        self._configure_letterbox_for_source(*src_dims)
                        self._native_dims_pending = False
                        log.info("[SCREEN MODE GEOMETRY:%s] screen_mode='%s' branch=letterbox_for_source(%s,%s) canvas=%sx%s decode=%sx%s offset=(%s,%s)", self.engine_label, _screen_mode, src_dims[0], src_dims[1], self.width, self.height, getattr(self, "_decode_w", None), getattr(self, "_decode_h", None), getattr(self, "_letterbox_offset_x", None), getattr(self, "_letterbox_offset_y", None))
                    else:
                        self._fill_full_canvas()
                        self._native_dims_pending = True
                        self._native_dims_deadline_ms = pygame.time.get_ticks() + 1500
                        log.info("[SCREEN MODE GEOMETRY:%s] screen_mode='%s' branch=letterbox_no_src_dims->fill_full_canvas canvas=%sx%s decode=%sx%s", self.engine_label, _screen_mode, self.width, self.height, getattr(self, "_decode_w", None), getattr(self, "_decode_h", None))

                def refresh_screen_mode_geometry(self):
                    """Re-applies Screen Mode's VLC-side crop/letterbox geometry to whatever is playing, keeping the position."""
                    try:
                        fp = getattr(self, "current_filepath", None)
                        if not fp:
                            log.info("[SCREEN MODE REFRESH:%s] skipped: no current_filepath (nothing open on this engine)", self.engine_label)
                            return
                        try:
                            import vlc as _vlc
                            _state = self.player.get_state()
                        except Exception as _swallowed_error:
                            _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.refresh_screen_mode_geometry: import vlc as _vlc", _swallowed_error)
                            _state = None
                            _vlc = None
                        if _vlc is not None and _state not in (_vlc.State.Playing, _vlc.State.Paused):
                            log.info("[SCREEN MODE REFRESH:%s] skipped: player state=%s (not Playing/Paused)", self.engine_label, _state)
                            return
                        _gen = getattr(self, "_seek_generation", None)
                        if (getattr(self, "_pending_seek_generation", None) == _gen
                                and getattr(self, "_pending_seek_ms", 0) > 0):
                            seek_seconds = self._pending_seek_ms / 1000.0
                            _stash_at = getattr(self, "_pending_seek_at", 0.0)
                            if _stash_at:
                                seek_seconds += max(0.0, time.monotonic() - _stash_at)
                        else:
                            try:
                                pos_ms = self.player.get_time()
                            except Exception as e:
                                log.warning("refresh_screen_mode_geometry: get_time() failed: %s", e)
                                pos_ms = -1
                            seek_seconds = (pos_ms / 1000.0) if pos_ms and pos_ms > 0 else 0
                        log.info("[SCREEN MODE REFRESH:%s] reopening %s at %.2fs to apply screen_mode='%s' (state=%s)", self.engine_label, fp, seek_seconds, self._configured_screen_mode(), _state)
                        self.play_file_segmented(fp, seek_seconds, gain=getattr(self, "file_gain", 1.0))
                        try:
                            import pygame as _pg
                            app_state["last_video_play_started_at"] = _pg.time.get_ticks()
                        except Exception as e:
                            log.warning("refresh_screen_mode_geometry: failed to stamp last_video_play_started_at: %s", e)
                    except Exception as e:
                        log.warning("refresh_screen_mode_geometry failed: %s", e)

                def play_file_segmented(self, filepath, seek_seconds, gain=1.0,
                                        defer_unmute=False, on_confirmed=None, follow_clock=False):
                    """Opens the file in this engine; on_confirmed, if given, is called once with (success, attempt_id, deferred) when VLC has accepted or failed the open; with follow_clock the time spent before the open is added to seek_seconds."""
                    _attempt_id = next(_playback_attempt_ids)
                    # WARNING: a load for a channel the viewer has left must not open its file or report back (owner log 2026-11-04 01:20:58: a ch10 load opened Snowpiercer and switched the app back to ch10 after the viewer had gone to ch11). Checked before anything here touches the player or its attempt number, so the show on air is left alone.
                    _act_token = _current_activation_token()

                    def _attempt_stale():
                        return _activation_token_stale(_act_token)

                    if _attempt_stale():
                        log.info("[ATTEMPT %s] not started: the channel on screen is no longer the one this load was for: %s",
                                 _attempt_id, os.path.basename(str(filepath)))
                        return _PLAYBACK_STALE
                    # WARNING: taken first, before the stop, the picture-box wait and the size probe, so _seek_at_open counts every second the open waited.
                    _requested_seek = seek_seconds
                    _requested_at = time.monotonic()
                    self._current_attempt_id = _attempt_id
                    self._current_attempt_file = filepath
                    # WARNING: set until this attempt has handed its file to VLC (or given up); the mid-stream check reads it, and without it a tune whose picture box takes more than 2 s opens the same file a second time.
                    self._open_inflight = (_attempt_id, time.monotonic())
                    _governor_note_event("play_file")

                    def _open_handed_over():
                        if getattr(self, "_open_inflight", (None,))[0] == _attempt_id:
                            self._open_inflight = None

                    def _confirm(success, deferred):
                        if _attempt_stale():
                            log.info("[ATTEMPT %s] result not used: the channel on screen is no longer the one this load was for: %s",
                                     _attempt_id, os.path.basename(str(filepath)))
                            # WARNING: a tune from the guide keeps the preview's file playing and takes this attempt as its own; that video is wanted on the channel now on screen and must not be stopped.
                            _taken_over = (app_state.get("is_playing_video", False)
                                           and app_state.get("_live_playback_channel") == str(app_state.get("current_channel", "")).zfill(2))
                            if success is True and getattr(self, "_current_attempt_id", None) == _attempt_id and not _taken_over:
                                try:
                                    self.stop(block=False)
                                except Exception as _stale_stop_err:
                                    log.warning("[ATTEMPT %s] stopping the out-of-date open failed: %s", _attempt_id, _stale_stop_err)
                            return
                        if on_confirmed is not None:
                            try:
                                on_confirmed(success, _attempt_id, deferred)
                            except Exception as e:
                                log.warning(
                                    "[ATTEMPT %s] play_file_segmented: on_confirmed callback raised: %s",
                                    _attempt_id, e,
                                )

                    log.info("[ATTEMPT %s] play_file_segmented: file=%s seek=%.2fs engine=%s",
                              _attempt_id, filepath, seek_seconds or 0.0, self.engine_label)
                    self._seek_generation = getattr(self, "_seek_generation", 0) + 1
                    self._pending_seek_ms = int(seek_seconds * 1000) if seek_seconds and seek_seconds > 0 else 0
                    self._pending_seek_generation = self._seek_generation
                    self._pending_seek_at = time.monotonic()
                    self.file_gain = gain if gain and gain > 0 else 1.0
                    try:
                        self.set_volume(
                            db.config.get("global_volume", 70) if db else 70,
                            db.config.get("is_muted", False) if db else False,
                        )
                        if defer_unmute:
                            self.player.audio_set_mute(True)
                    except Exception as e:
                        log.warning("play_file_segmented: immediate gain apply failed: %s", e)
                    if not _cached_path_exists(filepath):
                        log.warning("[ATTEMPT %s] play_file_segmented: file does not exist, refusing to play: %s",
                                     _attempt_id, filepath)
                        _open_handed_over()
                        _confirm(False, deferred=False)
                        return False

                    is_dvd_iso = is_dvd_disc_source(filepath)
                    self.is_dvd_iso = is_dvd_iso
                    self._dvd_title_menu_flags = None

                    if is_dvd_iso and filepath != getattr(self, "current_filepath", None):
                        self._dvd_src_dims = None

                    if is_dvd_iso:
                        media_source = dvd_disc_mrl(filepath)
                    else:
                        media_source = filepath
                    

                    _pending_stop_done = None
                    try:
                        _pending_stop_done = self.stop(block=False)
                    except Exception as e:
                        log.warning("play_file_segmented: pre-emptive stop() failed: %s", e)

                    self._pending_seek_generation = self._seek_generation

                    if is_dvd_iso:
                        self._apply_screen_mode_geometry(True, getattr(self, "_dvd_src_dims", None))
                        continue_probe = False
                        if (getattr(self, "_dvd_src_dims", None) is None
                                and self.target_aspect != "4:3"
                                and self._configured_screen_mode() in ("normal", "crop", "panscan")):
                            _dvd_native_gen = self._seek_generation
                            _t_dvd_native = threading.Thread(
                                target=self._apply_dvd_native_dims_when_ready,
                                args=(_dvd_native_gen,),
                                daemon=True)
                            _t_dvd_native.start()
                    else:
                        continue_probe = True

                    if continue_probe:
                        _norm_fp = os.path.normpath(os.path.abspath(filepath))
                        _src_dims = self._dim_probe_cache.get(_norm_fp)
                        if _src_dims is None:
                            _persisted_dims = _read_file_probe_facts(_norm_fp).get("dims")
                            if _persisted_dims and len(_persisted_dims) == 2:
                                _src_dims = tuple(_persisted_dims)
                                self._dim_probe_cache[_norm_fp] = _src_dims
                        _pre_show_box = _decide_picture_box_before_show(filepath)
                        if _pre_show_box and not _pre_show_box.get("guessed") and _pre_show_box.get("frame") and _pre_show_box.get("pixel_aspect"):
                            _box_w, _box_h = _pre_show_box["frame"]
                            if _box_w and _box_h:
                                _src_dims = (max(2, int(round(_box_w * float(_pre_show_box["pixel_aspect"])))), int(_box_h))
                                self._dim_probe_cache[_norm_fp] = _src_dims
                        if _src_dims is None and _norm_fp not in self._dim_probe_inflight:
                            self._dim_probe_inflight.add(_norm_fp)
                            _probe_gen = self._seek_generation

                            def _finish_dims_probe(_dims, _fp, _np, _gen):
                                """Persists the probed dims and, when the reopen path is still needed, reconciles geometry for what is on screen."""
                                # WARNING: only reconcile when this is still the exact open that was probed; reconfiguring the decode buffer live on a different stream is unsafe.
                                if not _dims:
                                    return
                                self._dim_probe_cache[_np] = _dims
                                try:
                                    _save_file_probe_facts(_np, dims=_dims)
                                    if db is not None:
                                        db.save_settings_async()
                                except Exception as e:
                                    log.warning("play_file_segmented: failed to persist dims for %s: %s", _fp, e)
                                try:
                                    _cur_fp = getattr(self, "current_filepath", None)
                                    _cur_norm = (os.path.normpath(os.path.abspath(_cur_fp))
                                                 if _cur_fp else None)
                                    if (getattr(self, "_seek_generation", None) == _gen
                                            and _cur_norm == _np
                                            and not getattr(self, "is_dvd_iso", False)
                                            and db is not None
                                            and self._configured_screen_mode() in ("normal", "crop", "panscan")):
                                        log.info("[GEOMETRY REFRESH TRIGGER:%s] source=slow_ffmpeg_probe file=%s gen=%s", self.engine_label, _fp, _gen)
                                        self.refresh_screen_mode_geometry()
                                except Exception as e:
                                    log.warning("play_file_segmented: post-probe geometry refresh failed for %s: %s", _fp, e)

                            _dims_probe_result = {}

                            def _probe_dims_worker(_fp=filepath, _out=_dims_probe_result):
                                try:
                                    _out["dims"] = get_media_video_dimensions(_fp)
                                except Exception as e:
                                    log.warning("play_file_segmented: source dimension probe failed for %s: %s", _fp, e)

                            import threading as _t_dims
                            _dims_probe_thread = _t_dims.Thread(target=_probe_dims_worker, daemon=True)
                            _dims_probe_thread.start()
                            _dims_probe_thread.join(timeout=PRE_OPEN_DIMS_PROBE_BOUND_S)

                            if _dims_probe_thread.is_alive():
                                def _probe_dims_async(_fp=filepath, _np=_norm_fp, _gen=_probe_gen,
                                                       _thread=_dims_probe_thread, _out=_dims_probe_result):
                                    try:
                                        _thread.join()
                                        _finish_dims_probe(_out.get("dims"), _fp, _np, _gen)
                                    finally:
                                        self._dim_probe_inflight.discard(_np)
                                _t_dims.Thread(target=_probe_dims_async, daemon=True).start()
                            else:
                                _dims = _dims_probe_result.get("dims")
                                if _dims:
                                    _src_dims = _dims
                                self._dim_probe_inflight.discard(_norm_fp)
                                _finish_dims_probe(_dims, filepath, _norm_fp, _probe_gen)

                        self._apply_screen_mode_geometry(False, _src_dims)

                    def _open_and_play(verify_off_thread=False):
                        try:
                            return _open_and_play_steps(verify_off_thread)
                        finally:
                            _open_handed_over()

                    def _seek_at_open():
                        """The start position for the open now happening: what was asked, plus the time the open waited when the file follows the station clock (R18)."""
                        if not follow_clock or is_dvd_iso:
                            return _requested_seek
                        _waited = time.monotonic() - _requested_at
                        if _waited < OPEN_WAIT_JOIN_CLOCK_MIN_S:
                            return _requested_seek
                        _joined = (_requested_seek or 0.0) + _waited
                        log.info("[ATTEMPT %s][JOIN CLOCK] the open waited %.2fs after its start was worked out; opening at %.2fs instead of %.2fs: %s",
                                 _attempt_id, _waited, _joined, _requested_seek or 0.0, os.path.basename(str(filepath)))
                        self._pending_seek_ms = int(_joined * 1000)
                        self._pending_seek_at = time.monotonic()
                        return _joined

                    def _open_and_play_steps(verify_off_thread=False):
                        if _attempt_stale():
                            log.info("[ATTEMPT %s] dropped before the open: the channel on screen is no longer the one this load was for: %s",
                                     _attempt_id, os.path.basename(str(filepath)))
                            return _PLAYBACK_STALE
                        seek_seconds = _seek_at_open()
                        try:
                            media = self.instance.media_new(media_source)
                            _cpu_for_picture = _vlc_does_picture_settings()
                            self._decoding_on_gpu = False
                            if _cpu_for_picture:
                                log.info("[PICTURE ADJUST] no graphics-card drawing step: the CPU decodes %s so VLC can draw the Video tab's picture settings",
                                         os.path.basename(str(filepath)))
                            elif self.engine_label == "dvd" and not is_dvd_iso and DVD_FILE_HW_DECODE:
                                try:
                                    media.add_option(":avcodec-hw=any")
                                    self._decoding_on_gpu = True
                                    log.info("[DVD DECODE] hardware decode requested for %s",
                                             os.path.basename(str(filepath)))
                                except Exception as _hw_e:
                                    log.warning("[DVD DECODE] could not request hardware decode for %s "
                                                "(staying on software): %s",
                                                os.path.basename(str(filepath)), _hw_e)
                            elif self.engine_label != "dvd" and not is_dvd_iso and _main_video_hw_decode_allowed():
                                try:
                                    # WARNING: VLC switches hardware decoding off for every player that hands frames to the app (avcodec-hw=none); only this per-file option turns it back on, and VLC decodes the file on the CPU by itself when the card cannot open it.
                                    media.add_option(":avcodec-hw=any")
                                    self._decoding_on_gpu = True
                                except Exception as _hw_e:
                                    log.warning("[VIDEO DECODE] could not ask VLC to decode %s on the graphics card "
                                                "(the CPU decodes it): %s", os.path.basename(str(filepath)), _hw_e)
                            _picture_options, _picture_adjust_on = _picture_adjust_media_options()
                            for _picture_option in _picture_options:
                                try:
                                    media.add_option(_picture_option)
                                except Exception as _pic_e:
                                    log.warning("[PICTURE ADJUST] VLC would not take %s for %s (the picture plays unadjusted): %s",
                                                _picture_option, os.path.basename(str(filepath)), _pic_e)
                            self._adjust_in_chain = _picture_adjust_on
                            _opened_at_position = False
                            if (SEEK_AT_OPEN and seek_seconds and seek_seconds > 0
                                    and not is_dvd_iso):
                                try:
                                    media.add_option(":start-time=%.3f" % seek_seconds)
                                    _opened_at_position = True
                                    log.info("[ATTEMPT %s][SEEK AT OPEN] start-time=%.3fs handed to VLC: file=%s",
                                             _attempt_id, seek_seconds, filepath)
                                except Exception as _st_e:
                                    log.warning("[ATTEMPT %s][SEEK AT OPEN] could not hand the start position to VLC "
                                                "(will seek after open instead): %s", _attempt_id, _st_e)
                            if self.engine_label != "dvd" and not is_dvd_iso:
                                try:
                                    media.add_option(":no-sub-autodetect-file")
                                except Exception as _sub_e:
                                    log.warning("could not turn off VLC sidecar subtitle autodetect for %s: %s",
                                                os.path.basename(str(filepath)), _sub_e)
                            self._frame_ready = False
                            self.clear_frame_buffer()
                            self._warmup_skip = 2
                            with self._state_cond:
                                self._current_state = None
                                self._current_length = -1
                                self._state_cond.notify_all()

                            _open_done = threading.Event()
                            _open_err = []

                            def _do_open():
                                try:
                                    self.player.set_media(media)
                                    self.player.play()
                                except Exception as _e:
                                    _open_err.append(_e)
                                finally:
                                    _open_done.set()

                            threading.Thread(
                                target=_do_open, daemon=True,
                                name=f"vlc-open-{self.engine_label}",
                            ).start()
                            if not _open_done.wait(timeout=WEDGED_STOP_TIMEOUT_S):
                                self._wedged = True
                                log.critical(
                                    "[WEDGED-TEARDOWN] player.play() on engine '%s' did not "
                                    "return within %ss -- libVLC open is almost certainly "
                                    "stalled on an unresponsive drive/device, same as a "
                                    "wedged stop(). Flagging this engine wedged so the "
                                    "per-frame recovery check can replace it, instead of "
                                    "blocking the caller (main thread, in the common case) "
                                    "further.",
                                    self.engine_label, WEDGED_STOP_TIMEOUT_S,
                                )
                                return False
                            if _open_err:
                                raise _open_err[0]

                            log.info("[ATTEMPT %s][STATE RACE] reset _current_state/_current_length before play(): file=%s",
                                      _attempt_id, filepath)
                        except Exception as e:
                            log.warning("[ATTEMPT %s] play_file_segmented: VLC failed to start playback for %s: %s",
                                         _attempt_id, filepath, e)
                            try:
                                _last_vlc_play_exception[os.path.normpath(filepath)] = str(e)
                            except Exception as _swallowed_error:
                                _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.play_file_segmented._open_and_play: _last_vlc_play_exception[os.path.normpath(filepath)] = str(e)", _swallowed_error)
                            return False

                        if seek_seconds and seek_seconds > 0:
                            import threading as _t
                            _t.Thread(target=self._seek_when_ready,
                                      args=(seek_seconds,),
                                      kwargs={"is_disc_image": is_dvd_iso,
                                              "timeout_ms": 8000 if is_dvd_iso else 4000,
                                              "generation": self._seek_generation,
                                              "opened_at_position": _opened_at_position},
                                      daemon=True).start()

                        if is_dvd_iso:
                            import threading as _t3
                            _t3.Thread(target=self._dump_dvd_title_map,
                                       daemon=True).start()

                        self.current_filepath = filepath
                        self._audio_index = None
                        try:
                            _last_vlc_play_exception.pop(os.path.normpath(filepath), None)
                        except Exception as _swallowed_error:
                            _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.play_file_segmented._open_and_play: _last_vlc_play_exception.pop(os.path.normpath(filepath), None)", _swallowed_error)
                        import threading as _t2
                        _t2.Thread(target=self._apply_saved_audio_track_when_ready,
                                   args=(filepath,), daemon=True).start()
                        _t2.Thread(target=self._apply_volume_when_ready,
                                   args=(filepath,), daemon=True).start()
                        if continue_probe and _src_dims is None:
                            _t2.Thread(target=self._apply_native_dims_when_ready,
                                       args=(filepath, _norm_fp, self._seek_generation),
                                       daemon=True).start()
                        if is_dvd_iso and getattr(self, "_dvd_src_dims", None) is None:
                            _t2.Thread(target=self._apply_dvd_native_dims_when_ready,
                                       args=(self._seek_generation,), daemon=True).start()
                        # WARNING: set_media()/play() not raising does not mean the file opened; verify below.
                        # WARNING: the fallback numbers below must match PLAY_OPEN_ERROR_CHECK_SECONDS in performance_governor.py; they are used only when that module fails to import.
                        _OPEN_ERROR_CHECK_S = performance_governor.PLAY_OPEN_ERROR_CHECK_SECONDS if performance_governor is not None else 0.25
                        # WARNING: libVLC can fail an open without State.Error: on a busy drive it read 0 bytes, matched no demuxer and went straight to Stopped while the app logged OPENED and left a black screen. A Stopped/Ended state that persists right after the open is a failed open; it is retried (the file is fine, the read was starved) before it is called a failure.
                        # WARNING: the fallback numbers below must match PLAY_OPEN_CONFIRM_WINDOW_SECONDS in performance_governor.py; they are used only when that module fails to import.
                        _OPEN_CONFIRM_WINDOW_S = performance_governor.PLAY_OPEN_CONFIRM_WINDOW_SECONDS if performance_governor is not None else 1.5
                        # WARNING: the fallback numbers below must match PLAY_OPEN_STOPPED_DEBOUNCE_SECONDS in performance_governor.py; they are used only when that module fails to import.
                        _OPEN_STOPPED_DEBOUNCE_S = performance_governor.PLAY_OPEN_STOPPED_DEBOUNCE_SECONDS if performance_governor is not None else 0.15
                        # WARNING: the fallback numbers below must match PLAY_OPEN_RETRY_DELAYS_SECONDS in performance_governor.py; they are used only when that module fails to import.
                        _OPEN_RETRY_DELAYS_S = performance_governor.PLAY_OPEN_RETRY_DELAYS_SECONDS if performance_governor is not None else (0.5, 1.0)

                        def _wait_open_outcome(window_s):
                            """Returns "error" on State.Error, "stopped" when Stopped/Ended persists, "ok" once Playing/Paused, "pending" when the window ends first."""
                            _stopped_since = None
                            with self._state_cond:
                                _deadline = time.monotonic() + window_s
                                while True:
                                    _st = self._current_state
                                    if _st == vlc.State.Error:
                                        return "error"
                                    if _st in (vlc.State.Playing, vlc.State.Paused):
                                        return "ok"
                                    if _st in (vlc.State.Stopped, vlc.State.Ended):
                                        if _stopped_since is None:
                                            _stopped_since = time.monotonic()
                                        elif time.monotonic() - _stopped_since >= _OPEN_STOPPED_DEBOUNCE_S:
                                            return "stopped"
                                    else:
                                        _stopped_since = None
                                    _remaining = _deadline - time.monotonic()
                                    if _remaining <= 0:
                                        return "pending"
                                    self._state_cond.wait(timeout=min(_remaining, 0.05))

                        def _reopen_same_media():
                            """Hands the same media to the player again from a helper thread (the player call can block on a stalled drive)."""
                            with self._state_cond:
                                self._current_state = None
                                self._current_length = -1
                                self._state_cond.notify_all()
                            _again_done = threading.Event()

                            def _again():
                                try:
                                    self.player.set_media(media)
                                    self.player.play()
                                except Exception as _again_err:
                                    log.warning("[ATTEMPT %s] open retry call failed: %s", _attempt_id, _again_err)
                                finally:
                                    _again_done.set()
                            threading.Thread(target=_again, daemon=True, name=f"vlc-open-retry-{self.engine_label}").start()
                            return _again_done.wait(timeout=WEDGED_STOP_TIMEOUT_S)

                        def _open_error_check(can_retry=False):
                            """Waits for libVLC to say whether the open worked; returns True when the open was accepted. With can_retry (off the main thread only) a Stopped-after-open is re-opened up to twice before it counts as failed."""
                            _window = _OPEN_CONFIRM_WINDOW_S if can_retry else _OPEN_ERROR_CHECK_S
                            _tries = 0
                            while True:
                                _outcome = _wait_open_outcome(_window)
                                if _outcome in ("ok", "pending"):
                                    break
                                if _outcome == "stopped" and can_retry and _tries < len(_OPEN_RETRY_DELAYS_S):
                                    _delay = _OPEN_RETRY_DELAYS_S[_tries]
                                    _tries += 1
                                    log.warning("[ATTEMPT %s] VLC stopped right after the open without an error (read nothing); "
                                                "retry %d of %d in %.1fs: file=%s",
                                                _attempt_id, _tries, len(_OPEN_RETRY_DELAYS_S), _delay, filepath)
                                    time.sleep(_delay)
                                    if getattr(self, "_current_attempt_id", None) != _attempt_id or _attempt_stale():
                                        return False
                                    if not _reopen_same_media():
                                        break
                                    continue
                                if _outcome == "stopped" and not can_retry:
                                    break
                                log.warning(
                                    "[ATTEMPT %s] play() returned without raising, but libVLC "
                                    "reported State.%s within %.1fs of the open call -- "
                                    "treating this as a failed open, not a successful one: "
                                    "file=%s",
                                    _attempt_id, "Error" if _outcome == "error" else "Stopped", _window, filepath,
                                )
                                try:
                                    _last_vlc_play_exception[os.path.normpath(filepath)] = (
                                        "libVLC reported State.Error immediately after open "
                                        "(drive/file rejected the open)"
                                    )
                                except Exception as _swallowed_error:
                                    _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.play_file_segmented._open_and_play._open_error_check: _last_vlc_play_exception[os.path.normpath(filepath)] = 'libVLC reported State.Error imm...", _swallowed_error)
                                return False
                            if _outcome == "stopped":
                                return False
                            log.info("[ATTEMPT %s] OPENED: file=%s%s", _attempt_id, filepath,
                                     " (after %d open retr%s)" % (_tries, "y" if _tries == 1 else "ies") if _tries else "")
                            return True

                        if not verify_off_thread:
                            return _open_error_check()

                        # WARNING: while the check runs the caller gets _PLAYBACK_PENDING and on_confirmed fires from the check thread; the watchdog must stay off until _open_confirm_pending_attempt clears.
                        self._open_confirm_pending_attempt = _attempt_id

                        def _verify_open_off_thread():
                            try:
                                _confirm(_open_error_check(can_retry=True), deferred=True)
                            except Exception as _verr:
                                log.warning("[ATTEMPT %s] open error check failed: %s", _attempt_id, _verr)
                                _confirm(False, deferred=True)
                            finally:
                                if getattr(self, "_open_confirm_pending_attempt", None) == _attempt_id:
                                    self._open_confirm_pending_attempt = None

                        threading.Thread(
                            target=_verify_open_off_thread, daemon=True,
                            name=f"vlc-open-check-{self.engine_label}",
                        ).start()
                        return _PLAYBACK_PENDING

                    if _pending_stop_done is None or _pending_stop_done.wait(
                            timeout=_PLAY_SEGMENTED_STOP_FAST_WAIT_S):
                        _sync_ok = _open_and_play(verify_off_thread=True)
                        if _sync_ok is _PLAYBACK_PENDING:
                            return _PLAYBACK_PENDING
                        _confirm(_sync_ok, deferred=False)
                        return _sync_ok

                    log.info("[ATTEMPT %s][STOP RACE GUARD] pre-emptive stop() for %s still running after "
                              "%.0fms -- deferring open to avoid racing it",
                              _attempt_id, filepath, _PLAY_SEGMENTED_STOP_FAST_WAIT_S * 1000)

                    def _open_after_stop_settles(_done=_pending_stop_done, _fp=filepath, _aid=_attempt_id):
                        _stop_settled = _done.wait(timeout=WEDGED_STOP_TIMEOUT_S)
                        if _attempt_stale():
                            log.info("[ATTEMPT %s][STOP RACE GUARD] deferred open dropped: the channel on screen is no longer the one this load was for: %s", _aid, _fp)
                            _open_handed_over()
                            return
                        if _stop_settled and not self._wedged:
                            _deferred_ok = _open_and_play()
                            log.info("[ATTEMPT %s][STOP RACE GUARD] deferred open %s: file=%s",
                                      _aid, "OPENED" if _deferred_ok else "FAILED", _fp)
                            _confirm(_deferred_ok, deferred=True)
                        else:
                            log.warning("[ATTEMPT %s][STOP RACE GUARD] stop() for %s never completed (or engine "
                                        "went wedged) -- abandoning this open; wedge-replacement will "
                                        "handle recovery", _aid, _fp)
                            _open_handed_over()
                            _confirm(False, deferred=True)

                    import threading as _t_deferred_open
                    _t_deferred_open.Thread(target=_open_after_stop_settles, daemon=True).start()

                    # WARNING: this return value means not decided yet; callers must wait for on_confirmed.
                    log.info("[ATTEMPT %s] DEFERRED: outcome not yet known -- caller must wait for "
                              "on_confirmed (see [STOP RACE GUARD] log for this attempt id for the "
                              "real outcome once it lands)", _attempt_id)
                    return _PLAYBACK_PENDING

                def _display_dims_from_player(self):
                    """Returns the player's display size with the stream's sample aspect ratio applied, or None."""
                    # WARNING: video_get_size(0) alone returns the coded frame size without the sample aspect ratio.
                    try:
                        size = self.player.video_get_size(0)
                    except Exception as _swallowed_error:
                        _log_swallowed("_display_dims_from_player: size = self.player.video_get_size(0)", _swallowed_error)
                        return None
                    if not size or not size[0] or not size[1]:
                        return None
                    w, h = int(size[0]), int(size[1])
                    if w <= 0 or h <= 0:
                        return None
                    try:
                        import vlc as _vlc
                        media = self.player.get_media()
                        tracks = media.tracks_get() if media is not None else None
                        if tracks:
                            for track in tracks:
                                if (getattr(track, "type", None) == _vlc.TrackType.video
                                        and track.video):
                                    sar_num = int(track.video.sar_num or 0)
                                    sar_den = int(track.video.sar_den or 0)
                                    if sar_num > 0 and sar_den > 0 and sar_num != sar_den:
                                        corrected_w = round(w * (sar_num / sar_den))
                                        if 0.5 * w <= corrected_w <= 2.0 * w:
                                            log.info("[NATIVE DIMS SAR CORRECT:%s] coded=%sx%s sar=%s:%s -> display=%sx%s",
                                                      self.engine_label, w, h, sar_num, sar_den, corrected_w, h)
                                            return (corrected_w, h)
                                    break
                    except Exception as e:
                        log.warning("_display_dims_from_player: SAR lookup failed, using coded size: %s", e)
                    return (w, h)

                def _apply_native_dims_when_ready(self, filepath, norm_fp, generation, timeout_ms=1200):
                    """Polls the open VLC player for the source's real pixel size."""
                    deadline = pygame.time.get_ticks() + timeout_ms
                    log.info("[NATIVE DIMS POLL:%s] START file=%s gen=%s timeout_ms=%s", self.engine_label, filepath, generation, timeout_ms)
                    while pygame.time.get_ticks() < deadline:
                        if (getattr(self, "current_filepath", None) != filepath
                                or getattr(self, "_seek_generation", None) != generation):
                            log.info("[NATIVE DIMS POLL:%s] SUPERSEDED file=%s gen=%s current_filepath=%s current_gen=%s -- another open/seek took over, this poll never applied anything",
                                     self.engine_label, filepath, generation, getattr(self, "current_filepath", None), getattr(self, "_seek_generation", None))
                            return
                        dims = self._display_dims_from_player()
                        if dims:
                            w, h = dims
                            if w > 0 and h > 0:
                                _elapsed_ms = timeout_ms - (deadline - pygame.time.get_ticks())
                                log.info("[NATIVE DIMS POLL:%s] FOUND file=%s gen=%s dims=%sx%s after %sms", self.engine_label, filepath, generation, w, h, _elapsed_ms)
                                self._dim_probe_cache[norm_fp] = (w, h)
                                try:
                                    _save_file_probe_facts(norm_fp, dims=(w, h))
                                    if db is not None:
                                        db.save_settings_async()
                                except Exception as e:
                                    log.warning("_apply_native_dims_when_ready: failed to persist dims for %s: %s", filepath, e)
                                try:
                                    _refresh_gate = (getattr(self, "current_filepath", None) == filepath
                                            and getattr(self, "_seek_generation", None) == generation
                                            and not getattr(self, "is_dvd_iso", False)
                                            and db is not None
                                            and self._configured_screen_mode() in ("normal", "crop", "panscan"))
                                    if _refresh_gate:
                                        log.info("[GEOMETRY REFRESH TRIGGER:%s] source=native_dims_poll file=%s gen=%s dims=%sx%s", self.engine_label, filepath, generation, w, h)
                                        self.refresh_screen_mode_geometry()
                                    else:
                                        log.info("[NATIVE DIMS POLL:%s] dims found but refresh SKIPPED (gate failed) file=%s gen=%s current_filepath_match=%s current_gen_match=%s is_dvd_iso=%s screen_mode=%s",
                                                 self.engine_label, filepath, generation,
                                                 getattr(self, "current_filepath", None) == filepath,
                                                 getattr(self, "_seek_generation", None) == generation,
                                                 getattr(self, "is_dvd_iso", False),
                                                 self._configured_screen_mode())
                                except Exception as e:
                                    log.warning("_apply_native_dims_when_ready: geometry refresh failed for %s: %s", filepath, e)
                                return
                        time.sleep(0.02)
                    log.info("[NATIVE DIMS POLL:%s] TIMEOUT file=%s gen=%s -- no size from VLC within %sms, falling back to the slow ffmpeg probe entirely",
                             self.engine_label, filepath, generation, timeout_ms)

                def _apply_dvd_native_dims_when_ready(self, generation, timeout_ms=1500):
                    """DVD counterpart to _apply_native_dims_when_ready()."""
                    deadline = pygame.time.get_ticks() + timeout_ms
                    while pygame.time.get_ticks() < deadline:
                        if (not getattr(self, "is_dvd_iso", False)
                                or getattr(self, "_seek_generation", None) != generation):
                            return
                        try:
                            size = self.player.video_get_size(0)
                        except Exception as _swallowed_error:
                            _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._apply_dvd_native_dims_when_ready: size = self.player.video_get_size(0)", _swallowed_error)
                            size = None
                        if size and size[0] and size[1]:
                            w, h = int(size[0]), int(size[1])
                            if w > 0 and h > 0:
                                self._dvd_src_dims = (w, h)
                                try:
                                    if (getattr(self, "_seek_generation", None) == generation
                                            and getattr(self, "is_dvd_iso", False)
                                            and self.target_aspect != "4:3"
                                            and self._configured_screen_mode() in ("normal", "crop", "panscan")):
                                        self.refresh_screen_mode_geometry()
                                except Exception as e:
                                    log.warning("_apply_dvd_native_dims_when_ready: geometry refresh failed: %s", e)
                                return
                        time.sleep(0.02)

                def _apply_volume_when_ready(self, filepath, timeout_ms=5000):
                    import vlc as _vlc
                    deadline = pygame.time.get_ticks() + timeout_ms
                    while pygame.time.get_ticks() < deadline:
                        if getattr(self, "current_filepath", None) != filepath:
                            return
                        try:
                            state = self.player.get_state()
                        except Exception as _swallowed_error:
                            _log_swallowed("_apply_volume_when_ready: state = self.player.get_state()", _swallowed_error)
                            return
                        if state in (_vlc.State.Ended, _vlc.State.Error, _vlc.State.Stopped):
                            return
                        if state in (_vlc.State.Playing, _vlc.State.Paused):
                            try:
                                _watchdog_armed = False
                                _reassert_deadline = pygame.time.get_ticks() + 1500
                                while True:
                                    if getattr(self, "current_filepath", None) != filepath:
                                        return
                                    self.set_volume(
                                        db.config.get("global_volume", 70) if db else 70,
                                        db.config.get("is_muted", False) if db else False,
                                    )
                                    if app_state.get("_video_pending_unmute", False):
                                        try:
                                            self.player.audio_set_mute(True)
                                        except Exception as _swallowed_error:
                                            _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._apply_volume_when_ready: self.player.audio_set_mute(True)", _swallowed_error)
                                        if not _watchdog_armed:
                                            _mute_guard_log("apply_volume_when_ready FORCE-REMUTE + spawning watchdog",
                                                             ch=app_state.get("current_channel"), filepath=filepath)
                                            _arm_mute_guard_watchdog(app_state.get("current_channel"), filepath)
                                            _watchdog_armed = True
                                    if pygame.time.get_ticks() >= _reassert_deadline:
                                        break
                                    pygame.time.wait(150)
                            except Exception as e:
                                log.warning("_apply_volume_when_ready: set_volume failed: %s", e)
                            return
                        pygame.time.wait(50)

                def _apply_saved_audio_track_when_ready(self, filepath, timeout_ms=4000):
                    import vlc as _vlc
                    saved = _get_saved_audio_track(filepath)
                    if saved is None:
                        self._apply_preferred_audio_track_when_ready(filepath, timeout_ms)
                        return
                    saved_id, saved_name = saved
                    deadline = pygame.time.get_ticks() + timeout_ms
                    tracks = []
                    while pygame.time.get_ticks() < deadline:
                        if getattr(self, "current_filepath", None) != filepath:
                            return
                        try:
                            state = self.player.get_state()
                        except Exception as _swallowed_error:
                            _log_swallowed("_apply_saved_audio_track_when_ready: state = self.player.get_state()", _swallowed_error)
                            return
                        if state in (_vlc.State.Ended, _vlc.State.Error, _vlc.State.Stopped):
                            return
                        if state in (_vlc.State.Playing, _vlc.State.Paused):
                            try:
                                tracks = self.player.audio_get_track_description() or []
                            except Exception as _swallowed_error:
                                _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._apply_saved_audio_track_when_ready: tracks = self.player.audio_get_track_description() or []", _swallowed_error)
                                tracks = []
                            if tracks:
                                break
                        pygame.time.wait(50)
                    else:
                        return

                    if not tracks or getattr(self, "current_filepath", None) != filepath:
                        return

                    ids = [t[0] for t in tracks]
                    target_id = None
                    if saved_id in ids:
                        target_id = saved_id
                    elif saved_name:
                        for tid, tname in tracks:
                            _label = tname.decode("utf-8", "ignore") if isinstance(tname, bytes) else str(tname)
                            if _label == saved_name:
                                target_id = tid
                                break
                    if target_id is not None:
                        try:
                            self.player.audio_set_track(target_id)
                            log.info("[AUDIO TRACK] Restored saved track %s for %s", target_id, filepath)
                            _listed = [tid for tid, _n in self.get_audio_tracks()]
                            if target_id in _listed:
                                self._audio_index = _listed.index(target_id)
                            self._reapply_track_gain(filepath)
                        except Exception as e:
                            log.warning("[AUDIO TRACK] Failed to restore saved track for %s: %s", filepath, e)

                def _apply_preferred_audio_track_when_ready(self, filepath, timeout_ms=4000):
                    """For a file with no saved track choice: once VLC's track list has settled, switches to the first track in the preferred language (English first) when another track is playing; the pick is not saved, so a later choice in the menu still wins."""
                    import vlc as _vlc
                    try:
                        if is_dvd_disc_source(filepath):
                            return
                        header = _audio_header_streams(filepath)
                        settle_ms = int(_gov_audio_track_value("AUDIO_TRACK_SETTLE_MS", 600))
                        settle_max_ms = int(_gov_audio_track_value("AUDIO_TRACK_SETTLE_MAX_MS", 2500))
                        deadline = pygame.time.get_ticks() + timeout_ms
                        tracks, stable_since, settle_deadline = None, None, None
                        while pygame.time.get_ticks() < deadline:
                            if getattr(self, "current_filepath", None) != filepath:
                                return
                            state = self.player.get_state()
                            if state in (_vlc.State.Ended, _vlc.State.Error, _vlc.State.Stopped):
                                return
                            if state in (_vlc.State.Playing, _vlc.State.Paused):
                                now_tracks = self.get_audio_tracks()
                                now_ms = pygame.time.get_ticks()
                                if settle_deadline is None and now_tracks:
                                    settle_deadline = now_ms + settle_max_ms
                                if now_tracks != tracks:
                                    tracks, stable_since = now_tracks, now_ms
                                elif tracks and (now_ms - stable_since >= settle_ms
                                                 or (header and len(tracks) >= len(header))
                                                 or now_ms >= settle_deadline):
                                    break
                            pygame.time.wait(100)
                        if not tracks or getattr(self, "current_filepath", None) != filepath:
                            return
                        if len(tracks) < 2:
                            return
                        _playing_id = self.get_current_audio_track()
                        target_id, why = _pick_preferred_audio_track(tracks, header, _playing_id)
                        _ids = [tid for tid, _n in tracks]
                        if target_id is None:
                            log.info("[AUDIO TRACK] %s: kept the playing track (%s)", os.path.basename(filepath), why)
                            if _playing_id in _ids:
                                self._audio_index = _ids.index(_playing_id)
                                self._reapply_track_gain(filepath)
                            return
                        if self.set_audio_track(target_id):
                            log.info("[AUDIO TRACK] %s: switched to the preferred-language track, %s", os.path.basename(filepath), why)
                            self._audio_index = _ids.index(target_id)
                            self._reapply_track_gain(filepath)
                        else:
                            log.warning("[AUDIO TRACK] %s: could not switch to the preferred-language track %s", os.path.basename(filepath), target_id)
                    except Exception as e:
                        log.warning("[AUDIO TRACK] picking the preferred-language track for %s failed: %s", os.path.basename(str(filepath)), e)

                def _reapply_track_gain(self, filepath):
                    """Background, at file start: loads the file's per-track gains and, when the track now playing has its own gain, plays the file at it; a muted start stays muted."""
                    try:
                        if self is not vlc_engine:
                            return
                        _load_track_gains(os.path.normpath(filepath))
                        if getattr(self, "current_filepath", None) != filepath:
                            return
                        new_gain = _lookup_file_gain(app_state.get("current_channel") or "", filepath)
                        if abs(new_gain - (self.file_gain or 0.0)) < 1e-6:
                            return
                        self.file_gain = new_gain
                        self.set_volume(db.config.get("global_volume", 70), db.config.get("is_muted", False))
                        if app_state.get("_video_pending_unmute", False):
                            self.player.audio_set_mute(True)
                        log.info("[AUDIO TRACK] %s: playing audio track %s at its own gain x%.3f",
                                 os.path.basename(filepath), (self._audio_index or 0) + 1, new_gain)
                    except Exception as e:
                        log.warning("[AUDIO TRACK] applying the gain of the playing track of %s failed: %s", os.path.basename(str(filepath)), e)

                def get_audio_tracks(self):
                    try:
                        raw = self.player.audio_get_track_description() or []
                    except Exception as _swallowed_error:
                        _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.get_audio_tracks: raw = self.player.audio_get_track_description() or []", _swallowed_error)
                        raw = []
                    out = []
                    for tid, tname in raw:
                        if tid == -1:
                            continue
                        label = tname.decode("utf-8", "ignore") if isinstance(tname, bytes) else str(tname)
                        out.append((tid, label or f"Track {tid}"))
                    return out

                def get_current_audio_track(self):
                    try:
                        return self.player.audio_get_track()
                    except Exception as _swallowed_error:
                        _log_swallowed("get_current_audio_track: return self.player.audio_get_track()", _swallowed_error)
                        return -1

                def set_audio_track(self, track_id):
                    try:
                        return self.player.audio_set_track(track_id) == 0
                    except Exception as e:
                        log.warning("set_audio_track: failed to set track %s: %s", track_id, e)
                        return False

                def get_current_time(self):
                    """Current playback position in ms, or None if unavailable."""
                    try:
                        pos_ms = self.player.get_time()
                        return pos_ms if pos_ms is not None and pos_ms >= 0 else None
                    except Exception as _swallowed_error:
                        _log_swallowed("get_current_time: pos_ms = self.player.get_time()", _swallowed_error)
                        return None

                def get_playback_state(self):
                    """Returns (state, length_ms or None); state is one of 'playing', 'paused', 'ended', 'stopped', 'error', 'opening', 'buffering' or 'other'."""
                    try:
                        raw_state = self.player.get_state()
                    except Exception as _swallowed_error:
                        _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper.get_playback_state: raw_state = self.player.get_state()", _swallowed_error)
                        return "other", None
                    _STATE_NAMES = {
                        vlc.State.Playing:   "playing",
                        vlc.State.Paused:    "paused",
                        vlc.State.Ended:     "ended",
                        vlc.State.Stopped:   "stopped",
                        vlc.State.Error:     "error",
                        vlc.State.Opening:   "opening",
                        vlc.State.Buffering: "buffering",
                    }
                    state_name = _STATE_NAMES.get(raw_state, "other")
                    length_ms = getattr(self, "_current_length", -1)
                    length_ms = length_ms if length_ms and length_ms > 0 else None
                    return state_name, length_ms

                def _seek_when_ready(self, seek_seconds, timeout_ms=4000, is_disc_image=False, generation=None,
                                     opened_at_position=False):
                    import vlc as _vlc
                    target_ms = int(seek_seconds * 1000)
                    deadline = pygame.time.get_ticks() + timeout_ms
                    _still_in_menu_at_timeout = False
                    _timed_out = False

                    def _superseded():
                        return generation is not None and generation != self._seek_generation

                    if _superseded():
                        log.info("[STATE RACE] _seek_when_ready superseded before starting: file=%s", getattr(self, "current_filepath", "?"))
                        return
                    with self._state_cond:
                        while True:
                            if _superseded():
                                log.info("[STATE RACE] _seek_when_ready superseded mid-wait, bailing: file=%s", getattr(self, "current_filepath", "?"))
                                return
                            remaining_ms = deadline - pygame.time.get_ticks()
                            if remaining_ms <= 0:
                                _timed_out = True
                                break
                            state = self._current_state
                            if state in (_vlc.State.Ended, _vlc.State.Error):
                                log.info("[STATE RACE] _seek_when_ready bailing: terminal state=%s file=%s", state, getattr(self, "current_filepath", "?"))
                                return
                            if state == _vlc.State.Stopped:
                                log.info("[STATE RACE] saw Stopped, debouncing before treating as terminal: file=%s", getattr(self, "current_filepath", "?"))
                                self._state_cond.wait(0.1)
                                if self._current_state == _vlc.State.Stopped:
                                    log.info("[STATE RACE] Stopped persisted after debounce, bailing: file=%s", getattr(self, "current_filepath", "?"))
                                    return
                                log.info("[STATE RACE] Stopped was stale, state now=%s -- continuing wait: file=%s", self._current_state, getattr(self, "current_filepath", "?"))
                                continue
                            if state in (_vlc.State.Playing, _vlc.State.Paused) and self._current_length > 0:
                                if is_disc_image and self._current_title < 1:
                                    _still_in_menu_at_timeout = True
                                    self._state_cond.wait(remaining_ms / 1000.0)
                                    continue
                                # WARNING: wait (bounded) for the first real frame before seeking, or the seek lands under an in-flight preroll frame.
                                _frame_grace_deadline = min(
                                    deadline, pygame.time.get_ticks() + _SEEK_FRAME_READY_GRACE_MS)
                                while (not self._frame_ready
                                       and pygame.time.get_ticks() < _frame_grace_deadline):
                                    if _superseded():
                                        log.info("[STATE RACE] _seek_when_ready superseded while "
                                                  "waiting for first frame, bailing: file=%s",
                                                  getattr(self, "current_filepath", "?"))
                                        return
                                    self._state_cond.wait(0.02)
                                if not self._frame_ready:
                                    log.info("[SEEK VERIFY] first frame never arrived within %dms -- "
                                              "seeking anyway: file=%s", _SEEK_FRAME_READY_GRACE_MS,
                                              getattr(self, "current_filepath", "?"))
                                _still_in_menu_at_timeout = False
                                break
                            self._state_cond.wait(remaining_ms / 1000.0)
                    if _timed_out:
                        if is_disc_image and _still_in_menu_at_timeout:
                            return
                    if _superseded():
                        log.info("[STATE RACE] _seek_when_ready superseded right before initial seek, bailing: file=%s", getattr(self, "current_filepath", "?"))
                        return
                    if self._closed:
                        log.info("[STATE RACE] _seek_when_ready: engine closed right before initial seek, bailing: file=%s", getattr(self, "current_filepath", "?"))
                        return
                    _opened_there = False
                    if opened_at_position:
                        _open_poll_t0 = pygame.time.get_ticks()
                        _not_published_logged = False
                        while True:
                            try:
                                _cur_at_open = self.player.get_time()
                            except Exception as _swallowed_error:
                                _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._seek_when_ready: _cur_at_open = self.player.get_time()", _swallowed_error)
                                _cur_at_open = None
                            if (_cur_at_open is not None and _cur_at_open >= 0
                                    and abs(_cur_at_open - target_ms) <= 1500):
                                _opened_there = True
                                log.info("[SEEK VERIFY] opened at the target via start-time, no seek needed: "
                                         "get_time()=%s target=%s file=%s", _cur_at_open, target_ms,
                                         getattr(self, "current_filepath", "?"))
                                break
                            if _cur_at_open is not None and _cur_at_open > 0:
                                log.info("[SEEK VERIFY] start-time at open did not take (get_time()=%s target=%s) "
                                         "-- seeking: file=%s", _cur_at_open, target_ms,
                                         getattr(self, "current_filepath", "?"))
                                break
                            if not _not_published_logged:
                                _not_published_logged = True
                                log.info("[SEEK VERIFY] start-time at open: VLC has not published a time yet "
                                         "(get_time()=%s target=%s) -- waiting: file=%s", _cur_at_open, target_ms,
                                         getattr(self, "current_filepath", "?"))
                            if pygame.time.get_ticks() - _open_poll_t0 >= _START_TIME_CONFIRM_MS:
                                log.info("[SEEK VERIFY] start-time at open never confirmed within %dms "
                                         "(get_time()=%s target=%s) -- seeking: file=%s", _START_TIME_CONFIRM_MS,
                                         _cur_at_open, target_ms, getattr(self, "current_filepath", "?"))
                                break
                            pygame.time.wait(_START_TIME_POLL_MS)
                            if _superseded():
                                log.info("[STATE RACE] _seek_when_ready superseded while confirming start-time, bailing: file=%s",
                                         getattr(self, "current_filepath", "?"))
                                return
                            if self._closed:
                                log.info("[STATE RACE] _seek_when_ready: engine closed while confirming start-time, bailing: file=%s",
                                         getattr(self, "current_filepath", "?"))
                                return
                    if not _opened_there:
                        self.player.set_time(target_ms)
                    _seek_verify_t0 = pygame.time.get_ticks()
                    if not _opened_there:
                        log.info("[SEEK VERIFY] seek requested: target_ms=%s file=%s", target_ms, getattr(self, "current_filepath", "?"))
                    _seek_deadline = pygame.time.get_ticks() + 3000
                    _last_set_time_at = pygame.time.get_ticks()
                    _SEEK_RETRY_INTERVAL_MS = SEEK_RETRY_INTERVAL_MS
                    _landed_at_ms = None
                    while pygame.time.get_ticks() < _seek_deadline:
                        if _superseded():
                            log.info("[STATE RACE] _seek_when_ready superseded during verify poll, bailing: file=%s", getattr(self, "current_filepath", "?"))
                            return
                        pygame.time.wait(150)
                        if self._closed:
                            log.info("[STATE RACE] _seek_when_ready: engine closed during verify poll, bailing: file=%s", getattr(self, "current_filepath", "?"))
                            return
                        try:
                            _cur = self.player.get_time()
                        except Exception as e:
                            log.warning("_seek_when_ready: get_time() failed during seek verification: %s", e)
                            break
                        _elapsed = pygame.time.get_ticks() - _seek_verify_t0
                        log.info("[SEEK VERIFY] +%sms poll: get_time()=%s target=%s delta=%s",
                                 _elapsed, _cur, target_ms, (None if _cur is None else _cur - target_ms))
                        if _cur is not None and _cur >= 0 and abs(_cur - target_ms) <= 1500:
                            _landed_at_ms = _elapsed
                            log.info("[SEEK VERIFY] landed close enough at +%sms (get_time()=%s)", _elapsed, _cur)
                            if getattr(self, "_pending_seek_generation", None) == generation:
                                self._pending_seek_generation = None
                            break
                        if pygame.time.get_ticks() - _last_set_time_at >= _SEEK_RETRY_INTERVAL_MS:
                            if self._closed:
                                log.info("[STATE RACE] _seek_when_ready: engine closed before retry set_time(), bailing: file=%s", getattr(self, "current_filepath", "?"))
                                return
                            try:
                                self.player.set_time(target_ms)
                                _last_set_time_at = pygame.time.get_ticks()
                                log.info("[SEEK VERIFY] +%sms re-issued set_time(%s)", _elapsed, target_ms)
                            except Exception as e:
                                log.warning("_seek_when_ready: retry set_time failed: %s", e)
                                break
                    else:
                        try:
                            _final = self.player.get_time()
                        except Exception as _swallowed_error:
                            _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._seek_when_ready: _final = self.player.get_time()", _swallowed_error)
                            _final = None
                        log.warning(
                            "_seek_when_ready: seek to %sms never landed within 3s (ended near %sms) -- "
                            "playback may start from the wrong position for this file.",
                            target_ms, _final)
                        if getattr(self, "_pending_seek_generation", None) == generation:
                            self._pending_seek_generation = None

                    if _landed_at_ms is not None:
                        for _post_delay_s in (1, 2, 4, 8):
                            pygame.time.wait(int(_post_delay_s * 1000) - 0)
                            if _superseded():
                                log.info("[SEEK VERIFY] post-check superseded, stopping: file=%s", getattr(self, "current_filepath", "?"))
                                return
                            if self._closed:
                                log.info("[SEEK VERIFY] post-check: engine closed, stopping: file=%s", getattr(self, "current_filepath", "?"))
                                return
                            try:
                                _post_cur = self.player.get_time()
                            except Exception as e:
                                log.warning("[SEEK VERIFY] post-check get_time() failed: %s", e)
                                break
                            _total_elapsed = pygame.time.get_ticks() - _seek_verify_t0
                            _expected = target_ms + _total_elapsed
                            log.info(
                                "[SEEK VERIFY] post-landing +%sms real: get_time()=%s expected~=%s "
                                "(target+elapsed) diff_from_expected=%s diff_from_elapsed_only=%s",
                                _total_elapsed, _post_cur, _expected,
                                (None if _post_cur is None else _post_cur - _expected),
                                (None if _post_cur is None else _post_cur - _total_elapsed),
                            )


                def stop(self, block=True):
                    """Stops playback and returns the _stop_done Event, which is set when player.stop() has finished."""
                    if not self.player:
                        return None
                    if self._wedged:
                        return None

                    self._seek_generation = getattr(self, "_seek_generation", 0) + 1

                    _stop_done = threading.Event()
                    _stop_err = []

                    def _do_stop():
                        try:
                            self.player.stop()
                        except Exception as _e:
                            _stop_err.append(_e)
                        finally:
                            _stop_done.set()

                    _t = threading.Thread(
                        target=_do_stop,
                        daemon=True,
                        name=f"vlc-stop-{self.engine_label}",
                    )
                    _t.start()

                    def _await_and_flag_if_wedged():
                        if _stop_done.wait(timeout=WEDGED_STOP_TIMEOUT_S):
                            if _stop_err:
                                log.warning("VLCEngineWrapper.stop(): player.stop() failed: %s", _stop_err[0])
                        else:
                            self._wedged = True
                            log.critical(
                                "[WEDGED-TEARDOWN] player.stop() on engine '%s' did not "
                                "return within %ss -- libVLC teardown is almost certainly "
                                "stalled on an unresponsive drive/device. Abandoning this engine "
                                "instance instead of blocking further; a replacement "
                                "engine will be created.",
                                self.engine_label, WEDGED_STOP_TIMEOUT_S,
                            )

                    # WARNING: main-loop callers must use block=False so a stalled drive cannot block input and rendering.
                    if block:
                        _await_and_flag_if_wedged()
                    else:
                        threading.Thread(
                            target=_await_and_flag_if_wedged,
                            daemon=True,
                            name=f"vlc-stop-watch-{self.engine_label}",
                        ).start()

                    return _stop_done

                def close(self):
                    """Releases this engine's libVLC player and instance."""
                    if self._closed:
                        return
                    self._closed = True

                    _release_done = threading.Event()
                    _release_err = []

                    def _do_release():
                        try:
                            if self.player is not None:
                                try:
                                    self.player.release()
                                except Exception as _e:
                                    _release_err.append(_e)
                            if self.instance is not None:
                                try:
                                    self.instance.release()
                                except Exception as _e:
                                    _release_err.append(_e)
                        finally:
                            _release_done.set()

                    _t = threading.Thread(
                        target=_do_release,
                        daemon=True,
                        name=f"vlc-close-{self.engine_label}",
                    )
                    _t.start()
                    if _release_done.wait(timeout=WEDGED_STOP_TIMEOUT_S):
                        if _release_err:
                            log.warning("VLCEngineWrapper.close(): release() raised: %s", _release_err[0])
                    else:
                        log.critical(
                            "[WEDGED-TEARDOWN] release() on engine '%s' did not "
                            "return within %ss -- abandoning it cleanly. The "
                            "process is exiting anyway, so this is logged for "
                            "diagnosis rather than retried.",
                            self.engine_label, WEDGED_STOP_TIMEOUT_S,
                        )

                _NAVIGATE_IDS = {
                    "activate": 0,
                    "up":       1,
                    "down":     2,
                    "left":     3,
                    "right":    4,
                    "popup":    5,
                }

                def _dvd_sig_log(self, msg):
                    with self._state_cond:
                        title = self._current_title
                    now = pygame.time.get_ticks()
                    log.info(
                        "[DVD SIGNAL] %s | title=%s confirmed_title=%s "
                        "ms_since_active=%d active_source=%s "
                        "ever_seen=%s ms_since_title_entered=%d",
                        msg, title, self._dvd_sig_confirmed_title,
                        now - self._dvd_sig_last_active_tick, self._dvd_sig_last_active_source,
                        self._dvd_sig_ever_seen, now - self._dvd_title_entered_at,
                    )

                def note_dvd_menu_signal_active(self, source):
                    prev_source = self._dvd_sig_last_active_source
                    self._dvd_sig_last_active_tick = pygame.time.get_ticks()
                    self._dvd_sig_last_active_source = source
                    self._dvd_sig_ever_seen = True
                    with self._state_cond:
                        self._dvd_sig_confirmed_title = self._current_title
                    self._dvd_sig_confirmed_title_source = source
                    if prev_source != source:
                        self._dvd_sig_log(f"window refreshed by '{source}'")

                def note_menu_activity(self):
                    self.note_dvd_menu_signal_active("time-jump")

                def _record_veto_evidence(self, title, source):
                    if title in self._dvd_flag_override_titles:
                        return False
                    now = pygame.time.get_ticks()
                    ev = self._dvd_sig_veto_evidence.get(title)
                    if ev is None or (now - ev["first_tick"]) > self._DVD_VETO_OVERRIDE_WINDOW_MS:
                        ev = {"count": 0, "first_tick": now}
                    ev["count"] += 1
                    self._dvd_sig_veto_evidence[title] = ev
                    if ev["count"] >= self._DVD_VETO_OVERRIDE_COUNT:
                        self._dvd_flag_override_titles.add(title)
                        self._dvd_sig_log(
                            f"title {title} flag-table veto OVERRIDDEN -- "
                            f"{ev['count']} corroborating '{source}' signals "
                            f"within {now - ev['first_tick']}ms despite disc's "
                            f"title-flags table saying menu=False (mislabeled "
                            f"disc, same pattern as EIKEN.iso) -- trusting "
                            f"this title like a real highlight from now on")
                        try:
                            self._ensure_menu_highlight_spu()
                        except Exception as e:
                            log.warning("_ensure_menu_highlight_spu (veto override) failed: %s", e)
                        return True
                    return False

                def record_time_jump_veto_evidence(self, title):
                    return self._record_veto_evidence(title, "time-jump")


                def navigate(self, direction):
                    if not self.player:
                        return

                    if direction == "activate":
                        pass

                    if direction == "menu":
                        try:
                            self.player.set_title(0)
                        except Exception as e:
                            log.warning("DVD set_title(0) (return-to-menu) failed: %s", e)
                        return
                    nav_id = self._NAVIGATE_IDS.get(direction)
                    if nav_id is None:
                        log.warning("DVD menu navigate(%s): unknown direction", direction)
                        return
                    try:
                        self.player.navigate(nav_id)
                        self._dvd_sig_log(f"navigate({direction}) sent to libVLC (nav_id={nav_id})")
                    except Exception as e:
                        log.warning("DVD menu navigate(%s) failed: %s", direction, e)

                def _current_title_is_menu_domain(self):
                    with self._state_cond:
                        title = self._current_title
                    if title < 1:
                        return True
                    if title in self._dvd_flag_override_titles:
                        return True
                    if self._dvd_sig_confirmed_title == title:
                        return True
                    _menu = self._title_is_menu(title)
                    return bool(_menu)

                def _ensure_menu_highlight_spu(self):
                    if not self.is_dvd_iso:
                        return
                    if not self.player:
                        return
                    try:
                        if not self._current_title_is_menu_domain():
                            return
                        current_spu = self.player.video_get_spu()
                        if current_spu is not None and current_spu >= 0:
                            return
                        track_id = None
                        try:
                            descriptions = self.player.video_get_spu_description()
                        except Exception as _swallowed_error:
                            _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._ensure_menu_highlight_spu: descriptions = self.player.video_get_spu_description()", _swallowed_error)
                            descriptions = None
                        if descriptions:
                            for desc in descriptions:
                                try:
                                    desc_id = desc[0]
                                except (TypeError, IndexError) as _swallowed_error:
                                    _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._ensure_menu_highlight_spu: desc_id = desc[0]", _swallowed_error)
                                    continue
                                if desc_id is not None and desc_id >= 0:
                                    track_id = desc_id
                                    break
                        if track_id is None:
                            count = self.player.video_get_spu_count()
                            if not count or count <= 0:
                                return
                            track_id = 0
                        self.player.video_set_spu(track_id)

                    except Exception as e:
                        log.warning("_ensure_menu_highlight_spu failed (non-fatal): %s", e)

                def is_menu_active(self):
                    if not self.player:
                        return False
                    with self._state_cond:
                        title = self._current_title
                    _menu = self._title_is_menu(title)
                    if _menu is not None:
                        result = _menu
                        result_reason = f"title-flags table says menu={_menu}"
                    else:
                        result = title < 1
                        result_reason = f"fallback: title<1 ({title})"
                    if result != self._dvd_menu_active_last_logged:
                        self._dvd_sig_log(f"is_menu_active() -> {result} ({result_reason})")
                        self._dvd_menu_active_last_logged = result
                    return result

                def _title_is_menu(self, title):
                    flags_map = self._dvd_title_menu_flags
                    if not flags_map:
                        flags_map = {}
                        try:
                            descs = self.player.get_full_title_descriptions()
                        except Exception as _swallowed_error:
                            _log_swallowed("initialize_vlc_on_demand.VLCEngineWrapper._title_is_menu: descs = self.player.get_full_title_descriptions()", _swallowed_error)
                            descs = None
                        if descs:
                            for i, d in enumerate(descs):
                                f = getattr(d, "flags", 0) or 0
                                flags_map[i] = bool(f & 0x3)
                            self._dvd_title_menu_flags = flags_map
                    if not flags_map:
                        return None
                    if title < 0:
                        return True
                    return flags_map.get(title, title < 1)

                def get_last_error(self):
                    try:
                        msg = vlc.libvlc_errmsg()
                        if msg:
                            return msg.decode("utf-8", "ignore") if isinstance(msg, bytes) else str(msg)
                    except Exception as e:
                        log.warning("get_last_error: libvlc_errmsg() call failed: %s", e)
                    return ""

                def get_recent_vlc_log(self, max_lines=15):
                    path = getattr(self, "_vlc_debug_log_path", None)
                    if not path or not os.path.exists(path):
                        return ""
                    try:
                        with open(path, "r", encoding="utf-8", errors="ignore") as f:
                            lines = f.readlines()
                    except Exception as e:
                        log.warning("get_recent_vlc_log: could not read %s: %s", path, e)
                        return ""
                    _keywords = ("dvdnav", "dvdread", "dvdcss", "css",
                                 "access", "demux", "error", "cannot", "fail")
                    relevant = [ln.rstrip("\n") for ln in lines[-300:]
                                if any(k in ln.lower() for k in _keywords)]
                    return "\n".join(relevant[-max_lines:])

                def clear_frame_buffer(self):
                    with self._frame_lock:
                        try:
                            _pixel_count = self.buf_size // 4
                            _opaque_black_row = bytes((0, 0, 0, 255)) * _pixel_count
                            ctypes.memmove(self.raw_buffer, _opaque_black_row, self.buf_size)
                        except Exception as e:
                            log.warning("clear_frame_buffer: opaque-black fill failed, "
                                        "falling back to memset (bars may be transparent): %s", e)
                            try:
                                ctypes.memset(self.raw_buffer, 0, self.buf_size)
                            except Exception as e2:
                                log.warning("clear_frame_buffer: ctypes.memset fallback also failed: %s", e2)
                        
                def set_volume(self, val, mute_flag=False):
                    if self.player:
                        curved = _perceptual_volume_pct(val, min_db=VLC_GAIN_MIN_DB)
                        _loudness_active = bool(db is not None and db.config.get("loudness_scan_enabled", True))
                        _applied_gain = self.file_gain if _loudness_active else 1.0
                        boosted = int(curved * _applied_gain)
                        _volume_ceiling = min(MAX_COMFORTABLE_VOLUME, VLC_VOLUME_CEILING)
                        self.player.audio_set_volume(0 if mute_flag else max(0, min(_volume_ceiling, boosted)))

                        try:
                            self.player.audio_set_mute(bool(mute_flag))
                        except Exception as e:
                            log.warning("set_volume: audio_set_mute sync failed: %s", e)
                        
                def _self_heal_native_dims(self):
                    """Main-thread safety net that clears a pending fill_full_canvas stretch."""
                    if not self._native_dims_pending:
                        return
                    if pygame.time.get_ticks() > self._native_dims_deadline_ms:
                        self._native_dims_pending = False
                        return
                    if self.is_dvd_iso or self._configured_screen_mode() not in ("normal", "crop", "panscan"):
                        self._native_dims_pending = False
                        return
                    dims = self._display_dims_from_player()
                    if not dims:
                        return
                    w, h = dims
                    if w <= 0 or h <= 0:
                        return
                    self._native_dims_pending = False
                    filepath = getattr(self, "current_filepath", None)
                    if filepath:
                        try:
                            _norm_fp = os.path.normpath(os.path.abspath(filepath))
                            self._dim_probe_cache[_norm_fp] = (w, h)
                            _save_file_probe_facts(_norm_fp, dims=(w, h))
                            if db is not None:
                                db.save_settings_async()
                        except Exception as e:
                            log.warning("_self_heal_native_dims: failed to persist dims for %s: %s", filepath, e)
                    log.info("[GEOMETRY REFRESH TRIGGER:%s] source=self_heal_main_thread file=%s dims=%sx%s", self.engine_label, filepath, w, h)
                    try:
                        self.refresh_screen_mode_geometry()
                    except Exception as e:
                        log.warning("_self_heal_native_dims: geometry reconfigure failed: %s", e)

                def get_display_frame(self):
                    import vlc as _vlc
                    self._self_heal_native_dims()
                    if self._native_dims_pending and not self.is_dvd_iso:
                        self._frame_ready = False
                        return None
                    s = self.player.get_state()
                    live = (_vlc.State.Playing, _vlc.State.Paused)
                    if s in live and self._frame_ready and self.raw_buffer is not None:
                        self._frame_ready = False
                        with self._frame_lock:
                            if self._decode_buffer is not None:
                                self._composite_letterboxed_frame()
                            _copy_t0 = time.perf_counter()
                            _out = bytes(self.raw_buffer)
                        _copy_ms = (time.perf_counter() - _copy_t0) * 1000.0
                        _stats = getattr(self, "_frame_copy_stats", None)
                        if _stats is None:
                            _stats = self._frame_copy_stats = [0, 0.0, 0.0]
                        _stats[0] += 1
                        _stats[1] += _copy_ms
                        _stats[2] = max(_stats[2], _copy_ms)
                        if _stats[0] >= FRAME_COPY_LOG_EVERY_FRAMES:
                            log.info("[FRAME COPY] %s frames=%d avg=%.2f ms max=%.2f ms size=%dx%d",
                                     self.engine_label, _stats[0], _stats[1] / _stats[0], _stats[2], self.width, self.height)
                            _stats[0], _stats[1], _stats[2] = 0, 0.0, 0.0
                        return _out
                    return None

                def has_pending_frame(self):
                    return bool(self._frame_ready)

            # WARNING: the module-level reference is required; without it a rebuild retries forever on a NameError.
            global _VLCEngineWrapperClass
            _VLCEngineWrapperClass = VLCEngineWrapper

            _vlc_main_t0 = time.perf_counter()
            vlc_engine = VLCEngineWrapper(engine_label="main")
            _vlc_main_s = time.perf_counter() - _vlc_main_t0
            
            log.info("[DEBUG VLC MASTER] Core framework ready and operational.")
            # WARNING: a windowed build (no console) has sys.stdout set to None, so the flush is skipped there; the handler flushes below are the ones that matter for the log file.
            if sys.stdout is not None:
                try:
                    sys.stdout.flush()
                except Exception as _swallowed_error:
                    _log_swallowed("initialize_vlc_on_demand: sys.stdout.flush()", _swallowed_error)
            for _h in logging.getLogger().handlers:
                try:
                    _h.flush()
                except Exception as _swallowed_error:
                    _log_swallowed("initialize_vlc_on_demand: _h.flush()", _swallowed_error)

            log.info("[DEBUG VLC MASTER] About to construct dedicated DVD engine (hw decode disabled)...")
            for _h in logging.getLogger().handlers:
                try:
                    _h.flush()
                except Exception as _swallowed_error:
                    _log_swallowed("initialize_vlc_on_demand: _h.flush()", _swallowed_error)
            try:
                _vlc_dvd_t0 = time.perf_counter()
                dvd_engine = VLCEngineWrapper(instance_args=vlc_args_dvd, engine_label="dvd")
                
                log.info("[DEBUG VLC MASTER] Dedicated DVD engine ready and operational.")
                log.info("[VLC] start-up took %.1f s: loading VLC %.1f s, main engine %.1f s, DVD engine %.1f s",
                         time.perf_counter() - _vlc_start_t0, _vlc_import_s, _vlc_main_s, time.perf_counter() - _vlc_dvd_t0)
                print("[DVD ENGINE] Menu navigation uses libVLC's native dvdnav "
                      "signal only (no app-side heuristics). Regular DVDs are "
                      "fully supported; interactive multi-path DVD 'games' "
                      "with unreliable disc menu metadata are not.")
            except Exception as e:
                log.warning(f"[VLC INITIALIZE FAILURE] DVD engine failed to initialize (main engine unaffected): {e}")
                log.warning("DVD engine failed to initialize (main engine unaffected): %s", e)
                dvd_engine = None

            if game_deck is not None and dvd_engine is not None:
                game_deck.vlc_engine = dvd_engine
                game_deck.dvd_gain_lookup = _get_or_queue_dvd_gain

        except Exception as e:
            log.warning(f"[VLC INITIALIZE FAILURE] Failed to load libVLC module hooks: {e}")
            vlc_engine = None
            dvd_engine = None

_dvd_probe_inflight = set()

# WARNING: DVD/disc playback is never loudness-scanned or gain-adjusted; a scan could only start mid-playback and interrupt it.
DVD_FIXED_GAIN = 1.0


