def _get_or_queue_dvd_gain(file_path):
    """Always returns DVD_FIXED_GAIN -- see its comment above."""
    return DVD_FIXED_GAIN


def _todays_holiday_key(d=None, channel_key=None):
    """Return the holiday key if the given date (default: today) falls in a holiday window or is forced on, else None; with a channel the force counts only when it is switched on for that channel, without one (the bezel) it counts when any channel has it on."""
    today = broadcast_clock.date()
    if db is None:
        forced = ""
    elif channel_key is None:
        forced = media.holiday_forced_key_global(db.config)
    else:
        forced = media.holiday_forced_key_for_channel(db.config, channel_key)
    return media.holiday_key_for_date(d or today, forced, today)


def _toggle_holiday_force(holiday_key, channel_key):
    """Switches the force for holiday_key on or off for every channel from any channel's menu; the bezel follows it; does nothing while that toggle is greyed."""
    if db is None or holiday_key not in media.HOLIDAY_KEYS:
        return False
    ch_key = str(channel_key).zfill(2)
    if not media.holiday_force_toggle(db.config, ch_key, holiday_key, list(db.channels_db.keys()), broadcast_clock.date()):
        return False
    # WARNING: the saved live anchor must stay: it holds the airing show or movie until it ends, and the channel changes over after that.
    app_state["guide_refresh_token"] = app_state.get("guide_refresh_token", 0) + 1
    db.save_settings_async()
    print(f"[HOLIDAY] Switched from channel {ch_key}: {holiday_key} force is now {'on' if media.holiday_forced_key_global(db.config) else 'off'} for every channel")
    return True


# WARNING: the fallback numbers below must match CHANNEL_READY_INTERVAL_SECONDS, CHANNEL_READY_CHANNEL_PAUSE_SECONDS, CHANNEL_READY_REFRESH_BATCH, CHANNEL_READY_WARM_BATCH, CHANNEL_READY_LOG_SECONDS in performance_governor.py; they are used only when that module fails to import.
CHANNEL_READY_INTERVAL_SECONDS = performance_governor.CHANNEL_READY_INTERVAL_SECONDS if performance_governor is not None else 2.0
CHANNEL_READY_CHANNEL_PAUSE_SECONDS = performance_governor.CHANNEL_READY_CHANNEL_PAUSE_SECONDS if performance_governor is not None else 0.05
CHANNEL_READY_REFRESH_BATCH = performance_governor.CHANNEL_READY_REFRESH_BATCH if performance_governor is not None else 400
CHANNEL_READY_WARM_BATCH = performance_governor.CHANNEL_READY_WARM_BATCH if performance_governor is not None else 400
CHANNEL_READY_LOG_SECONDS = performance_governor.CHANNEL_READY_LOG_SECONDS if performance_governor is not None else 60.0
_channel_ready_stats = {"builds": 0, "build_s": 0.0, "paths": 0, "rechecks": 0, "warmed": 0, "last_log": 0.0}


def _channel_ready_order():
    """The active TV channels, the one on air first, then the one on screen, the one highlighted in the guide and the one open in the file explorer, then the rest in number order."""
    if db is None:
        return []
    first = [str(app_state.get("_live_playback_channel", "") or ""), str(app_state.get("current_channel", "") or ""),
             str(app_state.get("highlighted_guide_channel", "") or ""),
             str((app_state.get("file_explorer_context") or {}).get("ch", "") or "")]
    order = []
    for key in [k.zfill(2) for k in first if k] + ["%02d" % i for i in range(5, 45)]:
        info = db.channels_db.get(key)
        if key in order or not info or not info.get("active", True) or info.get("is_visualizer", False):
            continue
        order.append(key)
    return order


def _channel_ready_lists(ch_info):
    """The schedule lists a channel reads right now: its live block and its commercials."""
    schedules = ch_info.get("schedules", {}) or {}
    out = []
    for name in (_compute_live_block_name(ch_info), "Commercials"):
        items = schedules.get(name)
        if items:
            out.append(items)
    return out


def _channel_ready_pass():
    """One pass of the channel-ready thread: re-checks what the screen thread used past its time, then makes each active channel's track build ready so the screen thread only compares the clock with it."""
    stats = _channel_ready_stats
    stats["paths"] += media.run_queued_path_refreshes(limit=CHANNEL_READY_REFRESH_BATCH)
    hub = media.get_duration_hub()
    if hub is not None and hasattr(hub, "run_queued_rechecks"):
        stats["rechecks"] += hub.run_queued_rechecks(limit=CHANNEL_READY_REFRESH_BATCH)
    lists = [items for ch_key in _channel_ready_order() for items in _channel_ready_lists(db.channels_db.get(ch_key) or {})]
    # WARNING: every first path check is done before any build; a check made after a build moves the path generation on and the build would be made again.
    for items in lists:
        if _app_shutting_down.is_set():
            return
        paths = [it.get("path", it.get("file", "")) if isinstance(it, dict) else str(it) for it in list(items)]
        stats["warmed"] += media.warm_path_statuses(paths, limit=CHANNEL_READY_WARM_BATCH)
    for items in lists:
        if _app_shutting_down.is_set():
            return
        if media.track_build_is_ready(items):
            continue
        t0 = time.monotonic()
        media.build_raw_tracks(items, media._cached_path_exists)
        media.build_pending_tracks(items, media._cached_path_exists)
        stats["builds"] += 1
        stats["build_s"] += time.monotonic() - t0
        if _app_shutting_down.wait(CHANNEL_READY_CHANNEL_PAUSE_SECONDS):
            return


def _channel_ready_worker():
    """ChannelReady thread (owner 2026-11-02, N1: "i want the info for that channel ready to go"): keeps every active channel's file facts and track build ready ahead so the screen thread never builds a lineup or waits on a drive."""
    while not _app_shutting_down.is_set():
        if db is not None and getattr(db, "ready_flag", False):
            try:
                _channel_ready_pass()
            except Exception as _ready_err:
                _log_warn_throttled("channel_ready_pass", "[CHANNEL READY] pass failed, the screen thread builds what it needs itself: %s", _ready_err)
            stats = _channel_ready_stats
            now = time.monotonic()
            if now - stats["last_log"] >= CHANNEL_READY_LOG_SECONDS:
                if stats["builds"] or stats["paths"] or stats["rechecks"] or stats["warmed"]:
                    log.info("[CHANNEL READY] last %.0fs: %d lineup build(s) made ready (%.1fs), %d path(s) re-checked and %d first checked, %d length(s) asked again, off the screen thread",
                             now - stats["last_log"] if stats["last_log"] else 0.0, stats["builds"], stats["build_s"],
                             stats["paths"], stats["warmed"], stats["rechecks"])
                stats.update(builds=0, build_s=0.0, paths=0, rechecks=0, warmed=0, last_log=now)
        _added_seen = _scan_files_added_generation[0]
        _until = time.monotonic() + CHANNEL_READY_INTERVAL_SECONDS
        while time.monotonic() < _until and _scan_files_added_generation[0] == _added_seen:
            if _app_shutting_down.wait(0.1):
                return


def _compute_live_block_name(ch_info):
    """Returns the schedule block name that is live right now for this channel, from its scheduling_mode/block_mode and the wall clock."""
    smode = ch_info.get("scheduling_mode", "random_slots")
    bmode = ch_info.get("block_mode", "full_day")
    now_h = broadcast_clock.now().hour
    if smode == "marathon":
        return "Marathon"
    if bmode == "full_day":
        return "Full Day"
    if bmode == "six_block":
        return SIX_HOUR_BLOCKS[now_h // 4][0]
    if 4 <= now_h < 12:
        return "Morning"
    elif 12 <= now_h < 20:
        return "Evening"
    else:
        return "Night"


def _fe_locked_playing_path(context):
    """Returns the normalized path of the file airing right now for this file-explorer session's channel, if the bucket being edited is the one on air."""
    if db is None:
        return ""
    mode   = context.get("mode", "")
    ch_key = context.get("ch", "")
    if not ch_key or mode not in ("schedule", "commercial", "holiday"):
        return ""
    ch_info = db.channels_db.get(ch_key, {})
    if not ch_info:
        return ""
    if mode == "commercial":
        is_live_bucket = ch_info.get("commercials_enabled", False)
    elif mode == "holiday":
        is_live_bucket = (context.get("hkey", "") == _todays_holiday_key(channel_key=ch_key))
    else:
        is_live_bucket = (context.get("block", "") == _compute_live_block_name(ch_info))
    if not is_live_bucket:
        return ""
    try:
        now_state = _get_probe_now_state(ch_key)
    except Exception as _swallowed_error:
        _log_swallowed("_fe_locked_playing_path: now_state = _get_probe_now_state(ch_key)", _swallowed_error)
        return ""
    cur_file = now_state.get("file", "") if isinstance(now_state, dict) else ""
    return os.path.normpath(cur_file) if cur_file else ""


def _fe_existing_schedule_paths(context):
    """Returns the normalized paths already scheduled for this file-explorer context's bucket, so _fe_open() can pre-check them."""
    if db is None:
        return []
    mode   = context.get("mode", "")
    if mode == "add_roms":
        ck = context.get("console_key", "")
        if not ck or game_deck is None:
            return []
        return [os.path.normpath(p) for p in game_deck.console_roms_manual.get(ck, []) if p]
    if mode == "ch03_menu_music":
        out = []
        for e in db.config.get("ch03_menu_music", []):
            p = e.get("path", "") if isinstance(e, dict) else str(e)
            if p:
                out.append(os.path.normpath(p))
        return out
    ch_key = context.get("ch", "")
    if not ch_key or mode not in ("schedule", "commercial", "holiday"):
        return []
    ch_data = db.channels_db.get(ch_key, {})
    if not ch_data:
        return []
    if mode == "holiday":
        entries = ch_data.get("holiday_schedules", {}).get(context.get("hkey", ""), [])
    else:
        block = context.get("block", "")
        if not block:
            return []
        entries = ch_data.get("schedules", {}).get(block, [])
    out = []
    for e in entries:
        p = e.get("path", e.get("file", "")) if isinstance(e, dict) else str(e)
        if p:
            out.append(os.path.normpath(p))
    return out


def _reconcile_schedule_entries(existing_entries, final_paths):
    """Turns a file-explorer session's desired file list into the new entries list for that schedule bucket; kept files retain their existing dict."""
    final_norm = []
    _seen_final = set()
    for p in final_paths:
        np_ = os.path.normpath(p)
        if np_ not in _seen_final:
            _seen_final.add(np_)
            final_norm.append(np_)

    by_path = {}
    for e in existing_entries:
        p = e.get("path", e.get("file", "")) if isinstance(e, dict) else str(e)
        if p:
            by_path[os.path.normpath(p)] = e if isinstance(e, dict) else {"path": p, "duration": -1}

    out = []
    used_names = set()
    added_paths = []
    dupe_skipped = 0
    for p in final_norm:
        if p in by_path:
            out.append(by_path[p])
            used_names.add(os.path.basename(p))
        else:
            name = os.path.basename(p)
            if name in used_names:
                dupe_skipped += 1
                continue
            used_names.add(name)
            out.append({"path": p, "duration": -1})
            added_paths.append(p)
    removed = len(by_path) - sum(1 for p in final_norm if p in by_path)
    return out, added_paths, removed, dupe_skipped


def _paths_from_entry(entry):
    if not isinstance(entry, dict):
        return [str(entry)] if entry else []
    if entry.get("is_pair"):
        out = []
        p1 = entry.get("pair_ep1_path", "")
        p2 = entry.get("pair_ep2_path", "")
        if p1:
            out.append(p1)
        if p2:
            out.append(p2)
        return out
    p = entry.get("path", entry.get("file", ""))
    return [p] if p else []


_ORDERED_CONTENT_CACHE = {}
# WARNING: the fallback numbers below must match ORDERED_CONTENT_CACHE_TTL_MS in performance_governor.py; they are used only when that module fails to import.
_ORDERED_CONTENT_CACHE_TTL_MS = performance_governor.ORDERED_CONTENT_CACHE_TTL_MS if performance_governor is not None else 8000
# WARNING: the fallback numbers below must match ORDERED_CONTENT_CACHE_PRUNE_EVERY_MS, ORDERED_CONTENT_CACHE_LAST_PRUNE_MS in performance_governor.py; they are used only when that module fails to import.
_ORDERED_CONTENT_CACHE_PRUNE_EVERY_MS = performance_governor.ORDERED_CONTENT_CACHE_PRUNE_EVERY_MS if performance_governor is not None else 60000
_ORDERED_CONTENT_CACHE_LAST_PRUNE_MS = performance_governor.ORDERED_CONTENT_CACHE_LAST_PRUNE_MS if performance_governor is not None else 0.0


def _prune_ordered_content_cache(now_ms):
    global _ORDERED_CONTENT_CACHE_LAST_PRUNE_MS
    if now_ms - _ORDERED_CONTENT_CACHE_LAST_PRUNE_MS < _ORDERED_CONTENT_CACHE_PRUNE_EVERY_MS:
        return
    _ORDERED_CONTENT_CACHE_LAST_PRUNE_MS = now_ms
    _stale_keys = [k for k, (_ts, _tracks, _bname) in _ORDERED_CONTENT_CACHE.items()
                   if now_ms - _ts >= _ORDERED_CONTENT_CACHE_TTL_MS]
    for k in _stale_keys:
        _ORDERED_CONTENT_CACHE.pop(k, None)


# WARNING: the fallback numbers below must match MIXER_SEEK_TEST_ENCODERS, MIXER_SEEK_TEST_SECONDS, MIXER_SEEK_TEST_POSITION in performance_governor.py; they are used only when that module fails to import.
_MIXER_SEEK_TEST_ENCODERS = performance_governor.MIXER_SEEK_TEST_ENCODERS if performance_governor is not None else { ".mp3": "libmp3lame", ".ogg": "libvorbis", ".opus": "libopus", ".flac": "flac", ".wav": "pcm_s16le", ".aif": "pcm_s16be", ".aiff": "pcm_s16be", ".m4a": "aac", ".aac": "aac", ".wma": "wmav2", }
_MIXER_SEEK_TEST_SECONDS = performance_governor.MIXER_SEEK_TEST_SECONDS if performance_governor is not None else 4
_MIXER_SEEK_TEST_POSITION = performance_governor.MIXER_SEEK_TEST_POSITION if performance_governor is not None else 1.0


def _mixer_seekable_formats():
    """Returns {extension: can_seek} for this SDL_mixer version, or an empty dict when the self-test has not run for it."""
    if db is None:
        return {}
    table = db.config.get("mixer_seekable_formats")
    try:
        mixer_version = list(pygame.mixer.get_sdl_mixer_version())
    except Exception as _swallowed_error:
        _log_swallowed("_mixer_seekable_formats: mixer_version = list(pygame.mixer.get_sdl_mixer_version())", _swallowed_error)
        return {}
    if not isinstance(table, dict) or table.get("version") != mixer_version:
        return {}
    return table.get("formats", {})


def _run_mixer_seek_selftest():
    """Tests once per SDL_mixer version, on an idle mixer with generated tones, which audio formats can start mid-way, and stores the result for the Visualizer lineup."""
    # WARNING: runs on the main thread before any music plays; the mixer's music stream is shared, so it is never run from a scan thread.
    if db is None or not pygame.mixer.get_init() or pygame.mixer.music.get_busy():
        return
    if app_state.get("music_owner"):
        return
    try:
        mixer_version = list(pygame.mixer.get_sdl_mixer_version())
    except Exception as _swallowed_error:
        _log_swallowed("mixer seek self-test: reading the SDL mixer version", _swallowed_error)
        return
    table = db.config.get("mixer_seekable_formats")
    if not isinstance(table, dict) or table.get("version") != mixer_version:
        table = {"version": mixer_version, "formats": {}}
    formats = table["formats"]
    pending = [ext for ext in _MIXER_SEEK_TEST_ENCODERS if ext not in formats]
    if not pending:
        return

    import subprocess
    popen_kwargs = {}
    if os.name == "nt":
        popen_kwargs["creationflags"] = subprocess.CREATE_NO_WINDOW
    test_dir = os.path.join(media.resolve_loudness_dir(), "seek_selftest")
    try:
        os.makedirs(test_dir, exist_ok=True)
        ffmpeg_path = media._resolve_ffmpeg_path()
    except Exception as e:
        log.warning("[SEEK SELFTEST] setup failed: %s", e)
        return

    volume = pygame.mixer.music.get_volume()
    try:
        pygame.mixer.music.set_volume(0.0)
        for ext in pending:
            test_path = os.path.join(test_dir, "tone" + ext)
            if not os.path.exists(test_path):
                try:
                    subprocess.run(
                        [ffmpeg_path, "-nostdin", "-hide_banner", "-y", "-f", "lavfi", "-i",
                         "sine=frequency=440:duration=%d" % _MIXER_SEEK_TEST_SECONDS,
                         "-c:a", _MIXER_SEEK_TEST_ENCODERS[ext], test_path],
                        capture_output=True, timeout=20, stdin=subprocess.DEVNULL, **popen_kwargs)
                except Exception as _swallowed_error:
                    _log_swallowed("_run_mixer_seek_selftest: subprocess.run( [ffmpeg_path, '-nostdin', '-hide_banner', '-", _swallowed_error)
                    continue
            if not os.path.exists(test_path) or os.path.getsize(test_path) == 0:
                continue
            can_seek = None
            try:
                pygame.mixer.music.load(test_path)
                try:
                    pygame.mixer.music.play(start=_MIXER_SEEK_TEST_POSITION)
                    can_seek = True
                except Exception as _swallowed_error:
                    _log_swallowed("_run_mixer_seek_selftest: pygame.mixer.music.play(start=_MIXER_SEEK_TEST_POSITION)", _swallowed_error)
                    pygame.mixer.music.play()
                    can_seek = False
            except Exception as e:
                log.info("[SEEK SELFTEST] %s cannot be played by this mixer: %s", ext, e)
            try:
                pygame.mixer.music.stop()
                pygame.mixer.music.unload()
            except Exception as _swallowed_error:
                _log_swallowed("_run_mixer_seek_selftest: pygame.mixer.music.stop()", _swallowed_error)
            if can_seek is not None:
                formats[ext] = can_seek
    finally:
        pygame.mixer.music.set_volume(volume)
    db.config["mixer_seekable_formats"] = table
    log.info("[SEEK SELFTEST] SDL_mixer %s: %s", mixer_version,
             {ext: ("seeks" if ok else "cannot seek") for ext, ok in formats.items()})
    try:
        db.save_settings_async()
    except Exception as e:
        log.warning("_run_mixer_seek_selftest: failed to persist results: %s", e)


def _visualizer_unseekable_paths():
    """Songs the mixer cannot start mid-way, excluded from every Visualizer lineup; the list resets when the SDL_mixer version changes."""
    if db is None:
        return {}
    try:
        mixer_version = list(pygame.mixer.get_sdl_mixer_version())
    except Exception as _swallowed_error:
        _log_swallowed("_visualizer_unseekable_paths: mixer_version = list(pygame.mixer.get_sdl_mixer_version())", _swallowed_error)
        mixer_version = None
    if db.config.get("visualizer_unseekable_mixer") != mixer_version:
        db.config["visualizer_unseekable"] = {}
        db.config["visualizer_unseekable_mixer"] = mixer_version
    return db.config.setdefault("visualizer_unseekable", {})


def _start_visualizer_music(file_path, seek_seconds):
    """Starts the loaded song at seek_seconds; returns True when playing, False when its format cannot seek and it was removed from every Visualizer lineup, and None when it cannot play."""
    # WARNING: a song is never started from 0 as a stand-in for its scheduled position.
    # WARNING: a failed seek removes the song only when a short seek also fails and a start from 0 works; a seek past the real end of the audio leaves the song in the lineup.
    seek_seconds = max(0.0, float(seek_seconds))
    try:
        if seek_seconds > 0.05:
            pygame.mixer.music.play(start=seek_seconds)
        else:
            pygame.mixer.music.play()
        app_state["_vis_react_track"] = os.path.normpath(str(file_path))
        app_state["_vis_react_seek"] = seek_seconds if seek_seconds > 0.05 else 0.0
        app_state["_vis_react_state"] = {}
        return True
    except Exception as seek_err:
        log.warning("[VISUALIZER CHANNEL] play(start=%.2f) failed for %s: %s",
                    seek_seconds, os.path.basename(str(file_path)), seek_err)
    try:
        volume = pygame.mixer.music.get_volume()
        pygame.mixer.music.set_volume(0.0)
        try:
            short_seek_ok = False
            try:
                pygame.mixer.music.play(start=1.0)
                short_seek_ok = True
            except Exception as _swallowed_error:
                _log_swallowed("_start_visualizer_music: pygame.mixer.music.play(start=1.0)", _swallowed_error)
                pygame.mixer.music.play()
            pygame.mixer.music.stop()
        finally:
            pygame.mixer.music.set_volume(volume)
    except Exception as start_err:
        log.warning("[VISUALIZER CHANNEL] %s cannot play: %s", os.path.basename(str(file_path)), start_err)
        return None
    if short_seek_ok:
        return None
    _visualizer_unseekable_paths()[os.path.normpath(str(file_path))] = True
    log.warning("[VISUALIZER CHANNEL] %s cannot seek and is removed from every Visualizer lineup",
                os.path.basename(str(file_path)))
    try:
        db.save_settings_async()
    except Exception as e:
        log.warning("_start_visualizer_music: failed to persist the unseekable list: %s", e)
    return False


def _visualizer_admission_inputs():
    """Returns (unseekable song paths, unseekable extensions) that decide which songs a Visualizer lineup admits."""
    unseekable = _visualizer_unseekable_paths()
    unseekable_exts = {ext for ext, ok in _mixer_seekable_formats().items() if ok is False}
    return unseekable, unseekable_exts


app_state["visualizer_admission_inputs"] = _visualizer_admission_inputs


_visualizer_lineup_lock = threading.Lock()


def _visualizer_frozen_lineup(ch_key, ch_info, now):
    """Returns the Visualizer channel's (track_list, total_seconds, origin_seconds) for today; the loop position is (seconds since midnight - origin_seconds) % total_seconds."""
    # WARNING: this is the ONLY place a Visualizer lineup is built; the scheduler, guide, watchdog, and scan threads all read it so they can never disagree.
    # WARNING: the lineup changes mid-day only when the channel's files change or a scanned length replaces an unmeasured one; the order is kept and the origin is recomputed then so the song airing right now keeps its exact position.
    stack = ch_info.get("schedules", {}).get("Music Tracks", [])
    unseekable, unseekable_exts = _visualizer_admission_inputs()
    assets = media.admit_visualizer_assets(stack, unseekable, unseekable_exts)
    if not assets:
        return [], 0, 0.0

    current_seconds = (now.hour * 3600 + now.minute * 60 + now.second
                       + now.microsecond / 1_000_000.0)
    day_key = "%d-%03d" % (now.year, now.timetuple().tm_yday)
    members = sorted({p for p, _a in assets})
    day_seed = now.year * 1000 + now.timetuple().tm_yday + int(str(ch_key).zfill(2)) + 400

    def _scanned_length(path):
        real, real_kind = media.read_track_duration(path, 0)
        return int(real) if real_kind == media.DURATION_MEASURED and real and real > 0 else None

    def _best_length(path, asset):
        real = _scanned_length(path)
        if real is not None:
            return real
        return int(asset["duration"])

    with _visualizer_lineup_lock:
        vlog = ch_info.setdefault("playback_log", {})
        lineup = vlog.get("visualizer_lineup")
        changed = False
        if (not isinstance(lineup, dict) or lineup.get("day") != day_key
                or not lineup.get("order")
                or any(not lineup.get("durations", {}).get(p, 0) for p in lineup.get("order", []))):
            order = [p for p, _a in assets]
            random.Random(day_seed).shuffle(order)
            lineup = {"day": day_key, "members": members, "order": order,
                      "durations": {p: _best_length(p, a) for p, a in assets}, "origin": 0.0}
            changed = True
        else:
            upgrades = {}
            for p in lineup.get("unmeasured", []):
                real = _scanned_length(p)
                if real is not None:
                    upgrades[p] = real
            if lineup.get("members") != members or upgrades:
                old_order = lineup["order"]
                old_durs = lineup["durations"]
                old_members = set(lineup.get("members", []))
                old_total = sum(old_durs[p] for p in old_order)
                old_pos = (current_seconds - lineup.get("origin", 0.0)) % old_total
                airing_idx, airing_seek, walked = 0, 0.0, 0
                for i, p in enumerate(old_order):
                    d = old_durs[p]
                    if walked + d > old_pos:
                        airing_idx, airing_seek = i, old_pos - walked
                        break
                    walked += d
                member_set = set(members)
                airing_survived = old_order[airing_idx] in member_set
                survivors_before = sum(1 for p in old_order[:airing_idx] if p in member_set)
                added = [p for p, _a in assets if p not in old_members]
                random.Random(day_seed).shuffle(added)
                new_order = [p for p in old_order if p in member_set] + added
                asset_by_path = {}
                for p, a in assets:
                    asset_by_path.setdefault(p, a)
                new_durs = {}
                for p in members:
                    if p in upgrades:
                        new_durs[p] = upgrades[p]
                    elif p in old_members and p in old_durs:
                        new_durs[p] = old_durs[p]
                    else:
                        new_durs[p] = _best_length(p, asset_by_path.get(p, {}))
                new_total = sum(new_durs[p] for p in new_order)
                new_idx = survivors_before % len(new_order)
                new_start = sum(new_durs[p] for p in new_order[:new_idx])
                new_seek = airing_seek if airing_survived else 0.0
                lineup["members"] = members
                lineup["order"] = new_order
                lineup["durations"] = new_durs
                lineup["origin"] = (current_seconds - (new_start + new_seek)) % new_total
                changed = True
        if changed:
            lineup["unmeasured"] = [p for p in members if _scanned_length(p) is None]
            vlog["visualizer_lineup"] = lineup
            if lineup["unmeasured"]:
                log.info("[VISUALIZER SCHEDULE] ch%s: %d track(s) await a scanned length: %s", ch_key,
                         len(lineup["unmeasured"]), [os.path.basename(e) for e in lineup["unmeasured"]])
            try:
                db.save_settings_async()
            except Exception as e:
                log.warning("_visualizer_frozen_lineup: failed to persist lineup for ch%s: %s", ch_key, e)
        durs = lineup["durations"]
        track_list = [{"path": p, "duration": durs[p]} for p in lineup["order"]]
        return track_list, sum(t["duration"] for t in track_list), float(lineup.get("origin", 0.0))


def _airing_block_name(ch_info, now):
    """The name of the block airing now on a channel: Marathon, Full Day, the four-hour block or the eight-hour block."""
    if ch_info.get("scheduling_mode", "random_slots") == "marathon":
        return "Marathon"
    block_mode = ch_info.get("block_mode", "full_day")
    if block_mode == "full_day":
        return "Full Day"
    if block_mode == "six_block":
        return SIX_HOUR_BLOCKS[now.hour // 4][0]
    return "Morning" if 4 <= now.hour < 12 else ("Evening" if 12 <= now.hour < 20 else "Night")


def _get_channel_ordered_content(ch_key, ch_info):
    now = broadcast_clock.now().replace(tzinfo=None)

    if ch_info.get("is_visualizer", False):
        track_list, _total, _origin = _visualizer_frozen_lineup(ch_key, ch_info, now)
        if not track_list:
            return [], None
        return track_list, "Music Tracks"

    block_name = _airing_block_name(ch_info, now)

    if block_name == "Marathon":
        folder_items = ch_info.get("schedules", {}).get("Marathon", [])
        ordered = build_ordered_tracks(folder_items, "marathon", _marathon_start_seed(ch_info) if folder_items else 0)
        if not ordered:
            return [], None
        return ordered, "Marathon"

    return _get_block_ordered_content(ch_key, ch_info, block_name, now)


# ============================================================================
# SECTION: Per-block lineups
# ============================================================================


def _block_names_after_airing(ch_info, now):
    """The block names of the channel's scheduling mode that air after the current one, in airing order; empty for visualizer, Marathon and Full Day channels."""
    if ch_info.get("is_visualizer", False):
        return []
    if ch_info.get("scheduling_mode", "random_slots") == "marathon":
        return []
    bmode = ch_info.get("block_mode", "full_day")
    if bmode == "full_day":
        return []
    if bmode == "six_block":
        names = list(SIX_HOUR_BLOCK_NAMES)
        cur = now.hour // 4
    else:
        names = ["Morning", "Evening", "Night"]
        cur = 0 if 4 <= now.hour < 12 else (1 if 12 <= now.hour < 20 else 2)
    return [names[(cur + k) % len(names)] for k in range(1, len(names))]


def _get_block_ordered_content(ch_key, ch_info, block_name, now, peek_only=False):
    """The airing-order lineup of one named block of a channel, kept for a few seconds; it never changes the channel's saved show positions, and peek_only is accepted and changes nothing."""
    folder_items = ch_info.get("schedules", {}).get(block_name, [])

    _occ_now_ms = time.monotonic() * 1000.0
    _prune_ordered_content_cache(_occ_now_ms)
    _occ_key = (str(ch_key), block_name, len(folder_items))
    _occ_hit = _ORDERED_CONTENT_CACHE.get(_occ_key)
    if _occ_hit is not None:
        _occ_ts, _occ_tracks, _occ_bname = _occ_hit
        if (_occ_now_ms - _occ_ts) < _ORDERED_CONTENT_CACHE_TTL_MS:
            return _occ_tracks, _occ_bname

    video_tracks, _lineup_block = read_block_lineup(
        ch_key, ch_info, block_name, now, _cached_path_exists, _start_order_seed,
        peek_only=peek_only,
    )
    _ORDERED_CONTENT_CACHE[_occ_key] = (_occ_now_ms, video_tracks, _lineup_block)
    return video_tracks, _lineup_block


_intro_seed_lock = threading.Lock()


def _channel_intro_seed(ch_info):
    """The channel's saved random start number, drawn from the operating system the first time the channel is scheduled with media; clearing the channel's media or settings removes it, so the next start is drawn fresh."""
    # WARNING: every reader of a channel's starting order must take the seed from here so the scheduler, guide and next-up lists never disagree.
    with _intro_seed_lock:
        _plog = ch_info.get("playback_log")
        if not isinstance(_plog, dict):
            _plog = ch_info["playback_log"] = {}
        _seed = _plog.get("intro_seed")
        if not isinstance(_seed, int) or isinstance(_seed, bool):
            _seed = random.SystemRandom().getrandbits(48)
            _plog["intro_seed"] = _seed
            try:
                if db is not None:
                    db.save_settings_async()
            except Exception as e:
                log.warning("_channel_intro_seed: failed to persist the start number: %s", e)
    return _seed


def _start_order_seed(ch_info, block_offset):
    """The seed for a block's first show order and first movie draw: the channel's saved start number plus the block, never the date."""
    return "%d:%d" % (_channel_intro_seed(ch_info), int(block_offset))


def _marathon_start_seed(ch_info):
    """The seed for a marathon channel's series order: the channel's saved start number, never the channel number or the date."""
    return "%d:marathon" % _channel_intro_seed(ch_info)


def _next_n_from_ordered(ordered, current_file, n=4):
    if not ordered:
        return []
    start_idx = 0
    for i, e in enumerate(ordered):
        if current_file and current_file in _paths_from_entry(e):
            start_idx = i
            break
    L = len(ordered)
    return [ordered[(start_idx + k) % L] for k in range(min(n, L))]


def _next_n_from_block_timeline(ch_str, current_file, n=4):
    """Returns up to n upcoming (path, is_commercial) items in true broadcast order for the block airing on ch_str, or None if no usable cached timeline exists."""
    # WARNING: returns None, never [], when the cache is unusable; callers tell a cache miss from an empty block by it.
    cached = _probe_block_timeline_cache.get(ch_str)
    if not cached or not cached.get("items"):
        return None
    items = cached["items"]
    start_idx = None
    if current_file:
        norm_cur = os.path.normpath(current_file)
        now_entry = cached.get("now")
        if now_entry and now_entry[0] == norm_cur:
            # WARNING: a commercial airs many times a block; the item airing now is found by its place in the block, never by its first airing (owner 2026-11-02, N5: the break's later commercials got no picture box).
            for i, it in enumerate(items):
                if (it.get("path") and os.path.normpath(it["path"]) == norm_cur
                        and it.get("start_time") == now_entry[1]):
                    start_idx = i
                    break
    if current_file and start_idx is None:
        for i, it in enumerate(items):
            if it.get("path") and os.path.normpath(it["path"]) == norm_cur:
                start_idx = i
                break
    if start_idx is None:
        return None
    return items[start_idx:start_idx + n]


_priming_inflight = set()
_priming_inflight_lock = threading.Lock()


# ============================================================================
# SECTION: Duration & loudness priming
# ============================================================================


def _prime_one_missing_duration(ch_str, item, priority=False):
    """Probes and stores one entry's real duration; returns 1 when a duration was stored, else 0."""
    p, np_ = item
    _cached = _read_file_probe_facts(np_)
    if _cached.get("duration") and _cached.get("duration") > 0:
        return 0
    if not _cached_path_exists(p):
        return 0
    try:
        if priority:
            with _governor_priority_scope():
                _dur = _probe_duration_guarded(np_)
        else:
            _dur = _probe_duration_guarded(np_)
    except Exception as e:
        log.warning("[TUNE PRIME] ch%s: duration probe failed for %s: %s", ch_str, os.path.basename(str(p)), e)
        _dur = None
    if _dur and _dur > 0:
        _save_file_probe_facts(np_, duration=_dur)
        return 1
    return 0


def _prime_missing_durations(ch_str, missing, pace=True):
    """Probes real durations for `missing` [(path, norm_path), ...] entries and saves each result in the library; an unpaced call (the boot start) is first-scan work, run in a priority scope and on several threads when the governor says this PC can spare them."""
    _t0 = time.monotonic()
    if pace:
        _probed = 0
        for _i, item in enumerate(missing):
            _probed += _prime_one_missing_duration(ch_str, item)
            if _i < len(missing) - 1:
                time.sleep(0.5)
        return _probed, time.monotonic() - _t0
    _workers = 1
    if len(missing) > 1 and performance_governor is not None and performance_governor.first_start_scans_concurrent():
        _workers = max(1, min(len(missing), performance_governor.duration_workers()))
    if _workers > 1:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=_workers, thread_name_prefix="prime-duration") as _pool:
            _probed = sum(_pool.map(lambda item: _prime_one_missing_duration(ch_str, item, priority=True), missing))
    else:
        _probed = sum(_prime_one_missing_duration(ch_str, item, priority=True) for item in missing)
    return _probed, time.monotonic() - _t0


def _prime_channel_block_durations_worker(ch_str, missing):
    # WARNING: missing[0] is what is on air (or must air first); it is probed at once in a priority scope so the channel leaves Static in about a second, never queued behind the paced scan of the files after it.
    _t_first = time.monotonic()
    _first_probed = _prime_one_missing_duration(ch_str, missing[0], priority=True)
    _probed = _first_probed
    if len(missing) > 1:
        _probed += _prime_missing_durations(ch_str, missing[1:], pace=True)[0]
    _elapsed = time.monotonic() - _t_first
    if _probed:
        print(f"[TUNE PRIME] ch{ch_str}: background-probed {_probed} near-term duration(s) "
              f"in {_elapsed:.2f}s (off the main thread -- "
              f"calculate_slotted_playback_state's stale-lineup rebuild picks up the "
              f"correction on its next call, same as any other background-probe catch-up)")
    with _priming_inflight_lock:
        _priming_inflight.discard(ch_str)


# WARNING: the fallback numbers below must match PRIME_DURATIONS_NEAR_TERM_N in performance_governor.py; they are used only when that module fails to import.
# WARNING: keep in sync with the "near-term" wording in this function's log line.
_PRIME_DURATIONS_NEAR_TERM_N = performance_governor.PRIME_DURATIONS_NEAR_TERM_N if performance_governor is not None else 8

def _prime_channel_block_durations(ch_key, synchronous=False):
    """Tune-in duration priming for a channel's *near-term* lineup."""
    if db is None:
        return
    ch_str = str(ch_key).zfill(2)
    ch_info = db.channels_db.get(ch_str, {})
    if not ch_info or not ch_info.get("active", True):
        return
    try:
        ordered, _block_key = _get_channel_ordered_content(ch_str, ch_info)
    except Exception as e:
        log.warning("_prime_channel_block_durations: ordered-content peek failed for ch%s: %s", ch_str, e)
        return
    paths = []
    _seen = set()
    if not ordered:
        # WARNING: a channel with no lineup has no file with a known duration; its first unscanned files are probed so it can leave Static.
        if ch_info.get("is_visualizer", False):
            return
        _no_lineup_broken = set(ch_info.get("broken_files", []))
        _no_lineup_block = _airing_block_name(ch_info, broadcast_clock.now().replace(tzinfo=None))
        for _track in build_pending_tracks(ch_info.get("schedules", {}).get(_no_lineup_block, []), _cached_path_exists):
            if _track["path"] in _no_lineup_broken:
                continue
            np_ = os.path.normpath(_track["path"])
            if np_ not in _seen:
                _seen.add(np_)
                paths.append((_track["path"], np_))
            if len(paths) >= _PRIME_DURATIONS_NEAR_TERM_N:
                break
    else:
        _now_state = _get_probe_now_state(ch_str)
        _current_file = _now_state.get("file", "")
        near_term = _next_n_from_ordered(ordered, _current_file, n=_PRIME_DURATIONS_NEAR_TERM_N)
        for entry in near_term:
            for p in _paths_from_entry(entry):
                if not p:
                    continue
                np_ = os.path.normpath(p)
                if np_ not in _seen:
                    _seen.add(np_)
                    paths.append((p, np_))

    missing = []
    for p, np_ in paths:
        _cached = _read_file_probe_facts(np_)
        if not (_cached.get("duration") and _cached.get("duration") > 0):
            missing.append((p, np_))
    if not missing:
        return

    if synchronous:
        _probed, _elapsed = _prime_missing_durations(ch_str, missing, pace=False)
        if _probed:
            print(f"[TUNE PRIME] ch{ch_str}: boot-probed {_probed} near-term duration(s) "
                  f"in {_elapsed:.2f}s before computing initial playback state")
        return

    with _priming_inflight_lock:
        if ch_str in _priming_inflight:
            return
        _priming_inflight.add(ch_str)
    threading.Thread(
        target=_prime_channel_block_durations_worker,
        args=(ch_str, missing),
        daemon=True,
        name=f"prime-ch{ch_str}",
    ).start()


_loudness_priming_inflight = set()
_loudness_priming_lock = threading.Lock()
# WARNING: the fallback number must match LOUDNESS_PRIME_AT_ONCE in performance_governor.py; it is used only when that module fails to import.
_LOUDNESS_PRIME_AT_ONCE = performance_governor.LOUDNESS_PRIME_AT_ONCE if performance_governor is not None else 2
_loudness_prime_turns = threading.BoundedSemaphore(_LOUDNESS_PRIME_AT_ONCE)

_loudness_priority_count = 0
_loudness_priority_lock = threading.Lock()
_LOUDNESS_PRIORITY_PENDING = threading.Event()


def _mark_loudness_priority_active():
    global _loudness_priority_count
    with _loudness_priority_lock:
        _loudness_priority_count += 1
        _LOUDNESS_PRIORITY_PENDING.set()


def _mark_loudness_priority_done():
    global _loudness_priority_count
    with _loudness_priority_lock:
        _loudness_priority_count = max(0, _loudness_priority_count - 1)
        if _loudness_priority_count == 0:
            _LOUDNESS_PRIORITY_PENDING.clear()


def _prime_channel_block_loudness(ch_key, current_file, current_block):
    """Gain counterpart to _prime_channel_block_durations() above."""
    if db is None or not current_file:
        return
    ch_str = str(ch_key).zfill(2)
    if _channel_is_server_streamed(ch_str):
        # WARNING: server-owned gains; never scan streamed channels.
        return
    if db.channels_db.get(ch_str, {}).get("is_visualizer", False):
        return
    try:
        norm_p = os.path.normpath(current_file)
    except Exception as _swallowed_error:
        _log_swallowed("_prime_channel_block_loudness: norm_p = os.path.normpath(current_file)", _swallowed_error)
        return
    if not _cached_path_exists(norm_p):
        return
    if _read_file_probe_facts(norm_p).get("gain") is not None:
        return
    if _loudness_probe_in_cooldown(norm_p):
        return

    _prime_key = (ch_str, norm_p)
    with _loudness_priming_lock:
        if _prime_key in _loudness_priming_inflight:
            return
        _loudness_priming_inflight.add(_prime_key)

    def _worker():
        # WARNING: the scan starts only once the channel has stayed on screen the governor's settle seconds; flipping through channels on a 4-core PC started a scan of 5 to 8 ffmpeg windows on every channel passed (48 at once in the owner's log).
        _settle = performance_governor.tune_loudness_settle_seconds() if performance_governor is not None else 0.0
        if _settle > 0 and _app_shutting_down.wait(_settle):
            with _loudness_priming_lock:
                _loudness_priming_inflight.discard(_prime_key)
            return
        if str(app_state.get("current_channel", "")).zfill(2) != ch_str:
            with _loudness_priming_lock:
                _loudness_priming_inflight.discard(_prime_key)
            log.info("[TUNE PRIME] ch%s: left within %.1fs, its first loudness scan is not started", ch_str, _settle)
            return
        # WARNING: tune-in loudness scans run at priority and are never held by the governor, so they take turns: at most _LOUDNESS_PRIME_AT_ONCE at once (the channel on screen plus one it just left), and a scan still waiting its turn when the viewer leaves is dropped. Owner log 2026-11-06 had 8 of them standing at once, 24 ffmpeg windows on a 4-core PC.
        while not _loudness_prime_turns.acquire(timeout=1.0):
            if _app_shutting_down.is_set() or str(app_state.get("current_channel", "")).zfill(2) != ch_str:
                with _loudness_priming_lock:
                    _loudness_priming_inflight.discard(_prime_key)
                log.info("[TUNE PRIME] ch%s: left while waiting its turn, its first loudness scan is not started", ch_str)
                return
        _mark_loudness_priority_active()
        try:
            if str(app_state.get("current_channel", "")).zfill(2) == ch_str:
                _probe_and_apply_loudness_blocking(
                    "channel", ch_str, current_block or "Full Day", norm_p,
                    "tune-in priority scan", priority=True)
        finally:
            with _loudness_priming_lock:
                _loudness_priming_inflight.discard(_prime_key)
            _mark_loudness_priority_done()
            _loudness_prime_turns.release()

    threading.Thread(target=_worker, daemon=True, name=f"prime-gain-ch{ch_str}").start()


def _prime_visualizer_lookahead_loudness(ch_key, current_file):
    """Keeps a Visualizer channel's next-3-songs loudness buffer topped up as its playlist advances."""
    if db is None:
        return
    ch_str = str(ch_key).zfill(2)
    ch_info = db.channels_db.get(ch_str, {})
    if not ch_info or not ch_info.get("is_visualizer", False) or ch_info.get("server_locked", False):
        return
    try:
        ordered, block_key = _get_channel_ordered_content(ch_str, ch_info)
    except Exception as _swallowed_error:
        _log_swallowed("_prime_visualizer_lookahead_loudness: ordered, block_key = _get_channel_ordered_content(ch_str, ch", _swallowed_error)
        return

    _targets = []
    for entry in _next_n_from_ordered(ordered, current_file, n=4):
        for p in _paths_from_entry(entry):
            if not (p and _cached_path_exists(p)):
                continue
            norm_p = os.path.normpath(p)
            if _read_file_probe_facts(norm_p).get("gain") is not None:
                continue
            if _loudness_probe_in_cooldown(norm_p):
                continue
            if norm_p not in _targets:
                _targets.append(norm_p)
    if not _targets:
        return

    _lookahead_key = (ch_str, tuple(_targets))
    with _loudness_priming_lock:
        if _lookahead_key in _loudness_priming_inflight:
            return
        _loudness_priming_inflight.add(_lookahead_key)

    def _worker():
        _mark_loudness_priority_active()
        try:
            for norm_p in _targets:
                _probe_and_apply_music_loudness_blocking(
                    "channel", ch_str, block_key or "Music Tracks", norm_p,
                    "lookahead top-up scan")
        finally:
            with _loudness_priming_lock:
                _loudness_priming_inflight.discard(_lookahead_key)
            _mark_loudness_priority_done()

    threading.Thread(target=_worker, daemon=True, name=f"prime-lookahead-ch{ch_str}").start()


def _probe_and_apply_loudness_blocking(kind, ch_key, block_key, norm_p, tag, chunk_timeout=None,
                                        semaphore_timeout=None, priority=False):
    """Blocking single-file scan-and-apply for TV stations and TV guide previews."""
    if not norm_p or not _cached_path_exists(norm_p):
        return None
    if _read_file_probe_facts(norm_p).get("gain") is not None:
        return None
    if _loudness_probe_in_cooldown(norm_p):
        return None
    if _is_drive_degraded(norm_p):
        log.info("_probe_and_apply_loudness_blocking: skipping %s -- its drive looks degraded", os.path.basename(norm_p))
        return None
    _pb_thread = None
    _together, _together_why = (performance_governor.first_start_scan_plan()
                                if performance_governor is not None else (False, "no governor"))
    if priority and _together:
        _pb_thread = threading.Thread(target=_picture_box_before_loudness, args=(norm_p,), daemon=True,
                                      name="first-scan-picbox")
        _pb_thread.start()
        log.info("[FIRST START] ch%s %s: picture box and loudness scans start together (%s)",
                 ch_key, os.path.basename(norm_p), _together_why)
    else:
        if priority:
            log.info("[FIRST START] ch%s %s: picture box first, then loudness (%s)",
                     ch_key, os.path.basename(norm_p), _together_why)
        _picture_box_before_loudness(norm_p)
    try:
        _shortfall = {}
        _extra_kwargs = {}
        if chunk_timeout is not None:
            _extra_kwargs["chunk_timeout"] = chunk_timeout
        if semaphore_timeout is not None:
            _extra_kwargs["semaphore_timeout"] = semaphore_timeout
        if priority:
            _extra_kwargs["semaphore"] = media._LOUDNESS_PRIORITY_SEMAPHORE
        _extra_kwargs["parallel_windows"] = True
        _extra_kwargs["raise_on_no_audio"] = (kind == "channel")
        with _governor_priority_scope():
            gain = _probe_loudness_guarded(norm_p, out_shortfall=_shortfall,
                                           treat_fallback_as_unknown=True, **_extra_kwargs)
    except NoAudioStreamError as _naerr:
        _no_audio_reason = getattr(_naerr, "reason", "no audio track")
        if kind == "channel":
            if _drop_media_from_pool(ch_key, block_key, norm_p, _no_audio_reason):
                print(f"[LOUDNESS PROBE] ch{ch_key} {tag}: '{os.path.basename(norm_p)}' rejected from the pool -- {_no_audio_reason}")
                try:
                    db.save_settings_async()
                except Exception as _save_err:
                    log.warning("_probe_and_apply_loudness_blocking: settings save after no-audio rejection failed: %s", _save_err)
            else:
                _mark_confirmed_no_audio(norm_p, _no_audio_reason)
        return None
    except Exception as e:
        log.warning("_probe_and_apply_loudness_blocking: probe failed for %s (%s): %s", ch_key, norm_p, e)
        return None
    finally:
        if _pb_thread is not None:
            _pb_thread.join()
    if gain:
        _patch_probed_gain(kind, ch_key, block_key, norm_p, gain=gain, duration=None)
    if gain:
        _label = f"ch{ch_key}" if ch_key else kind
        _measured = _shortfall.get("measured_lufs")
        _lufs_note = f" (measured {_measured:.1f} LUFS)" if _measured is not None else ""
        print(f"[LOUDNESS PROBE] {_label} {tag}: '{os.path.basename(norm_p)}' -> gain x{gain:.2f}{_lufs_note}")
    return gain



def _probe_and_apply_music_loudness_blocking(kind, ch_key, block_key, norm_p, tag):
    """Music counterpart using the dedicated music loudness scanner."""
    if not norm_p or not _cached_path_exists(norm_p):
        return None
    _blocking_cached = _read_file_probe_facts(norm_p)
    if (_blocking_cached.get("gain") is not None
            and ((_blocking_cached.get("duration") or 0) > 0
                 or norm_p in _music_duration_scan_attempted)):
        return None
    if _loudness_probe_in_cooldown(norm_p):
        return None
    try:
        _shortfall = {}
        _scan_duration = {}
        gain = _probe_music_loudness_guarded(
            norm_p, out_shortfall=_shortfall,
            treat_fallback_as_unknown=True, duration_out=_scan_duration)
    except Exception as e:
        log.warning("_probe_and_apply_music_loudness_blocking: probe failed for %s (%s): %s",
                    ch_key, norm_p, e)
        return None
    _music_duration_scan_attempted.add(norm_p)
    if gain or _scan_duration.get("duration_sec"):
        _patch_probed_gain(kind, ch_key, block_key, norm_p, gain=(gain or None),
                           duration=_scan_duration.get("duration_sec"))
    if gain:
        _label = f"ch{ch_key}" if ch_key else kind
        _measured = _shortfall.get("measured_lufs")
        _lufs_note = f" (measured {_measured:.1f} LUFS)" if _measured is not None else ""
        print(f"[LOUDNESS PROBE] {_label} {tag}: '{os.path.basename(norm_p)}' -> gain x{gain:.2f} (music target){_lufs_note}")
    return gain


# ============================================================================
# SECTION: First-pass now-playing loudness sweep
# ============================================================================


def _first_scheduled_target_for_channel(ch_str, ch_info):
    """The first scheduled item for a channel, scanned immediately when the channel is created mid-sweep."""
    try:
        ordered, block_key = _get_channel_ordered_content(ch_str, ch_info)
    except Exception as e:
        log.warning("_first_scheduled_target_for_channel: ordered-content peek "
                    "failed for ch%s: %s", ch_str, e)
        return None, None
    if not ordered:
        return None, None
    for p in _paths_from_entry(ordered[0]):
        if p and os.path.exists(p):
            norm_p = os.path.normpath(p)
            if _read_file_probe_facts(norm_p).get("gain") is None:
                return block_key, norm_p
    return None, None


def _snapshot_now_playing_loudness_targets():
    """Every audio target that is airing right now, or is the default starting point for something not yet live."""
    out = {}
    if db is None:
        return out

    for i in range(5, 45):
        ch_str = str(i).zfill(2)
        ch_info = db.channels_db.get(ch_str, {})
        if not ch_info or not ch_info.get("active", True):
            continue
        if ch_info.get("server_locked", False):
            continue
        if ch_info.get("is_visualizer", False):
            continue
        now_state = _get_probe_now_state(ch_str)
        current_file = now_state.get("file", "")
        if not current_file or not os.path.exists(current_file):
            continue
        norm_p = os.path.normpath(current_file)
        if _read_file_probe_facts(norm_p).get("gain") is not None:
            continue
        try:
            _ordered, block_key = _get_channel_ordered_content(ch_str, ch_info)
        except Exception as _swallowed_error:
            _log_swallowed("_snapshot_now_playing_loudness_targets: _ordered, block_key = _get_channel_ordered_content(ch_str, ch_info)", _swallowed_error)
            block_key = "Full Day"
        out[f"ch{ch_str}"] = ("channel", ch_str, block_key or "Full Day", norm_p)

    return out



# WARNING: the fallback numbers below must match SWEEP_SKIP_BACKOFF_SECONDS in performance_governor.py; they are used only when that module fails to import.
_SWEEP_SKIP_BACKOFF_SECONDS = performance_governor.SWEEP_SKIP_BACKOFF_SECONDS if performance_governor is not None else 1.0


# WARNING: the fallback numbers below must match LOUDNESS_SWEEP_WAIT_FOR_INFO_SCANS_MAX_SECONDS and LOUDNESS_SWEEP_WAIT_RECHECK_SECONDS in performance_governor.py; they are used only when that module fails to import.
_SWEEP_INFO_WAIT_MAX_S = performance_governor.LOUDNESS_SWEEP_WAIT_FOR_INFO_SCANS_MAX_SECONDS if performance_governor is not None else 120.0
_SWEEP_INFO_WAIT_RECHECK_S = performance_governor.LOUDNESS_SWEEP_WAIT_RECHECK_SECONDS if performance_governor is not None else 2.0


def _airing_shows_missing_info():
    """The airing shows of every channel that still need their length or picture box (a file on a held drive or confirmed bad is left out)."""
    missing = []
    lookups = [SCAN_GATHER_LIBRARY_LOOKUPS]
    try:
        airing = _gather_probe_priority_queue()[0]
    except Exception as e:
        _log_warn_throttled("sweep_info_gather", "[LOUDNESS PROBE] could not list the airing shows: %s" % e)
        return missing
    for _kind, _ch, _block, norm_p in airing:
        if media.file_is_confirmed_bad(norm_p) or _scan_drive_on_hold(norm_p):
            continue
        if (not _scan_duration_reported(_read_file_probe_facts(norm_p), False)
                or not _scan_picture_box_reported(norm_p, lookups)):
            missing.append(norm_p)
    return missing


def _sweep_wait_for_airing_info_scans():
    """Holds the background loudness pass while an airing show still needs its length or picture box, at most _SWEEP_INFO_WAIT_MAX_S; True when the app is shutting down."""
    # WARNING: owner order 2026-11-02 and 2026-11-03: every channel's airing show gets its length and picture box first, loudness after.
    _t0 = time.monotonic()
    _first = None
    while time.monotonic() - _t0 < _SWEEP_INFO_WAIT_MAX_S:
        missing = _airing_shows_missing_info()
        if not missing:
            if _first is not None:
                log.info("[LOUDNESS PROBE] airing shows' length and picture-box scans finished; loudness pass goes on after %.1fs", time.monotonic() - _t0)
            return False
        if _first is None:
            _first = len(missing)
            log.info("[LOUDNESS PROBE] loudness pass waits for the length and picture-box scans of %d airing show(s)", _first)
        if _app_shutting_down.wait(_SWEEP_INFO_WAIT_RECHECK_S):
            return True
    log.info("[LOUDNESS PROBE] waited %.0fs for the airing shows' length and picture-box scans; loudness pass goes on", _SWEEP_INFO_WAIT_MAX_S)
    return False


def _run_first_pass_now_playing_sweep():
    """Scans every currently-airing audio target back to back before any ambient backlog tier work, until nothing live is left unscanned; each scan waits first for the airing shows' length and picture-box scans."""
    if db is None:
        return
    print("[LOUDNESS PROBE] First-pass now-playing sweep starting...")
    _t0 = time.monotonic()
    _scanned = 0
    _crashed = False
    try:
        _known_channels = set(db.channels_db.keys())
        pending = _snapshot_now_playing_loudness_targets()
        while True:
            if _app_shutting_down.is_set():
                return

            _current_channels = set(db.channels_db.keys())
            _new_channels = _current_channels - _known_channels
            if _new_channels:
                _interrupted = False
                for new_ch in sorted(_new_channels, key=_channel_scan_rank):
                    _known_channels.add(new_ch)
                    ch_info = db.channels_db.get(new_ch, {})
                    if not ch_info or not ch_info.get("active", True):
                        continue
                    block_key, norm_p = _first_scheduled_target_for_channel(new_ch, ch_info)
                    if not norm_p:
                        continue
                    print(f"[LOUDNESS PROBE] New channel ch{new_ch} detected mid-sweep -- "
                          f"pausing to scan its first scheduled show before resuming.")
                    if _sweep_wait_for_airing_info_scans():
                        return
                    if _probe_and_apply_loudness_blocking(
                            "channel", new_ch, block_key or "Full Day", norm_p,
                            "new-channel priority scan"):
                        _scanned += 1
                    elif _app_shutting_down.wait(_SWEEP_SKIP_BACKOFF_SECONDS):
                        return
                    _interrupted = True
                if _interrupted:
                    continue

            _fresh = _snapshot_now_playing_loudness_targets()
            _drifted_key = None
            for key, target in _fresh.items():
                _prev = pending.get(key)
                if _prev is not None and _prev[3] != target[3]:
                    _drifted_key = key
                    break
            if _drifted_key is not None:
                kind, ch_key, block_key, norm_p = _fresh[_drifted_key]
                _label = f"ch{ch_key}" if ch_key else kind
                print(f"[LOUDNESS PROBE] {_label} now-playing changed mid-sweep -- "
                      f"pausing to scan the new show before resuming.")
                if _sweep_wait_for_airing_info_scans():
                    return
                if _probe_and_apply_loudness_blocking(
                        kind, ch_key, block_key, norm_p, "now-playing priority scan"):
                    _scanned += 1
                elif _app_shutting_down.wait(_SWEEP_SKIP_BACKOFF_SECONDS):
                    return
                pending = _fresh
                continue

            for key, target in _fresh.items():
                pending.setdefault(key, target)
            if not pending:
                break
            if _sweep_wait_for_airing_info_scans():
                return
            key, (kind, ch_key, block_key, norm_p) = next(iter(pending.items()))
            del pending[key]
            if _probe_and_apply_loudness_blocking(kind, ch_key, block_key, norm_p, "first-pass scan"):
                _scanned += 1
            elif _app_shutting_down.wait(_SWEEP_SKIP_BACKOFF_SECONDS):
                return
    except Exception:
        _crashed = True
        log.exception(
            "[LOUDNESS PROBE] First-pass now-playing sweep crashed mid-scan -- "
            "completing early so dependent scan tiers aren't blocked forever")
    print(f"[LOUDNESS PROBE] First-pass now-playing sweep "
          f"{'aborted after error' if _crashed else 'complete'} -- "
          f"{_scanned} file(s) scanned in {time.monotonic() - _t0:.1f}s")


# ============================================================================
# SECTION: Probe priority queues & music precache
# ============================================================================


def _front_load_watched_channel(items):
    if not items:
        return items
    watched = str(app_state.get("current_channel", "")).zfill(2) if 'app_state' in globals() else ""
    if not watched:
        return items
    highlighted = (str(app_state.get("highlighted_guide_channel", "")).zfill(2)
                   if 'app_state' in globals() and app_state.get("current_channel") == "04" else "")
    mine = [it for it in items if len(it) > 1 and str(it[1]) == watched]
    boosted = ([it for it in items if len(it) > 1 and str(it[1]) == highlighted]
               if highlighted and highlighted != watched else [])
    if not mine and not boosted:
        return items
    rest = [it for it in items if not (len(it) > 1 and str(it[1]) in (watched, highlighted))]
    return mine + boosted + rest


# WARNING: the fallback numbers below must match PROBE_NOW_STATE_TTL_SECONDS in performance_governor.py; they are used only when that module fails to import.
_PROBE_NOW_STATE_TTL_S = performance_governor.PROBE_NOW_STATE_TTL_SECONDS if performance_governor is not None else 3.0
_probe_now_state_cache = {}

_probe_block_timeline_cache = {}

def _get_probe_now_state(ch_str):
    import time as _time
    now = _time.monotonic()
    entry = _probe_now_state_cache.get(ch_str)
    if entry is not None and (now - entry[0]) < _PROBE_NOW_STATE_TTL_S:
        return entry[1]
    try:
        state = calculate_slotted_playback_state(ch_str)
    except Exception as _swallowed_error:
        _log_swallowed("_get_probe_now_state: state = calculate_slotted_playback_state(ch_str)", _swallowed_error)
        state = {}
    _probe_now_state_cache[ch_str] = (now, state)
    return state


# ============================================================================
# SECTION: Shared scan snapshot and per-channel scan progress
# ============================================================================
# WARNING: a published snapshot is replaced whole by one builder thread and only read elsewhere; never mutate it.
# WARNING: "done" for a file must stay in step with the scans that actually exist (duration, loudness gain, picture box); a new info scan must be added to _scan_file_is_done.

# WARNING: the fallback numbers below must match SCAN_SNAPSHOT_INTERVAL_S, SCAN_SNAPSHOT_STALE_S, SCAN_SNAPSHOT_DUTY_FACTOR, SCAN_SNAPSHOT_MAX_REST_S, SCAN_PICTURE_BOX_LOOKUPS_PER_BUILD in performance_governor.py; they are used only when that module fails to import.
SCAN_SNAPSHOT_INTERVAL_S = performance_governor.SCAN_SNAPSHOT_INTERVAL_S if performance_governor is not None else 5.0
SCAN_SNAPSHOT_STALE_S = performance_governor.SCAN_SNAPSHOT_STALE_S if performance_governor is not None else 15.0
SCAN_SNAPSHOT_DUTY_FACTOR = performance_governor.SCAN_SNAPSHOT_DUTY_FACTOR if performance_governor is not None else 8.0
SCAN_SNAPSHOT_MAX_REST_S = performance_governor.SCAN_SNAPSHOT_MAX_REST_S if performance_governor is not None else 10.0
SCAN_PICTURE_BOX_LOOKUPS_PER_BUILD = performance_governor.SCAN_PICTURE_BOX_LOOKUPS_PER_BUILD if performance_governor is not None else 200

_scan_snapshot_lock = threading.Lock()
_scan_snapshot = {"built_at": -1e9, "channels": {}}
_scan_pb_has_box = set()
_scan_progress_complete_logged = {}
_scan_done_sticky = {}


def _get_block_ordered_content_peek(ch_key, ch_info, block_name, now):
    """The lineup of a block that is not on air, read without changing any saved scheduler state."""
    return _get_block_ordered_content(ch_key, ch_info, block_name, now, peek_only=True)


def _build_scan_snapshot():
    """One pass over every active, non-server channel: its ordered content for the airing block, the lineups of its other blocks in airing order, the file playing now, and its commercials."""
    channels = {}
    if db is None:
        return {"built_at": time.monotonic(), "channels": channels}
    for i in range(5, 45):
        ch_str = str(i).zfill(2)
        ch_info = db.channels_db.get(ch_str, {})
        if not ch_info or not ch_info.get("active", True) or ch_info.get("server_locked", False):
            continue
        try:
            ordered, block_key = _get_channel_ordered_content(ch_str, ch_info)
            current_file = _get_probe_now_state(ch_str).get("file", "")
        except Exception as e:
            log.warning("[SCAN SNAPSHOT] ch%s content gather failed (skipped): %s", ch_str, e)
            continue
        commercials_on = bool(ch_info.get("commercials_enabled", False))
        other_blocks = []
        try:
            _snap_now = broadcast_clock.now().replace(tzinfo=None)
            for _other_name in _block_names_after_airing(ch_info, _snap_now):
                _other_ordered, _other_key = _get_block_ordered_content_peek(ch_str, ch_info, _other_name, _snap_now)
                if _other_ordered and _other_key:
                    other_blocks.append({"block_key": _other_key, "ordered": list(_other_ordered)})
        except Exception as e:
            log.warning("[SCAN SNAPSHOT] ch%s other-block gather failed (airing block kept): %s", ch_str, e)
            other_blocks = []
        _pending_block, _pending_airing, _pending_other = "", [], []
        if ch_info.get("is_visualizer", False):
            try:
                _vis_unseekable, _vis_unseekable_exts = _visualizer_admission_inputs()
                _pending_block = "Music Tracks"
                _pending_airing = media.pending_visualizer_paths(
                    ch_info.get("schedules", {}).get("Music Tracks", []), _vis_unseekable, _vis_unseekable_exts)
            except Exception as e:
                log.warning("[SCAN SNAPSHOT] ch%s pending-song gather failed (lineup kept): %s", ch_str, e)
                _pending_block, _pending_airing = "", []
        else:
            try:
                _pend_now = broadcast_clock.now().replace(tzinfo=None)
                _pend_broken = set(ch_info.get("broken_files", []))
                _pend_schedules = ch_info.get("schedules", {})

                def _pending_paths(_name):
                    return [t["path"] for t in build_pending_tracks(_pend_schedules.get(_name, []), _cached_path_exists)
                            if t["path"] not in _pend_broken]

                _pending_block = _airing_block_name(ch_info, _pend_now)
                _pending_airing = _pending_paths(_pending_block)
                for _dist, _other_name in enumerate(_block_names_after_airing(ch_info, _pend_now)):
                    _other_pending = _pending_paths(_other_name)
                    if _other_pending:
                        _pending_other.append({"block_key": _other_name, "distance": _dist, "paths": _other_pending})
            except Exception as e:
                log.warning("[SCAN SNAPSHOT] ch%s pending-file gather failed (lineup kept): %s", ch_str, e)
                _pending_block, _pending_airing, _pending_other = "", [], []
        channels[ch_str] = {
            "ordered": list(ordered or []),
            "block_key": block_key,
            "pending_block": _pending_block,
            "pending": _pending_airing,
            "pending_other": _pending_other,
            "other_blocks": other_blocks,
            "current_file": current_file,
            "is_visualizer": bool(ch_info.get("is_visualizer", False)),
            "commercials": list(ch_info.get("schedules", {}).get("Commercials", [])) if commercials_on else [],
        }
    return {"built_at": time.monotonic(), "channels": channels}


def _get_scan_snapshot():
    """The latest shared snapshot; rebuilt on the spot only when the builder thread has not refreshed it recently."""
    global _scan_snapshot
    snap = _scan_snapshot
    if time.monotonic() - snap["built_at"] <= SCAN_SNAPSHOT_STALE_S:
        return snap
    fresh = _build_scan_snapshot()
    with _scan_snapshot_lock:
        if fresh["built_at"] > _scan_snapshot["built_at"]:
            _scan_snapshot = fresh
        return _scan_snapshot


def _scan_snapshot_channel(ch_str):
    """The snapshot record for one channel, or None when the channel is inactive, server-locked or has no content."""
    return _get_scan_snapshot()["channels"].get(ch_str)


def _scan_picture_box_known(norm_p, lookups_left):
    """True when the file's picture box is stored or given up; looks in the library at most once per file while lookups_left[0] allows."""
    if norm_p in _picture_box_done or norm_p in _scan_pb_has_box:
        return True
    if lookups_left[0] <= 0:
        return False
    lookups_left[0] -= 1
    try:
        import media_library as _ml
        entry = _get_probe_library().get_cached(norm_p)
    except Exception as _swallowed_error:
        _log_swallowed("checking if the picture box is known: media_library lookup", _swallowed_error)
        return False
    if (entry and entry.get("picture_box")
            and (entry.get("picture_box_detector_version") or 0) >= _ml.PICTURE_BOX_DETECTOR_VERSION):
        _scan_pb_has_box.add(norm_p)
        return True
    return False


def _scan_duration_reported(facts, sched_has_dur):
    """True when the duration scan has reported a file: a measured length is stored, or the schedule entry already holds one."""
    return (facts.get("duration") or 0) > 0 or bool(sched_has_dur)


def _scan_loudness_reported(facts, sched_has_gain):
    """True when the loudness scan has reported a file: a scanned gain is stored, or the schedule entry already holds one."""
    return "gain" in facts or bool(sched_has_gain)


def _scan_picture_box_reported(norm_p, lookups_left):
    """True when the picture-box scan has reported a file: its picture box is stored or given up, or the file is not video and has none to scan."""
    if os.path.splitext(norm_p)[1].lower() not in media.VIDEO_DISPLAY_EXTS:
        return True
    return _scan_picture_box_known(norm_p, lookups_left)


def _scan_file_is_done(norm_p, sched_has_gain, sched_has_dur, music_only, lookups_left):
    """True when all three scan lanes (loudness, duration, picture box) have reported the file, or the file is confirmed bad; a song needs only loudness and duration. Captions are not part of it."""
    # WARNING: this is the one place that decides a file is finished; the duration and picture-box scan threads skip a file by the same _scan_*_reported tests, so a new info scan must be added here and to its own thread together.
    if media.file_is_confirmed_bad(norm_p):
        return True
    facts = _read_file_probe_facts(norm_p)
    if not _scan_loudness_reported(facts, sched_has_gain):
        return False
    if not _scan_duration_reported(facts, False if music_only else sched_has_dur):
        return False
    if music_only:
        return True
    return _scan_picture_box_reported(norm_p, lookups_left)


def _scan_picture_box_finished(norm_p, lookups_left):
    """True only when a real picture-box scan result is stored for the file: not a full-frame label put in after repeated time-outs."""
    if os.path.splitext(norm_p)[1].lower() not in media.VIDEO_DISPLAY_EXTS:
        return True
    if norm_p in _picture_box_guessed:
        return False
    return _scan_picture_box_known(norm_p, lookups_left)


def _scan_file_is_finished(norm_p, music_only, lookups_left):
    """True when every scan of the file has really finished, for the Channels-tab bar: a measured length, a scanned loudness gain and a stored picture box, all read from the library. A guessed length, a gain or length copied on a schedule entry, a file given up on and a full-frame label put in after time-outs do not count."""
    # WARNING: only the bar uses this test; the scans themselves skip a file by _scan_file_is_done, which also accepts the schedule's copies and a file given up on.
    facts = _read_file_probe_facts(norm_p)
    if "gain" not in facts or (facts.get("duration") or 0) <= 0:
        return False
    if music_only:
        return True
    return _scan_picture_box_finished(norm_p, lookups_left)


def _scan_stages_pending(norm_p, sched_has_gain, sched_has_dur, lookups_left):
    """True while any of the file's three scans (picture box, duration, loudness) is neither finished nor given up; the same test the Channels-tab bar uses."""
    return not _scan_file_is_done(norm_p, sched_has_gain, sched_has_dur, False, lookups_left)


def _compute_channel_scan_progress(snap, lookups_left):
    """{channel: (done, total)} counting every distinct file of each channel's airing block, its other blocks and its commercials."""
    progress = {}
    for ch_str, rec in snap["channels"].items():
        seen = {}
        _all_lineups = [rec["ordered"]] + [ob["ordered"] for ob in rec.get("other_blocks", [])]
        for _lineup in _all_lineups:
            for entry in _lineup:
                entry_has_gain = isinstance(entry, dict) and "gain" in entry
                for p in _paths_from_entry(entry):
                    if p and _cached_path_exists(p):
                        norm_p = os.path.normpath(p)
                        seen[norm_p] = (seen.get(norm_p, (False, False))[0] or entry_has_gain, False)
        for casset in rec["commercials"]:
            cp = casset.get("path", casset.get("file", "")) if isinstance(casset, dict) else str(casset)
            if cp and _cached_path_exists(cp):
                norm_c = os.path.normpath(cp)
                c_gain = isinstance(casset, dict) and "gain" in casset
                c_dur = isinstance(casset, dict) and casset.get("duration", -1) not in (-1, 0, None)
                prev = seen.get(norm_c, (False, False))
                seen[norm_c] = (prev[0] or c_gain, prev[1] or c_dur)
        # WARNING: a Visualizer channel's lineup holds only the songs that already have a length, so its bar was 2/2 or 3/3 and left at once; the songs still waiting for their length count as not done, so the bar covers the whole music list (owner log 2026-11-06).
        if rec.get("is_visualizer"):
            for p in rec.get("pending", []):
                if p and _cached_path_exists(p):
                    seen.setdefault(os.path.normpath(p), (False, False))
        total = len(seen)
        if total == 0:
            continue
        # WARNING: a file that finished its last scan stays counted on the bar; a rescan (changed-file sweep, newer detector, a rebuilt schedule) never takes it back off, so the bar only moves forward as files finish (owner rule 2026-11-06).
        _kept = _scan_done_sticky.setdefault(ch_str, set())
        _kept.intersection_update(seen)
        done = 0
        for norm_p, (has_gain, has_dur) in seen.items():
            if norm_p in _kept:
                done += 1
            elif _scan_file_is_finished(norm_p, rec["is_visualizer"], lookups_left):
                _kept.add(norm_p)
                done += 1
        progress[ch_str] = (done, total)
    return progress


def _publish_channel_scan_progress(snap):
    """Writes app_state["_channel_scan_progress"] = {channel: (done, total)}; the Channels tab only reads it."""
    lookups_left = [0 if _python_heavy_should_pause() else SCAN_PICTURE_BOX_LOOKUPS_PER_BUILD]
    progress = _compute_channel_scan_progress(snap, lookups_left)
    app_state["_channel_scan_progress"] = progress
    for ch_str, (done, total) in progress.items():
        if done >= total:
            if _scan_progress_complete_logged.get(ch_str) != total:
                _scan_progress_complete_logged[ch_str] = total
                log.info("[SCAN PROGRESS] ch%s complete: %d/%d files", ch_str, done, total)
        else:
            _scan_progress_complete_logged.pop(ch_str, None)
    return progress


def _scan_snapshot_worker():
    """Background thread: rebuilds the shared snapshot every SCAN_SNAPSHOT_INTERVAL_S and publishes the per-channel progress."""
    global _scan_snapshot
    if db is None:
        return
    _woke_for_added = _scan_files_added_generation[0]
    while not _app_shutting_down.is_set():
        # WARNING: a rebuild walks every channel's whole schedule; adding files woke it again at once, so while channels were being set up it ran back to back and held the Python lock for a third of the app's time, which made the picture stall and drop frames (owner logs 2026-11-05). After each rebuild it rests SCAN_SNAPSHOT_DUTY_FACTOR times as long as the rebuild took, up to SCAN_SNAPSHOT_MAX_REST_S, whatever wakes it.
        _built_from = time.monotonic()
        try:
            _added_seen = _scan_files_added_generation[0]
            with _background_activity("scan_snapshot"):
                fresh = _build_scan_snapshot()
            with _scan_snapshot_lock:
                _scan_snapshot = fresh
            _publish_channel_scan_progress(fresh)
            if _added_seen != _woke_for_added:
                _woke_for_added = _added_seen
                _scan_work_generation[0] += 1
        except Exception as e:
            log.warning("[SCAN SNAPSHOT] rebuild failed: %s", e)
        _rest = min(float(SCAN_SNAPSHOT_MAX_REST_S), (time.monotonic() - _built_from) * float(SCAN_SNAPSHOT_DUTY_FACTOR))
        if _rest > 0 and _app_shutting_down.wait(_rest):
            return
        if _scan_idle_wait(max(0.0, SCAN_SNAPSHOT_INTERVAL_S - _rest), _scan_files_added_generation):
            return


_logged_missing_probe_paths = set()


def _log_missing_probe_path_once(raw_path, ch_key, block_key):
    if not raw_path or raw_path in _logged_missing_probe_paths:
        return
    _logged_missing_probe_paths.add(raw_path)
    print(f"[MEDIA PRECACHE] Skipping ch{ch_key} '{block_key}' entry -- path does not exist, "
          f"will never be scanned until fixed: {raw_path}")


def _gather_probe_priority_queue():
    tiers = [[], [], [], []]
    if db is None:
        return tiers
    _pb_lookups = [SCAN_GATHER_LIBRARY_LOOKUPS]

    # WARNING: the DVD player has no tier here and never will; DVD/disc-backup playback is never loudness-scanned.

    for i in range(5, 45):
        ch_str = str(i).zfill(2)
        ch_info = db.channels_db.get(ch_str, {})
        if not ch_info or not ch_info.get("active", True):
            continue
        if ch_info.get("server_locked", False):
            continue
        if ch_info.get("is_visualizer", False):
            _vis_rec = _scan_snapshot_channel(ch_str)
            if _vis_rec is not None and not _vis_rec["ordered"]:
                for _pend_path in _vis_rec.get("pending", []):
                    _pend_norm = os.path.normpath(_pend_path)
                    if _cached_path_exists(_pend_norm):
                        tiers[0].append(("channel", ch_str, "Music Tracks", _pend_norm))
                        break
            continue
        _snap_rec = _scan_snapshot_channel(ch_str)
        if _snap_rec is None:
            continue
        current_file = _snap_rec["current_file"]
        ordered, block_key = _snap_rec["ordered"], _snap_rec["block_key"]

        # WARNING: a channel with no lineup has no file with a known duration; its first unscanned file goes in the airing tier so the channel can leave Static, the rest of its files follow in the deep backlog.
        if not ordered:
            for _pend_path in _snap_rec.get("pending", []):
                _pend_norm = os.path.normpath(_pend_path)
                if _cached_path_exists(_pend_norm) and _scan_stages_pending(_pend_norm, False, False, _pb_lookups):
                    tiers[0].append(("channel", ch_str, _snap_rec.get("pending_block") or "", _pend_norm))
                    break

        tl_upcoming = None
        if ch_info.get("commercials_enabled", False):
            tl_upcoming = _next_n_from_block_timeline(ch_str, current_file, n=4)

        if tl_upcoming is not None:
            for k, tl_entry in enumerate(tl_upcoming):
                p = tl_entry.get("path", "")
                if not (p and _cached_path_exists(p)):
                    _log_missing_probe_path_once(p, ch_str, block_key or "Commercials")
                    continue
                norm_p = os.path.normpath(p)
                if not _scan_stages_pending(norm_p, False, False, _pb_lookups):
                    continue
                _label = "Commercials" if tl_entry.get("is_commercial") else (block_key or "")
                tiers[k].append(("channel", ch_str, _label, norm_p))
        elif ordered and block_key:
            upcoming = _next_n_from_ordered(ordered, current_file, n=4)
            for k, entry in enumerate(upcoming):
                for p in _paths_from_entry(entry):
                    if not (p and _cached_path_exists(p)):
                        _log_missing_probe_path_once(p, ch_str, block_key)
                        continue
                    norm_p = os.path.normpath(p)
                    if not _scan_stages_pending(norm_p, isinstance(entry, dict) and "gain" in entry, False, _pb_lookups):
                        continue
                    tiers[k].append(("channel", ch_str, block_key, norm_p))

        if ch_info.get("commercials_enabled", False) and tl_upcoming is None:
            _comm_list = ch_info.get("schedules", {}).get("Commercials", [])
            _added = 0
            for _casset in _comm_list:
                if _added >= 4:
                    break
                _cp = _casset.get("path", _casset.get("file", "")) if isinstance(_casset, dict) else str(_casset)
                if not (_cp and _cached_path_exists(_cp)):
                    _log_missing_probe_path_once(_cp, ch_str, "Commercials")
                    continue
                _cnorm = os.path.normpath(_cp)
                _chas_gain = isinstance(_casset, dict) and "gain" in _casset
                _chas_dur = isinstance(_casset, dict) and _casset.get("duration", -1) not in (-1, 0, None)
                if not _scan_stages_pending(_cnorm, _chas_gain, _chas_dur, _pb_lookups):
                    continue
                tiers[1].append(("channel", ch_str, "Commercials", _cnorm))
                _added += 1
    tiers = [_front_load_watched_channel(_t) for _t in tiers]

    return tiers


def _music_scan_source_items(source_key, songs):
    """Turns one playlist's songs, in play order from the one playing (distance 0), into ranked scan items; songs already scanned are left out and counted toward how far ahead the scan is."""
    ahead = 0
    counting = True
    pending = []
    for distance, (kind, ch_key, block_key, norm_p, done) in enumerate(songs):
        if done:
            if counting and distance > 0:
                ahead += 1
            continue
        if distance > 0:
            counting = False
        pending.append((distance, kind, ch_key, block_key, norm_p))
    if performance_governor is not None:
        behind = performance_governor.music_scan_falling_behind(_music_scan_behind.get(source_key, True), ahead)
    else:
        behind = True
    if behind != _music_scan_behind.get(source_key):
        if source_key in _music_scan_behind:
            log.info("[MUSIC PRECACHE] %s: %d next songs scanned, %s", source_key, ahead,
                     "falling behind, scanning fast" if behind else "far enough ahead, scanning slower")
        _music_scan_behind[source_key] = behind
    out = []
    for distance, kind, ch_key, block_key, norm_p in pending:
        if performance_governor is not None:
            cls = performance_governor.music_scan_class(distance, behind)
        else:
            cls = "now" if distance == 0 else "next"
        out.append((cls, distance, kind, ch_key, block_key, norm_p))
    return out


_music_scan_behind = {}
_MUSIC_SCAN_CLASS_RANK = {"now": 0, "next": 1, "deep": 2}


def _gather_music_probe_queue():
    """Every music-type source that still needs a probed gain or length, as (kind, channel, block, path, pace class) fed to _music_precache_worker(): ranked by pace class, then by how many songs ahead of the playing one, so every playlist's next songs come before any playlist's far songs."""
    ranked = []
    if db is None:
        return []

    if (db.config.get("game_channel_enabled", True)
            and db.config.get("ch03_menu_music_enabled", True)):
        playlist = db.config.get("ch03_menu_music", [])
        cur_idx = app_state.get("ch03_menu_music_idx", 0) % len(playlist) if playlist else 0
        songs = []
        for k in range(len(playlist)):
            idx = (cur_idx + k) % len(playlist)
            entry = playlist[idx]
            p = entry.get("path", "") if isinstance(entry, dict) else str(entry)
            if not p:
                continue
            _have = _read_file_probe_facts(os.path.normpath(p))
            if _have.get("gain") is not None and _have.get("duration"):
                songs.append(("ch03_menu_music", None, idx, os.path.normpath(p), True))
                continue
            if _cached_path_exists(p):
                songs.append(("ch03_menu_music", None, idx, os.path.normpath(p), False))
        ranked.extend(_music_scan_source_items("ch03 menu music", songs))

    for i in range(5, 45):
        ch_str = str(i).zfill(2)
        ch_info = db.channels_db.get(ch_str, {})
        if not ch_info or not ch_info.get("active", True) or not ch_info.get("is_visualizer", False):
            continue
        if ch_info.get("server_locked", False):
            continue
        _snap_rec = _scan_snapshot_channel(ch_str)
        if _snap_rec is None:
            continue
        current_file = _snap_rec["current_file"]
        ordered, block_key = _snap_rec["ordered"], _snap_rec["block_key"] or "Music Tracks"
        songs = []
        for entry in _next_n_from_ordered(ordered, current_file, n=len(ordered)):
            for p in _paths_from_entry(entry):
                if not (p and _cached_path_exists(p)):
                    continue
                norm_p = os.path.normpath(p)
                _cached = _read_file_probe_facts(norm_p)
                has_gain = "gain" in _cached or (isinstance(entry, dict) and "gain" in entry)
                has_dur = (_cached.get("duration") or 0) > 0 or norm_p in _music_duration_scan_attempted
                songs.append(("channel", ch_str, block_key or "Music Tracks", norm_p, has_gain and has_dur))
        # WARNING: a song gets into the lineup only once its length is known, so the songs still without one are walked too, after the lineup; without them a Visualizer whose songs are all new never starts (owner log 2026-11-03: 564 songs, Static for 25 minutes).
        _in_songs = {s[3] for s in songs}
        for p in _snap_rec.get("pending", []) or []:
            norm_p = os.path.normpath(p)
            if norm_p in _in_songs or not _cached_path_exists(norm_p):
                continue
            _in_songs.add(norm_p)
            _cached = _read_file_probe_facts(norm_p)
            has_gain = "gain" in _cached
            has_dur = (_cached.get("duration") or 0) > 0 or norm_p in _music_duration_scan_attempted
            songs.append(("channel", ch_str, block_key or "Music Tracks", norm_p, has_gain and has_dur))
        ranked.extend(_music_scan_source_items("ch" + ch_str, songs))

    ranked.sort(key=lambda it: (_MUSIC_SCAN_CLASS_RANK.get(it[0], 2), it[1]))
    return [(kind, ch_key, block_key, norm_p, cls) for cls, _distance, kind, ch_key, block_key, norm_p in ranked]


_music_duration_scan_attempted = set()


# WARNING: the fallback numbers below must match MUSIC_PRECACHE_IDLE_SLEEP_SECONDS, MUSIC_PRECACHE_BETWEEN_TRACKS_SECONDS, MUSIC_PRECACHE_SAVE_THROTTLE_SECONDS in performance_governor.py; they are used only when that module fails to import.
MUSIC_PRECACHE_IDLE_SLEEP_SECONDS = performance_governor.MUSIC_PRECACHE_IDLE_SLEEP_SECONDS if performance_governor is not None else 20.0
MUSIC_PRECACHE_BETWEEN_TRACKS_SECONDS = performance_governor.MUSIC_PRECACHE_BETWEEN_TRACKS_SECONDS if performance_governor is not None else 0.5
MUSIC_PRECACHE_SAVE_THROTTLE_SECONDS = performance_governor.MUSIC_PRECACHE_SAVE_THROTTLE_SECONDS if performance_governor is not None else 10.0


_music_scan_stats = {"songs": 0, "priority": 0, "seconds": 0.0, "since": None}
# WARNING: the fallback number below must match MUSIC_SCAN_LOG_SECONDS in performance_governor.py; it is used only when that module fails to import.
MUSIC_SCAN_LOG_SECONDS = performance_governor.MUSIC_SCAN_LOG_SECONDS if performance_governor is not None else 60.0


def _note_music_scan(scan_class, seconds):
    """Counts one scanned song and writes one [MUSIC SCAN] line a minute: songs, how many ran as priority, the time spent and the governor's level (owner 2026-11-02, N12)."""
    st = _music_scan_stats
    now = time.monotonic()
    if st["since"] is None:
        st["since"] = now
    st["songs"] += 1
    st["priority"] += 1 if scan_class == "now" else 0
    st["seconds"] += seconds
    if now - st["since"] >= MUSIC_SCAN_LOG_SECONDS:
        log.info("[MUSIC SCAN] last %.0fs: %d song(s) scanned, %d as priority (the next songs of a music channel), %.1fs of scanning, load level %s",
                 now - st["since"], st["songs"], st["priority"], st["seconds"],
                 performance_governor.current_level() if performance_governor is not None else "n/a")
        st.update(songs=0, priority=0, seconds=0.0, since=now)


_music_queue_note = {"at": 0.0}


def _note_music_queue(queue):
    """Writes one [MUSIC QUEUE] line a minute: how many songs wait in each scan class, so a music scan that sits idle or crawls can be told from one with nothing to do."""
    now = time.monotonic()
    if now - _music_queue_note["at"] < MUSIC_SCAN_LOG_SECONDS:
        return
    _music_queue_note["at"] = now
    counts = {}
    for item in queue:
        counts[item[4]] = counts.get(item[4], 0) + 1
    log.info("[MUSIC QUEUE] %d song(s) waiting for a scan: %s", len(queue),
             ", ".join("%s %d" % (k, counts[k]) for k in sorted(counts)) or "none")


def _music_precache_worker():
    """Runs separate duration and loudness scans for ch03 menu music and Visualizer playlists: the next 3 songs of every playlist with no pause, fast until 10 songs ahead are scanned, slower after that, and fast again once fewer than 5 of the next songs are scanned."""
    if db is None:
        return
    pygame.time.wait(1000)

    _last_music_save = 0.0
    _since_last_save = 0

    def _scan_pace(base_seconds):
        return _background_scan_pace_seconds(base_seconds)

    def _flush(force=False):
        nonlocal _last_music_save, _since_last_save
        _now = time.monotonic()
        if not force and (_since_last_save == 0
                           or (_now - _last_music_save) < MUSIC_PRECACHE_SAVE_THROTTLE_SECONDS):
            return
        try:
            db.save_settings_async(force=force)
        except Exception as e:
            log.warning("[MUSIC PRECACHE] settings save failed: %s", e)
        _last_music_save = _now
        _since_last_save = 0

    def _music_scan_one(kind, ch_key, block_key, norm_p):
        """Scans one song's length and loudness when they are missing; True when a scan ran."""
        nonlocal _since_last_save
        _ran = False
        _worker_cached = _read_file_probe_facts(norm_p)
        _duration = _worker_cached.get("duration") or 0
        _gain = _worker_cached.get("gain")
        if not _duration and norm_p not in _music_duration_scan_attempted:
            _ran = True
            try:
                # WARNING: a song's length is read on the music lane, not the TV length lane; behind five TV length workers a song waited 110 s for one header read (owner log 2026-11-06 08:46).
                _duration = _scan_store_duration(kind, ch_key, block_key, norm_p, lane="music_loudness")
            except Exception as e:
                log.warning("[MUSIC PRECACHE] duration scan failed for %s: %s", norm_p, e)
            _music_duration_scan_attempted.add(norm_p)
            if _duration:
                _since_last_save += 1
            _flush()

        if _gain is not None or _loudness_probe_in_cooldown(norm_p):
            return _ran

        _is_visualizer_track = (kind == "channel")
        try:
            gain = _probe_music_loudness_guarded(
                norm_p, treat_fallback_as_unknown=True,
                raise_on_no_audio=_is_visualizer_track,
                raise_on_unplayable=True, raise_on_timeout=True)
        except LoudnessProbeTimeoutError:
            _record_loudness_timeout(norm_p)
            return True
        except NoAudioStreamError as _naerr:
            _drop_media_from_pool(ch_key, block_key, norm_p,
                                   getattr(_naerr, "reason", "no audio track"))
            _since_last_save += 1
            _flush()
            return True
        except UnplayableMediaError as _uerr:
            _register_unplayable_strike(norm_p, _uerr.reason)
            return True
        except Exception as e:
            log.warning("[MUSIC PRECACHE] loudness scan failed for %s: %s", norm_p, e)
            return True
        if gain:
            _clear_loudness_timeout_streak(norm_p)
            _patch_probed_gain(kind, ch_key, block_key, norm_p, gain=gain, duration=None)
            _since_last_save += 1
        _flush()
        return True

    try:
        while True:
            if _app_shutting_down.is_set():
                return
            try:
                _visualizer_analysis_prefetch()
            except Exception as e:
                _log_warn_throttled("vis_analysis_prefetch", "[VISUALIZER ANALYSIS] prefetch of the next songs failed: %s" % e)
            queue = _gather_music_probe_queue()
            _note_music_queue(queue)
            if not queue:
                _flush()
                _scan_report_head("music")
                if _scan_idle_wait(_scan_pace(MUSIC_PRECACHE_IDLE_SLEEP_SECONDS)):
                    return
                continue
            _queue_built_at = time.monotonic()
            for kind, ch_key, block_key, norm_p, _scan_cls in queue:
                if _app_shutting_down.is_set():
                    return
                if time.monotonic() - _queue_built_at >= SCAN_PIPELINE_PREEMPT_CHECK_SECONDS:
                    break
                # WARNING: a pause waits on this song; moving on to the next would scan the playlist out of order.
                while _background_scan_should_pause():
                    if _app_shutting_down.wait(_scan_pace(MUSIC_PRECACHE_BETWEEN_TRACKS_SECONDS)):
                        return
                with _scan_thread_slot("music", _scan_cls) as _slot_ok:
                    if not _slot_ok:
                        return
                    _song_t0 = time.monotonic()
                    with (_governor_priority_scope() if _scan_cls == "now" else _governor_nullscope()):
                        _worked = _music_scan_one(kind, ch_key, block_key, norm_p)
                    if _worked:
                        _note_music_scan(_scan_cls, time.monotonic() - _song_t0)
                # WARNING: a song that needed no scan (gain in cooldown) must still wait the background pace, or a playlist of such songs spins the thread.
                _pace = (_scan_class_pace_seconds(_scan_cls, MUSIC_PRECACHE_BETWEEN_TRACKS_SECONDS) if _worked
                         else _scan_pace(MUSIC_PRECACHE_BETWEEN_TRACKS_SECONDS))
                if _pace > 0 and _app_shutting_down.wait(_pace):
                    return
    finally:
        _flush(force=True)


HOLIDAY_SCAN_LEAD_DAYS = performance_governor.HOLIDAY_SCAN_LEAD_DAYS if performance_governor is not None else 7


def _gather_holiday_scan_items():
    """The unscanned files of every channel's holiday lists as (kind, channel, holiday key, path) in three lists: on air now, opening within HOLIDAY_SCAN_LEAD_DAYS, and later; each later list is soonest first and a path appears once."""
    active, upcoming = [], []
    if db is None:
        return active, [], []
    try:
        today = broadcast_clock.date()
        _pb_lookups = [SCAN_GATHER_LIBRARY_LOOKUPS]
        seen = set()
        for i in range(5, 45):
            ch_str = str(i).zfill(2)
            ch_info = db.channels_db.get(ch_str, {})
            if not ch_info or not ch_info.get("active", True) or ch_info.get("server_locked", False):
                continue
            if ch_info.get("is_visualizer", False):
                continue
            broken = set(ch_info.get("broken_files", []))
            on_air_key = _todays_holiday_key(channel_key=ch_str)
            for h_key in media.HOLIDAY_KEYS:
                entries = (ch_info.get("holiday_schedules") or {}).get(h_key) or []
                distance = 0 if on_air_key == h_key else media.holiday_days_until_open(h_key, today)
                if distance is None:
                    continue
                for entry in entries:
                    for p in _paths_from_entry(entry):
                        if not (p and _cached_path_exists(p)):
                            continue
                        norm_p = os.path.normpath(p)
                        if norm_p in broken or norm_p in seen:
                            continue
                        if not _scan_stages_pending(norm_p, isinstance(entry, dict) and "gain" in entry, False, _pb_lookups):
                            continue
                        seen.add(norm_p)
                        item = ("channel", ch_str, h_key, norm_p)
                        if on_air_key == h_key:
                            active.append(item)
                        else:
                            upcoming.append((distance, item))
    except Exception as e:
        log.warning("[HOLIDAY SCAN] gathering the holiday files to scan failed (the rest of the scan continues): %s", e)
        return [], [], []
    upcoming.sort(key=lambda pair: pair[0])
    soon = [item for dist, item in upcoming if dist <= HOLIDAY_SCAN_LEAD_DAYS]
    later = [item for dist, item in upcoming if dist > HOLIDAY_SCAN_LEAD_DAYS]
    return active, soon, later


def _gather_deep_backlog_queue():
    """Every not-yet-scanned file behind each channel's next 3 shows, as (kind, channel, block, path): holiday files on air or opening soon first, then every channel's lineup by distance from the show on air (each channel's 4th show before any channel's 5th), commercials, the other blocks by how soon they air, and the far holiday files last."""
    out_content = []
    _ranked_content = []
    out_commercials = []
    out_other_blocks = []
    if db is None:
        return out_content
    _pb_lookups = [SCAN_GATHER_LIBRARY_LOOKUPS]
    for i in range(5, 45):
        ch_str = str(i).zfill(2)
        ch_info = db.channels_db.get(ch_str, {})
        if not ch_info or not ch_info.get("active", True):
            continue
        if ch_info.get("server_locked", False):
            continue
        _snap_rec = _scan_snapshot_channel(ch_str)
        if _snap_rec is None:
            continue
        current_file = _snap_rec["current_file"]
        ordered, block_key = _snap_rec["ordered"], _snap_rec["block_key"]
        if ordered and block_key:
            L = len(ordered)
            if L > 4:
                start_idx = 0
                for _i, _e in enumerate(ordered):
                    if current_file and current_file in _paths_from_entry(_e):
                        start_idx = _i
                        break
                for k in range(4, L):
                    entry = ordered[(start_idx + k) % L]
                    for p in _paths_from_entry(entry):
                        if not (p and _cached_path_exists(p)):
                            continue
                        norm_p = os.path.normpath(p)
                        if not _scan_stages_pending(norm_p, isinstance(entry, dict) and "gain" in entry, False, _pb_lookups):
                            continue
                        _ranked_content.append((k, len(_ranked_content), ("channel", ch_str, block_key, norm_p)))

        if ch_info.get("commercials_enabled", False):
            for _casset in ch_info.get("schedules", {}).get("Commercials", []):
                _cp = _casset.get("path", _casset.get("file", "")) if isinstance(_casset, dict) else str(_casset)
                if not (_cp and _cached_path_exists(_cp)):
                    continue
                _cnorm = os.path.normpath(_cp)
                _chas_gain = isinstance(_casset, dict) and "gain" in _casset
                _chas_dur = isinstance(_casset, dict) and _casset.get("duration", -1) not in (-1, 0, None)
                if not _scan_stages_pending(_cnorm, _chas_gain, _chas_dur, _pb_lookups):
                    continue
                out_commercials.append(("channel", ch_str, "Commercials", _cnorm))

        _lineup_paths = set()
        for _lineup_entry in list(ordered or []) + [_e for _ob in _snap_rec.get("other_blocks", []) for _e in _ob["ordered"]]:
            _lineup_paths.update(os.path.normpath(_lp) for _lp in _paths_from_entry(_lineup_entry) if _lp)
        _airing_pending_items = []
        for _pend_path in _snap_rec.get("pending", []):
            _pend_norm = os.path.normpath(_pend_path)
            if _pend_norm in _lineup_paths or not _cached_path_exists(_pend_norm):
                continue
            if _scan_stages_pending(_pend_norm, False, False, _pb_lookups):
                _airing_pending_items.append(("channel", ch_str, _snap_rec.get("pending_block") or "", _pend_norm))
        _pending_base = len(ordered) if ordered else 0
        for _pending_rank, _pending_item in enumerate(_airing_pending_items):
            _ranked_content.append((_pending_base + _pending_rank, len(_ranked_content), _pending_item))
        for _pob in _snap_rec.get("pending_other", []):
            _pob_items = []
            for _pend_path in _pob["paths"]:
                _pend_norm = os.path.normpath(_pend_path)
                if _pend_norm in _lineup_paths or not _cached_path_exists(_pend_norm):
                    continue
                if _scan_stages_pending(_pend_norm, False, False, _pb_lookups):
                    _pob_items.append(("channel", ch_str, _pob["block_key"], _pend_norm))
            out_other_blocks.append((_pob["distance"] + 0.5, _pob_items))
        for _dist, _ob in enumerate(_snap_rec.get("other_blocks", [])):
            _ob_items = []
            for entry in _ob["ordered"]:
                for p in _paths_from_entry(entry):
                    if not (p and _cached_path_exists(p)):
                        continue
                    norm_p = os.path.normpath(p)
                    if not _scan_stages_pending(norm_p, isinstance(entry, dict) and "gain" in entry, False, _pb_lookups):
                        continue
                    _ob_items.append(("channel", ch_str, _ob["block_key"], norm_p))
            out_other_blocks.append((_dist, _ob_items))

    out_content = [_item for _d, _seq, _item in sorted(_ranked_content, key=lambda it: (it[0], it[1]))]
    _other_by_distance = sorted(out_other_blocks, key=lambda it: it[0])
    _other_flat = [_item for _d, _items in _other_by_distance for _item in _items]
    _hol_active, _hol_soon, _hol_later = _gather_holiday_scan_items()
    out = _front_load_watched_channel(_hol_active + _hol_soon + out_content + out_commercials + _other_flat + _hol_later)
    return out


