def _request_schedule_rebuild(ch_key, block_key):
    """Mark one channel block for an immediate unaired-tail schedule rebuild."""
    if db is None or not ch_key or not block_key:
        return
    ch_str = str(ch_key).zfill(2)
    ch_info = db.channels_db.get(ch_str, {})
    playback_log = ch_info.get("playback_log") if isinstance(ch_info, dict) else None
    if isinstance(playback_log, dict):
        playback_log["_sched_rebuild_requested"] = True
        playback_log["_sched_rebuild_block"] = block_key
    for cache_key in list(_ORDERED_CONTENT_CACHE):
        if str(cache_key[0]).zfill(2) == ch_str:
            _ORDERED_CONTENT_CACHE.pop(cache_key, None)
    _probe_block_timeline_cache.pop(ch_str, None)
    app_state["guide_channel_stamps"] = dict(app_state.get("guide_channel_stamps", {}))
    app_state["guide_channel_stamps"][ch_str] = app_state["guide_channel_stamps"].get(ch_str, 0) + 1
    _guide_dirty_event.set()
    _replan_hub_future_soon(ch_str)


_hub_replan_pending = set()


def _replan_hub_future_soon(ch_str):
    """Re-plans one station's hub future rows on a short background thread right after its scheduling or station options changed, so the guide grid shows the new schedule without waiting for the slow background step."""
    # WARNING: this only plans; the scheduler (the hub's writer) rebuilds the station first, the remembered playback facts are dropped so the next read asks again, a second request while one is waiting is folded into it, and the caller is never blocked.
    if ch_str in _hub_replan_pending:
        return
    _hub_replan_pending.add(ch_str)

    def _run():
        try:
            time.sleep(0.3)
            import media_library as _ml
            _ml.shared_schedule_hub().forget_show_facts(ch_str)
            _hub_writer_step(ch_str)
            _hub_future_for_channel(ch_str, force=True)
            app_state["guide_channel_stamps"] = dict(app_state.get("guide_channel_stamps", {}))
            app_state["guide_channel_stamps"][ch_str] = app_state["guide_channel_stamps"].get(ch_str, 0) + 1
            _guide_dirty_event.set()
        except Exception as _e:
            _log_warn_throttled("hub_replan_" + ch_str, "[HUB FUTURE] ch%s: could not re-plan after an option change: %s", ch_str, _e)
        finally:
            _hub_replan_pending.discard(ch_str)
    threading.Thread(target=_run, daemon=True, name="HubReplan" + ch_str).start()


def _patch_probed_gain(kind, ch_key, block_key, norm_p, gain=None, duration=None, dims=None):
    _save_file_probe_facts(norm_p, duration=duration, gain=gain, dims=dims)
    if kind == "dvd":
        if gain is not None:
            if (dvd_engine is not None
                    and game_deck is not None
                    and getattr(game_deck, "dvd_playback_active", False)
                    and os.path.normpath(getattr(game_deck, "dvd_file_path", "") or "") == norm_p):
                dvd_engine.file_gain = gain
                try:
                    dvd_engine.set_volume(
                        db.config.get("global_volume", 70),
                        db.config.get("is_muted", False),
                    )
                except Exception as e:
                    log.warning("_patch_probed_gain (dvd): immediate apply failed: %s", e)
        return
    if kind == "ch03_menu_music":
        if gain is not None:
            print(f"[LOUDNESS PROBE] ch03 menu music '{os.path.basename(norm_p)}': gain x{gain:.2f}")
            try:
                _active_ch03_track = app_state.get("ch03_menu_music_track", "") or ""
                if (_active_ch03_track
                        and os.path.normpath(_active_ch03_track) == norm_p
                        and _ch03_music_is_playing()):
                    app_state["ch03_menu_music_gain"] = gain * 10 ** (_get_manual_audio_gain_db(norm_p) / 20.0)
                    _set_ch03_menu_music_volume(
                        db.config.get("global_volume", 70),
                        db.config.get("is_muted", False),
                    )
                    log.info("[PRECACHE] Hot-patched live ch03 menu music gain x%.2f for %s", gain, norm_p)
            except Exception as _hp_e3:
                log.warning("_patch_probed_gain (ch03_menu_music): live gain hot-patch failed: %s", _hp_e3)
        return
    ch_info = db.channels_db.get(ch_key, {})

    if duration is not None and duration > 0 and isinstance(ch_info, dict):
        _real_dur = media.whole_seconds_up(duration)
        _anchor = ch_info.get("playback_anchor")
        if isinstance(_anchor, dict) and _anchor.get("file"):
            try:
                if os.path.normpath(str(_anchor["file"])) == norm_p:
                    _anchor["duration"] = _real_dur
            except Exception as _swallowed_error:
                _log_swallowed("_patch_probed_gain: if os.path.normpath(str(_anchor['file'])) == norm_p:", _swallowed_error)
        _plog = ch_info.get("playback_log")
        if isinstance(_plog, dict):
            _scd = _plog.get("sched_cached_durations")
            if isinstance(_scd, dict):
                for _k in list(_scd.keys()):
                    try:
                        if os.path.normpath(str(_k)) == norm_p and _scd.get(_k) != _real_dur:
                            _scd[_k] = _real_dur
                    except Exception as _swallowed_error:
                        _log_swallowed("_patch_probed_gain: if os.path.normpath(str(_k)) == norm_p and _scd.get(_k) != _real_dur:", _swallowed_error)

    _COMMERCIAL_MAX_SECONDS = media.COMMERCIAL_MAX_SECONDS
    if (block_key == "Commercials" and duration is not None and duration > 0
            and int(duration) > _COMMERCIAL_MAX_SECONDS and isinstance(ch_info, dict)):
        _drop_media_from_pool(ch_key, block_key, norm_p, f"{int(duration)}s > {_COMMERCIAL_MAX_SECONDS}s, too long to be a commercial")
        return

    if gain is not None and vlc_engine is not None:
        try:
            if os.path.normpath(getattr(vlc_engine, "current_filepath", "") or "") == norm_p:
                vlc_engine.file_gain = gain
                vlc_engine.set_volume(
                    db.config.get("global_volume", 70),
                    db.config.get("is_muted", False),
                )
                log.info("[PRECACHE] Hot-patched live VLC gain x%.2f for channel content %s", gain, norm_p)
        except Exception as _hp_e:
            log.warning("_patch_probed_gain (channel): live gain hot-patch failed: %s", _hp_e)

    if gain is not None:
        try:
            _active_track = app_state.get("active_music_track_file", "") or ""
            if (_active_track
                    and os.path.normpath(_active_track) == norm_p
                    and pygame.mixer.music.get_busy()):
                app_state["active_music_gain"] = gain
                pygame.mixer.music.set_volume(
                    _effective_audio_gain(min_db=STACKED_GAIN_MIN_DB)
                    * MUSIC_GAIN
                    * _effective_loudness_gain(gain)
                )
                log.info("[PRECACHE] Hot-patched live visualizer/music gain x%.2f for %s", gain, norm_p)
        except Exception as _hp_e2:
            log.warning("_patch_probed_gain (channel): visualizer/music live gain hot-patch failed: %s", _hp_e2)

    for container_key in ("schedules", "holiday_schedules"):
        pool = ch_info.get(container_key, {}).get(block_key, [])
        for entry in pool:
            if not isinstance(entry, dict):
                continue
            _ep = os.path.normpath(entry.get("path", entry.get("file", "")))
            if _ep == norm_p:
                if gain is not None:
                    if duration is not None and duration > 0:
                        entry["duration"] = media.whole_seconds_up(duration)
                        _request_schedule_rebuild(ch_key, block_key)
                    return
            if entry.get("is_pair"):
                _p1 = os.path.normpath(entry.get("pair_ep1_path", ""))
                _p2 = os.path.normpath(entry.get("pair_ep2_path", ""))
                if norm_p in (_p1, _p2):
                    if duration is not None and duration > 0:
                        if norm_p == _p1:
                            entry["pair_ep1_duration"] = media.whole_seconds_up(duration)
                        else:
                            entry["pair_ep2_duration"] = media.whole_seconds_up(duration)
                        _request_schedule_rebuild(ch_key, block_key)
                    return


_guide_preload_scratch_surface = None
_guide_preload_last_tick_ts = time.time()
_guide_preload_thread_obj = None


# ============================================================================
# SECTION: Guide preload worker
# ============================================================================


def _make_guide_preload_watchdog_tick():
    """Detects a stalled GuidePreloader thread and reports where it is stuck."""
    import traceback as _tb
    # WARNING: the fallback numbers below must match GUIDE_PRELOAD_STALL_SECONDS in performance_governor.py; they are used only when that module fails to import.
    STALL_THRESHOLD_S = performance_governor.GUIDE_PRELOAD_STALL_SECONDS if performance_governor is not None else 2.0
    # WARNING: the fallback numbers below must match GUIDE_PRELOAD_REPORT_COOLDOWN_SECONDS in performance_governor.py; they are used only when that module fails to import.
    REPORT_COOLDOWN_S = performance_governor.GUIDE_PRELOAD_REPORT_COOLDOWN_SECONDS if performance_governor is not None else 10.0
    _state = {"last_report_ts": 0.0}

    def _tick():
        if _guide_preload_thread_obj is None or not _guide_preload_thread_obj.is_alive():
            return
        _guide_is_open = app_state.get("current_channel") == "04"
        if not _guide_is_open and not _guide_dirty_event.is_set():
            return
        # WARNING: the preloader pauses on purpose while a game core runs (see _guide_preload_worker), so that time is never a stall (owner 2026-11-02: no false warnings).
        _lr_core = getattr(game_deck, "_libretro_core", None) if game_deck is not None else None
        if _lr_core is not None and getattr(_lr_core, "is_loaded", False) and not getattr(_lr_core, "is_frozen", False):
            return
        _staleness = time.time() - _guide_preload_last_tick_ts
        if _staleness < STALL_THRESHOLD_S:
            return
        _now = time.time()
        if _now - _state["last_report_ts"] < REPORT_COOLDOWN_S:
            return
        _state["last_report_ts"] = _now
        try:
            _lock_state = _guide_build_lock.describe()
        except Exception as _lock_err:
            _lock_state = f"<error reading lock state: {_lock_err}>"
        _frames = sys._current_frames()
        _target_frame = _frames.get(_guide_preload_thread_obj.ident)
        if _target_frame is not None:
            _stack_str = "".join(_tb.format_stack(_target_frame))
        else:
            _stack_str = "<thread frame not found -- may have just exited>"
        log.warning(
            "[GUIDE PRELOAD WATCHDOG] GuidePreloader has not completed a "
            "tick in %.1fs (guide_open=%s). Lock state: %s\n"
            "GuidePreloader thread stack at time of report:\n%s",
            _staleness, _guide_is_open, _lock_state, _stack_str,
        )

    return _tick


def _guide_preload_worker():
    """Keeps the TV guide's grid and schedule built in the background from boot, regardless of which channel is on screen."""
    global _guide_preload_scratch_surface, _guide_preload_last_tick_ts
    # WARNING: the fallback numbers below must match GUIDE_PRELOAD_POLL_SECONDS in performance_governor.py; they are used only when that module fails to import.
    GUIDE_POLL_S = performance_governor.GUIDE_PRELOAD_POLL_SECONDS if performance_governor is not None else 0.5
    # WARNING: the fallback number below must match GUIDE_CLOSED_REBUILD_SECONDS in performance_governor.py; it is used only when that module fails to import.
    GUIDE_CLOSED_REBUILD_S = performance_governor.GUIDE_CLOSED_REBUILD_SECONDS if performance_governor is not None else 15.0
    _tick_count = 0
    _winsize_wait_since = None
    _initial_build_pending = True
    _last_closed_build = 0.0
    while True:
        try:
            if _app_shutting_down.is_set():
                return
            _lr_core = getattr(game_deck, "_libretro_core", None) if game_deck is not None else None
            if _lr_core is not None and getattr(_lr_core, "is_loaded", False) and not getattr(_lr_core, "is_frozen", False):
                time.sleep(GUIDE_POLL_S)
                continue
            if not pygame.display.get_init() or not pygame.font.get_init():
                time.sleep(GUIDE_POLL_S)
                continue
            _asked = True
            if _initial_build_pending:
                _initial_build_pending = False
            else:
                _asked = _guide_dirty_event.wait(timeout=GUIDE_POLL_S)
                _guide_dirty_event.clear()
            if _app_shutting_down.is_set():
                return
            # WARNING: while the guide is not on screen, a length or loudness that came in is caught at most every GUIDE_CLOSED_REBUILD_SECONDS and not while Python-heavy work must wait; a rebuild someone asks for (opening the guide, a channel edit) always runs at once (audit stage 3, 2026-11-02: 629 rebuilds in 15 minutes with the guide closed).
            if not _asked and app_state.get("current_channel") != "04":
                if _python_heavy_should_pause() or time.monotonic() - _last_closed_build < GUIDE_CLOSED_REBUILD_S:
                    _guide_preload_last_tick_ts = time.time()
                    continue
            if db is None or not pygame.display.get_init() or not pygame.font.get_init():
                _log_warn_throttled(
                    "guide_preload_bail_prereq",
                    "[GUIDE] preload worker bailed: db_is_none=%s pygame_display_init=%s font_init=%s",
                    db is None, pygame.display.get_init(), pygame.font.get_init())
                continue
            _w, _h = app_state.get("_window_size", (0, 0))
            if not _w or not _h:
                # WARNING: (0, 0) is normal until the main loop draws its first frame; only a size still unset after the wait below is a failure.
                if _winsize_wait_since is None:
                    _winsize_wait_since = time.time()
                if time.time() - _winsize_wait_since > GUIDE_PRELOAD_WINDOW_SIZE_WAIT_SECONDS:
                    _log_warn_throttled(
                        "guide_preload_bail_winsize",
                        "[GUIDE] preload worker bailed: window size still not set after %.0fs (%s, %s)", GUIDE_PRELOAD_WINDOW_SIZE_WAIT_SECONDS, _w, _h)
                continue
            _winsize_wait_since = None
            _theme_snapshot = app_state.get("_active_theme_snapshot") or dict(DEFAULT_THEME)
            if (_guide_preload_scratch_surface is None
                    or _guide_preload_scratch_surface.get_size() != (_w, _h)):
                _guide_preload_scratch_surface = pygame.Surface((_w, _h))
            _content_rect = pygame.Rect(0, 0, _w, _h)
            if app_state.get("current_channel") != "04":
                with _background_activity("guide_build"):
                    guide_preload_tick(_guide_preload_scratch_surface, app_state, db,
                                        _theme_snapshot, target_rect=_content_rect)
                _last_closed_build = time.monotonic()
            else:
                guide_preload_tick(_guide_preload_scratch_surface, app_state, db,
                                    _theme_snapshot, target_rect=_content_rect)
            _tick_count += 1
            _guide_preload_last_tick_ts = time.time()
        except Exception as e:
            _diag_hl_ch = str(app_state.get("highlighted_guide_channel", "?"))
            _diag_sel_ch = str(app_state.get("selected_guide_channel", "?"))
            _log_warn_throttled(
                f"guide_preload_tick_fail_{_diag_hl_ch}",
                "[GUIDE DIAGNOSTIC] preload tick failed (non-fatal) -- "
                "highlighted_guide_channel=%s selected_guide_channel=%s "
                "current_channel=%s: %s",
                _diag_hl_ch, _diag_sel_ch,
                app_state.get("current_channel", "?"), e,
            )
            log.warning(
                "[GUIDE DIAGNOSTIC] full traceback for the failure above "
                "(hl_ch=%s):", _diag_hl_ch, exc_info=True)


