# SECTION: Upcoming-media probing
# ============================================================================


def _probe_upcoming_media():
    import time as _time
    from concurrent.futures import ThreadPoolExecutor
    if db is None:
        return
    pygame.time.wait(1000)

    try:
        _report_interrupted_probe_marker()
    except Exception as _marker_e:
        log.warning(f"[MEDIA PRECACHE] interrupted-probe check failed (non-fatal): {_marker_e}")

    try:
        _resume_interrupted_probe_batches()
    except Exception as _resume_e:
        log.warning(f"[MEDIA PRECACHE] resuming interrupted probe batches failed (non-fatal): {_resume_e}")

    try:
        _stripped = _strip_local_entry_gains()
        if _stripped:
            print(f"[MEDIA PRECACHE] Removed {_stripped} old gain value(s) from the channel lists; gains live only in the library.")
            db.save_settings()
    except Exception as _strip_e:
        log.warning(f"[MEDIA PRECACHE] removing old gains from the channel lists failed (non-fatal): {_strip_e}")

    try:
        _run_first_pass_now_playing_sweep()
    except Exception as _first_pass_e:
        log.warning(f"[MEDIA PRECACHE] first-pass now-playing sweep failed (non-fatal): {_first_pass_e}")

    IDLE_SLEEP = PROBE_IDLE_SLEEP_SECONDS
    # WARNING: the fallback numbers below must match UPCOMING_PROBE_RESWEEP_COOLDOWN_SECONDS in performance_governor.py; they are used only when that module fails to import.
    _RESWEEP_COOLDOWN_S = performance_governor.UPCOMING_PROBE_RESWEEP_COOLDOWN_SECONDS if performance_governor is not None else 30.0
    _last_resweep_at = time.monotonic()
    BETWEEN_PROBES = BETWEEN_LOUDNESS_PROBES_SECONDS
    # WARNING: the fallback numbers below must match UPCOMING_PROBE_SAVE_THROTTLE_SECONDS in performance_governor.py; they are used only when that module fails to import.
    SAVE_THROTTLE_S = performance_governor.UPCOMING_PROBE_SAVE_THROTTLE_SECONDS if performance_governor is not None else 10.0
    _last_backlog_save = 0.0

    def _loudness_scan_pace(scan_class, base_seconds):
        # WARNING: the loudness scan runs at the same pace with Loudness Scan on or off; off only stops playback from using the gains.
        return _scan_class_pace_seconds(scan_class, base_seconds)

    def _pipeline_loudness_done(norm_p):
        """True when the file needs no loudness scan: its gain is stored, it was scanned this pass, or it is resting after a failed try."""
        if _read_file_probe_facts(norm_p).get("gain") is not None:
            return True
        with _pass_state_lock:
            if _this_pass_results.get(norm_p, {}).get("gain") is not None:
                return True
        return _loudness_probe_in_cooldown(norm_p)

    def _pipeline_workers_now(head_cls=None):
        # WARNING: while a video is playing it stays serial unless loudness is the most urgent scan (the others are waiting for it) and the load level allows; then it uses the scan threads the others leave, up to its own lane.
        spare = not app_state.get("is_playing_video", False)
        if performance_governor is None:
            return 1
        try:
            _base = max(1, performance_governor.loudness_dispatch_workers(spare=spare, cap=LOUDNESS_PROBE_MAX_CONCURRENT))
            if (head_cls is not None and head_cls != SCAN_CLASS_DEEP and performance_governor.scan_is_most_urgent("loudness")
                    and (performance_governor.current_level() if performance_governor.enforcing() else 0) <= 1):
                _lane = performance_governor.lane_slots("loudness_and_bake", performance_governor.current_level() if performance_governor.enforcing() else 0,
                                                       performance_governor.get_profile())
                return max(_base, min(_lane, performance_governor.scan_threads()))
            return _base
        except Exception as _swallowed_error:
            _log_swallowed("_pipeline_workers_now: return max(1, performance_governor.loudness_dispatch_workers", _swallowed_error)
            return 1

    while True:
        if _app_shutting_down.is_set():
            return
        if time.monotonic() - _last_resweep_at >= _RESWEEP_COOLDOWN_S and not _background_scan_should_pause():
            try:
                if _snapshot_now_playing_loudness_targets():
                    print("[LOUDNESS PROBE] Airing show(s) still unscanned -- running the now-playing sweep again.")
                    _run_first_pass_now_playing_sweep()
            except Exception as _resweep_e:
                log.warning("[LOUDNESS PROBE] now-playing re-sweep failed (non-fatal): %s", _resweep_e)
            _last_resweep_at = time.monotonic()
        tiers = _gather_probe_priority_queue()
        total_pending = sum(len(t) for t in tiers)
        if total_pending == 0:
            if _scan_idle_wait(IDLE_SLEEP):
                return
            continue

        if _background_scan_should_pause():
            if _app_shutting_down.wait(0.25):
                return
            continue

        
        _this_pass_results = {}
        _pass_stats = {"n": 0}
        _pass_state_lock = threading.Lock()

        def _find_pair_entry(ch_key, block_key, norm_p):
            if db is None:
                return None
            ch_info = db.channels_db.get(str(ch_key).zfill(2), {})
            for container_key in ("schedules", "holiday_schedules"):
                pool = ch_info.get(container_key, {}).get(block_key, [])
                if not isinstance(pool, list):
                    continue
                for entry in pool:
                    if not isinstance(entry, dict) or not entry.get("is_pair"):
                        continue
                    _p1 = entry.get("pair_ep1_path", "")
                    _p2 = entry.get("pair_ep2_path", "")
                    _np1 = os.path.normpath(_p1) if _p1 else ""
                    _np2 = os.path.normpath(_p2) if _p2 else ""
                    if norm_p == _np1:
                        return entry, _np2, 1
                    if norm_p == _np2:
                        return entry, _np1, 2
            return None

        def _probe_pair_loudness(ch_key, block_key, pair_info):
            entry, _sibling, _which = pair_info
            p1 = entry.get("pair_ep1_path", "")
            p2 = entry.get("pair_ep2_path", "")
            if not (p1 and p2):
                return
            np1, np2 = os.path.normpath(p1), os.path.normpath(p2)
            if not (os.path.exists(np1) and os.path.exists(np2)):
                return
            if (_read_file_probe_facts(np1).get("gain") is not None
                    and _read_file_probe_facts(np2).get("gain") is not None):
                return
            if _loudness_probe_in_cooldown(np1) or _loudness_probe_in_cooldown(np2):
                return
            if not _claim_probe(np1, "gain"):
                return
            if not _claim_probe(np2, "gain"):
                _release_probe(np1, "gain")
                return
            try:
                try:
                    gain = get_pair_loudness_gain(
                        np1, np2, raise_on_no_audio=True,
                        treat_fallback_as_unknown=True,
                        raise_on_unplayable=True,
                        raise_on_timeout=True,
                        db=db)
                except LoudnessProbeTimeoutError:
                    for _np in (np1, np2):
                        if _scan_handle_failure(_np, "loudness", "pair scan timed out", timed_out=True) == SCAN_FAIL_RETRY:
                            _record_loudness_timeout(_np)
                    return
                except NoAudioStreamError as _naerr:
                    _drop_pair_from_pool(ch_key, block_key, np1, np2,
                                          getattr(_naerr, "reason", "no audio track"))
                    with _pass_state_lock:
                        _this_pass_results.setdefault(np1, {})["gain"] = 1.0
                        _this_pass_results.setdefault(np2, {})["gain"] = 1.0
                        _pass_stats["n"] += 1
                    return
                except UnplayableMediaError as _uerr:
                    _culprit = os.path.normpath(_uerr.file_path) if _uerr.file_path else np1
                    if _culprit not in (np1, np2):
                        _culprit = np1
                    if _scan_handle_failure(_culprit, "loudness", _uerr.reason, corrupt=True) != SCAN_FAIL_RETRY:
                        return
                    _register_unplayable_strike(np1, _uerr.reason)
                    _register_unplayable_strike(np2, _uerr.reason)
                    return
                except Exception as e:
                    gain = None
                    log.warning(f"[LOUDNESS PRECACHE] pair {np1} / {np2}: {e}")
                if gain is None:
                    return
                _clear_loudness_timeout_streak(np1)
                _clear_loudness_timeout_streak(np2)
                with _pass_state_lock:
                    _this_pass_results.setdefault(np1, {})["gain"] = gain
                    _this_pass_results.setdefault(np2, {})["gain"] = gain
                _set_gain_double_checked(np1, True)
                _set_gain_double_checked(np2, True)
                _save_file_probe_facts(np1, gain=gain)
                _save_file_probe_facts(np2, gain=gain)
                if vlc_engine is not None:
                    try:
                        _cur = os.path.normpath(getattr(vlc_engine, "current_filepath", "") or "")
                        if _cur in (np1, np2):
                            vlc_engine.file_gain = gain
                            vlc_engine.set_volume(
                                db.config.get("global_volume", 70),
                                db.config.get("is_muted", False),
                            )
                    except Exception as _hp_e:
                        log.warning("_probe_pair_loudness: live gain hot-patch failed: %s", _hp_e)
                print(f"[LOUDNESS PROBE] Combined pair gain x{gain:.2f} for "
                      f"'{os.path.basename(np1)}' + '{os.path.basename(np2)}' (plays as one)")
                with _pass_state_lock:
                    _pass_stats["n"] += 1
            finally:
                _release_probe(np1, "gain")
                _release_probe(np2, "gain")

        def _probe_one_loudness(tier_idx, kind, ch_key, block_key, norm_p):
            _cached = _read_file_probe_facts(norm_p)
            if _cached.get("gain") is not None:
                _gain_neighbor_check(norm_p)
                return
            with _pass_state_lock:
                _already = _this_pass_results.get(norm_p, {}).get("gain") is not None
            if _already:
                return
            if _loudness_probe_in_cooldown(norm_p):
                return
            if _is_drive_degraded(norm_p):
                _scan_hold_drive(norm_p, _drive_latency_summary(norm_p) or "drive degraded")
            if _scan_drive_on_hold(norm_p):
                return
            if kind == "channel":
                _pair = _find_pair_entry(ch_key, block_key, norm_p)
                if _pair is not None:
                    _probe_pair_loudness(ch_key, block_key, _pair)
                    return
            _is_commercial = (kind == "channel" and block_key == "Commercials")
            _is_channel_content = (kind == "channel")
            try:
                probed_gain = _probe_loudness_guarded(
                    norm_p, raise_on_no_audio=_is_channel_content,
                    treat_fallback_as_unknown=True,
                    raise_on_unplayable=True,
                    raise_on_timeout=True)
            except LoudnessProbeTimeoutError:
                if _scan_handle_failure(norm_p, "loudness", "scan timed out", timed_out=True) == SCAN_FAIL_RETRY:
                    _record_loudness_timeout(norm_p)
                return
            except NoAudioStreamError as _naerr:
                if _is_channel_content:
                    _drop_media_from_pool(ch_key, block_key, norm_p, getattr(_naerr, "reason", "no audio track"))
                else:
                    _mark_confirmed_no_audio(norm_p, getattr(_naerr, "reason", "no audio track"))
                with _pass_state_lock:
                    # WARNING: gain 1.0 here only dedups within this pass; it is not persisted.
                    _this_pass_results.setdefault(norm_p, {})["gain"] = 1.0
                    _pass_stats["n"] += 1
                return
            except UnplayableMediaError as _uerr:
                if _scan_handle_failure(norm_p, "loudness", _uerr.reason, corrupt=True) != SCAN_FAIL_RETRY:
                    return
                _strikes = _register_unplayable_strike(norm_p, _uerr.reason)
                with _pass_state_lock:
                    # WARNING: gain 1.0 here only dedups within this pass; it is not persisted.
                    _this_pass_results.setdefault(norm_p, {})["gain"] = 1.0
                if _is_commercial and _strikes >= UNPLAYABLE_STRIKE_THRESHOLD:
                    _drop_media_from_pool(ch_key, block_key, norm_p,
                                           f"confirmed unplayable ({_uerr.reason}, {_strikes} strikes)")
                return
            except Exception as e:
                probed_gain = None
                log.warning(f"[LOUDNESS PRECACHE] {norm_p}: {e}")
            if probed_gain is not None:
                with _pass_state_lock:
                    _this_pass_results.setdefault(norm_p, {})["gain"] = probed_gain
            if probed_gain:
                _clear_loudness_timeout_streak(norm_p)
                _patch_probed_gain(kind, ch_key, block_key, norm_p, gain=probed_gain, duration=None)
                with _pass_state_lock:
                    _pass_stats["n"] += 1
                _gain_neighbor_check(norm_p, force=True)

        def _pipeline_stage_duration(tier_idx, kind, ch_key, block_key, norm_p):
            """Stage 2 of a file's scan chain: the video dimensions, once the duration scan has stored the duration. False while no duration is stored."""
            if (_read_file_probe_facts(norm_p).get("duration") or 0) <= 0:
                return False
            if (os.path.splitext(norm_p)[1].lower() in media.VIDEO_DISPLAY_EXTS
                    and not is_dvd_disc_source(norm_p)
                    and not _read_file_probe_facts(norm_p).get("dims")):
                try:
                    _dims = _probe_dims_gated(norm_p)
                    if _dims:
                        _save_file_probe_facts(norm_p, dims=_dims)
                except Exception as e:
                    log.warning("[SCAN PIPELINE] dimension probe of %s failed: %s", os.path.basename(norm_p), e)
            return True

        def _pipeline_scan_file(item):
            """One file's loudness chain, in order: the stored-duration check and video dimensions, then loudness. The duration is stored by the duration scan and the picture box by the picture-box scan; a stage that has to wait stops the chain for this file."""
            cls, tier_idx, kind, ch_key, block_key, norm_p = item
            if _app_shutting_down.is_set() or not _cached_path_exists(norm_p):
                return
            if _is_drive_degraded(norm_p):
                _scan_hold_drive(norm_p, _drive_latency_summary(norm_p) or "drive degraded")
            if _scan_drive_on_hold(norm_p):
                return
            try:
                with (_governor_priority_scope() if cls == SCAN_CLASS_NOW else _governor_nullscope()):
                    if not _pipeline_stage_duration(tier_idx, kind, ch_key, block_key, norm_p):
                        return
                    _probe_one_loudness(tier_idx, kind, ch_key, block_key, norm_p)
            except Exception as e:
                log.warning("[SCAN PIPELINE] chain for %s failed (next file continues): %s", os.path.basename(norm_p), e)

        _preempted = False
        _pipeline_items = _order_scan_pipeline(tiers, _gather_deep_backlog_queue())
        _attempted = set()
        _last_preempt_check = _time.perf_counter()
        _saved_n = 0
        _pi = 0
        _need_pi = 0
        while _pi < len(_pipeline_items):
            if _app_shutting_down.is_set():
                return
            if _LOUDNESS_PRIORITY_PENDING.is_set() or _background_scan_should_pause():
                if _app_shutting_down.wait(0.25):
                    return
                continue
            _head_cls = _pipeline_items[_pi][0]
            _now = _time.perf_counter()
            if _head_cls != SCAN_CLASS_NOW and _now - _last_preempt_check >= SCAN_PIPELINE_PREEMPT_CHECK_SECONDS:
                _last_preempt_check = _now
                # WARNING: a file that newly started airing outranks everything queued behind it, so restart the pass; files already tried this pass cannot trigger this, or one stuck file would restart it forever.
                if any(_it[3] not in _attempted for _it in _gather_probe_priority_queue()[0]):
                    _preempted = True
                    break
            while _need_pi < len(_pipeline_items) and (_need_pi < _pi or _pipeline_loudness_done(_pipeline_items[_need_pi][5])):
                _need_pi += 1
            if _need_pi < len(_pipeline_items):
                _scan_report_head("loudness", _pipeline_items[_need_pi][0], _pipeline_items[_need_pi][1])
            else:
                _scan_report_head("loudness")
            _workers_now = _pipeline_workers_now(_head_cls)
            _chunk = [_it for _it in _pipeline_items[_pi:_pi + _workers_now] if _it[0] == _head_cls]
            _pi += len(_chunk)
            _attempted.update(_it[5] for _it in _chunk)
            with _scan_thread_slot("loudness", _head_cls, _chunk[0][1]) as _slot_ok:
                if not _slot_ok:
                    return
                try:
                    if len(_chunk) == 1:
                        _pipeline_scan_file(_chunk[0])
                    else:
                        with ThreadPoolExecutor(max_workers=len(_chunk), thread_name_prefix="scan") as _sex:
                            list(_sex.map(_pipeline_scan_file, _chunk))
                except RuntimeError as _shutdown_e:
                    _log_warn_throttled("scan_pipeline_shutdown", f"[SCAN PIPELINE] Skipping chunk, interpreter is shutting down: {_shutdown_e}")
                    return
            if _pass_stats["n"] != _saved_n and _time.perf_counter() - _last_backlog_save >= SAVE_THROTTLE_S:
                _saved_n = _pass_stats["n"]
                _last_backlog_save = _time.perf_counter()
                try:
                    db.save_settings_async()
                except Exception as _swallowed_error:
                    _log_swallowed("_probe_upcoming_media: db.save_settings_async()", _swallowed_error)
            _pace = _loudness_scan_pace(_head_cls, BETWEEN_PROBES)
            if _pace > 0 and _app_shutting_down.wait(_pace):
                return

        if _pass_stats["n"]:
            try:
                db.save_settings_async()
            except Exception as e:
                log.warning("Settings save failed during media pre-cache: %s", e)
            try:
                app_state["guide_refresh_token"] = app_state.get("guide_refresh_token", 0) + 1
            except Exception as _swallowed_error:
                _log_swallowed("_probe_upcoming_media: app_state['guide_refresh_token'] = app_state.get('guide_refresh_token', 0) + 1", _swallowed_error)

        if not _preempted:
            _scan_report_head("loudness")
            if _scan_idle_wait(IDLE_SLEEP):
                return


# ============================================================================
# SECTION: Boot prewarm
# ============================================================================


def _prewarm_boot_channel_ready(boot_ch):
    """Gets duration, video dims and picture box of the boot channel's now-playing file before boot moves on, and starts its loudness scan without waiting for it, so the boot_prewarm step means the channel is ready to view."""
    try:
        if db is None or not boot_ch:
            return
        state = calculate_slotted_playback_state(boot_ch)
        file_path = state.get("file", "")
        mode = state.get("mode", "")
        if not file_path or not _cached_path_exists(file_path) or not _is_drive_responsive(file_path):
            return
        norm_p = os.path.normpath(file_path)
        cached = _read_file_probe_facts(norm_p)
        _dur = cached.get("duration")
        _dims = cached.get("dims")
        _wants_dims = mode in ("Video", "Commercial") and not is_dvd_disc_source(norm_p)
        if not _dur or (not _dims and _wants_dims):
            _probed_dur, _probed_dims = _probe_duration_and_dims_combined(norm_p)
            if not _dur:
                _dur = _probed_dur
            if not _dims and _wants_dims:
                _dims = _probed_dims
        if _dur or _dims:
            _save_file_probe_facts(norm_p, duration=_dur, dims=_dims)
        ch_info = db.channels_db.get(boot_ch, {})
        if not ch_info.get("is_visualizer", False) and not is_dvd_disc_source(norm_p):
            try:
                _ordered, block_key = _get_channel_ordered_content(boot_ch, ch_info)
            except Exception as _swallowed_error:
                _log_swallowed("_prewarm_boot_channel_ready: _ordered, block_key = _get_channel_ordered_content(boot_ch, ch_info)", _swallowed_error)
                block_key = "Full Day"
            _picture_box_before_loudness(norm_p)

            def _boot_channel_loudness(_ch=boot_ch, _block=block_key or "Full Day", _p=norm_p):
                # WARNING: same scan as the tune-in priority scan (priority slot, default timeouts); a short timeout here would abandon it and rescan after boot. Boot does not wait for it: it runs while the load bar fills, so it is done or nearly done when the channel starts.
                _mark_loudness_priority_active()
                try:
                    _probe_and_apply_loudness_blocking("channel", _ch, _block, _p, "boot prewarm scan", priority=True)
                except Exception as _loud_err:
                    log.warning("[BOOT PREWARM] boot-channel loudness scan failed (the channel still starts): %s", _loud_err)
                finally:
                    _mark_loudness_priority_done()
            threading.Thread(target=_boot_channel_loudness, daemon=True, name="boot-loudness").start()
    except Exception as e:
        log.warning(f"[BOOT PREWARM] Boot-channel readiness probe failed (non-fatal, boot continues normally): {e}")


def _gather_other_channels_now_playing_targets(boot_ch):
    """Every other active channel's now-playing file still missing cached duration and/or dims, as (ch_str, norm_p, mode, needs_dur, needs_dims) tuples."""
    targets = []
    if db is None:
        return targets
    for i in range(5, 45):
        ch_str = str(i).zfill(2)
        if ch_str == boot_ch:
            continue
        ch_info = db.channels_db.get(ch_str, {})
        if not ch_info or not ch_info.get("active", True):
            continue
        try:
            state = _get_probe_now_state(ch_str)
        except Exception as _swallowed_error:
            _log_swallowed("_gather_other_channels_now_playing_targets: state = _get_probe_now_state(ch_str)", _swallowed_error)
            continue
        file_path = state.get("file", "")
        mode = state.get("mode", "")
        if not file_path or not _cached_path_exists(file_path) or not _is_drive_responsive(file_path):
            continue
        norm_p = os.path.normpath(file_path)
        cached = _read_file_probe_facts(norm_p)
        needs_dur = not cached.get("duration")
        needs_dims = (not cached.get("dims") and mode in ("Video", "Commercial")
                      and not is_dvd_disc_source(norm_p))
        if not (needs_dur or needs_dims):
            continue
        targets.append((ch_str, norm_p, mode, needs_dur, needs_dims))
    return targets


# ============================================================================
# SECTION: Boot units (one file = one slice of the boot bar)
# ============================================================================
_boot_units_lock = threading.Lock()


def _boot_unit_new(weight, label, path):
    """Returns one boot-bar unit: its weight in expected seconds, a label, the file path, and start / end / abandoned state."""
    return {"w": float(weight), "label": label, "path": path, "start": None, "end": None, "abandoned": False}


def _boot_unit_hold_seconds():
    """Returns the longest one file may hold the boot bar: the time the whole bar is expected to take, never below the governor minimum."""
    floor = _boot_bar_const("BOOT_UNIT_HOLD_MIN_SECONDS", 5.0)
    return max(floor, float(app_state.get("_boot_expected_total_s", 0.0) or 0.0))


def _boot_unit_finish(unit, abandoned):
    """Marks a unit finished once and returns True only for the caller that finished it."""
    with _boot_units_lock:
        if unit["end"] is not None:
            return False
        unit["end"] = time.time()
        unit["abandoned"] = bool(abandoned)
        if abandoned:
            app_state["_boot_abandoned_units"] = app_state.get("_boot_abandoned_units", 0) + 1
        return True


def _bounded_file_size(path, timeout_s):
    """Returns the file size in bytes, or None when it cannot be read within timeout_s seconds."""
    box = []
    done = threading.Event()

    def _worker():
        try:
            box.append(os.path.getsize(path))
        except Exception as _swallowed_error:
            _log_swallowed("_bounded_file_size._worker: box.append(os.path.getsize(path))", _swallowed_error)
        finally:
            done.set()

    threading.Thread(target=_worker, daemon=True, name="BootSizeProbe").start()
    if done.wait(timeout_s) and box:
        return box[0]
    return None


def _boot_other_file_sizes(targets):
    """Returns the size in bytes (or None) of each target file, read in parallel and bounded per file."""
    if not targets:
        return []
    from concurrent.futures import ThreadPoolExecutor
    timeout_s = _boot_bar_const("BOOT_FILE_SIZE_TIMEOUT_SECONDS", 1.5)
    workers = max(1, int(_boot_bar_const("BOOT_FILE_SIZE_WORKERS", 8)))
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="prewarm-size") as _pex:
        return list(_pex.map(lambda _t: _bounded_file_size(_t[1], timeout_s), targets))


def _boot_build_other_units(targets, sizes, costs):
    """Returns one unit per target; the files share costs['per_target'] x count, part equally and part by file size."""
    n = len(targets)
    if n == 0:
        return []
    size_weight = min(1.0, max(0.0, _boot_bar_const("BOOT_BAR_FILE_SIZE_WEIGHT", 0.5)))
    known = [x for x in sizes if x]
    mean = (sum(known) / len(known)) if known else 0
    effective = [(x if x else mean) for x in sizes]
    total = float(sum(effective))
    pool = costs["per_target"] * n
    units = []
    for target, size in zip(targets, effective):
        size_share = (size / total) if total > 0 else 1.0 / n
        share = (1.0 - size_weight) / n + size_weight * size_share
        units.append(_boot_unit_new(pool * share, os.path.basename(target[1]), target[1]))
    return units


def _boot_unit_credit(unit, cap, now):
    """Returns the part of a unit's weight the bar counts now: all when finished, a share that keeps creeping toward the cap while it runs, none before it starts."""
    if unit["end"] is not None:
        return unit["w"]
    if unit["start"] is None:
        return 0.0
    return cap * unit["w"] * (1.0 - math.exp(-max(0.0, now - unit["start"]) / max(unit["w"], 0.05)))


def _boot_prewarm_open_units():
    """Returns every boot-prewarm unit that has not finished."""
    units = list(app_state.get("_boot_pw_units") or [])
    ready = app_state.get("_boot_pw_ready_unit")
    if ready is not None:
        units.append(ready)
    return [u for u in units if u["end"] is None]


def _boot_stall_summary():
    """Returns one line naming what boot is still waiting on."""
    done = app_state.get("_boot_steps_done", set())
    waiting = [step for step in BOOT_STEPS if step not in done]
    open_units = _boot_prewarm_open_units()
    names = ", ".join(u["label"] for u in open_units[:5])
    roots = ", ".join(_unresponsive_drive_roots()) or "none"
    return "unfinished steps=%s open files=%d [%s] drives not responding=%s" % (waiting, len(open_units), names, roots)


def _boot_prewarm_watchdog():
    """Logs once what boot is waiting on, then at the governor cap stops the optional boot warm-up from holding the loading screen."""
    report_s = _boot_bar_const("BOOT_STALL_REPORT_SECONDS", 8.0)
    cap_s = _boot_bar_const("BOOT_PREWARM_MAX_SECONDS", 20.0)
    t0 = time.monotonic()
    if report_s > 0:
        if _app_shutting_down.wait(report_s):
            return
        if len(app_state.get("_boot_steps_done", set())) < len(BOOT_STEPS):
            log.warning("[BOOT STALL] %.0fs into boot: %s", report_s, _boot_stall_summary())
    if cap_s > 0:
        left = cap_s - (time.monotonic() - t0)
        if left > 0 and _app_shutting_down.wait(left):
            return
        if "boot_prewarm" not in app_state.get("_boot_steps_done", set()):
            log.warning("[BOOT STALL] boot warm-up stopped holding the loading screen after %.0fs: %s", cap_s, _boot_stall_summary())
            app_state["_boot_prewarm_abandoned"] = True
            for _unit in _boot_prewarm_open_units():
                _boot_unit_finish(_unit, True)
            app_state["_boot_prewarm_done"] = app_state.get("_boot_prewarm_total", 0)
            _mark_boot_step("boot_prewarm")


def _prewarm_other_channels_now_playing(targets, units, done_lock):
    """Probes duration and dims for each target on its own thread, a few at a time; skips a file whose drive is not responding or that holds the bar past _boot_unit_hold_seconds."""
    _gate_wait = performance_governor.BOOT_PREWARM_GATE_WAIT_SECONDS if performance_governor is not None else None
    _workers = max(1, int(_boot_bar_const("BOOT_PREWARM_OTHER_WORKERS", 4)))
    _skipped = [0]

    def _count_done():
        with done_lock:
            app_state["_boot_prewarm_done"] += 1

    def _skip_unit(_t, _unit, _why):
        if _boot_unit_finish(_unit, True):
            _count_done()
            _root = media._drive_root_of(_t[1]) or ""
            _log_warn_throttled(
                "rtv_boot_prewarm_skip_" + _root,
                "[BOOT PREWARM] skipping ch%s now-playing probe -- %s (%s): %s",
                _t[0], _why, _drive_latency_summary(_t[1]), os.path.basename(_t[1]))

    def _prewarm_one(_t, _unit):
        ch_str, norm_p, mode, needs_dur, needs_dims = _t
        try:
            with media._gov_gate("probe_and_duration", timeout=_gate_wait,
                                 label="boot_prewarm_np(%s)" % os.path.basename(norm_p)) as _admitted:
                if not _admitted:
                    with done_lock:
                        _skipped[0] += 1
                    return
                if needs_dur and needs_dims:
                    _dur, _dims = _probe_duration_and_dims_combined_impl(norm_p)
                else:
                    _dur = _probe_duration_seconds_fast(norm_p) if needs_dur else None
                    _dims = _probe_dims_guarded(norm_p) if needs_dims else None
            if _dur or _dims:
                _save_file_probe_facts(norm_p, duration=_dur, dims=_dims)
        except Exception as e:
            log.warning(f"[BOOT PREWARM] ch{ch_str} now-playing probe failed "
                        f"(non-fatal, boot continues normally): {e}")
        finally:
            if _boot_unit_finish(_unit, False):
                _count_done()

    pending = list(zip(targets, units))
    active = []
    while pending or active:
        if _app_shutting_down.is_set():
            break
        _now = time.time()
        _hold = _boot_unit_hold_seconds()
        for _entry in list(active):
            _t, _unit = _entry
            if _unit["end"] is not None:
                active.remove(_entry)
            elif not _is_drive_responsive(_t[1]):
                _skip_unit(_t, _unit, "its drive stopped responding")
                active.remove(_entry)
            elif _now - _unit["start"] >= _hold:
                _skip_unit(_t, _unit, "it held the boot bar for %.0fs" % _hold)
                active.remove(_entry)
        while pending and len(active) < _workers:
            _t, _unit = pending.pop(0)
            if _is_drive_degraded(_t[1]):
                _skip_unit(_t, _unit, "its drive looks degraded right now")
                continue
            _unit["start"] = time.time()
            threading.Thread(target=_prewarm_one, args=(_t, _unit), daemon=True, name="prewarm-np").start()
            active.append((_t, _unit))
        time.sleep(0.05)
    if _skipped[0]:
        log.info("[BOOT PREWARM] %d other-channel now-playing probe(s) skipped while the PC was busy; the normal scan fills them in", _skipped[0])


# WARNING: the fallback numbers below must match BOOT_READY_UNIT_WEIGHT in performance_governor.py; they are used only when that module fails to import.
_BOOT_READY_UNIT_WEIGHT = performance_governor.BOOT_READY_UNIT_WEIGHT if performance_governor is not None else 15

_boot_drive_wake_done = threading.Event()


def _boot_wake_candidates_by_drive():
    """Returns {drive root: up to three scheduled file paths on it}, with the boot channel's files first, so a wake-up read can fall back if one file is gone."""
    by_root = {}
    if db is None:
        return by_root
    boot_ch = str(db.config.get("last_channel", "05")).zfill(2)
    order = [boot_ch] + [c for c in db.channels_db if c != boot_ch]
    for ch in order:
        ch_info = db.channels_db.get(ch) or {}
        for block in (ch_info.get("schedules", {}) or {}).values():
            for item in block:
                p = item.get("path", item.get("file", "")) if isinstance(item, dict) else str(item)
                root = media._drive_root_of(p) if p else None
                if root and len(by_root.setdefault(root, [])) < 3 and p not in by_root[root]:
                    by_root[root].append(p)
    return by_root


def _wake_drive_with_read(root, candidates, deadline):
    """Reads the first bytes of one real file on the drive (the first candidate that opens) so a sleeping hard drive spins up; returns True once a read finished."""
    for path in candidates:
        if time.monotonic() >= deadline:
            return False
        try:
            os.listdir(os.path.dirname(path))
            with open(path, "rb") as _f:
                _f.read(65536)
            return True
        except Exception as _swallowed_error:
            _log_swallowed("_wake_drive_with_read: reading the start of a candidate file", _swallowed_error)
    return False


def _wake_media_drives():
    """Boot step: spins up every drive that holds scheduled media before the boot warm-up and the first scan touch it; never blocks boot past BOOT_DRIVE_WAKE_SECONDS."""
    try:
        limit_s = float(_boot_bar_const("BOOT_DRIVE_WAKE_SECONDS", 15.0))
        if db is None or limit_s <= 0:
            return
        t0 = time.monotonic()
        deadline = t0 + limit_s
        while not getattr(db, "ready_flag", False) and time.monotonic() < deadline:
            if _app_shutting_down.wait(0.05):
                return
        by_root = _boot_wake_candidates_by_drive()
        if not by_root:
            return
        log.info("[BOOT] waking %d media drive(s) before the first scan: %s", len(by_root), ", ".join(sorted(by_root)))
        results = {}

        def _one(_root, _paths):
            _started = time.monotonic()
            _ok = _wake_drive_with_read(_root, _paths, deadline)
            results[_root] = (_ok, time.monotonic() - _started)

        threads = [threading.Thread(target=_one, args=(r, p), daemon=True, name="DriveWake") for r, p in by_root.items()]
        for _t in threads:
            _t.start()
        for _t in threads:
            _t.join(max(0.0, deadline - time.monotonic()))
        for root in sorted(by_root):
            if root in results and results[root][0]:
                log.info("[BOOT] drive %s is awake (%.1fs)", root, results[root][1])
            else:
                log.warning("[BOOT] drive %s did not answer within %.0fs; boot continues without waiting for it", root, limit_s)
    except Exception as e:
        log.warning("[BOOT] drive wake-up failed (non-fatal, boot continues normally): %s", e)
    finally:
        _boot_drive_wake_done.set()


# WARNING: the fallback numbers below must match DRIVE_KEEP_AWAKE_INTERVAL_SECONDS and DRIVE_KEEP_AWAKE_READ_TIMEOUT_SECONDS in performance_governor.py; they are used only when that module fails to import.
_DRIVE_KEEP_AWAKE_INTERVAL_S = performance_governor.DRIVE_KEEP_AWAKE_INTERVAL_SECONDS if performance_governor is not None else 300.0
_DRIVE_KEEP_AWAKE_READ_TIMEOUT_S = performance_governor.DRIVE_KEEP_AWAKE_READ_TIMEOUT_SECONDS if performance_governor is not None else 10.0


def _keep_media_drives_awake_once():
    """One keep-awake round: reads the start of one real scheduled file on every media drive that is not known dead, so a sleeping drive spins up before a show needs it; returns how many drives answered."""
    try:
        by_root = _boot_wake_candidates_by_drive()
        dead = set(_unresponsive_drive_roots())
        by_root = {r: p for r, p in by_root.items() if r not in dead}
        if not by_root:
            return 0
        deadline = time.monotonic() + _DRIVE_KEEP_AWAKE_READ_TIMEOUT_S
        results = {}

        def _one(_root, _paths):
            results[_root] = _wake_drive_with_read(_root, _paths, deadline)

        threads = [threading.Thread(target=_one, args=(r, p), daemon=True, name="DriveKeepAwake") for r, p in by_root.items()]
        for _t in threads:
            _t.start()
        for _t in threads:
            _t.join(max(0.0, deadline - time.monotonic()))
        return sum(1 for _ok in results.values() if _ok)
    except Exception as e:
        log.warning("[DRIVE KEEP-AWAKE] a round failed (non-fatal): %s", e)
        return 0


def _keep_media_drives_awake_loop():
    """Thread: after the boot wake-up, repeats a keep-awake round every _DRIVE_KEEP_AWAKE_INTERVAL_S for as long as the app is up (owner 2026-11-06, 14.3); 0 turns it off."""
    if _DRIVE_KEEP_AWAKE_INTERVAL_S <= 0:
        return
    _boot_drive_wake_done.wait()
    while not _app_shutting_down.wait(_DRIVE_KEEP_AWAKE_INTERVAL_S):
        _keep_media_drives_awake_once()


def _prewarm_boot_channel_paths():
    from concurrent.futures import ThreadPoolExecutor
    # WARNING: the fallback numbers below must match BOOT_PREWARM_WORKERS in performance_governor.py; they are used only when that module fails to import.
    _PREWARM_WORKERS = performance_governor.BOOT_PREWARM_WORKERS if performance_governor is not None else 8
    try:
        if db is None:
            return
        # WARNING: the fallback numbers below must match BOOT_PREWARM_SETTINGS_WAIT_SECONDS in performance_governor.py; they are used only when that module fails to import.
        _DB_READY_WAIT_TIMEOUT_S = performance_governor.BOOT_PREWARM_SETTINGS_WAIT_SECONDS if performance_governor is not None else 15.0
        _db_wait_deadline = time.monotonic() + _DB_READY_WAIT_TIMEOUT_S
        while not getattr(db, "ready_flag", False) and time.monotonic() < _db_wait_deadline:
            time.sleep(0.05)
        if not getattr(db, "ready_flag", False):
            log.warning(
                "[BOOT PREWARM] db.load_settings_async still not ready after "
                "%.1fs -- proceeding with whatever channels_db has; boot "
                "channel's schedule warm-up may be skipped/incomplete this run.",
                _DB_READY_WAIT_TIMEOUT_S,
            )
        # WARNING: the drives must be awake before any file is probed, or the probes are the reads that wake them and look like a failing drive.
        _boot_drive_wake_done.wait(max(0.0, float(_boot_bar_const("BOOT_DRIVE_WAKE_SECONDS", 15.0))))
        boot_ch = str(db.config.get("last_channel", "05")).zfill(2)
        if boot_ch in ("03", "04") or not boot_ch:
            boot_ch = "05"
        ch_info = db.channels_db.get(boot_ch)
        paths = set()
        if ch_info:
            for block in ch_info.get("schedules", {}).values():
                for item in block:
                    p = item.get("path", item.get("file", "")) if isinstance(item, dict) else str(item)
                    if p:
                        paths.add(p)
        _other_np_targets = _gather_other_channels_now_playing_targets(boot_ch)
        _boot_costs = _boot_bar_costs()
        _other_units = _boot_build_other_units(
            _other_np_targets, _boot_other_file_sizes(_other_np_targets), _boot_costs)
        _ready_unit = _boot_unit_new(_boot_costs["ready"], "boot channel ready step", "")
        app_state["_boot_pw_n_paths"] = len(paths)
        app_state["_boot_pw_n_others"] = len(_other_np_targets)
        app_state["_boot_pw_paths_done"] = 0
        app_state["_boot_pw_units"] = _other_units
        app_state["_boot_pw_ready_unit"] = _ready_unit
        app_state["_boot_expected_total_s"] = (
            _boot_costs["quick"] + _boot_costs["paths"] + _boot_costs["ready"] + sum(u["w"] for u in _other_units))
        app_state["_boot_pw_units_ready"] = True
        app_state["_boot_pw_t_start"] = time.time()
        app_state["_boot_prewarm_total"] = len(paths) + len(_other_np_targets) + _BOOT_READY_UNIT_WEIGHT
        app_state["_boot_prewarm_done"] = 0
        _prewarm_done_lock = threading.Lock()

        def _ready_job():
            app_state["_boot_pw_ready_started"] = _ready_unit["start"]
            try:
                _prewarm_boot_channel_ready(boot_ch)
            finally:
                app_state["_boot_pw_t_ready_end"] = time.time()
                with _prewarm_done_lock:
                    if _boot_unit_finish(_ready_unit, False):
                        app_state["_boot_prewarm_done"] += _BOOT_READY_UNIT_WEIGHT
                    app_state["_boot_pw_ready_finished"] = True

        _ready_unit["start"] = time.time()
        _ready_thread = threading.Thread(target=_ready_job, daemon=True, name="boot-ready")
        _ready_thread.start()

        if paths:
            def _prewarm_one(_p):
                _result = _cached_path_exists(_p)
                with _prewarm_done_lock:
                    app_state["_boot_prewarm_done"] += 1
                    app_state["_boot_pw_paths_done"] += 1
                return _result

            with ThreadPoolExecutor(max_workers=_PREWARM_WORKERS,
                                     thread_name_prefix="prewarm") as _pex:
                list(_pex.map(_prewarm_one, paths))
        app_state["_boot_pw_t_paths_end"] = time.time()
        if _other_np_targets:
            _prewarm_other_channels_now_playing(_other_np_targets, _other_units, _prewarm_done_lock)
        app_state["_boot_pw_t_others_end"] = time.time()
        _ready_thread.join(timeout=max(0.0, _ready_unit["start"] + _boot_unit_hold_seconds() - time.time()))
        if _ready_thread.is_alive():
            with _prewarm_done_lock:
                if _boot_unit_finish(_ready_unit, True):
                    app_state["_boot_prewarm_done"] += _BOOT_READY_UNIT_WEIGHT
            log.warning("[BOOT PREWARM] boot-channel ready step (including its loudness scan) still running after %.0fs; boot continues without it", time.time() - _ready_unit["start"])
    except Exception as e:
        log.warning(f"[BOOT PREWARM] Path prewarm failed (non-fatal, boot continues normally): {e}")
    finally:
        app_state["_boot_prewarm_done"] = app_state.get("_boot_prewarm_total", 0)
        _mark_boot_step("boot_prewarm")


SPLASH_IMAGES_BASE_DIR = media.resolve_splash_images_dir()
SPLASH_VIDEOS_BASE_DIR = os.path.join(resolve_main_dir(), "videos", "splash screen videos")

MENU_BG_BASE_DIR = os.path.join(SPLASH_IMAGES_BASE_DIR, "MENU")
WATERMARK_BASE_DIR = os.path.join(SPLASH_IMAGES_BASE_DIR, "WATERMARK")
DEFAULT_WATERMARK_PATH = os.path.join(WATERMARK_BASE_DIR, "watermark.png")


# ============================================================================
# SECTION: Splash folders & ASR caption cache purge
# ============================================================================


def _ensure_splash_folder_structure():
    try:
        from game_deck import CONSOLE_ORDER
        for console_key in CONSOLE_ORDER:
            os.makedirs(os.path.join(SPLASH_IMAGES_BASE_DIR, console_key), exist_ok=True)
            if console_key != "MENU":
                os.makedirs(os.path.join(SPLASH_VIDEOS_BASE_DIR, console_key), exist_ok=True)
        os.makedirs(MENU_BG_BASE_DIR, exist_ok=True)
    except Exception as e:
        log.warning(f"[BOOT] Splash folder scaffolding failed (non-fatal): {e}")
    try:
        loudness_dir = resolve_loudness_dir()
        print(f"[BOOT] Loudness work folder ready: {loudness_dir}")
    except Exception as e:
        log.warning(f"[BOOT] Loudness folder scaffolding failed (non-fatal): {e}")


# ============================================================================
# SECTION: Caption precache worker
# ============================================================================


def _caption_precache_worker():
    """Background pass that finds and saves, ahead of playback, where each upcoming file's captions come from for TV-station and visualizer channels."""
    if db is None:
        return
    pygame.time.wait(1000)

    IDLE_SLEEP = CAPTION_IDLE_SLEEP_SECONDS
    BETWEEN_CHEAP_CHECKS = CAPTION_PRECACHE_BETWEEN_CHEAP_CHECKS_SECONDS

    def _scan_pace(base_seconds):
        return _background_scan_pace_seconds(base_seconds)

    def _gather_upcoming_caption_candidates():
        now_playing_out = []
        upcoming_out = []
        watched_out = []
        watched_ch = str(app_state.get("current_channel", "")).zfill(2)
        for i in range(5, 45):
            ch_str = str(i).zfill(2)
            ch_info = db.channels_db.get(ch_str, {})
            if not ch_info or not ch_info.get("active", True):
                continue
            try:
                now_state = _get_probe_now_state(ch_str)
                current_file = now_state.get("file", "")
                current_seek = now_state.get("seek", 0) or 0
                ordered, block_key = _get_channel_ordered_content(ch_str, ch_info)
                if not (ordered and block_key):
                    continue
                upcoming = _next_n_from_ordered(ordered, current_file, n=len(ordered))
            except Exception as e:
                log.warning(f"[TV CAPTIONS PRECACHE] gather failed for ch {ch_str}: {e}")
                continue
            for slot, entry in enumerate(upcoming):
                for p in _paths_from_entry(entry):
                    if p and _cached_path_exists(p):
                        norm_p = os.path.normpath(p)
                        if slot == 0 and current_file and current_file in _paths_from_entry(entry):
                            (watched_out if ch_str == watched_ch else now_playing_out).append(
                                (norm_p, True, float(current_seek)))
                        else:
                            upcoming_out.append((norm_p, False, 0.0))
        seen = set()
        deduped = []
        for p, is_now, seek in watched_out + now_playing_out + upcoming_out:
            if p not in seen:
                seen.add(p)
                deduped.append((p, is_now, seek))
        return deduped

    def _current_watched_file():
        """The exact file airing on whichever channel is on screen right now."""
        # WARNING: read fresh on every call, not from the snapshot taken when the candidate list was gathered.
        ch = str(app_state.get("current_channel", "")).zfill(2)
        try:
            return _get_probe_now_state(ch).get("file", "") or ""
        except Exception as _swallowed_error:
            _log_swallowed("_current_watched_file: return _get_probe_now_state(ch).get('file', '') or ''", _swallowed_error)
            return ""

    def _captions_enabled():
        return _setting_on("tv_captions_enabled")

    while True:
        if _app_shutting_down.is_set():
            return
        if not _captions_enabled():
            if _app_shutting_down.wait(IDLE_SLEEP):
                return
            continue
        candidates = _gather_upcoming_caption_candidates()
        if not candidates:
            if _app_shutting_down.wait(IDLE_SLEEP):
                return
            continue

        _watched_snapshot = _current_watched_file()

        for norm_p, is_now_playing, start_seek in candidates:
            if _app_shutting_down.is_set():
                return

            if _watched_snapshot and _current_watched_file() != _watched_snapshot:
                break

            if not _captions_enabled():
                break

            while _background_scan_should_pause():
                if _app_shutting_down.wait(_scan_pace(BETWEEN_CHEAP_CHECKS)):
                    return
            if media.file_facts(norm_p)["caption_kind"]:
                continue

            try:
                info = resolve_caption_source(norm_p)
            except Exception as e:
                log.warning(f"[TV CAPTIONS PRECACHE] resolve failed for {norm_p}: {e}")
                continue

            if info["kind"] == "embedded":
                out_path = os.path.join(resolve_captions_dir(), f"tv_{abs(hash(norm_p.lower()))}.srt")
                with media._gov_gate("probe_and_duration", label="caption_extract(%s)" % os.path.basename(norm_p)):
                    _extracted = _extract_embedded_subtitle_to_file(norm_p, info["stream_index"], out_path)
                if _extracted:
                    media.note_caption_source(norm_p, "embedded", out_path)
            elif info["kind"] not in ("baked", "sidecar"):
                continue

            if _app_shutting_down.wait(_scan_pace(BETWEEN_CHEAP_CHECKS)):
                return

        if _app_shutting_down.wait(IDLE_SLEEP):
            return


# WARNING: the fallback numbers below must match GPU_DEDICATED_VRAM_FLOOR_BYTES in performance_governor.py; they are used only when that module fails to import.
_GPU_DEDICATED_VRAM_FLOOR_BYTES = performance_governor.GPU_DEDICATED_VRAM_FLOOR_BYTES if performance_governor is not None else 512 * 1024 * 1024

_DXGI_ADAPTER_FLAG_SOFTWARE = 0x2


# ============================================================================
# SECTION: GPU tier detection
# ============================================================================


class _DXGI_GUID(ctypes.Structure):
    _fields_ = [
        ("Data1", ctypes.c_uint32),
        ("Data2", ctypes.c_uint16),
        ("Data3", ctypes.c_uint16),
        ("Data4", ctypes.c_uint8 * 8),
    ]


class _DXGI_ADAPTER_DESC1(ctypes.Structure):
    _fields_ = [
        ("Description", ctypes.c_wchar * 128),
        ("VendorId", ctypes.c_uint32),
        ("DeviceId", ctypes.c_uint32),
        ("SubSysId", ctypes.c_uint32),
        ("Revision", ctypes.c_uint32),
        ("DedicatedVideoMemory", ctypes.c_size_t),
        ("DedicatedSystemMemory", ctypes.c_size_t),
        ("SharedSystemMemory", ctypes.c_size_t),
        ("AdapterLuid", ctypes.c_int64),
        ("Flags", ctypes.c_uint32),
    ]


def _dxgi_com_call(interface_ptr, vtable_index, restype, argtypes, *args):
    """Calls a COM method by vtable slot."""
    vtbl = ctypes.cast(interface_ptr, ctypes.POINTER(ctypes.c_void_p)).contents.value
    func_addr = ctypes.cast(
        vtbl + vtable_index * ctypes.sizeof(ctypes.c_void_p),
        ctypes.POINTER(ctypes.c_void_p),
    ).contents.value
    prototype = ctypes.WINFUNCTYPE(restype, ctypes.c_void_p, *argtypes)
    return prototype(func_addr)(interface_ptr, *args)


def _detect_gpu_tier():
    """Enumerates real (non-software) DXGI adapters and classifies the machine's GPU tier."""
    # WARNING: fails soft to ("none", []) so a failure here can never crash boot.
    if os.name != "nt":
        return "none", []

    factory_ptr = ctypes.c_void_p()
    adapters = []
    try:
        dxgi = ctypes.windll.dxgi
        iid_factory1 = _DXGI_GUID(
            0x7B7166EC, 0x21C7, 0x44AE,
            (ctypes.c_uint8 * 8)(0xB2, 0x1A, 0xC9, 0xAE, 0x32, 0x1A, 0xE3, 0x69),
        )
        hr = dxgi.CreateDXGIFactory1(ctypes.byref(iid_factory1), ctypes.byref(factory_ptr))
        if hr != 0 or not factory_ptr:
            log.info("[GPU DETECT] CreateDXGIFactory1 failed (hr=0x%08X) -- treating as no GPU info available.", hr & 0xFFFFFFFF)
            return "none", []

        index = 0
        while True:
            adapter_ptr = ctypes.c_void_p()
            hr = _dxgi_com_call(
                factory_ptr, 12, ctypes.c_int32,
                [ctypes.c_uint32, ctypes.POINTER(ctypes.c_void_p)],
                index, ctypes.byref(adapter_ptr),
            )
            if hr != 0 or not adapter_ptr:
                break

            try:
                desc = _DXGI_ADAPTER_DESC1()
                hr = _dxgi_com_call(
                    adapter_ptr, 10, ctypes.c_int32,
                    [ctypes.POINTER(_DXGI_ADAPTER_DESC1)],
                    ctypes.byref(desc),
                )
                if hr == 0:
                    adapters.append({
                        "name": desc.Description,
                        "dedicated_vram_mb": desc.DedicatedVideoMemory / (1024 * 1024),
                        "is_software": bool(desc.Flags & _DXGI_ADAPTER_FLAG_SOFTWARE),
                    })
            finally:
                _dxgi_com_call(adapter_ptr, 2, ctypes.c_uint32, [])
            index += 1
    except Exception as e:
        log.warning("[GPU DETECT] DXGI adapter enumeration failed: %s", e)
        return "none", []
    finally:
        if factory_ptr:
            _dxgi_com_call(factory_ptr, 2, ctypes.c_uint32, [])

    adapters.sort(key=lambda a: a["dedicated_vram_mb"], reverse=True)
    real_adapters = [a for a in adapters if not a["is_software"]]
    if not real_adapters:
        tier = "none"
    elif real_adapters[0]["dedicated_vram_mb"] * 1024 * 1024 >= _GPU_DEDICATED_VRAM_FLOOR_BYTES:
        tier = "dedicated"
    else:
        tier = "onboard"
    return tier, adapters


def _best_gpu_name():
    """Returns the name of the most capable real (non-software) adapter, judged by dedicated video memory, or None when there is none."""
    # WARNING: _detect_gpu_tier sorts adapters by dedicated VRAM, but this re-checks so the pick never depends on that ordering.
    _real = [a for a in (getattr(db, "_detected_gpu_adapters", None) or [])
             if not a.get("is_software") and str(a.get("name", "")).strip()]
    if not _real:
        return None
    return max(_real, key=lambda a: a.get("dedicated_vram_mb", 0))["name"]


def _apply_boot_gpu_choice(reason="boot"):
    """Picks the most capable GPU for rendering unless the person chose a GPU or CPU Only themselves on the GPU/CPU button."""
    # WARNING: render_mode_user_chosen is set only by the GPU/CPU button; without it the pick is automatic and is redone on every boot.
    if db is None or not GPU_RENDER_MODE_ENABLED:
        return
    _best = _best_gpu_name()
    if _best is None:
        return
    _saved = db.config.get("render_mode_override", "cpu_only")
    _names = {a["name"] for a in db._detected_gpu_adapters if not a.get("is_software")}
    if db.config.get("render_mode_user_chosen", False) and (_saved == "cpu_only" or _saved in _names):
        log.info("[GPU DETECT] %s: keeping the GPU/CPU choice the person made: %s", reason, _saved)
        return
    if _saved != _best:
        db.config["render_mode_override"] = _best
        db.save_settings()
    log.info("[GPU DETECT] %s: most capable GPU selected: %s", reason, _best)


BOOT_STEPS = ("db", "game_deck", "visualizer_deck", "vlc_engine", "boot_prewarm")


# ============================================================================
# SECTION: Background subsystem worker
# ============================================================================


def _mark_boot_step(step_key):
    """Record a boot step as finished (success or failure -- see BOOT_STEPS comment)."""
    app_state.setdefault("_boot_steps_done", set()).add(step_key)
    app_state.setdefault("_boot_step_times", {})[step_key] = time.time()


# ============================================================================
# SECTION: Boot load bar (steady, time-based, learns this PC's boot costs)
# ============================================================================
_BOOT_BAR_QUICK_STEPS = ("db", "game_deck", "visualizer_deck", "vlc_engine")


def _boot_bar_const(name, fallback):
    return getattr(performance_governor, name, fallback) if performance_governor is not None else fallback


def _boot_bar_costs():
    costs = {
        "quick": _boot_bar_const("BOOT_BAR_DEFAULT_QUICK_SECONDS", 3.0),
        "paths": _boot_bar_const("BOOT_BAR_DEFAULT_PATHS_SECONDS", 0.5),
        "ready": _boot_bar_const("BOOT_BAR_DEFAULT_READY_SECONDS", 6.0),
        "per_target": _boot_bar_const("BOOT_BAR_DEFAULT_PER_TARGET_SECONDS", 0.6),
        "others": _boot_bar_const("BOOT_BAR_DEFAULT_OTHERS_SECONDS", 6.0),
    }
    try:
        stored = db.config.get(_boot_bar_const("BOOT_BAR_CONFIG_KEY", "_boot_bar_costs")) if db is not None else None
        if isinstance(stored, dict):
            for key in costs:
                value = float(stored.get(key, costs[key]))
                if value > 0:
                    costs[key] = value
    except Exception as _swallowed_error:
        _log_swallowed("_boot_bar_costs: stored = db.config.get(_boot_bar_const('BOOT_BAR_CONFIG_KEY', '_boot_bar_costs')) if db...", _swallowed_error)
    return costs


def _boot_prewarm_weight_and_credit(costs, cap, now):
    """Returns (total weight, credited weight) of the boot warm-up: the paths, every other-channel file by size, and the boot-channel ready step."""
    if not app_state.get("_boot_pw_units_ready"):
        return costs["paths"] + costs["ready"] + costs["others"], 0.0
    n_paths = app_state.get("_boot_pw_n_paths", 0)
    total = credit = 0.0
    if n_paths > 0:
        total += costs["paths"]
        paths_fraction = 1.0 if app_state.get("_boot_pw_t_paths_end") else min(1.0, app_state.get("_boot_pw_paths_done", 0) / float(n_paths))
        credit += costs["paths"] * paths_fraction
    units = list(app_state.get("_boot_pw_units") or [])
    ready = app_state.get("_boot_pw_ready_unit")
    if ready is not None:
        units.append(ready)
    for unit in units:
        total += unit["w"]
        credit += _boot_unit_credit(unit, cap, now)
    return total, credit


def _boot_bar_target_percent(done, now):
    """Returns the bar's target percent: finished work plus a capped share of each unfinished file, over the weight of every file."""
    costs = _boot_bar_costs()
    cap = min(1.0, max(0.0, _boot_bar_const("BOOT_BAR_INFLIGHT_CAP", 0.9)))
    t0 = app_state.get("_boot_bar_t0", now)
    quick_w = costs["quick"] / len(_BOOT_BAR_QUICK_STEPS)
    total = credit = 0.0
    for step in _BOOT_BAR_QUICK_STEPS:
        total += quick_w
        credit += quick_w if step in done else cap * quick_w * (1.0 - math.exp(-max(0.0, now - t0) / max(quick_w, 0.05)))
    pw_total, pw_credit = _boot_prewarm_weight_and_credit(costs, cap, now)
    total += pw_total
    credit += pw_total if "boot_prewarm" in done else pw_credit
    return 100.0 * credit / total if total > 0 else 0.0


def _boot_bar_learn(t0):
    try:
        if db is None or app_state.get("_boot_prewarm_abandoned") or app_state.get("_boot_abandoned_units"):
            return
        times = app_state.get("_boot_step_times", {})
        pw_start = app_state.get("_boot_pw_t_start")
        paths_end = app_state.get("_boot_pw_t_paths_end")
        ready_start = app_state.get("_boot_pw_ready_started")
        ready_end = app_state.get("_boot_pw_t_ready_end")
        others_end = app_state.get("_boot_pw_t_others_end")
        pw_end = times.get("boot_prewarm")
        quick_end = max((times[s] for s in _BOOT_BAR_QUICK_STEPS if s in times), default=None)
        if None in (pw_start, paths_end, ready_start, ready_end, others_end, pw_end, quick_end):
            return
        n_others = app_state.get("_boot_pw_n_others", 0)
        measured = {
            "quick": quick_end - t0,
            "paths": paths_end - pw_start,
            "ready": ready_end - ready_start,
            "others": others_end - paths_end,
        }
        if n_others > 0:
            measured["per_target"] = measured["others"] / n_others
        low = _boot_bar_const("BOOT_BAR_MIN_PHASE_SECONDS", 0.05)
        high = _boot_bar_const("BOOT_BAR_MAX_PHASE_SECONDS", 120.0)
        blend = _boot_bar_const("BOOT_BAR_LEARN_BLEND", 0.5)
        costs = _boot_bar_costs()
        for key, value in measured.items():
            value = min(high, max(low, value))
            costs[key] = round(costs[key] * (1.0 - blend) + value * blend, 3)
        db.config[_boot_bar_const("BOOT_BAR_CONFIG_KEY", "_boot_bar_costs")] = costs
        _mark_settings_dirty()
        log.info("[BOOT BAR] learned costs (seconds): %s", costs)
    except Exception as e:
        log.warning("[BOOT BAR] could not record boot timings (non-fatal): %s", e)


# ============================================================================
# SECTION: Governor signal feed
# ============================================================================
_governor_feed = {
    "throttle": None, "busy": None, "loss": None, "cpu": None, "signature": None,
    "last_feed": 0.0, "tick_wait_ms": 0.0, "vlc_media": None, "vlc_media_key": None,
    "vlc_stats_logged": False, "stall_count": 0, "flip": None,
    "tick_budget_ms": None, "tick_kind": None, "frame_kind": None,
}


def _governor_feed_init():
    f = _governor_feed
    f["busy"] = performance_governor.BusyWindow()
    f["flip"] = performance_governor.BusyWindow()
    f["loss"] = performance_governor.LossTracker()
    f["cpu"] = performance_governor.SystemCpuSampler()
    f["last_feed"] = time.monotonic()
    _throttle = performance_governor.new_throttle()
    _throttle.note_event("boot_tune")
    f["throttle"] = _throttle


def _governor_note_event(kind):
    _throttle = _governor_feed["throttle"]
    if _throttle is not None:
        try:
            _throttle.note_event(kind)
        except Exception as _swallowed_error:
            _log_swallowed("_governor_note_event: _throttle.note_event(kind)", _swallowed_error)


def _governor_screen_kind(game_deck_ref):
    """Which screen the frame belongs to for the pressure test: game, menu, video or other."""
    if (game_deck_ref is not None and getattr(game_deck_ref, "mode", None) == "GAME"
            and getattr(game_deck_ref, "_libretro_core", None) is not None):
        return "game"
    if _lite_menu_screen_active(game_deck_ref):
        return "menu"
    if app_state.get("is_playing_video", False):
        return "video"
    return "other"


def _governor_note_tick_wait(wait_ms, tick_fps=None, kind=None):
    """Records how long the frame-rate wait took, the frame time of the rate it waited for, and the screen it was for."""
    f = _governor_feed
    f["tick_wait_ms"] = wait_ms
    f["tick_budget_ms"] = (1000.0 / tick_fps) if tick_fps and tick_fps > 0 else None
    f["tick_kind"] = kind


def _governor_note_flip(flip_ms):
    f = _governor_feed
    _throttle = f["throttle"]
    if _throttle is None or f["flip"] is None:
        return
    _now = time.monotonic()
    if not _throttle.in_event(_now):
        f["flip"].add(flip_ms, _now)


def _governor_state_signature():
    cfg = getattr(db, "config", None) or {}
    return (app_state.get("current_channel"), bool(app_state.get("show_menu", False)),
            tuple(bool(cfg.get(k, False)) for k in _HEAVY_VISUAL_EFFECT_CONFIG_KEYS),
            _gpu_swapchain_open())


def _governor_event_kind(prev, new):
    if prev[0] != new[0]:
        return "channel_change"
    for _key, _was, _is in zip(_HEAVY_VISUAL_EFFECT_CONFIG_KEYS, prev[2], new[2]):
        if _was != _is:
            return "effect_toggle:" + _key
    if prev[3] != new[3]:
        return "gpu_open" if new[3] else "gpu_close"
    return "menu_open" if prev[1] != new[1] else "state_change"


def _governor_any_drive_degraded():
    try:
        with media._drive_op_latency_lock:
            _roots = list(media._drive_op_latency.keys())
        if any(_is_drive_degraded(_r) for _r in _roots):
            return True
        return bool(_unresponsive_drive_roots())
    except Exception as _swallowed_error:
        _log_swallowed("_governor_any_drive_degraded: with media._drive_op_latency_lock: _roots = list(media._driv", _swallowed_error)
        return False


def _governor_read_vlc_loss(now, in_event):
    f = _governor_feed
    _engine = vlc_engine
    if (_engine is None or vlc is None or getattr(_engine, "_closed", False)
            or getattr(_engine, "_wedged", False) or not app_state.get("is_playing_video", False)):
        return None
    _key = getattr(_engine, "_current_attempt_id", None)
    if _key != f["vlc_media_key"] or f["vlc_media"] is None:
        _old = f["vlc_media"]
        f["vlc_media"] = None
        f["vlc_media_key"] = _key
        if _old is not None:
            try:
                _old.release()
            except Exception as _swallowed_error:
                _log_swallowed("_governor_read_vlc_loss: _old.release()", _swallowed_error)
        f["vlc_media"] = _engine.player.get_media()
    _media_obj = f["vlc_media"]
    if _media_obj is None:
        return None
    _stats = vlc.MediaStats()
    if not _media_obj.get_stats(_stats):
        if not f["vlc_stats_logged"]:
            f["vlc_stats_logged"] = True
            log.info("[GOVERNOR] VLC stats unavailable: get_stats returned failure; "
                     "lost pictures/audio signals stay off")
        return None
    if not f["vlc_stats_logged"]:
        f["vlc_stats_logged"] = True
        log.info("[GOVERNOR] VLC stats available: lost_pictures=%d lost_abuffers=%d displayed=%d played_abuffers=%d",
                 _stats.lost_pictures, _stats.lost_abuffers, _stats.displayed_pictures, _stats.played_abuffers)
    return f["loss"].update(_key, _stats.lost_pictures, _stats.lost_abuffers, now, in_event)


def _governor_feed_tick(now):
    f = _governor_feed
    _throttle = f["throttle"]
    _avg, _worst, _n = f["busy"].stats(now)
    _signals = {}
    if _avg is not None and _n >= performance_governor.MIN_BUSY_SAMPLES:
        _signals["busy_avg_ms"] = _avg
        _signals["busy_worst_ms"] = _worst
    _kind = f["frame_kind"] or "other"
    _ratio, _worst_ratio, _rn = f["busy"].ratio_stats(now, _kind, _throttle.frame_budget_ms)
    _signals["busy_kind"] = _kind
    if _ratio is not None and _rn >= performance_governor.MIN_BUSY_SAMPLES:
        _signals["busy_ratio"] = _ratio
        _signals["busy_worst_ratio"] = _worst_ratio
    if f["tick_budget_ms"]:
        _signals["frame_time_ms"] = f["tick_budget_ms"]
    _cpu = f["cpu"].percent()
    if _cpu is not None:
        _signals["system_cpu_pct"] = _cpu
    try:
        _lost = _governor_read_vlc_loss(now, _throttle.in_event(now))
    except Exception as _loss_err:
        _lost = None
        _log_warn_throttled("governor_vlc_stats", "[GOVERNOR] VLC stats read failed: %s", _loss_err)
    if _lost is not None:
        _signals["lost_pictures"], _signals["lost_audio"] = _lost
    _signals["drive_degraded"] = _governor_any_drive_degraded()
    try:
        _bg_active, _bg_lanes = performance_governor.background_active()
        _signals["background_active"] = _bg_active
        _signals["background_lanes"] = _bg_lanes
    except Exception as _bg_err:
        _log_warn_throttled("governor_bg_active", "[GOVERNOR] background activity read failed: %s", _bg_err)
    _flip_avg, _flip_worst, _flip_n = f["flip"].stats(now)
    if _flip_avg is not None:
        _signals["flip_avg_ms"] = _flip_avg
    _signals["channel"] = app_state.get("current_channel")
    _throttle.update(_signals, now)
    if _throttle.status_due(now):
        log.info(performance_governor.format_status(_throttle, performance_governor.get_profile(), _signals))


def _governor_feed_frame(gap_ms):
    f = _governor_feed
    _throttle = f["throttle"]
    if _throttle is None:
        return
    try:
        _now = time.monotonic()
        _sig = _governor_state_signature()
        _prev = f["signature"]
        f["signature"] = _sig
        if _app_shutting_down.is_set():
            _throttle.note_event("shutdown", _now)
        if _prev is not None and _sig != _prev:
            _throttle.note_event(_governor_event_kind(_prev, _sig), _now)
        _wait_ms = f["tick_wait_ms"]
        f["tick_wait_ms"] = 0.0
        _busy_ms = max(0.0, gap_ms - _wait_ms)
        _in_event = _throttle.in_event(_now)
        f["frame_kind"] = f["tick_kind"]
        if not _in_event:
            f["busy"].add(_busy_ms, _now, f["tick_budget_ms"], f["tick_kind"])
        if gap_ms >= performance_governor.STALL_LOG_MS:
            f["stall_count"] += 1
            log.info("[GOVERNOR] stall gap=%dms busy=%.0fms classified=%s%s", gap_ms, _busy_ms,
                     ("EVENT(%s) NOT counted" % _throttle.event_kind()) if _in_event else "UNEXPLAINED (counts toward pressure)",
                     " (shadow)" if performance_governor.SHADOW_MODE else "")
        if _now - f["last_feed"] >= performance_governor.FEED_INTERVAL_SECONDS:
            f["last_feed"] = _now
            _governor_feed_tick(_now)
    except Exception as _feed_err:
        _log_warn_throttled("governor_feed", "[GOVERNOR] signal feed error: %s", _feed_err)


def _apply_governor_settings_when_db_ready():
    _deadline = time.monotonic() + 15.0
    while not getattr(db, "ready_flag", False) and time.monotonic() < _deadline:
        time.sleep(0.05)
    if getattr(db, "ready_flag", False):
        performance_governor.set_enabled(db.config.get("perf_governor_enabled", True))
        try:
            if performance_governor.apply_boot_mode(db.config):
                db.save_settings_async()
        except Exception as _mode_err:
            log.warning("[GOVERNOR] boot mode pick failed, staying on Standard: %s", _mode_err)
    else:
        log.warning("[GOVERNOR] boot mode pick skipped: db not ready after 15s")


def _start_performance_governor():
    if performance_governor is None:
        log.warning("[GOVERNOR] module not importable, governor off: %s", _PERFORMANCE_GOVERNOR_IMPORT_ERROR)
        return
    try:
        _gpu_names = [a["name"] for a in db._detected_gpu_adapters if not a.get("is_software")]
        try:
            _vlc_ver = vlc.libvlc_get_version().decode("utf-8", "replace") if vlc is not None else ""
        except Exception as _swallowed_error:
            _log_swallowed("_start_performance_governor: _vlc_ver = vlc.libvlc_get_version().decode('utf-8', 'replace') if v...", _swallowed_error)
            _vlc_ver = ""
        performance_governor.start(
            gpu_tier=db._detected_gpu_tier, gpu_names=_gpu_names, vlc_version=_vlc_ver,
            pygame_version=pygame.version.ver,
            sdl_version=".".join(str(_n) for _n in pygame.version.SDL))
        threading.Thread(target=_apply_governor_settings_when_db_ready, daemon=True,
                         name="GovernorSettingsApply").start()
        _governor_feed_init()
    except Exception as _governor_err:
        log.warning("[GOVERNOR] start failed, governor off this run: %s", _governor_err)


def _install_duration_hub():
    """Installs the schedule hub's duration reader so the scheduler, guide and catch-up read every length from the library first."""
    try:
        import media_library as _ml
        hub = _ml.shared_duration_hub()
        media.set_duration_hub(hub)
        log.info("[SCHEDULE HUB] duration reader installed")
    except Exception as e:
        log.warning("[SCHEDULE HUB] duration reader not installed, lengths are not read from the library, only schedule entries hold them: %s", e)



def _update_base_dir():
    if db is not None and getattr(db, "base_dir", None):
        return db.base_dir
    return os.path.dirname(os.path.abspath(sys.argv[0]))


def _open_update_popup(record, automatic):
    """Opens the shared Yes/No update popup unless another confirm is up; an automatic (boot or background) check is held back when the owner ticked Don't show this again, a manual check always shows it."""
    if automatic and db is not None and db.config.get("update_prompt_skip_confirm", False):
        log.info("[UPDATE] popup skipped: the owner chose not to see update prompts (a manual check in System still shows it)")
        return False
    if app_state.get("show_clear_confirm", False):
        return False
    app_state["update_prompt_version"] = str((record or {}).get("version", "") or "")
    app_state["clear_confirm_selection"] = "No"
    app_state["clear_confirm_target"] = "app_update"
    app_state["clear_confirm_focus"] = "buttons"
    # WARNING: the box must start ticked when Don't show this again is saved, or a manual check could never turn the boot prompt back on.
    app_state["clear_confirm_dont_show_again"] = bool(db is not None and db.config.get("update_prompt_skip_confirm", False))
    app_state["clear_confirm_shown_at"] = pygame.time.get_ticks()
    app_state["show_clear_confirm"] = True
    return True


def _set_update_result(result, automatic=False):
    """Copy updater output into the main-thread-owned UI state."""
    if not isinstance(result, dict):
        return
    if result.get("available"):
        app_state["_update_available"] = True
        app_state["_update_up_to_date"] = False
        app_state["_update_status"] = result.get("message", "Update available.")
        app_state["_update_record"] = result.get("staged") or result.get("manifest")
        # WARNING: the boot check and the background check must both open the same Yes/No update popup, or a posted release is missed.
        _open_update_popup(app_state["_update_record"], automatic)
        log.info("[UPDATE] %s", app_state["_update_status"])
    elif result.get("error"):
        app_state["_update_up_to_date"] = False
        app_state["_update_status"] = result["message"]
        log.warning("[UPDATE] %s", app_state["_update_status"])
    elif result.get("message"):
        # WARNING: a result with no newer release must clear the update flags, or the System button keeps offering Update Now; only a manual check shows Up to Date.
        app_state["_update_available"] = False
        app_state["_update_ready"] = False
        if result.get("configured", True) and not automatic:
            app_state["_update_up_to_date"] = True
        app_state["_update_status"] = result["message"]
        log.info("[UPDATE] %s", app_state["_update_status"])


def _start_update_check(boot=False):
    """Looks for a newer release; nothing is downloaded until the owner answers Yes on the popup, for the boot check and the manual one alike."""
    if app_state.get("_update_check_inflight", False):
        return
    app_state["_update_check_inflight"] = True
    app_state["_update_up_to_date"] = False
    app_state["_update_status"] = "Checking for updates..."
    base_dir = _update_base_dir()
    config = dict(db.config) if db is not None else {}

    def _worker():
        try:
            result = auto_updater.check_for_update(base_dir, config=config)
            _set_update_result(result, automatic=boot)
        except Exception as exc:
            app_state["_update_status"] = f"Update check failed: {exc}"
            log.warning("[UPDATE] %s", app_state["_update_status"])
        finally:
            app_state["_update_check_inflight"] = False

    threading.Thread(target=_worker, daemon=True, name="ManualUpdateCheck").start()



def _background_subsystem_worker():
    global db, game_deck, visualizer_deck, _guide_preload_thread_obj

    # WARNING: the fallback numbers below must match BOOT_SUBSYSTEM_YIELD_SECONDS in performance_governor.py; they are used only when that module fails to import.
    _BOOT_YIELD = performance_governor.BOOT_SUBSYSTEM_YIELD_SECONDS if performance_governor is not None else 0.05

    print("Starting database...")
    db = RetroDatabase(detected_aspect_ratio=DETECTED_ASPECT_RATIO)
    print("Database ready.")
    if getattr(db, "config_was_missing", False):
        try:
            import media_library as _ml_fresh
            _fresh_removed = _ml_fresh.shared_schedule_hub().clear_all_schedule_data()
            log.info("[FRESH START] no retro_config.json at boot: the guide's old schedule was emptied (%s) and the old station positions dropped",
                     ", ".join("%s %d" % (k, v) for k, v in _fresh_removed.items()))
        except Exception as _fresh_error:
            log.warning("[FRESH START] could not empty the guide's old schedule: %s", _fresh_error)
    _mark_boot_step("db")
    threading.Thread(target=_wake_media_drives, daemon=True, name="BootDriveWake").start()
    threading.Thread(target=_keep_media_drives_awake_loop, daemon=True, name="DriveKeepAwakeLoop").start()
    _install_duration_hub()

    try:
        _apply_mixer_channels_setting()
    except Exception as _mixer_boot_err:
        log.warning("[SETTINGS] Mono Audio boot-time mixer setup failed: %s", _mixer_boot_err)

    if _setting_on("tv_captions_enabled"):
        _start_caption_model_prewarm("boot")

    db._detected_gpu_tier, db._detected_gpu_adapters = _detect_gpu_tier()
    log.info(
        "[GPU DETECT] tier=%s adapters=%s",
        db._detected_gpu_tier,
        [(a["name"], f"{a['dedicated_vram_mb']:.0f}MB", "software" if a["is_software"] else "hw")
         for a in db._detected_gpu_adapters],
    )
    _apply_boot_gpu_choice("boot")

    _start_performance_governor()


    _ensure_ch03_menu_music_seeded()

    # WARNING: background update checks never download or install; staging and applying a release needs the explicit System-tab button.
    def _on_background_update_result(result):
        if isinstance(result, dict) and result.get("available"):
            _set_update_result(result, automatic=True)

    if UPDATER_AND_SERVER_FEATURES_ENABLED:
        threading.Thread(
            target=auto_updater.background_check_loop,
            args=(
                db.base_dir,
                lambda: dict(db.config),
                _on_background_update_result,
                _app_shutting_down,
            ),
            daemon=True,
            name="BackgroundUpdateChecker",
        ).start()
    else:
        print("[SETTINGS] Updater disabled (UPDATER_AND_SERVER_FEATURES_ENABLED=False) -- background update checker not started.")

    if UPDATER_AND_SERVER_FEATURES_ENABLED:
        _start_update_check(boot=True)

    def _schedule_broadcaster_controller():
        global server_broadcaster
        running = None
        while not _app_shutting_down.is_set():
            want_server = _server_service_should_run()
            service_managed = False
            if want_server:
                service_managed = _reconcile_server_service()

            if want_server and service_managed:
                if running is not None:
                    try:
                        running.stop()
                    except Exception as e:
                        _server_breadcrumb(
                            log, logging.WARNING, "server-fallback-stop",
                            "In-process broadcaster stop failed: %s",
                            e,
                        )
                    running = server_broadcaster = None
            elif want_server and running is None:
                try:
                    device_id = server_discovery.get_or_create_device_id(db.base_dir)
                    slots = lambda: {slot_id: db.get_server_slot_path(slot_id)
                                     for slot_id, _name in db.list_server_slots()}
                    running = server_sync.ScheduleBroadcaster(
                        slots, remote_id=device_id,
                        playback_provider=lambda: {"screen_mode": db.config.get("screen_mode", "normal")})
                    running.start()
                    server_broadcaster = running
                    print("[SERVER SYNC] In-process fallback broadcaster started.")
                except Exception as e:
                    _server_breadcrumb(
                        log, logging.ERROR, "server-fallback-start",
                        "In-process broadcaster start failed: %s",
                        e,
                    )
                    running = None
            elif not want_server:
                if running is not None:
                    try: running.stop()
                    except Exception as e:
                        _server_breadcrumb(
                            log, logging.WARNING, "server-fallback-stop-runtime",
                            "In-process broadcaster stop failed: %s",
                            e,
                        )
                    running = server_broadcaster = None
                if db is not None:
                    try:
                        server_service.set_autostart(db.base_dir, False)
                    except Exception as _swallowed_error:
                        _log_swallowed("_background_subsystem_worker._schedule_broadcaster_controller: server_service.set_autostart(db.base_dir, False)", _swallowed_error)
            _app_shutting_down.wait(1.0)
        if running is not None:
            try: running.stop()
            except Exception as _swallowed_error:
                _log_swallowed("_background_subsystem_worker._schedule_broadcaster_controller: running.stop()", _swallowed_error)
        server_broadcaster = None

    if UPDATER_AND_SERVER_FEATURES_ENABLED:
        threading.Thread(target=_schedule_broadcaster_controller,
                         daemon=True, name="ScheduleBroadcasterController").start()
    else:
        print("[SETTINGS] Server subsystem disabled (UPDATER_AND_SERVER_FEATURES_ENABLED=False) -- schedule broadcaster controller not started.")

    if UPDATER_AND_SERVER_FEATURES_ENABLED:
        try:
            _server_device_id = server_discovery.get_or_create_device_id(db.base_dir)
            db.server_listener = server_discovery.ServerListener(device_id=_server_device_id)
            db.server_listener.start()
            print("[SERVER DISCOVERY] Listener started.")
        except Exception as e:
            _server_breadcrumb(
                log, logging.ERROR, "server-listener-start",
                "Discovery listener start failed: %s", e,
                interval=0.0,
            )
            db.server_listener = None
    else:
        db.server_listener = None
        print("[SETTINGS] Server subsystem disabled (UPDATER_AND_SERVER_FEATURES_ENABLED=False) -- discovery listener not started.")

    _ensure_splash_folder_structure()

    _purge_removed_scan_data()
    threading.Thread(target=_boot_prewarm_watchdog, daemon=True, name="BootPrewarmWatchdog").start()
    threading.Thread(target=_prewarm_boot_channel_paths, daemon=True).start()
    threading.Thread(target=_preload_all_bezel_styles, daemon=True).start()
    if db is None or db.config.get("game_channel_enabled", True):
        threading.Thread(target=_preload_games_tab_logos, daemon=True, name="GamesTabLogoPreload").start()
    time.sleep(_BOOT_YIELD)

    if app_state.get("shell_takeover_active", False) and not db.config.get("start_on_boot", False):
        log.warning("[STARTUP] shell_takeover_active is True but start_on_boot config says False -- "
                    "config drifted out of sync with the registry. Correcting config to match reality.")
        db.config["start_on_boot"] = True
        db.save_settings()

    if db.config.get("start_on_boot", False):
        _set_start_on_boot(True)

    try:
        _remember_old_core_and_bios_copies()
    except Exception as e:
        log.warning(f"[GAMES] Could not remember the old core and BIOS copies: {e}")

    print("Creating game frontend deck...")
    try:
        from game_deck import ExternalGameDeck
        game_deck = ExternalGameDeck()
        print("Game frontend deck ready.")
        if db is not None:
            if game_deck.refresh_from_config(db.config):
                db.save_settings()
    except Exception as e:
        log.warning(f"[GAME DECK] Failed to init game frontend: {e}")
        game_deck = None
    _mark_boot_step("game_deck")
    time.sleep(_BOOT_YIELD)

    print("Creating visualizer deck...")
    try:
        visualizer_deck = VisualizerDeck()
        print("Visualizer deck ready.")
    except Exception as e:
        log.warning(f"[VISUALIZER DECK] Failed to init: {e}")
        visualizer_deck = None
    try:
        _run_mixer_seek_selftest()
    except Exception as e:
        log.warning("[SEEK SELFTEST] failed: %s", e)
    _mark_boot_step("visualizer_deck")
    time.sleep(_BOOT_YIELD)

    print("Warming up VLC engine...")
    try:
        initialize_vlc_on_demand()
        print("VLC engine warm-up complete.")
    except Exception as e:
        log.warning(f"[VLC ENGINE] Warm-up failed: {e}")
    _mark_boot_step("vlc_engine")
    app_state["_joystick_init_done"] = True

    while not _MODULE_DEFINED.wait(0.1):
        if _app_shutting_down.is_set():
            return

    threading.Thread(target=_scan_snapshot_worker, daemon=True, name="ScanSnapshot").start()
    threading.Thread(target=_carry_config_file_data_into_hub, daemon=True, name="HubCarryOver").start()
    threading.Thread(target=_channel_ready_worker, daemon=True, name="ChannelReady").start()

    threading.Thread(target=_probe_upcoming_media, daemon=True).start()

    threading.Thread(target=_music_precache_worker, daemon=True, name="MusicPrecache").start()

    threading.Thread(target=_caption_precache_worker, daemon=True, name="CaptionPrecache").start()

    # WARNING: duration has its own scan thread in the same order as the chain in _probe_upcoming_media; adding another precache thread would scan files out of priority order.
    threading.Thread(target=_duration_scan_worker, daemon=True, name="DurationScan").start()

    # WARNING: the picture box has its own scan thread in the same order as the duration scan and the loudness chain; the three scans never wait for one another.
    threading.Thread(target=_picture_box_scan_worker, daemon=True, name="PictureBoxScan").start()

    # WARNING: the hub's future rows are worked out on their own low-priority thread after boot, one channel per pass, only while the governor allows background work; boot never waits for them.
    threading.Thread(target=_hub_future_worker, daemon=True, name="HubFutureRows").start()

    # WARNING: the scheduler is the hub's writer: this thread gives it its bookkeeping beat so readers never have to
    threading.Thread(target=_hub_writer_worker, daemon=True, name="HubWriter").start()

    threading.Thread(target=_drive_health_monitor_loop, daemon=True, name="DriveHealthMonitor").start()

    threading.Thread(target=_changed_file_sweep_loop, daemon=True, name="ChangedFileSweep").start()

    _start_autoplay_dismisser()

    _guide_preload_thread_obj = threading.Thread(target=_guide_preload_worker, daemon=True, name="GuidePreloader")
    _guide_preload_thread_obj.start()
    threading.Thread(target=_background_watchdog_scheduler, daemon=True, name="BackgroundWatchdogScheduler").start()

    print("[TELEMETRY - PART 2A] All background systems loaded.")

# WARNING: set just before the main loop, once every function below this point exists; the background worker waits for it before starting the threads defined further down (owner crash 2026-11-01 23:38: NameError _background_watchdog_scheduler on a fast boot).
_MODULE_DEFINED = threading.Event()

print("Launching background thread...")
threading.Thread(target=_background_subsystem_worker, daemon=True).start()


# ============================================================================
# SECTION: Scheduling helpers: gains, anchors & marathon
# ============================================================================


def _channel_is_server_streamed(ch_key):
    """True for a channel whose schedule and per-file gain are owned by a connected Server."""
    try:
        return bool(db is not None
                    and db.channels_db.get(str(ch_key).zfill(2), {}).get("server_locked", False))
    except Exception as _swallowed_error:
        _log_swallowed("_channel_is_server_streamed: return bool(db is not None and db.channels_db.get(str(ch_key", _swallowed_error)
        return False


def _safe_gain(entry, default=1.0):
    g = entry.get("gain", default) if isinstance(entry, dict) else default
    return g if g and g > 0 else default

def _lookup_file_gain(ch_key, file_path, default=1.0):
    """The gain a file plays with: the library's scanned gain (the playing track's own gain when another audio track plays) times the owner's manual dB; a channel streamed from a connected Server uses the gain the Server sent in its schedule, which is the Server's library gain."""
    if not file_path or db is None:
        return default
    manual_gain = 10 ** (_get_manual_audio_gain_db(file_path) / 20.0)
    norm_target = os.path.normpath(file_path)
    if not _library_gain_first(ch_key):
        _server_gain = _server_entry_gain(ch_key, norm_target)
        if _server_gain is not None:
            return _server_gain * manual_gain
    _library_gain = _get_library_gain(norm_target)
    if _library_gain is not None:
        _track_gain = _playing_track_gain(norm_target)
        if _track_gain is not None and not _owner_set_gain(norm_target):
            return _track_gain * 10 ** (_learned_offset_applied(norm_target) / 20.0) * manual_gain
        return _library_gain * manual_gain
    _guessed_gain = _season_guess_gain(norm_target)
    if _guessed_gain is not None:
        return _guessed_gain * manual_gain
    return default * manual_gain


def _server_entry_gain(ch_key, norm_target):
    """The gain the connected Server sent for a file in a streamed channel's schedule, or None when it sent none."""
    ch_info = db.channels_db.get(str(ch_key).zfill(2), {})
    for pool in list(ch_info.get("schedules", {}).values()) + list(ch_info.get("holiday_schedules", {}).values()):
        if not isinstance(pool, list):
            continue
        for entry in pool:
            if not isinstance(entry, dict):
                continue
            if os.path.normpath(entry.get("path", entry.get("file", ""))) == norm_target:
                return _safe_gain(entry, None) if "gain" in entry else None
            if entry.get("is_pair"):
                for _key, _gkey in (("pair_ep1_path", "pair_ep1_gain"), ("pair_ep2_path", "pair_ep2_gain")):
                    _p = entry.get(_key, "")
                    if _p and os.path.normpath(_p) == norm_target:
                        g = entry.get(_gkey) or entry.get("gain")
                        return float(g) if g and float(g) > 0 else None
    return None


def _owner_set_gain(norm_path):
    """True when the file's saved gain is the owner's own; the owner's gain wins on every audio track."""
    hub = _get_gain_hub()
    if hub is None:
        return False
    try:
        return hub.read(norm_path)["scan_version"] == media.OWNER_GAIN_SCAN_VERSION
    except Exception as _swallowed_error:
        _log_swallowed("_owner_set_gain: reading the file's gain row", _swallowed_error)
        return False


def _reset_marathon_anchor(ch_info):
    _n = broadcast_clock.now().replace(tzinfo=None)
    _cs = _n.hour * 3600 + _n.minute * 60 + _n.second
    ch_info["marathon_anchor_epoch"] = _n.toordinal() * 86400 + (_cs // 1800) * 1800


def _block_overrun_anchor(ch_info, channel_key, block_key, now, current_seconds, blk_clock_now, real_start_seconds, is_holiday_date):
    """The second on the block clock at which an entry still airing across a block's start ends, for a block seen for the first time; None when the block has its start saved, the channel has not aired before, or nothing runs across the start."""
    playback_log = ch_info.setdefault("playback_log", {})
    if block_key in (playback_log.get("block_anchors") or {}):
        return None
    _last_built = playback_log.get("sched_block_key")
    if not _last_built or _last_built == block_key:
        return None
    _items = ch_info.get("schedules", {}).get("Commercials", [])
    _commercials = (build_commercial_tracks(_items, _cached_path_exists)
                    if ch_info.get("commercials_enabled", False) and _items else [])
    try:
        _run_end_abs = media.catch_up_overrun_end(
            channel_key, ch_info, playback_log.get("show_pos") or {}, _last_built, block_key, _cached_path_exists, _commercials,
            lambda _offset: _start_order_seed(ch_info, _offset), is_holiday_date)
    except Exception as _overrun_err:
        log.warning("[SCHEDULER] ch%s block %s could not tell whether an entry runs across its start, so it starts at its clock start: %s",
                    channel_key, block_key, _overrun_err)
        return None
    if _run_end_abs is None:
        return None
    _ordinal = now.toordinal()
    _shift = blk_clock_now - current_seconds
    _boundary = real_start_seconds - _shift
    if not any(_start < _boundary and _end > _boundary - 0.5
               for _e, _start, _end, _n in media.aired_ledger_entries(playback_log, _ordinal)):
        _note_missed_blocks(
            ch_info, channel_key, playback_log.setdefault("show_pos", {}), _last_built, block_key, now, _commercials, is_holiday_date)
    return (_run_end_abs - _ordinal * 86400) + _shift


def _get_or_set_block_anchor(ch_info, block_key, blk_clock_now, real_start_seconds=None, overrun_end_seconds=None, exact_start=False):
    """The second of the day a block's schedule is measured from, saved on first sight: the end of the entry still airing across the block's start, else its real clock start for a channel that has aired before, the half hour the channel first went on air for a new channel."""
    # WARNING: the saved anchor must never change once set; the scheduler and the guide both measure the block from it.
    playback_log = ch_info.setdefault("playback_log", {})
    anchors = playback_log.setdefault("block_anchors", {})
    anchor = anchors.get(block_key)
    if anchor is None:
        _last_built = playback_log.get("sched_block_key")
        if real_start_seconds is not None and _last_built and _last_built != block_key:
            anchor = int(real_start_seconds)
            if overrun_end_seconds is not None and overrun_end_seconds > anchor:
                anchor = int(overrun_end_seconds)
        elif exact_start:
            anchor = int(blk_clock_now)
        else:
            anchor = (int(blk_clock_now) // 1800) * 1800
        anchors[block_key] = anchor
        if len(anchors) > 12:
            for _old_key in sorted(anchors.keys())[:-12]:
                anchors.pop(_old_key, None)
        try:
            db.save_settings()
        except Exception as e:
            log.warning("_get_or_set_block_anchor: failed to persist anchor for %s: %s", block_key, e)
    return anchor


def _missed_block_day_seeds(prev_block_key, block_name, channel_num, block_offset, now_dt, max_missed=21900):
    if not prev_block_key:
        return []
    parts = prev_block_key.split("_", 2)
    if len(parts) < 2:
        return []
    try:
        prev_year = int(parts[0])
        prev_yday = int(parts[1])
        prev_date = datetime.date(prev_year, 1, 1) + datetime.timedelta(days=prev_yday - 1)
    except (TypeError, ValueError, OverflowError) as _swallowed_error:
        _log_swallowed("_missed_block_day_seeds: prev_year = int(parts[0])", _swallowed_error)
        return []

    now_date = now_dt.date()
    gap_days = (now_date - prev_date).days
    if gap_days <= 1:
        return []

    n_missed = min(gap_days - 1, max_missed)
    start_offset = gap_days - n_missed
    seeds = []
    for i in range(n_missed):
        d = prev_date + datetime.timedelta(days=start_offset + i)
        seeds.append(block_day_seed(d, channel_num, block_offset))
    return seeds


# ============================================================================
# SECTION: Schedule rebuild in-flight guard
# ============================================================================
# WARNING: the running count must always be released in the finally of the guard, or a picked scheduling mode would wait for ever.
# WARNING: a mode switch may only write the mode while no scheduler call of that channel is running, or one lineup can be built from two modes.
_sched_rebuild_gate = threading.Lock()
_sched_rebuild_running = {}
_sched_mode_generation = {}


def _sched_rebuild_guard(scheduler_call):
    """Counts each running scheduler call of a channel so a mode switch can tell whether a rebuild is in progress."""
    @functools.wraps(scheduler_call)
    def _guarded(channel_id, *args, **kwargs):
        _key = str(channel_id).zfill(2)
        with _sched_rebuild_gate:
            _sched_rebuild_running[_key] = _sched_rebuild_running.get(_key, 0) + 1
        try:
            return scheduler_call(channel_id, *args, **kwargs)
        finally:
            with _sched_rebuild_gate:
                _left = _sched_rebuild_running.get(_key, 1) - 1
                if _left > 0:
                    _sched_rebuild_running[_key] = _left
                else:
                    _sched_rebuild_running.pop(_key, None)
    return _guarded


def _sched_rebuild_is_running(target_ch_str):
    """True while any scheduler call of the channel is running."""
    with _sched_rebuild_gate:
        return _sched_rebuild_running.get(target_ch_str, 0) > 0


def _apply_scheduling_mode_change(ch_info, new_mode, target_ch_str):
    """Switches a channel to a committed scheduling mode and records the stopping point; returns False, changing nothing, while a rebuild of the channel is running."""
    if _sched_rebuild_is_running(target_ch_str):
        return False
    old_mode = ch_info.get("scheduling_mode", "random_slots")

    _live_now = None
    _is_live_ch = (str(app_state.get("current_channel", "")).zfill(2) == target_ch_str
                   and app_state.get("is_playing_video", False))
    if _is_live_ch:
        _existing_anc = ch_info.get("playback_anchor", {})
        if _existing_anc and _existing_anc.get("file"):
            _live_now = dict(_existing_anc)
        else:
            try:
                _ls = calculate_slotted_playback_state(target_ch_str)
                if _ls.get("mode") in ("Video", "Commercial") and _ls.get("file"):
                    _live_now = {
                        "file":        _ls["file"],
                        "seek_offset": _ls.get("seek", 0),
                        "duration":    _ls.get("duration", 1800),
                        "mode":        _ls.get("mode", "Video"),
                        "block":       _ls.get("block", "Morning"),
                        "interior_cut": bool(_ls.get("interior_cut", False)),
                    }
            except Exception as _swallowed_error:
                _log_swallowed("_apply_scheduling_mode_change: _ls = calculate_slotted_playback_state(target_ch_str)", _swallowed_error)
                _live_now = None

    if _live_now and _live_now.get("file"):
        _live_now["wall_start"] = broadcast_clock.seconds_since_midnight()
        _live_now["anchor_written_at"] = broadcast_clock.now().timestamp()
        try:
            if vlc_engine is not None and getattr(vlc_engine, "player", None) is not None:
                _pos_ms = vlc_engine.player.get_time()
                if _pos_ms is not None and _pos_ms >= 0:
                    _live_now["seek_offset"] = _pos_ms / 1000.0
        except Exception as e:
            log.warning("_apply_scheduling_mode_change: failed to read current VLC position for seek_offset: %s", e)

    with _sched_rebuild_gate:
        if _sched_rebuild_running.get(target_ch_str, 0) > 0:
            return False
        ch_info["scheduling_mode"] = new_mode
        _generation = _sched_mode_generation.get(target_ch_str, 0) + 1
        _sched_mode_generation[target_ch_str] = _generation
    if old_mode != new_mode:
        _stop_log = ch_info.setdefault("playback_log", {})
        _stop_points = _stop_log.setdefault("mode_stop_points", [])
        _stop_points.append({
            "from_mode": old_mode,
            "to_mode": new_mode,
            "generation": _generation,
            "file": str((_live_now or {}).get("file", "")),
            "clock": broadcast_clock.now().isoformat(),
            "show_pos": copy.deepcopy(_stop_log.get("show_pos", {})),
        })
        del _stop_points[:-max(1, int(_SCHEDULE_MODE_STOP_POINTS_KEPT))]
        log.info("[MODE SWITCH] ch%s committed %s -> %s (mode generation %d); stopping point kept: file=%s",
                 target_ch_str, old_mode, new_mode, _generation, os.path.basename(str((_live_now or {}).get("file", ""))) or "none")
    crossing_marathon_boundary = (old_mode == "marathon") != (new_mode == "marathon")
    entering_marathon = (old_mode != "marathon") and (new_mode == "marathon")

    if old_mode != new_mode:
        if crossing_marathon_boundary:
            if entering_marathon:
                _reset_marathon_anchor(ch_info)
            ch_info["playback_anchor"] = {}
            ch_info["_sched_debounce_pending_since"] = None
        else:
            if _live_now and _live_now.get("file"):
                ch_info["playback_anchor"] = dict(_live_now)
            ch_info["_sched_debounce_pending_since"] = pygame.time.get_ticks() - _SCHEDULE_MODE_COMMIT_HOLD_MS

    if crossing_marathon_boundary and str(app_state.get("current_channel", "")).zfill(2) == target_ch_str:
        app_state["is_playing_video"] = False
        try:
            change_channel(target_ch_str, is_surfing=False, force_reload=True,
                            internal_advance=True, snap_internal_advance=False)
            if entering_marathon:
                print(f"[MARATHON] Started marathon at episode 1 on ch{target_ch_str}.")
            else:
                print(f"[MARATHON] Left marathon on ch{target_ch_str}; resumed {new_mode} schedule.")
        except Exception:
            log.exception("[MARATHON] Boundary re-tune failed")

    db.save_settings()
    return True


def _request_scheduling_mode(ch_info, new_mode, target_ch_str):
    """Records the Schedule row pick for the menu to show; the channel itself changes later, in _commit_requested_scheduling_modes."""
    shown_before = menu_nav.shown_scheduling_mode(ch_info)
    if new_mode == ch_info.get("scheduling_mode", "random_slots"):
        ch_info.pop("_sched_mode_request", None)
    else:
        ch_info["_sched_mode_request"] = {"to": new_mode, "since": pygame.time.get_ticks()}
    if (shown_before == "marathon") != (new_mode == "marathon"):
        if str(app_state.get("selected_channel_row", "")).zfill(2) == target_ch_str \
                and app_state.get("menu_layer") == "CHANNEL_SUB_MENU":
            app_state["sub_menu_row_index"] = 1
            app_state["sub_menu_col_index"] = 0


def _commit_requested_scheduling_modes():
    """Switches each channel to its picked scheduling mode once the pick has been left alone for the hold time; a pick that returned to the real mode commits nothing."""
    channels = getattr(db, "channels_db", None) if "db" in globals() and db is not None else None
    if not isinstance(channels, dict):
        return
    now_ticks = pygame.time.get_ticks()
    for target_ch_str, ch_info in list(channels.items()):
        pending = ch_info.get("_sched_mode_request") if isinstance(ch_info, dict) else None
        if not isinstance(pending, dict):
            continue
        if now_ticks - pending.get("since", now_ticks) < _SCHEDULE_MODE_COMMIT_HOLD_MS:
            continue
        ch_info.pop("_sched_mode_request", None)
        if pending.get("to") and pending["to"] != ch_info.get("scheduling_mode", "random_slots"):
            try:
                _applied = _apply_scheduling_mode_change(ch_info, pending["to"], str(target_ch_str).zfill(2))
                if _applied is not False:
                    _replan_hub_future_soon(str(target_ch_str).zfill(2))
            except Exception:
                log.exception("[SCHEDULE MODE] ch%s: switching to %s failed", target_ch_str, pending.get("to"))
                _applied = True
            if _applied is False:
                ch_info["_sched_mode_request"] = pending
                if not pending.get("deferred_logged"):
                    pending["deferred_logged"] = True
                    log.info("[MODE SWITCH] ch%s: the switch to %s waits, a schedule rebuild of this channel is running; trying again next frame",
                             target_ch_str, pending.get("to"))


# ============================================================================
# SECTION: Duration snapshots & cached lineup reconciliation
# ============================================================================


def _snapshot_track_durations(video_tracks):
    """Freezes each track's already-probed real duration as the baseline for later stale checks; fallback guesses are not frozen."""
    out = {}

    def _best_dur(path):
        try:
            _c = _read_file_probe_facts(os.path.normpath(str(path))).get("duration")
            if _c and _c > 0:
                return int(_c)
        except Exception as _swallowed_error:
            _log_swallowed("_snapshot_track_durations._best_dur: _c = _read_file_probe_facts(os.path.normpath(str(path))).get('duration')", _swallowed_error)
        return None

    for t in video_tracks:
        if t.get("is_pair"):
            p1, p2 = t.get("pair_ep1_path", t.get("path")), t.get("pair_ep2_path", "")
            if p1:
                _d1 = _best_dur(p1)
                if _d1 is not None:
                    out[p1] = _d1
            if p2:
                _d2 = _best_dur(p2)
                if _d2 is not None:
                    out[p2] = _d2
        elif t.get("is_bundle"):
            for p in lineup_paths([t]):
                _d = _best_dur(p)
                if _d is not None:
                    out[p] = _d
        else:
            p = t.get("path", "")
            if p:
                _d = _best_dur(p)
                if _d is not None:
                    out[p] = _d
    return out


def _timeline_whole_episode_durations(timeline):
    """Maps the index of each non-pair show entry to the whole length of the episode it belongs to, adding up its commercial-split pieces."""
    whole = {}
    open_run = {}
    for idx, entry in enumerate(timeline or []):
        if entry.get("is_commercial") or entry.get("is_pair") or entry.get("is_bundle"):
            continue
        p = entry.get("path", "")
        if not p:
            continue
        end = (entry.get("seek_offset", 0) or 0) + (entry.get("duration", 0) or 0)
        run = open_run.get(p)
        if run is None or not (entry.get("seek_offset", 0) or 0):
            run = {"indexes": [], "end": 0}
            open_run[p] = run
        run["indexes"].append(idx)
        run["end"] = max(run["end"], end)
        for i in run["indexes"]:
            whole[i] = run["end"]
    return whole


def _pending_paths_signature(paths):
    """A short fingerprint of a block's pending file paths, the same for the same set of paths in any order."""
    import hashlib
    joined = "\n".join(sorted(str(p) for p in paths if p))
    return hashlib.sha1(joined.encode("utf-8", "surrogatepass")).hexdigest()


def _stored_pending_signature(playback_log):
    """The block's saved pending fingerprint; a full path list saved by an older version is turned into its fingerprint and stored that way, with the same meaning."""
    stored = playback_log.get("sched_pending_signature")
    if isinstance(stored, str):
        return stored
    signature = _pending_paths_signature(stored or ())
    if stored is not None:
        playback_log["sched_pending_signature"] = signature
    return signature


def _freeze_aired_prefix_durations(timeline, target_show, cached_durations,
                                    frozen_paths):
    """Freezes the whole duration of every episode at or before the one airing so it never changes."""
    changed = False
    _whole = _timeline_whole_episode_durations(timeline)
    for _idx, entry in enumerate(timeline or []):
        if entry.get("is_pair"):
            for p, d in ((entry.get("pair_ep1_path", ""), entry.get("pair_ep1_duration", 0)),
                         (entry.get("pair_ep2_path", ""), entry.get("pair_ep2_duration", 0))):
                if p and p not in frozen_paths and d and d > 0:
                    cached_durations[p] = d
                    frozen_paths.add(p)
                    changed = True
        elif entry.get("is_bundle"):
            for p, d in zip(entry.get("bundle_item_paths", []), entry.get("bundle_item_durations", [])):
                if p and p not in frozen_paths and d and d > 0:
                    cached_durations[p] = d
                    frozen_paths.add(p)
                    changed = True
        else:
            p = entry.get("path", "")
            d = _whole.get(_idx, entry.get("duration", 0))
            if p and p not in frozen_paths and d and d > 0:
                cached_durations[p] = d
                frozen_paths.add(p)
                changed = True
        if entry is target_show or (
                entry.get("start_time") == target_show.get("start_time")
                and entry.get("path") == target_show.get("path")):
            break
    return cached_durations, frozen_paths, changed


def _cached_lineup_durations_stale(cached_durations,
                                   movie_threshold_seconds=None,
                                   material_diff_seconds=60,
                                   frozen_aired_paths=None):
    if not cached_durations:
        return False
    if movie_threshold_seconds is None:
        try:
            from media import MOVIE_LENGTH_THRESHOLD_SECONDS as movie_threshold_seconds
        except Exception as _swallowed_error:
            _log_swallowed("_cached_lineup_durations_stale: from media import MOVIE_LENGTH_THRESHOLD_SECONDS as movie_threshold...", _swallowed_error)
            movie_threshold_seconds = 4800
    _frozen_aired = frozen_aired_paths or ()
    for path, frozen in cached_durations.items():
        if not (frozen and frozen > 0):
            continue
        if path in _frozen_aired:
            # WARNING: a position already committed by _freeze_aired_prefix_durations must never be moved by a later real probe.
            continue
        real, real_kind = media.read_track_duration(path, 0)
        if real_kind != media.DURATION_MEASURED or not (real and real > 0):
            continue
        crosses_movie_line = (
            (frozen >= movie_threshold_seconds) != (real >= movie_threshold_seconds))
        if crosses_movie_line or abs(float(real) - float(frozen)) > material_diff_seconds:
            return True
    return False


# ============================================================================
# SECTION: Repeat guard
# ============================================================================


def _apply_repeat_guard(target_clean_key, playback_log, block_label, timeline,
                         total_block_content, position_in_playlist, now):
    target_show = None
    for item in timeline:
        if item["start_time"] <= position_in_playlist < (item["start_time"] + item["duration"]):
            target_show = item
            break

    _distinct_paths = {os.path.normpath(str(it.get("path", ""))).lower() for it in timeline}
    if len(_distinct_paths) <= 1:
        return target_show, position_in_playlist

    _REPEAT_GUARD_SEC = SCHEDULER_REPEAT_GUARD_SECONDS
    _REPEAT_GUARD_WINDOW = SCHEDULER_REPEAT_GUARD_WINDOW_SECONDS

    _je_slot = playback_log.get("just_ended_slot")
    if _je_slot:
        if (now.timestamp() - _je_slot.get("armed_ts", 0) > _REPEAT_GUARD_WINDOW
                or _je_slot.get("block") != block_label):
            playback_log.pop("just_ended_slot", None)
            _je_slot = None
    _lec_slot = playback_log.get("last_ended_commercial")
    if _lec_slot:
        if (now.timestamp() - _lec_slot.get("armed_ts", 0) > _REPEAT_GUARD_WINDOW
                or _lec_slot.get("block") != block_label):
            playback_log.pop("last_ended_commercial", None)
            _lec_slot = None

    _floor_slot = playback_log.get("repeat_guard_floor")
    if _floor_slot and (not (_je_slot or _lec_slot) or _floor_slot.get("block") != block_label):
        playback_log.pop("repeat_guard_floor", None)
        _floor_slot = None
    if _floor_slot and total_block_content > 0 and _floor_slot.get("position", 0) >= total_block_content:
        playback_log.pop("repeat_guard_floor", None)
        _floor_slot = None
    _used_floor = False
    if _floor_slot and _floor_slot.get("position", 0) > position_in_playlist:
        position_in_playlist = _floor_slot["position"]
        _used_floor = True
        target_show = None
        for item in timeline:
            if item["start_time"] <= position_in_playlist < (item["start_time"] + item["duration"]):
                target_show = item
                break

    if (_je_slot or _lec_slot) and target_show is not None and timeline and total_block_content > 0:
        _je_file  = _je_slot.get("file") if _je_slot else None
        _lec_file = _lec_slot.get("file") if _lec_slot else None
        _guard_iters = 0
        while target_show is not None and _guard_iters <= len(timeline):
            _cand_seek = (position_in_playlist - target_show["start_time"]) + target_show.get("seek_offset", 0)
            _cand_file = target_show["path"]
            _cand_is_commercial = bool(target_show.get("is_commercial"))
            if target_show.get("is_pair") and not _cand_is_commercial:
                if _cand_seek >= target_show.get("pair_ep1_duration", 0):
                    _cand_file = target_show.get("pair_ep2_path", _cand_file)
            _guard_file = _lec_file if _cand_is_commercial else _je_file
            _floor_forced_self = _used_floor and _guard_iters == 0
            if (not _guard_file
                    or os.path.normpath(str(_cand_file)).lower() != _guard_file
                    or (_cand_seek <= _REPEAT_GUARD_SEC and not _floor_forced_self)):
                break
            _last_skip_file = _guard_file
            position_in_playlist = target_show["start_time"] + target_show["duration"] + 1
            if position_in_playlist >= total_block_content:
                position_in_playlist = 0
            target_show = None
            for _it in timeline:
                if _it["start_time"] <= position_in_playlist < (_it["start_time"] + _it["duration"]):
                    target_show = _it
                    break
            _guard_iters += 1
        if _guard_iters > 0:
            _guard_named = _last_skip_file or _je_file or _lec_file
            print(f"[REPEAT-GUARD] ch{target_clean_key} ({block_label}): skipped {_guard_iters} slot(s) past "
                  f"just-ended '{os.path.basename(_guard_named or '')}' -- raw wall-clock position "
                  f"would have re-landed inside it (position_in_playlist={position_in_playlist}, "
                  f"total_block_content={total_block_content})")

    if _je_slot or _lec_slot:
        _prev_floor_pos = _floor_slot.get("position", -1) if _floor_slot else -1
        if position_in_playlist > _prev_floor_pos:
            playback_log["repeat_guard_floor"] = {
                "position": position_in_playlist,
                "block": block_label,
            }
    else:
        playback_log.pop("repeat_guard_floor", None)

    return target_show, position_in_playlist


# ============================================================================
# SECTION: Probe library singleton
# ============================================================================
# WARNING: never compute a seek from an estimated duration; see _maybe_correct_estimated_target_duration.
_probe_library_singleton = None
_probe_library_lock = threading.Lock()

_cold_primed_channels = set()
_cold_primed_channels_lock = threading.Lock()


def _get_probe_library():
    """Returns the shared persistent probe library, building it on first use."""
    global _probe_library_singleton
    if _probe_library_singleton is None:
        with _probe_library_lock:
            if _probe_library_singleton is None:
                import media_library as _ml
                _probe_library_singleton = _ml.shared_probe_library()
    return _probe_library_singleton


def _hub_note_measured_duration(norm_path, duration):
    """Records a measured length in the schedule hub; returns False when the library could not save it, and a failure is logged and never reaches the caller."""
    hub = media.get_duration_hub()
    if hub is None:
        return False
    try:
        return bool(hub.note_measured(norm_path, duration))
    except Exception as e:
        log.warning("[SCHEDULE HUB] could not record the measured length of %s: %s", os.path.basename(str(norm_path)), e)
        return False


def _hub_forget_path(norm_path):
    """Drops a changed file's lengths and gains from the schedule hub's memory so they are measured again."""
    gain_hub = _get_gain_hub()
    if gain_hub is not None:
        try:
            gain_hub.forget(norm_path)
        except Exception as e:
            log.warning("[SCHEDULE HUB] could not forget the gain of %s: %s", os.path.basename(str(norm_path)), e)
    hub = media.get_duration_hub()
    if hub is None:
        return
    try:
        hub.forget(norm_path)
    except Exception as e:
        log.warning("[SCHEDULE HUB] could not forget the lengths of %s: %s", os.path.basename(str(norm_path)), e)


# WARNING: the fallback numbers below must match ONDEMAND_DURATION_PROBE_COOLDOWN_SECONDS in performance_governor.py; they are used only when that module fails to import.
_ONDEMAND_DURATION_PROBE_COOLDOWN_S = performance_governor.ONDEMAND_DURATION_PROBE_COOLDOWN_SECONDS if performance_governor is not None else 30.0
_ondemand_duration_probe_next = {}
_duration_precache_inflight = media._InFlightGuard()


def _probe_and_persist_duration(path):
    """Probe one file and save its duration in the library."""
    if not _duration_precache_inflight.try_claim(path):
        return None
    try:
        probe_lib = _get_probe_library()
        entry = probe_lib.get_or_probe_sync(path)
        real_dur = entry.get("duration") if entry else None
    except Exception as e:
        _log_probe_failure("duration_probe_import", e, "[DURATION PROBE] on-demand probe failed for %s: %s",
                           os.path.basename(str(path)), e)
        return None
    finally:
        _duration_precache_inflight.release(path)
    if not real_dur or real_dur <= 0:
        return None
    try:
        _save_file_probe_facts(os.path.normpath(str(path)), duration=real_dur)
    except Exception as e:
        log.warning("[DURATION PROBE] failed to persist duration for %s: %s",
                    os.path.basename(str(path)), e)
    return real_dur


def _maybe_correct_estimated_target_duration(target_clean_key, current_block, timeline,
                                              target_show, position_in_playlist, now):
    """Starts a background probe for a track whose duration is still an estimate."""
    # WARNING: do not make this probe synchronous; it runs on the main thread during channel changes and would freeze video, audio and input.
    if not target_show or not target_show.get("duration_estimated"):
        return target_show, position_in_playlist
    if target_show.get("is_pair"):
        return target_show, position_in_playlist
    path = target_show.get("path")
    if not path:
        return target_show, position_in_playlist
    _now_mono = time.monotonic()
    if _ondemand_duration_probe_next.get(path, 0.0) > _now_mono:
        return target_show, position_in_playlist
    _ondemand_duration_probe_next[path] = _now_mono + _ONDEMAND_DURATION_PROBE_COOLDOWN_S
    try:
        threading.Thread(
            target=_probe_and_persist_duration, args=(path,),
            daemon=True, name="OnDemandDurationProbe",
        ).start()
    except Exception as e:
        log.warning(
            "[SCHEDULER] ch%s: could not start on-demand duration probe for "
            "%s, keeping the estimated duration: %s",
            target_clean_key, os.path.basename(str(path)), e,
        )
    return target_show, position_in_playlist


# ============================================================================
# SECTION: Cold-start duration priming
# ============================================================================


def _prime_block_durations_on_cold_start(target_clean_key, current_block, video_tracks,
                                          seconds_into_block):
    """Synchronously probes, in parallel, every still-estimated track from the start of the block to one track past the current position, once per channel per session."""
    with _cold_primed_channels_lock:
        if target_clean_key in _cold_primed_channels:
            return
        _cold_primed_channels.add(target_clean_key)

    try:
        probe_lib = _get_probe_library()
    except Exception as e:
        _log_probe_failure("cold_prime_import", e, "[COLD PRIME] ch%s: could not get probe library, skipping: %s",
                           target_clean_key, e)
        return

    to_probe = []
    running = 0.0
    _threshold_reached = False
    for t in (video_tracks or []):
        if t.get("is_pair"):
            running += t.get("duration", 0) or 0
        else:
            if t.get("_duration_estimated") and t.get("path"):
                to_probe.append(t)
            running += t.get("duration", 0) or 0
        if running >= seconds_into_block:
            if _threshold_reached:
                break
            _threshold_reached = True

    to_probe = [t for t in to_probe if _is_drive_responsive(t.get("path"))]
    if not to_probe:
        return

    log.info(
        "[COLD PRIME] ch%s block=%s: first resolve this session -- "
        "synchronously probing %d still-estimated track(s) up through the "
        "current position before trusting the schedule.",
        target_clean_key, current_block, len(to_probe),
    )

    def _probe_one(track):
        path = track.get("path")
        try:
            with _governor_priority_scope():
                entry = probe_lib.get_or_probe_sync(path)
            real_dur = entry.get("duration") if entry else None
        except Exception as e:
            log.warning("[COLD PRIME] ch%s: probe failed for %s: %s",
                        target_clean_key, os.path.basename(str(path)), e)
            return
        if not real_dur or real_dur <= 0:
            return
        track["duration"] = real_dur
        track["_duration_estimated"] = False
        try:
            _save_file_probe_facts(os.path.normpath(str(path)), duration=real_dur)
        except Exception as e:
            log.warning("[COLD PRIME] ch%s: failed to persist probed duration for %s: %s",
                        target_clean_key, os.path.basename(str(path)), e)

    try:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=min(8, len(to_probe))) as ex:
            list(ex.map(_probe_one, to_probe))
    except Exception as e:
        log.warning("[COLD PRIME] ch%s: parallel priming failed, tracks left as-is: %s",
                    target_clean_key, e)
        return

    log.info(
        "[COLD PRIME] ch%s block=%s: done -- %d track(s) now have real durations.",
        target_clean_key, current_block, len(to_probe),
    )


# ============================================================================
# SECTION: Scan failure classification (stalled drive vs dead file)
# ============================================================================
# WARNING: the fallback numbers below must match SCAN_RETRY_LIMIT, SCAN_DEAD_BURST_LIMIT, SCAN_DEAD_BURST_WINDOW_S in performance_governor.py; they are used only when that module fails to import.
SCAN_RETRY_LIMIT = performance_governor.SCAN_RETRY_LIMIT if performance_governor is not None else 3
SCAN_DEAD_BURST_LIMIT = performance_governor.SCAN_DEAD_BURST_LIMIT if performance_governor is not None else 5
SCAN_DEAD_BURST_WINDOW_S = performance_governor.SCAN_DEAD_BURST_WINDOW_S if performance_governor is not None else 300.0

SCAN_FAIL_DRIVE = "drive"
SCAN_FAIL_DEAD = "dead"
SCAN_FAIL_RETRY = "retry"

_scan_drive_hold = {}
_scan_hold_lock = threading.Lock()
_scan_retry_counts = {}
_scan_dead_times = []


def _scan_bounded(fn):
    """Runs fn on a helper thread for at most the static-fallback file probe's time limit; returns its result, "error" if it raised, or "timeout"."""
    box = {}

    def _go():
        try:
            box["r"] = fn()
        except Exception as _swallowed_error:
            _log_swallowed("_scan_bounded._go: box['r'] = fn()", _swallowed_error)
            box["r"] = "error"

    t = threading.Thread(target=_go, daemon=True, name="scan-read-probe")
    t.start()
    t.join(media._FILE_PROBE_TIMEOUT_MS / 1000.0)
    return box.get("r", "timeout")


def _scan_read_first_bytes(path):
    with open(path, "rb") as f:
        f.read(media._FILE_PROBE_READ_BYTES)
    return "ok"


def _scan_read_bytes(path):
    """One real open+read of the file's first bytes, the same read the static fallback's recovery probe does: "ok", "error" or "timeout"."""
    return _scan_bounded(lambda: _scan_read_first_bytes(path))


def _scan_sibling_read(norm_p):
    """Reads the first bytes of another file of the same type in the same folder: "ok", "error", "timeout", or None when the folder has no other such file."""
    def _go():
        _dir, _ext = os.path.dirname(norm_p), os.path.splitext(norm_p)[1].lower()
        for _name in os.listdir(_dir):
            _cand = os.path.normpath(os.path.join(_dir, _name))
            if _cand != norm_p and os.path.splitext(_name)[1].lower() == _ext:
                try:
                    return _scan_read_first_bytes(_cand)
                except Exception as _swallowed_error:
                    _log_swallowed("scanning a file: reading its first bytes", _swallowed_error)
                    return "error"
        return None
    return _scan_bounded(_go)


def _scan_diagnose(norm_p, timed_out=False, corrupt=False):
    """What a failed scan means: SCAN_FAIL_DRIVE when the drive is stalled, SCAN_FAIL_DEAD when the drive is healthy and the file itself is broken, else SCAN_FAIL_RETRY."""
    # WARNING: a missing file is never "dead" here; missing media has its own handling and a dropped share must not empty a lineup.
    if _path_status(norm_p) == PATH_MISSING:
        return SCAN_FAIL_RETRY
    if _is_drive_degraded(norm_p):
        return SCAN_FAIL_DRIVE
    read = _scan_read_bytes(norm_p)
    if read == "timeout" or _is_drive_degraded(norm_p):
        return SCAN_FAIL_DRIVE
    if read == "error":
        sibling = _scan_sibling_read(norm_p)
        if sibling == "ok":
            return SCAN_FAIL_DEAD
        if sibling in ("error", "timeout"):
            return SCAN_FAIL_DRIVE
        return SCAN_FAIL_RETRY
    if corrupt:
        return SCAN_FAIL_DEAD
    return SCAN_FAIL_RETRY


def _scan_hold_drive(norm_p, why):
    """Puts scans on this file's drive on hold; _scan_drive_on_hold releases it once the drive reads again."""
    root = media._drive_root_of(norm_p)
    if not root:
        return
    with _scan_hold_lock:
        new = root not in _scan_drive_hold
        if new:
            _scan_drive_hold[root] = {"since": time.monotonic(), "checked": time.monotonic()}
    if new:
        log.warning("[SCAN HOLD] %s: scans on this drive are on hold (%s) -- last file %s; they resume when the drive "
                    "is responsive again and a real read succeeds", root, why, os.path.basename(norm_p))


def _scan_drive_on_hold(norm_p):
    """True while this file's drive is on scan hold; releases the hold once the drive is not flagged unresponsive or degraded and a real read of this file succeeds."""
    # WARNING: the release test is the same two checks _drive_confirmed_recovered makes (drive responsive, real read succeeds) but must not call it: it consumes the one-shot probe state the static fallback is waiting on.
    root = media._drive_root_of(norm_p)
    with _scan_hold_lock:
        hold = _scan_drive_hold.get(root)
    if hold is None:
        return False
    now = time.monotonic()
    if now - hold["checked"] < media._FILE_PROBE_RECHECK_MS / 1000.0:
        return True
    hold["checked"] = now
    if (root not in _unresponsive_drive_roots() and not _is_drive_degraded(norm_p)
            and _scan_read_bytes(norm_p) == "ok"):
        with _scan_hold_lock:
            _scan_drive_hold.pop(root, None)
        log.info("[SCAN HOLD] %s responsive again after %.0fs -- scans on this drive resume", root, now - hold["since"])
        return False
    return True


def _scan_entry_is_file(entry, norm_p):
    if isinstance(entry, dict):
        paths = [entry.get("path", entry.get("file", ""))]
        if entry.get("is_pair"):
            paths += [entry.get("pair_ep1_path", ""), entry.get("pair_ep2_path", "")]
    else:
        paths = [entry]
    return any(p and os.path.normpath(str(p)) == norm_p for p in paths)


def _scan_remove_dead_file(norm_p, reason):
    """Takes a broken file out of every channel's lineup and marks it unplayable and unschedulable; never touches the file on disk. False when it was not removed."""
    if db is None or not norm_p or is_dvd_disc_source(norm_p):
        return False
    _now = time.monotonic()
    with _scan_hold_lock:
        _scan_dead_times[:] = [t for t in _scan_dead_times if _now - t < SCAN_DEAD_BURST_WINDOW_S]
        if len(_scan_dead_times) >= SCAN_DEAD_BURST_LIMIT:
            _log_warn_throttled("scan_dead_burst", "[SCAN DEAD FILE] NOT removing %s (%s) -- %d files were declared dead in the last %ds, "
                                "which points at the scanner (ffmpeg, antivirus, a share) rather than the files; it stays in place",
                                os.path.basename(norm_p), reason, SCAN_DEAD_BURST_LIMIT, int(SCAN_DEAD_BURST_WINDOW_S))
            return False
        _scan_dead_times.append(_now)
    _hub = media.get_file_facts_hub()
    if _hub is None or not _hub.note(norm_p, confirmed_unplayable=True, unplayable_reason=reason):
        log.warning("[SCAN DEAD FILE] the library could not record %s as unplayable (%s); it is still taken out of every lineup", os.path.basename(norm_p), reason)
    removed_from = []
    for ch_key, ch_info in list(db.channels_db.items()):
        if not isinstance(ch_info, dict):
            continue
        touched = False
        for container in ("schedules", "holiday_schedules"):
            pools = ch_info.get(container)
            if not isinstance(pools, dict):
                continue
            for sub_key, entries in list(pools.items()):
                if not isinstance(entries, list):
                    continue
                kept = [e for e in entries if not _scan_entry_is_file(e, norm_p)]
                if len(kept) != len(entries):
                    pools[sub_key] = kept
                    touched = True
        if touched:
            broken = ch_info.setdefault("broken_files", [])
            if norm_p not in broken:
                broken.append(norm_p)
            removed_from.append(ch_key)
    log.warning("[SCAN DEAD FILE] removed %s from %s -- %s (drive healthy, file broken; the file on disk is untouched)",
                norm_p, ("channel(s) " + ", ".join(removed_from)) if removed_from else "no lineup (was not scheduled)", reason)
    try:
        app_state["guide_refresh_token"] = app_state.get("guide_refresh_token", 0) + 1
        db.save_settings_async()
    except Exception as e:
        log.warning("[SCAN DEAD FILE] could not persist the removal of %s: %s", norm_p, e)
    return True


def _scan_handle_failure(norm_p, stage, reason, timed_out=False, corrupt=False):
    """Diagnoses a failed scan and acts on it: holds the drive, removes the dead file, or counts a retry; returns the verdict."""
    verdict = _scan_diagnose(norm_p, timed_out=timed_out, corrupt=corrupt)
    if verdict == SCAN_FAIL_DRIVE:
        _scan_hold_drive(norm_p, "%s: %s" % (stage, reason))
    elif verdict == SCAN_FAIL_DEAD:
        if _scan_remove_dead_file(norm_p, "%s: %s" % (stage, reason)):
            return verdict
        verdict = SCAN_FAIL_RETRY
    if verdict == SCAN_FAIL_RETRY:
        _scan_retry_counts[(norm_p, stage)] = _scan_retry_counts.get((norm_p, stage), 0) + 1
    return verdict


def _scan_retries_exhausted(norm_p, stage):
    return _scan_retry_counts.get((norm_p, stage), 0) >= SCAN_RETRY_LIMIT


def _scan_store_duration(kind, ch_key, block_key, norm_p, lane="probe_and_duration"):
    """Probes one file's duration and stores it everywhere the schedule and guide read it; returns the duration, or 0 when there is none."""
    try:
        _dur = _probe_duration_gated(norm_p, lane) or 0
    except Exception as e:
        log.warning("[DURATION SCAN] duration probe of %s crashed: %s", os.path.basename(norm_p), e)
        return 0
    if _dur <= 0:
        return 0
    _scan_retry_counts.pop((norm_p, "duration"), None)
    _patch_probed_gain(kind, ch_key, block_key, norm_p, gain=None, duration=_dur)
    try:
        app_state["guide_refresh_token"] = app_state.get("guide_refresh_token", 0) + 1
    except Exception as _swallowed_error:
        _log_swallowed("_scan_store_duration: app_state['guide_refresh_token'] = app_state.get('guide_refresh_token', 0) + 1", _swallowed_error)
    return _dur


def _scan_duration_failed(norm_p):
    """Decides what a missing duration means; the file's chain stops here either way."""
    # WARNING: a miss while another thread holds this file's duration probe is contention, not a bad file; and a header read that does return a duration means the next pass stores it. Neither may count toward removal.
    with _probe_dispatch_lock:
        if (norm_p, "duration") in _probe_dispatch_inflight:
            return False
    result = None
    try:
        import media_library as _ml
        result = _ml.combined_header_probe(norm_p)
    except Exception as e:
        log.warning("[SCAN PIPELINE] duration diagnosis of %s failed: %s", os.path.basename(norm_p), e)
    if result is not None and result.ok and result.duration:
        return False
    timed_out = result is not None and result.error == "timeout"
    corrupt = result is not None and media._stderr_indicates_corrupt(result.stderr)
    why = "header read timed out" if timed_out else ("ffmpeg could not open it" if corrupt else "no duration from ffmpeg or VLC")
    verdict = _scan_handle_failure(norm_p, "duration", why, timed_out=timed_out, corrupt=corrupt)
    log.info("[SCAN PIPELINE] no duration for %s: %s -> %s", os.path.basename(norm_p), why, verdict)
    if verdict == SCAN_FAIL_RETRY and _scan_retries_exhausted(norm_p, "duration"):
        _scan_handle_failure(norm_p, "duration", "no duration after %d tries on a healthy drive" % SCAN_RETRY_LIMIT, corrupt=True)
    return False


# ============================================================================
# SECTION: Picture-box scan hook-up
# ============================================================================
_picture_box_done = set()
_picture_box_guessed = set()


# ============================================================================
# SECTION: Smart background pacing
# ============================================================================
# WARNING: single throttle source for every heavy worker; a menu over a plain picture must not throttle anything by itself.

_HEAVY_VISUAL_EFFECT_CONFIG_KEYS = (
    "fake_43_border_enabled",
    "warp_screen_enabled",
    "fake_43_scanlines_enabled",
    "fake_static_noise_enabled",
    "fake_reception_lines_enabled",
)

# WARNING: the fallback numbers below must match GUIDE_BACKOFF_MULTIPLIER in performance_governor.py; they are used only when that module fails to import.
GUIDE_BACKOFF_MULTIPLIER = performance_governor.GUIDE_BACKOFF_MULTIPLIER if performance_governor is not None else 2.0


def _is_game_actively_playing():
    """True only while a libretro core is loaded and not frozen on the Games channel."""
    _lr_core = getattr(game_deck, "_libretro_core", None) if game_deck is not None else None
    return (_lr_core is not None
            and getattr(_lr_core, "is_loaded", False)
            and not getattr(_lr_core, "is_frozen", False))


def _menu_open_with_heavy_effects():
    """True only while the Settings overlay is open and at least one CPU-side compositing effect is on."""
    if not app_state.get("show_menu", False):
        return False
    if db is None:
        return False
    cfg = getattr(db, "config", None) or {}
    return any(cfg.get(k, False) for k in _HEAVY_VISUAL_EFFECT_CONFIG_KEYS)


def _guide_open():
    return app_state.get("current_channel") == "04"


def _governor_level_if_enforcing():
    """Current smart-throttle level while the governor gates are live, else None."""
    if performance_governor is None:
        return None
    try:
        if performance_governor.enforcing():
            return performance_governor.current_level()
    except Exception as _swallowed_error:
        _log_swallowed("_governor_level_if_enforcing: if performance_governor.enforcing():", _swallowed_error)
    return None


_scan_files_added_generation = [0]
_scan_work_generation = [0]


def _note_scan_work_added():
    """Tells the scan snapshot that files were added; it rebuilds at once and then wakes every scan thread resting between passes, so they see the new files in the right order."""
    _scan_files_added_generation[0] += 1


def _scan_idle_wait(seconds, generation=_scan_work_generation):
    """Rests a scan thread between passes for up to `seconds`, ending early when `generation` moves on; True when the app is shutting down."""
    _seen = generation[0]
    _until = time.monotonic() + max(0.0, float(seconds))
    while True:
        _left = _until - time.monotonic()
        if _left <= 0 or generation[0] != _seen:
            return _app_shutting_down.is_set()
        if _app_shutting_down.wait(min(0.25, _left)):
            return True


def _background_scan_should_pause():
    """True while no new background scan may start: a channel just set up is having its first show scanned, a channel is being tuned, or a game could not catch up while the scans crept and the scans are stopped for as long as the game took to catch up last time."""
    # WARNING: owner order 2026-11-05: scans are throttled before they are stopped and the load level never stops them (a game that falls behind makes them creep, then stop for a measured time; performance_governor.scan_throttle_mode). Python-heavy work keeps the load-level rule in _python_heavy_should_pause.
    if _NEW_CHANNEL_SCAN_ACTIVE.is_set():
        return True
    if performance_governor is not None and performance_governor.tune_in_progress():
        return True
    if performance_governor is None:
        return _is_game_actively_playing()
    return performance_governor.scan_throttle_mode() == "stopped"


def _background_activity(lane):
    """Context manager marking Python-heavy background work as running for the governor (see performance_governor.background_activity)."""
    if performance_governor is None:
        import contextlib as _ctx
        return _ctx.nullcontext()
    return performance_governor.background_activity(lane)


def _python_heavy_should_pause():
    """True while Python-heavy background work (future guide rows, the changed-file sweep, library look-ups for the scan progress) may not start: whenever the background scans may not, and for as long as a game is being played, because that work takes turns with the game's own frames on the one Python thread at a time."""
    if _background_scan_should_pause() or _is_game_actively_playing():
        return True
    level = _governor_level_if_enforcing()
    if level is not None:
        return not performance_governor.level_allows(level, "background")
    return False


def _background_scan_pace_seconds(base_seconds):
    """Pause after each unit of background work, stretched by the playback state and the governor level."""
    pace = base_seconds
    if (app_state.get("is_playing_video", False)
            or _is_game_actively_playing()
            or _menu_open_with_heavy_effects()):
        pace *= SCAN_BACKOFF_WHILE_PLAYING_MULTIPLIER
    elif _guide_open():
        pace *= GUIDE_BACKOFF_MULTIPLIER
    level = _governor_level_if_enforcing()
    if level is not None:
        factor = max(performance_governor.PACE_FACTOR_FLOOR, performance_governor.LEVEL_FACTOR[level])
        pace /= factor
    return pace


def _scan_class_name(scan_class):
    """The governor's pace class for a scan-pipeline class: "now" for files airing now, "deep" for the files behind the next 3 shows, "next" for the rest."""
    if scan_class == SCAN_CLASS_NOW or scan_class == "now":
        return "now"
    if scan_class == SCAN_CLASS_DEEP or scan_class == "deep":
        return "deep"
    return "next"


def _scan_class_pace_seconds(scan_class, base_seconds):
    """Seconds a scan rests after one file of the duration, picture-box, loudness or music scan: none for a file airing now, otherwise the governor's pause for the current load level, at most SCAN_GAP_MAX_SECONDS (1 s)."""
    # WARNING: owner order 2026-11-05: no huge gaps between files; the pause is a small step that follows how strained this PC is, and a quiet PC has none. The old pause was 4 to 16 s after each next-3 file and 24 to 96 s after each file behind them on a weak PC while a show played.
    if performance_governor is None:
        return 0.0
    try:
        return float(performance_governor.scan_gap_seconds(_scan_class_name(scan_class)))
    except Exception as e:
        _log_warn_throttled("scan_class_pace", "[SCAN PACE] governor gap failed, no pause: %s" % e)
        return 0.0


def _scan_rank(scan_class, tier=0):
    """How urgent a file is for the scan turns: (scan class, tier), smaller is sooner; a music scan's "now", "next" and "deep" map to the same classes as the TV scans."""
    if isinstance(scan_class, str):
        scan_class = {"now": SCAN_CLASS_NOW, "next": SCAN_CLASS_NEXT, "deep": SCAN_CLASS_DEEP}.get(scan_class, SCAN_CLASS_DEEP)
    return (int(scan_class), int(tier or 0))


def _scan_report_head(kind, scan_class=None, tier=0):
    """Tells the governor how urgent this scan's next file is, or that it has nothing waiting (scan_class None)."""
    if performance_governor is None:
        return
    try:
        performance_governor.scan_report_head(kind, None if scan_class is None else _scan_rank(scan_class, tier))
    except Exception as _swallowed_error:
        _log_swallowed("_scan_report_head: performance_governor.scan_report_head", _swallowed_error)


def _scan_thread_slot(kind, scan_class, tier=0):
    """Context manager holding one of the governor's shared scan threads for one file: the scan's next file is reported for the scan turns, a less urgent file waits while another scan has a more urgent one, and files airing now never wait. Yields False when the app is shutting down."""
    if performance_governor is None:
        import contextlib as _ctx
        return _ctx.nullcontext(True)
    _scan_report_head(kind, scan_class, tier)
    return performance_governor.scan_thread_slot(kind, priority=_scan_class_name(scan_class) == "now",
                                                 stop=_app_shutting_down, rank=_scan_rank(scan_class, tier))


_picture_box_path_locks = {}
_picture_box_path_locks_guard = threading.Lock()


class _picture_box_path_lock:
    """Per-file lock so the background worker, the tune-in prime and the pre-loudness step never scan the same file twice; a second caller waits, then finds the stored result."""

    def __init__(self, path):
        self._path = path
        self._slot = None

    def __enter__(self):
        with _picture_box_path_locks_guard:
            slot = _picture_box_path_locks.get(self._path)
            if slot is None:
                slot = [threading.Lock(), 0]
                _picture_box_path_locks[self._path] = slot
            slot[1] += 1
        self._slot = slot
        if not slot[0].acquire(blocking=False):
            if performance_governor is not None:
                with performance_governor.scan_slot_idle():
                    slot[0].acquire()
            else:
                slot[0].acquire()
        return self

    def __exit__(self, exc_type, exc, tb):
        self._slot[0].release()
        with _picture_box_path_locks_guard:
            self._slot[1] -= 1
            if self._slot[1] == 0:
                _picture_box_path_locks.pop(self._path, None)
        return False


def _picture_box_scan_one(lib, ml, path, parallel=1):
    """Scan one file into the library if it has no current picture box; serialised per file."""
    with _picture_box_path_lock(path):
        return _picture_box_scan_one_locked(lib, ml, path, parallel)


def _picture_box_scan_one_priority(lib, ml, path, parallel=1):
    """Scans one file's picture box as first-scan work of the file about to play, in a priority scope."""
    with _governor_priority_scope():
        return _picture_box_scan_one(lib, ml, path, parallel)


def _picture_box_before_loudness(norm_p):
    """Decides a video file's picture box before its loudness scan starts. A file that failed, is backing off, is on a struggling drive or is not video is skipped, and nothing here ever stops the loudness scan from running."""
    if not norm_p or os.path.splitext(norm_p)[1].lower() not in media.VIDEO_DISPLAY_EXTS:
        return
    if norm_p in _picture_box_done or norm_p in _scan_pb_has_box:
        return
    if _is_drive_degraded(norm_p):
        return
    try:
        import media_library as _ml
        _lib = _get_probe_library()
        if _lib is None:
            return
        with _governor_priority_scope():
            _picture_box_scan_one(_lib, _ml, norm_p)
    except Exception as e:
        _log_probe_failure("pb_preloud_import", e, "[PICTURE BOX] pre-loudness scan of %s failed (loudness continues): %s",
                           os.path.basename(norm_p), e)


def _prime_channel_picture_box(ch_key, current_file):
    """Tune-in counterpart of the loudness prime: decides the playing file's picture box in the background right away, ahead of its loudness scan."""
    if db is None or not current_file:
        return
    ch_str = str(ch_key).zfill(2)
    if _channel_is_server_streamed(ch_str):
        return
    try:
        norm_p = os.path.normpath(current_file)
    except Exception as _swallowed_error:
        _log_swallowed("_prime_channel_picture_box: norm_p = os.path.normpath(current_file)", _swallowed_error)
        return
    if not _cached_path_exists(norm_p) or norm_p in _picture_box_done or norm_p in _scan_pb_has_box:
        return
    threading.Thread(target=_picture_box_before_loudness, args=(norm_p,), daemon=True,
                     name=f"prime-picbox-ch{ch_str}").start()


def _pipeline_stage_picture_box(norm_p):
    """One file's picture-box scan, as run by the picture-box scan thread. True when the picture box is stored; False when the drive is on hold, the file was removed as broken, or the scan is tried again next pass."""
    if os.path.splitext(norm_p)[1].lower() not in media.VIDEO_DISPLAY_EXTS:
        return True
    if norm_p in _picture_box_done or norm_p in _scan_pb_has_box:
        return True
    try:
        import media_library as _ml
        lib = _get_probe_library()
    except Exception as e:
        _log_warn_throttled("pipeline_pb_lib", "[SCAN PIPELINE] picture box library unavailable, stage skipped: %s" % e)
        return True
    if lib is None:
        return True
    _picture_box_scan_one(lib, _ml, norm_p)
    return norm_p in _picture_box_done


# ============================================================================
# SECTION: First show of a channel just set up
# ============================================================================
# WARNING: owner order 2026-11-02: the moment a channel's files are saved, the show it would be airing gets its duration and picture box first, while the other background scans pause at their next file, so the channel can come on as soon as it is turned to (loudness may follow later); channels set up one after another are done in that order.
_NEW_CHANNEL_SCAN_ACTIVE = threading.Event()
_new_channel_queue = []
_new_channel_queue_lock = threading.Lock()
_new_channel_wake = threading.Event()
_new_channel_thread = None


_channel_added_order = {}


def _channel_scan_rank(ch_key):
    """Where a channel's files go among those of the same scan class: channels set up before this run by number, then channels set up during this run in the order they were set up."""
    ch = str(ch_key or "").zfill(2)
    _added = _channel_added_order.get(ch)
    return (0, int(ch) if ch.isdigit() else 0) if _added is None else (1, _added)


def _queue_new_channel_first_show(ch_key):
    """Puts a channel whose files were just saved in line for its first-show scan and starts the scan thread when it is not running."""
    global _new_channel_thread
    ch = str(ch_key).zfill(2)
    _channel_added_order.setdefault(ch, len(_channel_added_order))
    _note_scan_work_added()
    with _new_channel_queue_lock:
        if ch not in _new_channel_queue:
            _new_channel_queue.append(ch)
        if _new_channel_thread is None or not _new_channel_thread.is_alive():
            _new_channel_thread = threading.Thread(target=_new_channel_first_show_worker, daemon=True, name="NewChannelFirstShow")
            _new_channel_thread.start()
    _new_channel_wake.set()


def _new_channel_airing_paths(ch):
    """The file the channel would be airing right now, exactly as a tune would open it, and its block."""
    _state = calculate_slotted_playback_state(ch) or {}
    _file = _state.get("file") or ""
    return ([os.path.normpath(_file)] if _file else []), (_state.get("block") or "Full Day")


def _warm_new_file_lengths(paths):
    """Asks the library for every just-saved file's length on a background thread, so the screen thread finds each answer already held and never waits on the library file by file."""
    # WARNING: owner log 2026-11-03: the first lineup build of a 2651-file channel asked the library once per file on the screen thread.
    _paths = [str(p) for p in (paths or []) if p]
    if not _paths:
        return

    def _worker():
        _t0 = time.monotonic()
        for _i, _p in enumerate(_paths):
            if _app_shutting_down.is_set():
                return
            try:
                media.read_track_duration(os.path.normpath(_p), 0)
            except Exception as e:
                _log_warn_throttled("warm_lengths", "[LENGTH WARM] could not read the length of %s: %s" % (os.path.basename(_p), e))
            if _i % 50 == 49:
                time.sleep(0)
        log.info("[LENGTH WARM] %d saved file(s) looked up in the library in %.1fs, off the screen thread", len(_paths), time.monotonic() - _t0)

    threading.Thread(target=_worker, daemon=True, name="LengthWarm").start()


def _new_channel_first_pending(ch):
    """The channel's first file that has no length yet, in its airing block (a Visualizer: its first song), and that block; ("", block) when there is none."""
    ch_info = db.channels_db.get(ch, {}) if db is not None else {}
    if ch_info.get("is_visualizer", False):
        _unseekable, _unseekable_exts = _visualizer_admission_inputs()
        _paths = media.pending_visualizer_paths(ch_info.get("schedules", {}).get("Music Tracks", []), _unseekable, _unseekable_exts)
        _block = "Music Tracks"
    else:
        _block = _airing_block_name(ch_info, broadcast_clock.now().replace(tzinfo=None))
        _broken = set(ch_info.get("broken_files", []))
        _paths = [t["path"] for t in build_pending_tracks(ch_info.get("schedules", {}).get(_block, []), _cached_path_exists)
                  if t["path"] not in _broken]
    for _path in _paths:
        _norm = os.path.normpath(_path)
        if _cached_path_exists(_norm) and not _scan_duration_reported(_read_file_probe_facts(_norm), False):
            return _norm, _block
    return "", _block


def _new_channel_first_show_worker():
    """Scans each queued channel's airing show for its duration and picture box, in the order the channels were set up, with the other background scans paused."""
    while not _app_shutting_down.is_set():
        _new_channel_wake.wait(1.0)
        _new_channel_wake.clear()
        while not _app_shutting_down.is_set():
            with _new_channel_queue_lock:
                if not _new_channel_queue:
                    _NEW_CHANNEL_SCAN_ACTIVE.clear()
                    break
                _ch = _new_channel_queue.pop(0)
                _NEW_CHANNEL_SCAN_ACTIVE.set()
            _t0 = time.monotonic()
            try:
                _paths, _block = _new_channel_airing_paths(_ch)
                if not _paths:
                    # WARNING: a channel whose files have no length yet airs Static, so the scheduler names no show; one length is scanned first so it can name the show it would air (owner 2026-11-03: every new channel's first show scanned in 3 to 5 s).
                    _first, _first_block = _new_channel_first_pending(_ch)
                    if _first:
                        with _governor_priority_scope():
                            _first_dur = _scan_store_duration("channel", _ch, _first_block, _first)
                        log.info("[NEW CHANNEL] ch%s: no show has a length yet; %s scanned first: duration %s, %.1fs",
                                 _ch, os.path.basename(_first), "stored" if _first_dur else "not found", time.monotonic() - _t0)
                        _paths, _block = _new_channel_airing_paths(_ch)
                    if not _paths:
                        log.info("[NEW CHANNEL] ch%s: still no show to air after its first length scan; the normal scans will reach it", _ch)
                for _path in _paths:
                    if not _cached_path_exists(_path):
                        continue
                    with _governor_priority_scope():
                        _dur = _scan_duration_reported(_read_file_probe_facts(_path), False) or _scan_store_duration("channel", _ch, _block, _path)
                        _box = _pipeline_stage_picture_box(_path)
                    log.info("[NEW CHANNEL] ch%s: first show %s scanned ahead of the other scans: duration %s, picture box %s, %.1fs",
                             _ch, os.path.basename(_path), "stored" if _dur else "not found", "stored" if _box else "not yet", time.monotonic() - _t0)
            except Exception as _new_channel_error:
                log.warning("[NEW CHANNEL] ch%s: first-show scan failed, the normal scans will reach it: %s", _ch, _new_channel_error)
    _NEW_CHANNEL_SCAN_ACTIVE.clear()


_PICTURE_BOX_PRE_SHOW_BUDGET_S = performance_governor.PICTURE_BOX_PRE_SHOW_BUDGET_S if performance_governor is not None else 8.0


def _engine_open_in_flight(engine):
    """True while the engine's latest play_file_segmented has not handed its file to VLC yet; a mark older than the longest the open can take counts as gone."""
    inflight = getattr(engine, "_open_inflight", None) if engine is not None else None
    if not inflight:
        return False
    return time.monotonic() - inflight[1] < _PICTURE_BOX_PRE_SHOW_BUDGET_S + WEDGED_STOP_TIMEOUT_S + PRE_OPEN_DIMS_PROBE_BOUND_S


def _decide_picture_box_before_show(path):
    """Returns the file's stored picture box for the play path, scanning it first when it has none and waiting up to the pre-show budget; None for non-video, unreadable or held-back files, or when the scan has no answer in time."""
    # WARNING: this runs before the first frame of a play; it must never wait longer than _PICTURE_BOX_PRE_SHOW_BUDGET_S.
    if not path or os.path.splitext(path)[1].lower() not in media.VIDEO_DISPLAY_EXTS:
        return None
    try:
        norm_p = os.path.normpath(os.path.abspath(path))
        if not _cached_path_exists(norm_p):
            return None
        import media_library as _ml
        lib = _get_probe_library()
        if lib is None:
            return None

        def _stored():
            entry = lib.get_cached(norm_p)
            box = entry.get("picture_box") if entry else None
            if box and (entry.get("picture_box_detector_version") or 0) >= _ml.PICTURE_BOX_DETECTOR_VERSION:
                return box
            return None

        box = _stored()
        if box is not None:
            return box
        guessed = _season_guess_picture_box(norm_p)
        if guessed is not None:
            _pb_parallel, _pb_why = (performance_governor.picture_box_pre_show_parallel()
                                     if performance_governor is not None else (1, "no governor"))
            threading.Thread(target=_picture_box_scan_one_priority, args=(lib, _ml, norm_p, _pb_parallel),
                             daemon=True, name="pre-show-picbox").start()
            log.info("[PICTURE BOX] pre-show: %s drawn with its season's picture box (%s picture_aspect=%s) until its own scan lands",
                     os.path.basename(norm_p), guessed.get("reason"), guessed.get("picture_aspect"))
            return guessed
        if _is_drive_degraded(norm_p):
            log.info("[PICTURE BOX] pre-show: %s is on hold (drive struggling), played with its full frame", os.path.basename(norm_p))
            return None
        # WARNING: on a PC where first-start scans must run in sequence, decoding the sample points side by side starves the file that is starting and stalls the picture.
        _pb_parallel, _pb_why = (performance_governor.picture_box_pre_show_parallel()
                                 if performance_governor is not None else (1, "no governor"))
        log.info("[PICTURE BOX] pre-show: %s, %d sample point(s) at once (%s)", os.path.basename(norm_p), _pb_parallel, _pb_why)
        _t0 = time.monotonic()
        _worker = threading.Thread(target=_picture_box_scan_one_priority, args=(lib, _ml, norm_p, _pb_parallel),
                                   daemon=True, name="pre-show-picbox")
        _worker.start()
        _wait_until = _t0 + _PICTURE_BOX_PRE_SHOW_BUDGET_S
        while _worker.is_alive() and time.monotonic() < _wait_until:
            # WARNING: a load the viewer has left stops waiting here at once; the scan itself goes on and stores its answer for later.
            if _activation_superseded():
                log.info("[PICTURE BOX] pre-show: stopped waiting for %s, the viewer left the channel", os.path.basename(norm_p))
                return None
            _worker.join(timeout=min(0.1, max(0.0, _wait_until - time.monotonic())))
        box = _stored()
        _took = time.monotonic() - _t0
        if box is None:
            log.info("[PICTURE BOX] pre-show: no answer for %s within %.1fs, played with its full frame until the scan lands",
                     os.path.basename(norm_p), _took)
        else:
            log.info("[PICTURE BOX] pre-show: %s decided before the show in %.1fs: %s picture_aspect=%s",
                     os.path.basename(norm_p), _took, box.get("reason"), box.get("picture_aspect"))
        return box
    except Exception as e:
        log.warning("[PICTURE BOX] pre-show decision for %s failed: %s", os.path.basename(str(path)), e)
        return None


SCAN_CLASS_NOW = 0
SCAN_CLASS_COMMERCIAL = 1
SCAN_CLASS_NEXT = 2
SCAN_CLASS_DEEP = 3


def _order_scan_pipeline(tiers, deep_items):
    """One ordered list of (class, tier, kind, channel, block, path): airing files on every channel first, then upcoming commercials, then the next 3 shows by distance, then the deeper lineup. A path keeps its best slot."""
    deep_items = _season_seeds_first(deep_items)
    ranked = []
    for tier_idx, tier_items in enumerate(tiers):
        for kind, ch_key, block_key, norm_p in tier_items:
            if tier_idx == 0:
                cls = SCAN_CLASS_NOW
            elif block_key == "Commercials":
                cls = SCAN_CLASS_COMMERCIAL
            else:
                cls = SCAN_CLASS_NEXT
            ranked.append((cls, tier_idx, kind, ch_key, block_key, norm_p))
    for kind, ch_key, block_key, norm_p in deep_items:
        ranked.append((SCAN_CLASS_DEEP, 4, kind, ch_key, block_key, norm_p))
    # WARNING: within a scan class, channels go in the order they were set up (owner 2026-11-02), the same order as the first-show scan; the watched channel's own scan is started at the tune and never waits for this order.
    ranked.sort(key=lambda it: (it[0], it[1], _channel_scan_rank(it[3]) if it[2] == "channel" else (0, 0)))
    out, seen = [], set()
    for it in ranked:
        if it[5] in seen:
            continue
        seen.add(it[5])
        out.append(it)
    return out


def _picture_box_scan_one_locked(lib, ml, path, parallel=1):
    """Scan one file into the library if it has no current picture box."""
    try:
        entry = lib.get_cached(path)
        if (entry and entry.get("picture_box")
                and (entry.get("picture_box_detector_version") or 0) >= ml.PICTURE_BOX_DETECTOR_VERSION):
            _picture_box_done.add(path)
            return False
        diag = {}
        t0 = time.monotonic()
        box = lib.detect_picture_box_if_needed(path, diag=diag, parallel=parallel)
        took = time.monotonic() - t0
    except Exception as e:
        verdict = _scan_handle_failure(path, "picture box", "scan crashed: %s" % e)
        log.warning("[PICTURE BOX] scan of %s crashed (%s): %s", os.path.basename(path), verdict, e)
        if verdict == SCAN_FAIL_RETRY and _scan_retries_exhausted(path, "picture box"):
            _scan_handle_failure(path, "picture box", "crashed %d times on a healthy drive" % SCAN_RETRY_LIMIT, corrupt=True)
        return True
    if box is None:
        stderr = diag.get("stderr")
        timed_out = bool(diag.get("timeouts")) or bool(diag.get("unkeyable"))
        why = "timed out" if timed_out else ("ffmpeg could not open it" if stderr is not None else "no result")
        verdict = _scan_handle_failure(path, "picture box", why, timed_out=timed_out,
                                       corrupt=bool(stderr) and media._stderr_indicates_corrupt(stderr))
        log.info("[PICTURE BOX] no answer for %s: %s -> %s", os.path.basename(path), why, verdict)
        if verdict == SCAN_FAIL_RETRY and _scan_retries_exhausted(path, "picture box"):
            # WARNING: a file that opens but whose cropdetect keeps timing out on a healthy drive is still labeled (full frame, no bars); only a file with no usable frame size is declared dead.
            label = lib.store_full_frame_picture_box(path) if timed_out else None
            if label is not None:
                _picture_box_done.add(path)
                _picture_box_guessed.add(path)
                _scan_retry_counts.pop((path, "picture box"), None)
                log.info("[PICTURE BOX] %s: cropdetect kept timing out, labeled full frame %s", os.path.basename(path), label.get("frame"))
            else:
                _scan_handle_failure(path, "picture box", "no usable result after %d tries on a healthy drive" % SCAN_RETRY_LIMIT, corrupt=True)
        return True
    _picture_box_done.add(path)
    _scan_retry_counts.pop((path, "picture box"), None)
    log.info("[PICTURE BOX] %s: %s picture_aspect=%s rect=%s frame=%s samples=%s (%.1fs)",
             os.path.basename(path), box.get("reason"), box.get("picture_aspect"),
             box.get("rect"), box.get("frame"), box.get("samples"), took)
    return True


# ============================================================================
# SECTION: Duration scan (runs ahead of the scan chain)
# ============================================================================
# SECTION: Duration scan (runs ahead of the scan chain)
# ============================================================================


def _duration_scan_worker():
    """Background thread: stores the duration of every scheduled file in the scan chain's order, without waiting for any file's picture box or loudness scan."""
    if db is None:
        return
    log.info("[DURATION SCAN] ahead-of-chain scan starting")
    _attempted = set()
    while not _app_shutting_down.is_set():
        if _background_scan_should_pause():
            if _app_shutting_down.wait(DURATION_PRECACHE_PAUSE_RECHECK_SECONDS):
                return
            continue
        try:
            _items = _order_scan_pipeline(_gather_probe_priority_queue(), _gather_deep_backlog_queue())
        except Exception as e:
            log.warning("[DURATION SCAN] gather failed: %s", e)
            _items = []
        _gathered_at = time.monotonic()
        _stored = 0
        _regather = False
        for _cls, _tier_idx, _kind, _ch_key, _block_key, _norm_p in _items:
            if _app_shutting_down.is_set():
                return
            if _norm_p in _attempted or _scan_duration_reported(_read_file_probe_facts(_norm_p), False):
                continue
            if not _cached_path_exists(_norm_p):
                continue
            while _background_scan_should_pause():
                if _app_shutting_down.wait(DURATION_PRECACHE_PAUSE_RECHECK_SECONDS):
                    return
            if _is_drive_degraded(_norm_p):
                _scan_hold_drive(_norm_p, _drive_latency_summary(_norm_p) or "drive degraded")
            if _scan_drive_on_hold(_norm_p):
                continue
            _attempted.add(_norm_p)
            with _scan_thread_slot("duration", _cls, _tier_idx) as _slot_ok:
                if not _slot_ok:
                    return
                try:
                    with (_governor_priority_scope() if _cls == SCAN_CLASS_NOW else _governor_nullscope()):
                        if _scan_store_duration(_kind, _ch_key, _block_key, _norm_p) > 0:
                            _stored += 1
                        else:
                            _scan_duration_failed(_norm_p)
                except Exception as e:
                    log.warning("[DURATION SCAN] %s failed (next file continues): %s", os.path.basename(_norm_p), e)
            _pace = _scan_class_pace_seconds(_cls, BETWEEN_LOUDNESS_PROBES_SECONDS)
            if _pace > 0 and _app_shutting_down.wait(_pace):
                return
            if time.monotonic() - _gathered_at >= SCAN_PIPELINE_PREEMPT_CHECK_SECONDS:
                _regather = True
                break
        if _stored:
            try:
                db.save_settings_async()
            except Exception as e:
                log.warning("[DURATION SCAN] settings save failed: %s", e)
        if _regather:
            continue
        _attempted.clear()
        _scan_report_head("duration")
        if _scan_idle_wait(DURATION_PRECACHE_IDLE_SLEEP_SECONDS if _items else DURATION_PRECACHE_PAUSE_RECHECK_SECONDS):
            return


def _picture_box_lane_hold_reason():
    """(None, "") when the picture-box scan may start a file; otherwise ("pause", why) while background scans are paused, or ("first_start", why) while the playing file's first-start scans run and this PC's plan says they run in sequence."""
    # WARNING: the first-start plan decides together or in sequence per PC and load; the picture-box thread must follow it or it competes with the tune-in scan of the playing file.
    if _background_scan_should_pause():
        return "pause", "background scans are paused"
    if not _LOUDNESS_PRIORITY_PENDING.is_set():
        return None, ""
    if performance_governor is None:
        return "first_start", "no governor, scans run in sequence"
    try:
        _together, _why = performance_governor.first_start_scan_plan()
    except Exception as e:
        _log_swallowed("_picture_box_lane_hold_reason: reading the first-start plan", e)
        return "first_start", "first-start plan unreadable, scans run in sequence"
    if _together:
        return None, ""
    return "first_start", _why


def _picture_box_lane_wait():
    """Blocks the picture-box scan thread while it may not start a file; True when the app is shutting down. Each hold is named once in the log when it starts, and the resume line says how long each hold lasted."""
    _held_at = time.monotonic()
    _held_by = {}
    _last_kind, _last_at = None, _held_at
    while True:
        _kind, _why = _picture_box_lane_hold_reason()
        _now = time.monotonic()
        if _last_kind is not None:
            _held_by[_last_kind] = _held_by.get(_last_kind, 0.0) + (_now - _last_at)
        _last_kind, _last_at = _kind, _now
        if _kind is None:
            if _held_by:
                log.info("[PICTURE BOX] lane resumed after %.1fs (%s)", _now - _held_at,
                         ", ".join("%s %.0fs" % (_k, _v) for _k, _v in sorted(_held_by.items())))
            return False
        if _kind not in _held_by:
            _held_by[_kind] = 0.0
            if _kind == "first_start":
                log.info("[PICTURE BOX] lane waiting: the playing file's first-start scans run in sequence (%s)", _why)
            else:
                log.info("[PICTURE BOX] lane waiting: %s (the governor's load level or a new channel's first show)", _why)
        if _app_shutting_down.wait(PICTURE_BOX_PAUSE_RECHECK_SECONDS):
            return True


# WARNING: the fallback numbers below must match NEXT_ITEM_PREP_ITEMS, NEXT_ITEM_PREP_FIRST_START_WAIT_SECONDS in performance_governor.py; they are used only when that module fails to import.
NEXT_ITEM_PREP_ITEMS = performance_governor.NEXT_ITEM_PREP_ITEMS if performance_governor is not None else 3
# WARNING: the fallback number below must match NEXT_ITEM_PREP_BREAK_MAX_ITEMS in performance_governor.py; it is used only when that module fails to import.
NEXT_ITEM_PREP_BREAK_MAX_ITEMS = performance_governor.NEXT_ITEM_PREP_BREAK_MAX_ITEMS if performance_governor is not None else 12
NEXT_ITEM_PREP_FIRST_START_WAIT_SECONDS = performance_governor.NEXT_ITEM_PREP_FIRST_START_WAIT_SECONDS if performance_governor is not None else 60.0
# WARNING: only _request_next_item_prep writes "request" and only the NextItemPrep thread takes it; a newer request replaces an older one that has not started.
_next_item_prep_state = {"lock": threading.Lock(), "wake": threading.Event(), "request": None, "thread": None}


def _request_next_item_prep(ch_key, file_path):
    """Asks the NextItemPrep thread to get the next items after file_path on ch_key ready, replacing an older request."""
    if not ch_key or not file_path:
        return
    state = _next_item_prep_state
    with state["lock"]:
        state["request"] = (str(ch_key).zfill(2), file_path)
        if state["thread"] is None or not state["thread"].is_alive():
            state["thread"] = threading.Thread(target=_next_item_prep_worker, name="NextItemPrep", daemon=True)
            state["thread"].start()
    state["wake"].set()


def _next_item_prep_plan(ch_key, file_path):
    """Returns (the video files to ready ahead, nearest first, each once; whether a commercial break is on or next): the next NEXT_ITEM_PREP_ITEMS items after file_path, and when a break is among or right after them, on through the whole break and the item after it, up to NEXT_ITEM_PREP_BREAK_MAX_ITEMS; ([], False) when the block's order is not known."""
    window = max(NEXT_ITEM_PREP_ITEMS, NEXT_ITEM_PREP_BREAK_MAX_ITEMS) + 1
    items = _next_n_from_block_timeline(ch_key, file_path, n=window)
    if items is not None:
        upcoming = [(it.get("path", ""), bool(it.get("is_commercial"))) for it in items[1:]]
        on_air_is_break = bool(items[0].get("is_commercial")) if items else False
    else:
        rec = _scan_snapshot_channel(ch_key)
        if not rec or not rec.get("ordered"):
            return [], False
        upcoming = [(p, False) for entry in _next_n_from_ordered(rec["ordered"], file_path, n=NEXT_ITEM_PREP_ITEMS + 1)
                    for p in _paths_from_entry(entry)]
        on_air_is_break = False
    chosen = []
    in_break = on_air_is_break
    for i, (path, is_commercial) in enumerate(upcoming):
        if i >= NEXT_ITEM_PREP_ITEMS and not in_break:
            break
        if i >= NEXT_ITEM_PREP_BREAK_MAX_ITEMS:
            break
        chosen.append(path)
        if is_commercial:
            in_break = True
        elif in_break and i >= NEXT_ITEM_PREP_ITEMS - 1:
            break
    break_near = on_air_is_break or any(c for _p, c in upcoming[:NEXT_ITEM_PREP_ITEMS])
    current = os.path.normpath(file_path)
    out = []
    for p in chosen:
        if not p:
            continue
        norm_p = os.path.normpath(p)
        if norm_p == current or norm_p in out:
            continue
        if os.path.splitext(norm_p)[1].lower() not in media.VIDEO_DISPLAY_EXTS:
            continue
        out.append(norm_p)
    return out, break_near


def _next_item_prep_paths(ch_key, file_path):
    """The video files _next_item_prep_plan readies ahead after file_path in ch_key's block."""
    return _next_item_prep_plan(ch_key, file_path)[0]


def _first_start_scans_run_alone():
    """True while the playing file's first-start scans run and this PC's plan says nothing else may scan beside them."""
    if not _LOUDNESS_PRIORITY_PENDING.is_set():
        return False
    if performance_governor is None:
        return True
    try:
        together, _why = performance_governor.first_start_scan_plan()
    except Exception as e:
        _log_swallowed("_first_start_scans_run_alone: reading the first-start plan", e)
        return True
    return not together


def _next_item_prep_worker():
    """NextItemPrep thread: for the latest request, stores the picture box of each next item that has none, nearest first, as priority work; a newer request or another channel going on air stops the older one."""
    state = _next_item_prep_state
    while not _app_shutting_down.is_set():
        state["wake"].wait()
        state["wake"].clear()
        with state["lock"]:
            request, state["request"] = state["request"], None
        if request is None:
            continue
        ch_key, file_path = request

        def _stale():
            return (state["request"] is not None or _app_shutting_down.is_set()
                    or str(app_state.get("_live_playback_channel", "") or "").zfill(2) != ch_key)

        try:
            paths, _break_near = _next_item_prep_plan(ch_key, file_path)
        except Exception as e:
            log.warning("[NEXT ITEM] ch%s: working out the next items after %s failed: %s", ch_key, os.path.basename(str(file_path)), e)
            continue
        # WARNING: a break's items start seconds apart, so waiting here for the playing file's first-start scans leaves its later commercials with no picture box at their open (N16).
        _waited_from = time.monotonic()
        while (not _break_near and _first_start_scans_run_alone() and not _stale()
               and time.monotonic() - _waited_from < NEXT_ITEM_PREP_FIRST_START_WAIT_SECONDS):
            if _app_shutting_down.wait(PICTURE_BOX_PAUSE_RECHECK_SECONDS):
                return
        if _stale():
            continue
        started = time.monotonic()
        made = []
        for norm_p in paths:
            _season_guess_warm(norm_p)
        for norm_p in paths:
            if _stale():
                break
            if norm_p in _picture_box_done or norm_p in _scan_pb_has_box or not _cached_path_exists(norm_p):
                continue
            _picture_box_before_loudness(norm_p)
            made.append(os.path.basename(norm_p))
        if made:
            log.info("[NEXT ITEM] ch%s: picture box ready ahead for %s in %.1fs (after %s)",
                     ch_key, ", ".join(made), time.monotonic() - started, os.path.basename(str(file_path)))


def _picture_box_scan_worker():
    """Background thread: stores the picture box of every scheduled video file in the scan chain's order, without waiting for any file's duration or loudness scan."""
    # WARNING: the picture-box scan has its own thread in the same order as the duration and loudness scans; it must never call into the loudness chain, and the loudness chain must never wait for it.
    if db is None:
        return
    log.info("[PICTURE BOX] lane starting, independent of the duration and loudness scans")
    _attempted = set()
    while not _app_shutting_down.is_set():
        if _picture_box_lane_wait():
            return
        try:
            _items = _order_scan_pipeline(_gather_probe_priority_queue(), _gather_deep_backlog_queue())
        except Exception as e:
            log.warning("[PICTURE BOX] gather failed: %s", e)
            _items = []
        _gathered_at = time.monotonic()
        _scanned = 0
        _regather = False
        for _cls, _tier_idx, _kind, _ch_key, _block_key, _norm_p in _items:
            if _app_shutting_down.is_set():
                return
            if _norm_p in _attempted or _scan_picture_box_reported(_norm_p, [0]):
                continue
            if not _cached_path_exists(_norm_p):
                continue
            if _picture_box_lane_wait():
                return
            if _is_drive_degraded(_norm_p):
                _scan_hold_drive(_norm_p, _drive_latency_summary(_norm_p) or "drive degraded")
            if _scan_drive_on_hold(_norm_p):
                continue
            _attempted.add(_norm_p)
            with _scan_thread_slot("picture_box", _cls, _tier_idx) as _slot_ok:
                if not _slot_ok:
                    return
                try:
                    with (_governor_priority_scope() if _cls == SCAN_CLASS_NOW else _governor_nullscope()):
                        if _pipeline_stage_picture_box(_norm_p):
                            _scanned += 1
                except Exception as e:
                    log.warning("[PICTURE BOX] lane: %s failed (next file continues): %s", os.path.basename(_norm_p), e)
            _pace = _scan_class_pace_seconds(_cls, PICTURE_BOX_BETWEEN_FILES_SECONDS)
            if _pace > 0 and _app_shutting_down.wait(_pace):
                return
            if time.monotonic() - _gathered_at >= SCAN_PIPELINE_PREEMPT_CHECK_SECONDS:
                _regather = True
                break
        if _scanned:
            try:
                db.save_settings_async()
            except Exception as e:
                log.warning("[PICTURE BOX] lane: settings save failed: %s", e)
        if _regather:
            continue
        _attempted.clear()
        _scan_report_head("picture_box")
        if _scan_idle_wait(PICTURE_BOX_IDLE_SLEEP_SECONDS if _items else PICTURE_BOX_PAUSE_RECHECK_SECONDS):
            return


_EMPTY_FOLDER_DIAG_LOGGED = set()


# ============================================================================
# SECTION: Slotted playback state
# ============================================================================


_resolve_log_state = {}


def _note_aired_cycle(playback_log, block_name, block_key, now, current_seconds, seconds_into_block, cycle_boundary, timeline, total, block_end_offset=None):
    """Records one scheduler cycle in the channel's guide ledger, cut to what airs before the block ends, and saves where the entry running past the block end finishes; a failure is logged and never reaches the scheduler."""
    try:
        _block_abs_start = now.toordinal() * 86400 + current_seconds - seconds_into_block
        if block_end_offset is not None:
            timeline, total = media.timeline_through_block_end(timeline, total, block_end_offset - cycle_boundary)
            media.note_block_overrun(playback_log, block_key, _block_abs_start + cycle_boundary, total, block_end_offset - cycle_boundary)
        media.aired_ledger_upsert(playback_log, block_name, block_key, _block_abs_start + cycle_boundary, timeline, total, now)
    except Exception as e:
        log.warning("[SCHEDULER] guide ledger record failed (non-fatal): %s", e)


def _note_missed_blocks(ch_info, channel_key, show_pos, prev_block_key, block_key, now,
                        commercial_tracks, is_holiday_date):
    """Records in the channel's guide ledger the cycles that should have aired since the last block the scheduler built; a failure is logged and never reaches the scheduler."""
    try:
        _history_t0 = time.perf_counter()
        playback_log = ch_info.setdefault("playback_log", {})
        # WARNING: the block-start check and the scheduler both ask for the same gap in one pass; its records are already in the ledger and the hub after the first, so the second walk is skipped.
        if playback_log.get("_missed_blocks_noted") == [prev_block_key, block_key]:
            return
        playback_log["_missed_blocks_noted"] = [prev_block_key, block_key]
        records = media.replay_missed_blocks(
            channel_key, ch_info, show_pos, prev_block_key, block_key, now,
            _cached_path_exists, commercial_tracks, lambda _offset: _start_order_seed(ch_info, _offset),
            is_holiday_date)
        for _name, _key, _abs_start, _timeline, _total in records:
            media.aired_ledger_upsert(playback_log, _name, _key, _abs_start, _timeline, _total, now)
        _write_missed_blocks_to_hub(ch_info, channel_key, records)
        if records:
            log.info("[GUIDE HISTORY] ch%s rebuilt %d missed cycle(s) since block %s in %.1f ms",
                     channel_key, len(records), prev_block_key, (time.perf_counter() - _history_t0) * 1000.0)
    except Exception as e:
        log.warning("[SCHEDULER] guide past rebuild failed (non-fatal): %s", e)


def _write_missed_blocks_to_hub(ch_info, channel_key, records):
    """Records in the hub, as aired rows, the cycles the clock scheduled while the station was off (the same cycles the guide's past is rebuilt from); a cycle the hub already has a row for is left alone."""
    # WARNING: this only records; a failure here must never stop the scheduler, and nothing already in the hub is changed or removed (R26).
    try:
        import media_library as _ml
        _hub = _ml.shared_schedule_hub()
        _channel = _hub_channel_key(channel_key)
        _mode = _hub_channel_mode(channel_key)
        _written_total = 0
        for _name, _key, _abs_start, _timeline, _total in records:
            _moment = datetime.datetime.fromordinal(int(_abs_start) // 86400) + datetime.timedelta(seconds=int(_abs_start) % 86400)
            _epoch = _moment.timestamp()
            if _hub.at(_channel, _epoch + 1.0) is not None:
                continue
            _items = ch_info.get("schedules", {}).get(_name, [])
            _bundles = _hub_bundles_for(_channel, build_raw_tracks(_items, _cached_path_exists))
            _written_total += _hub.put_aired_rows(
                _channel, "%s@%d" % (_key, int(_abs_start)), media.schedule_rows_from_timeline(_timeline, _epoch, _bundles), mode=_mode)
        if _written_total:
            log.info("[HUB SCHEDULE] ch%s: %d aired row(s) recorded for the cycles the clock scheduled while the station was off", _channel, _written_total)
    except Exception as _e:
        _log_warn_throttled("hub_schedule_missed", "[HUB SCHEDULE] ch%s: could not record the missed cycles in the hub: %s", channel_key, _e)


_hub_future_state = {}


def _hub_future_inputs_signature(ch_info):
    """A short text that changes when anything the channel's future depends on (the saved show positions and cycle, the files of every block, the settings that shape a block) changes."""
    import hashlib
    import json
    _log = ch_info.get("playback_log", {}) or {}
    _parts = {
        "block": _log.get("sched_block_key"), "boundary": _log.get("sched_cycle_boundary"), "total": _log.get("sched_cycle_total"),
        "pos": _log.get("show_pos"), "orders": _log.get("show_order"), "commercial": _log.get("commercial_next_pos", _log.get("commercial_pos")),
        "files": {name: [(a.get("path", a.get("file", "")) if isinstance(a, dict) else str(a)) for a in items]
                  for name, items in (ch_info.get("schedules", {}) or {}).items()},
        "broken": sorted(ch_info.get("broken_files", []) or []),
        "settings": [ch_info.get(k) for k in ("block_mode", "scheduling_mode", "commercials_enabled", "commercial_placement", "pair_threshold_minutes", "active")],
        "holiday_files": {name: [(a.get("path", a.get("file", "")) if isinstance(a, dict) else str(a)) for a in items]
                          for name, items in (ch_info.get("holiday_schedules", {}) or {}).items()},
        "holiday_state": {name: {k: (h or {}).get(k) for k in ("block_key", "cycle_boundary", "cycle_index", "total_duration", "show_pos", "show_order", "commercial_pos")}
                          for name, h in (ch_info.get("holiday_playback_log", {}) or {}).items()},
        "anchors": _log.get("block_anchors"),
    }
    return hashlib.md5(json.dumps(_parts, sort_keys=True, default=str).encode("utf-8")).hexdigest()


def _hub_future_snapshot(ch_info):
    """A copy of just the parts of a channel the projection reads, so the scheduler thread changing its saved state cannot change it half way through."""
    _log = ch_info.get("playback_log", {}) or {}
    _keep = ("sched_block_key", "show_pos", "show_order", "commercial_next_pos", "commercial_pos", "block_anchors",
             "sched_cycle_boundary", "sched_cycle_total", "intro_seed", media.BLOCK_OVERRUN_KEY)
    _snap = {k: copy.deepcopy(v) for k, v in ch_info.items() if k not in ("playback_log", "schedules")}
    _snap["schedules"] = {name: list(items) for name, items in (ch_info.get("schedules", {}) or {}).items()}
    _snap["playback_log"] = {k: copy.deepcopy(_log[k]) for k in _keep if k in _log}
    return _snap


def _settle_future_rows(new_rows, saved_rows, now_epoch, live_hours=None):
    """The future rows to save: every new row inside the live hours, then whole further days of new rows while every row of the day has a measured length, then the rows saved before for what lies beyond; None when that is exactly what is saved already."""
    # WARNING: owner order 2026-11-02: the first GUIDE_LIVE_HOURS are always up to date, and each day past them is redrawn only once all its lengths are measured, so estimates being replaced one by one never keep moving the far guide; with nothing saved yet, the new rows are used whole so the guide fills at once.
    _day = 3600.0 * float(_GUIDE_LIVE_HOURS if live_hours is None else live_hours)
    _new = sorted(new_rows, key=lambda r: float(r["planned_start"]))
    _horizon = float(now_epoch) + _day
    _last_start = max((float(r["planned_start"]) for r in _new), default=_horizon)
    if saved_rows:
        while _horizon <= _last_start:
            _window = [r for r in _new if _horizon <= float(r["planned_start"]) < _horizon + _day]
            if not _window or any(r.get("length_source") == "estimate" for r in _window):
                break
            _horizon += _day
        _kept_new = [r for r in _new if float(r["planned_start"]) < _horizon]
        _seam = max([_horizon] + [float(r["planned_start"]) + float(r["used_length"] or 0) for r in _kept_new])
        _settled = _kept_new + [dict(r) for r in sorted(saved_rows, key=lambda r: float(r["planned_start"]))
                                if float(r["planned_start"]) >= _seam - 0.5]
    else:
        _settled = _new
    _key = lambda r: (str(r.get("path")), round(float(r["planned_start"]), 1), round(float(r.get("used_length") or 0), 1))
    if saved_rows and [_key(r) for r in _settled] == [_key(r) for r in sorted(saved_rows, key=lambda r: float(r["planned_start"]))]:
        return None
    return _settled


def _hub_loop_cycle_timeline(tracks, commercial_tracks, ch_info, day_seed, keep_commercials):
    """One pass through a looping channel's tracks as timeline entries with start_time from the top of the pass; Marathon goes through the scheduler's own timeline builder, a Visualizer lineup is the plain track list."""
    if keep_commercials:
        _timeline, _total, _state = media.build_channel_timeline(tracks, commercial_tracks, ch_info, day_seed)
        return _timeline or [], float(_total or 0)
    _timeline, _at = [], 0.0
    for _t in tracks:
        _d = float(_t.get("duration", 0) or 0)
        if _d <= 0:
            continue
        _timeline.append({"path": _t["path"], "duration": _d, "start_time": _at, "is_commercial": False})
        _at += _d
    return _timeline, _at


def _hub_loop_plan(channel_key, ch_info, now):
    """What a Marathon or Visualizer channel will air from now until HUB_FUTURE_HOURS_AHEAD, as (slot_key, pass_start_epoch, timeline) pairs worked out from the channel's own media with the same order and position the scheduler uses; a Visualizer plan stops at midnight because tomorrow's lineup is not built yet."""
    # WARNING: this only plans; it never changes what airs, and the scheduler stays the writer of what is airing now.
    _now_epoch = now.timestamp()
    _horizon = _now_epoch + 3600.0 * _HUB_FUTURE_HOURS_AHEAD
    _naive = now.replace(tzinfo=None)
    if ch_info.get("is_visualizer", False):
        _tracks, _total, _origin = _visualizer_frozen_lineup(channel_key, ch_info, _naive)
        if not _tracks or _total <= 0:
            return []
        _timeline, _len = _hub_loop_cycle_timeline(_tracks, [], ch_info, 0, False)
        if _len <= 0:
            return []
        _midnight = datetime.datetime.combine(_naive.date(), datetime.time(0)).timestamp()
        _cur = _naive.hour * 3600 + _naive.minute * 60 + _naive.second + _naive.microsecond / 1e6
        _pos = (_cur - _origin) % _len
        _start = _now_epoch - _pos
        _horizon = min(_horizon, _midnight + 86400.0)
        _label = "Music"
    else:
        _items = ch_info.get("schedules", {}).get("Marathon", [])
        _raw = build_raw_tracks(_items, _cached_path_exists)
        if not _raw:
            return []
        _ordered = build_ordered_tracks(_raw, "marathon", _marathon_start_seed(ch_info))
        _log = ch_info.get("playback_log", {}) or {}
        _durs = _log.get("marathon_cached_durations", {}) or {}
        _tracks = apply_cached_durations(_ordered, _durs) if _durs else _ordered
        _commercials = []
        if ch_info.get("commercials_enabled", False):
            _citems = ch_info.get("schedules", {}).get("Commercials", [])
            _commercials = build_commercial_tracks(_citems, _cached_path_exists) if _citems else []
        _seed = media.block_day_seed(media.block_start_date(_naive, "Marathon"), channel_key, media.block_seed_offset("Marathon", 0))
        _timeline, _len = _hub_loop_cycle_timeline(_tracks, _commercials, ch_info, _seed, True)
        if _len <= 0:
            return []
        _anchor = ch_info.get("marathon_anchor_epoch")
        if not _anchor:
            return []
        _epoch_now = _naive.toordinal() * 86400 + (_naive.hour * 3600 + _naive.minute * 60 + _naive.second + _naive.microsecond / 1e6)
        _start = _now_epoch - ((_epoch_now - _anchor) % _len)
        _label = "Marathon"
    _plan = []
    _guard = 0
    while _start < _horizon and _guard < 2000:
        _plan.append(("%s@%d" % (_label, int(_start)), _start, _timeline))
        _start += _len
        _guard += 1
    return _plan


def _hub_future_for_loop_channel(channel_key, ch_info, now=None, force=False):
    """Saves the hub's future rows for a Marathon or Visualizer channel, built from that mode's own media; only entries that start after now are kept, so the airing row stays the scheduler's."""
    try:
        now = now or broadcast_clock.now()
        _signature = "loop|" + _hub_future_inputs_signature(ch_info) + "|" + str(now.toordinal()) + "|" + str(ch_info.get("marathon_anchor_epoch"))
        _state = _hub_future_state.get(channel_key)
        _mono = time.monotonic()
        if not force and _state and _state[0] == _signature and _mono - _state[1] < _HUB_FUTURE_REFRESH_SECONDS:
            return 0
        _plan = _hub_loop_plan(channel_key, ch_info, now)
        _now_epoch = now.timestamp()
        _rows = []
        for _slot, _pass_start, _timeline in _plan:
            for _row in media.schedule_rows_from_timeline(_timeline, _pass_start):
                if _row["planned_start"] <= _now_epoch:
                    continue
                _row["slot_key"] = _slot
                _rows.append(_row)
        import media_library as _ml
        _hub_f = _ml.shared_schedule_hub()
        _written = _hub_f.replace_future_rows(channel_key, _rows)
        _hub_future_state[channel_key] = (_signature, _mono)
        if not _rows:
            return 0
        _hub_future_log_once(channel_key, "loop", "[HUB FUTURE] ch%s: %d row(s) saved for the next %.0f hours from its own %s media",
                             channel_key, _written, _HUB_FUTURE_HOURS_AHEAD, "Visualizer" if ch_info.get("is_visualizer", False) else "Marathon")
        return _written
    except Exception as _e:
        _log_warn_throttled("hub_future_loop_" + str(channel_key), "[HUB FUTURE] ch%s: could not plan the looping channel's future rows: %s", channel_key, _e)
        return None


def _hub_future_for_channel(channel_key, now=None, force=False):
    """Works out what one channel will air from the end of the cycle on air until HUB_FUTURE_HOURS_AHEAD from now, from the prebuilt order and the saved show positions, and saves it in the hub as future rows. Returns the number of rows saved, 0 when nothing needed doing, or None when it could not be done."""
    # WARNING: this only plans; it never changes the channel's saved positions or what airs, a channel whose block on air is not the last block built is left to the scheduler (R16, R18), and a failure is logged once and never reaches the scheduler.
    try:
        _channel = _hub_channel_key(channel_key)
        _info = db.channels_db.get(_channel, {}) if db is not None else {}
        if not _info or not _info.get("active", True):
            return 0
        if _info.get("is_visualizer", False) or _info.get("scheduling_mode", "random_slots") == "marathon":
            return _hub_future_for_loop_channel(_channel, _info, now, force)
        now = now or broadcast_clock.now()
        _log = _info.get("playback_log", {}) or {}
        _mode = _info.get("block_mode", "full_day")
        _forced = media.holiday_forced_key_for_channel(db.config, _channel)
        _signature = _hub_future_inputs_signature(_info) + "|" + str(now.toordinal()) + "|" + str(_forced)
        _state = _hub_future_state.get(_channel)
        _mono = time.monotonic()
        if not force and _state and _state[0] == _signature and _mono - _state[1] < _HUB_FUTURE_REFRESH_SECONDS:
            return 0
        _t0 = time.perf_counter()
        _snap = _hub_future_snapshot(_info)
        _items = _snap.get("schedules", {}).get("Commercials", [])
        _commercials = build_commercial_tracks(_items, _cached_path_exists) if _snap.get("commercials_enabled", False) and _items else []
        _playable = {}

        def _holiday_of(_d):
            _k = media.holiday_key_for_date(_d, _forced, now.date())
            if not _k:
                return None
            if _k not in _playable:
                _playable[_k] = bool(media.holiday_day_tracks(_snap, _k, _cached_path_exists)[0])
            return _k if _playable[_k] else None

        _is_holiday = lambda _d: _holiday_of(_d) is not None
        _order_seed_for = lambda _offset: _start_order_seed(_snap, _offset)
        _holiday_today = _is_holiday(now.date())
        if not _holiday_today and (not _log.get("sched_block_key") or _log.get("sched_block_key") != media.block_key_containing(_mode, now)):
            return 0
        _records = [] if _holiday_today else media.project_future_blocks(
            _channel, _snap, now, _cached_path_exists, _commercials, _order_seed_for, _is_holiday, _HUB_FUTURE_HOURS_AHEAD)
        _records = _records + media.project_holiday_days(
            _channel, _snap, now, _cached_path_exists, _commercials, _order_seed_for, _holiday_of, _missed_block_day_seeds, _HUB_FUTURE_HOURS_AHEAD)
        if _holiday_today and not _records:
            return 0
        _records.sort(key=lambda _r: _r[2])
        _rows = []
        _now_epoch = now.timestamp()
        for _name, _key, _abs_start, _timeline, _total in _records:
            _moment = datetime.datetime.fromordinal(int(_abs_start) // 86400) + datetime.timedelta(seconds=int(_abs_start) % 86400)
            _epoch = _moment.timestamp()
            if _epoch + _total <= _now_epoch:
                continue
            _slot = "%s@%d" % (_key, int(_abs_start))
            for _row in media.schedule_rows_from_timeline(_timeline, _epoch):
                _row["slot_key"] = _slot
                _rows.append(_row)
        import media_library as _ml
        _hub_f = _ml.shared_schedule_hub()
        _rows = _settle_future_rows(_rows, _hub_f.future_rows_between(_channel, _now_epoch, _now_epoch + 3600.0 * (_HUB_FUTURE_HOURS_AHEAD + 48.0)), _now_epoch)
        if _rows is None:
            _hub_future_state[_channel] = (_signature, _mono)
            return 0
        _written = _hub_f.replace_future_rows(_channel, _rows)
        _hub_future_state[_channel] = (_signature, _mono)
        _hub_future_log_once(_channel, "ok", "[HUB FUTURE] ch%s: %d row(s) saved for the next %.0f hours from the prebuilt order in %.0f ms",
                             _channel, _written, _HUB_FUTURE_HOURS_AHEAD, (time.perf_counter() - _t0) * 1000.0)
        return _written
    except Exception as _e:
        _log_warn_throttled("hub_future_" + str(channel_key), "[HUB FUTURE] ch%s: could not work out or save the future rows, the guide draws its own future: %s", channel_key, _e)
        return None


_hub_future_logged = {}


def _hub_future_log_once(channel, kind, message, *args):
    """Writes an informational line for a channel only when its row count changed, so the log is not filled every pass."""
    _k = (channel, kind)
    if _hub_future_logged.get(_k) != args[1:2]:
        _hub_future_logged[_k] = args[1:2]
        log.info(message, *args)


def _hub_future_worker():
    """Background thread: after boot, one channel per pass, saves what each channel will air in the next hours as hub future rows, only while the governor allows background work."""
    # WARNING: nothing here may run during boot or crowd playback: it waits HUB_FUTURE_START_DELAY_SECONDS, stops while _python_heavy_should_pause() says so, and sleeps between channels.
    if db is None:
        return
    if _app_shutting_down.wait(_HUB_FUTURE_START_DELAY_SECONDS):
        return
    log.info("[HUB FUTURE] background step starting: one channel per pass, %.0f hours ahead", _HUB_FUTURE_HOURS_AHEAD)
    while not _app_shutting_down.is_set():
        _did = 0
        try:
            _watched = str(app_state.get("current_channel", "")).zfill(2)
            _channels = sorted((str(i).zfill(2) for i in range(5, 45)), key=lambda c: (c != _watched, c))
        except Exception as _swallowed_error:
            _log_swallowed("_hub_future_worker: _watched = str(app_state.get('current_channel', '')).zfill(2)", _swallowed_error)
            _channels = [str(i).zfill(2) for i in range(5, 45)]
        for _ch in _channels:
            if _app_shutting_down.is_set():
                return
            if _python_heavy_should_pause():
                if _app_shutting_down.wait(_HUB_FUTURE_IDLE_SECONDS):
                    return
                continue
            with _background_activity("hub_future"):
                _written = _hub_future_for_channel(_ch)
            if _written:
                _did += 1
                if _app_shutting_down.wait(_background_scan_pace_seconds(_HUB_FUTURE_BETWEEN_CHANNELS_SECONDS)):
                    return
        if _did == 0 and _app_shutting_down.wait(_HUB_FUTURE_IDLE_SECONDS):
            return


_hub_rows_seen = {}
_hub_mode_since = {}
_hub_sync_lock = threading.Lock()


def _hub_channel_key(channel_key):
    return str(channel_key).zfill(2)


def _hub_channel_mode(channel_key):
    """The slot mode the hub labels a channel's rows with: its scheduling mode, or visualizer for a visualizer channel."""
    _info = db.channels_db.get(_hub_channel_key(channel_key), {}) if db is not None else {}
    return "visualizer" if _info.get("is_visualizer", False) else str(_info.get("scheduling_mode", "random_slots"))


def _hub_bundles_for(channel, raw_tracks):
    """The series and movie bundles of a channel's active files, or None when they cannot be worked out, so a row is then saved without a bundle."""
    if not raw_tracks:
        return None
    try:
        return media.bundles_of_tracks(raw_tracks)
    except Exception as _e:
        _log_warn_throttled("hub_bundles_" + str(channel), "[HUB SCHEDULE] ch%s: could not work out the bundles for the round number: %s", channel, _e)
        return None


_hub_row_sync_pending = {}
_hub_row_sync_lock = threading.Lock()
_hub_row_sync_wake = threading.Event()
_hub_row_sync_thread = None


def _request_hub_row_sync(channel_key, block_key, timeline, target_show, position_in_playlist, bundle_tracks=None, clock_shift_seconds=0.0):
    """Hands the hub row save for a block to the HubRowSync thread with the moment it was asked for; a newer request for the same channel replaces one not saved yet."""
    # WARNING: saving a block's rows took about 0.3 s per save on the thread that draws the screen (owner log 2026-11-01 22:03:16, a 1448 ms freeze tuning to ch09); it runs on its own thread and goes through the governor's gate, so it waits while a channel is being tuned.
    global _hub_row_sync_thread
    _now_epoch = broadcast_clock.now().timestamp()
    with _hub_row_sync_lock:
        _hub_row_sync_pending[_hub_channel_key(channel_key)] = (
            channel_key, block_key, timeline, target_show, position_in_playlist, bundle_tracks, clock_shift_seconds, _now_epoch)
        if _hub_row_sync_thread is None or not _hub_row_sync_thread.is_alive():
            _hub_row_sync_thread = threading.Thread(target=_hub_row_sync_worker, daemon=True, name="HubRowSync")
            _hub_row_sync_thread.start()
    _hub_row_sync_wake.set()


def _hub_row_sync_worker():
    """Saves the requested hub rows one channel at a time, each inside the governor's gate."""
    while not _app_shutting_down.is_set():
        _hub_row_sync_wake.wait(1.0)
        _hub_row_sync_wake.clear()
        while True:
            with _hub_row_sync_lock:
                if not _hub_row_sync_pending:
                    break
                _channel = next(iter(_hub_row_sync_pending))
                _args = _hub_row_sync_pending.pop(_channel)
            try:
                if performance_governor is None:
                    _sync_hub_rows_for_block(*_args[:7], now_epoch=_args[7])
                else:
                    with performance_governor.gate("hub_rows", label="ch%s" % _channel):
                        _sync_hub_rows_for_block(*_args[:7], now_epoch=_args[7])
            except Exception as _hub_row_sync_error:
                _log_warn_throttled("hub_row_sync_" + _channel, "[HUB SCHEDULE] ch%s: the rows could not be saved: %s", _channel, _hub_row_sync_error)


def _sync_hub_rows_for_block(channel_key, block_key, timeline, target_show, position_in_playlist, bundle_tracks=None, clock_shift_seconds=0.0, now_epoch=None):
    """Keeps the hub's rows for the block in step with the clock: writes the planned rows, rewrites the planned ones when lengths change, opens a new set of rows when the block was rebuilt with other files, run again, or its slot mode changed and held, marks what has passed as aired and what is on now as airing."""
    # WARNING: this only records; nothing reads the rows yet, so a failure here must never stop the scheduler, it acts only when the timeline, the airing entry, the block's start or the slot mode changed so it costs nothing on most calls, a second caller while one is writing leaves at once instead of waiting, and a slot mode that has not held for HUB_MODE_SWITCH_SETTLE_SECONDS changes nothing yet.
    if not _hub_sync_lock.acquire(blocking=False):
        return
    try:
        if not timeline or target_show is None:
            return
        _key = (_hub_channel_key(channel_key), str(block_key))
        _signature = tuple((e.get("path"), round(float(e.get("duration", 0) or 0), 1), bool(e.get("is_commercial"))) for e in timeline)
        _airing = next((i for i, e in enumerate(timeline) if e is target_show), None)
        if _airing is None:
            _airing = next((i for i, e in enumerate(timeline)
                            if e.get("path") == target_show.get("path") and e.get("start_time") == target_show.get("start_time")), None)
        if _airing is None:
            return
        _mode = _hub_channel_mode(channel_key)
        _mono = time.monotonic()
        _tracked = _hub_mode_since.get(_key[0])
        if _tracked is None:
            _hub_mode_since[_key[0]] = (_mode, _mono - _HUB_MODE_SWITCH_SETTLE_SECONDS)
        elif _tracked[0] != _mode:
            _hub_mode_since[_key[0]] = (_mode, _mono)
        _seen = _hub_rows_seen.get(_key)
        if _seen is not None and _seen[4] != _mode and _mono - _hub_mode_since[_key[0]][1] < _HUB_MODE_SWITCH_SETTLE_SECONDS:
            return
        _now_epoch = broadcast_clock.now().timestamp() if now_epoch is None else float(now_epoch)
        _clock_moment = _now_epoch + float(clock_shift_seconds or 0)
        _start_epoch = _clock_moment - float(position_in_playlist or 0)
        if (_seen is not None and _seen[0] == _signature and _seen[1] == _airing and _seen[4] == _mode
                and abs(_seen[2] - _start_epoch) <= _HUB_ROW_GENERATION_START_TOLERANCE_SECONDS):
            return
        import media_library as _ml
        _hub = _ml.shared_schedule_hub()
        if (_seen is None or _seen[0] != _signature or _seen[4] != _mode
                or abs(_seen[2] - _start_epoch) > _HUB_ROW_GENERATION_START_TOLERANCE_SECONDS):
            _bundles = _hub_bundles_for(_key[0], bundle_tracks)
            _slot, _written, _skipped, _opened = _hub.place_rows(
                _key[0], _key[1], media.schedule_rows_from_timeline(timeline, _start_epoch, _bundles),
                airing_position=_airing, now_epoch=_now_epoch, start_tolerance=_HUB_ROW_GENERATION_START_TOLERANCE_SECONDS, mode=_mode)
            if _opened and _seen is not None and _seen[4] != _mode:
                log.info("[HUB SCHEDULE] ch%s block=%s: the slot mode changed from %s to %s and held; the old set of rows is put aside with its unaired rows kept, the new rows go to %s, %d planned rows written",
                         _key[0], _key[1], _seen[4], _mode, _slot, _written)
            elif _opened:
                log.info("[HUB SCHEDULE] ch%s block=%s: the block was rebuilt with other files or started again; its rows now go to %s, %d planned rows written, the earlier rows stay as history", _key[0], _key[1], _slot, _written)
            if _opened:
                _first_unmarked = _airing
            else:
                log.info("[HUB SCHEDULE] ch%s block=%s: %d planned rows written, %d kept as history", _key[0], _key[1], _written, _skipped)
                _first_unmarked = 0
        else:
            _slot = _seen[3]
            _first_unmarked = _seen[1]
        for _position in range(_first_unmarked, _airing):
            _hub.mark(_key[0], _slot, _position, "aired")
        _hub.mark(_key[0], _slot, _airing, "airing")
        _left_airing, _left_planned = _hub.close_passed_rows(_key[0], _now_epoch, _slot, _airing)
        if _left_airing or _left_planned:
            log.info("[HUB SCHEDULE] ch%s block=%s: the clock has left %d row(s) airing and %d planned row(s) of earlier blocks behind (block change, or the app was off); they are marked aired",
                     _key[0], _key[1], _left_airing, _left_planned)
        _hub_rows_seen[_key] = (_signature, _airing, _start_epoch, _slot, _mode)
        _compare_hub_clock_answer(_hub, _key[0], _key[1], _clock_moment, target_show)
        if len(_hub_rows_seen) > 60:
            for _old_key in list(_hub_rows_seen)[:-40]:
                _hub_rows_seen.pop(_old_key, None)
    except Exception as _e:
        _log_warn_throttled("hub_schedule_sync", "[HUB SCHEDULE] ch%s block=%s: could not update the hub's rows: %s", channel_key, block_key, _e)
    finally:
        _hub_sync_lock.release()


def _compare_hub_clock_answer(hub, channel, block_key, epoch, target_show):
    """Asks the hub what is on this channel at this clock moment and compares it with the scheduler's pick; a disagreement is written to the log and nothing on air changes."""
    # WARNING: this only reports; it must never change what airs or stop the scheduler, and it runs only when the airing entry or the timeline changed.
    try:
        _path = str(target_show.get("path") or "")
        _kind = "commercial" if target_show.get("is_commercial") else "episode"

        def _same(_row):
            return _row is not None and _row["path"] == _path and _row["kind"] == _kind

        _row = hub.at(channel, epoch)
        if _same(_row) or _same(hub.at(channel, epoch - _HUB_CLOCK_COMPARE_GRACE_SECONDS)) or _same(hub.at(channel, epoch + _HUB_CLOCK_COMPARE_GRACE_SECONDS)):
            log.info("[HUB CLOCK] ch%s block=%s: the hub and the scheduler agree on %s", channel, block_key, os.path.basename(_path))
        elif _row is None:
            _log_warn_throttled("hub_clock_" + str(channel), "[HUB CLOCK] ch%s block=%s: the scheduler has %s on air and the hub has no row for this moment", channel, block_key, os.path.basename(_path))
        else:
            _log_warn_throttled(
                "hub_clock_" + str(channel),
                "[HUB CLOCK] ch%s block=%s: the scheduler has %s (%s) on air and the hub says %s (%s), slot=%s position=%s starts=%.0f length=%.0f state=%s",
                channel, block_key, os.path.basename(_path), _kind, os.path.basename(str(_row["path"])), _row["kind"],
                _row["slot_key"], _row["position"], float(_row["planned_start"] or 0), float(_row["used_length"] or 0), _row["state"])
    except Exception as _e:
        _log_warn_throttled("hub_clock_compare", "[HUB CLOCK] ch%s block=%s: could not ask the hub what is on air: %s", channel, block_key, _e)


_hub_airing_memo = {}


def _hub_airing_entry(channel_key, block_key, timeline, target_show, position_in_playlist, clock_shift_seconds=0.0):
    """Asks the hub which row covers the clock moment of the scheduler's pick and returns the block timeline entry that row names, or None when the hub has no row for that moment or its row does not name the entry the clock position falls in."""
    # WARNING: this only reads; whenever it returns None the caller keeps the timeline's own pick, so a failure here must never stop the scheduler or change what airs (R16, R18); the hub is asked only when the airing entry or the timeline changed, or once per HUB_AIRING_LOOKUP_RETRY_SECONDS after a miss, so the library lock is not taken on every pass.
    try:
        if not timeline or target_show is None:
            return None
        _airing = next((i for i, e in enumerate(timeline) if e is target_show), None)
        if _airing is None:
            return None
        _key = (_hub_channel_key(channel_key), str(block_key))
        _signature = tuple((e.get("path"), round(float(e.get("duration", 0) or 0), 1), bool(e.get("is_commercial"))) for e in timeline)
        _memo = _hub_airing_memo.get(_key)
        _mono = time.monotonic()
        if _memo is not None and _memo[0] == _signature and _memo[1] == _airing:
            if _memo[2]:
                return timeline[_airing]
            if _mono - _memo[3] < _HUB_AIRING_LOOKUP_RETRY_SECONDS:
                return None
        import media_library as _ml
        _epoch = broadcast_clock.now().timestamp() + float(clock_shift_seconds or 0)
        _row = _ml.shared_schedule_hub().at(_key[0], _epoch)
        _entry = None
        if _row is not None and str(_row["slot_key"]).split("#g")[0] == _key[1]:
            _kind = "commercial" if timeline[_airing].get("is_commercial") else "episode"
            _index = int(_row["position"])
            if 0 <= _index < len(timeline) and _index == _airing and _row["path"] == timeline[_airing].get("path") and _row["kind"] == _kind:
                _entry = timeline[_airing]
        _hub_airing_memo[_key] = (_signature, _airing, _entry is not None, _mono)
        if len(_hub_airing_memo) > 60:
            for _old_key in list(_hub_airing_memo)[:-40]:
                _hub_airing_memo.pop(_old_key, None)
        return _entry
    except Exception as _e:
        _log_warn_throttled("hub_airing_entry", "[HUB CLOCK] ch%s block=%s: could not ask the hub for the airing entry, the timeline's pick stays: %s", channel_key, block_key, _e)
        return None


def _write_prebuilt_block_to_hub(channel_key, block_key, lineup, raw_tracks=None):
    """Records the show order the Add Media prebuild dealt for a block that is not on air yet, as planned rows with no start times."""
    # WARNING: when the block goes live _sync_hub_rows_for_block writes the full timeline over these planned rows; nothing reads them yet, so a failure here must never stop Add Media.
    try:
        import media_library as _ml
        _slot, _written, _skipped, _opened = _ml.shared_schedule_hub().place_rows(
            _hub_channel_key(channel_key), str(block_key), media.schedule_rows_from_lineup(lineup, _hub_bundles_for(_hub_channel_key(channel_key), raw_tracks)),
            now_epoch=broadcast_clock.now().timestamp(), start_tolerance=_HUB_ROW_GENERATION_START_TOLERANCE_SECONDS,
            mode=_hub_channel_mode(channel_key))
        log.info("[HUB SCHEDULE] ch%s block=%s: Add Media prebuild recorded %d planned rows, %d kept as history", channel_key, block_key, _written, _skipped)
    except Exception as _e:
        _log_warn_throttled("hub_schedule_prebuild", "[HUB SCHEDULE] ch%s block=%s: could not record the Add Media prebuild: %s", channel_key, block_key, _e)


def _mark_hub_row_static(channel_key, file_path):
    """Marks the hub's airing row for a file that would not play as a Static slot."""
    try:
        import media_library as _ml
        if _ml.shared_schedule_hub().mark_airing_static(_hub_channel_key(channel_key), file_path):
            log.info("[HUB SCHEDULE] ch%s: the slot for %s went to Static and is marked static", channel_key, os.path.basename(str(file_path)))
    except Exception as _e:
        _log_warn_throttled("hub_schedule_static", "[HUB SCHEDULE] ch%s: could not mark the Static slot: %s", channel_key, _e)


def _hub_playback_guard(channel_key):
    """A small value that changes when what a station airs is changed under it (its mode, block on air, its files); remembered facts are only trusted while it still matches."""
    _info = db.channels_db.get(channel_key, {}) if db is not None else {}
    _log = _info.get("playback_log", {}) or {}
    return (broadcast_clock.now().toordinal(), _info.get("scheduling_mode", "random_slots"), bool(_info.get("is_visualizer", False)), _log.get("sched_block_key"),
            _log.get("sched_cycle_boundary"), sum(len(v or []) for v in (_info.get("schedules", {}) or {}).values()),
            len(_info.get("broken_files", []) or []))


def calculate_slotted_playback_state(channel_id, snap_internal_advance=False, trust_recent_stop=False,
                                     allow_cold_anchor_resume=False):
    """What a station is airing now. Everything that wants to know (channel change, previews, the watchdog) asks here; the answer comes from the hub's record of the show on air with the seek moved forward by the clock. When the hub has nothing valid for this moment it reaches out to the scheduler, which stays the writer, and remembers the reply."""
    # WARNING: playback talks to the hub and the hub talks to the scheduler; a Static answer is never remembered, and an advance, recent-stop or cold-anchor request always goes to the scheduler because it moves saved positions.
    _key = str(channel_id).zfill(2)
    _plain = not (snap_internal_advance or trust_recent_stop or allow_cold_anchor_resume)
    _hub = None
    _epoch = None
    _guard = None
    try:
        import media_library as _ml
        _hub = _ml.shared_schedule_hub()
        _epoch = broadcast_clock.now().timestamp()
        _guard = _hub_playback_guard(_key)
        if _plain:
            _facts = _hub.show_facts(_key, _epoch, _guard)
            if _facts is not None:
                return _facts
            _hub_miss_log_once(_key)
    except Exception as _e:
        _log_warn_throttled("hub_playback_door_" + _key, "[HUB PLAYBACK] ch%s: the hub could not answer, asking the scheduler: %s", _key, _e)
        _hub = None
    _state = _scheduler_playback_state(channel_id, snap_internal_advance, trust_recent_stop, allow_cold_anchor_resume)
    _hub_remember_state(_hub, _key, _state, _epoch)
    return _state


def _hub_remember_state(hub, channel_key, state, epoch):
    """Keeps the scheduler's answer for the show on air in the hub; a Static or empty answer is forgotten instead."""
    try:
        if hub is not None and isinstance(state, dict) and state.get("mode") in ("Video", "Commercial", "Visualizer") and state.get("file") and float(state.get("duration", 0) or 0) > 0:
            hub.remember_show_facts(channel_key, state, epoch, _hub_playback_guard(channel_key))
        elif hub is not None:
            hub.forget_show_facts(channel_key)
    except Exception as _e:
        _log_warn_throttled("hub_playback_remember_" + channel_key, "[HUB PLAYBACK] ch%s: could not remember the show on air: %s", channel_key, _e)


def _hub_writer_step(channel_key):
    """One bookkeeping pass for one station: the scheduler works out what is airing (marking rows, closing passed ones, moving saved positions) and the hub keeps the answer."""
    import media_library as _ml
    _epoch = broadcast_clock.now().timestamp()
    _state = _scheduler_playback_state(channel_key)
    _hub_writer_checked[channel_key] = time.monotonic()
    _hub_remember_state(_ml.shared_schedule_hub(), channel_key, _state, _epoch)


_hub_writer_checked = {}
# WARNING: the fallback number below must match HUB_WRITER_STATIC_RECHECK_SECONDS in performance_governor.py; it is used only when that module fails to import.
_HUB_WRITER_STATIC_RECHECK_SECONDS = performance_governor.HUB_WRITER_STATIC_RECHECK_SECONDS if performance_governor is not None else 60.0


def _hub_writer_next_stale(channels, after_index):
    """The next channel, in turn after the one last done, whose kept record in the hub is missing or no longer valid; a channel that already has the right record is skipped, and None means every channel is up to date."""
    import media_library as _ml
    _hub = _ml.shared_schedule_hub()
    _epoch = broadcast_clock.now().timestamp()
    for _step in range(1, len(channels) + 1):
        _ch = channels[(after_index + _step) % len(channels)]
        if not db.channels_db.get(_ch):
            continue
        if time.monotonic() - _hub_writer_checked.get(_ch, -1e9) < _HUB_WRITER_STATIC_RECHECK_SECONDS:
            continue
        if _hub.show_facts(_ch, _epoch, _hub_playback_guard(_ch)) is None:
            return _ch
    return None


def _hub_writer_worker():
    """Background thread: the scheduler is the hub's writer. The channel on screen gets a pass every HUB_WRITER_WATCHED_SECONDS (at once when its show is about to end), every other channel one pass in turn every HUB_WRITER_OTHER_CHANNEL_SECONDS, and the other channels give way to the governor."""
    # WARNING: readers (playback, previews, the guide) only read what this writes; the channel on screen is never held back by the governor because its reads depend on it.
    if db is None:
        return
    _turn = 0
    _last_other = 0.0
    while not _app_shutting_down.wait(_HUB_WRITER_WATCHED_SECONDS):
        try:
            _watched = str(app_state.get("current_channel", "")).zfill(2)
            if _watched.isdigit() and db.channels_db.get(_watched):
                _hub_writer_step(_watched)
            _now = time.monotonic()
            if _now - _last_other >= _HUB_WRITER_OTHER_CHANNEL_SECONDS / 40.0 and not _python_heavy_should_pause():
                _last_other = _now
                _channels = [str(i).zfill(2) for i in range(5, 45) if str(i).zfill(2) != _watched]
                _channel = _hub_writer_next_stale(_channels, _turn)
                if _channel is not None:
                    _turn = _channels.index(_channel)
                    with _background_activity("hub_writer"):
                        _hub_writer_step(_channel)
        except Exception as _e:
            _log_warn_throttled("hub_writer_worker", "[HUB WRITER] a bookkeeping pass failed, trying again next beat: %s", _e)


_hub_miss_logged = {}


def _hub_miss_log_once(channel_key):
    """Notes in the log, at most once a minute per station, that the hub had no valid record and the scheduler is being asked."""
    _now = time.monotonic()
    if _now - _hub_miss_logged.get(channel_key, -1e9) >= 60.0:
        _hub_miss_logged[channel_key] = _now
        log.info("[HUB MISS] ch%s: the hub had no valid record for this moment, asking the scheduler and keeping its answer", channel_key)


@_sched_rebuild_guard
def _scheduler_playback_state(channel_id, snap_internal_advance=False, trust_recent_stop=False,
                              allow_cold_anchor_resume=False):
      target_clean_key = str(channel_id).zfill(2)
      ch_info = db.channels_db.get(target_clean_key, {}) if db is not None else {}

      if not ch_info or not ch_info.get("active", True):
          if not ch_info:
              if target_clean_key in ("03", "04"):
                  return {
                      "mode": "Static", "file": "", "seek": 0,
                      "reason": "channel_inactive",
                      "reason_detail": f"CH{target_clean_key}: reserved channel, no schedule",
                  }
              log.warning(
                  "[SCHEDULER] ch%s returned Static: no channel config found "
                  "for this key (db_is_none=%s)", target_clean_key, db is None,
              )
              return {
                  "mode": "Static", "file": "", "seek": 0,
                  "reason": "channel_config_missing",
                  "reason_detail": f"CH{target_clean_key}: no channel configuration found",
              }
          log.info(
              "[SCHEDULER] ch%s is inactive (disabled) -- Static is expected.",
              target_clean_key,
          )
          return {
              "mode": "Static", "file": "", "seek": 0,
              "reason": "channel_inactive",
              "reason_detail": f"CH{target_clean_key}: channel is disabled",
          }

      playback_log = ch_info.setdefault("playback_log", {})

      now = broadcast_clock.now().replace(tzinfo=None)
      today = now.date()
      current_seconds = (now.hour * 3600 + now.minute * 60 + now.second
                          + now.microsecond / 1_000_000.0)

      _deferred_anchor_state = None
      anchor = ch_info.get("playback_anchor", {})
      _anchor_is_live_video = False
      if anchor and anchor.get("file"):
          try:
              if (str(app_state.get("_live_playback_channel", "")).zfill(2) == target_clean_key
                      and app_state.get("is_playing_video", False)
                      and vlc is not None
                      and vlc_engine is not None
                      and getattr(vlc_engine, "player", None) is not None):
                  _astate = vlc_engine.player.get_state()
                  _state_ok = _astate not in (vlc.State.Ended, vlc.State.Error) and (
                      _astate != vlc.State.Stopped or trust_recent_stop)
                  if _state_ok:
                      _amedia = vlc_engine.player.get_media()
                      if _amedia:
                          from urllib.parse import unquote as _unquote_a
                          _aloaded = os.path.normpath(_unquote_a(_amedia.get_mrl().replace("file:///", ""))).lower()
                          _afile   = os.path.normpath(str(anchor.get("file", ""))).lower()
                          _anchor_is_live_video = (_aloaded == _afile)
                      else:
                          pass
                  else:
                      pass
          except Exception as e:
              log.warning("calculate_slotted_playback_state: anchor live-match check failed: %s", e)

      if allow_cold_anchor_resume and anchor and anchor.get("file") and not _anchor_is_live_video:
          log.info("BOOT: ch%s -- rejoining live wall-clock schedule (no personal resume; "
                    "this is a broadcast emulator, not a DVR)", target_clean_key)

      _anchor_trusted = bool(
          anchor and anchor.get("file") and _cached_path_exists(str(anchor.get("file", "")))
          and _anchor_is_live_video
      )
      if _anchor_trusted and not _file_in_channel_schedule(target_clean_key, anchor.get("file")):
          _log_info_throttled("anchor_unscheduled:" + target_clean_key,
                              "[ANCHOR] ch%s ignoring saved anchor: %s is not in this channel's schedule",
                              target_clean_key, os.path.basename(str(anchor.get("file", ""))))
          ch_info["playback_anchor"] = {}
          _anchor_trusted = False
      if _anchor_trusted:
          wall_start = anchor.get("wall_start", 0)
          seek_off   = anchor.get("seek_offset", 0)
          duration   = anchor.get("duration", 1800)
          elapsed    = current_seconds - wall_start
          if elapsed < 0:
              elapsed += 86400
          _slot_start = anchor.get("slot_start_seek", 0)
          remaining = duration - (seek_off - _slot_start) - elapsed
          if remaining > 0:
              _anchor_state = {
                  "mode":             anchor.get("mode", "Video"),
                  "file":             anchor["file"],
                  "seek":             seek_off + elapsed,
                  "duration":         duration,
                  "block":            anchor.get("block", "Morning"),
                  "seek_slot_offset": anchor.get("slot_start_seek", 0),
                  "interior_cut":     bool(anchor.get("interior_cut", False)),
              }
              _pending = ch_info.get("_sched_debounce_pending_since")
              if (_pending is not None
                      and not ch_info.get("is_visualizer", False)
                      and ch_info.get("scheduling_mode", "random_slots") != "marathon"
                      and pygame.time.get_ticks() - _pending >= _SCHEDULE_MODE_COMMIT_HOLD_MS):
                  # WARNING: do not rebuild the entire schedule from the render loop.
                  ch_info["_sched_debounce_pending_since"] = None
              return _anchor_state
          else:
              _is_live_ch = (str(app_state.get("_live_playback_channel", "")).zfill(2) == target_clean_key
                             and app_state.get("is_playing_video", False))
              _still_playing_live = False
              _part_ends_at_cut = bool(anchor.get("interior_cut", False))
              if _part_ends_at_cut and _is_live_ch:
                  # WARNING: a part that ends at an interior cut ends on the clock, not when VLC stops; holding it while VLC plays on skips the break and puts the screen ahead of the schedule (L7, owner 2026-11-02: "always on schedule is the most important").
                  _log_info_throttled(
                      "interior_cut_end:%s:%s" % (target_clean_key, anchor.get("anchor_written_at")),
                      "[INTERIOR-BREAK] ch%s: %s reached the planned end of its part (%.1fs past it); the clock's next item airs now",
                      target_clean_key, os.path.basename(str(anchor.get("file", ""))), -remaining)
              if (_is_live_ch and not _part_ends_at_cut
                      and vlc_engine is not None and getattr(vlc_engine, "player", None) is not None):
                  try:
                      _vstate = vlc_engine.player.get_state()
                      _state_ok2 = vlc is not None and _vstate not in (vlc.State.Ended, vlc.State.Error) and (
                          _vstate != vlc.State.Stopped or trust_recent_stop)
                      if _state_ok2:
                          _media = vlc_engine.player.get_media()
                          if _media:
                              from urllib.parse import unquote as _unquote
                              _loaded_p = os.path.normpath(_unquote(_media.get_mrl().replace("file:///", ""))).lower()
                              _anchor_p = os.path.normpath(str(anchor["file"])).lower()
                              if _loaded_p == _anchor_p:
                                  _still_playing_live = True
                  except Exception as e:
                      log.warning("calculate_slotted_playback_state: live-playback verification failed: %s", e)
              if _still_playing_live:
                  return {
                      "mode":             anchor.get("mode", "Video"),
                      "file":             anchor["file"],
                      "seek":             seek_off + elapsed,
                      "duration":         duration,
                      "block":            anchor.get("block", "Morning"),
                      "seek_slot_offset": anchor.get("slot_start_seek", 0),
                      "interior_cut":     bool(anchor.get("interior_cut", False)),
                  }

      if ch_info.get("is_visualizer", False):
          # WARNING: the schedule is the only authority on what plays and where; no mixer state, skip, or resume position may feed back into it.
          track_list, total_playlist_seconds, _lineup_origin = _visualizer_frozen_lineup(target_clean_key, ch_info, now)
          if not track_list or total_playlist_seconds <= 0:
              _vis_stack = ch_info.get("schedules", {}).get("Music Tracks", [])
              if not _vis_stack:
                  return {
                      "mode": "Static", "file": "", "seek": 0,
                      "reason": "no_media_scheduled",
                  }
              _vis_unseekable, _vis_unseekable_exts = _visualizer_admission_inputs()
              _vis_pending = media.pending_visualizer_paths(
                  _vis_stack,
                  _vis_unseekable, _vis_unseekable_exts)
              if _vis_pending:
                  return {
                      "mode": "Static", "file": "", "seek": 0,
                      "reason": "visualizer_scanning",
                      "reason_detail": f"CH{target_clean_key}: measuring song lengths, {len(_vis_pending)} song(s) waiting",
                  }
              return {
                  "mode": "Static", "file": "", "seek": 0,
                  "reason": "visualizer_no_admitted_media",
                  "reason_detail": f"CH{target_clean_key}: no song can play (unplayable, silent or not seekable)",
              }

          position_in_playlist = (current_seconds - _lineup_origin) % total_playlist_seconds

          elapsed = 0
          for track in track_list:
              if elapsed + track["duration"] > position_in_playlist:
                  return {
                      "mode": "Visualizer",
                      "file": track["path"],
                      "seek": position_in_playlist - elapsed,
                      "duration": track["duration"],
                  }
              elapsed += track["duration"]

          return {"mode": "Visualizer", "file": track_list[0]["path"], "seek": 0, "duration": track_list[0]["duration"]}

      _holiday_forced = media.holiday_forced_key_for_channel(db.config, target_clean_key) if db is not None else ""

      def _get_holiday_key(d):
          """Return holiday key if the day falls in a holiday window, or is today and forced on, else None."""
          return media.holiday_key_for_date(d, _holiday_forced, today)

      holiday_key = _get_holiday_key(today)
      holiday_schedules = ch_info.get("holiday_schedules", {})
      _ch_is_marathon = ch_info.get("scheduling_mode", "random_slots") == "marathon"
      # WARNING: a normal-day show that crosses midnight owns the broadcast until it ends; the holiday branch must not replace it.
      _normal_overrun_end = media.active_block_overrun_end(
          playback_log, today.toordinal() * 86400)
      _normal_overrun_active = bool(
          _normal_overrun_end is not None
          and _normal_overrun_end > today.toordinal() * 86400 + current_seconds
      )

      if (not _normal_overrun_active and not _ch_is_marathon
              and holiday_key and holiday_key in holiday_schedules and holiday_schedules[holiday_key]):
          h_entries = holiday_schedules[holiday_key]

          h_raw_tracks = build_raw_tracks(h_entries, _cached_path_exists)
          h_pending_tracks = build_pending_tracks(h_entries, _cached_path_exists)
          if h_pending_tracks:
              _priority_probe_pending_schedule(
                  target_clean_key, "holiday_schedules", holiday_key, h_pending_tracks
              )
              h_raw_tracks = build_raw_tracks(h_entries, _cached_path_exists)
              h_pending_tracks = build_pending_tracks(h_entries, _cached_path_exists)
              if not h_raw_tracks and h_pending_tracks:
                  return {
                      "mode": "Static", "file": "", "seek": 0,
                      "reason": "first_file_scanning",
                      "reason_detail": (
                          f"CH{target_clean_key} holiday {holiday_key}: waiting for the first file's length; "
                          f"{len(h_pending_tracks)} scheduled file(s) are scanned one at a time"
                      ),
                  }


          if h_raw_tracks:
              h_log = ch_info.setdefault("holiday_playback_log", {}).setdefault(holiday_key, {})
              h_show_pos = h_log.setdefault("show_pos", {})

              h_block_key = f"{now.year}_{now.timetuple().tm_yday}_Holiday_{holiday_key}"
              _holiday_overrun_end = None
              if h_block_key not in (playback_log.get("block_anchors") or {}):
                  _holiday_overrun_end = media.active_block_overrun_end(
                      playback_log, today.toordinal() * 86400)
              h_block_start = _get_or_set_block_anchor(
                  ch_info, h_block_key, current_seconds, real_start_seconds=0,
                  overrun_end_seconds=(
                      _holiday_overrun_end - today.toordinal() * 86400
                      if _holiday_overrun_end is not None else None),
                  exact_start=bool(_holiday_forced) and media.holiday_force_started_today(db.config, today))
              h_seconds_into_block = current_seconds - h_block_start
              if h_seconds_into_block < 0:
                  h_seconds_into_block += 86400

              h_commercials_enabled  = ch_info.get("commercials_enabled", False)
              h_commercial_items     = ch_info.get("schedules", {}).get("Commercials", [])

              h_commercial_tracks = []
              if h_commercials_enabled and h_commercial_items:
                  h_commercial_tracks = build_commercial_tracks(h_commercial_items, _cached_path_exists)

              _pair_thresh_sec_h = max(0, ch_info.get("pair_threshold_minutes", 15)) * 60

              h_day_seed = (now.year * 1000 + now.timetuple().tm_yday + int(target_clean_key)
                            + 9000 + (sum(ord(c) for c in holiday_key) % 1000))
              _h_order_seed = _start_order_seed(ch_info, 9000 + (sum(ord(c) for c in holiday_key) % 1000))

              _prev_h_block_key = h_log.get("block_key")
              h_is_new_block = _prev_h_block_key != h_block_key
              if not h_is_new_block and not media.holiday_cycle_record_ok(h_log, h_block_key):
                  h_is_new_block = True
              h_block_end_offset = 86400 - h_block_start
              _h_reflavor = False
              _h_advanced = False
              _h_durations_stale_raw = (not h_is_new_block) and _cached_lineup_durations_stale(
                      h_log.get("cached_durations", {}),
                      frozen_aired_paths=set(h_log.get("frozen_aired_paths", [])))
              if _h_durations_stale_raw:
                  _h_stale_since = h_log.get("_durations_stale_since")
                  if _h_stale_since is None:
                      h_log["_durations_stale_since"] = pygame.time.get_ticks()
                  elif pygame.time.get_ticks() - _h_stale_since >= 5000:
                      h_log["_durations_stale_since"] = None
                      _h_reflavor = True
              else:
                  h_log["_durations_stale_since"] = None

              def _h_note_cut(_cycle):
                  if _cycle["how"] == "unmapped":
                      log.warning("[SCHEDULER] ch%s holiday %s: the cycle's entries could not be tied to its timeline; positions stay as the whole cycle left them",
                                  target_clean_key, holiday_key)

              if h_is_new_block or not h_log.get("timeline"):
                  _missed_h_seeds = _missed_block_day_seeds(
                      _prev_h_block_key, f"Holiday_{holiday_key}", target_clean_key,
                      9000 + (sum(ord(c) for c in holiday_key) % 1000), now)
                  if _missed_h_seeds:
                      _fwd_h_show_pos, _fwd_h_order, _h_catchup_report = fast_forward_show_pos(
                          h_raw_tracks, "random_slots", h_show_pos, _missed_h_seeds,
                          pair_threshold_seconds=_pair_thresh_sec_h,
                          episode_order_mode="random",
                          fixed_show_order=h_log.get("show_order"),
                           block_duration_seconds=86400,
                           channel_id=target_clean_key,
                          order_seed=_h_order_seed,
                          pending_tracks=h_pending_tracks,
                      )
                      h_show_pos.clear()
                      h_show_pos.update(_fwd_h_show_pos)
                      h_log["show_pos"] = h_show_pos
                      h_log["last_gap_catchup"] = {
                          "channel": target_clean_key,
                          "holiday": holiday_key,
                          "missed_occurrences": len(_missed_h_seeds),
                          "caught_up_at": now.isoformat(),
                          "shows": _h_catchup_report,
                      }
                      log.info(
                          "[CATCH-UP] ch%s holiday=%s was offline across %d missed "
                          "occurrence(s) -- fast-forwarded show_pos: %s",
                          target_clean_key, holiday_key, len(_missed_h_seeds), _h_catchup_report,
                      )
                  h_cycle = media.build_holiday_cycle(
                      h_raw_tracks, ch_info, h_commercial_tracks, h_show_pos, h_log.get("commercial_pos"),
                      h_day_seed, target_clean_key, h_log.get("show_order"), _h_order_seed,
                      h_block_end_offset, pending_tracks=h_pending_tracks)
                  _h_note_cut(h_cycle)
                  media.store_holiday_cycle(h_log, h_cycle, h_block_key, 0, 0)
                  h_log["cached_durations"] = _snapshot_track_durations(h_cycle["lineup"])
                  h_timeline, h_total = h_cycle["timeline"], h_cycle["total"]
                  try: db.save_settings_async()
                  except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist holiday rotation: %s", e)
              else:
                  h_timeline = h_log.get("timeline", [])
                  h_total = h_log.get("total_duration", 0)

              if h_timeline and h_total > 0:
                  h_cyc_boundary = float(h_log.get("cycle_boundary") or 0)
                  _h_cyc_index = int(h_log.get("cycle_index") or 0)
                  _h_guard = 0
                  while h_total > 0 and h_seconds_into_block >= h_cyc_boundary + h_total and _h_guard < 500:
                      _h_guard += 1
                      _h_next_boundary = h_cyc_boundary + h_total
                      h_cycle = media.build_holiday_cycle(
                          h_raw_tracks, ch_info, h_commercial_tracks, h_log.get("show_pos", {}),
                          h_log.get("commercial_pos"), h_day_seed + _h_cyc_index + 1, target_clean_key,
                          h_log.get("show_order"), _h_order_seed, h_block_end_offset - _h_next_boundary,
                          pending_tracks=h_pending_tracks)
                      if not h_cycle["timeline"] or h_cycle["total"] <= 0:
                          log.warning("[SCHEDULER] ch%s holiday %s: the next cycle came back empty; the last cycle is kept",
                                      target_clean_key, holiday_key)
                          break
                      _h_note_cut(h_cycle)
                      h_cyc_boundary = _h_next_boundary
                      _h_cyc_index += 1
                      media.store_holiday_cycle(h_log, h_cycle, h_block_key, h_cyc_boundary, _h_cyc_index)
                      h_log["cached_durations"] = _snapshot_track_durations(h_cycle["lineup"])
                      h_timeline, h_total = h_cycle["timeline"], h_cycle["total"]
                      _h_advanced = True
                  if _h_advanced:
                      try: db.save_settings_async()
                      except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist holiday cycle advance: %s", e)
                  elif _h_reflavor:
                      h_cycle = media.reflavor_holiday_cycle(
                          h_raw_tracks, ch_info, h_commercial_tracks, h_log, h_seconds_into_block - h_cyc_boundary,
                          h_day_seed + _h_cyc_index, target_clean_key, _h_order_seed,
                          h_block_end_offset - h_cyc_boundary, pending_tracks=h_pending_tracks)
                      if h_cycle is not None and h_cycle["timeline"] and h_cycle["total"] > 0:
                          _h_note_cut(h_cycle)
                          media.store_holiday_cycle(h_log, h_cycle, h_block_key, h_cyc_boundary, _h_cyc_index)
                          h_log["cached_durations"] = _snapshot_track_durations(h_cycle["lineup"])
                          h_timeline, h_total = h_cycle["timeline"], h_cycle["total"]
                      else:
                          log.warning("[SCHEDULER] ch%s holiday %s: durations changed but the entries already aired could not be tied to their shows; the timeline stays as it is",
                                      target_clean_key, holiday_key)
                          h_log["cached_durations"] = _snapshot_track_durations(h_log.get("cycle_lineup") or [])
                      try: db.save_settings_async()
                      except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist holiday re-flavor: %s", e)

                  h_pos = h_seconds_into_block - h_cyc_boundary

                  if h_timeline:
                      try:
                          _probe_block_timeline_cache[target_clean_key] = {
                              "block_key": h_block_key,
                              "items": [
                                  {"path": _hte.get("path", ""), "is_commercial": bool(_hte.get("is_commercial")),
                                   "start_time": _hte.get("start_time")}
                                  for _hte in h_timeline if isinstance(_hte, dict) and _hte.get("path")
                              ],
                          }
                      except Exception as _htl_cache_err:
                          log.warning("calculate_slotted_playback_state: failed to cache holiday probe timeline for ch%s: %s",
                                      target_clean_key, _htl_cache_err)

                  h_target, h_pos = _apply_repeat_guard(
                      target_clean_key, playback_log, "Holiday",
                      h_timeline, h_total, h_pos, now)

                  if h_target is not None:
                      h_start = h_target.get("start_time", 0)
                      h_dur = h_target.get("duration", 0)
                      h_mode = "Commercial" if h_target.get("is_commercial") else "Video"
                      return {"mode": h_mode, "file": h_target.get("path", ""),
                              "seek": h_pos - h_start, "duration": h_dur, "block": "Holiday",
                              "interior_cut": bool(h_target.get("interior_cut", False))}
                  h_first = h_timeline[0]
                  h_first_mode = "Commercial" if h_first.get("is_commercial") else "Video"
                  return {"mode": h_first_mode, "file": h_first.get("path", ""), "seek": 0,
                          "duration": h_first.get("duration", 0), "block": "Holiday",
                          "interior_cut": bool(h_first.get("interior_cut", False))}

      _marathon_mode = (ch_info.get("scheduling_mode", "random_slots") == "marathon")
      _full_day_mode = (not _marathon_mode) and (ch_info.get("block_mode", "full_day") == "full_day")
      _six_block_mode = (not _marathon_mode) and (ch_info.get("block_mode", "full_day") == "six_block")
      if _marathon_mode:
          current_block = "Marathon"
          block_start_seconds = 0
          block_duration_seconds = block_length_seconds(current_block)
          epoch_now = now.toordinal() * 86400 + current_seconds
          anchor = ch_info.get("marathon_anchor_epoch")
          if not anchor:
              anchor = now.toordinal() * 86400 + (current_seconds // 1800) * 1800
              ch_info["marathon_anchor_epoch"] = anchor
              try: db.save_settings()
              except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist marathon_anchor_epoch: %s", e)
          seconds_into_block = epoch_now - anchor
      elif _full_day_mode:
          current_block = "Full Day"
          _this_block_key = block_key_for(now, current_block)
          block_start_seconds = _get_or_set_block_anchor(
              ch_info, _this_block_key, current_seconds, real_start_seconds=0,
              overrun_end_seconds=_block_overrun_anchor(
                  ch_info, target_clean_key, _this_block_key, now, current_seconds, current_seconds, 0,
                  lambda _d: bool(_get_holiday_key(_d) and holiday_schedules.get(_get_holiday_key(_d)))))
          seconds_into_block = current_seconds - block_start_seconds
          if seconds_into_block < 0 and media.aired_entry_at(ch_info.get("playback_log", {}), now.toordinal(), current_seconds) is None:
              seconds_into_block += 86400
          block_duration_seconds = block_length_seconds(current_block)
      elif _six_block_mode:
          current_hour = now.hour
          current_block, block_start_hour, _block_end_hour = SIX_HOUR_BLOCKS[current_hour // 4]
      else:
          current_hour = now.hour
          if 4 <= current_hour < 12:
              current_block = "Morning"
              block_start_hour = 4
          elif 12 <= current_hour < 20:
              current_block = "Evening"
              block_start_hour = 12
          else:
              current_block = "Night"
              block_start_hour = 20

      if _marathon_mode:
          pass
      elif _full_day_mode:
          pass
      elif current_block == "Night" and current_hour < 4:
          _this_block_key = block_key_for(now, current_block)
          _blk_clock = 24 * 3600 + current_seconds
          block_start_seconds = _get_or_set_block_anchor(
              ch_info, _this_block_key, _blk_clock, real_start_seconds=block_start_hour * 3600,
              overrun_end_seconds=_block_overrun_anchor(
                  ch_info, target_clean_key, _this_block_key, now, current_seconds, _blk_clock,
                  block_start_hour * 3600,
                  lambda _d: bool(_get_holiday_key(_d) and holiday_schedules.get(_get_holiday_key(_d)))))
          seconds_into_block = _blk_clock - block_start_seconds
          block_duration_seconds = block_length_seconds(current_block)
      elif current_block == "Night":
          _this_block_key = block_key_for(now, current_block)
          _blk_clock = current_seconds
          block_start_seconds = _get_or_set_block_anchor(
              ch_info, _this_block_key, _blk_clock, real_start_seconds=block_start_hour * 3600,
              overrun_end_seconds=_block_overrun_anchor(
                  ch_info, target_clean_key, _this_block_key, now, current_seconds, _blk_clock,
                  block_start_hour * 3600,
                  lambda _d: bool(_get_holiday_key(_d) and holiday_schedules.get(_get_holiday_key(_d)))))
          seconds_into_block = _blk_clock - block_start_seconds
          block_duration_seconds = block_length_seconds(current_block)
      else:
          _this_block_key = block_key_for(now, current_block)
          _blk_clock = current_seconds
          block_start_seconds = _get_or_set_block_anchor(
              ch_info, _this_block_key, _blk_clock, real_start_seconds=block_start_hour * 3600,
              overrun_end_seconds=_block_overrun_anchor(
                  ch_info, target_clean_key, _this_block_key, now, current_seconds, _blk_clock,
                  block_start_hour * 3600,
                  lambda _d: bool(_get_holiday_key(_d) and holiday_schedules.get(_get_holiday_key(_d)))))
          seconds_into_block = _blk_clock - block_start_seconds
          block_duration_seconds = block_length_seconds(current_block)

      _block_end_offset = None if _marathon_mode else (
          (0 if _full_day_mode else block_start_hour * 3600) + block_duration_seconds - block_start_seconds)

      _reflavor_cycle_rec = None

      folder_items = ch_info.get("schedules", {}).get(current_block, [])

      _diag_key = f"{target_clean_key}:{current_block}"
      if not folder_items:
          if _diag_key not in _EMPTY_FOLDER_DIAG_LOGGED:
              _EMPTY_FOLDER_DIAG_LOGGED.add(_diag_key)
              _sched_dict = ch_info.get("schedules", {})
              _disk_count = "?"
              _disk_block_mode = "?"
              try:
                  if db is not None and getattr(db, "config_path", None) and os.path.exists(db.config_path):
                      import json as _json
                      with open(db.config_path, "r") as _df:
                          _disk_data = _json.load(_df)
                      _disk_ch = _disk_data.get("channels", {}).get(target_clean_key, {})
                      _disk_count = len(_disk_ch.get("schedules", {}).get(current_block, []))
                      _disk_block_mode = _disk_ch.get("block_mode", "?")
              except Exception as _diag_e:
                  _disk_count = f"error reading disk: {_diag_e}"
              if _disk_count != 0:
                  log.warning(
                      "[SCHED DIAG] ch%s block=%s current_block=%s -- folder_items EMPTY in memory. "
                      "in-memory schedules keys=%s, in-memory block_mode=%s, ch_info id=%s, "
                      "db.channels_db[ch] is ch_info=%s || ON DISK right now: %s items in "
                      "schedules[%r], disk block_mode=%s",
                      target_clean_key, current_block, current_block,
                      list(_sched_dict.keys()), ch_info.get("block_mode"), id(ch_info),
                      (db.channels_db.get(target_clean_key) is ch_info) if db is not None else "no-db",
                      _disk_count, current_block, _disk_block_mode,
                  )
      else:
          _EMPTY_FOLDER_DIAG_LOGGED.discard(_diag_key)

      raw_tracks = build_raw_tracks(folder_items, _cached_path_exists)
      _pending_tracks = build_pending_tracks(folder_items, _cached_path_exists)

      if _deferred_anchor_state is None and not _marathon_mode and seconds_into_block < 0:
          _ov_hit = media.aired_entry_at(playback_log, now.toordinal(), current_seconds)
          if _ov_hit is None:
              return {
                  "mode": "Static", "file": "", "seek": 0,
                  "reason": "probe_failed",
                  "reason_detail": (
                      f"CH{target_clean_key} {current_block}: the entry airing across the block change "
                      f"is not in the guide ledger"
                  ),
              }
          _ov_entry, _ov_into = _ov_hit
          _ov_mode = "Commercial" if _ov_entry.get("is_commercial") else "Video"
          _ov_file = _ov_entry["path"]
          _ov_seek = _ov_entry.get("seek_offset", 0) + _ov_into
          _ov_dur = _ov_entry["duration"]
          if _ov_mode == "Video":
              _ov_file, _ov_seek, _ov_dur = media.resolve_lineup_playback(_ov_entry, _ov_seek)
          return {"mode": _ov_mode, "file": _ov_file, "seek": _ov_seek, "duration": _ov_dur,
                  "block": current_block, "seek_slot_offset": _ov_entry.get("seek_offset", 0),
                  "interior_cut": bool(_ov_entry.get("interior_cut", False))}

      if _pending_tracks:
          _priority_probe_pending_schedule(target_clean_key, "schedules", current_block, _pending_tracks)

      raw_tracks = build_raw_tracks(folder_items, _cached_path_exists)
      _pending_tracks = build_pending_tracks(folder_items, _cached_path_exists)
      if not raw_tracks and _pending_tracks:
          return {
              "mode": "Static", "file": "", "seek": 0,
              "reason": "first_file_scanning",
              "reason_detail": (
                  f"CH{target_clean_key} {current_block}: waiting for the first file's length; "
                  f"{len(_pending_tracks)} scheduled file(s) are scanned one at a time"
              ),
          }


      if not raw_tracks:
          if folder_items:
              _retry_paths = []
              _folder_paths = []
              for _asset in folder_items:
                  _path = (
                      _asset.get("path", _asset.get("file", ""))
                      if isinstance(_asset, dict)
                      else str(_asset)
                  )
                  if _path:
                      _folder_paths.append(_path)
              if _folder_paths:
                  _sample_count = min(12, len(_folder_paths))
                  _sample_indexes = set(range(_sample_count))
                  _sample_indexes.update(
                      range(max(0, len(_folder_paths) - _sample_count), len(_folder_paths))
                  )
                  for _idx in sorted(_sample_indexes):
                      _retry_paths.append(_folder_paths[_idx])
                  with _path_exists_cache_lock:
                      for _path in _retry_paths:
                          _cached = _path_exists_cache.get(_path)
                          if isinstance(_cached, tuple) and _cached and _cached[0] in (PATH_MISSING, PATH_UNKNOWN):
                              _path_exists_cache.pop(_path, None)
                  _retry_found = any(_cached_path_exists(_path) for _path in _retry_paths)
                  if _retry_found:
                      raw_tracks = build_raw_tracks(folder_items, _cached_path_exists)

              if raw_tracks:
                  log.warning(
                      "[SCHEDULER] ch%s block=%s recovered %d/%d media paths "
                      "after a transient path check failure",
                      target_clean_key, current_block, len(raw_tracks), len(folder_items),
                  )
              else:
                  _health_roots = _unresponsive_drive_roots()
                  log.warning(
                      "[SCHEDULER] ch%s block=%s returned Static: %d configured "
                      "entries, 0 playable paths; unresponsive drives=%s; "
                      "sample=%s",
                      target_clean_key, current_block, len(folder_items),
                      _health_roots, _folder_paths[:3],
                  )
          if not raw_tracks:
              if folder_items:
                  return {
                      "mode": "Static", "file": "", "seek": 0,
                      "reason": "missing_media",
                      "reason_detail": (
                          f"CH{target_clean_key} {current_block}: {len(folder_items)} "
                          f"file(s) scheduled, 0 found at their configured path"
                      ),
                  }
              _log_info_throttled(
                  f"empty_schedule:{target_clean_key}:{current_block}",
                  "[SCHEDULER] ch%s block=%s: nothing scheduled for this block "
                  "-- Static is expected.", target_clean_key, current_block,
              )
              return {
                  "mode": "Static", "file": "", "seek": 0,
                  "reason": "no_media_scheduled",
                  "reason_detail": f"CH{target_clean_key} {current_block}: no media scheduled",
              }

      scheduling_mode = ch_info.get("scheduling_mode", "random_slots")
      
      block_offset = block_seed_offset(current_block, 0)
      _seed_date = block_start_date(now, current_block)
      day_seed = block_day_seed(_seed_date, target_clean_key, block_offset)
      _order_seed = _start_order_seed(ch_info, block_offset)

      playback_log = ch_info.setdefault("playback_log", {})
      _show_pos = playback_log.setdefault("show_pos", {})

      _pair_thresh_sec = max(0, ch_info.get("pair_threshold_minutes", 15)) * 60

      commercials_enabled  = ch_info.get("commercials_enabled", False)
      commercial_items     = ch_info.get("schedules", {}).get("Commercials", [])

      commercial_tracks = []
      if commercials_enabled and commercial_items:
          commercial_tracks = build_commercial_tracks(commercial_items, _cached_path_exists)

      if _marathon_mode:
        _marathon_ordered = build_ordered_tracks(raw_tracks, "marathon", _marathon_start_seed(ch_info) if raw_tracks else 0)
        _mara_log = ch_info.setdefault("playback_log", {})
        _mara_cached_paths = _mara_log.get("marathon_cached_tracks")
        _mara_cached_durs  = _mara_log.get("marathon_cached_durations", {})
        _mara_live_paths   = [t["path"] for t in _marathon_ordered] if _marathon_ordered else []

        if _mara_cached_paths is not None:
            _mara_reconciled_ordered, _mara_dropped_transient = reconcile_cached_lineup(
                _mara_cached_paths, raw_tracks, folder_items, ch_info.get("broken_files", []),
                _mara_cached_durs, log_label=f"ch{target_clean_key} marathon",
            )
        else:
            _mara_reconciled_ordered = []
        _mara_reconciled_paths = [t["path"] for t in _mara_reconciled_ordered]

        _mara_membership_changed = (
            _mara_cached_paths is None or set(_mara_reconciled_paths) != set(_mara_live_paths)
        )
        _mara_stale_raw = (not _mara_membership_changed) and _cached_lineup_durations_stale(
            _mara_cached_durs
        )
        if _mara_stale_raw:
            _mara_stale_since = _mara_log.get("_marathon_durations_stale_since")
            if _mara_stale_since is None:
                _mara_log["_marathon_durations_stale_since"] = pygame.time.get_ticks()
                _mara_stale = False
            else:
                _mara_stale = (pygame.time.get_ticks() - _mara_stale_since) >= 5000
                if _mara_stale:
                    _mara_log["_marathon_durations_stale_since"] = None
        else:
            _mara_log["_marathon_durations_stale_since"] = None
            _mara_stale = False
        if _mara_membership_changed or _mara_stale or not _mara_cached_durs:
            _mara_cached_durs = _snapshot_track_durations(_marathon_ordered)
            _mara_log["marathon_cached_tracks"]     = list(_mara_live_paths)
            _mara_log["marathon_cached_durations"]  = _mara_cached_durs
            try: db.save_settings_async()
            except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist marathon_cached_durations: %s", e)
            video_tracks = apply_cached_durations(_marathon_ordered, _mara_cached_durs) if _marathon_ordered else []
        else:
            video_tracks = (apply_cached_durations(_mara_reconciled_ordered, _mara_cached_durs)
                             if _mara_reconciled_ordered else _marathon_ordered)
        _is_new_block = False
        block_key = block_key_for(now, current_block)
      else:
        block_key = _this_block_key
        _prev_sched_block_key = playback_log.get("sched_block_key")
        _is_new_block = (
            _prev_sched_block_key != block_key
            or playback_log.get("sched_pairing_rule_version")
                != SHORT_EPISODE_PAIRING_VERSION
        )

        _pending_signature = _pending_paths_signature(t.get("path", "") for t in _pending_tracks if t.get("path"))
        _pending_changed = (
            not _is_new_block
            and _stored_pending_signature(playback_log) != _pending_signature
        )
        _durations_stale_raw = (
            (not _is_new_block)
            and (
                bool(playback_log.get("_sched_rebuild_requested"))
                or _cached_lineup_durations_stale(
                    playback_log.get("sched_cached_durations", {}),
                    frozen_aired_paths=set(playback_log.get("sched_frozen_aired_paths", [])))
            )
        )

        if _durations_stale_raw:
            _durations_stale_since = playback_log.get("_sched_durations_stale_since")
            if _durations_stale_since is None:
                playback_log["_sched_durations_stale_since"] = pygame.time.get_ticks()
                _durations_stale = False
            else:
                _durations_stale = (pygame.time.get_ticks() - _durations_stale_since) >= 5000
                if _durations_stale:
                    playback_log["_sched_durations_stale_since"] = None
        else:
            playback_log["_sched_durations_stale_since"] = None
            _durations_stale = False

        _pending_since = ch_info.get("_sched_debounce_pending_since")
        _mode_change_ready = (
            _pending_since is not None
            and pygame.time.get_ticks() - _pending_since >= _SCHEDULE_MODE_COMMIT_HOLD_MS
        )
        if _mode_change_ready or _durations_stale or _pending_changed:
            if _mode_change_ready:
                ch_info["_sched_debounce_pending_since"] = None
            if not _is_new_block:
                _old_cached = playback_log.get("sched_cached_tracks", [])
                _old_video_tracks = saved_block_lineup(
                    _old_cached, playback_log.get("sched_cached_durations", {}), raw_tracks, folder_items,
                    ch_info.get("broken_files", []), _pair_thresh_sec,
                    log_label=f"ch{target_clean_key} block={current_block} (re-flavor)",
                    cached_groups=playback_log.get("sched_cached_groups"),
                )
                _keep_n = 0
                if _old_video_tracks:
                    _old_timeline, _old_total, _ = build_channel_timeline(
                        _old_video_tracks, commercial_tracks, ch_info, day_seed,
                        commercial_state=playback_log.get("commercial_pos"),
                    )
                    if _old_total > 0:
                        # WARNING: the place in the airing cycle must be found the same way the scheduler finds it below (from the saved cycle start, or the remainder in marathon mode); a remainder of the block time in any other mode keeps the wrong entries once a block has passed its first cycle.
                        _old_boundary = playback_log.get("sched_cycle_boundary", 0) or 0
                        if _old_boundary > seconds_into_block:
                            _old_boundary = 0
                        _old_pos = seconds_into_block % _old_total if _marathon_mode else seconds_into_block - _old_boundary
                        _vt_idx = -1
                        _last_path = None
                        _found = False
                        _last_completed_video_idx = -1
                        for _item in _old_timeline:
                            if not _item.get("is_commercial"):
                                if _item["path"] != _last_path:
                                    _vt_idx += 1
                                    _last_path = _item["path"]
                                if (_item["start_time"] + _item["duration"]) <= _old_pos:
                                    _last_completed_video_idx = _vt_idx
                                if _item["start_time"] <= _old_pos < _item["start_time"] + _item["duration"]:
                                    _keep_n = _vt_idx + 1
                                    _found = True
                                    break
                            elif _item["start_time"] <= _old_pos < _item["start_time"] + _item["duration"]:
                                _keep_n = max(0, _last_completed_video_idx + 1)
                                _found = True
                                break
                        if not _found:
                            _keep_n = len(_old_video_tracks)
                if 0 < _keep_n <= len(_old_video_tracks):
                    _kept_video_tracks = _old_video_tracks[:_keep_n]
                    _kept_paths = []
                    _kept_paths.extend(lineup_paths(_kept_video_tracks))
                    _show_order_by_block = playback_log.setdefault("show_order", {})
                    _cycle_start_rec = playback_log.get("sched_cycle_start_pos")
                    _tail_start_pos = _show_pos
                    _prior_kept = _cycle_start_rec.get("kept") if isinstance(_cycle_start_rec, dict) else None
                    if (isinstance(_cycle_start_rec, dict) and _cycle_start_rec.get("block_key") == block_key
                            and isinstance(_cycle_start_rec.get("positions"), dict)
                            and isinstance(_prior_kept, int) and 0 <= _prior_kept <= _keep_n):
                        # WARNING: the entries that aired were dealt in the slot mode and episode order saved with the cycle's start; replaying them in a mode just switched to moves each show by the wrong count and a show repeats or skips an episode.
                        _replay_info = dict(ch_info)
                        for _rec_field, _info_field in (("mode", "scheduling_mode"), ("order", "episode_order_mode")):
                            if _cycle_start_rec.get(_rec_field):
                                _replay_info[_info_field] = _cycle_start_rec[_rec_field]
                        _kept_pos = media.positions_after_aired_entries(
                            raw_tracks, _replay_info, _cycle_start_rec["positions"], day_seed, block_duration_seconds,
                            target_clean_key, _show_order_by_block.get(current_block), _order_seed,
                            _old_video_tracks[_prior_kept:], _keep_n - _prior_kept, pending_tracks=_pending_tracks)
                        if _kept_pos is not None:
                            _tail_start_pos = _kept_pos
                            _reflavor_cycle_rec = {"block_key": block_key, "positions": copy.deepcopy(_kept_pos), "kept": _keep_n,
                                                   "mode": ch_info.get("scheduling_mode"), "order": ch_info.get("episode_order_mode")}
                        else:
                            log.warning("[SCHEDULER] ch%s block=%s the kept entries could not be tied to their shows; the rebuilt tail starts from the positions as saved",
                                        target_clean_key, current_block)
                    else:
                        log.warning("[SCHEDULER] ch%s block=%s no saved start of the airing cycle; the rebuilt tail starts from the positions as saved",
                                    target_clean_key, current_block)
                    if _reflavor_cycle_rec is not None:
                        playback_log["sched_cycle_start_pos"] = _reflavor_cycle_rec
                    else:
                        playback_log.pop("sched_cycle_start_pos", None)
                    _new_tail_tracks, _new_show_pos, _new_show_order = build_block_rotation(
                        raw_tracks, ch_info, _tail_start_pos, day_seed, block_duration_seconds,
                        target_clean_key, _show_order_by_block.get(current_block), _order_seed,
                        pending_tracks=_pending_tracks,
                    )
                    _show_pos = _new_show_pos
                    playback_log["show_pos"] = _new_show_pos
                    _show_order_by_block[current_block] = _new_show_order
                    _tail_paths = []
                    _tail_paths.extend(lineup_paths(_new_tail_tracks))
                    _old_durs = playback_log.get("sched_cached_durations", {})
                    _new_saved_tracks = [p for p in (_kept_paths + _tail_paths) if p]
                    _new_saved_groups = lineup_groups(
                        list(_kept_video_tracks) + list(_new_tail_tracks), _pair_thresh_sec)
                    _set_saved_lineup(
                        playback_log, _new_saved_tracks,
                        {
                            **{p: _old_durs[p] for p in _kept_paths if p in _old_durs},
                            **_snapshot_track_durations(_new_tail_tracks),
                        },
                        _new_saved_groups,
                    )
                    playback_log["sched_pending_signature"] = _pending_signature
                    playback_log["sched_cycle_total"] = 0

                    _kept_paths_set = set(_kept_paths)
                    playback_log["sched_frozen_aired_paths"] = [
                        p for p in playback_log.get("sched_frozen_aired_paths", [])
                        if p in _kept_paths_set
                    ]
                    playback_log["sched_block_key"] = block_key
                    _blk_rot_cache_d = playback_log.setdefault("block_rotation_cache", {})
                    _blk_rot_cache_d[block_key] = {
                        "tracks":    list(playback_log["sched_cached_tracks"]),
                        "durations": dict(playback_log["sched_cached_durations"]),
                        "groups":    copy.deepcopy(playback_log.get("sched_cached_groups")),
                        "pairing_rule_version": SHORT_EPISODE_PAIRING_VERSION,
                    }
                    if len(_blk_rot_cache_d) > 12:
                        for _prune_bk_d in sorted(_blk_rot_cache_d.keys())[:-12]:
                            _blk_rot_cache_d.pop(_prune_bk_d, None)
                    playback_log["_sched_rebuild_requested"] = False
                    if db is not None:
                        try: db.save_settings()
                        except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist re-flavored sched_cached_tracks: %s", e)
                elif _durations_stale and not _mode_change_ready:
                    _is_new_block = True

        if _deferred_anchor_state is not None:
            return _deferred_anchor_state

        video_tracks = []
        _new_block_start_pos = None
        _new_block_fixed_order = None
        if not _is_new_block:
          _cached = playback_log.get("sched_cached_tracks", [])
          video_tracks = saved_block_lineup(
              _cached, playback_log.get("sched_cached_durations", {}), raw_tracks, folder_items,
              ch_info.get("broken_files", []), _pair_thresh_sec,
              log_label=f"ch{target_clean_key} block={current_block}",
              cached_groups=playback_log.get("sched_cached_groups"),
          )
          if not video_tracks:
              _is_new_block = True

        if _is_new_block:
          _show_order_by_block = playback_log.setdefault("show_order", {})

          _note_missed_blocks(
              ch_info, target_clean_key, _show_pos, _prev_sched_block_key, block_key, now, commercial_tracks,
              lambda _d: bool(_get_holiday_key(_d) and holiday_schedules.get(_get_holiday_key(_d))))

          _catch_up_t0 = time.perf_counter()
          try:
              _catch_up = media.catch_up_state(
                  target_clean_key, ch_info, _show_pos, _prev_sched_block_key, block_key, _cached_path_exists, commercial_tracks,
                  lambda _offset: _start_order_seed(ch_info, _offset),
                  lambda _d: bool(_get_holiday_key(_d) and holiday_schedules.get(_get_holiday_key(_d))))
          except Exception as _catch_up_err:
              _catch_up = None
              log.warning("[CATCH-UP] ch%s schedule advancement across missed blocks failed, positions left as saved: %s",
                          target_clean_key, _catch_up_err)
          if _catch_up is not None:
              _fwd_show_pos, _fwd_commercial, _fwd_orders, _fwd_blocks = _catch_up
              _show_pos.clear()
              _show_pos.update(_fwd_show_pos)
              playback_log["show_pos"] = _show_pos
              if _fwd_commercial is not None:
                  playback_log["commercial_next_pos"] = _fwd_commercial
              for _fwd_name, _fwd_order in _fwd_orders.items():
                  _show_order_by_block.setdefault(_fwd_name, _fwd_order)
              playback_log["last_gap_catchup"] = {
                  "channel": target_clean_key,
                  "block": current_block,
                  "missed_blocks": _fwd_blocks,
                  "caught_up_at": now.isoformat(),
              }
              log.info(
                  "[CATCH-UP] ch%s block=%s advanced positions across %d missed block(s) since %s in %.1f ms",
                  target_clean_key, current_block, _fwd_blocks, _prev_sched_block_key,
                  (time.perf_counter() - _catch_up_t0) * 1000.0,
              )

          _new_block_start_pos = copy.deepcopy(_show_pos)
          _new_block_fixed_order = _show_order_by_block.get(current_block)
          video_tracks, _new_show_pos, _new_show_order = build_block_rotation(
              raw_tracks, ch_info, _show_pos, day_seed, block_duration_seconds,
              target_clean_key, _show_order_by_block.get(current_block), _order_seed,
              pending_tracks=_pending_tracks,
          )
          if not video_tracks and _pending_tracks:
              return {
                  "mode": "Static", "file": "", "seek": 0,
                  "reason": "not_scanned",
                  "reason_detail": (
                      f"CH{target_clean_key} {current_block}: nothing scanned to air yet, "
                      f"{len(_pending_tracks)} file(s) not scanned"
                  ),
              }
          playback_log["show_pos"] = _new_show_pos
          _show_order_by_block[current_block] = _new_show_order
          playback_log["sched_block_key"] = block_key
          playback_log["sched_pairing_rule_version"] = SHORT_EPISODE_PAIRING_VERSION
          _cache_paths = lineup_paths(video_tracks)
          _set_saved_lineup(
              playback_log, _cache_paths, _snapshot_track_durations(video_tracks),
              lineup_groups(video_tracks, _pair_thresh_sec))
          playback_log["sched_pending_signature"] = _pending_signature
          playback_log["sched_frozen_aired_paths"] = []

          _blk_rot_cache_n = playback_log.setdefault("block_rotation_cache", {})
          _blk_rot_cache_n[block_key] = {
              "tracks":    list(playback_log["sched_cached_tracks"]),
              "durations": dict(playback_log["sched_cached_durations"]),
              "groups":    copy.deepcopy(playback_log.get("sched_cached_groups")),
              "pairing_rule_version": SHORT_EPISODE_PAIRING_VERSION,
          }
          if len(_blk_rot_cache_n) > BLOCK_ROTATION_CACHE_MAX_BLOCKS:
              for _prune_bk_n in sorted(_blk_rot_cache_n.keys())[:-BLOCK_ROTATION_CACHE_MAX_BLOCKS]:
                  _blk_rot_cache_n.pop(_prune_bk_n, None)
          playback_log["sched_cycle_boundary"] = 0
          playback_log["sched_cycle_total"]    = 0
          playback_log["sched_cycle_start_pos"] = {"block_key": block_key, "positions": copy.deepcopy(_new_block_start_pos), "kept": 0,
                                                   "mode": ch_info.get("scheduling_mode"), "order": ch_info.get("episode_order_mode")}
          try: db.save_settings()
          except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist sched_cached_tracks: %s", e)
          app_state["guide_refresh_token"] = app_state.get("guide_refresh_token", 0) + 1

      _prime_block_durations_on_cold_start(
          target_clean_key, current_block, video_tracks, seconds_into_block,
      )

      if _is_new_block:
          playback_log["commercial_pos"] = copy.deepcopy(media.carried_commercial_state(playback_log) or {})
      timeline, total_block_content, _new_commercial_state = build_channel_timeline(
          video_tracks, commercial_tracks, ch_info, day_seed,
          commercial_state=playback_log.get("commercial_pos"),
      )
      if _reflavor_cycle_rec is not None and not _is_new_block and timeline and total_block_content > 0:
          _re_kept = _reflavor_cycle_rec["kept"]
          _re_aired = len(video_tracks)
          _re_mapped = True
          if _block_end_offset is not None:
              _re_cutoff = _block_end_offset - (playback_log.get("sched_cycle_boundary", 0) or 0)
              if total_block_content > _re_cutoff:
                  _re_started = media.entries_started_before(timeline, video_tracks, _re_cutoff)
                  if _re_started is None:
                      _re_mapped = False
                  else:
                      _re_aired = _re_started
          _re_pos = None
          if _re_mapped:
              _re_pos = media.positions_after_aired_entries(
                  raw_tracks, ch_info, _reflavor_cycle_rec["positions"], day_seed, block_duration_seconds,
                  target_clean_key, playback_log.setdefault("show_order", {}).get(current_block), _order_seed,
                  list(video_tracks)[_re_kept:], max(0, _re_aired - _re_kept), pending_tracks=_pending_tracks)
          if _re_pos is not None:
              playback_log["show_pos"] = _re_pos
              try: db.save_settings()
              except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist re-flavored show_pos for ch%s: %s", target_clean_key, e)
          else:
              log.warning("[SCHEDULER] ch%s block=%s the re-flavored entries could not be tied to their shows or timeline; positions stay as the rebuilt tail left them",
                          target_clean_key, current_block)
      if _is_new_block:
          playback_log["commercial_next_pos"] = _new_commercial_state
          if _block_end_offset is not None and _new_block_start_pos is not None and timeline and total_block_content > 0:
              _cut_pos, _cut_how = media.cycle_positions_at_block_end(
                  raw_tracks, ch_info, _new_block_start_pos, day_seed, block_duration_seconds,
                  target_clean_key, _new_block_fixed_order, _order_seed,
                  video_tracks, timeline, total_block_content, _block_end_offset,
                  playback_log.get("show_pos"), pending_tracks=_pending_tracks)
              if _cut_how == "cut":
                  playback_log["show_pos"] = _cut_pos
                  try: db.save_settings()
                  except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist cut-cycle show_pos for ch%s: %s", target_clean_key, e)
              elif _cut_how == "unmapped":
                  log.warning("[SCHEDULER] ch%s block=%s the new block's entries could not be tied to its timeline; positions stay as the whole cycle left them",
                              target_clean_key, current_block)

      if timeline:
          try:
              _probe_block_timeline_cache[target_clean_key] = {
                  "block_key": block_key,
                  "items": [
                      {"path": _te.get("path", ""), "is_commercial": bool(_te.get("is_commercial")),
                       "start_time": _te.get("start_time")}
                      for _te in timeline if isinstance(_te, dict) and _te.get("path")
                  ],
              }
          except Exception as _tl_cache_err:
              log.warning("calculate_slotted_playback_state: failed to cache probe timeline for ch%s: %s",
                          target_clean_key, _tl_cache_err)

      if not timeline or total_block_content <= 0:
          _tl_track_info = [
              {"path": _t.get("path", ""), "duration": _t.get("duration")}
              for _t in (video_tracks or [])
          ]
          log.warning(
              "[SCHEDULER] ch%s block=%s returned Static: build_block_timeline "
              "produced no usable timeline (total_block_content=%s) from %d "
              "video track(s) and %d commercial track(s); tracks=%s",
              target_clean_key, current_block, total_block_content,
              len(video_tracks or []), len(commercial_tracks or []), _tl_track_info,
          )
          return {
              "mode": "Static", "file": "", "seek": 0,
              "reason": "not_scanned" if _pending_tracks else "timeline_build_failed",
              "reason_detail": (
                  f"CH{target_clean_key} {current_block}: schedule builder produced "
                  f"no playable timeline from {len(video_tracks or [])} track(s)"
              ),
          }

      if not _marathon_mode:
          _cyc_boundary = playback_log.get("sched_cycle_boundary", 0)
          _cyc_total    = playback_log.get("sched_cycle_total", 0) or total_block_content
          if _cyc_boundary > seconds_into_block:
              _cyc_boundary = 0
              _cyc_total    = total_block_content
          _distinct_bundle_paths = {
              os.path.normpath(str(it.get("path", ""))).lower() for it in timeline
          }
          _bundle_file_count = len(_distinct_bundle_paths)
          if (_cyc_boundary == 0
                  and _bundle_file_count in (1, 2)
                  and _cyc_total != total_block_content):
              log.info(
                  "calculate_slotted_playback_state: ch%s small bundle "
                  "(%d distinct file(s)) -- resyncing stale sched_cycle_total "
                  "(%s) to freshly-computed total_block_content (%s) so it "
                  "loops/repeats instead of running out and going Static.",
                  target_clean_key, _bundle_file_count, _cyc_total, total_block_content,
              )
              _cyc_total = total_block_content
          _cycle_changed    = False
          _show_order_by_block2 = playback_log.setdefault("show_order", {})
          _sp2              = dict(playback_log.get("show_pos", {}))
          _new_show_order2  = _show_order_by_block2.get(current_block)
          _cp2              = dict(_new_commercial_state or {})
          _live_cp2         = playback_log.get("commercial_pos")
          _good_timeline, _good_total, _good_video_tracks = timeline, total_block_content, video_tracks
          _good_sp2, _good_show_order2, _good_cyc_total = _sp2, _new_show_order2, _cyc_total
          _good_cp2 = _cp2
          _good_live_cp2 = _live_cp2
          _airing_cycle_start_pos = None
          while total_block_content > 0 and seconds_into_block >= _cyc_boundary + _cyc_total:
              _try_boundary = _cyc_boundary + _cyc_total
              _try_start_pos = copy.deepcopy(_sp2)
              _try_video_tracks, _try_sp2, _try_show_order2 = build_block_rotation(
                  raw_tracks, ch_info, _sp2, day_seed, block_duration_seconds,
                  target_clean_key, _show_order_by_block2.get(current_block), _order_seed,
                  pending_tracks=_pending_tracks,
              )
              _try_timeline, _try_total, _try_cp2 = build_channel_timeline(
                  _try_video_tracks, commercial_tracks, ch_info, day_seed,
                  commercial_state=_cp2,
              )
              if (not _try_timeline or _try_total <= 0) and _pending_tracks:
                  return {
                      "mode": "Static", "file": "", "seek": 0,
                      "reason": "not_scanned",
                      "reason_detail": (
                          f"CH{target_clean_key} {current_block}: the next cycle has nothing "
                          f"scanned to air, {len(_pending_tracks)} file(s) not scanned"
                      ),
                  }
              if not _try_timeline or _try_total <= 0:
                  log.warning(
                      "calculate_slotted_playback_state: ch%s cycle rebuild came back "
                      "empty (raw_tracks=%d, video_tracks=%d, scheduling_mode=%s, "
                      "day_seed=%d, show_pos=%s) -- keeping last known-good cycle instead "
                      "of going to Static.",
                      target_clean_key, len(raw_tracks), len(_try_video_tracks or []),
                      scheduling_mode, day_seed, _try_sp2)
                  break
              if _block_end_offset is not None:
                  _try_sp2, _try_cut_how = media.cycle_positions_at_block_end(
                      raw_tracks, ch_info, _try_start_pos, day_seed, block_duration_seconds,
                      target_clean_key, _show_order_by_block2.get(current_block), _order_seed,
                      _try_video_tracks, _try_timeline, _try_total,
                      _block_end_offset - _try_boundary, _try_sp2, pending_tracks=_pending_tracks)
                  if _try_cut_how == "unmapped":
                      log.warning("[SCHEDULER] ch%s block=%s the next cycle's entries could not be tied to its timeline; positions stay as the whole cycle left them",
                                  target_clean_key, current_block)
              _note_aired_cycle(playback_log, current_block, block_key, now, current_seconds,
                                seconds_into_block, _cyc_boundary, timeline, _cyc_total, _block_end_offset)
              _cyc_boundary = _try_boundary
              _cycle_changed = True
              _airing_cycle_start_pos = _try_start_pos
              video_tracks, timeline, total_block_content = _try_video_tracks, _try_timeline, _try_total
              _sp2, _new_show_order2 = _try_sp2, _try_show_order2
              _live_cp2 = _cp2
              _cp2 = _try_cp2
              _cyc_total = total_block_content
              _good_timeline, _good_total, _good_video_tracks = timeline, total_block_content, video_tracks
              _good_sp2, _good_show_order2, _good_cyc_total = _sp2, _new_show_order2, _cyc_total
              _good_cp2 = _cp2
              _good_live_cp2 = _live_cp2
          if not timeline or total_block_content <= 0:
              timeline, total_block_content, video_tracks = _good_timeline, _good_total, _good_video_tracks
              _sp2, _new_show_order2, _cyc_total = _good_sp2, _good_show_order2, _good_cyc_total
              _cp2 = _good_cp2
              _live_cp2 = _good_live_cp2
          if _cycle_changed and timeline and total_block_content > 0:
              playback_log["show_pos"] = _sp2
              if _airing_cycle_start_pos is not None:
                  playback_log["sched_cycle_start_pos"] = {"block_key": block_key, "positions": copy.deepcopy(_airing_cycle_start_pos), "kept": 0,
                                                           "mode": ch_info.get("scheduling_mode"), "order": ch_info.get("episode_order_mode")}
              playback_log["commercial_pos"] = _live_cp2
              playback_log["commercial_next_pos"] = _cp2
              if _new_show_order2 is not None:
                  _show_order_by_block2[current_block] = _new_show_order2
              _cache_paths2 = lineup_paths(video_tracks)
              _set_saved_lineup(
                  playback_log, _cache_paths2, _snapshot_track_durations(video_tracks),
                  lineup_groups(video_tracks, _pair_thresh_sec))
              playback_log["sched_frozen_aired_paths"] = []
              _blk_rot_cache_c = playback_log.setdefault("block_rotation_cache", {})
              _blk_rot_cache_c[block_key] = {
                  "tracks":    list(playback_log["sched_cached_tracks"]),
                  "durations": dict(playback_log["sched_cached_durations"]),
                  "groups":    copy.deepcopy(playback_log.get("sched_cached_groups")),
                  "pairing_rule_version": SHORT_EPISODE_PAIRING_VERSION,
              }
              if len(_blk_rot_cache_c) > 12:
                  for _prune_bk_c in sorted(_blk_rot_cache_c.keys())[:-12]:
                      _blk_rot_cache_c.pop(_prune_bk_c, None)
              try: db.save_settings()
              except Exception as e: log.warning("calculate_slotted_playback_state: failed to persist cycle-advanced sched: %s", e)
              app_state["guide_refresh_token"] = app_state.get("guide_refresh_token", 0) + 1
          playback_log["sched_cycle_boundary"] = _cyc_boundary
          playback_log["sched_cycle_total"]    = _cyc_total
          _note_aired_cycle(playback_log, current_block, block_key, now, current_seconds,
                            seconds_into_block, _cyc_boundary, timeline, _cyc_total, _block_end_offset)
          if not timeline or total_block_content <= 0:
              log.warning(
                  "[SCHEDULER] ch%s block=%s returned Static: cycle rebuild "
                  "attempts exhausted with no usable timeline left "
                  "(cyc_boundary=%s, cyc_total=%s, seconds_into_block=%s)",
                  target_clean_key, current_block, _cyc_boundary, _cyc_total,
                  seconds_into_block,
              )
              return {
                  "mode": "Static", "file": "", "seek": 0,
                  "reason": "schedule_exhausted",
                  "reason_detail": (
                      f"CH{target_clean_key} {current_block}: ran out of scheduled "
                      f"content and couldn't rebuild the next cycle"
                  ),
              }
          position_in_playlist = seconds_into_block - _cyc_boundary
      else:
          position_in_playlist = seconds_into_block % total_block_content

      if not _marathon_mode and total_block_content > 0 and position_in_playlist >= total_block_content:
          log.info(
              "calculate_slotted_playback_state: ch%s block=%s "
              "position_in_playlist=%.3f still >= freshly-recomputed "
              "total_block_content=%s after the cycle-boundary advance loop "
              "(cached sched_cycle_total was %s) -- resyncing the cycle "
              "boundary to the current wall-clock position instead of "
              "returning Static.",
              target_clean_key, current_block, position_in_playlist,
              total_block_content, _cyc_total,
          )
          _cyc_boundary = seconds_into_block - (seconds_into_block % total_block_content)
          position_in_playlist = seconds_into_block - _cyc_boundary
          playback_log["sched_cycle_boundary"] = _cyc_boundary
          playback_log["sched_cycle_total"] = total_block_content
          try: db.save_settings()
          except Exception as e:
              log.warning("calculate_slotted_playback_state: failed to persist "
                          "drift-resync boundary for ch%s: %s", target_clean_key, e)

      _position_before_guard = position_in_playlist
      target_show, position_in_playlist = _apply_repeat_guard(
          target_clean_key, playback_log, current_block,
          timeline, total_block_content, position_in_playlist, now)

      target_show, position_in_playlist = _maybe_correct_estimated_target_duration(
          target_clean_key, current_block, timeline, target_show, position_in_playlist, now)
      _tl_now_cache = _probe_block_timeline_cache.get(target_clean_key)
      if _tl_now_cache is not None and _tl_now_cache.get("block_key") == block_key and target_show.get("path"):
          _tl_now_cache["now"] = (os.path.normpath(str(target_show.get("path"))), target_show.get("start_time"))
      _clock_shift_seconds = position_in_playlist - _position_before_guard

      if target_show is not None:
          # WARNING: commit (freeze) the duration used for every item at or before what is airing now; a later real probe must never shift an item already airing.
          _frozen_paths_set = set(playback_log.get("sched_frozen_aired_paths", []))
          _cached_durs_ref = playback_log.get("sched_cached_durations", {})
          _, _, _freeze_changed = _freeze_aired_prefix_durations(
              timeline, target_show, _cached_durs_ref, _frozen_paths_set)
          if _freeze_changed:
              _set_saved_lineup(
                  playback_log,
                  playback_log.get("sched_cached_tracks", []),
                  _cached_durs_ref,
                  playback_log.get("sched_cached_groups"),
              )
              playback_log["sched_frozen_aired_paths"] = sorted(_frozen_paths_set)
              try:
                  db.save_settings()
              except Exception as e:
                  log.warning("calculate_slotted_playback_state: failed to persist "
                              "frozen-aired durations for ch%s: %s", target_clean_key, e)

      if target_show is None:
          log.warning(
              "[SCHEDULER] ch%s block=%s returned Static: repeat-guard/target-show "
              "resolution found no show for position_in_playlist=%s out of "
              "total_block_content=%s (timeline has %d entries)",
              target_clean_key, current_block, position_in_playlist,
              total_block_content, len(timeline or []),
          )
          return {
              "mode": "Static", "file": "", "seek": 0,
              "reason": "no_show_selected",
              "reason_detail": (
                  f"CH{target_clean_key} {current_block}: no show could be matched "
                  f"to the current playback position"
              ),
          }

      _hub_pick = _hub_airing_entry(target_clean_key, block_key, timeline, target_show, position_in_playlist, _clock_shift_seconds)
      if _hub_pick is not None:
          target_show = _hub_pick

      _request_hub_row_sync(target_clean_key, block_key, timeline, target_show, position_in_playlist, raw_tracks, _clock_shift_seconds)

      seek_pos    = position_in_playlist - target_show["start_time"]
      actual_seek = target_show.get("seek_offset", 0) + seek_pos
      slot_start_seek = target_show.get("seek_offset", 0)
      mode = "Commercial" if target_show.get("is_commercial") else "Video"
      resolved_file = target_show["path"]
      resolved_seek = actual_seek
      resolved_dur  = target_show["duration"]
      if mode == "Video":
          resolved_file, resolved_seek, resolved_dur = media.resolve_lineup_playback(
              target_show, actual_seek)
      _resolve_sig = (current_block, resolved_file)
      _resolve_now = time.monotonic()
      if target_clean_key == "05" and (
              _resolve_sig != _resolve_log_state.get("sig")
              or _resolve_now - _resolve_log_state.get("ts", -1e9) >= 15.0):
          _resolve_log_state["sig"] = _resolve_sig
          _resolve_log_state["ts"] = _resolve_now
          log.info(
              "[RESOLVE ch05] block=%s pos_in_playlist=%.2f total_block_content=%.2f "
              "cyc_boundary=%s cyc_total=%s show.path=%s show.start_time=%.2f "
              "show.seek_offset=%.2f show.slot_remaining_duration=%.2f show.is_pair=%s "
              "show.interior_cut=%s -> seek_pos=%.2f actual_seek=%.2f "
              "resolved_file=%s resolved_seek=%.2f resolved_dur=%.2f",
              current_block, position_in_playlist, total_block_content,
              playback_log.get("sched_cycle_boundary"), playback_log.get("sched_cycle_total"),
              target_show.get("path"), target_show.get("start_time", 0),
              target_show.get("seek_offset", 0), target_show.get("duration", 0),
              bool(target_show.get("is_pair")), bool(target_show.get("interior_cut", False)),
              seek_pos, actual_seek, resolved_file, resolved_seek, resolved_dur,
          )
      return {"mode": mode, "file": resolved_file, "seek": resolved_seek,
              "duration": resolved_dur, "block": current_block,
              "seek_slot_offset": slot_start_seek,
              "interior_cut": bool(target_show.get("interior_cut", False))}


_MARK_BROKEN_CONFIRMED_REASONS = {"confirmed_missing", "file_corrupt"}

_transient_failure_state = {}

_play_fail_streak_by_root = {}


# ============================================================================
# SECTION: Broken-file tracking & episode recovery
# ============================================================================


def _note_playback_succeeded(file_path):
    """Called when a file is confirmed playing (state leaves Opening/Buffering cleanly, or a normal end-of-episode)."""
    if file_path:
        _transient_failure_state.pop(file_path, None)
        try:
            if _play_fail_streak_by_root:
                _play_fail_streak_by_root.pop(media._drive_root_of(file_path), None)
        except Exception as _swallowed_error:
            _log_swallowed("_note_playback_succeeded: _play_fail_streak_by_root.pop", _swallowed_error)


def _remove_confirmed_file_from_saved_lineups(file_path):
    """Remove one confirmed-broken path from saved lineups without changing clock state."""
    if db is None or not file_path:
        return False
    changed = False
    for _ch_key, _ch_info in db.channels_db.items():
        _log = _ch_info.get("playback_log") or {}
        _tracks = _log.get("sched_cached_tracks")
        if not isinstance(_tracks, list) or file_path not in _tracks:
            continue
        _new_tracks = [p for p in _tracks if p != file_path]
        _durations = dict(_log.get("sched_cached_durations") or {})
        _durations.pop(file_path, None)
        _record = copy.deepcopy(_log.get("sched_cached_groups"))
        _pair_broken = False
        if isinstance(_record, dict) and isinstance(_record.get("groups"), list):
            _groups = []
            for _group in _record["groups"]:
                _paths = [p for p in (_group.get("paths") or []) if p != file_path]
                if not _paths:
                    continue
                _kind = _group.get("kind", "single")
                if _kind == "pair" and len(_paths) != 2:
                    _kind = "single"
                    _pair_broken = True
                _groups.append({"kind": _kind, "paths": _paths})
            _record["groups"] = _groups
        _set_saved_lineup(_log, _new_tracks, _durations, _record)
        changed = True
        if _pair_broken:
            # WARNING: a short episode must not air alone because its partner was found broken; the entries still ahead are dealt again so it gets a new partner, and nothing that aired or is on air changes.
            log.warning("[SCHEDULER] ch%s: %s was removed from a pair; the entries still ahead are dealt again so its partner gets a new one",
                        _ch_key, os.path.basename(str(file_path)))
            _request_schedule_rebuild(_ch_key, _log.get("sched_block_key"))
    return changed


def _mark_file_broken(ch_info, file_path, reason=None):
    """Record a playback failure for file_path."""
    _reason = reason or "unspecified"
    _confirmed = reason in _MARK_BROKEN_CONFIRMED_REASONS

    if not _confirmed:
        try:
            if _path_status(file_path) == PATH_MISSING:
                _confirmed = True
                _reason = f"{_reason} + _path_status()=MISSING (confirmed now)"
        except Exception as e:
            log.warning("_mark_file_broken: live path-status check failed for %s: %s", file_path, e)

    if not _confirmed:
        try:
            _root = media._drive_root_of(file_path)
        except Exception as _swallowed_error:
            _log_swallowed("_mark_file_broken: _root = media._drive_root_of(file_path)", _swallowed_error)
            _root = None
        if _root is not None and (_root in _unresponsive_drive_roots() or _is_drive_degraded(file_path)):
            log.warning("_mark_file_broken: NOT counting this failure against %s -- drive %s "
                        "is currently unresponsive/degraded, so the drive (not this file) is "
                        "the more likely cause (reason=%s).", file_path, _root, _reason)
            return

        _st = _transient_failure_state.setdefault(file_path, {"count": 0})
        _st["count"] += 1
        _st["last_reason"] = _reason
        _st["last_ms"] = pygame.time.get_ticks()
        log.warning("_mark_file_broken: NOT removing %s -- failure %d (reason=%s) is not a confirmed corrupt or missing "
                    "file; it passed its scan, so the channel goes to Static and the same file is tried again.",
                    file_path, _st["count"], _reason)
        return

    _transient_failure_state.pop(file_path, None)
    broken = ch_info.setdefault("broken_files", [])
    if file_path not in broken:
        broken.append(file_path)
        log.warning("Marking file unplayable, removing from future scheduling: %s (reason=%s)", file_path, _reason)
    _remove_confirmed_file_from_saved_lineups(file_path)
    try:
        if db is not None:
            db.save_settings()
    except Exception as e:
        log.warning("_mark_file_broken: failed to persist broken_files for %s: %s", file_path, e)


def _clear_broken_files_for_root(root):
    """Drop every broken_files entry, on every channel, that lives on `root`."""
    if db is None or root is None:
        return
    _changed = False
    for _ch_info in db.channels_db.values():
        _broken = _ch_info.get("broken_files")
        if not _broken:
            continue
        _kept = [p for p in _broken if media._drive_root_of(p) != root]
        if len(_kept) != len(_broken):
            _ch_info["broken_files"] = _kept
            _changed = True
    _stale_transient = [p for p in _transient_failure_state
                         if media._drive_root_of(p) == root]
    for p in _stale_transient:
        _transient_failure_state.pop(p, None)
    if _stale_transient:
        log.info("[DRIVE HEALTH] %s recovered -- cleared %d transient ambiguous-failure "
                  "count(s) on it too, so a pre-recovery strike can't combine with an "
                  "unrelated post-recovery hiccup", root, len(_stale_transient))
    if _changed:
        log.info("[DRIVE HEALTH] %s recovered -- cleared broken_files entries on "
                  "it so their episodes are schedulable again", root)
        try:
            db.save_settings()
        except Exception as e:
            log.warning("_clear_broken_files_for_root: failed to persist cleared "
                        "broken_files for %s: %s", root, e)


def _get_show_episode_context(ch_info, current_block, file_path):
    folder_items = ch_info.get("schedules", {}).get(current_block, [])
    broken = set(ch_info.get("broken_files", []))
    raw = []
    for asset in folder_items:
        path = asset.get("path", asset.get("file", "")) if isinstance(asset, dict) else str(asset)
        if not path or path in broken:
            continue
        _status = _path_status(path)
        if _status == PATH_MISSING:
            continue
        if _status == PATH_UNKNOWN:
            # WARNING: an UNKNOWN path status must keep the episode eligible for substitution (fail open, as _cached_path_exists does); log it.
            _log_info_throttled("path_unknown:" + str(path), "[PATH STATUS] %s: UNKNOWN (drive unresponsive or probe timed out) -- "
                                "keeping eligible for substitution rather than dropping it", path)
        stored = asset.get("duration", 0) if isinstance(asset, dict) else 0
        if media.track_duration_is_estimated(path, stored):
            continue
        raw.append({"path": path, "duration": resolve_track_duration(path, stored)})
    _movie_pool, show_names, show_episodes = split_movies_and_series(raw)
    for sn in show_names:
        eps = show_episodes.get(sn, [])
        if any(e["path"] == file_path for e in eps):
            return sn, eps
    return None, []


def _set_saved_lineup(playback_log, tracks, durations=None, groups=None):
    """Store the saved lineup fields together and keep the active block cache synchronized."""
    _tracks = list(dict.fromkeys(p for p in (tracks or []) if p))
    _durations = dict(durations or {})
    playback_log["sched_cached_tracks"] = _tracks
    playback_log["sched_cached_durations"] = {
        p: _durations[p] for p in _tracks if p in _durations
    }
    if groups is not None:
        playback_log["sched_cached_groups"] = copy.deepcopy(groups)
    _block_key = playback_log.get("sched_block_key")
    _block_cache = playback_log.get("block_rotation_cache")
    if _block_key and isinstance(_block_cache, dict):
        _cached_block = _block_cache.get(_block_key)
        if isinstance(_cached_block, dict):
            _cached_block["tracks"] = list(playback_log["sched_cached_tracks"])
            _cached_block["durations"] = dict(playback_log["sched_cached_durations"])
            _cached_block["groups"] = copy.deepcopy(playback_log.get("sched_cached_groups"))


def _perceptual_volume_pct(slider_pct, min_db=-40.0):
    pct = max(0, min(100, slider_pct))
    if pct <= 0:
        return 0.0
    frac = pct / 100.0
    db_level = min_db * (1.0 - frac)
    amplitude_frac = 10 ** (db_level / 20.0)
    return amplitude_frac * 100.0


