_surface_lock_events = {}
_surface_lock_last_at = {}
_surface_lock_searched = set()
_surface_lock_unreadable = [0]


def _surface_lock_refers(value, target):
    """True when value is target or hangs off it through .base or .obj."""
    try:
        for _step in range(5):
            if value is target:
                return True
            value = getattr(value, "base", None) if getattr(value, "base", None) is not None else getattr(value, "obj", None)
            if value is None:
                return False
    except Exception:
        _surface_lock_unreadable[0] += 1
    return False


def _surface_lock_targets(surface):
    """The objects that hold a picture's locks; a locked sub-picture is followed to what locks it."""
    targets = []
    pending = [surface]
    seen = set()
    while pending and len(seen) < 12:
        item = pending.pop()
        if id(item) in seen:
            continue
        seen.add(id(item))
        for lock in item.get_locks():
            if isinstance(lock, pygame.Surface) and lock is not item:
                pending.append(lock)
            targets.append(lock)
    return targets


def _surface_lock_scan(container, path, depth, targets, found, deadline, seen):
    """Looks through a container, and containers inside it, for the lock holders."""
    if time.monotonic() > deadline or id(container) in seen:
        return
    seen.add(id(container))
    try:
        if isinstance(container, dict):
            items = list(container.items())
        else:
            items = list(enumerate(container))
    except Exception:
        _surface_lock_unreadable[0] += 1
        return
    for key, value in items:
        if any(_surface_lock_refers(value, t) for t in targets):
            found.append("%s[%s]" % (path, key))
        elif depth > 0 and isinstance(value, (dict, list, tuple, set, collections.deque)):
            _surface_lock_scan(value, "%s[%s]" % (path, key), depth - 1, targets, found, deadline, seen)
        elif depth > 0 and hasattr(value, "__dict__") and not isinstance(value, (type, types.ModuleType, types.FunctionType)):
            _surface_lock_scan(vars(value), "%s[%s].attr" % (path, key), depth - 1, targets, found, deadline, seen)


def _surface_lock_threads():
    """Where every thread is right now, as text."""
    names = {t.ident: t.name for t in threading.enumerate()}
    parts = []
    frames = sys._current_frames()
    try:
        for ident, frame in frames.items():
            code = frame.f_code
            parts.append("%s in %s (%s:%d)" % (names.get(ident, "?"), code.co_name, os.path.basename(code.co_filename or "?"), frame.f_lineno))
    finally:
        frames.clear()
    return "; ".join(parts)


def _surface_lock_find(surface):
    """Names what holds a picture's locks: a running function's variable, a stored container, or a frame kept alive."""
    started = time.monotonic()
    deadline = started + _SURFACE_LOCK_FIND_SECONDS
    targets = _surface_lock_targets(surface)
    found = []
    plain = [t for t in targets if not isinstance(t, pygame.Surface)]
    if not plain:
        found.append("a lock() that was never unlocked, on a %dx%d picture" % surface.get_size())
    own_codes = (_surface_lock_find.__code__, _surface_lock_scan.__code__, _surface_lock_threads.__code__)
    frames = sys._current_frames()
    try:
        for ident, top in frames.items():
            frame = top
            while frame is not None:
                if frame.f_code not in own_codes:
                    for name, value in list(frame.f_locals.items()):
                        if any(_surface_lock_refers(value, t) for t in plain):
                            found.append("variable %s in %s (%s:%d) of thread %s" % (name, frame.f_code.co_name, os.path.basename(frame.f_code.co_filename or "?"), frame.f_lineno, ident))
                frame = frame.f_back
    finally:
        frames.clear()
        top = frame = None
    modules = sorted(list(sys.modules.items()), key=lambda item: ("site-packages" in str(getattr(item[1], "__file__", "")), item[0]))
    seen = set()
    for name, module in modules:
        if plain and time.monotonic() < deadline and module is not None:
            _surface_lock_scan(vars(module), "module %s" % name, 2, plain, found, deadline, seen)
    for target in plain[:4]:
        for referrer in gc.get_referrers(target)[:8]:
            if isinstance(referrer, types.FrameType) and referrer.f_code not in own_codes:
                found.append("a kept frame of %s (%s:%d)" % (referrer.f_code.co_name, os.path.basename(referrer.f_code.co_filename or "?"), referrer.f_lineno))
            elif isinstance(referrer, (types.TracebackType, types.GeneratorType)):
                found.append("a kept %s" % type(referrer).__name__)
    referrer = None
    return "%s; %d lock(s); found in %.2fs, %d unreadable" % (" | ".join(found) if found else "no holder found", len(targets), time.monotonic() - started, _surface_lock_unreadable[0])


def _surface_lock_event(surface, label):
    """Writes the [SURFACE LOCK] line for a locked picture and says whether the caller may recover."""
    # WARNING: every incident gets its own SURFACE_LOCK_SWAPS_MAX repairs: the count starts again after a quiet _SURFACE_LOCK_INCIDENT_GAP_SECONDS, because a count that only ever grew used up the repairs in the first minutes and every later lock froze the picture for about 2 seconds (owner logs 2026-11-05, 8 incidents of 100+ errors each); the slow search for who holds the lock runs once per label, not once per incident.
    _now = time.monotonic()
    _last = _surface_lock_last_at.get(label)
    if _last is not None and _now - _last > _SURFACE_LOCK_INCIDENT_GAP_SECONDS:
        _surface_lock_events[label] = 0
    _surface_lock_last_at[label] = _now
    count = _surface_lock_events.get(label, 0) + 1
    _surface_lock_events[label] = count
    if count == 1 and label not in _surface_lock_searched:
        _surface_lock_searched.add(label)
        try:
            holders = _surface_lock_find(surface)
        except Exception as error:
            holders = "the holder search failed: %s: %s" % (type(error).__name__, error)
        log.error("[SURFACE LOCK] %s is locked at frame %d; holders: %s; threads: %s", label, _main_frame_clock["n"], holders, _surface_lock_threads())
    elif count == 1:
        log.error("[SURFACE LOCK] %s is locked again at frame %d, a new incident", label, _main_frame_clock["n"])
    elif count <= _SURFACE_LOCK_SWAPS_MAX:
        log.error("[SURFACE LOCK] %s is locked again (%d) at frame %d", label, count, _main_frame_clock["n"])
    else:
        log.error("[SURFACE LOCK] %s is locked again (%d) at frame %d; the recovery limit of %d is used up, the error goes through", label, count, _main_frame_clock["n"], _SURFACE_LOCK_SWAPS_MAX)
    return count <= _SURFACE_LOCK_SWAPS_MAX


_transition_static_noise_cache = {"key": None, "surface": None, "built_at": 0}


def _render_transition_static(screen, rect, target_aspect=None):
    """Renders the transition static burst inside `rect`; target_aspect overrides the global Aspect Ratio setting."""
    # WARNING: the guide preview box is a fixed 16:9 rect; only the video inside it is pillarboxed to 4:3, never the box.
    _static_sound_play()

    fit_rect = _aspect_fit_rect(rect, target_aspect=target_aspect)
    if fit_rect.width < rect.width or fit_rect.height < rect.height:
        screen.fill(_video_bar_color(), rect)
    rect = fit_rect

    sw, sh = rect.width // 4, rect.height // 4
    if sw > 0 and sh > 0:
        noise_style = db.config.get("static_noise_color", "white") if db is not None else "white"
        theme_hue = db.config.get("theme_bg_hue", 220) if (db is not None and noise_style == "theme") else 0

        now = pygame.time.get_ticks()
        key = (rect.width, rect.height, noise_style, theme_hue)
        cache = _transition_static_noise_cache
        if (cache["key"] != key or cache["surface"] is None
                or now - cache["built_at"] >= _STATIC_NOISE_REFRESH_MS):
            if noise_style == "rainbow":
                noise = np.random.randint(30, 170, (sw, sh, 3), dtype=np.uint8)
            elif noise_style == "theme":
                import colorsys as _theme_static_colorsys
                _bg_hue = theme_hue / 360.0
                _tr, _tg, _tb = _theme_static_colorsys.hsv_to_rgb(_bg_hue, 0.9, 1.0)
                theme_rgb = np.array([_tr, _tg, _tb], dtype=np.float32)
                intensity = np.random.randint(20, 86, (sw, sh, 1)).astype(np.float32)
                noise = (intensity * theme_rgb.reshape(1, 1, 3)).astype(np.uint8)
            elif noise_style == "white":
                white = np.random.randint(100, 155, (sw, sh, 1), dtype=np.uint8)
                noise = np.repeat(white, 3, axis=2)
            else:
                gray = np.random.randint(10, 55, (sw, sh, 1), dtype=np.uint8)
                noise = np.repeat(gray, 3, axis=2)
            surf = pygame.surfarray.make_surface(noise)
            _scaled_noise = pygame.transform.scale(surf, (rect.width, rect.height))
            cache["surface"] = _scaled_noise.convert() if pygame.display.get_surface() is not None else _scaled_noise
            cache["key"] = key
            cache["built_at"] = now
        if cache["surface"].get_locked() and _surface_lock_event(cache["surface"], "static noise picture"):
            cache["surface"] = None
            return
        if screen.get_locked() and _surface_lock_event(screen, "static draw target"):
            return
        screen.blit(cache["surface"], (rect.x, rect.y))
    else:
        screen.fill(COLOR_SCREEN_BLACK, rect)


def _static_transition_running():
    """True while a Static-style transition is on screen: its burst timer is running or a channel flip is waiting."""
    if _configured_transition_style() != "static":
        return False
    return (pygame.time.get_ticks() < app_state.get("channel_switch_static_until", 0)
            or _surf_origin_active())


def _channel_transition_over():
    """True once neither the black shield nor a Static-style burst or channel flip is running; the picture effects wait for it."""
    # WARNING: Static style keeps channel_switch_black_until at 0 and uses channel_switch_static_until, so checking the black timer alone calls a running Static burst over.
    if pygame.time.get_ticks() < app_state.get("channel_switch_black_until", 0):
        return False
    return not _static_transition_running()


_static_sound_state = {"last_stop": "", "last_stop_ms": 0, "stop_counts": {}, "logged_restart": ""}


def _static_sound_play():
    """Starts the Static noise at the current volume when it is not playing; one line names what stopped it last."""
    # WARNING: a mixer channel keeps the volume another sound gave it, so the channel the noise lands on is set back to full; the noise's own volume is set on the sound.
    if 'static_audio' not in globals() or static_audio is None or static_audio.get_num_channels() != 0:
        return
    channel = static_audio.play(-1)
    if channel is None:
        _log_swallowed("_static_sound_play: starting the Static noise", RuntimeError("no free mixer channel"))
        return
    channel.set_volume(1.0)
    static_audio.set_volume(_effective_audio_gain() * _effective_loudness_gain(_STATIC_AUDIO_GAIN))
    last = _static_sound_state["last_stop"]
    if last and last != _static_sound_state["logged_restart"]:
        _static_sound_state["logged_restart"] = last
        log.info("[STATIC SOUND] started again; last stopped by %s %d ms before",
                 last, pygame.time.get_ticks() - _static_sound_state["last_stop_ms"])


def _static_sound_stop(where):
    """Stops the Static noise if it is playing and remembers who stopped it; the 1st, 10th, 100th ... stop from one place writes a line."""
    if 'static_audio' not in globals() or static_audio is None or static_audio.get_num_channels() == 0:
        return
    static_audio.stop()
    _static_sound_state["last_stop"] = where
    _static_sound_state["last_stop_ms"] = pygame.time.get_ticks()
    count = _static_sound_state["stop_counts"].get(where, 0) + 1
    _static_sound_state["stop_counts"][where] = count
    if count == 10 ** (len(str(count)) - 1):
        log.info("[STATIC SOUND] stopped by %s%s", where, "" if count == 1 else " (seen %d times)" % count)


def _stop_transition_static():
    # WARNING: this must do nothing while a Static-style burst or flip is running, or the noise is cut every frame and never heard.
    if _static_transition_running():
        return
    _static_sound_stop("a transition that is not Static style")


def _mute_guard_engine(ch):
    """Which VLCEngineWrapper the mute guard should actually be watching/muting for the given channel."""
    if str(ch).zfill(2) == "03" and game_deck is not None and getattr(game_deck, "dvd_playback_active", False):
        return dvd_engine
    return vlc_engine


def _mute_guard_log(event, ch=None, filepath=None, extra=""):
    _engine = _mute_guard_engine(ch)
    _tid = threading.get_ident()
    _short_fp = os.path.basename(filepath) if filepath else None
    _cur_fp = os.path.basename(getattr(_engine, "current_filepath", "") or "") if _engine is not None else "?"
    try:
        _mute_now = _engine.player.audio_get_mute() if _engine is not None else "?"
    except Exception as _swallowed_error:
        _log_swallowed("_mute_guard_log: _mute_now = _engine.player.audio_get_mute() if _engine is not None ...", _swallowed_error)
        _mute_now = "?"
    print(f"[MUTE GUARD] {event} | thread={_tid} ch={ch} armed_for={_short_fp} "
          f"engine_current_file={_cur_fp} pending_unmute={app_state.get('_video_pending_unmute', False)} "
          f"audio_get_mute()={_mute_now} {extra}")


_mute_guard_lock = threading.Lock()
_mute_guard_generation = 0


def _arm_mute_guard_watchdog(ch, filepath):
    """Single spawn point for the buffering mute-guard watchdog."""
    global _mute_guard_generation
    with _mute_guard_lock:
        _mute_guard_generation += 1
        _generation = _mute_guard_generation
    threading.Thread(target=_watchdog_hold_mute_during_buffering,
                      args=(ch, filepath, _generation), daemon=True).start()
    return _generation


def _watchdog_hold_mute_during_buffering(ch, filepath=None, generation=None):
    _engine = _mute_guard_engine(ch)
    if _engine is None:
        return
    _mute_guard_log("watchdog SPAWNED", ch=ch, filepath=filepath)
    _deadline = time.time() + 5.0
    _landed_logged = False
    while time.time() < _deadline:
        _engine = _mute_guard_engine(ch)
        if _engine is None:
            return
        if filepath is not None and getattr(_engine, "current_filepath", None) != filepath:
            _mute_guard_log("watchdog BAIL (superseded)", ch=ch, filepath=filepath)
            return
        if generation is not None and generation != _mute_guard_generation:
            _mute_guard_log("watchdog BAIL (superseded, stale generation)", ch=ch, filepath=filepath)
            return
        if not app_state.get("_video_pending_unmute", False):
            _mute_guard_log("watchdog BAIL (flag cleared)", ch=ch, filepath=filepath)
            return
        try:
            _cur = _engine.player.audio_get_mute()
            if _cur != 1:
                _mute_guard_log("watchdog FORCE-REMUTE", ch=ch, filepath=filepath,
                                 extra=f"(saw audio_get_mute()={_cur}, forcing back to muted)")
                _engine.player.audio_set_mute(True)
            elif not _landed_logged:
                
                _landed_logged = True
        except Exception as _swallowed_error:
            _log_swallowed("_watchdog_hold_mute_during_buffering: _cur = _engine.player.audio_get_mute()", _swallowed_error)
            return
        time.sleep(0.1)
    _mute_guard_log("watchdog TIMED OUT (5s)", ch=ch, filepath=filepath)


def _lift_buffering_mute(ch, reason):
    if not app_state.get("_video_pending_unmute", False):
        return
    app_state["_video_pending_unmute"] = False
    _mute_guard_log("lift CLEARING flag", ch=ch, extra=f"reason={reason}")
    _still_muted = db.config.get("is_muted", False) if db is not None else False

    _engine = _mute_guard_engine(ch)
    if _engine is None:
        return
    if not _still_muted:
        try: _engine.player.audio_set_mute(False)
        except Exception as _swallowed_error:
            _log_swallowed("lifting the buffering mute: audio_set_mute(False)", _swallowed_error)
    else:
        try: _engine.player.audio_set_mute(True)
        except Exception as _swallowed_error:
            _log_swallowed("_lift_buffering_mute: _engine.player.audio_set_mute(True)", _swallowed_error)

    try:
        _post_lift_mute = _engine.player.audio_get_mute()
    except Exception as _swallowed_error:
        _log_swallowed("_lift_buffering_mute: _post_lift_mute = _engine.player.audio_get_mute()", _swallowed_error)
        _post_lift_mute = "?"
    if _post_lift_mute == -1:
        def _verify_mute_landed(_ch=ch, _reason=reason, _want_muted=_still_muted, _engine=_engine):
            _deadline = time.time() + 5.0
            _tries = 0
            while time.time() < _deadline:
                time.sleep(0.2)
                _tries += 1
                try:
                    if _engine is None:
                        return
                    _cur = _engine.player.audio_get_mute()
                except Exception as _swallowed_error:
                    _log_swallowed("checking the mute landed: reading the player mute state", _swallowed_error)
                    return
                if _cur != -1:
                    
                    return
                try:
                    _engine.player.audio_set_mute(_want_muted)
                    if db is not None:
                        _engine.set_volume(
                            db.config.get("global_volume", 70),
                            db.config.get("is_muted", False),
                        )
                except Exception as _swallowed_error:
                    _log_swallowed("checking the mute landed: forcing the wanted mute state", _swallowed_error)
                    return
            
        threading.Thread(target=_verify_mute_landed, daemon=True).start()


def _note_fresh_live_video_frame(ch):
    """Bookkeeping for a newly decoded live-TV frame, run by the render pass that consumes it."""
    app_state["_last_new_frame_ticks"] = pygame.time.get_ticks()
    app_state["_had_first_frame_this_tune"] = True
    _now_ticks = pygame.time.get_ticks()
    if (_now_ticks >= app_state.get("channel_switch_static_until", 0)
            and _now_ticks >= app_state.get("channel_switch_black_until", 0)):
        _stop_transition_static()
        _lift_buffering_mute(ch, "first-frame")
        app_state["_video_audio_hold_until"] = 0
    app_state["_boot_suppress_static"] = False


