COMMERCIAL_SUB_MENU_KEYS = ("Commercials", "Fade-in", "Fade-out")


def _reset_channel_lineup_after_clear(target_ch_str, ch_info):
    """After a Clear Media on the channel on screen, its saved lineup is dropped so the next resolve builds from what is left, as a file-explorer remove does."""
    if str(app_state.get("current_channel", "")).zfill(2) == str(target_ch_str).zfill(2):
        _plog = ch_info.setdefault("playback_log", {})
        _plog["sched_block_key"] = ""
        _set_saved_lineup(_plog, [], {}, groups=None)


def _execute_commercial_media_clear(target_ch_str, ch_info):
    """Clears everything the Commercials sub-menu holds (commercials, fade-in and fade-out) for one channel."""
    for key in COMMERCIAL_SUB_MENU_KEYS:
        ch_info.setdefault("schedules", {})[key] = []
    _reset_channel_lineup_after_clear(target_ch_str, ch_info)
    db.save_settings()
    invalidate_guide_cache()
    print(f"[CLEARED COMMERCIAL MEDIA] Channel {target_ch_str}.")


def _execute_holiday_media_clear(target_ch_str, ch_info):
    ch_info["holiday_schedules"] = {}
    _reset_channel_lineup_after_clear(target_ch_str, ch_info)
    db.save_settings()
    invalidate_guide_cache()
    print(f"[CLEARED HOLIDAY MEDIA] Storage wiped for Channel {target_ch_str}.")


def _execute_channel_media_clear(target_ch_str, ch_info):
    if ch_info.get("is_visualizer", False):
        ch_info["schedules"]["Music Tracks"] = []
    else:
        for key in media.channel_clear_schedule_keys():
            ch_info.setdefault("schedules", {})[key] = []
        ch_info["holiday_schedules"] = {}

    ch_info.pop("sched_cached_tracks",   None)
    ch_info.pop("marathon_anchor_epoch", None)
    ch_info.pop("playback_log",          None)
    ch_info.pop("playback_anchor", None)

    print(f"[CLEARED PROFILE] Storage wiped for Channel {target_ch_str}.")

    if app_state.get("current_channel", "") == target_ch_str:
        try:
            if vlc_engine is not None:
                vlc_engine.stop()
        except Exception as _ce:
            log.warning("[CLEAR CHANNEL] vlc_engine.stop() failed: %s", _ce)
        _static_sound_stop("Clear media on the channel")
        try:
            pygame.mixer.Channel(1).stop()
        except Exception as _swallowed_error:
            _log_swallowed("_execute_channel_media_clear: pygame.mixer.Channel(1).stop()", _swallowed_error)
        try:
            if pygame.mixer.music.get_busy():
                pygame.mixer.music.stop()
            pygame.mixer.music.unload()
        except Exception as _swallowed_error:
            _log_swallowed("_execute_channel_media_clear: if pygame.mixer.music.get_busy():", _swallowed_error)
        _clear_last_video_frame()
        app_state["is_playing_video"]            = False
        app_state["active_music_track_file"]     = ""
        app_state["music_owner"]                 = ""
        app_state["guide_preview_music_track"]   = ""
        app_state["last_scheduled_vis_track"]    = {}
        app_state["persistent_track_pool_cache"] = ""
        app_state["last_vlc_retry_at"]           = 0
        app_state["last_video_play_started_at"]  = 0

    db.save_settings()
    invalidate_guide_cache()


def _execute_clear_manual_roms():
    """"Clear Roms": wipes every console's manually-added and scanned ROM list."""
    if game_deck is not None:
        game_deck.console_roms_manual = {}
    db.config["console_roms_manual"] = {}
    db.save_settings()
    print("[GAMES] Clear Roms: manually-added ROM lists cleared for all consoles.")


def _any_manual_roms_exist():
    """Whether the system-wide "Clear Roms" button has anything to wipe."""
    if game_deck is None:
        return False
    return any(len(v) > 0 for v in (game_deck.console_roms_manual or {}).values())


def _execute_clear_console_manual_roms(console_key):
    """Per-console "Clear Roms": same as _execute_clear_manual_roms() but for a single console."""
    if game_deck is not None:
        game_deck.console_roms_manual.pop(console_key, None)
    db.config.setdefault("console_roms_manual", {}).pop(console_key, None)
    db.save_settings()
    print(f"[GAMES] Clear Roms: manually-added ROM list cleared for {console_key}.")


def _execute_clear_all_cores():
    """"Clear Cores": forgets every console's core and deletes the core files the app copied into main/cores; cores kept anywhere else are not touched and controller maps are kept."""
    from game_deck import is_console_core_key
    cfg = _read_emulator_config()
    forgotten = [k for k in list(cfg) if is_console_core_key(k)]
    for k in forgotten:
        cfg.pop(k, None)
    deleted, failed = _delete_tool_copies(False)
    if db is not None:
        db.save_settings()
    if _write_emulator_config(cfg):
        print(f"[GAMES] Clear Cores: forgot the core for {len(forgotten)} console(s); deleted {deleted} core file(s) the app had copied into main/cores"
              + (f"; {failed} could not be deleted" if failed else "") + "; cores kept anywhere else were not touched.")


def _execute_clear_all_bios():
    """"Clear BIOS": forgets every console's BIOS and deletes the BIOS files the app copied into main/cores; a BIOS kept anywhere else is not touched."""
    if db is None:
        return
    forgotten = [k for k, v in (db.config.get("active_bios", {}) or {}).items() if v]
    db.config["active_bios"] = {}
    deleted, failed = _delete_tool_copies(True)
    db.save_settings()
    if game_deck is not None:
        game_deck.refresh_from_config(db.config)
    print(f"[GAMES] Clear BIOS: forgot the BIOS for {len(forgotten)} console(s); deleted {deleted} BIOS file(s) the app had copied into main/cores"
          + (f"; {failed} could not be deleted" if failed else "") + "; a BIOS kept anywhere else was not touched.")


def _any_cores_exist():
    """Whether the system-wide "Clear Cores" button has anything to forget."""
    from game_deck import is_console_core_key
    cfg = getattr(game_deck, "emulator_config", None) if game_deck is not None else None
    if cfg is None:
        cfg = _read_emulator_config()
    if any(is_console_core_key(k) and v for k, v in cfg.items()):
        return True
    return any(not _tool_copy_is_bios(p) for p in _tool_copy_paths())


def _any_bios_exist():
    """Whether the system-wide "Clear BIOS" button has anything to forget or delete."""
    if db is None:
        return False
    if any(v for v in (db.config.get("active_bios", {}) or {}).values()):
        return True
    return any(_tool_copy_is_bios(p) for p in _tool_copy_paths())


