def _refresh_guide_row_stops_offscreen():
    """Populate guide_current_row_blocks/guide_current_row_stops for the highlighted row only."""
    global _guide_jump_scratch_surface
    _real_size = screen.get_size()
    if (_guide_jump_scratch_surface is None
            or _guide_jump_scratch_surface.get_size() != _real_size):
        _guide_jump_scratch_surface = pygame.Surface(_real_size)
    _lock_wait_t0 = time.monotonic()
    with _guide_build_lock:
        _lock_wait_ms = (time.monotonic() - _lock_wait_t0) * 1000.0
        if _lock_wait_ms > 5.0:
            _log_warn_throttled(
                "guide_row_stops_lock_wait",
                "[GUIDE] _refresh_guide_row_stops_offscreen waited %.1fms for "
                "_guide_build_lock (thread=%s)",
                _lock_wait_ms, threading.current_thread().name)
        app_state["_guide_stops_only_probe"] = True
        try:
            _guide_render_row_impl(_guide_jump_scratch_surface, app_state, db, active_theme)
        except Exception:
            log.warning(
                "[GUIDE DIAGNOSTIC] _refresh_guide_row_stops_offscreen "
                "failed for highlighted_guide_channel=%s (row stops left "
                "unchanged):", app_state.get("highlighted_guide_channel", "?"),
                exc_info=True)
        finally:
            app_state["_guide_stops_only_probe"] = False


_guide_jump_scratch_surface = None


def _resync_guide_stop_after_row_switch():
    """Re-resolves guide_selected_stop_key / guide_selected_abs_time against the row just switched onto."""
    _guide_dirty_event.set()
    curr_col = app_state.get("guide_col_pos", 0)
    _ch_str = str(app_state.get("selected_guide_channel", 5)).zfill(2)
    _expected_time_idx = get_current_guide_time_idx(app_state, db)
    _cached = get_cached_row_stops(_ch_str, expected_time_idx=_expected_time_idx)
    if _cached is not None:
        _blocks, _stops = _cached
        app_state["guide_current_row_blocks"] = _blocks
        app_state["guide_current_row_stops"] = _stops
    else:
        log.info("[GUIDE] row switch resync: cache miss for ch=%s "
                  "expected_time_idx=%s -- forcing offscreen repaint",
                  _ch_str, _expected_time_idx)
        _refresh_guide_row_stops_offscreen()
    # WARNING: the anchor is set only by explicit left/right movement; row switches read it but never write it.
    stops = sorted(app_state.get("guide_current_row_stops", []) or [], key=lambda s: s.get("abs", 0))
    _anchor_abs = app_state.get("guide_col_anchor_abs")
    if _anchor_abs is None:
        _anchor_abs = app_state.get("guide_selected_abs_time")
    if _anchor_abs is None:
        _anchor_abs = stops[0].get("abs", 0) if stops else 0
    app_state["guide_col_anchor_abs"] = _anchor_abs
    _owning = [s for s in stops if s.get("abs", 0) <= _anchor_abs]
    if _owning:
        _owner = max(_owning, key=lambda s: s.get("abs", 0))
    elif stops:
        _owner = stops[0]
    else:
        _owner = None

    if _owner is not None:
        app_state["guide_selected_stop_key"] = _owner.get("key")
        app_state["guide_selected_abs_time"] = _owner.get("abs")
        app_state["guide_col_pos"] = min(_owner.get("col", 0), get_guide_num_cols(db) - 1)
    else:
        log.warning("[GUIDE] row switch resync: anchor_abs=%s (was curr_col=%s) -- "
                     "no stops found on new row, highlight left unchanged",
                     _anchor_abs, curr_col)


def _guide_jump_col(direction, _source="unknown"):
    _guide_dirty_event.set()
    curr_col = app_state.get("guide_col_pos", 0)
    _guide_last_col = get_guide_num_cols(db) - 1
    stops = sorted(
        (app_state.get("guide_current_row_stops", []) or
         [{"col": 0, "abs": 0, "key": ("col", 0)}]),
        key=lambda s: s.get("abs", 0),
    )

    def _resolve_curr_abs():
        _key = app_state.get("guide_selected_stop_key")
        if _key is not None:
            for _s in stops:
                if _s.get("key") == _key:
                    return _s.get("abs", 0)
        _preceding = [s for s in stops if s.get("col", 0) <= curr_col]
        if _preceding:
            return max(_preceding, key=lambda s: (s.get("col", 0), s.get("abs", 0))).get("abs", 0)
        return stops[0].get("abs", 0)

    curr_abs = _resolve_curr_abs()

    def _sync_to_edge_stop(edge_col):
        _owning = [s for s in stops if s.get("col", 0) <= edge_col]
        if _owning:
            _owner = max(_owning, key=lambda s: (s.get("col", 0), s.get("abs", 0)))
            app_state["guide_selected_stop_key"] = _owner.get("key")
            app_state["guide_selected_abs_time"] = _owner.get("abs")
            app_state["guide_col_anchor_abs"] = _owner.get("abs")
        else:
            log.warning("[GUIDE] sync_to_edge edge_col=%s: no owning stop found "
                         "(highlight left unchanged -- this is a desync condition "
                         "if it ever shows up)", edge_col)

    if direction > 0:
        target = next((s for s in stops
                       if s.get("abs", 0) > curr_abs
                       and s.get("col", 0) > curr_col), None)
        if target is None:
            target = next((s for s in stops if s.get("abs", 0) > curr_abs), None)
        if target is not None:
            app_state["guide_col_pos"] = min(target.get("col", 0), _guide_last_col)
            app_state["guide_selected_stop_key"] = target.get("key")
            app_state["guide_selected_abs_time"] = target.get("abs")
            app_state["guide_col_anchor_abs"] = target.get("abs")
            return
        if curr_col < _guide_last_col:
            _edge_owning = [s for s in stops if s.get("col", 0) <= _guide_last_col]
            _edge_owner = max(_edge_owning, key=lambda s: (s.get("col", 0), s.get("abs", 0))) if _edge_owning else None
            if _edge_owner is not None and _edge_owner.get("key") == app_state.get("guide_selected_stop_key"):
                app_state["guide_col_pos"] = _guide_last_col
            else:
                app_state["guide_col_pos"] = _guide_last_col
                _sync_to_edge_stop(_guide_last_col)
                return
        _num_cols = get_guide_num_cols(db)
        _now_dt = broadcast_clock.now().replace(tzinfo=None)
        _sys_live_c_idx = (_now_dt.hour * 2) + (1 if _now_dt.minute >= 30 else 0)
        _old_shift = app_state.get("selected_guide_time_idx", 0)
        # WARNING: the fallback numbers below must match GUIDE_TIME_STEP_MAX_SHIFTS in performance_governor.py; they are used only when that module fails to import.
        _MAX_STEP3_SHIFTS = performance_governor.GUIDE_TIME_STEP_MAX_SHIFTS if performance_governor is not None else 8
        _prev_clamped_idx = _sys_live_c_idx + _old_shift
        _next_target = None
        _new_stops = []
        for _step in range(1, _MAX_STEP3_SHIFTS + 1):
            _raw_shift = _old_shift + _step
            _clamped_idx = clamp_guide_time_idx(_sys_live_c_idx + _raw_shift, _num_cols)
            app_state["selected_guide_time_idx"] = _clamped_idx - _sys_live_c_idx
            _refresh_guide_row_stops_offscreen()
            _new_stops = sorted(app_state.get("guide_current_row_stops", []) or [],
                                 key=lambda s: s.get("abs", 0))
            _next_target = next((s for s in _new_stops if s.get("abs", 0) > curr_abs), None)
            if _next_target is not None:
                break
            if _clamped_idx == _prev_clamped_idx:
                break
            _prev_clamped_idx = _clamped_idx
        if _next_target is not None:
            app_state["guide_col_pos"] = min(_next_target.get("col", 0), _guide_last_col)
            app_state["guide_selected_stop_key"] = _next_target.get("key")
            app_state["guide_selected_abs_time"] = _next_target.get("abs")
            app_state["guide_col_anchor_abs"] = _next_target.get("abs")
        elif _new_stops:
            app_state["guide_col_pos"] = _guide_last_col
            app_state["guide_selected_stop_key"] = _new_stops[-1].get("key")
            app_state["guide_selected_abs_time"] = _new_stops[-1].get("abs")
            app_state["guide_col_anchor_abs"] = _new_stops[-1].get("abs")
        else:
            log.warning("[GUIDE] jump_col forward: render produced no stops at all "
                         "(curr_abs=%s) -- highlight state left untouched", curr_abs)

    else:
        target = next((s for s in reversed(stops) if s.get("abs", 0) < curr_abs), None)
        if target is not None:
            app_state["guide_col_pos"] = max(target.get("col", 0), 0)
            app_state["guide_selected_stop_key"] = target.get("key")
            app_state["guide_selected_abs_time"] = target.get("abs")
            app_state["guide_col_anchor_abs"] = target.get("abs")
            return
        if curr_col > 0:
            _edge_owning0 = [s for s in stops if s.get("col", 0) <= 0]
            _edge_owner0 = max(_edge_owning0, key=lambda s: (s.get("col", 0), s.get("abs", 0))) if _edge_owning0 else None
            if _edge_owner0 is not None and _edge_owner0.get("key") == app_state.get("guide_selected_stop_key"):
                app_state["guide_col_pos"] = 0
            else:
                app_state["guide_col_pos"] = 0
                _sync_to_edge_stop(0)
                return
        _num_cols = get_guide_num_cols(db)
        _now_dt = broadcast_clock.now().replace(tzinfo=None)
        _sys_live_c_idx = (_now_dt.hour * 2) + (1 if _now_dt.minute >= 30 else 0)
        _old_shift = app_state.get("selected_guide_time_idx", 0)
        # WARNING: the fallback numbers below must match GUIDE_TIME_STEP_MAX_SHIFTS in performance_governor.py; they are used only when that module fails to import.
        _MAX_STEP3_SHIFTS = performance_governor.GUIDE_TIME_STEP_MAX_SHIFTS if performance_governor is not None else 8
        _prev_clamped_idx = _sys_live_c_idx + _old_shift
        _prev_target = None
        _new_stops = []
        for _step in range(1, _MAX_STEP3_SHIFTS + 1):
            _raw_shift = _old_shift - _step
            _clamped_idx = clamp_guide_time_idx(_sys_live_c_idx + _raw_shift, _num_cols)
            app_state["selected_guide_time_idx"] = _clamped_idx - _sys_live_c_idx
            _refresh_guide_row_stops_offscreen()
            _new_stops = sorted(app_state.get("guide_current_row_stops", []) or [],
                                 key=lambda s: s.get("abs", 0))
            _prev_target = next((s for s in reversed(_new_stops) if s.get("abs", 0) < curr_abs), None)
            if _prev_target is not None:
                break
            if _clamped_idx == _prev_clamped_idx:
                break
            _prev_clamped_idx = _clamped_idx
        if _prev_target is not None:
            app_state["guide_col_pos"] = max(_prev_target.get("col", 0), 0)
            app_state["guide_selected_stop_key"] = _prev_target.get("key")
            app_state["guide_selected_abs_time"] = _prev_target.get("abs")
            app_state["guide_col_anchor_abs"] = _prev_target.get("abs")
        elif _new_stops:
            app_state["guide_col_pos"] = 0
            app_state["guide_selected_stop_key"] = _new_stops[0].get("key")
            app_state["guide_selected_abs_time"] = _new_stops[0].get("abs")
            app_state["guide_col_anchor_abs"] = _new_stops[0].get("abs")
        else:
            log.warning("[GUIDE] jump_col backward: render produced no stops at all "
                         "(curr_abs=%s) -- highlight state left untouched", curr_abs)


def _guide_step_row(step, resync_stop):
    """Moves the guide highlight one channel row up (-1) or down (+1), wrapping at both ends and scrolling the window; resync_stop also re-aims the time highlight at the new row."""
    if not db:
        return
    _allowed = [str(_i).zfill(2) for _i in range(5, 45) if db.channels_db.get(str(_i).zfill(2), {}).get("active", True)]
    _target = menu_nav.guide_row_step(_allowed, app_state.get("selected_guide_channel", 5), app_state.get("guide_row_offset", 0), get_guide_visible_rows(db), step)
    if _target is None:
        return
    app_state["selected_guide_channel"] = int(_target[0])
    app_state["highlighted_guide_channel"] = _target[0]
    _clear_last_video_frame(context="preview")
    _arm_guide_preview_transition()
    app_state["guide_row_offset"] = _target[1]
    if resync_stop:
        _resync_guide_stop_after_row_switch()


# WARNING: the fallback number below must match GUIDE_STOP_MATCH_SECONDS in performance_governor.py; it is used only when that module fails to import.
_GUIDE_STOP_MATCH_SECONDS = performance_governor.GUIDE_STOP_MATCH_SECONDS if performance_governor is not None else 2.0


def _guide_keep_highlight_in_view():
    """Re-aims the guide highlight at the left-most visible show when the live clock slides the window past the highlighted one."""
    _target = app_state.get("guide_selected_abs_time")
    if not db or _target is None:
        app_state["_guide_live_idx_seen"] = None
        return
    _now_dt = broadcast_clock.now().replace(tzinfo=None)
    _live_idx = (_now_dt.hour * 2) + (1 if _now_dt.minute >= 30 else 0)
    _seen = app_state.get("_guide_live_idx_seen")
    app_state["_guide_live_idx_seen"] = _live_idx
    if _seen is None or _seen == _live_idx:
        return
    _ch_str = str(app_state.get("selected_guide_channel", 5)).zfill(2)
    _cached = get_cached_row_stops(_ch_str, expected_time_idx=get_current_guide_time_idx(app_state, db))
    if _cached is None:
        _refresh_guide_row_stops_offscreen()
        _stops = app_state.get("guide_current_row_stops", []) or []
    else:
        _stops = _cached[1]
    if any(abs(_s.get("abs", 0) - _target) <= _GUIDE_STOP_MATCH_SECONDS for _s in _stops):
        return
    _resync_guide_stop_after_row_switch()


def _guide_snap_highlight_to_stop():
    """Moves the guide highlight onto the stop that owns its time when that time is no longer a stop of the highlighted row's last drawing, so the highlight never sits on nothing or on a commercial break sliver."""
    if not db:
        return
    _ch_str = str(app_state.get("selected_guide_channel", 5)).zfill(2)
    _cached = get_cached_row_stops(_ch_str, expected_time_idx=get_current_guide_time_idx(app_state, db))
    if _cached is None:
        return
    _stops = sorted(_cached[1] or [], key=lambda s: s.get("abs", 0))
    if not _stops:
        return
    _target = app_state.get("guide_selected_abs_time")
    if _target is not None:
        # WARNING: a stop's start time can drift a fraction of a second between two drawings (a show on air is placed from the clock), so a stop that is within _GUIDE_STOP_MATCH_SECONDS of the highlight time IS the highlight's stop; matching exactly threw the highlight back to the stop on its left.
        _near = [_s for _s in _stops if abs(_s.get("abs", 0) - _target) <= _GUIDE_STOP_MATCH_SECONDS]
        if _near:
            _best = min(_near, key=lambda _s: abs(_s.get("abs", 0) - _target))
            if _best.get("abs") != _target or _best.get("key") != app_state.get("guide_selected_stop_key"):
                app_state["guide_selected_stop_key"] = _best.get("key")
                app_state["guide_selected_abs_time"] = _best.get("abs")
                app_state["guide_col_anchor_abs"] = _best.get("abs")
            return
    if _target is None:
        _now_dt = broadcast_clock.now().replace(tzinfo=None)
        _target = _now_dt.hour * 3600 + _now_dt.minute * 60 + _now_dt.second
    _owning = [_s for _s in _stops if _s.get("abs", 0) <= _target]
    _owner = max(_owning, key=lambda s: s.get("abs", 0)) if _owning else _stops[0]
    _log_warn_throttled("guide_highlight_snapped",
                        "[GUIDE] ch%s highlight time %s was on no stop of the row; moved to the stop at %s",
                        _ch_str, app_state.get("guide_selected_abs_time"), _owner.get("abs"))
    app_state["guide_selected_stop_key"] = _owner.get("key")
    app_state["guide_selected_abs_time"] = _owner.get("abs")
    app_state["guide_col_pos"] = min(_owner.get("col", 0), get_guide_num_cols(db) - 1)
    _guide_dirty_event.set()


