_MODULE_DEFINED.set()

while True:
    _prof_begin()
    _main_frame_clock["start"] = time.monotonic()
    _main_frame_clock["n"] += 1

    # ========================================================================
    # SECTION: Frame setup, heartbeat & housekeeping
    # ========================================================================

    if screen is globals().get("_virtual_screen_surf"):
        screen = pygame.display.get_surface() or screen

    if 'db' in globals() and db is not None:
        _theme_key = db.config.get("current_theme", "DefaultBlueGreen")
        active_theme = db.themes.get(_theme_key) or db.themes.get("DefaultBlueGreen") \
            or dict(DEFAULT_THEME)
    else:
        active_theme = dict(DEFAULT_THEME)
        
    events = pygame.event.get()
    now_ticks = pygame.time.get_ticks()
    app_state["_nav_frame_id"] = app_state.get("_nav_frame_id", 0) + 1

    _loop_gap_ms = now_ticks - app_state.get("_loop_prev_ticks", now_ticks)
    app_state["_loop_prev_ticks"] = now_ticks
    if _loop_gap_ms >= _LOOP_BLOCKED_GAP_MS:
        app_state["_last_new_frame_ticks"] = min(
            now_ticks, app_state.get("_last_new_frame_ticks", 0) + _loop_gap_ms)

    _sweep_all_recovered_dead_drives()
    _commit_requested_scheduling_modes()

    if (app_state.get("show_menu", False)
            and app_state.get("menu_layer") not in ("REMOTE_REMAP_CAPTURE", "NUMBER_REMAP_CAPTURE")
            and not (app_state.get("menu_layer") == "DVD_BTN_MAP" and app_state.get("dvd_map_capturing", False))):
        _mnav_matrix = pygame.key.get_pressed()
        _mnav_held_set = app_state["_held_keys"]

        # WARNING: opposite-direction nav keys both held at once almost always means a stale _held_keys entry from a swallowed KEYUP, not two real keys.
        for _mnav_a, _mnav_b in ((pygame.K_w, pygame.K_s), (pygame.K_a, pygame.K_d)):
            if _mnav_a in _mnav_held_set and _mnav_b in _mnav_held_set:
                _a_phys = bool(_mnav_matrix[_mnav_a])
                _b_phys = bool(_mnav_matrix[_mnav_b])
                _mnav_down_ticks = app_state.get("_held_key_down_ticks", {})
                _mnav_drop = menu_nav.hold_conflict(_a_phys, _b_phys, _mnav_down_ticks.get(_mnav_a, 0), _mnav_down_ticks.get(_mnav_b, 0))
                if (_mnav_drop == menu_nav.DROP_BOTH
                        and not menu_nav.hold_released(events, _mnav_a, app_state["_held_keys_source"])
                        and not menu_nav.hold_released(events, _mnav_b, app_state["_held_keys_source"])):
                    log.warning("[MENU NAV DEBUG] SUSPECTED STUCK KEY: saw both %s and %s "
                                "held via _held_keys with matrix=(%s=%s, %s=%s) -- "
                                "clearing both and stopping repeat",
                                pygame.key.name(_mnav_a), pygame.key.name(_mnav_b),
                                pygame.key.name(_mnav_a), _a_phys, pygame.key.name(_mnav_b), _b_phys)
                if _mnav_drop in (menu_nav.DROP_FIRST, menu_nav.DROP_BOTH):
                    _mnav_held_set.discard(_mnav_a)
                if _mnav_drop in (menu_nav.DROP_SECOND, menu_nav.DROP_BOTH):
                    _mnav_held_set.discard(_mnav_b)

        _mnav_key = menu_nav.hold_pick(_mnav_held_set, (pygame.K_w, pygame.K_a, pygame.K_s, pygame.K_d))
        _mnav_hold = app_state["_hold_menu"]

        if _mnav_key is not None:
            _mnav_released = menu_nav.hold_released(events, _mnav_key, app_state["_held_keys_source"])
            _mnav_held_ms = now_ticks - _mnav_hold.start if _mnav_hold.key == _mnav_key else 0
            _mnav_since = now_ticks - _mnav_hold.last if _mnav_hold.key == _mnav_key else 0
            _mnav_step = menu_nav.hold_step(
                menu_nav.hold_rule(_mnav_key), _mnav_hold, _mnav_key, now_ticks, bool(_mnav_matrix[_mnav_key]),
                _mnav_released, menu_nav.HOLD_STUCK_MS["menu"], _MENU_NAV_REPEAT_DELAY_MS)
            if _mnav_step == menu_nav.HOLD_STUCK:
                log.warning("[MENU NAV DEBUG] SUSPECTED STUCK KEY: key=%s has been "
                            "'held' for %sms via _held_keys only (SDL pressed_keys_matrix "
                            "says NOT pressed) -- self-healing by releasing it now "
                            "(probably a swallowed KEYUP from a past focus loss/remap "
                            "event)", pygame.key.name(_mnav_key), _mnav_held_ms)
                app_state["_held_keys"].discard(_mnav_key)
            elif _mnav_step == menu_nav.HOLD_REPEAT:
                _mnav_same_layer = app_state.get("_held_key_down_layer", {}).get(_mnav_key) == app_state.get("menu_layer")
                _mnav_repeat_ok = menu_nav.repeat_allowed(
                    app_state.get("menu_layer"), _mnav_key,
                    suppressed=bool(app_state.get("editing_channel_name", False)
                                    or app_state.get("editing_server_slot_name", False)
                                    or app_state.get("show_clear_confirm", False)
                                    or app_state.get("show_splash", False)
                                    or app_state.get("show_quit_confirm", False)
                                    or app_state.get("show_restart_confirm", False)
                                    or app_state.get("file_explorer_active", False)))
                if not _mnav_released and _mnav_same_layer and _mnav_repeat_ok:
                    events.append(pygame.event.Event(
                        pygame.KEYDOWN, key=_mnav_key, synthetic=True, menu_repeat=True))
                    _menu_nav_trace("repeat", _mnav_key,
                                    "held_ms=%d since_last=%d matrix_down=%s batch=%d" % (
                                        _mnav_held_ms, _mnav_since, bool(_mnav_matrix[_mnav_key]), len(events)))
        else:
            _mnav_hold.clear()

    _fgap_last = app_state.get("_frame_gap_last_ticks")
    if _fgap_last is not None:
        _fgap_ms = now_ticks - _fgap_last
        _last_frame_gap_ms = _fgap_ms
        _governor_feed_frame(_fgap_ms)
        if performance_governor is not None:
            performance_governor.set_game_active(_is_game_actively_playing())
        _log_frame_time_sample(_fgap_ms, app_state.get("current_channel"))
        if health_monitor is not None:
            health_monitor.explain_gap(_fgap_ms, "ch%s%s" % (app_state.get("current_channel"), ", guide open" if app_state.get("current_channel") == "04" else ""))
        if _fgap_ms >= 200:
            _fgap_threads = (health_monitor.thread_groups_text() if health_monitor is not None
                             else ", ".join(t.name for t in threading.enumerate() if t.is_alive()))
            log.warning(
                "[FRAME GAP] iteration took %sms (top-of-loop to top-of-loop), "
                "channel=%s, guide_open=%s, alive_threads=[%s]",
                _fgap_ms, app_state.get("current_channel"),
                app_state.get("current_channel") == "04", _fgap_threads,
            )
    app_state["_frame_gap_last_ticks"] = now_ticks

    _run_pending_loudness_engine_swap()
    _run_deferred_dvd_engine_rebuild()
    _reassert_live_stereo_mode_throttled()

    _hb_last = app_state.get("_heartbeat_last_ticks", 0)
    if now_ticks - _hb_last >= 15000:
        app_state["_heartbeat_last_ticks"] = now_ticks
        print(f"[HEARTBEAT] main loop alive at {now_ticks}ms, "
              f"channel={app_state.get('current_channel')}, "
              f"fullscreen={app_state.get('is_fullscreen')}", flush=True)
        _health_watch_instance_locks()

    if (sys.platform == "win32" and pygame_hwnd
            and app_state.get("is_fullscreen", False)
            and now_ticks - app_state.get("_focus_watchdog_last_ms", -10_000) >= 1500):
        app_state["_focus_watchdog_last_ms"] = now_ticks
        try:
            u32 = ctypes.windll.user32
            fg_hwnd = u32.GetForegroundWindow()
            if fg_hwnd != pygame_hwnd:
                if u32.IsIconic(pygame_hwnd):
                    print(f"[WINDOW] Focus watchdog: window is minimized (user-initiated), "
                          f"NOT forcing focus back. fg_hwnd={fg_hwnd} pygame_hwnd={pygame_hwnd}")
                else:
                    _watchdog_ok = _win32_force_foreground(pygame_hwnd)
                    print(f"[WINDOW] Focus watchdog: foreground mismatch, re-grabbed focus. "
                          f"fg_hwnd_before={fg_hwnd} pygame_hwnd={pygame_hwnd} success={_watchdog_ok}")
        except Exception as _watchdog_err:
            log.warning(f"[WINDOW] Focus watchdog error (non-fatal): {_watchdog_err}")

    if menu_nav.digit_entry_due(app_state.get("digit_buffer", ""), app_state.get("digit_timer", 0), now_ticks):
        final_ch = menu_nav.digit_entry_channel(app_state["digit_buffer"])
        _digit_count = len(app_state["digit_buffer"])
        app_state["digit_buffer"] = ""
        app_state["digit_timer"] = 0
        
        if _typed_channel_valid(final_ch):
            print(f"[TUNER] digit_buffer resolved ({_digit_count} digit(s)): tuning to {final_ch}")
            if _surf_origin_active():
                _tune_after_flip(final_ch, is_surfing=True)
            else:
                change_channel(final_ch, is_surfing=True)

    _surf_commit_if_due(now_ticks, events)
    _surf_recover_if_stuck()

    if app_state["current_channel"] == "04":
        _guide_keep_highlight_in_view()
        _guide_snap_highlight_to_stop()
        if (now_ticks >= app_state.get("guide_inactivity_timer", 0)
                and not app_state.get("file_explorer_active", False)
                and not app_state.get("show_menu", False)):
            target_burn_in_safe_ch = str(app_state.get("highlighted_guide_channel", "05")).zfill(2)
            print(f"[ANTI-BURN-IN SHIELD] Inactivity limit reached. Forcing fullscreen re-entry to Channel: {target_burn_in_safe_ch}")
            app_state["loaded_preview_path_cache"] = ""
            change_channel(target_burn_in_safe_ch)
            continue

    try:
        while not explorer_queue.empty():
            queued_item = explorer_queue.get_nowait()
            if isinstance(queued_item, dict):
                target_ch = str(queued_item.get("ch", "")).zfill(2)
                _raw_block = queued_item.get("block", "")
                if not _raw_block:
                    log.warning(
                        "[FILE EXPLORER] schedule commit for ch%s arrived with no block "
                        "in its frozen context -- defaulting to 'Morning' rather than "
                        "silently misfiling into whatever block was actually intended. "
                        "This almost always means _fe_open() was called with an empty "
                        "'block' in its context dict; check the call site.",
                        target_ch,
                    )
                active_b  = _raw_block or "Morning"
                files_list = queued_item.get("files", [])
                # WARNING: this payload carries the full desired final list, not just additions.
                _is_reconcile_payload = True
            else:
                files_list = queued_item
                _is_reconcile_payload = False
                target_ch = str(app_state["selected_channel_row"]).zfill(2)
                ch_info_cache = db.channels_db.get(target_ch, {}) if db is not None else {}
                if ch_info_cache.get("is_visualizer", False):
                    active_b = "Music Tracks"
                else:
                    sub_r_cached = app_state.get("sub_menu_row_index", 1)
                    sub_c_cached = app_state.get("sub_menu_col_index", 0)
                    if ch_info_cache.get("scheduling_mode", "random_slots") == "marathon":
                        active_b = "Marathon"
                    elif (ch_info_cache.get("scheduling_mode", "random_slots") != "marathon"
                          and ch_info_cache.get("block_mode", "full_day") == "full_day"):
                        active_b = "Full Day"
                    else:
                        _folder_row_cached = 5
                        if ch_info_cache.get("block_mode", "full_day") == "six_block":
                            folder_map = {
                                (_folder_row_cached, _ci): _bn
                                for _ci, _bn in enumerate(SIX_HOUR_BLOCK_NAMES)
                            }
                        else:
                            folder_map = {
                                (_folder_row_cached, 0): "Morning",
                                (_folder_row_cached, 1): "Evening",
                                (_folder_row_cached, 2): "Night",
                            }
                        active_b = folder_map.get((sub_r_cached, sub_c_cached), "Morning")

            if (files_list or _is_reconcile_payload) and db is not None and target_ch:
                ch_info_cache = db.channels_db.get(target_ch, {})

                _existing_schedules_snapshot = ch_info_cache.get("schedules", {})
                _channel_was_empty_before_write = not any(
                    _existing_schedules_snapshot.get(_blk) for _blk in _existing_schedules_snapshot
                )

                if "schedules" not in db.channels_db[target_ch]:
                    db.channels_db[target_ch]["schedules"] = {}

                existing_entries = db.channels_db[target_ch]["schedules"].get(active_b, [])
                if _is_reconcile_payload:
                    # WARNING: files_list is the full desired final set for this block: a replace, not an append.
                    new_entries, added_paths, removed_n, dupe_n = _reconcile_schedule_entries(
                        existing_entries, files_list)
                    db.channels_db[target_ch]["schedules"][active_b] = new_entries
                    
                    newly_added_paths = added_paths
                    print(f"[FILE EXPLORER] (schedule) {active_b} -> {len(new_entries)} file(s) "
                          f"for ch {target_ch} (+{len(added_paths)} new, -{removed_n} removed"
                          + (f", {dupe_n} exact-name duplicate(s) skipped" if dupe_n else "") + ")")
                else:
                    deduped_files = _dedupe_incoming_files(existing_entries, files_list)
                    _dupe_count = len(files_list) - len(deduped_files)
                    
                    for file_path in deduped_files:
                        fallback_dur = -1
                        new_entry = {"path": os.path.normpath(file_path), "duration": fallback_dur}
                        existing_entries.append(new_entry)
                    db.channels_db[target_ch]["schedules"][active_b] = existing_entries
                    newly_added_paths = deduped_files
                    print(f"[FILE EXPLORER] (schedule, append-fallback) {active_b} -> "
                          f"{len(existing_entries)} file(s) for ch {target_ch} "
                          f"(+{len(deduped_files)} new, {_dupe_count} duplicate(s) skipped)")

                _plog_invalidate = db.channels_db[target_ch].setdefault("playback_log", {})
                _plog_invalidate["sched_block_key"] = ""
                _plog_invalidate["sched_cached_tracks"] = []
                _plog_invalidate["sched_cached_durations"] = {}

                if _channel_was_empty_before_write and newly_added_paths:
                    _now_stamp = broadcast_clock.now().replace(tzinfo=None)
                    _onair_since = db.config.get("guide_onair_since", {})
                    _onair_since[target_ch] = [
                        _now_stamp.year,
                        _now_stamp.timetuple().tm_yday,
                        ((_now_stamp.hour * 3600 + _now_stamp.minute * 60) // 1800) * 1800,
                    ]
                    db.config["guide_onair_since"] = _onair_since

                db.save_settings_async()
                if newly_added_paths:
                    _warm_new_file_lengths(newly_added_paths)
                    _queue_new_channel_first_show(target_ch)
                

                if str(app_state.get("current_channel", "")).zfill(2) == str(target_ch).zfill(2):
                    _ch_info_add = db.channels_db.get(target_ch, {})
                    _smode_add   = _ch_info_add.get("scheduling_mode", "random_slots")
                    _bmode_add   = _ch_info_add.get("block_mode", "full_day")
                    _now_h_add   = broadcast_clock.now().hour

                    _bseed_offsets_add = {
                        "Morning": 100, "Evening": 200, "Night": 300, "Full Day": 500,
                    }
                    for _sbi_add, _sbn_add in enumerate(SIX_HOUR_BLOCK_NAMES):
                        _bseed_offsets_add[_sbn_add] = 600 + _sbi_add * 100

                    if _smode_add == "marathon":
                        _live_block_add = "Marathon"
                    elif _bmode_add == "full_day":
                        _live_block_add = "Full Day"
                    elif _bmode_add == "six_block":
                        _live_block_add = SIX_HOUR_BLOCKS[_now_h_add // 4][0]
                    else:
                        if 4 <= _now_h_add < 12:
                            _live_block_add = "Morning"
                        elif 12 <= _now_h_add < 20:
                            _live_block_add = "Evening"
                        else:
                            _live_block_add = "Night"

                    _always_retune_add = {
                        "Commercials", "Intros", "Outros",
                        "Full Day", "Marathon", "Music Tracks",
                    }

                    if active_b in _always_retune_add or active_b == _live_block_add:
                        _plog_add = db.channels_db[target_ch].setdefault("playback_log", {})
                        _plog_add["sched_block_key"] = ""
                        _plog_add["sched_cached_tracks"] = []
                        _plog_add["sched_cached_durations"] = {}
                    else:
                        
                        try:
                            _plog_add   = _ch_info_add.setdefault("playback_log", {})
                            _scheds_add = _ch_info_add.get("schedules", {})
                            _items_add  = _scheds_add.get(active_b, [])
                            _path_exists_add = os.path.exists
                            _raw_add = build_raw_tracks(
                                _items_add, _path_exists_add)
                            _pend_add = build_pending_tracks(
                                _items_add, _path_exists_add)
                            if _raw_add:
                                _now_add = broadcast_clock.now().replace(tzinfo=None)
                                _boff_add = _bseed_offsets_add.get(active_b, 0)
                                _seed_date_add = block_start_date(_now_add, active_b)
                                _seed_add = block_day_seed(
                                    _seed_date_add, target_ch, _boff_add)
                                _order_seed_add = _start_order_seed(
                                    _ch_info_add, _boff_add)
                                _sp_snap_add = copy.deepcopy(_plog_add.get("show_pos", {}))
                                _pt_add = max(0, _ch_info_add.get(
                                    "pair_threshold_minutes", 15)) * 60
                                _eom_add = _ch_info_add.get(
                                    "episode_order_mode", "sequential")
                                _so_add = (_plog_add.get("show_order", {})
                                           .get(active_b))
                                _bdur_add = block_length_seconds(active_b)

                                _vt_add, _, _ = build_block_rotation(
                                    _raw_add, _ch_info_add, _sp_snap_add,
                                    _seed_add, _bdur_add, target_ch,
                                    _so_add, _order_seed_add,
                                    pending_tracks=_pend_add,
                                )
                                if _vt_add:
                                    _bkey_add = block_key_for(_now_add, active_b)
                                    _cpaths_add = lineup_paths(_vt_add)
                                    _cdur_add = _snapshot_track_durations(_vt_add)
                                    _brc_add = _plog_add.setdefault(
                                        "block_rotation_cache", {})
                                    _brc_add[_bkey_add] = {
                                        "tracks": [p for p in _cpaths_add if p],
                                        "durations": _cdur_add,
                                        "groups": lineup_groups(_vt_add, _pt_add),
                                        "pairing_rule_version": SHORT_EPISODE_PAIRING_VERSION,
                                    }
                                    _write_prebuilt_block_to_hub(target_ch, _bkey_add, _vt_add, _raw_add)
                                    if len(_brc_add) > BLOCK_ROTATION_CACHE_MAX_BLOCKS:
                                        for _k_prune in sorted(_brc_add)[
                                                :len(_brc_add) - BLOCK_ROTATION_CACHE_MAX_BLOCKS]:
                                            _brc_add.pop(_k_prune, None)
                                    db.save_settings_async()
                                    
                        except Exception as _pre_err:
                            _log_warn_throttled("rtv_L14717", f"[FILE ADD] Warning: pre-cache rotation failed "
                                  f"for '{active_b}' ch{target_ch}: {_pre_err}")

                # WARNING: no separate scanner for the files just added (removed 2026-11-02, it measured every added file in folder order outside the scan order, the pause and games); the ordered scans are told below and pick them up at once.
                _note_scan_work_added()
    except Exception as e:
        _failed_ch    = locals().get("target_ch", "?")
        _failed_block = locals().get("active_b", "?")
        log.error(
            "[EXPLORER QUEUE EXCEPTION] failed while committing a queued "
            "file-explorer change (ch=%s block=%s) -- this queued item is "
            "now DROPPED and will not be retried; whatever the user just "
            "added/removed there may be missing until they redo it: %s",
            _failed_ch, _failed_block, e, exc_info=True,
        )

    # ========================================================================
    # SECTION: Event handling
    # ========================================================================

    try:
        _picture_adjust_live_tick()
    except Exception as _pic_tick_e:
        _log_warn_throttled("picture_adjust_tick", "[PICTURE ADJUST] checking the Video tab values failed: %s", _pic_tick_e)
    _prof_mark("housekeeping")
    _nav_frame_begin = _menu_nav_frame_begin()

    for event in events:
        if event.type == pygame.QUIT:
            log.info("[QUIT] window close requested; shutting down")
            _app_shutting_down.set()
            try:
                try: media.request_media_shutdown()
                except Exception as e: log.warning(f"[QUIT] media shutdown signal failed: {e}")
                try:
                    if pygame.mixer.get_init() and pygame.mixer.music.get_busy():
                        pygame.mixer.music.stop()
                except Exception as e: log.warning(f"[QUIT] mixer music stop failed: {e}")
                if db is not None and getattr(db, "server_listener", None) is not None:
                    try: db.server_listener.stop()
                    except Exception as e: log.warning(f"[QUIT] server listener stop failed: {e}")
                if server_broadcaster is not None:
                    try: server_broadcaster.stop()
                    except Exception as e: log.warning(f"[QUIT] schedule broadcaster stop failed: {e}")
                try: _disconnect_remote_server("application closing")
                except Exception as e: log.warning(f"[QUIT] remote server disconnect failed: {e}")
                if vlc_engine is not None: 
                    try: vlc_engine.stop()
                    except Exception as e: log.warning(f"[QUIT] vlc stop failed: {e}")
                    try: vlc_engine.close()
                    except Exception as e: log.warning(f"[QUIT] vlc close failed: {e}")
                if dvd_engine is not None:
                    try: dvd_engine.stop()
                    except Exception as e: log.warning(f"[QUIT] dvd engine stop failed: {e}")
                    try: dvd_engine.close()
                    except Exception as e: log.warning(f"[QUIT] dvd engine close failed: {e}")
                if game_deck is not None and hasattr(game_deck, "shutdown_deck"):
                    try: game_deck.shutdown_deck()
                    except Exception as e: log.warning(f"[QUIT] game_deck shutdown failed: {e}")
                if db is not None:
                    _quit_ch = app_state.get("current_channel", "05")
                    if _quit_ch not in ("03", "04"):
                        db.config["last_channel"] = _quit_ch
                    try: db.save_settings()
                    except Exception as e: log.warning(f"[QUIT] save_settings failed: {e}")
                if db is not None and db.config.get("start_on_boot", False):
                    _launch_explorer_fallback()
            except Exception as e:
                # WARNING: log the error loudly and still fall through to the unconditional exit; a quit request must never leave the process or its audio running.
                log.error(f"[QUIT] unexpected error during shutdown cleanup -- exiting anyway: {e}", exc_info=True)
            # WARNING: the fallback numbers below must match SHUTDOWN_PROBE_GRACE_SECONDS in performance_governor.py; they are used only when that module fails to import.
            _PROBE_SHUTDOWN_GRACE_S = performance_governor.SHUTDOWN_PROBE_GRACE_SECONDS if performance_governor is not None else 0.4
            _probe_grace_deadline = time.time() + _PROBE_SHUTDOWN_GRACE_S
            while _probe_dispatch_inflight and time.time() < _probe_grace_deadline:
                time.sleep(0.05)
            pygame.quit()
            _hard_exit_process(0)

        if event.type in (pygame.WINDOWFOCUSLOST, pygame.WINDOWFOCUSGAINED, pygame.ACTIVEEVENT):
            if app_state.get("_held_keys"):
                log.info("[GUIDE] STUCK-KEY GUARD: focus event=%s -- clearing "
                         "_held_keys=%r guide_hold_key=%r (were any of these still "
                         "down for real, a fresh KEYDOWN will re-add them)",
                         pygame.event.event_name(event.type), app_state.get("_held_keys"),
                         app_state["_hold_guide"].key)
            app_state["_held_keys"] = set()
            app_state["_held_keys_source"] = {}
            app_state["_held_key_down_layer"] = {}
            app_state["_hold_guide"].clear()
            app_state["last_hold_direction"] = 0
            app_state["hold_start_timestamp"] = 0
            app_state["_hold_menu"].clear()
            app_state["_hold_volume"].clear()

        if event.type == _WINDOW_COMMAND_EVENT:
            if getattr(event, "window_action", None) == "restore_fixed_from_maximized_minimize":
                if (app_state.get("windowed_maximized", False)
                        and not app_state.get("is_fullscreen", False)):
                    screen = _restore_fixed_windowed_surface(screen)
                    app_state["is_fullscreen"] = False
                    app_state["windowed_maximized"] = False
                    app_state["windowed_minimized"] = False
                    app_state["window_event_guard_until"] = pygame.time.get_ticks() + 500
                    pygame.event.clear(pygame.VIDEORESIZE)
                    pygame.event.clear(pygame.WINDOWMAXIMIZED)
                    for _window_event_name in ("WINDOWRESTORED", "WINDOWMINIMIZED"):
                        _window_event_type = getattr(pygame, _window_event_name, None)
                        if _window_event_type is not None:
                            pygame.event.clear(_window_event_type)
            continue

        if event.type in (pygame.KEYDOWN, pygame.KEYUP):
            if getattr(event, "controller", False):
                if (app_state.get("current_channel") != "03"
                        or app_state.get("show_menu", False)
                        or app_state.get("show_splash", False)
                        or app_state.get("show_quit_confirm", False)
                        or app_state.get("is_loading", False)
                        or app_state.get("file_explorer_active", False)):
                    continue

        if app_state.get("file_explorer_active", False):
            _fe_handle_event(event)
            continue

        if event.type == pygame.JOYDEVICEADDED:
            try:
                _j = pygame.joystick.Joystick(event.device_index)
                _j.init()
                print(f"[CTRL] Joystick connected: {_j.get_name()} (id={event.device_index})")
            except Exception as _je:
                log.warning(f"[CTRL] Joystick connect error: {_je}")

        if (app_state.get("current_channel") == "03"
                and game_deck is not None
                and not app_state.get("show_menu", False)
                and not app_state.get("show_splash", False)
                and not app_state.get("show_quit_confirm", False)
                and not app_state.get("is_loading", False)):
            if event.type == pygame.JOYAXISMOTION:
                # WARNING: the fallback number must match STICK_CH03_AXIS_ACTIVITY_DEADZONE in performance_governor.py; it is used only when that module fails to import.
                _AXIS_ACTIVITY_DEADZONE = performance_governor.STICK_CH03_AXIS_ACTIVITY_DEADZONE if performance_governor is not None else 8000 / 32767.0
                _axis_key = (getattr(event, "instance_id", getattr(event, "joy", 0)), event.axis)
                _axis_active_set = app_state.setdefault("_ch03_axis_active", set())
                _past_deadzone = abs(event.value) > _AXIS_ACTIVITY_DEADZONE
                if _past_deadzone and _axis_key not in _axis_active_set:
                    _axis_active_set.add(_axis_key)
                    app_state["ch03_screensaver_last_input"] = pygame.time.get_ticks()
                    if app_state.get("ch03_screensaver_active", False):
                        app_state["ch03_screensaver_active"] = False
                        if app_state.get("ch03_ss_was_game_running", False) and game_deck is not None:
                            print("[SCREENSAVER] Unfreezing emulator after controller dismiss.")
                            game_deck.set_paused(False, reason="screensaver", muted=False)
                        app_state["ch03_ss_was_game_running"] = False
                elif not _past_deadzone and _axis_key in _axis_active_set:
                    _axis_active_set.discard(_axis_key)
                continue
            if event.type in (pygame.JOYBUTTONDOWN, pygame.JOYHATMOTION):
                app_state["ch03_screensaver_last_input"] = pygame.time.get_ticks()
                if app_state.get("ch03_screensaver_active", False):
                    app_state["ch03_screensaver_active"] = False
                    if app_state.get("ch03_ss_was_game_running", False) and game_deck is not None:
                        print("[SCREENSAVER] Unfreezing emulator after controller dismiss.")
                        game_deck.set_paused(False, reason="screensaver", muted=False)
                    app_state["ch03_ss_was_game_running"] = False
                continue

        if event.type == pygame.VIDEORESIZE:
            continue

        elif event.type == pygame.WINDOWMAXIMIZED:
            if pygame.time.get_ticks() < app_state.get("window_event_guard_until", 0):
                continue
            if app_state.get("is_fullscreen", False):
                # WARNING: ignore a stale native maximize notification while already in borderless fullscreen.
                continue
            # WARNING: do not call pygame.FULLSCREEN here; it removes the title bar, moves the surface to (0, 0) and turns the square button into a second fullscreen toggle.
            screen = _maximize_windowed_surface(screen)
            app_state["is_fullscreen"] = False
            app_state["windowed_maximized"] = True
            app_state["windowed_minimized"] = False
            # WARNING: do not let that notification undo the native maximize just established.
            app_state["window_event_guard_until"] = pygame.time.get_ticks() + 500
            _set_window_topmost(
                pygame.display.get_wm_info().get("window") if sys.platform == "win32" else None,
                topmost=False,
            )

        elif event.type == getattr(pygame, "WINDOWMINIMIZED", -1):
            if not app_state.get("is_fullscreen", False):
                app_state["windowed_minimized"] = True

        elif event.type == getattr(pygame, "WINDOWRESTORED", -1):
            if pygame.time.get_ticks() < app_state.get("window_event_guard_until", 0):
                continue
            if app_state.get("is_fullscreen", False):
                continue

            _restored_hwnd = None
            if sys.platform == "win32":
                try:
                    _restored_hwnd = pygame.display.get_wm_info().get("window")
                except Exception as _swallowed_error:
                    _log_swallowed("main script: _restored_hwnd = pygame.display.get_wm_info().get('window')", _swallowed_error)

            if app_state.get("windowed_minimized", False):
                screen = _restore_fixed_windowed_surface(screen)
                app_state["is_fullscreen"] = False
                app_state["windowed_maximized"] = False
                app_state["windowed_minimized"] = False
                app_state["window_event_guard_until"] = pygame.time.get_ticks() + 500
                pygame.event.clear(pygame.VIDEORESIZE)
                pygame.event.clear(pygame.WINDOWMAXIMIZED)
                continue

            if app_state.get("windowed_maximized", False):
                if _win32_window_is_zoomed(_restored_hwnd):
                    screen = _maximize_windowed_surface(screen)
                    continue

                _fs_w, _fs_h = NATIVE_WIDTH, NATIVE_HEIGHT
                try:
                    _desktops = pygame.display.get_desktop_sizes()
                    if _desktops:
                        _fs_w, _fs_h = _desktops[0]
                except Exception as _fs_err:
                    log.warning(f"[WINDOW] get_desktop_sizes() failed on restore, using boot native size: {_fs_err}")
                WINDOW_WIDTH, WINDOW_HEIGHT = _fs_w, _fs_h
                screen = _set_display_mode((WINDOW_WIDTH, WINDOW_HEIGHT), pygame.NOFRAME)
                app_state["is_fullscreen"] = True
                app_state["windowed_maximized"] = False
                app_state["windowed_minimized"] = False
                _finalize_window_mode(
                    screen, windowed=False,
                    client_w=WINDOW_WIDTH, client_h=WINDOW_HEIGHT,
                    pos_x=0, pos_y=0,
                )

        elif event.type == pygame.KEYUP:
            _raw_keyup_key = event.key
            _actual_held_value = app_state["_held_keys_source"].pop(_raw_keyup_key, None)
            if _actual_held_value is not None:
                app_state["_held_keys"].discard(_actual_held_value)

            if app_state.get("menu_layer") not in ("REMOTE_REMAP_CAPTURE", "NUMBER_REMAP_CAPTURE") and not (
                app_state.get("menu_layer") == "DVD_BTN_MAP" and app_state.get("dvd_map_capturing", False)
            ):
                event.key = translate_remote_key(db, event.key)
            app_state["_held_keys"].discard(_raw_keyup_key)
            app_state["_held_keys"].discard(event.key)
            if app_state.get("show_menu", False):
                _menu_nav_trace("up", event.key, "raw=%s" % pygame.key.name(_raw_keyup_key))

        elif event.type == pygame.KEYDOWN:
            now_ticks = pygame.time.get_ticks()
            
            app_state["last_input_time"] = now_ticks

            _raw_key_before_translate = event.key
            if (not getattr(event, "synthetic", False)
                    and app_state.get("menu_layer") not in ("REMOTE_REMAP_CAPTURE", "NUMBER_REMAP_CAPTURE")
                    and not (app_state.get("menu_layer") == "DVD_BTN_MAP" and app_state.get("dvd_map_capturing", False))):
                event.key = translate_remote_key(db, event.key)

            if (not getattr(event, "synthetic", False)
                    and event.key in _NAV_DUP_KEYS
                    and (app_state.get("show_menu", False)
                         or app_state.get("current_channel") == "04"
                         or app_state.get("file_explorer_active", False))):
                _dup_last = app_state.setdefault("_nav_last_down", {}).get(event.key)
                if _dup_last is not None and menu_nav.press_is_duplicate(
                        now_ticks - _dup_last[0],
                        _raw_key_before_translate == _dup_last[1],
                        event.key in app_state["_held_keys"]):
                    _menu_nav_trace("dup", event.key, "raw=%s since_last=%d" % (
                        pygame.key.name(_raw_key_before_translate), now_ticks - _dup_last[0]))
                    continue
                app_state["_nav_last_down"][event.key] = (now_ticks, _raw_key_before_translate)

            _nav_gated = False
            if (not getattr(event, "menu_repeat", False)
                    and event.key in _NAV_DUP_KEYS
                    and (app_state.get("show_menu", False)
                         or app_state.get("current_channel") == "04"
                         or app_state.get("file_explorer_active", False))
                    and app_state.get("menu_layer") not in menu_nav.NO_REPEAT_LAYERS
                    and not (app_state.get("menu_layer") == "DVD_BTN_MAP" and app_state.get("dvd_map_capturing", False))
                    and not app_state.get("editing_channel_name", False)
                    and not app_state.get("editing_server_slot_name", False)):
                # WARNING: the highlight speed limit (owner 2026-11-01): a press too soon after the last move, or a second one in the same frame (a pile-up after a freeze), is thrown away, not saved; the key still counts as held so a hold repeats as before.
                _nav_gated = not menu_nav.move_allowed(
                    app_state.setdefault("_nav_move_gate", {}), now_ticks, app_state.get("_nav_frame_id", 0))

            if not getattr(event, "menu_repeat", False):
                app_state["_held_keys"].add(event.key)
                app_state.setdefault("_held_key_down_ticks", {})[event.key] = now_ticks
                app_state.setdefault("_held_key_down_layer", {})[event.key] = app_state.get("menu_layer")
            if not getattr(event, "synthetic", False):
                app_state["_held_keys_source"][_raw_key_before_translate] = event.key
            if app_state.get("show_menu", False) and not getattr(event, "menu_repeat", False):
                _menu_nav_trace("gated" if _nav_gated else "down", event.key, "raw=%s synthetic=%s" % (
                    pygame.key.name(_raw_key_before_translate), bool(getattr(event, "synthetic", False))))
            if _nav_gated:
                continue

            if app_state.get("current_channel") == "03":
                app_state["ch03_screensaver_last_input"] = now_ticks
                if app_state.get("ch03_screensaver_active", False):
                    app_state["ch03_screensaver_active"] = False
                    globals()["_ch03_ss_surf_cache"] = None
                    if app_state.get("ch03_ss_was_game_running", False) and game_deck is not None:
                        print("[SCREENSAVER] Unfreezing emulator after keyboard dismiss.")
                        game_deck.set_paused(False, reason="screensaver", muted=False)
                    app_state["ch03_ss_was_game_running"] = False
                    continue

            if (app_state.get("show_menu") and
                    app_state.get("menu_layer") == "GAMES_STICK_DZ" and
                    game_deck is not None):
                import game_deck as _sz_mod
                _sz_player = app_state.get("stick_dz_player", 1)
                _sz_on = _sz_mod.stick_switch_on(db.config, _sz_player)
                _sz_rows = menu_nav.stick_dz_rows(_sz_on)
                _sz_from = menu_nav.stick_dz_cell(_sz_rows, app_state.get("stick_dz_cursor", 0))
                _sz_dir = menu_nav.key_to_direction(event.key, arrows=True)
                if _sz_dir in (menu_nav.UP, menu_nav.DOWN):
                    _sz_to = menu_nav.navigate(app_state, "GAMES_STICK_DZ", menu_nav.stick_dz_table(_sz_on), _sz_from, _sz_dir)
                    if _sz_to is not None:
                        app_state["stick_dz_cursor"] = menu_nav.stick_dz_index(_sz_rows, _sz_to)
                    continue
                if _sz_dir in (menu_nav.LEFT, menu_nav.RIGHT):
                    if _sz_from in menu_nav.STICK_DZ_SETTINGS:
                        _sz_mod.adjust_stick_setting(db.config, _sz_from, 1 if _sz_dir == menu_nav.RIGHT else -1, _sz_player)
                        _sz_mod.apply_stick_config(db.config)
                        db.save_settings()
                    elif _sz_from == menu_nav.STICK_DZ_PLAYERS:
                        _sz_new = menu_nav.stick_dz_player_step(_sz_player, _sz_dir)
                        if _sz_new is None:
                            _sz_to = menu_nav.navigate(app_state, "GAMES_STICK_DZ", menu_nav.stick_dz_table(_sz_on), _sz_from, _sz_dir)
                            if _sz_to is not None:
                                app_state["stick_dz_cursor"] = menu_nav.stick_dz_index(_sz_rows, _sz_to)
                        else:
                            app_state["stick_dz_player"] = _sz_new
                            _sz_new_rows = menu_nav.stick_dz_rows(_sz_mod.stick_switch_on(db.config, _sz_new))
                            app_state["stick_dz_cursor"] = menu_nav.stick_dz_index(_sz_new_rows, menu_nav.STICK_DZ_PLAYERS)
                    elif _sz_from == menu_nav.CLOSE:
                        _sz_to = menu_nav.navigate(app_state, "GAMES_STICK_DZ", menu_nav.stick_dz_table(_sz_on), _sz_from, _sz_dir)
                        if _sz_to is not None:
                            app_state["stick_dz_cursor"] = menu_nav.stick_dz_index(_sz_rows, _sz_to)
                    continue
                if menu_nav.is_accept(event.key):
                    if _sz_from == menu_nav.STICK_DZ_SWITCH:
                        _sz_mod.toggle_stick_switch(db.config, _sz_player)
                        _sz_mod.apply_stick_config(db.config)
                        db.save_settings()
                        if not _sz_mod.stick_switch_on(db.config, _sz_player):
                            app_state["stick_dz_cursor"] = 0
                    elif _sz_from == menu_nav.STICK_DZ_RESET:
                        _sz_mod.reset_stick_defaults(db.config, _sz_player)
                        _sz_mod.apply_stick_config(db.config)
                        db.save_settings()
                    elif _sz_from == menu_nav.CLOSE:
                        app_state["menu_layer"] = "GAMES_SUB_MENU"
                    continue
                if menu_nav.is_back(event.key):
                    pass
                else:
                    continue

            if (app_state.get("show_menu") and
                    app_state.get("menu_layer") == "GAMES_CTRL_MAP" and
                    game_deck is not None):

                if getattr(game_deck, "_pick_layout_popup_player", None) is not None:
                    if menu_nav.is_back(event.key):
                        game_deck.dismiss_pick_layout_popup()
                    elif menu_nav.is_accept(event.key):
                        game_deck.confirm_pick_layout_popup()
                    continue

                if game_deck.mapping_reassign_pending():
                    if menu_nav.is_back(event.key):
                        game_deck.cancel_any_mapping_reassign()
                    continue

                if getattr(game_deck, "_seq_remap_active", False):
                    if menu_nav.is_back(event.key):
                        game_deck.ctrl_mapping_active_btn = None
                        game_deck._seq_remap_active = False
                    elif menu_nav.key_to_action(event.key, parent=True) == menu_nav.PARENT:
                        game_deck.skip_current_remap_button()
                        continue
                    else:
                        continue

                _cm_console   = getattr(game_deck, "_active_mapping_console", None) or "GBA"
                _cm_is_n64    = (_cm_console == "N64")
                _cm_squares_idx = 0
                _cm_map_idx     = 1
                _cm_stick_idx   = None if _cm_is_n64 else 2
                _cm_close_idx   = 2 if _cm_is_n64 else 3
                _ci = app_state.get("ctrl_map_cursor", _cm_map_idx)

                _cm_active_player = getattr(game_deck, "_active_mapping_player", 1)

                _cm_dir = menu_nav.key_to_direction(event.key, arrows=True)
                if _cm_dir is not None:
                    _cm_rows = menu_nav.ctrl_map_rows(not _cm_is_n64)
                    _cm_from = menu_nav.ctrl_map_cell(_cm_rows, _ci)
                    _cm_to = None
                    if _cm_from == menu_nav.CTRL_MAP_SQUARES and _cm_dir in (menu_nav.LEFT, menu_nav.RIGHT):
                        _cm_pick = [p for p in range(1, 5) if game_deck._player_slot_pickable(p, _cm_console)]
                        _cm_sel, _cm_on_pick, _cm_leave = menu_nav.ctrl_map_squares_step(
                            _cm_pick, app_state.get("ctrl_map_player_sel", _cm_active_player),
                            app_state.get("ctrl_map_on_pick", False), _cm_dir, _cm_console == "MENU")
                        app_state["ctrl_map_player_sel"] = _cm_sel
                        app_state["ctrl_map_on_pick"] = _cm_on_pick
                        if _cm_leave:
                            _cm_to = menu_nav.navigate(app_state, "GAMES_CTRL_MAP", menu_nav.ctrl_map_table(not _cm_is_n64), _cm_from, _cm_dir)
                    else:
                        _cm_to = menu_nav.navigate(app_state, "GAMES_CTRL_MAP", menu_nav.ctrl_map_table(not _cm_is_n64), _cm_from, _cm_dir)
                    if _cm_to is not None:
                        app_state["ctrl_map_cursor"] = menu_nav.ctrl_map_index(_cm_rows, _cm_to)
                        if _cm_to == menu_nav.CTRL_MAP_SQUARES:
                            app_state["ctrl_map_on_pick"] = (_cm_console == "MENU")
                            if _cm_console != "MENU":
                                app_state["ctrl_map_player_sel"] = 1
                        elif _cm_from == menu_nav.CTRL_MAP_SQUARES:
                            app_state["ctrl_map_on_pick"] = False
                    continue

                if menu_nav.is_accept(event.key):
                    if _ci == _cm_squares_idx:
                        if _cm_console == "MENU":
                            if app_state.get("ctrl_map_on_pick", False):
                                game_deck.start_menu_controller_pick()
                        else:
                            _sel_p = app_state.get("ctrl_map_player_sel", _cm_active_player)
                            if app_state.get("ctrl_map_on_pick", False):
                                if game_deck._player_slot_pickable(_sel_p):
                                    game_deck.start_controller_pick(_sel_p)
                            elif game_deck._player_slot_pickable(_sel_p):
                                game_deck._switch_mapping_player(_sel_p)
                                app_state["ctrl_map_player_sel"] = _sel_p
                    elif _ci == _cm_map_idx:
                        game_deck.start_sequential_remap()
                    elif _cm_stick_idx is not None and _ci == _cm_stick_idx:
                        game_deck.ctrl_mapping["stick_as_dpad"] = not game_deck.ctrl_mapping.get("stick_as_dpad", False)
                        game_deck._save_controller_mapping()
                    elif _ci == _cm_close_idx:
                        game_deck._mapping_close_requested = True
                    continue

                if menu_nav.is_back(event.key):
                    pass

                else:
                    continue

            _capture_layer = app_state.get("menu_layer")
            if app_state.get("show_menu") and _capture_layer in ("REMOTE_REMAP_CAPTURE", "NUMBER_REMAP_CAPTURE"):
                
                if getattr(event, "synthetic", False):
                    continue

                if not menu_nav.is_back(event.key):
                    _last_accept = app_state.get("_remap_last_accept")
                    if _last_accept is not None:
                        _ra_dt      = pygame.time.get_ticks() - _last_accept["ms"]
                        _ra_same_key = (event.key == _last_accept["key"])
                        _ra_same_sc  = getattr(event, "scancode", 0) == _last_accept["scancode"]
                        # WARNING: the fallback numbers below must match KEY_CAPTURE_SAME_PRESS_MS in performance_governor.py; they are used only when that module fails to import.
                        _REMAP_HARD_DEDUP_MS = performance_governor.KEY_CAPTURE_SAME_PRESS_MS if performance_governor is not None else 250
                        if _ra_dt < _REMAP_HARD_DEDUP_MS:
                            print(f"[REMOTE REMAP] Ignored duplicate capture event "
                                  f"(key={event.key} scancode={getattr(event, 'scancode', '?')}, "
                                  f"last accepted key={_last_accept['key']}) within "
                                  f"{_REMAP_HARD_DEDUP_MS}ms -- second delivery path of same "
                                  f"physical press.", flush=True)
                            continue
                        if _ra_same_key and _ra_dt < _REMAP_CAPTURE_DEDUP_MS and not _ra_same_sc:
                            print(f"[REMOTE REMAP] Ignored duplicate capture event "
                                  f"(key={event.key} scancode={getattr(event, 'scancode', '?')}) "
                                  f"within {_REMAP_CAPTURE_DEDUP_MS}ms of the last binding -- "
                                  f"same physical button arriving on a second input path.", flush=True)
                            continue

                _is_number_capture = (_capture_layer == "NUMBER_REMAP_CAPTURE")
                _action_set = NUMBER_REMAP_ACTIONS if _is_number_capture else REMOTE_REMAP_ACTIONS
                _landing_sel = 1 if _is_number_capture else 0

                remap_idx = app_state.get("remote_remap_index", 0)
                action_id, action_label = _action_set[remap_idx]

                _remap_conflict_lbl = check_remap_conflict(db, app_state, action_id, event.key)
                if _remap_conflict_lbl is not None:
                    app_state["_remap_reject_flash"] = pygame.time.get_ticks()
                    app_state["_remap_reject_key"]   = event.key
                    print(f"[REMOTE REMAP] Rejected key {event.key} -- "
                          f"already bound to: {_remap_conflict_lbl}", flush=True)
                    continue

                set_remote_binding(db, action_id, event.key)
                app_state.setdefault("_remap_used_keys", []).append(event.key)
                app_state["_remap_reject_flash"] = None
                app_state["_remap_last_accept"] = {
                    "ms":       pygame.time.get_ticks(),
                    "key":      event.key,
                    "scancode": getattr(event, "scancode", 0),
                }

                next_idx = remap_idx + 1
                if next_idx < len(_action_set):
                    app_state["remote_remap_index"] = next_idx
                else:
                    app_state["menu_layer"] = "REMOTE_REMAP_LIST"
                    app_state["menu_selection_index"] = _landing_sel
                    app_state["remote_remap_index"] = 0
                    app_state.pop("_remap_used_keys", None)
                    print("[REMOTE REMAP] Sequence complete.")
                continue

            _kiosk_on_now = db.config.get("kiosk_mode_enabled", False) if db is not None else False
            is_global_menu_trigger = event.key == pygame.K_m or (event.key == pygame.K_c and not _kiosk_on_now)
            is_any_menu_showing = (
                app_state.get("show_menu", False) or 
                app_state.get("show_splash", False) or 
                app_state.get("show_quit_confirm", False)
            )

            if app_state.get("show_clear_confirm", False):
                if app_state.get("update_install_active", False):
                    # WARNING: while the update downloads, the bar owns the screen; no key may close the popup or start a second install.
                    continue
                _cc_is_burnin_family = app_state.get("clear_confirm_target") in (
                    "visualizer_style_change", "console_bezel_toggle", "program_bezel_toggle",
                    "pixel_orbiter_toggle", "ch03_screensaver_toggle", "app_update",
                )
                _cc_focus = app_state.get("clear_confirm_focus", "buttons")
                if menu_nav.is_back(event.key):
                    if app_state.get("clear_confirm_target") == "app_update":
                        _remember_update_prompt_skip(app_state.get("clear_confirm_dont_show_again", False))
                    app_state["clear_confirm_dont_show_again"] = False
                    app_state["show_clear_confirm"] = False
                    app_state["clear_confirm_target"] = None
                    app_state["clear_confirm_channel"] = None
                    app_state["clear_confirm_console"] = None
                    app_state["clear_confirm_shown_at"] = 0
                    app_state["clear_confirm_focus"] = "buttons"
                    continue
                _cc_dir = menu_nav.key_to_direction(event.key)
                if _cc_dir is not None:
                    _cc_from = menu_nav.confirm_cell(app_state.get("clear_confirm_selection"), _cc_focus)
                    _cc_to = menu_nav.navigate(app_state, "CLEAR_CONFIRM", menu_nav.confirm_table(_cc_is_burnin_family), _cc_from, _cc_dir)
                    if _cc_dir in (menu_nav.UP, menu_nav.DOWN):
                        if _cc_to is not None:
                            app_state["clear_confirm_focus"] = menu_nav.confirm_focus(_cc_to)
                        app_state["clear_confirm_shown_at"] = now_ticks
                    elif _cc_focus == "buttons":
                        app_state["clear_confirm_selection"] = menu_nav.confirm_answer(_cc_to or _cc_from)
                        app_state["clear_confirm_shown_at"] = now_ticks
                elif menu_nav.is_accept(event.key):
                    if _cc_is_burnin_family and _cc_focus == "checkbox":
                        app_state["clear_confirm_dont_show_again"] = not app_state.get("clear_confirm_dont_show_again", False)
                        app_state["clear_confirm_shown_at"] = now_ticks
                        continue

                    _cc_target = app_state.get("clear_confirm_target")
                    if app_state.get("clear_confirm_selection") == "Yes":
                        if _cc_target == "reset_settings":
                            _execute_system_reset_all_settings()
                        elif _cc_target == "poweroff":
                            _trigger_crt_off("shutdown")
                        elif _cc_target == "app_update":
                            # WARNING: the popup stays up on Yes; the download runs on a worker thread, the bar is drawn over the popup, and the app restarts itself at 100%.
                            if _begin_update_install():
                                continue
                            app_state["_update_status"] = "No update package is ready."
                            app_state["show_clear_confirm"] = False
                            app_state["clear_confirm_target"] = None
                        elif _cc_target == "boot_on_start":
                            if _set_start_on_boot(True):
                                db.config["start_on_boot"] = True
                                db.save_settings()
                                print("[SETTINGS] Boot on Start = True (confirmed).")
                        elif _cc_target == "commercial_media":
                            _cc_ch_str = app_state.get("clear_confirm_channel")
                            if _cc_ch_str:
                                _execute_commercial_media_clear(_cc_ch_str, db.channels_db.get(_cc_ch_str, {}))
                        elif _cc_target == "holiday_media":
                            _cc_ch_str = app_state.get("clear_confirm_channel")
                            if _cc_ch_str:
                                _execute_holiday_media_clear(_cc_ch_str, db.channels_db.get(_cc_ch_str, {}))
                        elif _cc_target in ("channel_schedule", "channel_music"):
                            _cc_ch_str = app_state.get("clear_confirm_channel")
                            if _cc_ch_str:
                                _cc_ch_info = db.channels_db.get(_cc_ch_str, {})
                                _execute_channel_media_clear(_cc_ch_str, _cc_ch_info)
                        elif _cc_target == "clear_roms":
                            _execute_clear_manual_roms()
                        elif _cc_target == "clear_cores":
                            _execute_clear_all_cores()
                        elif _cc_target == "clear_bios":
                            _execute_clear_all_bios()
                        elif _cc_target == "clear_console_roms":
                            _cc_console = app_state.get("clear_confirm_console")
                            if _cc_console:
                                _execute_clear_console_manual_roms(_cc_console)
                        elif _cc_target == "visualizer_style_change":
                            _vs_ch_str = app_state.get("clear_confirm_channel")
                            _vs_new_style = app_state.get("clear_confirm_burnin_new_value", "Random")
                            if _vs_ch_str:
                                _vs_ch_info = db.channels_db.get(_vs_ch_str)
                                if _vs_ch_info is not None:
                                    _vs_ch_info["visualizer_style"] = _vs_new_style
                            if app_state.get("clear_confirm_dont_show_again", False):
                                db.config["burn_in_protection_skip_confirm"] = True
                            db.save_settings()
                            print(f"[VISUALIZER STYLE] ch{_vs_ch_str} set to {_vs_new_style} after burn-in warning confirmation "
                                  f"(skip_confirm={app_state.get('clear_confirm_dont_show_again', False)}).")
                        elif _cc_target == "console_bezel_toggle":
                            _bz_console = app_state.get("clear_confirm_channel")
                            _bz_profile = app_state.get("clear_confirm_profile_num")
                            if _bz_console and _bz_profile is not None:
                                log.info("[BEZEL DEBUG] Console Bezel ON (confirmed after burn-in warning), "
                                         "console=%s profile=%s", _bz_console, _bz_profile)
                                _set_console_bezel_enabled(_bz_console, _bz_profile, True)
                                if app_state.get("clear_confirm_dont_show_again", False):
                                    db.config["console_bezel_skip_confirm"] = True
                                    db.save_settings()
                                print(f"[CONSOLE BEZEL] Turned on for {_bz_console} profile {_bz_profile} "
                                      f"after burn-in warning confirmation "
                                      f"(skip_confirm={app_state.get('clear_confirm_dont_show_again', False)}).")
                        elif _cc_target == "program_bezel_toggle":
                            log.info("[BEZEL DEBUG] TV Bezel ON (confirmed after burn-in warning), channel=%s",
                                     app_state.get("current_channel"))
                            db.config["fake_43_border_enabled"] = True
                            if app_state.get("clear_confirm_dont_show_again", False):
                                db.config["program_bezel_skip_confirm"] = True
                            db.save_settings()
                            print(f"[SETTINGS] Bezel = True (confirmed after burn-in warning, "
                                  f"skip_confirm={app_state.get('clear_confirm_dont_show_again', False)}).")
                        elif _cc_target == "pixel_orbiter_toggle":
                            db.config["pixel_orbiter_enabled"] = False
                            if app_state.get("clear_confirm_dont_show_again", False):
                                db.config["pixel_orbiter_skip_confirm"] = True
                            db.save_settings()
                            print(f"[SETTINGS] Pixel Orbiter = False (confirmed after burn-in warning, "
                                  f"skip_confirm={app_state.get('clear_confirm_dont_show_again', False)}).")
                        elif _cc_target == "ch03_screensaver_toggle":
                            _toggle_ss()
                            if app_state.get("clear_confirm_dont_show_again", False):
                                db.config["ch03_screensaver_skip_confirm"] = True
                                db.save_settings()
                            print(f"[SETTINGS] Screen Saver = False (confirmed after burn-in warning, "
                                  f"skip_confirm={app_state.get('clear_confirm_dont_show_again', False)}).")
                    if _cc_target == "app_update" and app_state.get("clear_confirm_selection") != "Yes":
                        _remember_update_prompt_skip(app_state.get("clear_confirm_dont_show_again", False))
                    print(f"[SETTINGS ENGINE] Clear-confirm popup: committing '{app_state.get('clear_confirm_selection')}' for target '{_cc_target}'.")
                    app_state["show_clear_confirm"]     = False
                    app_state["clear_confirm_target"]   = None
                    app_state["clear_confirm_channel"]  = None
                    app_state["clear_confirm_console"]  = None
                    app_state["clear_confirm_shown_at"] = 0
                    app_state["clear_confirm_burnin_new_value"] = None
                    app_state["clear_confirm_dont_show_again"]  = False
                    app_state["clear_confirm_profile_num"] = None
                    app_state["clear_confirm_focus"]    = "buttons"
                else:
                    print(f"[SETTINGS ENGINE] Clear-confirm popup open: ignoring key {pygame.key.name(event.key)} (only A/D/W/S/Enter are live).")
                continue

            if (app_state.get("current_channel") == "03"
                    and 'game_deck' in globals() and game_deck is not None
                    and getattr(game_deck, "mode", "BROWSE") == "DVD_PLAYER"
                    and (getattr(game_deck, "dvd_exit_confirm", False)
                         or getattr(game_deck, "dvd_return_menu_confirm", False))):
                if (menu_nav.deck_confirm_choice(menu_nav.key_to_direction(event.key)) is not None
                        or menu_nav.is_accept(event.key) or menu_nav.is_back(event.key)):
                    print(f"[DVD GATE] Confirm popup open -> routing '{pygame.key.name(event.key)}' to DVD deck.")
                    game_deck.handle_event(event)
                    continue
                if event.key in (pygame.K_UP, pygame.K_DOWN):
                    print(f"[DVD GATE] Confirm popup open -> channel key '{pygame.key.name(event.key)}' stays live.")
                else:
                    print(f"[DVD GATE] Confirm popup open -> swallowing '{pygame.key.name(event.key)}' (inactive until a choice is made).")
                    continue

            if app_state.get("current_channel") == "03" and not is_any_menu_showing and not is_global_menu_trigger:
                if 'game_deck' in globals() and game_deck is not None:
                    deck_mode = getattr(game_deck, "mode", "BROWSE")
                    is_global_tv_key = event.key in [pygame.K_UP, pygame.K_DOWN, pygame.K_LEFT, pygame.K_RIGHT, pygame.K_n]
                    is_emulator_live  = (deck_mode == "GAME"
                                         and not getattr(game_deck, "emulator_loading", False))

                    if menu_nav.is_back(event.key) and deck_mode == "BROWSE":
                        pass
                    elif is_emulator_live:
                        pass
                    elif deck_mode == "GAME" and getattr(game_deck, "emulator_loading", False):
                        if is_global_tv_key:
                            pass
                        else:
                            continue
                    elif deck_mode == "DVD_PLAYER" and is_global_tv_key:
                        pass
                    elif deck_mode == "DVD_PLAYER" and (
                            menu_nav.key_to_direction(event.key) is not None
                            or menu_nav.key_to_action(event.key) in (menu_nav.BACK, menu_nav.ACCEPT)):
                        game_deck.handle_event(event)
                        continue
                    else:
                        if game_deck.handle_event(event):
                            continue

            if app_state.get("is_loading", False):
                continue

            if app_state.get("editing_channel_name", False):
                target_ch_str = str(app_state["selected_channel_row"]).zfill(2)
                ch_info = db.channels_db.get(target_ch_str, {})
                if ch_info.get("server_locked", False):
                    app_state["editing_channel_name"] = False
                    app_state["channel_name_all_selected"] = False
                    print(f"[SERVER SYNC] Ignored channel-name edit on locked channel {target_ch_str}.")
                    continue
                current_name = ch_info.get("name", f"STATION {target_ch_str}")
                all_selected = app_state.get("channel_name_all_selected", False)
                
                _name_result, _name_text, _name_selected = menu_nav.name_entry_step(
                    event.key, event.unicode, current_name, all_selected,
                    app_state.get("channel_name_max_len", menu_nav.NAME_ENTRY_CHANNEL_MAX_DEFAULT))
                if _name_result == menu_nav.NAME_SAVE:
                    app_state["editing_channel_name"] = False
                    app_state["channel_name_all_selected"] = False
                    db.save_settings()
                    print(f"[NAME ENGINE] Saved customized channel label: '{current_name}'")
                elif _name_result == menu_nav.NAME_EDIT:
                    ch_info["name"] = _name_text
                    app_state["channel_name_all_selected"] = _name_selected
                continue 

            if app_state.get("editing_server_slot_name", False):
                buf = app_state.get("server_slot_name_buffer", "")
                all_selected = app_state.get("server_slot_name_all_selected", False)
                mode = app_state.get("server_slot_name_mode", "create")

                _slot_result, _slot_text, _slot_selected = menu_nav.name_entry_step(
                    event.key, event.unicode, buf, all_selected, menu_nav.NAME_ENTRY_SLOT_MAX, cancel_on_back=True)
                if _slot_result == menu_nav.NAME_CANCEL:
                    app_state["editing_server_slot_name"] = False
                    app_state["server_slot_name_all_selected"] = False
                elif _slot_result == menu_nav.NAME_SAVE:
                    name = buf.strip()
                    if not name:
                        pass
                    elif mode == "create":
                        new_slot_id = db.create_server_slot(name)
                        if new_slot_id is not None:
                            _reconcile_server_service()
                            app_state["editing_server_slot_name"] = False
                            app_state["server_slot_name_all_selected"] = False
                            _new_idx = (
                                list(db.SERVER_SLOT_IDS).index(new_slot_id)
                                if new_slot_id in db.SERVER_SLOT_IDS else 0
                            )
                            app_state["menu_selection_index"] = _new_idx
                            print(f"[SERVER SLOTS] Created {new_slot_id}: '{name}'")
                        else:
                            print(f"[SERVER SLOTS] Could not create slot for '{name}' (6-slot limit reached?)")
                    else:
                        target_slot_id = app_state.get("server_slot_name_target_slot_id")
                        if db.rename_server_slot(target_slot_id, name):
                            app_state["editing_server_slot_name"] = False
                            app_state["server_slot_name_all_selected"] = False
                            print(f"[SERVER SLOTS] Renamed {target_slot_id} -> '{name}'")
                elif _slot_result == menu_nav.NAME_EDIT:
                    app_state["server_slot_name_buffer"] = _slot_text
                    app_state["server_slot_name_all_selected"] = _slot_selected
                continue

            if app_state["current_channel"] == "04":
                app_state["guide_inactivity_timer"] = now_ticks + MENU_IDLE_CLOSE_MS

            if app_state.get("show_splash", False):
                last_page = NUM_CONTROL_PAGES - 1

                page  = app_state.get("controls_splash_page",  0)
                focus = app_state.get("controls_splash_focus", 1)

                if menu_nav.is_back(event.key) or event.key == pygame.K_c:
                    app_state["show_splash"] = False
                    app_state["splash_shown_at"] = 0
                    app_state["controls_splash_page"]  = 0
                    app_state["controls_splash_focus"] = 1
                    print("[TELEMETRY] Control splash menu dismissed.")
                elif menu_nav.key_to_direction(event.key, arrows=True) is not None:
                    if page != 0:
                        _sp_to = menu_nav.navigate(app_state, "CONTROLS_SPLASH", menu_nav.splash_table(), menu_nav.splash_cell(focus), menu_nav.key_to_direction(event.key, arrows=True))
                        if _sp_to is not None:
                            app_state["controls_splash_focus"] = menu_nav.splash_focus(_sp_to)
                elif menu_nav.is_accept(event.key):
                    if page == 0:
                        app_state["controls_splash_page"]  = 1
                        app_state["controls_splash_focus"] = 1
                    elif focus == 0:
                        new_page = page - 1
                        app_state["controls_splash_page"]  = new_page
                        app_state["controls_splash_focus"] = 0 if new_page != 0 else 1
                    elif page == last_page:
                        app_state["show_splash"] = False
                        app_state["splash_shown_at"] = 0
                        app_state["controls_splash_page"]  = 0
                        app_state["controls_splash_focus"] = 1
                        print("[TELEMETRY] Control splash menu dismissed.")
                    else:
                        app_state["controls_splash_page"]  = page + 1
                        app_state["controls_splash_focus"] = 1
                # WARNING: every key, M included, ends here while the Controls splash shows; letting M fall through to the M handler below would close the splash, and M only opens and closes the Settings menu.
                continue

            if app_state.get("show_quit_confirm", False):
                app_state["quit_confirm_shown_at"] = now_ticks
                if menu_nav.is_accept(event.key):
                    _win_hwnd_dbg = None
                    if sys.platform == "win32":
                        try:
                            _win_hwnd_dbg = pygame.display.get_wm_info().get("window")
                        except Exception as _swallowed_error:
                            _log_swallowed("main script: _win_hwnd_dbg = pygame.display.get_wm_info().get('window')", _swallowed_error)
                    print(f"[WINDOW] Minimize/restore toggle: was_fullscreen={app_state.get('is_fullscreen', True)} "
                          f"hwnd={_win_hwnd_dbg} foreground_before={ctypes.windll.user32.GetForegroundWindow() if sys.platform == 'win32' else None}")
                    if app_state.get("is_fullscreen", True):
                        min_width, min_height = _compute_boot_window_size(
                            NATIVE_WIDTH, NATIVE_HEIGHT, DETECTED_ASPECT_RATIO
                        )
                        WINDOW_WIDTH, WINDOW_HEIGHT = min_width, min_height
                        screen = _set_display_mode((min_width, min_height))
                        app_state["is_fullscreen"] = False
                        app_state["windowed_maximized"] = False
                        app_state["windowed_minimized"] = False
                        _pos_x = max(0, (NATIVE_WIDTH - min_width) // 2)
                        _pos_y = max(0, (NATIVE_HEIGHT - min_height) // 2)
                        _finalize_window_mode(
                            screen, windowed=True,
                            client_w=min_width, client_h=min_height,
                            pos_x=_pos_x, pos_y=_pos_y,
                        )
                    else:
                        _fs_w, _fs_h = NATIVE_WIDTH, NATIVE_HEIGHT
                        try:
                            _desktops = pygame.display.get_desktop_sizes()
                            if _desktops:
                                _fs_w, _fs_h = _desktops[0]
                        except Exception as _fs_err:
                            log.warning(f"[WINDOW] get_desktop_sizes() failed, using boot native size: {_fs_err}")
                        WINDOW_WIDTH, WINDOW_HEIGHT = _fs_w, _fs_h
                        screen = _set_display_mode((WINDOW_WIDTH, WINDOW_HEIGHT), pygame.NOFRAME)
                        app_state["is_fullscreen"] = True
                        app_state["windowed_maximized"] = False
                        app_state["windowed_minimized"] = False
                        _finalize_window_mode(
                            screen, windowed=False,
                            client_w=WINDOW_WIDTH, client_h=WINDOW_HEIGHT,
                            pos_x=0, pos_y=0,
                        )
                    pygame.event.clear(pygame.VIDEORESIZE)
                    pygame.event.clear(pygame.WINDOWMAXIMIZED)
                    for _window_event_name in ("WINDOWRESTORED", "WINDOWMINIMIZED"):
                        _window_event_type = getattr(pygame, _window_event_name, None)
                        if _window_event_type is not None:
                            pygame.event.clear(_window_event_type)
                    app_state["window_event_guard_until"] = pygame.time.get_ticks() + 400
                    app_state["show_quit_confirm"] = False
                    if sys.platform == "win32":
                        try:
                            print(f"[WINDOW] Minimize/restore toggle complete: is_fullscreen={app_state['is_fullscreen']} "
                                  f"foreground_after={ctypes.windll.user32.GetForegroundWindow()} "
                                  f"is_window_hwnd_foreground={ctypes.windll.user32.GetForegroundWindow() == _win_hwnd_dbg}")
                        except Exception as _swallowed_error:
                            _log_swallowed("main script: print(f\"[WINDOW] Minimize/restore toggle complete: is_fullscreen={app_state['is_fullscr...", _swallowed_error)
                elif menu_nav.is_back(event.key):
                    app_state["show_quit_confirm"] = False
                continue

            if (event.key == pygame.K_c
                    and not app_state.get("show_menu", False)):
                app_state["show_splash"] = True
                app_state["splash_shown_at"] = now_ticks
                app_state["controls_splash_page"]  = 0
                app_state["controls_splash_focus"] = 1
                continue

            if menu_nav.is_back(event.key) and app_state.get("show_menu", False):
                _layer = app_state.get("menu_layer", "TAB_SELECTION")

                if _layer == "DVD_BTN_MAP" and app_state.get("dvd_map_capturing", False):
                    app_state["dvd_map_capturing"] = False
                    print("[DVD REMAP] Capture cancelled.")
                    continue

                _sub_menu_parent = {
                    "CHANNEL_SUB_MENU":     "CHANNEL_LIST",
                    "CHANNEL_SETTINGS_SUB_MENU": "CHANNEL_LIST",
                    "HOLIDAY_SUB_MENU":     "CHANNEL_SUB_MENU",
                    "COMMERCIALS_SUB_MENU": "CHANNEL_SUB_MENU",
                    "AUDIO_TRACK_PICKER":   "CHANNEL_SUB_MENU",
                    "GAMES_SUB_MENU":       "GAMES_LIST",
                    "GAMES_CTRL_MAP":       "GAMES_SUB_MENU",
                    "GAMES_STICK_DZ":       "GAMES_SUB_MENU",
                    "GAMES_SAVE_PROFILE":   "GAMES_SUB_MENU",
                    "REMOTE_REMAP_LIST":    "SYSTEM_ADVANCED_SUB_MENU",
                    "SERVER_MENU":          "SYSTEM_ADVANCED_SUB_MENU",
                    "SERVER_SLOTS_MENU":    "SERVER_MENU",
                    "SERVER_SLOT_ACTIONS":  "SERVER_SLOTS_MENU",
                    "SERVER_PICKER_MENU":   "SERVER_MENU",
                    "DVD_BTN_MAP":          "GAMES_SUB_MENU",
                    "SYSTEM_ADVANCED_SUB_MENU": "SYSTEM_ROWS",
                }.get(_layer)
                if _layer == "AUDIO_TRACK_PICKER" and app_state.get("audio_track_context") == "dvd":
                    _sub_menu_parent = "GAMES_SUB_MENU"
                if _sub_menu_parent is not None:
                    app_state["menu_layer"] = _sub_menu_parent
                    if _layer == "AUDIO_TRACK_PICKER" and app_state.get("audio_track_context") == "dvd":
                        _dvd_rows_now = ["status"] + get_games_sub_menu_rows(db, app_state, "DVD", True) + ["close"]
                        app_state["games_sub_row"] = (
                            _dvd_rows_now.index("dvd_audio_track") if "dvd_audio_track" in _dvd_rows_now else 0
                        )
                    elif _layer == "AUDIO_TRACK_PICKER":
                        _atp_ch = db.channels_db.get(str(app_state.get("selected_channel_row", "")).zfill(2), {})
                        _atp_marathon = menu_nav.shown_scheduling_mode(_atp_ch) == "marathon"
                        app_state["sub_menu_row_index"] = 5 if _atp_marathon else 6
                        app_state["sub_menu_col_index"] = 0 if _atp_marathon else 1
                    elif _layer == "REMOTE_REMAP_LIST":
                        _as_rows_now = get_advanced_settings_menu_rows(db, app_state)
                        app_state["menu_selection_index"] = (
                            _as_rows_now.index("remote_remap") if "remote_remap" in _as_rows_now else 0
                        )
                    elif _layer == "SERVER_MENU":
                        _as_rows_now = get_advanced_settings_menu_rows(db, app_state)
                        app_state["menu_selection_index"] = (
                            _as_rows_now.index("server_menu_open") if "server_menu_open" in _as_rows_now else 0
                        )
                    elif _layer == "SYSTEM_ADVANCED_SUB_MENU":
                        _sys_rows_now = get_system_menu_rows(db, app_state)
                        app_state["menu_selection_index"] = (
                            _sys_rows_now.index("advanced_settings") if "advanced_settings" in _sys_rows_now else 0
                        )
                    elif _layer == "SERVER_SLOTS_MENU":
                        app_state["menu_selection_index"] = 2
                    elif _layer == "SERVER_SLOT_ACTIONS":
                        app_state["server_slot_pending_delete"] = False
                        app_state["menu_selection_index"] = app_state.get("server_slot_name_target_row", 0)
                    elif _layer == "SERVER_PICKER_MENU":
                        app_state["menu_selection_index"] = 2
                    elif _layer == "DVD_BTN_MAP":
                        _dvd_rows_now = ["status"] + get_games_sub_menu_rows(db, app_state, "DVD", True) + ["close"]
                        app_state["games_sub_row"] = (
                            _dvd_rows_now.index("dvd_button_mapping") if "dvd_button_mapping" in _dvd_rows_now else 0
                        )
                        app_state["dvd_map_capturing"] = False
                    elif _layer == "CHANNEL_SETTINGS_SUB_MENU":
                        app_state["menu_selection_index"] = 43
                    elif _layer == "COMMERCIALS_SUB_MENU":
                        app_state["sub_menu_row_index"] = 3
                        app_state["sub_menu_col_index"] = 1
                    elif _layer == "HOLIDAY_SUB_MENU":
                        _holiday_ch = db.channels_db.get(str(app_state.get("selected_channel_row", 5)).zfill(2), {})
                        app_state["sub_menu_row_index"] = 5 if menu_nav.shown_scheduling_mode(_holiday_ch) == "marathon" else 6
                        app_state["sub_menu_col_index"] = 0
                    else:
                        app_state["sub_menu_row_index"] = 0
                        app_state["sub_menu_col_index"] = 0
                    print(f"[SETTINGS ENGINE] ESC: stepped back from {_layer} to {_sub_menu_parent}.")
                else:
                    if app_state.get("current_channel") != "04":
                        app_state["loaded_preview_path_cache"] = ""
                    app_state["show_menu"] = False
                    app_state["games_tab_page"] = 0
                    app_state["menu_shown_at"] = 0
                    app_state["_esc_menu_close_guard_until"] = now_ticks + 400
                    print("[SETTINGS ENGINE] Overlay menu dismissed via ESCAPE.")
                continue

            if menu_nav.is_back(event.key) and not app_state.get("show_menu", False):
                if app_state.get("current_channel") == "03" and 'game_deck' in globals() and game_deck is not None:
                    if getattr(game_deck, "mode", "") == "GAME":
                        if (now_ticks >= app_state.get("_esc_menu_close_guard_until", 0)
                                and not getattr(game_deck, "emulator_loading", False)):
                            game_deck._exit_key_event_at = pygame.time.get_ticks()
                        else:
                            print("[GAME EXIT] Esc ignored (menu just closed or game still loading).")
                        continue

                if now_ticks < app_state.get("_esc_menu_close_guard_until", 0):
                    print("[SETTINGS ENGINE] ESC swallowed: duplicate of the press that just closed the menu.")
                    continue

                if not app_state.get("shell_takeover_active", False):
                    app_state["show_quit_confirm"] = True
                    app_state["quit_confirm_shown_at"] = now_ticks
                continue

            if event.key == pygame.K_m:
                if app_state.get("show_menu", False):
                    if app_state.get("current_channel") != "04":
                        app_state["loaded_preview_path_cache"] = ""
                    app_state["show_menu"] = False
                    app_state["games_tab_page"] = 0
                    app_state["menu_shown_at"] = 0
                else:
                    if app_state.get("show_splash", False):
                        app_state["show_splash"] = False
                    app_state["show_menu"] = True
                    app_state["menu_shown_at"] = now_ticks
                    app_state["active_menu_tab"] = "System"
                    app_state["menu_layer"] = "TAB_SELECTION"
                    if db is not None and db.config.get("game_channel_enabled", True):
                        preload_games_tab_assets(app_state)
                    print("[SETTINGS ENGINE] Main overlay menu initialized.")
                continue

            if app_state["current_channel"] == "04" and not app_state["show_menu"] and not app_state["show_quit_confirm"] and not app_state["show_splash"]:
                now_ticks = pygame.time.get_ticks()
                
                if menu_nav.key_to_direction(event.key, arrows=True) is not None or menu_nav.is_accept(event.key):
                    app_state["guide_inactivity_timer"] = now_ticks + MENU_IDLE_CLOSE_MS

                if menu_nav.is_accept(event.key):
                    target_tuning_channel = str(app_state["selected_guide_channel"]).zfill(2)
                    print(f"[EPG TUNER] Activation dispatch caught. Tuning to selected row channel: {target_tuning_channel}")
                    change_channel(target_tuning_channel, is_surfing=True)
                    continue

                elif menu_nav.key_to_direction(event.key) is not None:
                    _guide_axis, _guide_step = menu_nav.guide_move(menu_nav.key_to_direction(event.key))
                    if _guide_axis == menu_nav.GUIDE_TIME:
                        _guide_jump_col(_guide_step, _source="keydown")
                        continue
                    _guide_step_row(_guide_step, True)
                    continue

            if app_state.get("show_menu", False):
                pass
            else:
                pressed_digit = menu_nav.key_to_digit(event.key)

                if pressed_digit is not None:
                    _surf_digit_typed(pressed_digit, now_ticks)
                    continue

                if event.key == pygame.K_n:
                    db.config["is_muted"] = not db.config.get("is_muted", False)
                    app_state["osd_volume_timer"] = now_ticks + 2500
                    if game_deck is not None:
                        game_deck.dvd_osd_msg = ""; game_deck.dvd_osd_until = 0
                    
                    safe_mute_flag = db.config["is_muted"]
                    current_vol = 0 if safe_mute_flag else int(db.config.get("global_volume", 70))
                    target_gain = _perceptual_volume_pct(current_vol) / 100.0
                    music_target_gain = _perceptual_volume_pct(current_vol, min_db=STACKED_GAIN_MIN_DB) / 100.0
                    
                    if vlc_engine is not None:
                        _refresh_live_file_gain()
                        vlc_engine.set_volume(current_vol, safe_mute_flag)
                    _set_dvd_volume(int(db.config.get("global_volume", 70)), safe_mute_flag)
                    if static_audio is not None: 
                        static_audio.set_volume(target_gain * _effective_loudness_gain(_STATIC_AUDIO_GAIN))
                    pygame.mixer.music.set_volume(
                        music_target_gain * MUSIC_GAIN
                        * _effective_loudness_gain(app_state.get("active_music_gain", 1.0)))
                    pygame.mixer.Channel(1).set_volume(
                        music_target_gain * MUSIC_GAIN
                        * _effective_loudness_gain(app_state.get("active_music_gain", 1.0)))
                    if game_deck is not None and hasattr(game_deck, "set_libretro_volume"):
                        game_deck.set_libretro_volume(
                            db.config.get("global_volume", 70), db.config.get("is_muted", False))
                    _set_ch03_menu_music_volume(db.config.get("global_volume", 70), safe_mute_flag)
                    
                    _mark_settings_dirty()
                    continue

                elif event.key in [pygame.K_RIGHT, pygame.K_LEFT]:
                    if not menu_nav.step_ready(app_state.setdefault("_step_gate", {}), "volume", now_ticks):
                        continue
                    db.config["global_volume"] = menu_nav.volume_next(
                        db.config.get("global_volume", 70), menu_nav.volume_direction(event.key))
                        
                    app_state["osd_volume_timer"] = now_ticks + 2500
                    if game_deck is not None:
                        game_deck.dvd_osd_msg = ""; game_deck.dvd_osd_until = 0
                    db.config["is_muted"] = False 
                    
                    target_gain = _perceptual_volume_pct(db.config["global_volume"]) / 100.0
                    music_target_gain = _perceptual_volume_pct(db.config["global_volume"], min_db=STACKED_GAIN_MIN_DB) / 100.0
                    
                    if vlc_engine is not None:
                        _refresh_live_file_gain()
                        vlc_engine.set_volume(int(db.config["global_volume"]), False)
                    _set_dvd_volume(int(db.config["global_volume"]), False)
                    if static_audio is not None: 
                        static_audio.set_volume(target_gain * _effective_loudness_gain(_STATIC_AUDIO_GAIN))
                    pygame.mixer.music.set_volume(
                        music_target_gain * MUSIC_GAIN
                        * _effective_loudness_gain(app_state.get("active_music_gain", 1.0)))
                    pygame.mixer.Channel(1).set_volume(
                        music_target_gain * MUSIC_GAIN
                        * _effective_loudness_gain(app_state.get("active_music_gain", 1.0)))
                    if game_deck is not None and hasattr(game_deck, "set_libretro_volume"):
                        game_deck.set_libretro_volume(
                            db.config.get("global_volume", 70), db.config.get("is_muted", False))
                    _set_ch03_menu_music_volume(db.config["global_volume"], db.config.get("is_muted", False))
                    
                    _mark_settings_dirty()
                    continue

                elif event.key == pygame.K_UP:
                    if app_state.get("_chsurf_display_gate", False):
                        continue
                    app_state["_chsurf_display_gate"] = True
                    _surf_step(1)
                    continue

                elif event.key == pygame.K_DOWN:
                    if app_state.get("_chsurf_display_gate", False):
                        continue
                    app_state["_chsurf_display_gate"] = True
                    _surf_step(-1)
                    continue

            if app_state.get("show_menu", False):
                game_ch_on = db.config.get("game_channel_enabled", True) if db is not None else False
                kiosk_on = db.config.get("kiosk_mode_enabled", False) if db is not None else False
                tabs_pool = ["System", "Channels", "Games", "Video", "Theme"] if game_ch_on else ["System", "Channels", "Video", "Theme"]
                if kiosk_on:
                    tabs_pool = [t for t in tabs_pool if t != "Channels"]
                if not game_ch_on and app_state.get("active_menu_tab") == "Games":
                    app_state["active_menu_tab"] = "System"
                    app_state["menu_layer"] = "TAB_SELECTION"
                if kiosk_on and app_state.get("active_menu_tab") == "Channels":
                    app_state["active_menu_tab"] = "System"
                    app_state["menu_layer"] = "TAB_SELECTION"

                if app_state["menu_layer"] == "TAB_SELECTION":
                    _tb_dir = menu_nav.key_to_direction(event.key)
                    if _tb_dir is not None:
                        _tb_from = menu_nav.tabs_cell(tabs_pool, app_state.get("active_menu_tab", "System"))
                        _tb_to = menu_nav.navigate(app_state, "TAB_SELECTION", menu_nav.tabs_table(tabs_pool), _tb_from, _tb_dir)
                        if _tb_to == menu_nav.PANEL:
                            target_layer = menu_nav.TAB_PANEL_LAYERS.get(app_state["active_menu_tab"], "SYSTEM_ROWS")
                            app_state["menu_layer"] = target_layer
                            if target_layer == "GAMES_LIST":
                                from game_deck import CONSOLE_ORDER
                                _gl_page = min(app_state.get("games_tab_page", 0), menu_nav.games_page_count(len(CONSOLE_ORDER)) - 1)
                                app_state["menu_selection_index"] = _gl_page * menu_nav.GAMES_PAGE_SIZE
                            elif target_layer == "CHANNEL_LIST":
                                _cl_page = min(app_state.get("channels_tab_page", 0), menu_nav.CHANNELS_NUM_PAGES - 1)
                                app_state["menu_selection_index"] = _cl_page * menu_nav.CHANNELS_PAGE_SIZE
                            else:
                                app_state["menu_selection_index"] = 0
                            print(f"[MENU NAVIGATION] Dropped cursor down into sub-panel layer: {target_layer}")
                        elif _tb_to is not None:
                            app_state["active_menu_tab"] = _tb_to
                            print(f"[MENU NAVIGATION] Swapped tab focus {'right' if _tb_dir == menu_nav.RIGHT else 'left'} to: {app_state['active_menu_tab']}")
                        continue

                elif app_state["menu_layer"] == "CHANNEL_LIST":
                    cur_sel = app_state.get("menu_selection_index", 0)

                    _cl_dir = menu_nav.key_to_direction(event.key)
                    if _cl_dir is not None:
                        _cl_from = menu_nav.channels_cell(cur_sel)
                        if _cl_from is not None:
                            _cl_table = menu_nav.channels_table(menu_nav.channels_page_of(cur_sel, app_state.get("channels_tab_page", 0)))
                            _cl_to = menu_nav.navigate(app_state, "CHANNEL_LIST", _cl_table, _cl_from, _cl_dir)
                            if _cl_to == menu_nav.TAB_BAR:
                                app_state["menu_layer"] = "TAB_SELECTION"
                            elif _cl_to is not None:
                                app_state["menu_selection_index"] = menu_nav.channels_index(_cl_to)
                        continue

                    if menu_nav.is_accept(event.key):
                        if cur_sel == 43:
                            app_state["menu_layer"] = "CHANNEL_SETTINGS_SUB_MENU"
                            app_state["menu_selection_index"] = 0
                            pygame.event.clear(pygame.KEYDOWN)
                            continue
                        elif cur_sel == 42:
                            app_state["channels_tab_page"] = (app_state.get("channels_tab_page", 0) + 1) % menu_nav.CHANNELS_NUM_PAGES
                        elif cur_sel == 99:
                            if app_state.get("current_channel") != "04":
                                app_state["loaded_preview_path_cache"] = ""
                            app_state["show_menu"] = False
                            app_state["games_tab_page"] = 0
                            app_state["menu_shown_at"] = 0
                        else:
                            selected_ch_num = cur_sel + 5
                            app_state["selected_channel_row"] = selected_ch_num
                            app_state["sub_menu_row_index"] = 0

                            _ch_str_entry = str(selected_ch_num).zfill(2)
                            _ch_active_entry = db.channels_db.get(_ch_str_entry, {}).get("active", True)
                            _active_count_entry = sum(
                                1 for _n in range(5, 45)
                                if db.channels_db.get(str(_n).zfill(2), {}).get("active", str(_n).zfill(2) == "05")
                            )
                            _is_last = _ch_active_entry and (_active_count_entry <= 1)
                            app_state["sub_menu_col_index"] = 1 if _is_last else 0

                            app_state["menu_layer"] = "CHANNEL_SUB_MENU"
                            print(f"[MENU NAVIGATION] Selected Channel {str(selected_ch_num).zfill(2)}. Opening sub-menu details window.")
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "CHANNEL_SETTINGS_SUB_MENU":
                    cur_row = app_state.get("menu_selection_index", 0)
                    _cs_rows = get_channels_settings_menu_rows(db, app_state)
                    _cs_row_id = _cs_rows[cur_row] if cur_row < len(_cs_rows) else "close"

                    _cs_dir = menu_nav.key_to_direction(event.key)
                    if _cs_dir is not None:
                        _cs_to = menu_nav.navigate(app_state, "CHANNEL_SETTINGS_SUB_MENU", menu_nav.channel_settings_table(_cs_rows), menu_nav.channel_settings_cell(_cs_rows, cur_row), _cs_dir)
                        if _cs_to is not None:
                            app_state["menu_selection_index"] = menu_nav.channel_settings_index(_cs_rows, _cs_to)
                        continue

                    if menu_nav.is_accept(event.key):
                        if _cs_row_id in ("scan_lines", "static_noise", "warp_screen",
                                          "reception_lines", "bezel_toggle", "boot_anim"): 
                            _now_tk  = pygame.time.get_ticks()
                            _tgl_deb = app_state.setdefault("_menu_toggle_debounce", {})
                            if _now_tk - _tgl_deb.get(_cs_row_id, -10000) < 300:
                                pygame.event.clear(pygame.KEYDOWN)
                                continue
                            _tgl_deb[_cs_row_id] = _now_tk
                        if _cs_row_id == "scan_lines" and _feature_locked("fake_43_scanlines_enabled"):
                            # WARNING: Enter is a no-op while the mode locks this row; the stored setting must not flip.
                            pygame.event.clear(pygame.KEYDOWN)
                        elif _cs_row_id == "warp_screen" and (_feature_locked("warp_screen_enabled") or not _warp_bezel_available()):
                            # WARNING: Enter is a no-op while the mode locks this row or no bezel that warps is on; the stored setting must not flip, it is kept for the next bezel.
                            pygame.event.clear(pygame.KEYDOWN)
                        elif _cs_row_id == "scan_lines":
                            db.config["fake_43_scanlines_enabled"] = not db.config.get("fake_43_scanlines_enabled", False)
                            db.save_settings()
                            print(f"[SETTINGS] Scan Lines = {db.config['fake_43_scanlines_enabled']}")
                        elif _cs_row_id == "static_noise":
                            db.config["fake_static_noise_enabled"] = not db.config.get("fake_static_noise_enabled", False)
                            db.save_settings()
                            print(f"[SETTINGS] Static Noise = {db.config['fake_static_noise_enabled']}")
                        elif _cs_row_id == "warp_screen":
                            db.config["warp_screen_enabled"] = not db.config.get("warp_screen_enabled", False)
                            db.save_settings()
                            print(f"[SETTINGS] Warp Screen = {db.config['warp_screen_enabled']}")
                        elif _cs_row_id == "reception_lines":
                            db.config["fake_reception_lines_enabled"] = not db.config.get("fake_reception_lines_enabled", False)
                            db.save_settings()
                            print(f"[SETTINGS] Reception Lines = {db.config['fake_reception_lines_enabled']}")
                        elif _cs_row_id == "bezel_toggle":
                            _bz_turning_on = not db.config.get("fake_43_border_enabled", False)
                            if _bz_turning_on:
                                if db.config.get("program_bezel_skip_confirm", False):
                                    log.info("[BEZEL DEBUG] TV Bezel ON (skip-confirm path), channel=%s",
                                             app_state.get("current_channel"))
                                    db.config["fake_43_border_enabled"] = True
                                    db.save_settings()
                                    print("[SETTINGS] Bezel = True (confirmation skipped by user preference).")
                                else:
                                    app_state["show_clear_confirm"]      = True
                                    app_state["clear_confirm_selection"]  = "No"
                                    app_state["clear_confirm_target"]     = "program_bezel_toggle"
                                    app_state["clear_confirm_shown_at"]   = now_ticks
                                    app_state["clear_confirm_burnin_new_value"] = True
                                    app_state["clear_confirm_dont_show_again"]  = False
                            else:
                                log.info("[BEZEL DEBUG] TV Bezel OFF, channel=%s",
                                         app_state.get("current_channel"))
                                db.config["fake_43_border_enabled"] = False
                                db.save_settings()
                                print("[SETTINGS] Bezel = False")
                        elif _cs_row_id == "bezel_style_select":
                            _n_styles = _effective_bezel_style_count(*screen.get_size())
                            if _n_styles > 1 and db.config.get("fake_43_border_enabled", False):
                                _cur_style = db.config.get("bezel_style", 1)
                                try:
                                    _cur_style = int(_cur_style)
                                except (TypeError, ValueError) as _swallowed_error:
                                    _log_swallowed("module: _cur_style = int(_cur_style)", _swallowed_error)
                                    _cur_style = 1
                                db.config["bezel_style"] = (_cur_style % _n_styles) + 1
                                db.save_settings()
                                print(f"[SETTINGS] Bezel Style = {db.config['bezel_style']}")
                        elif _cs_row_id == "boot_anim":
                            db.config["boot_anim_enabled"] = not db.config.get("boot_anim_enabled", False)
                            db.save_settings()
                            print(f"[SETTINGS] Boot Anim = {db.config['boot_anim_enabled']}")
                        else:
                            app_state["menu_layer"] = "CHANNEL_LIST"
                            app_state["menu_selection_index"] = 43
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "SYSTEM_ADVANCED_SUB_MENU":
                    cur_row = app_state.get("menu_selection_index", 0)
                    _as_rows = get_advanced_settings_menu_rows(db, app_state)
                    _as_row_id = _as_rows[cur_row] if cur_row < len(_as_rows) else "close"

                    _as_dir = menu_nav.key_to_direction(event.key)
                    if _as_dir is not None:
                        _as_to = menu_nav.navigate(app_state, "SYSTEM_ADVANCED_SUB_MENU", menu_nav.advanced_table(_as_rows), menu_nav.advanced_cell(_as_rows, cur_row), _as_dir)
                        if _as_to is not None:
                            app_state["menu_selection_index"] = menu_nav.advanced_index(_as_rows, _as_to)
                        continue
                    if menu_nav.is_accept(event.key):
                        if _as_row_id == "server_option" and not UPDATER_AND_SERVER_FEATURES_ENABLED:
                            # WARNING: the Server subsystem is disabled in packaging; this row is a deliberate no-op.
                            pass
                        elif _as_row_id == "server_option" and not SERVER_TOGGLE_ENABLED:
                            # WARNING: the Server Mode toggle is greyed out for now (ui.SERVER_TOGGLE_ENABLED); the row can be reached but pressing it changes nothing.
                            pass
                        elif _as_row_id == "server_option":
                            db.config["server_mode_enabled"] = not db.config.get("server_mode_enabled", False)
                            if (not db.config["server_mode_enabled"]
                                    and app_state.get("active_remote_server") is not None):
                                _disconnect_remote_server("Server Mode turned off")
                            if not db.config["server_mode_enabled"] and db.config.get("active_server_slot") is not None:
                                db.leave_server_slot()
                                print("[SERVER SLOTS] Server Mode turned off while a slot was active — channels back to main project")
                            db.save_settings()
                            print(f"[SETTINGS] Server Mode = {db.config['server_mode_enabled']}")
                        elif _as_row_id == "server_menu_open":
                            if UPDATER_AND_SERVER_FEATURES_ENABLED and db.config.get("server_mode_enabled", False):
                                app_state["menu_layer"] = "SERVER_MENU"
                                app_state["menu_selection_index"] = 0
                        elif _as_row_id == "boot_on_start":
                            _new_boot_val = not db.config.get("start_on_boot", False)
                            if _new_boot_val:
                                app_state["show_clear_confirm"]     = True
                                app_state["clear_confirm_selection"] = "No"
                                app_state["clear_confirm_target"]   = "boot_on_start"
                                app_state["clear_confirm_shown_at"] = now_ticks
                            elif _set_start_on_boot(False):
                                db.config["start_on_boot"] = False
                                db.save_settings()
                                print("[SETTINGS] Boot on Start = False")
                        elif _as_row_id == "update_check" and not UPDATER_AND_SERVER_FEATURES_ENABLED:
                            pass
                        elif _as_row_id == "update_check":
                            if app_state.get("_update_check_inflight", False):
                                pass
                            elif app_state.get("_update_ready", False):
                                _launch_staged_update()
                            elif app_state.get("_update_available", False) and app_state.get("_update_record"):
                                # WARNING: Update Now must reopen the popup without a fresh check; the check is only for Look for Updates.
                                _open_update_popup(app_state["_update_record"], False)
                            else:
                                _start_update_check()
                        elif _as_row_id == "performance_mode":
                            _cycle_performance_mode()
                        elif _as_row_id == "gpu_render_mode" and not GPU_RENDER_MODE_ENABLED:
                            pass
                        elif _as_row_id == "gpu_render_mode":
                            _render_opts = _gpu_render_mode_options(db)
                            _render_values = [v for v, _ in _render_opts]
                            _cur_val = db.config.get("render_mode_override", "cpu_only")
                            if _cur_val not in _render_values:
                                _cur_val = "cpu_only"
                            _next_i = (_render_values.index(_cur_val) + 1) % len(_render_values)
                            db.config["render_mode_override"] = _render_values[_next_i]
                            db.config["render_mode_user_chosen"] = True
                            db.save_settings()
                            print(f"[SETTINGS] GPU/CPU render mode = {db.config['render_mode_override']}")
                        elif _as_row_id == "remote_remap":
                            app_state["menu_layer"] = "REMOTE_REMAP_LIST"
                            app_state["menu_selection_index"] = 0
                            app_state["remote_remap_index"] = 0
                        else:
                            app_state["menu_layer"] = "SYSTEM_ROWS"
                            _sys_rows_now = get_system_menu_rows(db, app_state)
                            app_state["menu_selection_index"] = (
                                _sys_rows_now.index("advanced_settings") if "advanced_settings" in _sys_rows_now else 0
                            )
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "SYSTEM_ROWS":

                    cur_row = app_state.get("menu_selection_index", 0)
                    sys_rows = get_system_menu_rows(db, app_state)
                    sys_rows_close_idx = len(sys_rows)
                    ccolor_focused  = (cur_row == CAPTIONS_COLOR_BOX_SEL)
                    if ccolor_focused:
                        row_id = "captions_toggle"
                    else:
                        row_id = sys_rows[cur_row] if cur_row < len(sys_rows) else "close"

                    _nav_dir = menu_nav.key_to_direction(event.key)
                    if _nav_dir is not None:
                        _nav_from = menu_nav.system_cell(sys_rows, cur_row)
                        if _nav_from is not None:
                            _nav_to = menu_nav.navigate(app_state, "SYSTEM_ROWS", menu_nav.system_table(sys_rows), _nav_from, _nav_dir)
                            if _nav_to == menu_nav.TAB_BAR:
                                app_state["menu_layer"] = "TAB_SELECTION"
                            elif _nav_to is not None:
                                app_state["menu_selection_index"] = menu_nav.system_index(sys_rows, _nav_to)
                        continue

                    if menu_nav.is_accept(event.key):
                        is_enter = True

                        if ccolor_focused:
                            if _setting_on("tv_captions_enabled"):
                                from game_deck import LIST_TEXT_COLOR_NAMES
                                _cur_cc = db.config.get("tv_captions_color", "white")
                                try:
                                    _cci = LIST_TEXT_COLOR_NAMES.index(_cur_cc)
                                except ValueError as _swallowed_error:
                                    _log_swallowed("module: _cci = LIST_TEXT_COLOR_NAMES.index(_cur_cc)", _swallowed_error)
                                    _cci = 0
                                db.config["tv_captions_color"] = LIST_TEXT_COLOR_NAMES[(_cci + 1) % len(LIST_TEXT_COLOR_NAMES)]
                                db.save_settings()
                                print(f"[SETTINGS] TV Captions Color = {db.config['tv_captions_color']}")
                        elif row_id == "game_ch":
                            db.config["game_channel_enabled"] = not db.config.get("game_channel_enabled", True)
                            db.save_settings()
                            print(f"[SETTINGS] Channel 03 (Games) flipped to: {db.config['game_channel_enabled']}")
                            if not db.config.get("game_channel_enabled", True):
                                _surf_up_from_disabled("03")
                        elif row_id == "guide":
                            db.config["tv_guide_enabled"] = not db.config.get("tv_guide_enabled", True)
                            db.save_settings()
                            print(f"[SETTINGS] Channel 04 (TV Guide) flipped to: {db.config['tv_guide_enabled']}")
                            if not db.config.get("tv_guide_enabled", True):
                                _surf_up_from_disabled("04")
                        elif row_id == "controls_on_start":
                            db.config["show_controls_on_launch"] = not db.config.get("show_controls_on_launch", True)
                            db.save_settings()
                            print(f"[SETTINGS] Controls Menu on Start = {db.config['show_controls_on_launch']}")
                        elif row_id == "advanced_settings":
                            app_state["menu_layer"] = "SYSTEM_ADVANCED_SUB_MENU"
                            app_state["menu_selection_index"] = 0
                        elif row_id == "kiosk_mode":
                            db.config["kiosk_mode_enabled"] = not db.config.get("kiosk_mode_enabled", False)
                            db.save_settings()
                            print(f"[SETTINGS] Kiosk Mode = {db.config['kiosk_mode_enabled']}")
                            if db.config["kiosk_mode_enabled"] and not app_state.get("is_fullscreen", False):
                                WINDOW_WIDTH, WINDOW_HEIGHT = NATIVE_WIDTH, NATIVE_HEIGHT
                                screen = _set_display_mode((WINDOW_WIDTH, WINDOW_HEIGHT), pygame.NOFRAME)
                                app_state["is_fullscreen"] = True
                                _finalize_window_mode(
                                    screen, windowed=False,
                                    client_w=WINDOW_WIDTH, client_h=WINDOW_HEIGHT,
                                    pos_x=0, pos_y=0,
                                )
                            _new_sys_rows = get_system_menu_rows(db, app_state)
                            app_state["menu_selection_index"] = _new_sys_rows.index("kiosk_mode")
                        elif row_id == "loudness_scan":
                            _loudness_was_enabled = db.config.get("loudness_scan_enabled", True)
                            db.config["loudness_scan_enabled"] = not _loudness_was_enabled
                            _loudness_now_enabled = db.config["loudness_scan_enabled"]
                            if _loudness_was_enabled and not _loudness_now_enabled:
                                db.config["volume_loudness_on"] = db.config.get("global_volume", 70)
                                if not db.config.get("loudness_off_seen", False):
                                    db.config["global_volume"] = 50
                                    db.config["is_muted"] = False
                                    db.config["loudness_off_seen"] = True
                                    print("[SETTINGS] Loudness Scan off for the first time -- "
                                          "volume set to 50% for safety")
                                else:
                                    # WARNING: a restored off-volume must never come back above 70, or repeated toggles can ratchet it upward.
                                    _remembered_off_vol = db.config.get("volume_loudness_off", 50)
                                    db.config["global_volume"] = min(70, _remembered_off_vol)
                            elif _loudness_now_enabled and not _loudness_was_enabled:
                                db.config["volume_loudness_off"] = db.config.get("global_volume", 70)
                                db.config["global_volume"] = db.config.get(
                                    "volume_loudness_on", db.config.get("global_volume", 70))
                            db.save_settings()
                            print(f"[SETTINGS] Loudness Scan = {db.config['loudness_scan_enabled']}")
                            if _loudness_was_enabled != _loudness_now_enabled:
                                app_state["osd_volume_timer"] = now_ticks + 2500
                            # WARNING: apply the setting to the active audio players right now; do not wait for the next file or channel change.
                            _apply_loudness_setting_live()
                            try:
                                _reload_visualizer_music_for_loudness_toggle()
                            except Exception as _vis_reload_err:
                                _log_warn_throttled("loudness_toggle_visualizer_reload",
                                                     "[SETTINGS] Loudness Scan Visualizer reload "
                                                     "failed: %s", _vis_reload_err)
                            try:
                                _rebuild_vlc_engines_for_loudness_toggle()
                            except Exception as _rebuild_err:
                                _log_warn_throttled("loudness_toggle_rebuild_call",
                                                     "[SETTINGS] Loudness Scan engine rebuild "
                                                     "failed: %s", _rebuild_err)
                            if db.config["loudness_scan_enabled"]:
                                try:
                                    _cur_ch = str(app_state.get("current_channel", "")).zfill(2)
                                    _cur_state = _get_probe_now_state(_cur_ch)
                                    if _cur_state.get("mode") == "Video" and _cur_state.get("file"):
                                        _prime_channel_block_loudness(
                                            _cur_ch, _cur_state["file"], _cur_state.get("block"))
                                except Exception as _toggle_gain_err:
                                    log.warning("[SETTINGS] Loudness Scan on-toggle priority "
                                                "probe dispatch failed: %s", _toggle_gain_err)
                        elif row_id == "pixel_orbiter":
                            _po_turning_off = db.config.get("pixel_orbiter_enabled", True)
                            if _po_turning_off:
                                if db.config.get("pixel_orbiter_skip_confirm", False):
                                    db.config["pixel_orbiter_enabled"] = False
                                    db.save_settings()
                                    print("[SETTINGS] Pixel Orbiter = False (confirmation skipped by user preference).")
                                else:
                                    app_state["show_clear_confirm"]      = True
                                    app_state["clear_confirm_selection"]  = "No"
                                    app_state["clear_confirm_target"]     = "pixel_orbiter_toggle"
                                    app_state["clear_confirm_shown_at"]   = now_ticks
                                    app_state["clear_confirm_burnin_new_value"] = False
                                    app_state["clear_confirm_dont_show_again"]  = False
                            else:
                                db.config["pixel_orbiter_enabled"] = True
                                db.save_settings()
                                print("[SETTINGS] Pixel Orbiter = True")
                        elif row_id == "captions_toggle" and _feature_locked("tv_captions_enabled"):
                            # WARNING: Enter is a no-op while the mode locks this row; the stored setting must not flip.
                            pygame.event.clear(pygame.KEYDOWN)
                        elif row_id == "captions_toggle":
                            db.config["tv_captions_enabled"] = not db.config.get("tv_captions_enabled", False)
                            db.save_settings()
                            print(f"[SETTINGS] Captions = {db.config['tv_captions_enabled']}")
                            if db.config["tv_captions_enabled"]:
                                _start_caption_model_prewarm("captions switched on")
                        elif row_id == "mono_stereo_toggle":
                            db.config["audio_stereo"] = not db.config.get("audio_stereo", True)
                            db.save_settings()
                            print(f"[SETTINGS] Mono Audio = {not db.config['audio_stereo']}")
                            try:
                                _apply_live_stereo_mode(reason="toggle")
                            except Exception as _live_err:
                                _log_warn_throttled("mono_toggle_live_apply",
                                                     "[SETTINGS] Mono Audio live apply "
                                                     "failed: %s", _live_err)
                            try:
                                _apply_mixer_channels_setting()
                            except Exception as _mixer_err:
                                _log_warn_throttled("mono_toggle_mixer_reinit",
                                                     "[SETTINGS] Mono Audio pygame.mixer reinit "
                                                     "failed: %s", _mixer_err)
                        elif is_enter and row_id == "reset_settings":
                            if _any_settings_to_reset():
                                app_state["show_clear_confirm"]    = True
                                app_state["clear_confirm_selection"] = "No"
                                app_state["clear_confirm_target"]  = "reset_settings"
                                app_state["clear_confirm_shown_at"] = now_ticks
                        elif is_enter and row_id == "exit_program":
                            log.info("[EXIT] Exit program chosen in Settings; shutting down")
                            _exit_program("EXIT")
                        elif is_enter and row_id == "poweroff":
                            app_state["show_clear_confirm"]     = True
                            app_state["clear_confirm_selection"] = "No"
                            app_state["clear_confirm_target"]   = "poweroff"
                            app_state["clear_confirm_shown_at"] = now_ticks
                        elif is_enter and cur_row == sys_rows_close_idx:
                            if app_state.get("current_channel") != "04":
                                app_state["loaded_preview_path_cache"] = ""
                            app_state["show_menu"] = False
                            app_state["games_tab_page"] = 0
                            app_state["menu_shown_at"] = 0
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "SERVER_MENU":
                    srv_sel = app_state.get("menu_selection_index", 0)
                    _srv_role_now = db.config.get("server_role")
                    _srv_manage_visible = _srv_role_now == "server"
                    _srv_pick_visible = _srv_role_now == "user"
                    _srv_extra_btn_visible = _srv_manage_visible or _srv_pick_visible
                    _srv_close_idx = 3 if _srv_extra_btn_visible else 2

                    _srv_dir = menu_nav.key_to_direction(event.key)
                    if _srv_dir is not None:
                        app_state["menu_selection_index"] = menu_nav.column_move(app_state, "SERVER_MENU", srv_sel, _srv_close_idx + 1, _srv_dir)
                        continue

                    if menu_nav.is_accept(event.key):
                        if srv_sel == 0:
                            if app_state.get("active_remote_server") is not None:
                                _disconnect_remote_server("role changed to Server")
                            db.config["server_role"] = "server"
                            db.save_settings()
                            print("[SETTINGS] Server Menu role = server")
                        elif srv_sel == 1:
                            if app_state.get("active_remote_server") is not None:
                                _disconnect_remote_server("role changed to User")
                            if db.config.get("active_server_slot") is not None:
                                db.leave_server_slot()
                                print("[SERVER SLOTS] Left server slot mode (role -> User) — channels back to main project")
                            db.config["server_role"] = "user"
                            db.save_settings()
                            print("[SETTINGS] Server Menu role = user")
                        elif _srv_manage_visible and srv_sel == 2:
                            app_state["menu_layer"] = "SERVER_SLOTS_MENU"
                            app_state["menu_selection_index"] = 0
                        elif _srv_pick_visible and srv_sel == 2:
                            app_state["menu_layer"] = "SERVER_PICKER_MENU"
                            app_state["menu_selection_index"] = 0
                        else:
                            app_state["menu_layer"] = "SYSTEM_ADVANCED_SUB_MENU"
                            _as_rows_now = get_advanced_settings_menu_rows(db, app_state)
                            app_state["menu_selection_index"] = (
                                _as_rows_now.index("server_menu_open") if "server_menu_open" in _as_rows_now else 0
                            )
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "SERVER_PICKER_MENU":
                    _sp_entries = get_server_picker_entries(db)
                    _sp_close_idx = get_server_picker_selectable_count(_sp_entries) - 1
                    sp_sel = app_state.get("menu_selection_index", 0)

                    _sp_dir = menu_nav.key_to_direction(event.key)
                    if _sp_dir is not None:
                        app_state["menu_selection_index"] = menu_nav.column_move(app_state, "SERVER_PICKER_MENU", sp_sel, _sp_close_idx + 1, _sp_dir)
                        continue

                    if menu_nav.is_accept(event.key):
                        if sp_sel < len(_sp_entries):
                            _picked = _sp_entries[sp_sel]
                            _disconnect_remote_server("switching servers")
                            _sync_status_state = {"value": None}
                            def _on_remote_schedule(message):
                                try:
                                    if db.apply_remote_schedule(message.get("channels", {}), message.get("playback")):
                                        app_state["_sched_membership_cache"] = {}
                                        app_state["_guide_preview_position_cache"] = {}
                                        app_state["guide_channel_stamps"] = {}
                                        _guide_dirty_event.set()
                                        app_state["remote_schedule_revision"] = message.get("revision", 0)
                                        log.info(
                                            "Remote schedule applied "
                                            "server=%s slot=%s revision=%s",
                                            _picked["name"], _picked.get("slot_id"),
                                            message.get("revision", 0),
                                        )
                                except Exception as e:
                                    _server_breadcrumb(
                                        log, logging.WARNING,
                                        f"remote-schedule-apply:{_picked.get('host')}:{_picked.get('slot_id')}",
                                        "Remote schedule apply failed "
                                        "server=%s: %s", _picked.get("name"), e,
                                    )
                            def _on_sync_status(status):
                                app_state["remote_server_status"] = status
                                if status != _sync_status_state["value"]:
                                    log.info(
                                        "Remote schedule status "
                                        "server=%s status=%s",
                                        _picked.get("name"), status,
                                    )
                                    _sync_status_state["value"] = status
                            server_schedule_client = server_sync.ScheduleClient(
                                _picked.get("host", ""),
                                port=_picked.get("port", 47532),
                                slot_id=_picked.get("slot_id"),
                                on_schedule=_on_remote_schedule, on_status=_on_sync_status)
                            server_schedule_client.start()
                            app_state["user_selected_server_name"] = _picked["name"]
                            app_state["active_remote_server"] = _picked
                            print(f"[SERVER PICKER] Connected to '{_picked['name']}'")
                            app_state["menu_layer"] = "SYSTEM_ADVANCED_SUB_MENU"
                            _as_rows_now = get_advanced_settings_menu_rows(db, app_state)
                            app_state["menu_selection_index"] = (
                                _as_rows_now.index("server_menu_open") if "server_menu_open" in _as_rows_now else 0
                            )
                        else:
                            app_state["menu_layer"] = "SERVER_MENU"
                            app_state["menu_selection_index"] = 2
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "SERVER_SLOTS_MENU":
                    slot_ids = db.SERVER_SLOT_IDS
                    named = dict(db.config.get("server_slots", {}))
                    can_add_now = len(named) < len(slot_ids)
                    ss_sel = app_state.get("menu_selection_index", 0)
                    CREATE_IDX, MANAGE_IDX, CLOSE_IDX = 6, 7, 8

                    _ss_dir = menu_nav.key_to_direction(event.key)
                    if _ss_dir is not None:
                        _ss_to = menu_nav.navigate(app_state, "SERVER_SLOTS_MENU", menu_nav.server_slots_table(), menu_nav.server_slots_cell(ss_sel), _ss_dir)
                        if _ss_to is not None:
                            app_state["menu_selection_index"] = menu_nav.server_slots_index(_ss_to)
                        continue

                    if menu_nav.is_accept(event.key):
                        if ss_sel < 6:
                            slot_id = slot_ids[ss_sel]
                            if slot_id in named:
                                app_state["menu_layer"] = "SERVER_SLOT_ACTIONS"
                                app_state["menu_selection_index"] = 0
                                app_state["server_slot_name_target_row"] = ss_sel
                                app_state["server_slot_pending_delete"] = False
                        elif ss_sel == CREATE_IDX:
                            if can_add_now:
                                first_free = next((i for i, sid in enumerate(slot_ids) if sid not in named), None)
                                if first_free is not None:
                                    app_state["menu_selection_index"] = first_free
                                    app_state["editing_server_slot_name"] = True
                                    app_state["server_slot_name_mode"] = "create"
                                    app_state["server_slot_name_buffer"] = ""
                                    app_state["server_slot_name_all_selected"] = False
                                    app_state["server_slot_name_target_row"] = first_free
                        elif ss_sel == MANAGE_IDX:
                            if named:
                                first_named = next((i for i, sid in enumerate(slot_ids) if sid in named), 0)
                                app_state["menu_selection_index"] = first_named
                        else:
                            app_state["menu_layer"] = "SERVER_MENU"
                            app_state["menu_selection_index"] = 2
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "SERVER_SLOT_ACTIONS":
                    sa_sel = app_state.get("menu_selection_index", 0)
                    slot_ids = db.SERVER_SLOT_IDS
                    named = dict(db.config.get("server_slots", {}))
                    target_row = app_state.get("server_slot_name_target_row", 0)
                    target_slot_id = slot_ids[target_row] if 0 <= target_row < len(slot_ids) else None
                    target_name = named.get(target_slot_id, "") if target_slot_id else ""

                    _sa_dir = menu_nav.key_to_direction(event.key)
                    if _sa_dir is not None:
                        app_state["menu_selection_index"] = menu_nav.column_move(app_state, "SERVER_SLOT_ACTIONS", sa_sel, 4, _sa_dir)
                        if sa_sel != app_state["menu_selection_index"]:
                            app_state["server_slot_pending_delete"] = False
                        continue

                    if menu_nav.is_accept(event.key):
                        if sa_sel == 0:
                            if target_slot_id is not None:
                                if db.config.get("active_server_slot") == target_slot_id:
                                    db.leave_server_slot()
                                    print(f"[SERVER SLOTS] Deactivated {target_slot_id} ('{target_name}') — channels back to main project")
                                else:
                                    if db.make_server_slot_active(target_slot_id):
                                        print(f"[SERVER SLOTS] Made {target_slot_id} ('{target_name}') active for edit")
                            app_state["menu_layer"] = "SERVER_SLOTS_MENU"
                            app_state["menu_selection_index"] = target_row
                        elif sa_sel == 1:
                            app_state["menu_layer"] = "SERVER_SLOTS_MENU"
                            app_state["editing_server_slot_name"] = True
                            app_state["server_slot_name_mode"] = "rename"
                            app_state["server_slot_name_buffer"] = target_name
                            app_state["server_slot_name_all_selected"] = True
                            app_state["server_slot_name_target_slot_id"] = target_slot_id
                            app_state["menu_selection_index"] = target_row
                        elif sa_sel == 2:
                            if app_state.get("server_slot_pending_delete", False):
                                if target_slot_id is not None:
                                    db.delete_server_slot(target_slot_id)
                                    print(f"[SERVER SLOTS] Deleted {target_slot_id} ('{target_name}')")
                                app_state["server_slot_pending_delete"] = False
                                app_state["menu_layer"] = "SERVER_SLOTS_MENU"
                                app_state["menu_selection_index"] = 0
                            else:
                                app_state["server_slot_pending_delete"] = True
                        else:
                            app_state["server_slot_pending_delete"] = False
                            app_state["menu_layer"] = "SERVER_SLOTS_MENU"
                            app_state["menu_selection_index"] = target_row
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "REMOTE_REMAP_LIST":
                    rr_sel = app_state.get("menu_selection_index", 0)

                    _rr_dir = menu_nav.key_to_direction(event.key)
                    if _rr_dir is not None:
                        app_state["menu_selection_index"] = menu_nav.ring_move(app_state, "REMOTE_REMAP_LIST", rr_sel, 3, _rr_dir)
                        continue

                    if menu_nav.is_accept(event.key):
                        if rr_sel == 0:
                            app_state["menu_layer"] = "REMOTE_REMAP_CAPTURE"
                            _hook_reinstall_fn = globals().get("_kbd_hook_request_reinstall")
                            if _hook_reinstall_fn is not None:
                                _hook_reinstall_fn()
                            app_state["remote_remap_index"] = 0
                            app_state["_remap_used_keys"]   = []
                            app_state["_remap_reject_flash"] = None
                            app_state["_remap_last_accept"]  = None
                            print("[REMOTE REMAP] Sequence started.")
                        elif rr_sel == 1:
                            app_state["menu_layer"] = "NUMBER_REMAP_CAPTURE"
                            _hook_reinstall_fn = globals().get("_kbd_hook_request_reinstall")
                            if _hook_reinstall_fn is not None:
                                _hook_reinstall_fn()
                            app_state["remote_remap_index"] = 0
                            app_state["_remap_used_keys"]   = []
                            app_state["_remap_reject_flash"] = None
                            app_state["_remap_last_accept"]  = None
                            print("[NUMBER REMAP] Sequence started.")
                        else:
                            app_state["menu_layer"] = "SYSTEM_ADVANCED_SUB_MENU"
                            _as_rows_now = get_advanced_settings_menu_rows(db, app_state)
                            app_state["menu_selection_index"] = (
                                _as_rows_now.index("remote_remap") if "remote_remap" in _as_rows_now else 0
                            )
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "CHANNEL_SUB_MENU":
                    sub_row = app_state.get("sub_menu_row_index", 0) 
                    sub_col = app_state.get("sub_menu_col_index", 0) 
                    target_ch_str = str(app_state["selected_channel_row"]).zfill(2)
                    ch_info = db.channels_db.get(target_ch_str, {"active": True, "is_visualizer": False, "name": f"STATION {target_ch_str}"})

                    is_music_mode = ch_info.get("is_visualizer", False)
                    _sched_is_marathon = (not is_music_mode) and (menu_nav.shown_scheduling_mode(ch_info) == "marathon")
                    _is_full_day = (not _sched_is_marathon) and (ch_info.get("block_mode", "full_day") == "full_day")
                    _is_six_block = (not _sched_is_marathon) and (ch_info.get("block_mode", "full_day") == "six_block")
                    if not ch_info.get("active", True):
                        max_close_row = 1
                    elif is_music_mode:
                        max_close_row = 7
                    else:
                        max_close_row = 6 if _sched_is_marathon else 7
                    _block_len_row = None if _sched_is_marathon else 4
                    _folder_row    = 4 if _sched_is_marathon else 5
                    _holiday_row   = 5 if _sched_is_marathon else 6
                    _audio_track_row = None if (not ch_info.get("active", True) or is_music_mode) else _holiday_row
                    is_server_locked = bool(ch_info.get("server_locked", False))

                    _active_count_r0h = sum(
                        1 for _n in range(5, 45)
                        if db.channels_db.get(str(_n).zfill(2), {}).get("active", str(_n).zfill(2) == "05")
                    )

                    if is_server_locked and menu_nav.is_accept(event.key):
                        if sub_row == max_close_row:
                            print(f"[SERVER SYNC] Closing locked channel {target_ch_str} editor.")
                            app_state["menu_layer"] = "CHANNEL_LIST"
                            app_state["menu_selection_index"] = max(
                                0, min(39, app_state.get("selected_channel_row", 5) - 5)
                            )
                        else:
                            print(f"[SERVER SYNC] Channel {target_ch_str} is server-controlled; edit ignored.")
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                    _reactive_mode_available = (performance_governor.get_mode() if performance_governor is not None else "lite") in ("standard", "performance")
                    if is_music_mode and sub_row == 5 and not _reactive_mode_available and event.key in (pygame.K_a, pygame.K_d):
                        continue

                    if is_music_mode and sub_row == 5 and ch_info.get("reactive_visualizer_enabled", True) and event.key in (pygame.K_a, pygame.K_d):
                        # WARNING: this slider must move exactly like the Video and Theme sliders: the same SLIDER_STEP and rule (menu_nav.reactive_strength_adjust), the same step gate, and the same deferred save; the menu picture redraws at once because _channel_menu_fingerprint in ui.py includes this value.
                        if not menu_nav.step_ready(app_state.setdefault("_step_gate", {}), "reactive_strength", now_ticks):
                            continue
                        _rs_dir = menu_nav.key_to_direction(event.key)
                        if menu_nav.reactive_strength_adjust(ch_info, _rs_dir):
                            _mark_settings_dirty()
                        continue

                    if is_music_mode and sub_row == 3 and event.key in (pygame.K_a, pygame.K_d):
                        # WARNING: with Loudness Scan off no gain is played, so the gain row is greyed and cannot be changed; the owner could not hear what a change does.
                        if not db.config.get("loudness_scan_enabled", True):
                            continue
                        # WARNING: the gain belongs to the song playing on this channel; with another channel on screen or no song playing the row is greyed and a change would only move the number.
                        _vis_file = ui.visualizer_gain_file(app_state, target_ch_str)
                        if not _vis_file:
                            continue
                        _vis_step = -1 if event.key == pygame.K_a else 1
                        _vis_gain = max(-12, min(12, _get_audio_gain_db(_vis_file, target_ch_str) + _vis_step))
                        app_state["visualizer_gain_db"] = _vis_gain
                        _save_audio_gain_db(_vis_file, _vis_gain)
                        if _vis_file:
                            app_state["active_music_gain"] = _lookup_file_gain(target_ch_str, _vis_file)
                        else:
                            app_state["active_music_gain"] = 10 ** (_vis_gain / 20.0)
                        if pygame.mixer.music.get_busy():
                            _vis_live_volume = max(0.0, min(1.0,
                                _effective_audio_gain(min_db=STACKED_GAIN_MIN_DB)
                                * MUSIC_GAIN
                                * _effective_loudness_gain(app_state.get("active_music_gain", 1.0))))
                            pygame.mixer.music.set_volume(_vis_live_volume)
                            pygame.mixer.Channel(1).set_volume(_vis_live_volume)
                        db.save_settings()
                        continue

                    _cm_dir = menu_nav.key_to_direction(event.key)
                    if _cm_dir is not None:
                        _cm_layout = menu_nav.channel_sub_layout(ch_info, _active_count_r0h)
                        _cm_to = menu_nav.navigate(app_state, "CHANNEL_SUB_MENU", menu_nav.channel_sub_table(_cm_layout), menu_nav.channel_sub_cell(sub_row, sub_col), _cm_dir)
                        if _cm_to is not None:
                            app_state["sub_menu_row_index"], app_state["sub_menu_col_index"] = menu_nav.channel_sub_index(_cm_to)
                        continue

                    if menu_nav.is_accept(event.key):
                        if sub_row == 4 and sub_col == 1 and not is_music_mode and ch_info.get("active", True):
                            ch_info["watermark_enabled"] = not ch_info.get("watermark_enabled", False)
                            db.save_settings()
                            print(f"[WATERMARK] Channel {target_ch_str} = {ch_info['watermark_enabled']}")
                            continue
                        if sub_row == 4 and sub_col == 2 and not is_music_mode and ch_info.get("active", True):
                            from game_deck import DVD_SPLASH_IMAGE_EXTS
                            os.makedirs(WATERMARK_BASE_DIR, exist_ok=True)
                            _wm_now = _channel_watermark_path(target_ch_str)
                            _fe_open(
                                f"Select Channel {target_ch_str} Watermark",
                                DVD_SPLASH_IMAGE_EXTS,
                                {"mode": "watermark_select", "channel": target_ch_str}
                            )
                            _fe_navigate(os.path.dirname(_wm_now) if _wm_now else os.path.join(WATERMARK_BASE_DIR, f"Channel {target_ch_str}"))
                            continue
                        # WARNING: on a TV channel that is on, the bottom row holds two buttons: column 0 is Clear All Scheduled Media (handled further down) and column 3 is Close; a music or off channel has only Close there.
                        if sub_row == max_close_row and not ((not is_music_mode) and ch_info.get("active", True) and sub_col == 0):
                            print("[SUB-MENU CONTROLLER] Close button triggered. Returning to main Channels tab layout.")
                            app_state["menu_layer"] = "CHANNEL_LIST"
                            app_state["menu_selection_index"] = max(0, min(39, app_state.get("selected_channel_row", 5) - 5))
                        elif sub_row == 0:
                            if sub_col == 0:
                                currently_active = ch_info.get("active", True)
                                if currently_active:
                                    if _count_active_content_channels(db) > 1:
                                        ch_info["active"] = False
                                        print(f"[CHANNEL] {target_ch_str} turned OFF.")
                                        app_state["guide_refresh_token"] = app_state.get("guide_refresh_token", 0) + 1
                                        _surf_up_from_disabled(target_ch_str)
                                    else:
                                        print(f"[CHANNEL] {target_ch_str} is the last active channel - blocked.")
                                else:
                                    ch_info["active"] = True
                                    print(f"[CHANNEL] {target_ch_str} turned ON.")
                                    app_state["guide_refresh_token"] = app_state.get("guide_refresh_token", 0) + 1
                            elif sub_col == 1:
                                ch_info["is_visualizer"] = not ch_info.get("is_visualizer", False)
                                print(f"[MODE ENGINE] Toggled channel mode. is_visualizer={ch_info['is_visualizer']}")
                            elif sub_col == 2: 
                                app_state["editing_channel_name"] = True
                                app_state["channel_name_all_selected"] = True
                                try:
                                    app_state["channel_name_max_len"] = ui.compute_channel_name_char_limit(WINDOW_HEIGHT)
                                except Exception as _name_len_err:
                                    log.warning(f"[NAME ENGINE] Could not compute guide-cell name limit, falling back to 18: {_name_len_err}")
                                    app_state["channel_name_max_len"] = 18
                                print(f"[NAME ENGINE] Editing channel {target_ch_str} text identification label string (max {app_state['channel_name_max_len']} chars).")
                        else:
                            active_block = "Morning"
                            
                            if is_music_mode:
                                if sub_row == 4:
                                    if (performance_governor.get_mode() if performance_governor is not None else "lite") not in ("standard", "performance"):
                                        continue
                                    ch_info["reactive_visualizer_enabled"] = not ch_info.get("reactive_visualizer_enabled", True)
                                    db.save_settings()
                                    continue
                                elif sub_row == 1:
                                    styles = ["Random"] + list(visualizer_deck.render_styles)
                                    _cur_style = ch_info.get("visualizer_style", "Random")
                                    try: curr_idx = styles.index(_cur_style)
                                    except ValueError as _swallowed_error:
                                        _log_swallowed("module: curr_idx = styles.index(_cur_style)", _swallowed_error)
                                        curr_idx = 0
                                    _next_style = styles[(curr_idx + 1) % len(styles)]
                                    _leaving_random = (_cur_style == "Random" and _next_style != "Random")
                                    if _leaving_random and not db.config.get("burn_in_protection_skip_confirm", False):
                                        app_state["show_clear_confirm"]    = True
                                        app_state["clear_confirm_selection"] = "No"
                                        app_state["clear_confirm_target"]  = "visualizer_style_change"
                                        app_state["clear_confirm_channel"] = target_ch_str
                                        app_state["clear_confirm_shown_at"] = now_ticks
                                        app_state["clear_confirm_burnin_new_value"] = _next_style
                                        app_state["clear_confirm_dont_show_again"] = False
                                        print(f"[VISUALIZER STYLE] Leaving Random for {_next_style} -- confirming burn-in warning first.")
                                    else:
                                        ch_info["visualizer_style"] = _next_style
                                        print(f"[VISUALIZER STYLE] Cycled forward to style: {ch_info['visualizer_style']}")
                                        db.save_settings()
                                    continue
                                elif sub_row in (3, 5):
                                    continue
                                elif sub_row == 2:
                                    active_block = "Music Tracks"
                                elif sub_row == 6:
                                    _has_music_content = len(ch_info.get("schedules", {}).get("Music Tracks", [])) > 0
                                    if _has_music_content:
                                        app_state["show_clear_confirm"]    = True
                                        app_state["clear_confirm_selection"] = "No"
                                        app_state["clear_confirm_target"]  = "channel_music"
                                        app_state["clear_confirm_channel"] = target_ch_str
                                        app_state["clear_confirm_shown_at"] = now_ticks
                                    continue
                            else:
                                if _is_six_block:
                                    folder_map = {
                                        (_folder_row, _ci): _bn
                                        for _ci, _bn in enumerate(SIX_HOUR_BLOCK_NAMES)
                                    }
                                else:
                                    folder_map = {
                                        (_folder_row, 0): "Morning",
                                        (_folder_row, 1): "Evening",
                                        (_folder_row, 2): "Night",
                                    }
                                if sub_row == 1:
                                    if sub_col == 1 and not _sched_is_marathon:
                                        _cur_order = ch_info.get("episode_order_mode", "sequential")
                                        ch_info["episode_order_mode"] = "random" if _cur_order == "sequential" else "sequential"
                                        print(f"[EPISODE ORDER] ch{target_ch_str} -> {ch_info['episode_order_mode']}")
                                        db.save_settings()
                                    else:
                                        _SM = ["random_slots", "one_slot", "two_slots", "marathon"]
                                        _sc = menu_nav.shown_scheduling_mode(ch_info)
                                        try: _si = _SM.index(_sc)
                                        except ValueError as _swallowed_error:
                                            _log_swallowed("module: _si = _SM.index(_sc)", _swallowed_error)
                                            _si = 0
                                        _request_scheduling_mode(ch_info, _SM[(_si + 1) % len(_SM)], target_ch_str)
                                    continue
                                elif sub_row == 2:
                                    _pt = ch_info.get("pair_threshold_minutes", 15)
                                    ch_info["pair_threshold_minutes"] = _pt + 1 if _pt < 30 else 0
                                    db.save_settings()
                                    _replan_hub_future_soon(target_ch_str)
                                    continue
                                elif sub_row == 3:
                                    if sub_col == 0:
                                        _new_val = not ch_info.get("commercials_enabled", False)
                                        ch_info["commercials_enabled"] = _new_val
                                        _plog = ch_info.setdefault("playback_log", {})
                                        _plog["sched_block_key"] = ""
                                        _plog["sched_cached_tracks"] = []
                                        _plog["sched_cached_durations"] = {}
                                        db.save_settings()
                                        _replan_hub_future_soon(target_ch_str)
                                    elif sub_col == 1:
                                        _com_on = db.channels_db.get(target_ch_str, {}).get("commercials_enabled", False)
                                        if _com_on:
                                            app_state["menu_layer"] = "COMMERCIALS_SUB_MENU"
                                            app_state["sub_menu_row_index"] = 0
                                    elif sub_col == 2:
                                        _com_on = db.channels_db.get(target_ch_str, {}).get("commercials_enabled", False)
                                        if _com_on:
                                            _cur_place = ch_info.get("commercial_placement", "interrupt_half_hour")
                                            ch_info["commercial_placement"] = (
                                                "end_of_show" if _cur_place == "interrupt_half_hour"
                                                else "interrupt_half_hour")
                                            print(f"[COMMERCIALS] Placement -> {ch_info['commercial_placement']} for ch {target_ch_str}")
                                            db.save_settings()
                                            _replan_hub_future_soon(target_ch_str)
                                    continue
                                elif _block_len_row is not None and sub_row == _block_len_row and sub_col == 0:
                                    _BL_CYCLE = ["full_day", "segmented", "six_block"]
                                    _cur_bl = ch_info.get("block_mode", "full_day")
                                    try:
                                        _bli = _BL_CYCLE.index(_cur_bl)
                                    except ValueError as _swallowed_error:
                                        _log_swallowed("module: _bli = _BL_CYCLE.index(_cur_bl)", _swallowed_error)
                                        _bli = 0
                                    ch_info["block_mode"] = _BL_CYCLE[(_bli + 1) % len(_BL_CYCLE)]
                                    app_state["sub_menu_col_index"] = 0
                                    _plog = ch_info.setdefault("playback_log", {})
                                    _plog["sched_block_key"] = ""
                                    _plog["sched_cached_tracks"] = []
                                    _plog["sched_cached_durations"] = {}
                                    print(f"[BLOCK LENGTH] ch{target_ch_str} -> {ch_info['block_mode']}")
                                    db.save_settings()
                                    _replan_hub_future_soon(target_ch_str)
                                    continue
                                elif (not _sched_is_marathon) and sub_row == _holiday_row and (_audio_track_row is None or sub_col == 0):
                                    app_state["menu_layer"] = "HOLIDAY_SUB_MENU"
                                    app_state["sub_menu_row_index"] = 0
                                    app_state["sub_menu_col_index"] = 0
                                    continue
                                elif _audio_track_row is not None and sub_row == _audio_track_row and (_sched_is_marathon or sub_col == 1):
                                    if _sched_is_marathon:
                                        _atr_has_media = len(ch_info.get("schedules", {}).get("Marathon", [])) > 0
                                    elif _is_full_day:
                                        _atr_has_media = len(ch_info.get("schedules", {}).get("Full Day", [])) > 0
                                    else:
                                        _atr_slot_names = SIX_HOUR_BLOCK_NAMES if _is_six_block else ["Morning", "Evening", "Night"]
                                        _atr_has_media = any(len(ch_info.get("schedules", {}).get(n, [])) > 0 for n in _atr_slot_names)
                                    if _atr_has_media:
                                        _open_audio_track_picker(target_ch_str)
                                    continue
                                elif sub_row == max_close_row:
                                    if media.channel_has_clearable_media(ch_info):
                                        app_state["show_clear_confirm"]    = True
                                        app_state["clear_confirm_selection"] = "No"
                                        app_state["clear_confirm_target"]  = "channel_schedule"
                                        app_state["clear_confirm_channel"] = target_ch_str
                                        app_state["clear_confirm_shown_at"] = now_ticks
                                    continue
                                elif _sched_is_marathon and sub_row == _folder_row:
                                    active_block = "Marathon"
                                elif _is_full_day and sub_row == _folder_row:
                                    active_block = "Full Day"
                                else:
                                    active_block = folder_map.get((sub_row, sub_col), "Morning")
                            
                            pygame.mixer.Channel(1).stop()

                            app_state["sub_menu_row_index"] = sub_row
                            is_vis_channel = ch_info.get("is_visualizer", False)

                            if is_vis_channel:
                                _pick_title = f"Add Audio — {active_block}"
                                _pick_exts  = {".mp3", ".wav", ".ogg", ".flac", ".m4a", ".aac", ".wma"}
                            else:
                                _pick_title = f"Add Video — {active_block} Schedule"
                                _pick_exts  = {".mp4", ".mkv", ".avi", ".mov", ".wmv", ".webm", ".m4v", ".flv"}
                            _fe_open(_pick_title, _pick_exts, {
                                "mode": "schedule", "ch": target_ch_str, "block": active_block
                            })

                        db.save_settings()
                        continue

                elif app_state["menu_layer"] == "AUDIO_TRACK_PICKER":
                    sub_row  = app_state.get("sub_menu_row_index", 0)
                    tracks   = app_state.get("audio_track_list", [])
                    gain_row = len(tracks)
                    close_row = gain_row + 1
                    _audio_ctx = app_state.get("audio_track_context", "channel")
                    _target_engine = dvd_engine if _audio_ctx == "dvd" else vlc_engine

                    _at_dir = menu_nav.key_to_direction(event.key)
                    if _at_dir is not None:
                        if sub_row == gain_row and _at_dir in (menu_nav.LEFT, menu_nav.RIGHT) and _audio_ctx == "channel":
                            # WARNING: with Loudness Scan off no gain is played, so the gain row is greyed and cannot be changed.
                            if not db.config.get("loudness_scan_enabled", True):
                                continue
                            _step = -1 if _at_dir == menu_nav.LEFT else 1
                            _cur_file = getattr(_target_engine, "current_filepath", None)
                            _new_gain = max(-12, min(12, int(app_state.get("audio_track_gain_db", 0)) + _step))
                            app_state["audio_track_gain_db"] = _new_gain
                            _save_audio_gain_db(_cur_file, _new_gain)
                            if _cur_file:
                                _ch = str(app_state.get("audio_track_source_channel", "")).zfill(2)
                                _target_engine.file_gain = _lookup_file_gain(_ch, _cur_file)
                                _target_engine.set_volume(db.config.get("global_volume", 70), db.config.get("is_muted", False))
                                _active_music_file = app_state.get("active_music_track_file", "") or ""
                                if (os.path.normpath(_active_music_file) == os.path.normpath(_cur_file)
                                        and pygame.mixer.music.get_busy()):
                                    app_state["active_music_gain"] = _target_engine.file_gain
                                    _visualizer_volume = (
                                        _effective_audio_gain(min_db=STACKED_GAIN_MIN_DB)
                                        * MUSIC_GAIN
                                        * _effective_loudness_gain(app_state["active_music_gain"])
                                    )
                                    pygame.mixer.music.set_volume(_visualizer_volume)
                                    pygame.mixer.Channel(1).set_volume(_visualizer_volume)
                                    log.info("[AUDIO GAIN] Applied visualizer gain x%.3f live for %s",
                                             app_state["active_music_gain"], os.path.basename(_cur_file))
                        else:
                            app_state["sub_menu_row_index"] = menu_nav.column_move(app_state, "AUDIO_TRACK_PICKER", sub_row, close_row + 1, _at_dir)
                        continue

                    if menu_nav.is_accept(event.key):
                        if sub_row == close_row:
                            pass
                        elif 0 <= sub_row < len(tracks) and _target_engine is not None:
                            track_id, track_name = tracks[sub_row]
                            _target_engine.set_audio_track(track_id)
                            if _audio_ctx == "dvd":
                                app_state["audio_track_active_id"] = track_id
                                print(f"[AUDIO TRACK] DVD: switched to '{track_name}'.")
                            else:
                                _src_ch = app_state.get("audio_track_source_channel")
                                _cur_file = getattr(_target_engine, "current_filepath", None)
                                if _cur_file:
                                    # WARNING: save VLC's own label, not the menu label with the added language, or restoring by name never matches.
                                    _vlc_tracks = _target_engine.get_audio_tracks()
                                    _vlc_label = dict(_vlc_tracks).get(track_id, track_name)
                                    _vlc_index = next((i for i, (tid, _l) in enumerate(_vlc_tracks) if tid == track_id), None)
                                    _save_audio_track_pref(_cur_file, track_id, _vlc_label, _vlc_index)
                                    _target_engine._audio_index = _vlc_index
                                    _target_engine.file_gain = _lookup_file_gain(_src_ch, _cur_file)
                                    _target_engine.set_volume(db.config.get("global_volume", 70), db.config.get("is_muted", False))
                                    app_state["audio_track_gain_db"] = _get_audio_gain_db(_cur_file, _src_ch)
                                    log.info("[AUDIO TRACK] %s: track %s chosen, playing at gain x%.3f",
                                             os.path.basename(_cur_file), (_vlc_index or 0) + 1, _target_engine.file_gain)
                                app_state["audio_track_active_id"] = track_id
                                print(f"[AUDIO TRACK] Channel {_src_ch}: switched to '{track_name}' and remembered for this file.")
                        if _audio_ctx == "dvd":
                            _dvd_rows_now = ["status"] + get_games_sub_menu_rows(db, app_state, "DVD", True) + ["close"]
                            app_state["menu_layer"] = "GAMES_SUB_MENU"
                            app_state["games_sub_row"] = (
                                _dvd_rows_now.index("dvd_audio_track") if "dvd_audio_track" in _dvd_rows_now else 0
                            )
                        else:
                            _atp_ch = db.channels_db.get(str(app_state.get("selected_channel_row", "")).zfill(2), {})
                            _atp_marathon = menu_nav.shown_scheduling_mode(_atp_ch) == "marathon"
                            app_state["menu_layer"] = "CHANNEL_SUB_MENU"
                            app_state["sub_menu_row_index"] = 5 if _atp_marathon else 6
                            app_state["sub_menu_col_index"] = 0 if _atp_marathon else 1
                        continue

                elif app_state["menu_layer"] == "HOLIDAY_SUB_MENU":
                    sub_row = app_state.get("sub_menu_row_index", 0)
                    sub_col = app_state.get("sub_menu_col_index", 0)
                    target_ch_str = str(app_state.get("selected_channel_row", 5)).zfill(2)
                    _holiday_dir = menu_nav.key_to_direction(event.key)
                    if _holiday_dir is not None:
                        _holiday_to = menu_nav.holiday_move(app_state, sub_row, sub_col, _holiday_dir)
                        app_state["sub_menu_row_index"], app_state["sub_menu_col_index"] = _holiday_to
                        continue
                    if menu_nav.is_accept(event.key):
                        if sub_row == menu_nav.HOLIDAY_CLEAR_ROW:
                            # WARNING: every Clear Media button works the same way: greyed and doing nothing when there is nothing to clear, else the Yes/No popup (owner 2026-11-03).
                            if not any(len(v or []) > 0 for v in (db.channels_db.get(target_ch_str, {}).get("holiday_schedules") or {}).values()):
                                continue
                            app_state["show_clear_confirm"] = True
                            app_state["clear_confirm_selection"] = "No"
                            app_state["clear_confirm_target"] = "holiday_media"
                            app_state["clear_confirm_channel"] = target_ch_str
                            app_state["clear_confirm_shown_at"] = now_ticks
                        elif sub_row == menu_nav.HOLIDAY_CLOSE_ROW:
                            _holiday_ch = db.channels_db.get(target_ch_str, {})
                            app_state["menu_layer"] = "CHANNEL_SUB_MENU"
                            app_state["sub_menu_row_index"] = 5 if menu_nav.shown_scheduling_mode(_holiday_ch) == "marathon" else 6
                            app_state["sub_menu_col_index"] = 0
                        elif 0 <= sub_row < len(media.HOLIDAY_KEYS) and sub_col == menu_nav.HOLIDAY_FORCE_COLUMN:
                            _toggle_holiday_force(media.HOLIDAY_KEYS[sub_row], target_ch_str)
                        elif 0 <= sub_row < len(media.HOLIDAY_KEYS):
                            pygame.mixer.Channel(1).stop()
                            _fe_open(
                                f"Holiday Override — {media.HOLIDAY_KEYS[sub_row].replace('_', ' ').title()} Videos",
                                {".mp4", ".mkv", ".avi", ".mov", ".wmv", ".webm", ".m4v", ".flv"},
                                {"mode": "holiday", "ch": target_ch_str, "hkey": media.HOLIDAY_KEYS[sub_row]}
                            )
                        continue

                elif app_state["menu_layer"] == "COMMERCIALS_SUB_MENU":
                    sub_row = app_state.get("sub_menu_row_index", 0)
                    target_ch_str = str(app_state.get("selected_channel_row", 5)).zfill(2)
                    ch_info = db.channels_db.get(target_ch_str, {})
                    _com_dir = menu_nav.key_to_direction(event.key)
                    if _com_dir is not None:
                        app_state["sub_menu_row_index"] = menu_nav.commercials_move(app_state, sub_row, _com_dir)
                        continue
                    if menu_nav.is_accept(event.key):
                        if sub_row == menu_nav.COMMERCIALS_CLEAR_ROW:
                            if not any(len(ch_info.get("schedules", {}).get(k, [])) > 0 for k in COMMERCIAL_SUB_MENU_KEYS):
                                continue
                            app_state["show_clear_confirm"] = True
                            app_state["clear_confirm_selection"] = "No"
                            app_state["clear_confirm_target"] = "commercial_media"
                            app_state["clear_confirm_channel"] = target_ch_str
                            app_state["clear_confirm_shown_at"] = now_ticks
                        elif sub_row == menu_nav.COMMERCIALS_CLOSE_ROW:
                            app_state["menu_layer"] = "CHANNEL_SUB_MENU"
                            app_state["sub_menu_row_index"] = 3
                            app_state["sub_menu_col_index"] = 1
                        else:
                            _bumper_keys = ("Commercials", "Fade-in", "Fade-out")
                            pygame.mixer.Channel(1).stop()
                            _fe_open(
                                f"Add {_bumper_keys[sub_row]}",
                                {".mp4", ".mkv", ".avi", ".mov", ".wmv", ".webm", ".m4v", ".flv"},
                                {"mode": "commercial", "ch": target_ch_str, "block": _bumper_keys[sub_row]}
                            )
                        continue

                elif app_state["menu_layer"] == "GAMES_LIST":
                    from game_deck import CONSOLE_ORDER
                    console_list = [c for c in CONSOLE_ORDER]
                    cols = 4
                    total = len(console_list)
                    cur_sel = app_state.get("menu_selection_index", 0)

                    _mm_on = db.config.get("ch03_menu_music_enabled", True) if db else True
                    _ss_on = db.config.get("ch03_screensaver_enabled", True) if db else True
                    _kiosk_on_gl = db.config.get("kiosk_mode_enabled", False) if db else False
                    _set_music_actionable  = _mm_on and not _kiosk_on_gl
                    _all_sync_on = db.config.get("all_profiles_sync", False) if db else False

                    _gl_dir = menu_nav.key_to_direction(event.key)
                    if _gl_dir is not None:
                        _gl_from = menu_nav.games_cell(cur_sel, total)
                        if _gl_from is not None:
                            _gl_table = menu_nav.games_table(menu_nav.games_page_of(cur_sel, total, app_state.get("games_tab_page", 0)), total, _kiosk_on_gl)
                            _gl_to = menu_nav.navigate(app_state, "GAMES_LIST", _gl_table, _gl_from, _gl_dir)
                            if _gl_to == menu_nav.TAB_BAR:
                                app_state["menu_layer"] = "TAB_SELECTION"
                            elif _gl_to is not None:
                                app_state["menu_selection_index"] = menu_nav.games_index(_gl_to)
                        continue

                    if menu_nav.is_accept(event.key):
                        if cur_sel == 99:
                            app_state["show_menu"] = False
                            app_state["games_tab_page"] = 0
                            app_state["menu_shown_at"] = 0
                        elif cur_sel == 95:
                            _toggle_all_consoles()
                        elif cur_sel == 101:
                            _toggle_all_profiles()
                        elif cur_sel == 103:
                            if _all_sync_on:
                                _adjust_all_settings_sync_profile(1, wrap=True)
                        elif cur_sel == 102:
                            from game_deck import CONSOLE_ORDER as _CON_ORDER_PAGES
                            _num_pages = max(1, (len(_CON_ORDER_PAGES) + (cols * 3) - 1) // (cols * 3))
                            app_state["games_tab_page"] = (app_state.get("games_tab_page", 0) + 1) % _num_pages
                        elif cur_sel == 100:
                            if _ss_on:
                                _adjust_ss_timer(5, wrap=True)
                        elif cur_sel == 98:
                            _ss_turning_off = db.config.get("ch03_screensaver_enabled", True)
                            if _ss_turning_off:
                                if db.config.get("ch03_screensaver_skip_confirm", False):
                                    _toggle_ss()
                                else:
                                    app_state["show_clear_confirm"]      = True
                                    app_state["clear_confirm_selection"]  = "No"
                                    app_state["clear_confirm_target"]     = "ch03_screensaver_toggle"
                                    app_state["clear_confirm_shown_at"]   = now_ticks
                                    app_state["clear_confirm_burnin_new_value"] = False
                                    app_state["clear_confirm_dont_show_again"]  = False
                            else:
                                _toggle_ss()
                        elif cur_sel == 97:
                            _toggle_menu_music()
                        elif cur_sel == 96 and _set_music_actionable:
                            pygame.mixer.Channel(1).stop()
                            _fe_open(
                                "Game Music — Set Tracks",
                                {".mp3", ".wav", ".ogg", ".flac", ".m4a", ".aac", ".wma"},
                                {"mode": "ch03_menu_music"}
                            )
                        elif 0 <= cur_sel < total:
                            app_state["games_selected_console"] = console_list[cur_sel]

                            _con_key_entry = console_list[cur_sel]
                            if _con_key_entry == "MENU":
                                app_state["games_sub_row"] = 0
                            else:
                                _con_enabled_map_entry = db.config.get("consoles_enabled", {})
                                _con_default_on_entry = (_con_key_entry == "DVD")
                                _con_is_on_entry = _con_enabled_map_entry.get(_con_key_entry, _con_default_on_entry)
                                _con_is_last_entry = _con_is_on_entry and (_count_active_consoles(db) <= 1)
                                app_state["games_sub_row"] = 1 if _con_is_last_entry else 0

                            app_state["menu_layer"] = "GAMES_SUB_MENU"
                            print(f"[GAMES TAB] Opening sub-menu for: {console_list[cur_sel]}")
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "GAMES_SUB_MENU":
                    console_key = app_state.get("games_selected_console", "DVD")
                    sub_row = app_state.get("games_sub_row", 0)
                    _g_enabled_map = db.config.get("consoles_enabled", {})
                    _g_default_on  = (console_key == "DVD")
                    _g_is_on       = True if console_key == "MENU" else _g_enabled_map.get(console_key, _g_default_on)

                    if console_key == "MENU":
                        games_rows = get_games_sub_menu_rows(db, app_state, console_key, _g_is_on) + ["close"]
                    else:
                        games_rows = ["status"] + get_games_sub_menu_rows(db, app_state, console_key, _g_is_on) + ["close"]
                    row_id = games_rows[sub_row] if sub_row < len(games_rows) else "close"

                    _g_is_last_console = _g_is_on and (_count_active_consoles(db) <= 1)

                    def _advance_psx_disc_to_next():
                        if game_deck is None or not hasattr(game_deck, "get_psx_disc_info"):
                            return
                        discs, cur_idx = game_deck.get_psx_disc_info()
                        if not discs:
                            return
                        if cur_idx < 0:
                            game_deck.change_psx_disc(0)
                            return
                        next_idx = cur_idx + 1
                        if next_idx >= len(discs):
                            return
                        game_deck.change_psx_disc(next_idx)

                    _gs_dir = menu_nav.key_to_direction(event.key)
                    if _gs_dir is not None:
                        _gs_to = menu_nav.navigate(app_state, "GAMES_SUB_MENU:" + str(console_key), menu_nav.games_sub_table(games_rows, _g_is_last_console), menu_nav.games_sub_cell(games_rows, sub_row), _gs_dir)
                        if _gs_to is not None:
                            app_state["games_sub_row"] = menu_nav.games_sub_index(games_rows, _gs_to)
                        continue

                    if menu_nav.is_accept(event.key):
                        if row_id == "status":
                            if _g_is_last_console:
                                print(f"[GAMES] {console_key} is the last active console - blocked.")
                            else:
                                enabled_map = db.config.setdefault("consoles_enabled", {})
                                default_on = (console_key == "DVD")
                                enabled_map[console_key] = not enabled_map.get(console_key, default_on)
                                db.save_settings()
                                if game_deck is not None: game_deck.refresh_from_config(db.config)
                                if not enabled_map[console_key]:
                                    app_state["games_sub_row"] = 0
                                print(f"[GAMES] {console_key} enabled = {enabled_map[console_key]}")
                        elif row_id == "core_select":
                            import os as _os
                            emu_folder = _os.path.join(resolve_main_dir(), "cores", console_key)
                            _os.makedirs(emu_folder, exist_ok=True)
                            _active_core = _fe_active_core_path(console_key)
                            pygame.mixer.Channel(1).stop()
                            _fe_open(
                                f"Select Libretro Core (.dll) — {console_key}",
                                {".dll"},
                                {"mode": "libretro_core", "console_key": console_key}
                            )
                            _fe_navigate(_os.path.dirname(_active_core) if _active_core else emu_folder)
                        elif row_id == "multitap_toggle":
                            from game_deck import MULTITAP_CONSOLES
                            enabled = not db.config.get("multitap_enabled_global", False)
                            db.config["multitap_enabled_global"] = enabled
                            db.save_settings()
                            if (game_deck is not None
                                    and getattr(game_deck, "_libretro_console", None) in MULTITAP_CONSOLES
                                    and hasattr(game_deck, "toggle_multitap_live")):
                                status = game_deck.toggle_multitap_live(enabled)
                                if status == "UNSUPPORTED" and hasattr(game_deck, "_libretro_osd_msg"):
                                    game_deck._libretro_osd_msg   = "MULTITAP NOT SUPPORTED THIS SESSION"
                                    game_deck._libretro_osd_until = pygame.time.get_ticks() + 2500
                            print(f"[GAMES] Multitap (all consoles) = {enabled}")
                        elif row_id == "stick_deadzone":
                            app_state["menu_layer"] = "GAMES_STICK_DZ"
                            app_state["stick_dz_cursor"] = 0
                            app_state["stick_dz_player"] = 1
                            print("[GAMES] Opening stick deadzone screen")
                        elif row_id == "controller_map":
                            app_state["menu_layer"]  = "GAMES_CTRL_MAP"
                            app_state["games_ctrl_console"] = console_key
                            app_state["ctrl_map_cursor"] = 1
                            app_state["ctrl_map_on_pick"] = False
                            if game_deck is not None:
                                game_deck.ctrl_mapping_active_btn = None
                                game_deck._seq_remap_active = False
                                game_deck._ctrl_map_cursor  = 1
                                _remembered_p = game_deck._mapping_player_by_console.get(console_key, 1)
                                app_state["ctrl_map_player_sel"] = _remembered_p
                            print(f"[GAMES] Opening controller mapping UI for {console_key}")
                        elif row_id in ("profile1", "profile2", "profile3"):
                            profile_num = int(row_id[-1])
                            app_state["games_profile_num"]  = profile_num
                            app_state["games_profile_row"]  = 0
                            app_state["menu_layer"] = "GAMES_SAVE_PROFILE"
                            print(f"[GAMES] Opening profile {profile_num} for {console_key}")
                        elif row_id == "disc":
                            _advance_psx_disc_to_next()
                        elif row_id == "dvd_captions_toggle" and _feature_locked("dvd_captions_enabled"):
                            # WARNING: Enter is a no-op while the mode locks this row; the stored setting must not flip.
                            pygame.event.clear(pygame.KEYDOWN)
                        elif row_id == "dvd_captions_toggle":
                            enabled = not db.config.get("dvd_captions_enabled", False)
                            db.config["dvd_captions_enabled"] = enabled
                            db.save_settings()
                            if game_deck is not None:
                                game_deck.refresh_from_config(db.config)
                                if getattr(game_deck, "dvd_playback_active", False):
                                    _dvd_live_vlc = getattr(game_deck, "vlc_engine", None) or globals().get("dvd_engine")
                                    if enabled:
                                        game_deck._dvd_captions_auto_pending = True
                                        game_deck._dvd_captions_auto_done = False
                                        game_deck._dvd_captions_auto_deadline = 0
                                        game_deck._dvd_captions_auto_next_try = 0
                                        game_deck._dvd_captions_asr_state = "idle"
                                        game_deck._dvd_captions_asr_srt_path = None
                                    else:
                                        game_deck._apply_dvd_captions_state(False, _dvd_live_vlc, silent=True)
                                        game_deck._dvd_captions_auto_pending = False
                                        game_deck._dvd_captions_auto_done = True
                            print(f"[GAMES] DVD captions enabled = {enabled}")
                        elif row_id == "dvd_resume_toggle":
                            enabled = not db.config.get("dvd_resume_enabled", False)
                            db.config["dvd_resume_enabled"] = enabled
                            if not enabled:
                                db.config["dvd_resume_positions"] = {}
                            db.save_settings()
                            if game_deck is not None: game_deck.refresh_from_config(db.config)
                            print(f"[GAMES] DVD resume-from-last-played enabled = {enabled}")
                        elif row_id == "splash_toggle":
                            if console_key == "DVD":
                                enabled = not db.config.get("dvd_splash_enabled", False)
                            else:
                                enabled = not db.config.get("console_splash_enabled", {}).get(console_key, False)
                            _set_splash_enabled(console_key, enabled)
                            if game_deck is not None: game_deck.refresh_from_config(db.config)
                        elif row_id == "splash_select_image":
                            _splash_is_on = (db.config.get("dvd_splash_enabled", False) if console_key == "DVD"
                                              else db.config.get("console_splash_enabled", {}).get(console_key, False))
                            if _splash_is_on:
                                import os as _os
                                from game_deck import DVD_SPLASH_IMAGE_EXTS
                                splash_folder = _os.path.join(SPLASH_IMAGES_BASE_DIR, console_key)
                                _os.makedirs(splash_folder, exist_ok=True)
                                pygame.mixer.Channel(1).stop()
                                _fe_open(
                                    f"Select Splash Image — {console_key}",
                                    DVD_SPLASH_IMAGE_EXTS,
                                    {"mode": "console_splash", "console_key": console_key, "splash_folder": splash_folder}
                                )
                                _fe_navigate(splash_folder)
                        elif row_id == "splash_select_video":
                            _splash_is_on = (db.config.get("dvd_splash_enabled", False) if console_key == "DVD"
                                              else db.config.get("console_splash_enabled", {}).get(console_key, False))
                            if _splash_is_on:
                                import os as _os
                                from game_deck import DVD_SPLASH_VIDEO_EXTS
                                splash_folder = _os.path.join(SPLASH_VIDEOS_BASE_DIR, console_key)
                                _os.makedirs(splash_folder, exist_ok=True)
                                pygame.mixer.Channel(1).stop()
                                _fe_open(
                                    f"Select Splash Video — {console_key}",
                                    DVD_SPLASH_VIDEO_EXTS,
                                    {"mode": "console_splash", "console_key": console_key, "splash_folder": splash_folder}
                                )
                                _fe_navigate(splash_folder)
                        elif row_id == "add_bios":
                            from game_deck import get_bios_dir_for_console, ARCHIVE_EXTS
                            bios_dir = get_bios_dir_for_console(base_dir, console_key)
                            if bios_dir:
                                import os as _os
                                _os.makedirs(bios_dir, exist_ok=True)
                                pygame.mixer.Channel(1).stop()
                                _active_bios = _fe_active_bios_path(console_key)
                                _fe_open(
                                    f"Add BIOS — {console_key}",
                                    {".bin"} | set(ARCHIVE_EXTS),
                                    {"mode": "add_bios", "console_key": console_key}
                                )
                                # WARNING: land where the active BIOS sits, else the console's own BIOS folder, never the last-browsed folder.
                                _fe_navigate(_os.path.dirname(_active_bios) if _active_bios else bios_dir)
                        elif row_id == "menu_bg_select_image":
                            import os as _os
                            from game_deck import DVD_SPLASH_IMAGE_EXTS
                            _os.makedirs(MENU_BG_BASE_DIR, exist_ok=True)
                            pygame.mixer.Channel(1).stop()
                            _fe_open(
                                "Select Menu Background Image",
                                DVD_SPLASH_IMAGE_EXTS,
                                {"mode": "menu_bg"}
                            )
                            _fe_navigate(MENU_BG_BASE_DIR)
                        elif row_id == "scroll_style":
                            from game_deck import CONSOLE_SCROLL_STYLES
                            current = db.config.get("console_scroll_style", "carousel")
                            try:
                                _si = CONSOLE_SCROLL_STYLES.index(current)
                            except ValueError as _swallowed_error:
                                _log_swallowed("module: _si = CONSOLE_SCROLL_STYLES.index(current)", _swallowed_error)
                                _si = 0
                            new_style = CONSOLE_SCROLL_STYLES[(_si + 1) % len(CONSOLE_SCROLL_STYLES)]
                            db.config["console_scroll_style"] = new_style
                            db.save_settings()
                            if game_deck is not None: game_deck.refresh_from_config(db.config)
                            print(f"[GAMES] Console scroll style = {new_style}")
                        elif row_id == "text_color":
                            from game_deck import LIST_TEXT_COLOR_NAMES
                            current = db.config.get("menu_text_color", "white")
                            try:
                                _ci = LIST_TEXT_COLOR_NAMES.index(current)
                            except ValueError as _swallowed_error:
                                _log_swallowed("module: _ci = LIST_TEXT_COLOR_NAMES.index(current)", _swallowed_error)
                                _ci = 0
                            new_color = LIST_TEXT_COLOR_NAMES[(_ci + 1) % len(LIST_TEXT_COLOR_NAMES)]
                            db.config["menu_text_color"] = new_color
                            db.save_settings()
                            if game_deck is not None: game_deck.refresh_from_config(db.config)
                            print(f"[GAMES] Menu text color = {new_color}")
                        elif row_id == "game_screen_mode":
                            _game_mode_cycle = ["normal", "stretch"]
                            _cur_game_mode = db.config.get("game_screen_mode", "normal")
                            _gidx = _game_mode_cycle.index(_cur_game_mode) if _cur_game_mode in _game_mode_cycle else 0
                            db.config["game_screen_mode"] = _game_mode_cycle[(_gidx + 1) % len(_game_mode_cycle)]
                            db.save_settings()
                            print(f"[SETTINGS] Game Screen Mode = {db.config['game_screen_mode']}")
                            pygame.event.clear(pygame.KEYDOWN)
                        elif row_id == "relocate_roms_folder":
                            pygame.mixer.Channel(1).stop()
                            from game_deck import ROM_EXTENSIONS
                            _fe_open(
                                f"Add/Remove Roms — {console_key}",
                                set(ROM_EXTENSIONS.get(console_key, [])),
                                {"mode": "add_roms", "console_key": console_key}
                            )
                        elif row_id == "clear_console_roms":
                            _cn_manual_n = len(game_deck.console_roms_manual.get(console_key, [])) if game_deck is not None else 0
                            if _cn_manual_n:
                                app_state["show_clear_confirm"]     = True
                                app_state["clear_confirm_selection"] = "No"
                                app_state["clear_confirm_target"]   = "clear_console_roms"
                                app_state["clear_confirm_console"]  = console_key
                                app_state["clear_confirm_shown_at"] = now_ticks
                        elif row_id == "scan_for_roms":
                            pygame.mixer.Channel(1).stop()
                            _fe_open(
                                "Scan For Roms",
                                set(),
                                {"mode": "scan_for_roms"}
                            )
                        elif row_id == "scan_for_cores":
                            pygame.mixer.Channel(1).stop()
                            _fe_open(
                                "Scan For Cores",
                                set(),
                                {"mode": "scan_for_cores"}
                            )
                        elif row_id == "clear_roms":
                            if _any_manual_roms_exist():
                                app_state["show_clear_confirm"]     = True
                                app_state["clear_confirm_selection"] = "No"
                                app_state["clear_confirm_target"]   = "clear_roms"
                                app_state["clear_confirm_shown_at"] = now_ticks
                        elif row_id == "clear_cores":
                            if _any_cores_exist():
                                app_state["show_clear_confirm"]     = True
                                app_state["clear_confirm_selection"] = "No"
                                app_state["clear_confirm_target"]   = "clear_cores"
                                app_state["clear_confirm_shown_at"] = now_ticks
                        elif row_id == "clear_bios":
                            if _any_bios_exist():
                                app_state["show_clear_confirm"]     = True
                                app_state["clear_confirm_selection"] = "No"
                                app_state["clear_confirm_target"]   = "clear_bios"
                                app_state["clear_confirm_shown_at"] = now_ticks
                        elif row_id == "dvd_button_mapping":
                            app_state["menu_layer"] = "DVD_BTN_MAP"
                            app_state["dvd_map_cursor"] = 0
                            app_state["dvd_map_capturing"] = False
                            app_state["dvd_map_capture_idx"] = 0
                            print("[DVD REMAP] Opening DVD button mapping popup")
                        elif row_id == "dvd_audio_track":
                            if app_state.get("dvd_audio_track_count", 0) > 1:
                                _open_dvd_audio_track_picker()
                        elif row_id == "dvd_screen_mode":
                            _dvd_mode_cycle = ["normal", "stretch", "crop", "panscan"]
                            _cur_dvd_mode = db.config.get("dvd_screen_mode", "normal")
                            _idx = _dvd_mode_cycle.index(_cur_dvd_mode) if _cur_dvd_mode in _dvd_mode_cycle else 0
                            _new_dvd_mode = _dvd_mode_cycle[(_idx + 1) % len(_dvd_mode_cycle)]
                            db.config["dvd_screen_mode"] = _new_dvd_mode
                            db.save_settings()
                            print(f"[SETTINGS] DVD Screen Mode = {db.config['dvd_screen_mode']}")
                            try:
                                if dvd_engine is not None and hasattr(dvd_engine, "refresh_screen_mode_geometry"):
                                    if _dvd_screen_mode_change_needs_reopen(dvd_engine, _cur_dvd_mode, _new_dvd_mode):
                                        _clear_last_video_frame(keep_shot_memory=True, context="fullscreen")
                                        dvd_engine.refresh_screen_mode_geometry()
                                    else:
                                        _reset_pan_scan_state(keep_shot_memory=True)
                                        log.info("[SETTINGS] DVD Screen Mode %s -> %s: same decode geometry, skipping reopen", _cur_dvd_mode, _new_dvd_mode)
                            except Exception as e:
                                log.warning("DVD Screen Mode cycle: refresh_screen_mode_geometry failed: %s", e)
                            pygame.event.clear(pygame.KEYDOWN)
                        elif row_id == "close":
                            # WARNING: Close must do what Esc does: back to the games list with the console you came from still highlighted, never the first one.
                            app_state["menu_layer"] = "GAMES_LIST"
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "DVD_BTN_MAP":
                    if getattr(event, "synthetic", False):
                        continue

                    _capturing = app_state.get("dvd_map_capturing", False)

                    def _close_dvd_map():
                        _dvd_rows = ["status"] + get_games_sub_menu_rows(db, app_state, "DVD", True) + ["close"]
                        app_state["menu_layer"] = "GAMES_SUB_MENU"
                        app_state["games_sub_row"] = _dvd_rows.index("dvd_button_mapping")
                        app_state["dvd_map_capturing"] = False
                        pygame.event.clear(pygame.KEYDOWN)

                    if _capturing:

                        # WARNING: the fallback numbers below must match KEY_CAPTURE_SAME_PRESS_MS in performance_governor.py; they are used only when that module fails to import.
                        _DVD_HARD_DEDUP_MS = performance_governor.KEY_CAPTURE_SAME_PRESS_MS if performance_governor is not None else 250
                        _dvd_last = app_state.get("_dvd_map_last_accept")
                        if _dvd_last is not None:
                            _dvd_dt = pygame.time.get_ticks() - _dvd_last["ms"]
                            if _dvd_dt < _DVD_HARD_DEDUP_MS:
                                print(f"[DVD REMAP] Ignored duplicate capture event "
                                      f"(key={event.key} scancode={getattr(event, 'scancode', '?')}, "
                                      f"last accepted key={_dvd_last['key']}) within "
                                      f"{_DVD_HARD_DEDUP_MS}ms -- second delivery path of same "
                                      f"physical press.", flush=True)
                                continue
                            _dvd_same_key = (event.key == _dvd_last["key"])
                            _dvd_same_scancode = getattr(event, "scancode", 0) == _dvd_last["scancode"]
                            if _dvd_same_key and _dvd_dt < _REMAP_CAPTURE_DEDUP_MS and not _dvd_same_scancode:
                                print("[DVD REMAP] Ignored duplicate capture event "
                                      "(same button on a second input path).", flush=True)
                                continue

                        _remote_binds = db.config.get("remote_bindings", {}) if db is not None else {}
                        _reserved = set()
                        for _rb_action, _rb_default_key in CANONICAL_REMOTE_KEYS.items():
                            _rb_key = _remote_binds.get(_rb_action, _rb_default_key)
                            if _rb_key is not None:
                                _reserved.add(_rb_key)
                        _reserved.add(pygame.K_c)
                        _reserved.add(pygame.K_m)
                        _reserved.update(app_state.get("_dvd_map_used_keys", []))
                        if event.key in _reserved:
                            app_state["_dvd_map_reject_flash"] = pygame.time.get_ticks()
                            app_state["_dvd_map_reject_key"]   = event.key
                            print(f"[DVD REMAP] Rejected key {event.key} -- already used by remote remap, system, or an earlier action in this mapping pass.", flush=True)
                            continue

                        _idx = app_state.get("dvd_map_capture_idx", 0)
                        if _idx < len(DVD_MAP_ACTIONS):
                            _action_id = DVD_MAP_ACTIONS[_idx][0]
                            set_dvd_binding(db, _action_id, event.key)
                            app_state["_dvd_map_last_accept"] = {
                                "ms":       pygame.time.get_ticks(),
                                "key":      event.key,
                                "scancode": getattr(event, "scancode", 0),
                            }
                            app_state.setdefault("_dvd_map_used_keys", []).append(event.key)
                        _idx += 1
                        if _idx >= len(DVD_MAP_ACTIONS):
                            app_state["dvd_map_capturing"] = False
                            print("[DVD REMAP] Mapping sequence complete.")
                        else:
                            app_state["dvd_map_capture_idx"] = _idx
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                    _cursor = app_state.get("dvd_map_cursor", 0)
                    _dm_dir = menu_nav.key_to_direction(event.key, arrows=True)
                    if _dm_dir is not None:
                        _dm_to = menu_nav.navigate(app_state, "DVD_BTN_MAP", menu_nav.dvd_map_table(), menu_nav.dvd_map_cell(_cursor), _dm_dir)
                        if _dm_to is not None:
                            app_state["dvd_map_cursor"] = menu_nav.dvd_map_index(_dm_to)
                        continue
                    if menu_nav.is_accept(event.key):
                        if _cursor == 0:
                            app_state["dvd_map_capturing"] = True
                            app_state["dvd_map_capture_idx"] = 0
                            app_state["_dvd_map_last_accept"] = None
                            app_state["_dvd_map_reject_flash"] = None
                            app_state["_dvd_map_used_keys"] = []
                            print("[DVD REMAP] Starting capture sequence.")
                            pygame.event.clear(pygame.KEYDOWN)
                        else:
                            _close_dvd_map()
                    continue

                elif app_state["menu_layer"] == "GAMES_SAVE_PROFILE":
                    from game_deck import (HANDHELD_CONSOLES, BORDER_CONSOLES_HOME,
                                            border_available_for_console, SCREEN_SIZE_OPTIONS)
                    console_key  = app_state.get("games_selected_console", "DVD")
                    profile_num  = app_state.get("games_profile_num", 1)
                    profile_row  = app_state.get("games_profile_row", 0)
                    is_handheld       = console_key in HANDHELD_CONSOLES
                    is_border_console = border_available_for_console(console_key)
                    # WARNING: must mirror the drawing order in ui.py exactly.
                    _right_specs      = []
                    if is_handheld:
                        _right_specs.append("screen_size")
                    if is_border_console:
                        _right_specs.append("tv_bezel")
                    SAVE_ROW          = 1
                    LOAD_ROW          = 2
                    AUTO_SAVE_ROW     = 3
                    AUTO_LOAD_ROW     = 4
                    SCREEN_SIZE_ROW   = 5 + _right_specs.index("screen_size") if "screen_size" in _right_specs else None
                    BORDER_ROW        = 5 + _right_specs.index("tv_bezel") if "tv_bezel" in _right_specs else None
                    _console_bezel_style_n = 1
                    if BORDER_ROW is not None and console_key in BORDER_CONSOLES_HOME and game_deck is not None:
                        # WARNING: this row is shown unconditionally for these consoles, so the picker must offer a 1<->2 range even before a second bezel image exists.
                        _console_bezel_style_n = max(game_deck.console_bezel_style_count(console_key), 2)
                    _show_bezel_style = BORDER_ROW is not None and console_key in BORDER_CONSOLES_HOME
                    _outer_bezel_blocks = (console_key in BORDER_CONSOLES_HOME
                                           and bool(db.config.get("fake_43_border_enabled", False)))
                    TV_BEZEL_STYLE_ROW = (5 + len(_right_specs)) if _show_bezel_style else None
                    BACK_ROW          = 5 + len(_right_specs) + (1 if _show_bezel_style else 0)

                    def _get_prof_cfg(con, pnum):
                        profiles = (db.config
                                    .setdefault("console_profiles", {})
                                    .setdefault(con, {"active": 1, "profiles": {}})
                                    .setdefault("profiles", {}))
                        if pnum not in profiles and str(pnum) in profiles:
                            profiles[pnum] = profiles.pop(str(pnum))
                        return profiles.setdefault(pnum, {"auto_save": False, "auto_load": False})

                    def _active_prof(con):
                        return int(db.config
                                   .setdefault("console_profiles", {})
                                   .setdefault(con, {"active": 1, "profiles": {}})
                                   .get("active", 1))

                    def _set_active_prof(con, pnum):
                        db.config.setdefault("console_profiles", {}) \
                                 .setdefault(con, {"active": 1, "profiles": {}}) \
                                 ["active"] = pnum
                        db.save_settings()
                        if game_deck is not None and hasattr(game_deck, "sync_profile_from_db"):
                            game_deck.sync_profile_from_db(con, db.config)

                    def _is_live_target(con, pnum):
                        return (game_deck is not None
                                and getattr(game_deck, "_libretro_console", None) == con
                                and _active_prof(con) == pnum)

                    def _cycle_screen_size(con, pnum, step):
                        cfg  = _get_prof_cfg(con, pnum)
                        keys = [k for k, _label, _f in SCREEN_SIZE_OPTIONS]
                        cur  = cfg.get("screen_size", "full")
                        idx  = keys.index(cur) if cur in keys else 0
                        idx  = (idx + step) % len(keys)
                        cfg["screen_size"] = keys[idx]
                        _sync_profile_setting_across_consoles(
                            con, pnum, "screen_size", keys[idx])
                        db.save_settings()
                        if _is_live_target(con, pnum):
                            game_deck._libretro_screen_size = keys[idx]
                        return keys[idx]

                    def _toggle_border(con, pnum):
                        cfg = _get_prof_cfg(con, pnum)
                        cur = cfg.get("border_enabled", cfg.get("gb_border", False))
                        return _set_console_bezel_enabled(con, pnum, not cur)

                    _sp_dir = menu_nav.key_to_direction(event.key)
                    if _sp_dir is not None:
                        _sp_rows = menu_nav.save_profile_rows(is_handheld, is_border_console, _show_bezel_style)
                        _sp_to = menu_nav.navigate(app_state, "GAMES_SAVE_PROFILE:" + str(console_key), menu_nav.save_profile_table(_sp_rows), menu_nav.save_profile_cell(_sp_rows, profile_row), _sp_dir)
                        if _sp_to is not None:
                            app_state["games_profile_row"] = menu_nav.save_profile_index(_sp_rows, _sp_to)
                        continue

                    if menu_nav.is_accept(event.key):
                        if profile_row in (SCREEN_SIZE_ROW, BORDER_ROW, TV_BEZEL_STYLE_ROW):
                            _now_tk  = pygame.time.get_ticks()
                            _pr_deb  = app_state.setdefault("_menu_toggle_debounce", {})
                            _pr_key  = f"profile_row_{profile_row}_{console_key}_{profile_num}"
                            if _now_tk - _pr_deb.get(_pr_key, -10000) < 300:
                                pygame.event.clear(pygame.KEYDOWN)
                                continue
                            _pr_deb[_pr_key] = _now_tk
                        is_active = (_active_prof(console_key) == profile_num)
                        if profile_row == 0:
                            _set_active_prof(console_key, profile_num)
                            print(f"[GAMES] Profile {profile_num} now active for {console_key}")
                        elif profile_row == SAVE_ROW and is_active:
                            if game_deck is not None and hasattr(game_deck, "libretro_save_to_profile"):
                                ok = game_deck.libretro_save_to_profile(console_key, profile_num)
                                msg = f"SAVED TO PROFILE {profile_num}" if ok else "SAVE FAILED"
                                if hasattr(game_deck, "_libretro_osd_msg"):
                                    game_deck._libretro_osd_msg   = msg
                                    game_deck._libretro_osd_until = pygame.time.get_ticks() + 2000
                        elif profile_row == LOAD_ROW and is_active:
                            if game_deck is not None and hasattr(game_deck, "libretro_load_from_profile"):
                                ok = game_deck.libretro_load_from_profile(console_key, profile_num)
                                msg = f"LOADED PROFILE {profile_num}" if ok else "NO SAVE / FAILED"
                                if hasattr(game_deck, "_libretro_osd_msg"):
                                    game_deck._libretro_osd_msg   = msg
                                    game_deck._libretro_osd_until = pygame.time.get_ticks() + 2000
                        elif profile_row == AUTO_SAVE_ROW and is_active:
                            cfg = _get_prof_cfg(console_key, profile_num)
                            cfg["auto_save"] = not cfg.get("auto_save", False)
                            _sync_profile_setting_across_consoles(
                                console_key, profile_num, "auto_save", cfg["auto_save"])
                            db.save_settings()
                            if _is_live_target(console_key, profile_num):
                                game_deck._libretro_auto_save = cfg["auto_save"]
                        elif profile_row == AUTO_LOAD_ROW and is_active:
                            cfg = _get_prof_cfg(console_key, profile_num)
                            cfg["auto_load"] = not cfg.get("auto_load", False)
                            _sync_profile_setting_across_consoles(
                                console_key, profile_num, "auto_load", cfg["auto_load"])
                            db.save_settings()
                            if _is_live_target(console_key, profile_num):
                                game_deck._libretro_auto_load = cfg["auto_load"]
                        elif profile_row == SCREEN_SIZE_ROW and is_active:
                            _cycle_screen_size(console_key, profile_num, 1)
                        elif profile_row == BORDER_ROW and is_active and not _outer_bezel_blocks:
                            _bz_cur_cfg = _get_prof_cfg(console_key, profile_num)
                            _bz_cur_val = _bz_cur_cfg.get("border_enabled", _bz_cur_cfg.get("gb_border", False))
                            _bz_turning_on = not _bz_cur_val
                            # WARNING: warn on any enable, not just genuine CRT; turning it back off never needs a warning.
                            _bz_needs_warning = _bz_turning_on
                            if _bz_needs_warning:
                                if db.config.get("console_bezel_skip_confirm", False):
                                    _toggle_border(console_key, profile_num)
                                    print(f"[CONSOLE BEZEL] Turned on for {console_key} profile "
                                          f"{profile_num} (confirmation skipped by user preference).")
                                else:
                                    app_state["show_clear_confirm"]        = True
                                    app_state["clear_confirm_selection"]   = "No"
                                    app_state["clear_confirm_target"]      = "console_bezel_toggle"
                                    app_state["clear_confirm_channel"]     = console_key
                                    app_state["clear_confirm_profile_num"] = profile_num
                                    app_state["clear_confirm_shown_at"]    = now_ticks
                                    app_state["clear_confirm_burnin_new_value"] = True
                                    app_state["clear_confirm_dont_show_again"]  = False
                            else:
                                _toggle_border(console_key, profile_num)
                        elif profile_row == TV_BEZEL_STYLE_ROW and is_active and not _outer_bezel_blocks:
                            _n_styles = (max(game_deck.console_bezel_style_count(console_key), 2)
                                         if game_deck is not None else 1)
                            if _n_styles > 1:
                                _bz_style_cfg = _get_prof_cfg(console_key, profile_num)
                                try:
                                    _cur_style = int(_bz_style_cfg.get("border_style", 1))
                                except (TypeError, ValueError) as _swallowed_error:
                                    _log_swallowed("module: _cur_style = int(_bz_style_cfg.get('border_style', 1))", _swallowed_error)
                                    _cur_style = 1
                                _new_style = (_cur_style % _n_styles) + 1
                                _set_console_bezel_style(console_key, profile_num, _new_style)
                                print(f"[CONSOLE BEZEL] Style = {_new_style} for {console_key} profile {profile_num}")
                        elif profile_row == BACK_ROW:
                            app_state["menu_layer"] = "GAMES_SUB_MENU"
                        pygame.event.clear(pygame.KEYDOWN)
                        continue

                elif app_state["menu_layer"] == "VIDEO_ROWS":
                    cur_row = app_state.get("menu_selection_index", 0)

                    _vd_dir = menu_nav.key_to_direction(event.key)
                    if _vd_dir is not None:
                        _vd_from = menu_nav.video_cell(cur_row)
                        _vd_to = menu_nav.navigate(app_state, "VIDEO_ROWS", menu_nav.video_table(), _vd_from, _vd_dir)
                        if _vd_to == menu_nav.TAB_BAR:
                            app_state["menu_layer"] = "TAB_SELECTION"
                        elif _vd_to is not None:
                            app_state["menu_selection_index"] = menu_nav.video_index(_vd_to)
                        elif (_vd_from in menu_nav.SLIDER_SPECS and _vd_dir in (menu_nav.LEFT, menu_nav.RIGHT)
                                and menu_nav.step_ready(app_state.setdefault("_step_gate", {}), _vd_from, now_ticks)
                                and menu_nav.slider_adjust(db.config, _vd_from, _vd_dir)):
                            _mark_settings_dirty()
                        continue

                    if menu_nav.is_accept(event.key):
                        if cur_row in (0, 1, 2, 3) and db.remote_screen_mode_for(app_state.get("current_channel", "")):
                            # WARNING: a Server-streamed channel's Screen Mode is decided by the Server; do not touch the user's own setting.
                            print("[SERVER SYNC] Screen Mode is controlled by the Server on streamed channels.")
                            pygame.event.clear(pygame.KEYDOWN)
                            continue
                        elif cur_row in (0, 1, 2, 3):
                            _new_mode = {0: "normal", 1: "stretch", 2: "crop", 3: "panscan"}[cur_row]
                            _old_mode = db.config.get("screen_mode", "normal")
                            db.config["screen_mode"] = _new_mode
                            db.save_settings()
                            print(f"[SETTINGS] Screen Mode = {db.config['screen_mode']}")

                            _vlc_needs_reopen = _screen_mode_change_needs_reopen(vlc_engine, _old_mode, _new_mode)
                            _dvd_needs_reopen = _screen_mode_change_needs_reopen(dvd_engine, _old_mode, _new_mode)

                            if _vlc_needs_reopen or _dvd_needs_reopen:
                                # WARNING: clear the cached frame before reopening; it holds the old geometry.
                                _clear_last_video_frame(keep_shot_memory=True, context="fullscreen")
                                try:
                                    if _vlc_needs_reopen and vlc_engine is not None:
                                        vlc_engine.refresh_screen_mode_geometry()
                                    if _dvd_needs_reopen and dvd_engine is not None:
                                        dvd_engine.refresh_screen_mode_geometry()
                                except Exception as e:
                                    log.warning("Screen Mode change: live geometry refresh failed: %s", e)
                            else:
                                _reset_pan_scan_state(keep_shot_memory=True)
                                log.info("[SETTINGS] Screen Mode %s -> %s: same decode geometry, skipping reopen", _old_mode, _new_mode)
                            pygame.event.clear(pygame.KEYDOWN)
                            continue
                        elif cur_row == 9:
                            app_state["show_menu"] = False
                            app_state["games_tab_page"] = 0
                            app_state["menu_shown_at"] = 0
                            pygame.event.clear(pygame.KEYDOWN)
                            continue

                elif app_state["menu_layer"] == "THEME_ROWS":
                    cur_row = app_state.get("menu_selection_index", 0)

                    _th_dir = menu_nav.key_to_direction(event.key)
                    if _th_dir is not None:
                        _th_from = menu_nav.theme_cell(cur_row, app_state.get("theme_row2_col", 0))
                        _th_to = menu_nav.navigate(app_state, "THEME_ROWS", menu_nav.theme_table(), _th_from, _th_dir)
                        if _th_to == menu_nav.TAB_BAR:
                            app_state["menu_layer"] = "TAB_SELECTION"
                        elif _th_to is not None:
                            app_state["menu_selection_index"] = menu_nav.theme_index(_th_to)
                            app_state["theme_row2_col"] = menu_nav.theme_row2_column(_th_to)
                        elif (_th_from in menu_nav.SLIDER_SPECS and _th_dir in (menu_nav.LEFT, menu_nav.RIGHT)
                                and menu_nav.step_ready(app_state.setdefault("_step_gate", {}), _th_from, now_ticks)
                                and menu_nav.slider_adjust(db.config, _th_from, _th_dir)):
                            _mark_settings_dirty()
                        continue

                    # WARNING: selection 0 is Volume Bar (col 0) / Channel Static (col 1); selection 1 is Channel Transition (col 0) / Letterboxing (col 1); 2 to 4 are the sliders; 5 is Close.
                    if menu_nav.is_accept(event.key):
                        _th_col = app_state.get("theme_row2_col", 0)
                        if cur_row == 1:
                            if _th_col == 1:
                                current_lb = db.config.get("letterbox_color", "black")
                                db.config["letterbox_color"] = "grey" if current_lb == "black" else "black"
                            else:
                                current_tt = db.config.get("transition_type", "black")
                                db.config["transition_type"] = "static" if current_tt == "black" else "black"
                            _mark_settings_dirty()
                            continue
                        if cur_row == 0:
                            if _th_col == 1:
                                current_snc = db.config.get("static_noise_color", "white")
                                _snc_cycle = {"grey": "rainbow", "rainbow": "theme", "theme": "white", "white": "grey"}
                                db.config["static_noise_color"] = _snc_cycle.get(current_snc, "white")
                            else:
                                current_vbs = db.config.get("volume_bar_style", "1")
                                db.config["volume_bar_style"] = "2" if current_vbs == "1" else "1"
                            _mark_settings_dirty()
                            continue
                        if cur_row == 5:
                            app_state["show_menu"] = False
                            app_state["games_tab_page"] = 0
                            app_state["menu_shown_at"] = 0
                            pygame.event.clear(pygame.KEYDOWN)
                            continue

    _menu_nav_frame_end(_nav_frame_begin, events)
    _prof_mark("events")

    # ========================================================================
    # SECTION: Loading screen
    # ========================================================================

    if app_state["is_loading"]:
        pygame.event.pump()
        
        if "load_start_time" not in app_state:
            app_state["load_start_time"] = pygame.time.get_ticks()
            app_state["_load_loop_entered_ticks"] = pygame.time.get_ticks()
            app_state["_load_progress_f"] = 0.0
            app_state["_boot_bar_t0"] = time.time()

        _done = app_state.get("_boot_steps_done", set())
        _all_steps_done = len(_done) >= len(BOOT_STEPS)
        _bar_now = time.time()
        if _all_steps_done:
            target_pct = 100.0
        else:
            target_pct = min(_boot_bar_const("BOOT_BAR_MAX_BEFORE_DONE", 99.0),
                             _boot_bar_target_percent(_done, _bar_now))

        _now_ticks = pygame.time.get_ticks()
        _dt_s = max(0.0, (_now_ticks - app_state.get("_load_last_tick", _now_ticks)) / 1000.0)
        app_state["_load_last_tick"] = _now_ticks
        _bar_rate = _boot_bar_const("BOOT_BAR_FINISH_RATE_PER_SECOND", 60.0) if _all_steps_done \
            else _boot_bar_const("BOOT_BAR_CATCHUP_RATE_PER_SECOND", 12.0)
        if target_pct > app_state["_load_progress_f"]:
            app_state["_load_progress_f"] = min(target_pct, app_state["_load_progress_f"] + _bar_rate * _dt_s)
        app_state["load_progress"] = int(app_state["_load_progress_f"])

        # WARNING: the fallback numbers below must match BOOT_HOLD_AT_100_SECONDS in performance_governor.py; they are used only when that module fails to import.
        _HOLD_AT_100_S = performance_governor.BOOT_HOLD_AT_100_SECONDS if performance_governor is not None else 0.5
        real_subsystems_loaded = len(_done) >= len(BOOT_STEPS) and app_state["_load_progress_f"] >= 100.0
        if real_subsystems_loaded:
            app_state["load_progress"] = 100
            if "_boot_100_reached_at" not in app_state:
                app_state["_boot_100_reached_at"] = time.time()
                _boot_bar_learn(app_state["_boot_bar_t0"])
            _held_long_enough = (time.time() - app_state["_boot_100_reached_at"]) >= _HOLD_AT_100_S
        else:
            _held_long_enough = False
        
        if db is not None and getattr(db, 'ready_flag', False):
            import colorsys
            bg_hue = db.config.get("theme_bg_hue", 220) / 360.0
            ui_hue = db.config.get("theme_ui_hue", 140) / 360.0
            r, g, b = colorsys.hsv_to_rgb(ui_hue, 0.9, 1.0)
            ui_color = (int(r * 255), int(g * 255), int(b * 255))
            r, g, b = colorsys.hsv_to_rgb(bg_hue, 0.6, 0.15)
            bg_color = (int(r * 255), int(g * 255), int(b * 255))
            active_theme = {"ui": ui_color, "bg": bg_color, "text": DEFAULT_THEME["text"]}
        else:
            active_theme = dict(DEFAULT_THEME)
        
        LOADING_GREEN = COLOR_LOADING_GREEN
        if loading_bg_surface:
            w_w, w_h = screen.get_size()
            _lbg_w, _lbg_h = loading_bg_surface.get_size()
            dest_w, dest_h, dest_x, dest_y = _letterbox_fit(_lbg_w, _lbg_h, w_w, w_h)
            # WARNING: not pure black; (0, 0, 0) is the game-overlay transparency key.
            screen.fill(COLOR_SCREEN_BLACK)
            scaled = pygame.transform.scale(loading_bg_surface, (dest_w, dest_h))
            screen.blit(scaled, (dest_x, dest_y))

            art_scale = dest_w / _lbg_w if _lbg_w else 1.0

            stretched_w = max(60, int(_LOAD_BAR_WIDTH * art_scale))
            bar_h = max(3, int(_LOAD_BAR_HEIGHT * art_scale))

            bar_x = dest_x + int(_LOAD_BAR_CENTER_X * art_scale) - stretched_w // 2
            bar_y = dest_y + int(_LOAD_BAR_CENTER_Y * art_scale) - bar_h // 2
            
            pygame.draw.rect(screen, COLOR_LOADING_BAR_TRACK, (bar_x, bar_y, stretched_w, bar_h), border_radius=3)
            
            if app_state["load_progress"] > 0:
                fill_w = int(stretched_w * (app_state["load_progress"] / 100.0))
                pygame.draw.rect(screen, LOADING_GREEN, (bar_x, bar_y, fill_w, bar_h), border_radius=3)

            if DETECTED_ASPECT_RATIO != "4:3":
                font_size = max(9, int(_LOAD_BAR_FONT_SIZE * art_scale))
                text_gap = max(2, int(_LOAD_BAR_TEXT_GAP * art_scale))
                f_load = _cached_sys_font("Courier New", font_size, bold=True)
                txt_str = f"{app_state['load_progress']}%"
                lbl_txt = f_load.render(txt_str, True, LOADING_GREEN)

                txt_x = dest_x + int(_LOAD_BAR_CENTER_X * art_scale) - lbl_txt.get_width() // 2
                txt_y = bar_y - lbl_txt.get_height() - text_gap
                screen.blit(lbl_txt, (txt_x, txt_y))
        else:
            green_loading_theme = {"ui": LOADING_GREEN, "bg": active_theme["bg"], "text": DEFAULT_THEME["text"]}
            render_loading_screen(screen, app_state["load_progress"], green_loading_theme)

        # WARNING: do not leave the loading screen until every real boot step is done and the bar has caught up to 100 and held there for _HOLD_AT_100_S.
        if real_subsystems_loaded and _held_long_enough:
            print("[TELEMETRY - PART 14] Preloader finished. Database records safely buffered from disk.")
            app_state["is_loading"] = False
            app_state["show_splash"] = db.config.get("show_controls_on_launch", True)
            if app_state["show_splash"]:
                _splash_now = pygame.time.get_ticks()
                app_state["last_input_time"] = _splash_now
                app_state["splash_shown_at"] = _splash_now
            if app_state.get("show_clear_confirm", False):
                # WARNING: a boot update popup opens while the loading screen is still up; its 20 second idle timer must start when it first appears, not when it was queued.
                _popup_now = pygame.time.get_ticks()
                app_state["last_input_time"] = _popup_now
                app_state["clear_confirm_shown_at"] = _popup_now
            
            if 'game_deck' in globals() and game_deck is not None:
                try:
                    game_deck.refresh_from_config(db.config)
                    print("[PERSISTENCE HOOK] Synchronized game_deck configurations with disk records on launch.")
                except Exception as deck_sync_err:
                    log.warning(f"[PERSISTENCE HOOK ERROR] Could not sync game_deck options on boot: {deck_sync_err}")

            _last_ch = str(db.config.get("last_channel", "05")).zfill(2) if db else "05"
            if _last_ch in ("03", "04") or not _last_ch:
                _last_ch = "05"
            app_state["current_channel"] = _last_ch
            change_channel(_last_ch, is_boot=True)
            if db is not None and db.config.get("boot_anim_enabled", False):
                app_state["_crt_power_on_started_at"] = pygame.time.get_ticks()

        _present_cpu_window()
        clock.tick(60)
        continue

    _prof_mark("loading")

    # ========================================================================
    # SECTION: Frame setup: virtual screen, content rect & playback state
    # ========================================================================

    w_w, w_h = screen.get_size()
    app_state["_window_size"] = (w_w, w_h)
    ch = app_state["current_channel"]
    _surf_quiet = _surf_origin_active()

    app_state["_video_painted_this_frame"] = False
    app_state["_held_frame_drawn_this_frame"] = False

    _real_screen = screen
    if (globals().get("_virtual_screen_surf") is not None
            and globals()["_virtual_screen_surf"].get_locked()
            and _surface_lock_event(globals()["_virtual_screen_surf"], "virtual screen")):
        globals()["_virtual_screen_surf"] = None
    if (globals().get("_virtual_screen_surf") is None
            or globals()["_virtual_screen_surf"].get_size() != (w_w, w_h)):
        globals()["_virtual_screen_surf"] = pygame.Surface((w_w, w_h))
    screen = globals()["_virtual_screen_surf"]

    content_rect = _compute_content_rect(w_w, w_h)
    _full_window_rect = pygame.Rect(0, 0, w_w, w_h)
    if content_rect.width < w_w or content_rect.height < w_h or _pixel_orbiter_active():
        screen.fill(_video_bar_color())

    _report_missing_media(None, None)

    app_state["_vis_card_text"] = None
    
    if db is not None and getattr(db, 'ready_flag', False):
        _theme_key = db.config.get("current_theme", "DefaultBlueGreen")
        active_theme = dict(db.themes.get(_theme_key) or db.themes.get("DefaultBlueGreen")
                             or dict(DEFAULT_THEME))
        try:
            import colorsys as _cs
            _ui_hue = db.config.get("theme_ui_hue", 140) / 360.0
            _bg_hue = db.config.get("theme_bg_hue", 220) / 360.0
            _r, _g, _b = _cs.hsv_to_rgb(_ui_hue, 0.9, 1.0)
            active_theme["ui"] = (int(_r * 255), int(_g * 255), int(_b * 255))
            _r, _g, _b = _cs.hsv_to_rgb(_bg_hue, 0.6, 0.15)
            active_theme["bg"] = (int(_r * 255), int(_g * 255), int(_b * 255))
        except Exception as e:
            _log_warn_throttled("theme_hue_recompute", "Live theme hue recompute failed, using unmodified theme colors this frame: %s", e)
    else:
        active_theme = dict(DEFAULT_THEME)

    app_state["_active_theme_snapshot"] = active_theme

    current_playback_state = calculate_slotted_playback_state(ch)

    _live_pb_raw = str(app_state.get("_live_playback_channel", "") or "").strip()
    _watchdog_owner_ch = _live_pb_raw.zfill(2) if _live_pb_raw else ch
    if _watchdog_owner_ch == ch:
        _owner_playback_state = current_playback_state
    elif not app_state.get("is_playing_video", False):
        # WARNING: the owner channel's answer is read only by the video watchdog, which runs only while a video plays; asking the scheduler for it on every frame of the games channel or a menu rebuilt that channel's schedule on the screen thread (audit stage 4, 2026-11-02: frame setup up to 361 ms on ch03).
        _owner_playback_state = {}
    else:
        try:
            _owner_playback_state = calculate_slotted_playback_state(_watchdog_owner_ch)
        except Exception as e:
            log.warning("[WATCHDOG] owner-channel schedule lookup failed for ch%s: %s", _watchdog_owner_ch, e)
            _owner_playback_state = {}

    _prof_mark("frame_setup")

    # ========================================================================
    # SECTION: Video end & stall detection
    # ========================================================================

    _engine_wedged_this_frame = False
    if vlc_engine is not None and getattr(vlc_engine, "_wedged", False):
        _replace_wedged_vlc_engine()
        _engine_wedged_this_frame = True
    is_video_finished = False
    _switch_pending = app_state.get("_pending_channel_activation") is not None
    _open_confirm_pending = vlc_engine is not None and (
        getattr(vlc_engine, "_open_confirm_pending_attempt", None) is not None or _engine_open_in_flight(vlc_engine))
    _finish_reason = None
    if vlc_engine is not None and app_state.get("is_playing_video", False) and not _switch_pending and not _open_confirm_pending and not _engine_wedged_this_frame and not _surf_quiet:
        try:
            vlc_state, _len_ms = vlc_engine.get_playback_state()
            if vlc_state in ("opening", "buffering"):
                last_play_at = app_state.get("last_video_play_started_at", 0)
                if last_play_at > 0 and pygame.time.get_ticks() - last_play_at > 8000:
                    _stall_attempt_id = getattr(vlc_engine, "_current_attempt_id", None)
                    log.warning(f"[WATCHDOG][ATTEMPT {_stall_attempt_id}] Video stalled in Opening/Buffering on ch{ch} for 8s+, treating as failed.")
                    is_video_finished = True
                    _finish_reason = "stalled"
                    _stalled_ch_info = db.channels_db.get(_watchdog_owner_ch, {}) if db is not None else {}
                    _stalled_file = _owner_playback_state.get("file", "")
                    if _stalled_file:
                        _last_attempt_reason[_watchdog_owner_ch] = f"opening_timeout (attempt {_stall_attempt_id})"
                        _mark_file_broken(_stalled_ch_info, _stalled_file, reason="opening_timeout")
            elif vlc_state == "playing":
                _playing_file = _owner_playback_state.get("file", "")
                if _playing_file:
                    _note_playback_succeeded(_playing_file)
            _pos_ms = vlc_engine.get_current_time()
            _tracking = vlc_engine._media_end_tracking
            _was_debouncing = bool(_tracking.get("_media_end_check_start_time"))
            _finished, _reason = check_media_truly_ended(
                state=vlc_state,
                pos_ms=_pos_ms,
                length_ms=_len_ms,
                now_ms=pygame.time.get_ticks(),
                last_play_started_at_ms=app_state.get("last_video_play_started_at", 0),
                tracking=_tracking,
                debounce_ms=200,
                proximity_ms=_END_PROXIMITY_MS,
            )
            if (vlc_state in ("ended", "stopped") and not _finished and _was_debouncing
                    and not _tracking.get("_media_end_check_start_time") and _len_ms and _pos_ms is not None):
                log.info(
                    "[PLAYBACK] %s read at %sms of %sms known length "
                    "(not near end) -- treating as a VLC glitch, not a "
                    "real finish.", vlc_state, _pos_ms, _len_ms)
            if _finished:
                is_video_finished = True
                _finish_reason = _reason
        except Exception as e: log.warning(f"[PLAYBACK] video-finished check failed: {e}")
    else:
        vlc_engine._media_end_tracking = {} if vlc_engine is not None else None

    _bg_ch = str(app_state.get("_live_playback_channel", "") or "")
    if _bg_ch:
        _bg_ch = _bg_ch.zfill(2)
    if (_bg_ch and ch in ("03", "04") and _bg_ch != ch
            and not _surf_quiet
            and is_video_finished
            and vlc_engine is not None
            and getattr(vlc_engine, "ready_flag", False)
            and not _engine_wedged_this_frame
            and db is not None):
        _bg_now_ms = pygame.time.get_ticks()
        if _bg_now_ms - app_state.get("_bg_last_vlc_retry_at", 0) > 300:
            app_state["_bg_last_vlc_retry_at"] = _bg_now_ms
            try:
                _bg_ch_entry = db.channels_db.get(_bg_ch, {})
                _bg_anchor = _bg_ch_entry.get("playback_anchor", {})
                if _bg_anchor.get("file"):
                    _bg_ab = _bg_anchor.get("block", "Morning")
                    _bg_guard_key = "last_ended_commercial" if _bg_anchor.get("mode") == "Commercial" else "just_ended_slot"
                    _bg_skip_guard_arm = False
                    if _bg_guard_key == "just_ended_slot":
                        try:
                            _bg_ended_show, _bg_ended_eps = _get_show_episode_context(
                                _bg_ch_entry, _bg_ab, str(_bg_anchor["file"]))
                            if _bg_ended_show is not None and len(_bg_ended_eps) <= 1:
                                _bg_skip_guard_arm = True
                        except Exception as e:
                            log.warning("BG WATCHDOG: episode-count check failed for ch%s: %s", _bg_ch, e)
                    if not _bg_skip_guard_arm:
                        _bg_ch_entry.setdefault("playback_log", {})[_bg_guard_key] = {
                            "file": os.path.normpath(str(_bg_anchor["file"])).lower(),
                            "block": _bg_ab,
                            "armed_ts": broadcast_clock.now().timestamp(),
                        }
                    print(f"[BG WATCHDOG] ch{_bg_ch} (warm-continued in background) "
                          f"finished '{os.path.basename(str(_bg_anchor['file']))}' -- advancing.")
                _bg_ch_entry["playback_anchor"] = {}
                _bg_next = calculate_slotted_playback_state(_bg_ch)
                if _bg_next.get("mode") in ("Video", "Commercial") and _bg_next.get("file"):
                    try:
                        vlc_engine.player.audio_set_mute(True)
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: vlc_engine.player.audio_set_mute(True)", _swallowed_error)

                    _bg_snap = dict(_bg_next)
                    _bg_snap_fg_ch = ch

                    def _bg_on_confirmed(success, attempt_id, deferred, _s=_bg_snap, _fg_ch=_bg_snap_fg_ch):
                        if success:
                            _confirm_playback_started(
                                _bg_ch, attempt_id, _s.get("file"),
                                _s.get("seek", 0), _s.get("seek_slot_offset", 0),
                                _s.get("duration", 1800), _s.get("mode", "Video"),
                                _s.get("block", "Morning"), _s.get("interior_cut", False),
                                deferred,
                            )
                            if app_state.get("loaded_preview_path_cache", "") and _fg_ch == "04":
                                app_state["loaded_preview_path_cache"] = _s.get("file")
                        else:
                            _confirm_playback_failed(_bg_ch, attempt_id, _s.get("file"), deferred,
                                                      reason="bg_watchdog_open_failed",
                                                      clear_live_channel=True)

                    # WARNING: stamp this before the call; see the mid-stream content-change race note in change_channel().
                    app_state["last_video_play_started_at"] = pygame.time.get_ticks()
                    _bg_file, _bg_seek = _bg_next["file"], _bg_next.get("seek", 0)
                    _bg_gain = _lookup_file_gain(_bg_ch, _bg_file)
                    # WARNING: opens on the content-activate thread like a tune, so a picture-box wait never freezes the menu or guide drawn over it (N5).
                    _dispatch_content_activation(
                        lambda _f=_bg_file, _sk=_bg_seek, _g=_bg_gain, _cb=_bg_on_confirmed:
                            vlc_engine.play_file_segmented(_f, _sk, gain=_g, defer_unmute=True, on_confirmed=_cb, follow_clock=True))
                else:
                    try:
                        vlc_engine.stop(block=False)
                    except Exception as e:
                        log.warning("BG WATCHDOG: stop failed for ch%s: %s", _bg_ch, e)
                    app_state["is_playing_video"] = False
                    app_state["_live_playback_channel"] = ""
            except Exception as e:
                log.warning("BG WATCHDOG: advance failed for ch%s: %s", _bg_ch, e)

    if (ch not in ("03", "04")
            and not _surf_quiet
            and current_playback_state["mode"] in ("Video", "Commercial")
            and (not app_state.get("is_playing_video", False) or is_video_finished)
            and vlc_engine is not None
            and getattr(vlc_engine, "ready_flag", False)
            and not _open_confirm_pending
            and not _engine_wedged_this_frame):
        now_watchdog = pygame.time.get_ticks()
        _watchdog_ms = 300 if is_video_finished else 2500
        if now_watchdog - app_state.get("last_vlc_retry_at", 0) > _watchdog_ms:
            app_state["last_vlc_retry_at"] = now_watchdog
            _wd_ch_key = str(ch).zfill(2)
            _skip_advance_this_frame = False
            if is_video_finished:
                app_state["is_playing_video"] = False

                if _finish_reason == "error":
                    _watchdog_consecutive_errors[_wd_ch_key] = (
                        _watchdog_consecutive_errors.get(_wd_ch_key, 0) + 1)
                else:
                    _watchdog_consecutive_errors[_wd_ch_key] = 0
                if db is not None:
                    _ch_entry = db.channels_db.get(str(ch).zfill(2), {})
                    _anchor   = _ch_entry.get("playback_anchor", {})

                    _anchor_matches_loaded = False
                    if _anchor.get("file") and vlc is not None and vlc_engine is not None:
                        try:
                            _amedia_wd = vlc_engine.player.get_media()
                            if _amedia_wd:
                                from urllib.parse import unquote as _unquote_wd
                                _loaded_p_wd = os.path.normpath(
                                    _unquote_wd(_amedia_wd.get_mrl().replace("file:///", ""))
                                ).lower()
                                _anchor_p_wd = os.path.normpath(str(_anchor["file"])).lower()
                                _anchor_matches_loaded = (_loaded_p_wd == _anchor_p_wd)
                        except Exception as e:
                            log.warning("WATCHDOG: anchor identity check failed for ch%s: %s", ch, e)

                    _resume_spurious = False
                    if _anchor.get("wall_start") is not None and _anchor.get("file") and _anchor_matches_loaded:
                        _now_w = broadcast_clock.now().replace(tzinfo=None)
                        _wall_now = (
                            _now_w.hour * 3600 + _now_w.minute * 60 + _now_w.second
                            + _now_w.microsecond / 1_000_000.0
                        )
                        _elapsed = _wall_now - _anchor["wall_start"]
                        if _elapsed < 0:
                            _elapsed += 86400
                        _real_dur = int(_anchor.get("seek_offset", 0) + _elapsed)
                        _ab = _anchor.get("block", "Morning")
                        _known_dur = None
                        try:
                            _known_dur = _read_file_probe_facts(
                                os.path.normpath(str(_anchor["file"]))).get("duration")
                        except Exception as _swallowed_error:
                            _log_swallowed("main script: _known_dur = _read_file_probe_facts(os.path.normpath(str(_anchor['file']))).get('durat...", _swallowed_error)
                        _too_long = bool(
                            _known_dur and _known_dur > 0
                            and _real_dur > max(30, _known_dur * 2)
                        )
                        _transient_blip = (not _too_long) and (_finish_reason != "error") and (_elapsed < 2.0)
                        _near_true_end = bool(_known_dur and _known_dur > 0 and _real_dur >= _known_dur - 3)
                        _far_from_known_end = bool(
                            _known_dur and _known_dur > 0 and not _too_long
                            and _real_dur < _known_dur - max(45, _known_dur * 0.08)
                        )
                        _spurious_blip = (bool(_known_dur and _known_dur > 0)
                                          and not _near_true_end
                                          and not _too_long
                                          and _finish_reason != "error"
                                          and (_transient_blip or _far_from_known_end))
                        _suspicious = (_finish_reason == "error") or _too_long or _transient_blip or _far_from_known_end
                        if _real_dur > 0 and not _suspicious:
                            # WARNING: this estimate must never be written back into the probe cache, the anchor or the frozen schedule durations; only a real ffmpeg/libVLC measurement goes there.
                            print(f"[WATCHDOG] {os.path.basename(str(_anchor['file']))} on ch{ch} "
                                  f"ended (wall-clock position {_real_dur}s, probed runtime "
                                  f"{_known_dur if _known_dur else 'unknown'}s) -- advancing to next show.")
                            if _known_dur and _known_dur > 0 and abs(_real_dur - _known_dur) > 5:
                                log.warning(
                                    "WATCHDOG: ch%s %s ended at a wall-clock position of %ss but its probed "
                                    "duration is %ss -- keeping the probed duration (the wall-clock figure "
                                    "is not a measurement).",
                                    ch, os.path.basename(str(_anchor["file"])), _real_dur, _known_dur)
                            _watchdog_consecutive_spurious_resumes.pop(_wd_ch_key, None)
                            _note_playback_succeeded(str(_anchor.get("file", "")))
                        elif _real_dur > 0 and _spurious_blip:
                            _sr_tracker = _watchdog_consecutive_spurious_resumes.get(_wd_ch_key)
                            if (_sr_tracker is None
                                    or now_watchdog - _sr_tracker["window_start_ms"] > _WATCHDOG_SPURIOUS_RESUME_WINDOW_MS):
                                _sr_tracker = {"count": 0, "window_start_ms": now_watchdog}
                            _sr_tracker["count"] += 1
                            _watchdog_consecutive_spurious_resumes[_wd_ch_key] = _sr_tracker
                            if _sr_tracker["count"] > _WATCHDOG_SPURIOUS_RESUME_BAIL_AFTER:
                                print(f"[WATCHDOG] {os.path.basename(str(_anchor['file']))} on ch{ch} "
                                      f"has spuriously ended and been resumed in place "
                                      f"{_sr_tracker['count']} times in the last "
                                      f"{_WATCHDOG_SPURIOUS_RESUME_WINDOW_MS // 1000}s -- resuming in "
                                      f"place keeps re-triggering the same glitch, so dropping anchor "
                                      f"trust instead and letting the schedule do a full, clean re-tune "
                                      f"(same as a manual channel-away-and-back).")
                                _watchdog_consecutive_spurious_resumes.pop(_wd_ch_key, None)
                            else:
                                print(f"[WATCHDOG] {os.path.basename(str(_anchor['file']))} on ch{ch} "
                                      f"reported ended ({_elapsed:.2f}s since this attempt started) but is "
                                      f"only {_real_dur}s into its known {_known_dur}s runtime -- treating as "
                                      f"a spurious VLC state glitch (freeze/stall, not a real end) and "
                                      f"resuming the same file instead of advancing the schedule.")
                                _resume_spurious = True
                        elif _real_dur > 0 and _transient_blip:
                            print(f"[WATCHDOG] {os.path.basename(str(_anchor['file']))} on ch{ch} "
                                  f"ended after only {_elapsed:.2f}s (likely tuned in/surfed through near "
                                  f"its own end) -- advancing without correcting duration or marking it broken.")
                        elif _real_dur > 0:
                            print(f"[WATCHDOG] {os.path.basename(str(_anchor['file']))} on ch{ch} "
                                  f"ended abnormally (reason={_finish_reason}, elapsed-based guess={_real_dur}s, "
                                  f"known-good={_known_dur}s, elapsed={_elapsed:.2f}s) -- advancing WITHOUT correcting duration.")
                            try:
                                _last_attempt_reason[str(ch).zfill(2)] = (
                                    f"abnormal_end_duration_mismatch (attempt "
                                    f"{getattr(vlc_engine, '_current_attempt_id', None)}, "
                                    f"elapsed={_elapsed:.2f}s known={_known_dur}s)")
                                _mark_file_broken(_ch_entry, str(_anchor["file"]), reason="abnormal_end_duration_mismatch")
                            except Exception as e:
                                log.warning("WATCHDOG: _mark_file_broken (abnormal-ended) failed for ch%s: %s", ch, e)
                            try:
                                _wd_fail_root = media._drive_root_of(str(_anchor["file"]))
                            except Exception as _swallowed_error:
                                _log_swallowed("module: _wd_fail_root = media._drive_root_of(str(_anchor['file']))", _swallowed_error)
                                _wd_fail_root = None
                            if _wd_fail_root and _wd_fail_root in _unresponsive_drive_roots():
                                _station_confirmed_dead_drive[str(ch).zfill(2)] = _wd_fail_root
                                _remember_dead_drive_probe_file(_wd_fail_root, str(_anchor["file"]))
                                log.warning(
                                    "WATCHDOG: drive %s (channel %s) confirmed unresponsive -- "
                                    "channel will go straight to Static on its next load instead "
                                    "of continuing to cycle the schedule.",
                                    _wd_fail_root, ch,
                                )
                        if _finish_reason == "error":
                            try:
                                _last_attempt_reason[str(ch).zfill(2)] = (
                                    f"vlc_state_error (attempt "
                                    f"{getattr(vlc_engine, '_current_attempt_id', None)})")
                                _mark_file_broken(_ch_entry, str(_anchor["file"]), reason="vlc_state_error")
                            except Exception as e:
                                log.warning("WATCHDOG: _mark_file_broken failed for ch%s: %s", ch, e)
                        if _real_dur > 0 and not _resume_spurious:
                            _guard_key = "last_ended_commercial" if _anchor.get("mode") == "Commercial" else "just_ended_slot"

                            _skip_guard_arm = False
                            if _guard_key == "just_ended_slot":
                                try:
                                    _ended_show, _ended_eps = _get_show_episode_context(
                                        _ch_entry, _ab, str(_anchor["file"]))
                                    if _ended_show is not None and len(_ended_eps) <= 1:
                                        _skip_guard_arm = True
                                        print(f"[REPEAT-GUARD] ch{ch}: '{_ended_show}' has only "
                                              f"1 episode on hand -- skipping the 900s repeat-guard "
                                              f"hold, immediate repeat is correct here.")
                                except Exception as e:
                                    log.warning("WATCHDOG: episode-count check for repeat-guard "
                                                "exemption failed on ch%s: %s", ch, e)

                            if not _skip_guard_arm:
                                _ch_entry.setdefault("playback_log", {})[_guard_key] = {
                                    "file": os.path.normpath(str(_anchor["file"])).lower(),
                                    "block": _ab,
                                    "armed_ts": _now_w.timestamp(),
                                }
                    elif _anchor.get("file"):
                        print(f"[WATCHDOG] Stale/mismatched anchor ({os.path.basename(str(_anchor.get('file','')))}) "
                              f"on ch{ch} ignored -- not the file VLC just ended; advancing via fresh schedule instead.")

                    if _resume_spurious:
                        _resume_pos = _anchor.get("seek_offset", 0) + _elapsed
                        _resume_ok = False

                        _resume_ch_key = str(ch).zfill(2)
                        _resume_anchor_snap = dict(_anchor)

                        def _resume_on_confirmed(success, attempt_id, deferred,
                                                  _ch_key=_resume_ch_key,
                                                  _a=_resume_anchor_snap, _pos=_resume_pos):
                            if (vlc_engine is None
                                    or getattr(vlc_engine, "_current_attempt_id", None) != attempt_id):
                                return
                            if success:
                                _resumed_anchor = dict(_a)
                                _resumed_anchor["wall_start"] = broadcast_clock.seconds_since_midnight()
                                _resumed_anchor["seek_offset"] = _pos
                                _resumed_anchor["anchor_written_at"] = broadcast_clock.now().timestamp()
                                if db is not None:
                                    db.channels_db.setdefault(_ch_key, {})["playback_anchor"] = _resumed_anchor
                                    try:
                                        db.save_playback_anchor()
                                    except Exception as e:
                                        log.warning("WATCHDOG: failed to persist resumed anchor for ch%s: %s", _ch_key, e)
                                app_state["is_playing_video"] = True
                            else:
                                log.warning(
                                    "WATCHDOG: spurious-blip resume for ch%s did not open "
                                    "(deferred=%s) -- clearing anchor so the next pass "
                                    "recomputes from the schedule instead of trusting a file "
                                    "that was never actually reopened.", _ch_key, deferred,
                                )
                                if db is not None:
                                    db.channels_db.setdefault(_ch_key, {})["playback_anchor"] = {}
                                if app_state.get("_live_playback_channel") == _ch_key:
                                    app_state["is_playing_video"] = False

                        try:
                            # WARNING: this continues a file VLC never stopped playing; do not force a mute or arm _video_pending_unmute.
                            app_state["last_video_play_started_at"] = pygame.time.get_ticks()
                            _resume_ok = vlc_engine.play_file_segmented(
                                str(_anchor["file"]), _resume_pos,
                                gain=_lookup_file_gain(_resume_ch_key, str(_anchor["file"])),
                                defer_unmute=False,
                                on_confirmed=_resume_on_confirmed,
                                follow_clock=True,
                            )
                        except Exception as e:
                            log.warning("WATCHDOG: spurious-blip resume failed for ch%s: %s", ch, e)
                        if _resume_ok is not False:
                            _skip_advance_this_frame = True
                    else:
                        _ch_entry["playback_anchor"] = {}

            if _skip_advance_this_frame:
                pass
            elif is_video_finished and _watchdog_consecutive_errors.get(_wd_ch_key, 0) >= _WATCHDOG_ERROR_BAIL_AFTER:
                log.warning(
                    "WATCHDOG: ch%s hit %d consecutive VLC State.Error "
                    "finishes -- abandoning auto-advance for now instead "
                    "of continuing to cycle through the schedule.",
                    ch, _watchdog_consecutive_errors.get(_wd_ch_key, 0),
                )
                if db is not None:
                    _err_file = current_playback_state.get("file", "")
                    if _err_file:
                        _register_channel_playback_failure(
                            _wd_ch_key, _err_file,
                            duration=current_playback_state.get("duration"),
                            block=current_playback_state.get("block"),
                        )
            else:
                change_channel(ch, is_surfing=False, internal_advance=True, snap_internal_advance=is_video_finished)
                current_playback_state = calculate_slotted_playback_state(ch, snap_internal_advance=is_video_finished)

    if (ch not in ("03", "04")
            and current_playback_state["mode"] in ("Video", "Commercial")
            and app_state.get("is_playing_video", False)
            and vlc_engine is not None
            and getattr(vlc_engine, "ready_flag", False)
            and current_playback_state.get("file")
            and not _switch_pending
            and not _open_confirm_pending
            and vlc_engine.player.get_state() not in (vlc.State.Opening, vlc.State.Buffering)
            and pygame.time.get_ticks() - app_state.get("last_video_play_started_at", 0) > 2000):
        try:
            current_media = vlc_engine.player.get_media()
            loaded_path = ""
            if current_media:
                from urllib.parse import unquote
                loaded_path = os.path.normpath(unquote(current_media.get_mrl().replace("file:///", ""))).lower()
            sched_path = os.path.normpath(current_playback_state["file"]).lower()
            if loaded_path and loaded_path != sched_path:
                print(f"[SCHEDULE] Mid-stream content change on ch{ch}: "
                      f"{os.path.basename(loaded_path)} -> {os.path.basename(sched_path)}")

                _resume_seek = current_playback_state.get("seek", 0)
                if db is not None:
                    _ch_entry_ms = db.channels_db.get(str(ch).zfill(2), {})
                    _plog_ms = _ch_entry_ms.setdefault("playback_log", {})
                    _old_anchor_ms = _ch_entry_ms.get("playback_anchor", {})
                    if bool(_old_anchor_ms.get("interior_cut")) and _old_anchor_ms.get("file"):
                        try:
                            _leave_pos_ms = vlc_engine.player.get_time()
                        except Exception as _swallowed_error:
                            _log_swallowed("module: _leave_pos_ms = vlc_engine.player.get_time()", _swallowed_error)
                            _leave_pos_ms = None
                        _seg_start_s = float(_old_anchor_ms.get("seek_offset", 0))
                        if (_leave_pos_ms is not None and _leave_pos_ms >= 0
                                and (_leave_pos_ms / 1000.0) > _seg_start_s):
                            _plog_ms["interior_break_pause"] = {
                                "file":     os.path.normpath(str(_old_anchor_ms["file"])).lower(),
                                "seek":     _leave_pos_ms / 1000.0,
                                "armed_ts": broadcast_clock.now().timestamp(),
                            }
                            print(f"[INTERIOR-BREAK] ch{ch}: paused "
                                  f"'{os.path.basename(str(_old_anchor_ms['file']))}' at real "
                                  f"position {_leave_pos_ms / 1000.0:.3f}s before cutting to break.")
                        elif _leave_pos_ms is not None and _leave_pos_ms >= 0:
                            print(f"[INTERIOR-BREAK] ch{ch}: discarded a bad leave-position "
                                  f"capture ({_leave_pos_ms / 1000.0:.3f}s, segment started at "
                                  f"{_seg_start_s:.3f}s) -- keeping the wall-clock resume instead.")
                            _plog_ms.pop("interior_break_pause", None)

                    _pause_rec = _plog_ms.get("interior_break_pause")
                    if (_pause_rec and _pause_rec.get("file") == sched_path
                            and broadcast_clock.now().timestamp() - _pause_rec.get("armed_ts", 0) < 3600):
                        _resume_seek = _pause_rec["seek"]
                        print(f"[INTERIOR-BREAK] ch{ch}: resuming "
                              f"'{os.path.basename(sched_path)}' from real pause point "
                              f"{_resume_seek}s instead of the schedule's fixed offset.")
                        _plog_ms.pop("interior_break_pause", None)

                try:
                    vlc_engine.player.audio_set_mute(True)
                except Exception as _swallowed_error:
                    _log_swallowed("main script: vlc_engine.player.audio_set_mute(True)", _swallowed_error)
                app_state["_video_pending_unmute"] = True
                app_state["_video_audio_hold_until"] = (
                    pygame.time.get_ticks() + SAME_CHANNEL_AUDIO_HOLD_MS
                )
                _hold_picture_through_advance()
                _mute_guard_log(
                    "ARM (mid-stream content change)",
                    ch=ch,
                    filepath=current_playback_state["file"],
                )
                _ms_ch_key = str(ch).zfill(2)
                _ms_snap = dict(current_playback_state)
                _ms_resume_seek = _resume_seek

                def _ms_on_confirmed(success, attempt_id, deferred,
                                      _ch_key=_ms_ch_key, _s=_ms_snap, _seek=_ms_resume_seek):
                    if success:
                        _confirm_playback_started(
                            _ch_key, attempt_id, _s.get("file"),
                            _seek, _s.get("seek_slot_offset", 0),
                            _s.get("duration", 1800), _s.get("mode", "Video"),
                            _s.get("block", "Morning"), _s.get("interior_cut", False),
                            deferred,
                        )
                    else:
                        _confirm_playback_failed(_ch_key, attempt_id, _s.get("file"), deferred,
                                                  reason="mid_stream_content_change_open_failed")

                app_state["last_video_play_started_at"] = pygame.time.get_ticks()
                _ms_file = current_playback_state["file"]
                _ms_gain = _lookup_file_gain(ch, _ms_file)

                def _ms_open(_file=_ms_file, _seek=_resume_seek, _gain=_ms_gain, _cb=_ms_on_confirmed):
                    vlc_engine.play_file_segmented(_file, _seek, gain=_gain, defer_unmute=True, on_confirmed=_cb, follow_clock=True)
                    vlc_engine.set_volume(db.config["global_volume"], db.config.get("is_muted", False))
                    try:
                        vlc_engine.player.audio_set_mute(True)
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: vlc_engine.player.audio_set_mute(True)", _swallowed_error)

                # WARNING: the next item of a channel on air opens on the content-activate thread like a tune; opened here its picture-box wait froze the picture 2 to 4 s mid-break (owner log 2026-11-02 21:59, N5).
                _dispatch_content_activation(_ms_open)
        except Exception as e:
            log.warning(f"[SCHEDULE] Mid-stream resync check failed: {e}")

    try:
        _lnp_now = broadcast_clock.now().replace(tzinfo=None)
        _lnp_file = current_playback_state.get("file", "")
        _lnp_seek = current_playback_state.get("seek", 0)
        _lnp_mode = current_playback_state.get("mode", "")
        if (str(app_state.get("current_channel", "")).zfill(2) == str(ch).zfill(2)
                and app_state.get("is_playing_video", False)
                and vlc is not None and vlc_engine is not None
                and getattr(vlc_engine, "player", None) is not None
                and _is_drive_responsive(_lnp_file)):
            try:
                _vst = vlc_engine.player.get_state()
                if _vst not in (vlc.State.Ended, vlc.State.Stopped, vlc.State.Error):
                    _vm = vlc_engine.player.get_media()
                    if _vm:
                        from urllib.parse import unquote as _unq_lnp
                        _real = os.path.normpath(_unq_lnp(_vm.get_mrl().replace("file:///", "")))
                        if _real and _cached_path_exists(_real):
                            _lnp_file = _real
                            _lnp_mode = (
                                "Commercial"
                                if _is_commercial_file_for_channel(ch, _real)
                                else "Video"
                            )
                            _tms = vlc_engine.player.get_time()
                            if _tms is not None and _tms >= 0:
                                _lnp_seek = _tms / 1000.0
            except Exception as _swallowed_error:
                _log_swallowed("main script: _vst = vlc_engine.player.get_state()", _swallowed_error)
        _lnp_dur = current_playback_state.get("duration", 0)
        try:
            _rc_dur, _rc_kind = media.read_track_duration(_lnp_file, 0)
            if _rc_kind == media.DURATION_MEASURED and _rc_dur:
                _lnp_dur = int(_rc_dur)
        except Exception as _swallowed_error:
            _log_swallowed("main script: _rc_dur, _rc_kind = media.read_track_duration(_lnp_file, 0) ...", _swallowed_error)
        _lnp_wall_seconds = (
            _lnp_now.hour * 3600 + _lnp_now.minute * 60 + _lnp_now.second
            + _lnp_now.microsecond / 1_000_000.0
        )
        app_state["live_now_playing"] = {
            "channel":  str(ch).zfill(2),
            "file":     _lnp_file,
            "mode":     _lnp_mode,
            "seek":     _lnp_seek,
            "duration": _lnp_dur,
            "block":    current_playback_state.get("block", ""),
            "_resolved_clock_seconds": _lnp_wall_seconds,
        }
    except Exception as _swallowed_error:
        _log_swallowed("main script: _lnp_now = broadcast_clock.now().replace(tzinfo=None)", _swallowed_error)

    if w_w < 100 or w_h < 100:
        # WARNING: not pure black; (0, 0, 0) is the game-overlay transparency key.
        screen.fill(COLOR_SCREEN_BLACK)
        w_w, w_h = 100, 100

    _prof_mark("stall_detect")

    # ========================================================================
    # SECTION: Video render (TV channels)
    # ========================================================================

    if _surf_quiet and ch not in ("03", "04"):
        if _configured_transition_style() == "static":
            _render_transition_static(screen, _full_window_rect)
        else:
            screen.fill(COLOR_TRANSITION_GREY, _full_window_rect)
    elif ch != "04":
        if ch == "03":
            # WARNING: a file picker left open by an earlier settings action must not paint over this frame or consume DVD navigation keys on the next one.
            _dvd_layer_active = (
                game_deck is not None
                and (
                    getattr(game_deck, "mode", "") == "DVD_PLAYER"
                    or getattr(game_deck, "dvd_playback_active", False)
                )
            )
            if _dvd_layer_active and app_state.get("file_explorer_active", False):
                log.warning("[CH03/DVD] Closing stale file explorer before DVD frame render.")
                _fe_finish_close()

            if vlc_engine is not None:
                try:
                    if vlc_engine.player.is_playing():
                        vlc_engine.stop()
                except Exception as e: log.warning(f"[PLAYBACK] vlc stop failed: {e}")
            if pygame.mixer.music.get_busy():
                pygame.mixer.music.stop()
            
            # WARNING: not pure black; (0, 0, 0) is the game-overlay transparency key.
            screen.fill(_video_bar_color())
            
            if game_deck is not None:
                game_deck.set_theme(active_theme.get("ui", DEFAULT_THEME["ui"]))
                crt_cfg = {}
                if db is not None:
                    crt_cfg = {
                        "brightness": db.config.get("brightness", 50),
                        "contrast":   db.config.get("contrast",   50),
                        "saturation": db.config.get("color",      50),
                        "sharpness":  db.config.get("sharpness",  50),
                        "hue_shift":  db.config.get("tint",       50),
                    }
                try:
                    game_deck.leave_list_of_failed_drive(set(_failed_drive_roots()))
                except Exception as _e:
                    _log_warn_throttled("deck_list_drive_failure", "[DRIVE HEALTH] leaving the list of a failed drive failed: %s", _e)
                _deck_render_rect = (
                    _compute_dvd_content_rect(*screen.get_size()) if _dvd_layer_active
                    else _compute_game_content_rect(*screen.get_size())
                )
                if game_deck.emulator_loading:
                    game_deck._libretro_tick_loading()
                    game_deck.render(screen, _deck_render_rect, crt_cfg=crt_cfg)
                elif (game_deck.mode == "GAME"
                      and getattr(game_deck, "_libretro_core", None) is not None):
                    _menu_overlay_open = (
                        app_state.get("show_menu", False)
                        or app_state.get("show_splash", False)
                        or app_state.get("show_quit_confirm", False)
                        or app_state.get("show_restart_confirm", False)
                    )
                    game_deck.render_libretro(screen, _deck_render_rect, crt_cfg=crt_cfg,
                                               overlay_open=_menu_overlay_open)
                else:
                    game_deck.render(screen, _deck_render_rect, crt_cfg=crt_cfg)
            else:
                font_loading = _cached_sys_font("Courier New", 24, bold=True)
                theme_color = active_theme.get("ui", DEFAULT_THEME["ui"])
                lbl = font_loading.render("Game frontend unavailable", True, theme_color)
                screen.blit(lbl, (content_rect.centerx - lbl.get_width() // 2, content_rect.centery - 12))
        elif current_playback_state["mode"] == "Video":
            _transition_now = pygame.time.get_ticks()
            if _transition_now < app_state.get("channel_switch_static_until", 0):
                _render_transition_static(screen, _full_window_rect)
            elif _transition_now < app_state.get("channel_switch_black_until", 0):
                        pass
            elif pygame.time.get_ticks() < app_state.get("_video_audio_hold_until", 0):
                if _loudness_hold_last_frame_active():
                    _blit_last_video_frame(screen, *_screen_mode_boxed_last_frame_rect(content_rect, w_w, w_h), context="fullscreen", outer_rect=content_rect)
            elif (not app_state.get("is_playing_video", False)
                    and (str(ch).zfill(2) in _channel_playback_failures
                         or str(ch).zfill(2) in _station_confirmed_dead_drive)):
                _render_transition_static(screen, _full_window_rect)
                _draw_channel_failure_message(screen, _full_window_rect, str(ch).zfill(2))
            elif vlc_engine is not None:
                try:
                    _vd_t0 = time.perf_counter()
                    vlc_bytes = vlc_engine.get_display_frame()
                    if vlc_bytes is not None and len(vlc_bytes) >= vlc_engine.buf_size:
                        _note_fresh_live_video_frame(ch)
                        _vd_t1 = time.perf_counter()
                        video_surf = pygame.image.frombuffer(vlc_bytes, (vlc_engine.width, vlc_engine.height), "BGRA")
                        video_surf = _true_content_surf(video_surf, vlc_engine)
                        _picture_box_set_content(current_playback_state.get("file", ""))
                        video_surf, _pb_aspect = _apply_picture_box_crop(video_surf)
                        if video_surf.get_width() > 0 and video_surf.get_height() > 0:
                            
                            # WARNING: the Video tab's adjustments are drawn by VLC itself (_picture_adjust_media_options); adding the CPU pass here would apply them twice.
                            effected_surf = video_surf
                            _vd_t2 = time.perf_counter()

                            _pan_scan_set_content(current_playback_state.get("file", ""))
                            _video_sa = _snap_standard_aspect(_pb_aspect or (video_surf.get_width() / video_surf.get_height()))
                            _video_target_rect = _video_screen_mode_rect(content_rect, w_w, w_h, source_aspect=_video_sa)
                            if (_video_target_rect.width < content_rect.width
                                    or _video_target_rect.height < content_rect.height):
                                screen.fill(_video_bar_color(), content_rect)
                            _real_blit_geom = {}
                            _vd_t3 = time.perf_counter()
                            _draw_video_picture(screen, effected_surf, _video_target_rect,
                                                mode=_bezel_video_fit_mode(),
                                                analysis_surf=video_surf, geom_out=_real_blit_geom,
                                                pixel_aspect=_video_pixel_aspect(w_w, w_h, _video_sa),
                                                fit_aspect=_video_sa)
                            _vd_t4 = time.perf_counter()
                            _rbg_key = (tuple(content_rect), tuple(_video_target_rect),
                                        video_surf.get_size(), tuple(sorted(_real_blit_geom.items())) if _real_blit_geom else None)
                            if _real_video_blit_log_state.get("key") != _rbg_key:
                                _real_video_blit_log_state["key"] = _rbg_key
                                log.info("[REAL VIDEO BLIT] content_rect=%s video_target_rect=%s true_content_surf=%sx%s "
                                         "actual_draw=(%s,%s,%s,%s) actual_draw_aspect=%s target_rect_aspect=%.4f",
                                         tuple(content_rect), tuple(_video_target_rect), video_surf.get_width(), video_surf.get_height(),
                                         _real_blit_geom.get("dest_x"), _real_blit_geom.get("dest_y"),
                                         _real_blit_geom.get("draw_w"), _real_blit_geom.get("draw_h"),
                                         ("%.4f" % (_real_blit_geom["draw_w"] / _real_blit_geom["draw_h"])
                                          if _real_blit_geom.get("draw_w") and _real_blit_geom.get("draw_h") else None),
                                         _video_target_rect.width / _video_target_rect.height if _video_target_rect.height else 0)
                            _store_last_video_frame(effected_surf, raw_surf=video_surf, context="fullscreen", fit_aspect=_video_sa)
                            _note_video_draw_timing(_vd_t1 - _vd_t0, _vd_t2 - _vd_t1, _vd_t3 - _vd_t2, _vd_t4 - _vd_t3,
                                                    time.perf_counter() - _vd_t4, current_playback_state.get("mode", ""))
                            app_state["_video_painted_this_frame"] = True
                        else:
                            if not _blit_last_video_frame(screen, *_screen_mode_boxed_last_frame_rect(content_rect, w_w, w_h), context="fullscreen", outer_rect=content_rect):
                                screen.fill(COLOR_TRANSITION_GREY)
                    else:
                        if not _blit_last_video_frame(screen, *_screen_mode_boxed_last_frame_rect(content_rect, w_w, w_h), context="fullscreen", outer_rect=content_rect):
                            screen.fill(COLOR_TRANSITION_GREY)
                except Exception as _swallowed_error:
                    _log_swallowed("module: vlc_bytes = vlc_engine.get_display_frame()", _swallowed_error)
                    if not _blit_last_video_frame(screen, *_screen_mode_boxed_last_frame_rect(content_rect, w_w, w_h), context="fullscreen", outer_rect=content_rect):
                        screen.fill(COLOR_TRANSITION_GREY)

            else:
                screen.fill(COLOR_TRANSITION_GREY)
                
        elif current_playback_state["mode"] == "Static":
            # WARNING: the grey screen is still Static on air, so its noise keeps playing; stopping it here fought the play in the Static sound section every frame and cut the sound.
            _draw_static_channel(screen, _full_window_rect, ("live", str(ch)), reason=current_playback_state.get("reason"))
            _static_reason = current_playback_state.get("reason")
            if (_static_reason and _static_reason not in SILENT_STATIC_REASONS
                    and _static_banner_ready(("live", str(ch)), _static_reason)):
                _sf_detail = current_playback_state.get(
                    "reason_detail",
                    "playback unavailable for this channel")
                _sf_prefix = STATIC_FALLBACK_BANNER_PREFIX.get(_static_reason, "PLAYBACK FAILED")
                _report_missing_media((str(ch), _static_reason, _sf_detail),
                                       f"{_sf_prefix} — {_sf_detail}")

        elif current_playback_state["mode"] == "Visualizer" and visualizer_deck is not None:
            target_file = current_playback_state.get("file", "")
            target_seek = current_playback_state.get("seek", 0)
            track_duration = current_playback_state.get("duration", 210)
            ch_conf = db.channels_db.get(str(ch).zfill(2), {}) if db else {}
            
            active_track = app_state.get("active_music_track_file", "")
            last_scheduled_vis_track = app_state.get("last_scheduled_vis_track", {}).get(str(ch).zfill(2), "")
            is_new_scheduled_track = last_scheduled_vis_track != target_file
            
            display_track_path = active_track if active_track else target_file
            
            if not display_track_path and db and "Music Tracks" in ch_conf.get("schedules", {}):
                tracks_list = ch_conf["schedules"]["Music Tracks"]
                if tracks_list:
                    first_track = tracks_list[0]
                    display_track_path = first_track.get("path", "") if isinstance(first_track, dict) else str(first_track)
            

    elif ch == "04":
        hl_ch = str(app_state.get("highlighted_guide_channel", "05")).zfill(2)
        _previous_preview_ch = str(app_state.get("_live_playback_channel", "")).zfill(2)
        if _previous_preview_ch and _previous_preview_ch != hl_ch:
            _capture_guide_preview_position(_previous_preview_ch)
        hl_state = _get_guide_hl_playback_state(hl_ch)
        # WARNING: while browsing the guide the current channel is 04, so a playing show could otherwise be painted OFF-AIR until a time-window rebuild lined up.
        _guide_now = broadcast_clock.now().replace(tzinfo=None)
        _guide_now_seconds = (
            _guide_now.hour * 3600 + _guide_now.minute * 60
            + _guide_now.second + _guide_now.microsecond / 1_000_000.0
        )
        app_state["guide_preview_live_state"] = {
            "channel": hl_ch,
            "mode": hl_state.get("mode", "Static"),
            "file": hl_state.get("file", ""),
            "seek": hl_state.get("seek", 0),
            "duration": hl_state.get("duration", 0),
            "block": hl_state.get("block", ""),
            "_resolved_clock_seconds": _guide_now_seconds,
        }

        if hl_state["mode"] in ("Video", "Commercial") and vlc_engine is not None:
            try:
                _guide_preview_settled = pygame.time.get_ticks() >= app_state.get("guide_preview_settle_until", 0)

                _guide_load_in_flight = app_state.get("guide_preview_loading", False)
                if _guide_load_in_flight:
                    if vlc_engine.has_pending_frame():
                        _guide_load_in_flight = False
                        app_state["guide_preview_loading"] = False
                    else:
                        _load_started = app_state.get("guide_preview_load_started_ms", 0)
                        if pygame.time.get_ticks() - _load_started > GUIDE_PREVIEW_LOAD_TIMEOUT_MS:
                            _guide_load_in_flight = False
                            app_state["guide_preview_loading"] = False
                            app_state["loaded_preview_path_cache"] = ""

                if (_guide_preview_settled
                        and not _guide_load_in_flight
                        and app_state.get("loaded_preview_path_cache", "") != hl_state["file"]):
                    _start_guide_preview_load(hl_ch, hl_state)
            except Exception as _swallowed_error:
                _log_swallowed("main script: _guide_preview_settled = pygame.time.get_ticks() >= app_state.get('guide_preview_settle...", _swallowed_error)

        render_tv_guide_async(screen, app_state, db, active_theme,
                               target_rect=pygame.Rect(0, 0, *screen.get_size()))

        px, py, pw, ph = app_state.get("guide_preview_bounds", (w_w // 2 - 400, 15, 800, 450))

        _guide_transition_style = _configured_transition_style()
        _preview_base_color = (0, 0, 0) if _guide_transition_style == "black" else COLOR_SCREEN_BLACK
        pygame.draw.rect(screen, _preview_base_color, (px, py, pw, ph))

        _now_ch04 = pygame.time.get_ticks()
        _ch04_shield_active = (
            _now_ch04 < app_state.get("channel_switch_black_until", 0)
            or _now_ch04 < app_state.get("guide_entry_static_suppress_until", 0)
            or (_guide_transition_style == "static"
                and _now_ch04 < app_state.get("guide_preview_static_until", 0))
            or (_guide_transition_style == "black"
                and _now_ch04 < app_state.get("guide_preview_black_until", 0))
        )

        _ch04_preview_static_visual_active = (
            _now_ch04 < app_state.get("channel_switch_black_until", 0)
            or (_guide_transition_style == "static"
                and _now_ch04 < app_state.get("guide_preview_static_until", 0))
        )

        if hl_state["mode"] in ("Video", "Commercial") and vlc_engine is not None:
            try:
                if _ch04_preview_static_visual_active and _guide_transition_style == "static":
                    _render_transition_static(screen, pygame.Rect(px, py, pw, ph), target_aspect=16.0 / 9.0)

                if not _ch04_shield_active:
                    if pygame.mixer.music.get_busy(): pygame.mixer.music.stop()

                    _preview_showed_real_picture = False

                    vlc_bytes = vlc_engine.get_display_frame()
                    _preview_load_matches_highlight = (
                        app_state.get("loaded_preview_path_cache", "") == hl_state["file"])
                    if vlc_bytes and _preview_load_matches_highlight and _guide_preview_box_hold(hl_state["file"]):
                        pass
                    elif vlc_bytes and _preview_load_matches_highlight:
                        _stop_transition_static()
                        _lift_buffering_mute(hl_ch, "guide-preview-first-frame")
                        video_surf = pygame.image.frombuffer(vlc_bytes, (vlc_engine.width, vlc_engine.height), "BGRA")
                        video_surf = _true_content_surf(video_surf, vlc_engine)
                        # WARNING: strip the file's own baked-in bars (picture-box scan result), as full-screen playback does, or the preview shows raw bars the channel itself does not.
                        _picture_box_set_content(hl_state["file"])
                        video_surf, _pv_pb_aspect = _apply_picture_box_crop(video_surf)
                        _pv_fit_aspect = _snap_standard_aspect(
                            _pv_pb_aspect or (video_surf.get_width() / video_surf.get_height()))
                        processed_surf = video_surf
                        _draw_video_picture(
                            screen, processed_surf, pygame.Rect(px, py, pw, ph),
                            mode=_bezel_video_fit_mode(),
                            analysis_surf=video_surf, fit_aspect=_pv_fit_aspect)
                        _last_guide_preview_picture_rect = _last_screen_mode_picture_rect
                        _store_last_video_frame(processed_surf, context="preview", fit_aspect=_pv_fit_aspect)

                        if db is not None and db.config.get("fake_static_noise_enabled", False):
                            try:
                                _hl_ch_n = int(hl_ch)
                            except (TypeError, ValueError) as _swallowed_error:
                                _log_swallowed("module: _hl_ch_n = int(hl_ch)", _swallowed_error)
                                _hl_ch_n = 0
                            if hl_ch not in ("03", "04") and 5 <= _hl_ch_n <= 44:
                                _apply_static_noise_effect(screen, pygame.Rect(px, py, pw, ph), hl_ch)

                        if db is not None and db.config.get("fake_reception_lines_enabled", False):
                            if _is_live_tv_broadcast_channel(hl_ch):
                                _apply_reception_lines_effect(screen, pygame.Rect(px, py, pw, ph))

                        _preview_showed_real_picture = True
                    else:
                        if _blit_last_video_frame(screen, px, py, pw, ph, apply_screen_mode=True, context="preview"):
                            _stop_transition_static()
                            _lift_buffering_mute(hl_ch, "guide-preview-bridge-frame")
                            _preview_showed_real_picture = True
                        else:
                            _guide_load_started_ms = app_state.get("guide_preview_load_started_ms", 0)
                            _guide_load_gave_up = (
                                app_state.get("guide_preview_loading", False)
                                and _guide_load_started_ms > 0
                                and (pygame.time.get_ticks() - _guide_load_started_ms) > GUIDE_PREVIEW_LOAD_TIMEOUT_MS
                            )
                            if _guide_load_gave_up:
                                _lift_buffering_mute(hl_ch, "guide-preview-shield-end")
                            _guide_transition_style = _configured_transition_style()
                            _hl_ch_confirmed_failed = (
                                hl_ch in _channel_playback_failures
                                or hl_ch in _station_confirmed_dead_drive
                            )
                            if _hl_ch_confirmed_failed:
                                _render_transition_static(screen, pygame.Rect(px, py, pw, ph), target_aspect=16.0 / 9.0)
                            elif _guide_transition_style == "static":
                                if _ch04_preview_static_visual_active:
                                    _render_transition_static(
                                        screen, pygame.Rect(px, py, pw, ph), target_aspect=16.0 / 9.0)
                                else:
                                    _stop_transition_static()
                                    screen.fill(COLOR_SCREEN_BLACK, (px, py, pw, ph))
                            else:
                                _stop_transition_static()
                                screen.fill(COLOR_TRANSITION_GREY, (px, py, pw, ph))

                            if _hl_ch_confirmed_failed:
                                _draw_channel_failure_message(
                                    screen, pygame.Rect(px, py, pw, ph), hl_ch,
                                    scale=0.5)

                    if (_preview_showed_real_picture
                            and db is not None and db.channels_db.get(str(app_state.get("current_channel", "")).zfill(2), {}).get("watermark_enabled", False)
                            and _is_live_tv_broadcast_channel(hl_ch)
                            and hl_state.get("mode") != "Commercial"):
                        _wm_preview_bounds = _watermark_bounds_rect_preview(
                            pygame.Rect(px, py, pw, ph))
                        _draw_watermark(screen, bounds_rect=_wm_preview_bounds, state_key="preview")
            except Exception as _swallowed_error:
                _log_swallowed("module: if _ch04_preview_static_visual_active and _guide_transition_style =...", _swallowed_error)
                if not _ch04_shield_active:
                    _stop_transition_static()
                    if not _blit_last_video_frame(screen, px, py, pw, ph, apply_screen_mode=True, context="preview"):
                        _guide_transition_style = _configured_transition_style()
                        _fallback_color = COLOR_SCREEN_BLACK if _guide_transition_style == "static" else COLOR_TRANSITION_GREY
                        screen.fill(_fallback_color, (px, py, pw, ph))

        elif hl_state["mode"] == "Visualizer" and visualizer_deck is not None and not _ch04_shield_active:
            try:
                if app_state.get("loaded_preview_path_cache", "") != "":
                    if vlc_engine is not None: vlc_engine.stop()
                    app_state["loaded_preview_path_cache"] = ""

                # WARNING: do not ask its live state for a music track; that state is the guide itself or a stale cache, and pygame.mixer.music is shared with the live visualizer.
                target_file = hl_state.get("file", "")
                target_seek_seconds = hl_state.get("seek", 0)
                track_duration_max = hl_state.get("duration", 210)
                _gain_ch_key = hl_ch
                
                guide_preview_track = app_state.get("guide_preview_music_track", "")

                _gp_vis_dead_root = _visualizer_confirmed_dead_drive.get(hl_ch)
                if _gp_vis_dead_root is not None and _drive_confirmed_recovered(_gp_vis_dead_root):
                    _visualizer_confirmed_dead_drive.pop(hl_ch, None)
                    _gp_vis_dead_root = None
                _gp_vis_confirmed_failed = _gp_vis_dead_root is not None or hl_ch in _channel_playback_failures

                _gp_vis_load_failed = False

                if _gp_vis_confirmed_failed:
                    if app_state.get("music_owner") == "guide_preview":
                        pygame.mixer.Channel(1).stop()
                        if pygame.mixer.music.get_busy():
                            pygame.mixer.music.stop()
                        app_state["music_owner"] = ""
                        app_state["guide_preview_music_track"] = ""
                elif target_file and (
                        app_state.get("music_owner") != "guide_preview"
                        or guide_preview_track != target_file):
                    _gp_load_t0 = time.monotonic()
                    pygame.mixer.Channel(1).stop()
                    if pygame.mixer.music.get_busy():
                        pygame.mixer.music.stop()
                    
                    try:
                        pygame.mixer.music.unload()
                    except Exception as e: log.warning(f"[GUIDE PREVIEW] music unload failed: {e}")

                    try:
                        pygame.mixer.music.load(target_file)
                    except Exception as load_err:
                        log.warning(f"[GUIDE PREVIEW] Music load failed for {target_file}: {load_err}")
                        _register_channel_playback_failure(hl_ch, target_file)
                        try:
                            _fail_root = media._drive_root_of(target_file)
                        except Exception as _swallowed_error:
                            _log_swallowed("module: _fail_root = media._drive_root_of(target_file)", _swallowed_error)
                            _fail_root = None
                        if _fail_root:
                            _visualizer_confirmed_dead_drive[hl_ch] = _fail_root
                            _remember_dead_drive_probe_file(_fail_root, target_file)
                        app_state["music_owner"] = ""
                        app_state["guide_preview_music_track"] = ""
                        _gp_vis_load_failed = True
                    else:
                        _static_sound_stop("guide preview: a visualizer channel's music loaded")
                        app_state["active_music_gain"] = _lookup_file_gain(_gain_ch_key, target_file)
                        pygame.mixer.music.set_volume(
                            _effective_audio_gain(min_db=STACKED_GAIN_MIN_DB)
                            * MUSIC_GAIN
                            * _effective_loudness_gain(app_state["active_music_gain"])
                        )

                        safe_seek = max(0.0, min(float(target_seek_seconds) + (time.monotonic() - _gp_load_t0), float(track_duration_max) - 1.0))
                        if _start_visualizer_music(target_file, safe_seek) is False:
                            app_state["guide_preview_music_track"] = ""
                            app_state["music_owner"] = ""
                        else:
                            app_state["guide_preview_music_track"] = target_file
                            app_state["music_owner"] = "guide_preview"
                            app_state["vis_card_timer"] = pygame.time.get_ticks() + 15000

                if _gp_vis_confirmed_failed:
                    _render_transition_static(screen, pygame.Rect(px, py, pw, ph), target_aspect=16.0 / 9.0)
                    _draw_channel_failure_message(
                        screen, pygame.Rect(px, py, pw, ph), hl_ch, scale=0.5)
                else:
                    mini = pygame.Surface((pw, ph))
                    # WARNING: not pure black; (0, 0, 0) is the game-overlay transparency key.
                    mini.fill(COLOR_SCREEN_BLACK)

                    h_ch_info = db.channels_db.get(hl_ch, {})
                    preview_style = _get_channel_visualizer_style(h_ch_info)

                    if preview_style != "Random":
                        preview_render_style = preview_style
                    else:
                        _last_sched_by_ch_prev = app_state.setdefault("last_scheduled_vis_track", {})
                        _prev_track = hl_state.get("file", "")
                        if _last_sched_by_ch_prev.get(hl_ch, "") != _prev_track or hl_ch not in visualizer_deck.style_by_channel:
                            _last_sched_by_ch_prev[hl_ch] = _prev_track
                            visualizer_deck.style_by_channel[hl_ch] = visualizer_deck.get_next_random_style()
                        preview_render_style = visualizer_deck.style_by_channel[hl_ch]

                    if pygame.mixer.music.get_busy():
                        p_amp = 45 + int(math.sin(pygame.time.get_ticks() * 0.045) * 45) + random.randint(0, 5)
                    else:
                        p_amp = 25 + int(math.sin(pygame.time.get_ticks() * 0.008) * 20)

                    _render_visualizer_frame(
                        mini,
                        active_theme,
                        p_amp,
                        style_override=preview_render_style,
                        reactive=_visualizer_reactive_frame(app_state.get("guide_preview_music_track")),
                    )

                    brightness, contrast, color_sat, sharpness, tint, fx_active = _get_video_effects(db)

                    # WARNING: with the graphics-card drawing step the Video tab settings are applied to the whole preview window there; doing them here too would apply them twice.
                    if fx_active and not _gpu_draws_picture_settings():
                        processed_mini = apply_video_effects(mini, brightness, contrast, color_sat, sharpness, tint)
                        screen.blit(processed_mini, (px, py))
                    else:
                        screen.blit(mini, (px, py))

                    if db is not None and db.config.get("fake_static_noise_enabled", False):
                        try:
                            _hl_ch_n_vis = int(hl_ch)
                        except (TypeError, ValueError) as _swallowed_error:
                            _log_swallowed("module: _hl_ch_n_vis = int(hl_ch)", _swallowed_error)
                            _hl_ch_n_vis = 0
                        if hl_ch not in ("03", "04") and 5 <= _hl_ch_n_vis <= 44:
                            _apply_static_noise_effect(screen, pygame.Rect(px, py, pw, ph), hl_ch)

                    if db is not None and db.config.get("fake_reception_lines_enabled", False):
                        if _is_live_tv_broadcast_channel(hl_ch):
                            _apply_reception_lines_effect(screen, pygame.Rect(px, py, pw, ph))

                    raw_filename = os.path.basename(_visualizer_title_path(hl_ch, target_file)).upper()
                    base_filename_str = os.path.splitext(raw_filename)[0]

                    import re
                    song_name_cleaned = re.sub(r'^[0-9\s\.\-_]+', '', base_filename_str)
                    song_name_cleaned = _clean_song_display_title(song_name_cleaned)
                    style_name_cleaned = preview_render_style.upper()

                    import colorsys as _preview_colorsys
                    _p_ui_hue = db.config.get("theme_ui_hue", 140) / 360.0 if db is not None else 140 / 360.0
                    _pr, _pg, _pb = _preview_colorsys.hsv_to_rgb(_p_ui_hue, 0.9, 1.0)
                    theme_ui_text_color = (int(_pr * 255), int(_pg * 255), int(_pb * 255))

                    _preview_shrink_x = (pw / w_w) if w_w > 0 else 1.0
                    _preview_shrink_y = (ph / w_h) if w_h > 0 else 1.0

                    _full_window_line_gap = max(2, round(w_h * 0.045))
                    _full_window_font_size = max(8, round(w_h * 0.026))
                    _preview_line_gap = max(1, round(_full_window_line_gap * _preview_shrink_y))
                    _preview_base_font_size = max(8, round(_full_window_font_size * _preview_shrink_y))

                    _PREVIEW_MARGIN_X_PX = max(1, round(48 * _preview_shrink_x))
                    _PREVIEW_MARGIN_Y_PX = max(1, round(64 * _preview_shrink_y))

                    _preview_max_text_width = max(10, pw - _PREVIEW_MARGIN_X_PX * 2)
                    f_card, _preview_fitted_size = _vis_card_font_that_fits(
                        (song_name_cleaned, f"VISUALIZER: {style_name_cleaned}"),
                        _preview_base_font_size, _preview_max_text_width)
                    _preview_line1_txt = _vis_card_truncate_to_width(
                        f_card, song_name_cleaned, _preview_max_text_width)
                    _preview_line2_txt = _vis_card_truncate_to_width(
                        f_card, f"VISUALIZER: {style_name_cleaned}", _preview_max_text_width)

                    lbl_s1 = f_card.render(_preview_line1_txt, True, theme_ui_text_color)
                    lbl_s2 = f_card.render(_preview_line2_txt, True, theme_ui_text_color)

                    _preview_right = px + pw
                    _line1_x = min(px + _PREVIEW_MARGIN_X_PX, _preview_right - lbl_s1.get_width())
                    _line2_x = min(px + _PREVIEW_MARGIN_X_PX, _preview_right - lbl_s2.get_width())
                    _line1_y = py + _PREVIEW_MARGIN_Y_PX
                    _line2_y = _line1_y + _preview_line_gap
                    screen.blit(lbl_s1, (_line1_x, _line1_y))
                    screen.blit(lbl_s2, (_line2_x, _line2_y))
            except Exception as preview_err:
                log.warning(f"[SYNC ENGINE ERROR] {preview_err}")
                screen.fill(COLOR_GUIDE_PREVIEW_ERROR_FILL, (px, py, pw, ph))
                
        elif hl_state["mode"] == "Visualizer_Empty" and not _ch04_shield_active:
            if vlc_engine is not None: vlc_engine.stop()
            _static_sound_stop("guide preview: an empty visualizer channel")
            if pygame.mixer.music.get_busy(): pygame.mixer.music.stop()
            app_state["music_owner"] = ""
            app_state["guide_preview_music_track"] = ""
            app_state["loaded_preview_path_cache"] = ""
            pygame.draw.rect(screen, (0, 0, 0), (px, py, pw, ph))
        else:
            if pygame.mixer.music.get_busy():
                pygame.mixer.music.stop()
            app_state["music_owner"] = ""
            app_state["guide_preview_music_track"] = ""
            if app_state.get("loaded_preview_path_cache", "") != "":
                if vlc_engine is not None: vlc_engine.stop()
                app_state["loaded_preview_path_cache"] = ""
            if (hl_state["mode"] == "Static"
                    or (_guide_transition_style == "static" and _ch04_preview_static_visual_active)):
                if hl_state["mode"] == "Static":
                    # WARNING: one look for a channel on Static, the station's and the guide's (owner 2026-11-02, N8: "dont fix one, remove one and have the call from the same source").
                    _draw_static_channel(screen, pygame.Rect(px, py, pw, ph), ("guide", str(hl_ch)), target_aspect=16.0 / 9.0, reason=hl_state.get("reason"))
                else:
                    _render_transition_static(screen, pygame.Rect(px, py, pw, ph), target_aspect=16.0 / 9.0)

                if hl_state["mode"] == "Static":
                    _draw_static_reason_banner(
                        screen, pygame.Rect(px, py, pw, ph),
                        hl_state.get("reason"), hl_state.get("reason_detail"),
                        scale=0.5)

    if pygame.time.get_ticks() < app_state.get("channel_switch_static_until", 0):
        _transition_style = _configured_transition_style()
        if _transition_style == "static":
            _render_transition_static(screen, _full_window_rect)
        else:
            _stop_transition_static()
            screen.fill(COLOR_TRANSITION_GREY, _full_window_rect)

    else:
        if app_state.get("_warm_static_mute_active", False):
            app_state["_warm_static_mute_active"] = False
            if vlc_engine is not None:
                _still_muted = db.config.get("is_muted", False) if db is not None else False
                if not _still_muted:
                    try: vlc_engine.player.audio_set_mute(False)
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: vlc_engine.player.audio_set_mute(False)", _swallowed_error)
            _mute_guard_log("warm static transition duck LIFTED", ch=ch)

        if app_state.get("_visualizer_audio_duck_active", False):
            app_state["_visualizer_audio_duck_active"] = False
            _pending_vol = app_state.pop("_visualizer_pending_music_vol", None)
            if _pending_vol is not None:
                try:
                    pygame.mixer.music.set_volume(_pending_vol)
                except Exception as _swallowed_error:
                    _log_swallowed("main script: pygame.mixer.music.set_volume(_pending_vol)", _swallowed_error)

        if app_state.get("_ch03_static_mute_active", False):
            app_state["_ch03_static_mute_active"] = False
            _still_muted_mm = db.config.get("is_muted", False) if db is not None else False
            try:
                if _ch03_music_is_playing():
                    _set_ch03_menu_music_volume(
                        db.config.get("global_volume", 70) if db else 70, _still_muted_mm)
            except Exception as _mm_restore_err:
                log.warning(f"[CH03 MUSIC] static-burst volume restore failed: {_mm_restore_err}")
            if game_deck is not None:
                _still_muted = db.config.get("is_muted", False) if db is not None else False
                try:
                    if getattr(game_deck, "_libretro_core", None) is not None and game_deck._libretro_core.is_loaded:
                        game_deck.set_libretro_volume(
                            db.config.get("global_volume", 70) if db else 70, _still_muted)
                except Exception as _ch03_restore_err:
                    log.warning(f"[CH03 AUDIO] static-burst restore failed: {_ch03_restore_err}")

    _prof_mark("video")

    # ========================================================================
    # SECTION: Game deck render (CH 03)
    # ========================================================================

    if _surf_quiet and ch not in ("03", "04"):
        pass
    elif ch == "03":
        if pygame.time.get_ticks() >= app_state.get("channel_switch_black_until", 0):
            _stop_transition_static()
        _run_pending_channel_activation()

        # WARNING: clear the leftover Visualizer target file when leaving ch03, the same as the ch != 04 branch below.
        app_state["_vis_target_filepath"] = ""

    elif ch != "04":
        _run_pending_channel_activation()

        current_state = current_playback_state

        app_state["_vis_target_filepath"] = ""

        if current_state["mode"] in ["Video", "Visualizer", "Visualizer_Empty"]:
            if vlc_engine is not None and current_state["mode"] != "Video":
                try:
                    if vlc_engine.player.is_playing(): vlc_engine.stop()
                except Exception as e: log.warning(f"[PREVIEW] vlc stop failed: {e}")
            
        if current_state["mode"] == "Static":
            if pygame.mixer.music.get_busy():
                pygame.mixer.music.stop()
                
            if ch == "03":
                _stop_transition_static()
                # WARNING: not pure black; (0, 0, 0) is the game-overlay transparency key.
                screen.fill(COLOR_SCREEN_BLACK)
            else:
                _render_transition_static(screen, _full_window_rect)

        elif current_state["mode"] in ("Video", "Commercial") and not (
                not app_state.get("is_playing_video", False)
                and (str(ch).zfill(2) in _channel_playback_failures
                     or str(ch).zfill(2) in _station_confirmed_dead_drive)):
            if pygame.mixer.music.get_busy():
                pygame.mixer.music.stop()

            _stalled_ms = max(0, now_ticks - app_state.get("_last_new_frame_ticks", 0))
            _stall_threshold = (PLAYBACK_STALL_TIMEOUT_MS
                                 if app_state.get("_had_first_frame_this_tune", False)
                                 else PLAYBACK_INITIAL_BUFFER_TIMEOUT_MS)
            if (vlc_engine is not None and _stalled_ms >= _stall_threshold
                    and not app_state.get("_stall_recovery_inflight", False)):
                app_state["_stall_recovery_inflight"] = True
                _recover_from_playback_stall(ch, _stalled_ms)
                continue

            _transition_style_wait = _configured_transition_style()
            # WARNING: the channel you just tuned to gets the longer first-load allowance until its first picture arrives (owner 2026-11-06); once a picture has played, the shorter rule applies.
            _stall_static_ms = (STALL_FORCES_STATIC_MS
                                if app_state.get("_had_first_frame_this_tune", False)
                                else STALL_FORCES_STATIC_FIRST_LOAD_MS)
            _stall_is_now_static = _stalled_ms >= _stall_static_ms
            app_state["_stall_is_now_static"] = _stall_is_now_static
            if _stall_is_now_static:
                # WARNING: the stall Static is the fallback static of owner 2026-11-05 (14.2): it carries the same red banner so the viewer knows the picture is not frozen, only not ready, and the retry goes on under it.
                _report_missing_media((str(ch).zfill(2), "picture_stalled", "stall"),
                                      "PLAYBACK STALLED \u2014 the picture is not ready, still trying")

            if vlc_engine is not None:
                try:
                    _static_transition_active = (
                        _transition_style_wait == "static"
                        and pygame.time.get_ticks() < app_state.get("channel_switch_static_until", 0)
                    )
                    _audio_sync_hold_active = (
                        pygame.time.get_ticks()
                        < app_state.get("_video_audio_hold_until", 0)
                    ) or _static_transition_active
                    vlc_bytes = (
                        None if _audio_sync_hold_active
                        else vlc_engine.get_display_frame()
                    )
                    if (_audio_sync_hold_active and _loudness_hold_last_frame_active()
                            and _has_last_video_frame(context="fullscreen")):
                        _blit_last_video_frame(screen, *_screen_mode_boxed_last_frame_rect(content_rect, w_w, w_h), context="fullscreen", outer_rect=content_rect)
                    elif _audio_sync_hold_active:
                        # WARNING: do not consume the first decoded frame while the replacement audio output settles.
                        if _transition_style_wait == "static" or _stall_is_now_static:
                            _render_transition_static(screen, _full_window_rect)
                        else:
                            _stop_transition_static()
                            screen.fill(COLOR_TRANSITION_GREY, _full_window_rect)
                    elif vlc_bytes:
                        _note_fresh_live_video_frame(ch)

                        if not app_state.get("_video_painted_this_frame", False):
                            video_surf = pygame.image.frombuffer(vlc_bytes, (vlc_engine.width, vlc_engine.height), "BGRA")
                            video_surf = _true_content_surf(video_surf, vlc_engine)
                            _picture_box_set_content(current_playback_state.get("file", ""))
                            video_surf, _pb_aspect = _apply_picture_box_crop(video_surf)

                            processed_surf = video_surf
                            _pan_scan_set_content(current_playback_state.get("file", ""))
                            _video_sa = _snap_standard_aspect(_pb_aspect or (video_surf.get_width() / video_surf.get_height()))
                            _video_target_rect = _video_screen_mode_rect(content_rect, w_w, w_h, source_aspect=_video_sa)
                            if (_video_target_rect.width < content_rect.width
                                    or _video_target_rect.height < content_rect.height):
                                screen.fill(_video_bar_color(), content_rect)
                            _blit_video_with_screen_mode(screen, processed_surf, _video_target_rect,
                                                          mode=_bezel_video_fit_mode(),
                                                          analysis_surf=video_surf,
                                                          pixel_aspect=_video_pixel_aspect(w_w, w_h, _video_sa),
                                                          fit_aspect=_video_sa)
                            _store_last_video_frame(processed_surf, raw_surf=video_surf, context="fullscreen", fit_aspect=_video_sa)
                    else:
                        # WARNING: decide whether this tick is about to show real static before touching static_audio.
                        _about_to_render_static = (
                            _stall_is_now_static
                            or (not _has_last_video_frame(context="fullscreen")
                                and _transition_style_wait == "static")
                        )
                        if not _about_to_render_static:
                            _static_sound_stop("fullscreen video: a frame is drawn and no Static is due")
                        if _stall_is_now_static:
                            _render_transition_static(screen, _full_window_rect)
                        elif _has_last_video_frame(context="fullscreen"):
                            _blit_last_video_frame(screen, *_screen_mode_boxed_last_frame_rect(content_rect, w_w, w_h), context="fullscreen", outer_rect=content_rect)
                        elif _transition_style_wait == "static":
                            _render_transition_static(screen, _full_window_rect)
                        else:
                            screen.fill(COLOR_TRANSITION_GREY, _full_window_rect)
                except Exception as _swallowed_error:
                    # WARNING: do not stop static_audio on a tick that is about to restart it via _render_transition_static(), or the noise never plays long enough to be heard.
                    _log_swallowed("module: _static_transition_active = _transition_style_wait == 'static' and ...", _swallowed_error)
                    _about_to_render_static = _stall_is_now_static or (
                        not _has_last_video_frame(context="fullscreen")
                        and _transition_style_wait == "static"
                    )
                    if not _about_to_render_static:
                        _static_sound_stop("fullscreen video: the picture draw failed and no Static is due")
                    if _stall_is_now_static:
                        _render_transition_static(screen, _full_window_rect)
                    elif _blit_last_video_frame(screen, *_screen_mode_boxed_last_frame_rect(content_rect, w_w, w_h), context="fullscreen", outer_rect=content_rect):
                        pass
                    else:
                        if _transition_style_wait == "static":
                            _render_transition_static(screen, _full_window_rect)
                        else:
                            screen.fill(COLOR_TRANSITION_GREY, _full_window_rect)

        elif current_state["mode"] in ("Video", "Commercial"):
            if pygame.mixer.music.get_busy():
                pygame.mixer.music.stop()
            _render_transition_static(screen, _full_window_rect)
            _draw_channel_failure_message(screen, _full_window_rect, str(ch).zfill(2))

        elif current_state["mode"] == "Visualizer":
            _vis_fixed_rect = (pygame.Rect(0, 0, *screen.get_size())
                                if _vis_ignores_package_aspect(w_w, w_h)
                                else content_rect)
            try:
                target_file = current_state.get("file", "")
                target_seek_seconds = current_state.get("seek", 0)
                track_duration_max = current_state.get("duration", 210)
                ch_conf = db.channels_db.get(str(ch).zfill(2), {})
                
                active_cached_track = app_state.get("active_music_track_file", "")
                
                _ch_key_vis = str(ch).zfill(2)

                _vis_grace_ms = 600
                _vis_in_grace  = (pygame.time.get_ticks() -
                                  app_state.get("vis_song_started_at", 0)) < _vis_grace_ms
                # WARNING: target_file always comes from the schedule; the load block below replaces whatever the mixer is playing at the scheduled seek.
                _last_sched_by_ch = app_state.setdefault("last_scheduled_vis_track", {})
                last_scheduled_vis_track = _last_sched_by_ch.get(_ch_key_vis, "")
                is_new_scheduled_track = last_scheduled_vis_track != target_file

                app_state["_vis_target_filepath"] = target_file

                _vis_dead_root = _visualizer_confirmed_dead_drive.get(_ch_key_vis)
                if _vis_dead_root is not None and _drive_confirmed_recovered(_vis_dead_root):
                    _visualizer_confirmed_dead_drive.pop(_ch_key_vis, None)
                    _vis_dead_root = None
                _vis_drive_confirmed_dead = _vis_dead_root is not None or _ch_key_vis in _channel_playback_failures

                if (not _vis_drive_confirmed_dead
                        and app_state.get("music_owner") == "live_visualizer"
                        and active_cached_track):
                    try:
                        _playing_root = media._drive_root_of(active_cached_track)
                    except Exception as _swallowed_error:
                        _log_swallowed("module: _playing_root = media._drive_root_of(active_cached_track)", _swallowed_error)
                        _playing_root = None
                    if _playing_root and _playing_root in _unresponsive_drive_roots():
                        log.warning(
                            "[VISUALIZER CHANNEL] Drive %s (channel %s) went "
                            "unresponsive mid-playback of %s -- stopping "
                            "music instead of continuing to stream from it.",
                            _playing_root, _ch_key_vis, os.path.basename(active_cached_track),
                        )
                        pygame.mixer.Channel(1).stop()
                        if pygame.mixer.music.get_busy():
                            pygame.mixer.music.stop()
                        app_state["music_owner"] = ""
                        app_state["active_music_track_file"] = ""
                        _register_channel_playback_failure(_ch_key_vis, active_cached_track)
                        _visualizer_confirmed_dead_drive[_ch_key_vis] = _playing_root
                        _remember_dead_drive_probe_file(_playing_root, active_cached_track)
                        _vis_drive_confirmed_dead = True
                        active_cached_track = ""
                        target_file = ""
                        _vis_stopped_mid_playback = True
                    else:
                        _vis_stopped_mid_playback = False
                else:
                    _vis_stopped_mid_playback = False

                _vis_fresh_failure = _vis_stopped_mid_playback

                if (app_state.get("music_owner") != "live_visualizer"
                        or active_cached_track != target_file):
                    if _vis_drive_confirmed_dead:
                        if app_state.get("music_owner") == "live_visualizer":
                            pygame.mixer.Channel(1).stop()
                            if pygame.mixer.music.get_busy():
                                pygame.mixer.music.stop()
                            app_state["music_owner"] = ""
                        active_cached_track = ""
                        target_file = ""
                    elif target_file and _cached_path_exists(target_file):
                        _vis_load_t0 = time.monotonic()
                        pygame.mixer.Channel(1).stop()
                        
                        if pygame.mixer.music.get_busy():
                            pygame.mixer.music.stop()
                        
                        try: 
                            pygame.mixer.music.unload()
                        except Exception as unload_err:
                            log.warning("Track transition: pygame.mixer.music unload failed for %s: %s", target_file, unload_err)

                        try:
                            _vis_loop_playback_path = _resolve_compressor_playback_path(target_file, for_seek=True)
                            pygame.mixer.music.load(_vis_loop_playback_path)
                            app_state["_music_loaded_playback_path"] = _vis_loop_playback_path
                            _static_sound_stop("visualizer: a music track loaded")
                            app_state["active_music_gain"] = _lookup_file_gain(_ch_key_vis, target_file)
                            pygame.mixer.music.set_volume(
                                _effective_audio_gain(min_db=STACKED_GAIN_MIN_DB)
                                * MUSIC_GAIN
                                * _effective_loudness_gain(app_state["active_music_gain"])
                            )
                            try:
                                _prime_channel_block_loudness(_ch_key_vis, target_file, "Music Tracks")
                                _prime_visualizer_lookahead_loudness(_ch_key_vis, target_file)
                            except Exception as _vis_gain_prime_err:
                                log.warning("[VISUALIZER CHANNEL] gain priming dispatch failed for %s: %s",
                                            target_file, _vis_gain_prime_err)
                        except Exception as vis_load_err:
                            log.warning("[VISUALIZER CHANNEL] Music load failed for %s: %s", target_file, vis_load_err)
                            _register_channel_playback_failure(_ch_key_vis, target_file)
                            # WARNING: a fast access rejection can leave the bare drive root answering os.path.exists() instantly, so the root check may never flag this drive.
                            try:
                                _fail_root = media._drive_root_of(target_file)
                            except Exception as _swallowed_error:
                                _log_swallowed("module: _fail_root = media._drive_root_of(target_file)", _swallowed_error)
                                _fail_root = None
                            if _fail_root:
                                _visualizer_confirmed_dead_drive[_ch_key_vis] = _fail_root
                                _remember_dead_drive_probe_file(_fail_root, target_file)
                            active_cached_track = ""
                            target_file = ""
                            _vis_fresh_failure = True

                        safe_seek = max(0.0, min(float(target_seek_seconds) + (time.monotonic() - _vis_load_t0), float(track_duration_max) - 1.0))

                        if _start_visualizer_music(target_file, safe_seek) is False:
                            app_state["active_music_track_file"] = ""
                            app_state["music_owner"] = ""
                        else:
                            app_state["active_music_track_file"] = target_file
                            app_state["music_owner"] = "live_visualizer"
                            app_state["vis_card_timer"] = pygame.time.get_ticks() + 15000
                            app_state["vis_song_started_at"] = pygame.time.get_ticks()
                
                if is_new_scheduled_track:
                    _last_sched_by_ch[_ch_key_vis] = target_file
                    if _get_channel_visualizer_style(ch_conf) == "Random":
                        _new_style = visualizer_deck.get_next_random_style()
                        visualizer_deck.current_running_style = _new_style
                        visualizer_deck.style_by_channel[_ch_key_vis] = _new_style
                elif (_get_channel_visualizer_style(ch_conf) == "Random"
                      and _ch_key_vis in visualizer_deck.style_by_channel):
                    visualizer_deck.current_running_style = visualizer_deck.style_by_channel[_ch_key_vis]
                
                if pygame.mixer.music.get_busy():
                    calc_amp = 45 + int(math.sin(pygame.time.get_ticks() * 0.045) * 45) + random.randint(0, 5)
                else:
                    # WARNING: an idle mixer on the scheduled song means the audio is shorter than its slot; it stays quiet until the schedule moves on and is never restarted.
                    calc_amp = 25 + int(math.sin(pygame.time.get_ticks() * 0.008) * 20)
                
                vis_style_setting = _get_channel_visualizer_style(ch_conf)
                if vis_style_setting != "Random":
                    visualizer_deck.current_running_style = vis_style_setting

                _vis_content_ok = bool(target_file) or pygame.mixer.music.get_busy() or _vis_fresh_failure

                _vis_static_burst_active = (
                    db is not None
                    and db.config.get("transition_type", "black") == "static"
                    and pygame.time.get_ticks() < app_state.get("channel_switch_static_until", 0)
                )

                if not _vis_content_ok or _vis_static_burst_active:
                    _render_transition_static(screen, _vis_fixed_rect)
                else:
                    _static_sound_stop("visualizer: content is playing")
                    import colorsys as _hud_colorsys
                    _hr, _hg, _hb = _hud_colorsys.hsv_to_rgb(db.config.get("theme_ui_hue", 140) / 360.0, 0.9, 1.0)
                    theme_green_color = (int(_hr * 255), int(_hg * 255), int(_hb * 255))
                    
                    if _vis_fixed_rect.height > 0 and (_vis_fixed_rect.width / _vis_fixed_rect.height) < (960 / 540):
                        vis_w, vis_h = 960, max(1, round(960 * _vis_fixed_rect.height / _vis_fixed_rect.width))
                    else:
                        vis_w, vis_h = 960, 540
                    vis_surf = pygame.Surface((vis_w, vis_h))
                    _render_visualizer_frame(
                        vis_surf, active_theme, calc_amp,
                        reactive=_visualizer_reactive_frame(app_state.get("active_music_track_file")))
                    
                    brightness, contrast, color_sat, sharpness, tint, fx_active = _get_video_effects(db)
                    
                    # WARNING: with the graphics-card drawing step the Video tab settings are applied to the whole picture there; doing them here too would apply them twice.
                    if fx_active and not _gpu_draws_picture_settings():
                        processed_surf = apply_video_effects(vis_surf, brightness, contrast, color_sat, sharpness, tint)
                        _blit_video_with_screen_mode(screen, processed_surf, _vis_fixed_rect)
                    else:
                        _blit_video_with_screen_mode(screen, vis_surf, _vis_fixed_rect)
                    
                    now_f = pygame.time.get_ticks()
                    if now_f < app_state.get("vis_card_timer", 0):
                        display_path_string = _visualizer_title_path(app_state.get("current_channel", ""), active_cached_track if active_cached_track else target_file)
                        raw_filename = os.path.basename(display_path_string).upper()
                        
                        if "." in raw_filename:
                            base_filename_str = raw_filename[:raw_filename.rfind(".")]
                        else:
                            base_filename_str = raw_filename
                            
                        import re
                        song_name_cleaned = re.sub(r'^[0-9\s\.\-_]+', '', base_filename_str)
                        song_name_cleaned = _clean_song_display_title(song_name_cleaned)
                        style_name_cleaned = visualizer_deck.current_running_style.upper()
                        app_state["_vis_card_text"] = (song_name_cleaned, f"VISUALIZER: {style_name_cleaned}")
            except Exception as e:
                _log_warn_throttled("visualizer_frame_failed", f"[VISUALIZER] the music station frame failed to draw, showing Static: {type(e).__name__}: {e}")
                _render_transition_static(screen, _vis_fixed_rect)
                
        elif current_state["mode"] == "Visualizer_Empty":
            if pygame.mixer.music.get_busy(): pygame.mixer.music.stop()
            pygame.mixer.Channel(1).stop()
            app_state["active_music_track_file"] = ""
            _render_transition_static(screen, pygame.Rect(0, 0, *screen.get_size()))

    else:
        if pygame.time.get_ticks() < app_state.get("channel_switch_static_until", 0):
            _transition_style = _configured_transition_style()
            if _transition_style == "static":
                _render_transition_static(screen, _full_window_rect)
            else:
                _stop_transition_static()
                screen.fill(COLOR_TRANSITION_GREY, _full_window_rect)
        elif (db is not None and db.config.get("transition_type", "black") == "static"
              and pygame.time.get_ticks() < app_state.get("guide_preview_static_until", 0)):
            if app_state.get("_warm_static_mute_active", False):
                app_state["_warm_static_mute_active"] = False
                if vlc_engine is not None:
                    _still_muted = db.config.get("is_muted", False) if db is not None else False
                    if not _still_muted:
                        try: vlc_engine.player.audio_set_mute(False)
                        except Exception as _swallowed_error:
                            _log_swallowed("main script: vlc_engine.player.audio_set_mute(False)", _swallowed_error)
                _mute_guard_log("warm static transition duck LIFTED", ch=ch)
            pass
        else:
            if app_state.get("_warm_static_mute_active", False):
                app_state["_warm_static_mute_active"] = False
                if vlc_engine is not None:
                    _still_muted = db.config.get("is_muted", False) if db is not None else False
                    if not _still_muted:
                        try: vlc_engine.player.audio_set_mute(False)
                        except Exception as _swallowed_error:
                            _log_swallowed("main script: vlc_engine.player.audio_set_mute(False)", _swallowed_error)
                _mute_guard_log("warm static transition duck LIFTED", ch=ch)
            preview_ch_num = str(app_state.get("highlighted_guide_channel", "05")).zfill(2)
            preview_ch_info = db.channels_db.get(preview_ch_num, {}) if db is not None else {}
            p_state = _get_guide_hl_playback_state(preview_ch_num)

            if p_state.get("mode") == "Static":
                pass
            elif preview_ch_info.get("is_visualizer", False):
                if not (preview_ch_num in _channel_playback_failures
                        or preview_ch_num in _visualizer_confirmed_dead_drive):
                    _stop_transition_static()
            else:
                if not (preview_ch_num in _channel_playback_failures
                        or preview_ch_num in _station_confirmed_dead_drive):
                    _stop_transition_static()

    # WARNING: a channel airing Static keeps its noise under menus, the file explorer and popups, as a TV does; the black shield of a non-Static transition stays silent.
    if (ch not in ("03", "04") and not _surf_quiet
            and current_playback_state.get("mode") == "Static"
            and pygame.time.get_ticks() >= app_state.get("channel_switch_black_until", 0)):
        _static_sound_play()

    _prof_mark("game_deck")

    # ========================================================================
    # SECTION: Overlays: captions, static, reception lines & watermark
    # ========================================================================

    # WARNING: paint the bad-reception overlay right after the video and before any menu or dialog, so it distorts the picture but never touches menu pixels.
    _static_rect = None
    _lines_rect = None
    if not _surf_quiet:
        _draw_caption_overlay(screen, content_rect=content_rect)
        if db is not None and db.config.get("fake_static_noise_enabled", False):
            _static_cur_ch = app_state.get("current_channel")
            _static_live_tv = _is_live_tv_broadcast_channel(_static_cur_ch)
            _static_ch_info = db.channels_db.get(str(_static_cur_ch).zfill(2), {}) if _static_live_tv else {}
            _static_transition_over = _channel_transition_over()
            # WARNING: a held picture (a freeze, an advance or a stall) keeps its Static Noise like the moving picture; dropping it showed a clean frozen picture (owner 2026-11-02 23:12).
            _static_content_active = _static_transition_over and (
                (app_state.get("is_playing_video", False) and app_state.get("_had_first_frame_this_tune", False))
                or app_state.get("_held_frame_drawn_this_frame", False)
                or (_static_ch_info.get("is_visualizer", False)
                    and pygame.mixer.music.get_busy())
            )
            if (_static_live_tv
                    and _static_content_active
                    and not app_state.get("file_explorer_active", False)
                    and app_state.get("crt_anim") is None):
                _static_rect = _full_window_rect
                _apply_static_noise_effect(screen, _static_rect, str(_static_cur_ch).zfill(2))

        if db is not None and db.config.get("fake_reception_lines_enabled", False):
            _lines_cur_ch = app_state.get("current_channel")
            _lines_live_tv = _is_live_tv_broadcast_channel(_lines_cur_ch)
            _lines_ch_info = db.channels_db.get(str(_lines_cur_ch).zfill(2), {}) if _lines_live_tv else {}
            _lines_transition_over = _channel_transition_over()
            _lines_content_active = _lines_transition_over and (
                (app_state.get("is_playing_video", False) and app_state.get("_had_first_frame_this_tune", False))
                or app_state.get("_held_frame_drawn_this_frame", False)
                or (_lines_ch_info.get("is_visualizer", False) and pygame.mixer.music.get_busy())
            )
            if (_lines_live_tv
                    and _lines_content_active
                    and not app_state.get("file_explorer_active", False)
                    and app_state.get("crt_anim") is None):
                _lines_rect = pygame.Rect(0, 0, *screen.get_size())
                _apply_reception_lines_effect(screen, _lines_rect)

        if db is not None and db.channels_db.get(str(app_state.get("current_channel", "")).zfill(2), {}).get("watermark_enabled", False):
            _wm_cur_ch = app_state.get("current_channel")
            _wm_ch_info = (db.channels_db.get(str(_wm_cur_ch).zfill(2), {})
                           if _is_live_tv_broadcast_channel(_wm_cur_ch) else {})
            if (_is_live_tv_broadcast_channel(_wm_cur_ch)
                    and not _wm_ch_info.get("is_visualizer", False)
                    and current_playback_state.get("mode") == "Video"
                    and not app_state.get("file_explorer_active", False)
                    and app_state.get("crt_anim") is None
                    and not app_state.get("show_splash", False)
                    and _channel_transition_over()):
                _wm_bounds = _watermark_bounds_rect(content_rect)
                _draw_watermark(screen, bounds_rect=_wm_bounds)
                if db.config.get("fake_static_noise_enabled", False) and _static_rect is not None:
                    _apply_static_noise_effect(screen, _static_rect, str(_static_cur_ch).zfill(2))
                if db.config.get("fake_reception_lines_enabled", False) and _lines_rect is not None:
                    _apply_reception_lines_effect(screen, _lines_rect)

        if pygame.time.get_ticks() < app_state.get("channel_switch_static_until", 0):
            _transition_style_cap = db.config.get("transition_type", "black") if db is not None else "black"
            if _transition_style_cap == "static":
                _render_transition_static(screen, _full_window_rect)
    try:
        _take_picture_layer(screen)
    except Exception as _pic_layer_err:
        _picture_layer_state.update(rect=None, taken=False)
        _log_warn_throttled("picture_layer", "[PICTURE ADJUST] could not mark the broadcast picture, the Video tab settings skip this frame: %s" % _pic_layer_err)

    _prof_mark("overlays")

    # ========================================================================
    # SECTION: Idle timeouts & held-key input
    # ========================================================================

    pressed_keys_matrix = pygame.key.get_pressed()

    def _key_is_held(_k):
        return _k in app_state["_held_keys"]

    now_ticks_ms = pygame.time.get_ticks()
    
    last_input = app_state.get("last_input_time", now_ticks_ms)
    elapsed_ms = now_ticks_ms - last_input

    if app_state.get("show_splash", False) and elapsed_ms >= MENU_IDLE_CLOSE_MS:
        app_state["show_splash"] = False
        app_state["splash_shown_at"] = 0

    if app_state.get("show_quit_confirm", False) and elapsed_ms >= CONFIRM_POPUP_IDLE_CLOSE_MS:
        app_state["show_quit_confirm"] = False
        app_state["quit_confirm_shown_at"] = 0

    if (app_state.get("show_clear_confirm", False) and elapsed_ms >= CONFIRM_POPUP_IDLE_CLOSE_MS
            and not app_state.get("update_install_active", False)):
        log.warning("[ANTI-BURN-IN SHIELD] Clear-confirm popup timed out. Cancelling.")
        app_state["show_clear_confirm"]     = False
        app_state["clear_confirm_target"]   = None
        app_state["clear_confirm_channel"]  = None
        app_state["clear_confirm_shown_at"] = 0
        app_state["clear_confirm_burnin_new_value"] = None
        app_state["clear_confirm_dont_show_again"]  = False
        app_state["clear_confirm_profile_num"] = None
        app_state["clear_confirm_focus"]    = "buttons"

    if game_deck is not None and elapsed_ms >= CONFIRM_POPUP_IDLE_CLOSE_MS:
        if getattr(game_deck, "_pick_layout_popup_player", None) is not None:
            log.warning("[ANTI-BURN-IN SHIELD] Pick Layout popup timed out. Dismissed.")
            game_deck.dismiss_pick_layout_popup()
        if game_deck.mapping_reassign_pending():
            log.warning("[ANTI-BURN-IN SHIELD] Waiting for a controller button timed out. Cancelled.")
            game_deck.cancel_any_mapping_reassign()

    _fe_busy_loading = (
        app_state.get("file_explorer_scan_pending", False)
        or app_state.get("file_explorer_expand_pending", 0) > 0
        or app_state.get("file_explorer_bulkscan_pending", False)
    )

    if app_state.get("file_explorer_active", False) and _fe_busy_loading:
        app_state["last_input_time"] = now_ticks_ms

    elif app_state.get("file_explorer_active", False) and elapsed_ms >= MENU_IDLE_CLOSE_MS:
        log.warning("[ANTI-BURN-IN SHIELD] File explorer timed out from inactivity -- "
              "closing explorer, menu, and guide together.")
        _fe_close(False)
        app_state["loaded_preview_path_cache"] = ""
        app_state["show_menu"]     = False
        app_state["menu_shown_at"] = 0
        if app_state.get("current_channel") == "04":
            _burn_target = str(app_state.get("highlighted_guide_channel", "05")).zfill(2)
            change_channel(_burn_target)
        app_state["last_input_time"] = now_ticks_ms

    elif app_state.get("show_menu", False) and elapsed_ms >= MENU_IDLE_CLOSE_MS:
        app_state["loaded_preview_path_cache"] = ""
        app_state["show_menu"] = False
        app_state["games_tab_page"] = 0
        app_state["menu_shown_at"] = 0

    if (app_state.get("current_channel") == "04"
            and not app_state.get("show_menu", False)
            and not app_state.get("show_quit_confirm", False)
            and not app_state.get("show_splash", False)
            and not app_state.get("file_explorer_active", False)):
        for _gh_a, _gh_b in ((pygame.K_w, pygame.K_s), (pygame.K_a, pygame.K_d)):
            if _gh_a in app_state["_held_keys"] and _gh_b in app_state["_held_keys"]:
                _a_phys = bool(pressed_keys_matrix[_gh_a])
                _b_phys = bool(pressed_keys_matrix[_gh_b])
                _gh_down_ticks = app_state.get("_held_key_down_ticks", {})
                _gh_drop = menu_nav.hold_conflict(_a_phys, _b_phys, _gh_down_ticks.get(_gh_a, 0), _gh_down_ticks.get(_gh_b, 0))
                if _gh_drop == menu_nav.DROP_BOTH:
                    log.warning("[GUIDE NAV DEBUG] SUSPECTED STUCK KEY: saw both %s and %s "
                                "held via _held_keys with matrix=(%s=%s, %s=%s) -- "
                                "clearing both and stopping repeat",
                                pygame.key.name(_gh_a), pygame.key.name(_gh_b),
                                pygame.key.name(_gh_a), _a_phys, pygame.key.name(_gh_b), _b_phys)
                if _gh_drop in (menu_nav.DROP_FIRST, menu_nav.DROP_BOTH):
                    app_state["_held_keys"].discard(_gh_a)
                if _gh_drop in (menu_nav.DROP_SECOND, menu_nav.DROP_BOTH):
                    app_state["_held_keys"].discard(_gh_b)

        _gh_any = False
        _gh_hold = app_state["_hold_guide"]
        for _gh_key in (pygame.K_w, pygame.K_s, pygame.K_a, pygame.K_d):
            if _key_is_held(_gh_key):
                _gh_any = True
                _gh_held_ms = now_ticks_ms - _gh_hold.start if _gh_hold.key == _gh_key else 0
                _gh_step = menu_nav.hold_step(
                    menu_nav.hold_rule(_gh_key), _gh_hold, _gh_key, now_ticks_ms, bool(pressed_keys_matrix[_gh_key]),
                    False, menu_nav.HOLD_STUCK_MS["guide"], _MENU_NAV_REPEAT_DELAY_MS)
                if _gh_step == menu_nav.HOLD_STUCK:
                    log.warning("[GUIDE NAV DEBUG] SUSPECTED STUCK KEY: key=%s "
                                "has been 'held' for %sms via _held_keys only "
                                "(SDL pressed_keys_matrix says NOT pressed) -- "
                                "self-healing by releasing it now (probably a "
                                "swallowed KEYUP from a past focus loss/remap "
                                "event)",
                                pygame.key.name(_gh_key), _gh_held_ms)
                    app_state["_held_keys"].discard(_gh_key)
                    _gh_any = False
                    continue
                if _gh_step == menu_nav.HOLD_REPEAT:
                    app_state["guide_inactivity_timer"] = now_ticks_ms + MENU_IDLE_CLOSE_MS
                    _guide_dirty_event.set()
                    _gh_axis, _gh_move = menu_nav.guide_move(menu_nav.key_to_direction(_gh_key))
                    if _gh_axis == menu_nav.GUIDE_TIME:
                        _guide_jump_col(_gh_move, _source="held-repeat")
                    else:
                        _guide_step_row(_gh_move, False)
                        app_state["_guide_hold_moved_rows"] = True
                break
        if not _gh_any:
            _gh_hold.clear()
            if app_state.pop("_guide_hold_moved_rows", False):
                _resync_guide_stop_after_row_switch()

    _prof_mark("idle_input")

    # ========================================================================
    # SECTION: Volume OSD
    # ========================================================================

    def _draw_channel_volume_osd(phase):
        now = pygame.time.get_ticks()
        w_w, w_h = screen.get_size()

        _overlay_active = (app_state.get("show_menu", False)
                            or app_state.get("show_splash", False)
                            or app_state.get("show_quit_confirm", False)
                            or app_state.get("show_restart_confirm", False)
                            or app_state.get("file_explorer_active", False))

        OSD_COLOR = _osd_ui_color()

        _led_rect = _bezel_channel_led_rect(w_w, w_h)
        if phase == "led" and _led_rect is not None:
            _led_stem = _bezel_led_stem()
            _num_part = _bezel_led_channel_text()
            _led_text_top_y = _draw_bezel_channel_led(
                screen, _led_rect, _led_stem, "CH", _num_part, OSD_COLOR,
                _bezel_measured_led_window() is not None, _bezel_measured_led_tilt())
            _record_led_text_top_y(_led_text_top_y, _led_stem)
        elif phase == "picture" and _led_rect is None and not _overlay_active:
            _channel_transition_active = not _channel_transition_over()

            _ch_geom = _bezel_composite_geometry(
                w_w, w_h,
                ignore_package_aspect=_content_ignores_package_aspect(w_w, w_h))
            _ch_rect = _ch_geom[0] if _ch_geom is not None else pygame.Rect(0, 0, w_w, w_h)
            if _ch_geom is not None and _ch_geom[2] > 0:
                _ch_scale = 1.0 / _ch_geom[2]
            else:
                _ch_scale = 1.0
            if _ch_geom is not None and _ch_geom[1] > 0:
                _ch_scale_x = 1.0 / _ch_geom[1]
            else:
                _ch_scale_x = 1.0
            _osd_right_off, _osd_top_off = _TV_BORDER_OSD_OFFSET
            def _cs(px):
                return max(1, round(px * _ch_scale))
            def _cs_x(px):
                return max(1, round(px * _ch_scale_x))
            def _cs_signed(px):
                # WARNING: do not apply _cs()'s max(1, ...) floor to a signed offset; a negative value would silently clamp up to +1.
                return round(px * _ch_scale)

            _true_top_y = _ch_rect.y + _cs_signed(_osd_top_off)
            app_state["_ch_num_generic_osd_y"] = _true_top_y
            app_state["_ch_num_osd_in_window"] = False

            _generic_osd_y = _true_top_y + _cs_signed(_CH_NUM_TOP_ALIGN_NUDGE_PX)

            if (_channel_transition_active
                    or now < app_state.get("osd_channel_timer", 0)):
                f_osd = _cached_sys_font("Arial Black", _cs(54), bold=False)
                display_txt = _bezel_led_channel_text()
                _osd_surf = f_osd.render(display_txt, True, OSD_COLOR)
                _osd_y = _generic_osd_y
                _osd_x = _ch_rect.right - _cs_x(_osd_right_off) - _osd_surf.get_width()
                if _osd_x < _ch_rect.x:
                    _osd_x = _ch_rect.x
                screen.blit(_osd_surf, (_osd_x, _osd_y))

        if (phase == "picture" and game_deck is not None
                and getattr(game_deck, "dvd_osd_msg", "") != ""
                and now < getattr(game_deck, "dvd_osd_until", 0)):
            app_state["osd_volume_timer"] = 0

        if phase == "picture" and not _overlay_active and now < app_state.get("osd_volume_timer", 0):
            _vol_rect = _precompose_bezel_content_rect(screen, ignore_package_aspect=True)
            _vol_scale = 1.0
            def _vs(px):
                return max(1, round(px * _vol_scale))

            _vol_cx  = _vol_rect.centerx
            _vol_bot = _vol_rect.bottom - _vs(120)
            f_vol_text = _cached_sys_font("Courier New", _vs(30), bold=True)
            f_vol_bar  = _cached_sys_font("Courier New", _vs(64), bold=True)
            if db.config.get("is_muted", False):
                center_x = _vol_cx
                base_y = _vol_bot
                pygame.draw.rect(screen, OSD_COLOR, (center_x - _vs(22), base_y + _vs(12), _vs(14), _vs(14)))
                pygame.draw.polygon(screen, OSD_COLOR, [
                    (center_x - _vs(10), base_y + _vs(12)), (center_x + _vs(4), base_y + _vs(2)),
                    (center_x + _vs(4), base_y + _vs(36)), (center_x - _vs(10), base_y + _vs(26))
                ])
                pygame.draw.line(screen, OSD_COLOR, (center_x + _vs(14), base_y + _vs(10)), (center_x + _vs(28), base_y + _vs(24)), max(1, _vs(3)))
                pygame.draw.line(screen, OSD_COLOR, (center_x + _vs(28), base_y + _vs(10)), (center_x + _vs(14), base_y + _vs(24)), max(1, _vs(3)))
                f_mute = _cached_sys_font("Courier New", _vs(14), bold=True)
                lbl_m = f_mute.render("MUTED", True, OSD_COLOR)
                screen.blit(lbl_m, (center_x - (lbl_m.get_width() // 2), base_y + _vs(44)))
            else:
                _vol_pct = db.config.get("global_volume", 70)
                lbl_v = f_vol_text.render(f"VOLUME: {_vol_pct}%", True, OSD_COLOR)
                _lbl_v_y = _vol_bot
                _bar_ref = f_vol_bar.size("VOLUME: 100%")[0]
                _bar_w = int(_bar_ref * 1.35)
                _bar_h = _vs(26)
                _bar_x = _vol_cx - _bar_w // 2
                _bar_y = _vol_bot + lbl_v.get_height() + _vs(6)

                if db.config.get("volume_bar_style", "1") == "2":
                    _seg_total = 20
                    _seg_filled = int(round((_vol_pct / 100.0) * _seg_total))
                    _seg_gap = max(1, _vs(4))
                    _seg_w = (_bar_w - (_seg_gap * (_seg_total - 1))) / _seg_total
                    _rect_h_tall = _bar_h * 3.2
                    _rect_h = (_rect_h_tall + _seg_w) / 2
                    _seg_center_y = _bar_y + (_bar_h / 2)
                    _rect_top = _seg_center_y - (_rect_h / 2)
                    _lbl_v_y = _rect_top - _vs(9.5) - lbl_v.get_height()
                    _dot_rad = max(2, int(_bar_h / 2))
                    screen.blit(lbl_v, (_vol_cx - lbl_v.get_width() // 2, _lbl_v_y))
                    for _i in range(_seg_total):
                        _seg_x = _bar_x + int(_i * (_seg_w + _seg_gap))
                        if _i < _seg_filled:
                            _rect_y = _seg_center_y - (_rect_h / 2)
                            pygame.draw.rect(screen, OSD_COLOR, (_seg_x, _rect_y, int(_seg_w), int(_rect_h)))
                        else:
                            _dot_cx = _seg_x + int(_seg_w / 2)
                            _dot_cy = int(_seg_center_y)
                            pygame.draw.circle(screen, OSD_COLOR, (_dot_cx, _dot_cy), _dot_rad)
                else:
                    screen.blit(lbl_v, (_vol_cx - lbl_v.get_width() // 2, _lbl_v_y))
                    _fill_w = int(_bar_w * _vol_pct / 100)
                    _bar_radius = max(1, _vs(8))
                    pygame.draw.rect(screen, COLOR_VOLUME_OSD_TRACK,   (_bar_x, _bar_y, _bar_w, _bar_h), border_radius=_bar_radius)
                    pygame.draw.rect(screen, OSD_COLOR,      (_bar_x, _bar_y, _fill_w, _bar_h), border_radius=_bar_radius)
                    pygame.draw.rect(screen, OSD_COLOR,      (_bar_x, _bar_y, _bar_w, _bar_h), max(1, _vs(2)), border_radius=_bar_radius)

    _vol_matrix = pygame.key.get_pressed()

    _prof_mark("volume_osd")

    # ========================================================================
    # SECTION: Menus & overlays
    # ========================================================================

    if app_state.get("show_menu", False):
        app_state["_hold_volume"].clear()
        for _vk in (pygame.K_LEFT, pygame.K_RIGHT):
            # WARNING: a swallowed key-up can leave an arrow counted as held under an open menu; drop it once it is old and SDL says it is not down.
            if (_vk in app_state["_held_keys"] and not _vol_matrix[_vk]
                    and now_ticks_ms - app_state.get("_held_key_down_ticks", {}).get(_vk, now_ticks_ms)
                    > menu_nav.HOLD_STUCK_MS["volume"]):
                app_state["_held_keys"].discard(_vk)
    elif not app_state.get("show_menu", False) and not app_state.get("show_splash", False) and not app_state.get("show_quit_confirm", False):
        pass

        _dvd_popup_open = (
            app_state.get("current_channel") == "03"
            and 'game_deck' in globals() and game_deck is not None
            and getattr(game_deck, "mode", "BROWSE") == "DVD_PLAYER"
            and (getattr(game_deck, "dvd_exit_confirm", False)
                 or getattr(game_deck, "dvd_return_menu_confirm", False))
        )

        _vol_key = None
        if not _dvd_popup_open:
            _rb = (db.config.get("remote_bindings", {}) if db else {}) or {}
            _right_claimed = any(_a != "right" and _k == pygame.K_RIGHT for _a, _k in _rb.items())
            _left_claimed  = any(_a != "left"  and _k == pygame.K_LEFT  for _a, _k in _rb.items())
            # WARNING: keep this opposite-key check; without it RIGHT always wins, and a stuck RIGHT keeps ramping volume up while a real LEFT hold does nothing.
            if pygame.K_LEFT in app_state["_held_keys"] and pygame.K_RIGHT in app_state["_held_keys"]:
                _l_phys = bool(_vol_matrix[pygame.K_LEFT])
                _r_phys = bool(_vol_matrix[pygame.K_RIGHT])
                if _l_phys and not _r_phys:
                    app_state["_held_keys"].discard(pygame.K_RIGHT)
                elif _r_phys and not _l_phys:
                    app_state["_held_keys"].discard(pygame.K_LEFT)
                elif _l_phys and _r_phys:
                    _vol_down_ticks = app_state.get("_held_key_down_ticks", {})
                    if _vol_down_ticks.get(pygame.K_LEFT, 0) <= _vol_down_ticks.get(pygame.K_RIGHT, 0):
                        app_state["_held_keys"].discard(pygame.K_LEFT)
                    else:
                        app_state["_held_keys"].discard(pygame.K_RIGHT)
                else:
                    log.warning("[VOLUME DEBUG] SUSPECTED STUCK KEY: saw both LEFT and RIGHT "
                                "held via _held_keys with matrix=(LEFT=%s, RIGHT=%s) -- "
                                "clearing both and stopping repeat", _l_phys, _r_phys)
                    app_state["_held_keys"].discard(pygame.K_LEFT)
                    app_state["_held_keys"].discard(pygame.K_RIGHT)

            # WARNING: a hold counts when the key is tracked as held OR is physically down per SDL, so a lost or never-recorded key-down cannot turn a hold into a single step.
            _vol_right_held = ((pygame.K_RIGHT in app_state["_held_keys"]) or bool(_vol_matrix[pygame.K_RIGHT])) and not _right_claimed
            _vol_left_held = ((pygame.K_LEFT in app_state["_held_keys"]) or bool(_vol_matrix[pygame.K_LEFT])) and not _left_claimed
            if _vol_right_held and _vol_left_held:
                # WARNING: both counted as held and the conflict check above kept both, so trust only what is physically down.
                _vol_right_held = bool(_vol_matrix[pygame.K_RIGHT])
                _vol_left_held = bool(_vol_matrix[pygame.K_LEFT]) and not _vol_right_held
            if _vol_right_held:    _vol_key = pygame.K_RIGHT
            elif _vol_left_held:   _vol_key = pygame.K_LEFT

        _vol_hold = app_state["_hold_volume"]
        if _vol_key is not None:
            # WARNING: the volume hold uses menu_nav's hold machinery (rule, stuck-key and repeat timing live in menu_nav.py); the first press itself is handled in the key-down handler.
            _vol_step = menu_nav.hold_step(
                menu_nav.hold_rule(_vol_key), _vol_hold, _vol_key, now_ticks_ms, bool(_vol_matrix[_vol_key]),
                False, menu_nav.HOLD_STUCK_MS["volume"])
            if _vol_step == menu_nav.HOLD_STARTED:
                log.info("[VOLUME DEBUG] hold started key=%s tracked=%s sdl_down=%s", pygame.key.name(_vol_key),
                         _vol_key in app_state["_held_keys"], bool(_vol_matrix[_vol_key]))
            elif _vol_step == menu_nav.HOLD_STUCK:
                log.warning("[VOLUME DEBUG] SUSPECTED STUCK KEY: key=%s counted as held but SDL says NOT pressed -- "
                            "releasing it now (probably a swallowed key-up)", pygame.key.name(_vol_key))
                app_state["_held_keys"].discard(_vol_key)
            elif _vol_step == menu_nav.HOLD_REPEAT:
                db.config["global_volume"] = menu_nav.volume_next(db.config.get("global_volume", 70), menu_nav.volume_direction(_vol_key))
                app_state["osd_volume_timer"] = now_ticks_ms + 2500
                if game_deck is not None:
                    game_deck.dvd_osd_msg = ""; game_deck.dvd_osd_until = 0
                db.config["is_muted"] = False
                
                target_gain_factor = _perceptual_volume_pct(db.config["global_volume"]) / 100.0
                music_gain_factor = _perceptual_volume_pct(db.config["global_volume"], min_db=STACKED_GAIN_MIN_DB) / 100.0
                if vlc_engine is not None: vlc_engine.set_volume(int(db.config["global_volume"]), False)
                _set_dvd_volume(int(db.config["global_volume"]), False)
                if static_audio is not None:
                    static_audio.set_volume(
                        target_gain_factor * _effective_loudness_gain(_STATIC_AUDIO_GAIN))
                pygame.mixer.music.set_volume(
                    music_gain_factor * MUSIC_GAIN
                    * _effective_loudness_gain(app_state.get("active_music_gain", 1.0)))
                pygame.mixer.Channel(1).set_volume(
                    music_gain_factor * MUSIC_GAIN
                    * _effective_loudness_gain(app_state.get("active_music_gain", 1.0)))
                if game_deck is not None and hasattr(game_deck, "set_libretro_volume"):
                    game_deck.set_libretro_volume(
                        db.config.get("global_volume", 70), db.config.get("is_muted", False))
                _set_ch03_menu_music_volume(db.config["global_volume"], db.config.get("is_muted", False))
                
                _mark_settings_dirty()
        else:
            _vol_hold.clear()

    _flush_settings_if_dirty()

    media.CRT_WARP_ACTIVE = _crt_shader_will_apply(screen)

    _draw_visualizer_song_card(screen)

    _fe_will_draw_over_menu = (
        app_state.get("file_explorer_active", False)
        and not (
            ch == "03"
            and game_deck is not None
            and (
                getattr(game_deck, "mode", "") == "DVD_PLAYER"
                or getattr(game_deck, "dvd_playback_active", False)
            )
        )
    )

    if app_state.get("show_menu", False) and not _fe_will_draw_over_menu:
        _menu_surf = _overlay_target(screen)
        app_state["dvd_audio_track_count"] = _get_dvd_audio_track_count(dvd_engine)
        render_settings_overlay_menu(_overlay_target_for_menu(screen), active_theme, app_state, db)

        if app_state.get("menu_layer") == "GAMES_STICK_DZ" and game_deck is not None:
            import colorsys as _szcs
            _sz_h = db.config.get("theme_ui_hue", 140) / 360.0 if db else 0.39
            _sz_r, _sz_g, _sz_b = _szcs.hsv_to_rgb(_sz_h, 0.88, 1.0)
            _sz_surf = _overlay_target_for_menu(screen)
            _sz_x, _sz_y, _sz_w, _sz_h2 = menu_panel_rect(_sz_surf.get_width(), _sz_surf.get_height(), db)
            _sz_scale = _sz_w / 1036.0
            import game_deck as _sz_mod
            _sz_player = app_state.get("stick_dz_player", 1)
            _sz_rows = menu_nav.stick_dz_rows(_sz_mod.stick_switch_on(db.config, _sz_player))
            _sz_mod.mark_stick_test_open()
            _sz_mod.render_stick_deadzone_ui(
                _sz_surf,
                (_sz_x + int(20 * _sz_scale), _sz_y + int(138 * _sz_scale), int(996 * _sz_scale), int(525 * _sz_scale)),
                (int(_sz_r * 255), int(_sz_g * 255), int(_sz_b * 255)), db, app_state.get("stick_dz_cursor", 0), _sz_rows,
                _sz_mod.stick_test_sticks(_sz_player), _sz_player)

        if app_state.get("menu_layer") == "GAMES_CTRL_MAP" and game_deck is not None:
            game_deck._ctrl_map_cursor = app_state.get("ctrl_map_cursor", 1)
            game_deck.refresh_player_slots()
            game_deck._ctrl_map_player_sel = app_state.get(
                "ctrl_map_player_sel", getattr(game_deck, "_active_mapping_player", 1))
            game_deck._ctrl_map_on_pick = app_state.get("ctrl_map_on_pick", False)
            import colorsys as _cmcs
            _ch = db.config.get("theme_ui_hue", 140) / 360.0 if db else 0.39
            _cr, _cg, _cb = _cmcs.hsv_to_rgb(_ch, 0.88, 1.0)
            _ui_col = (int(_cr * 255), int(_cg * 255), int(_cb * 255))
            _cm_surf = _overlay_target_for_menu(screen)
            _cm_x, _cm_y, _cm_w, _cm_h = menu_panel_rect(_cm_surf.get_width(), _cm_surf.get_height(), db)
            _content_scale = _cm_w / 1036.0
            _ctrl_x = _cm_x + int(20 * _content_scale)
            _ctrl_y = _cm_y + int(138 * _content_scale)
            _ctrl_w = int(996 * _content_scale)
            _ctrl_h = int(525 * _content_scale)
            game_deck.render_controller_mapping_ui(_cm_surf, (_ctrl_x, _ctrl_y, _ctrl_w, _ctrl_h), _ui_col, db, console=app_state.get("games_ctrl_console", "GBA"))
            game_deck.poll_xinput_for_remap()
            game_deck.poll_controller_test_lights(app_state.get("games_ctrl_console", "GBA"))
            _cur_ctrl_lit = (getattr(game_deck, "_ctrl_test_lit", None) or set()) | \
                            (getattr(game_deck, "_ctrl_test_lit_joy", None) or set())
            _prev_ctrl_lit = app_state.get("_ctrl_test_lit_prev", set())
            if _cur_ctrl_lit - _prev_ctrl_lit:
                app_state["last_input_time"] = pygame.time.get_ticks()
            app_state["_ctrl_test_lit_prev"] = _cur_ctrl_lit
            game_deck.poll_player_reassign()
            game_deck.poll_menu_reassign()
            if game_deck.mapping_reassign_pending():
                _pick_wait_player = None if game_deck.menu_reassign_pending() else game_deck.mapping_reassign_pending_player()
                render_controller_pick_wait_popup(_menu_surf, active_theme, db, game_deck,
                                                   _pick_wait_player)
            if getattr(game_deck, "_pick_layout_popup_player", None) is not None:
                render_pick_layout_popup(_menu_surf, active_theme, db, game_deck,
                                          game_deck._pick_layout_popup_player)
            if getattr(game_deck, "_mapping_close_requested", False):
                game_deck._mapping_close_requested = False
                app_state["menu_layer"] = "GAMES_SUB_MENU"
                app_state["sub_menu_row_index"] = 0

        elif app_state.get("menu_layer") == "DVD_BTN_MAP":
            render_dvd_button_mapping_popup(_menu_surf, app_state, db)

    elif app_state.get("show_quit_confirm", False):
        render_quit_prompt(_overlay_target(screen), active_theme, db)
        
    elif app_state.get("show_restart_confirm", False):
        elapsed_popup_ms = now_ticks_ms - app_state.get("restart_confirm_shown_at", now_ticks_ms)
        if elapsed_popup_ms >= CONFIRM_POPUP_IDLE_CLOSE_MS:
            log.warning("[ANTI-BURN-IN SHIELD] Restart popup timed out. Reverting changes.")
            app_state["show_restart_confirm"] = False
        else:
            rs_surf = _overlay_target(screen)
            w_w, w_h = rs_surf.get_size()
            
            native_box_w = 650
            native_box_h = 240
            
            box_w = min(native_box_w, w_w - 20)
            box_h = min(native_box_h, w_h - 20)
            box_x = (w_w - box_w) // 2
            box_y = (w_h - box_h) // 2
            
            scale_factor = 1.0 if w_w >= native_box_w else (w_w / 1920.0)
            
            import colorsys
            bg_hue = db.config.get("theme_bg_hue", 220) / 360.0 if db is not None else 220/360.0
            ui_hue = db.config.get("theme_ui_hue", 140) / 360.0 if db is not None else 140/360.0
            r, g, b = colorsys.hsv_to_rgb(ui_hue, 0.9, 1.0)
            NEON_GREEN = (int(r * 255), int(g * 255), int(b * 255))
            r, g, b = colorsys.hsv_to_rgb(bg_hue, 0.6, 0.15)
            MIDNIGHT_NAVY = (int(r * 255), int(g * 255), int(b * 255))
            TEXT_WHITE  = COLOR_TEXT_WHITE
            ARCADE_GOLD = COLOR_ARCADE_GOLD
            ACTION_RED  = COLOR_ACTION_RED
            
            slider_val = db.config.get("menu_opacity", 50) if db is not None else 50
            menu_opacity = int((slider_val / 100.0) * 255)
            popup_surface = pygame.Surface((box_w, box_h), pygame.SRCALPHA)
            popup_surface.fill(MIDNIGHT_NAVY + (menu_opacity,))
            rs_surf.blit(popup_surface, (box_x, box_y))
            
            border_thickness = 2 if w_w >= native_box_w else max(1, int(2 * scale_factor))
            pygame.draw.rect(rs_surf, NEON_GREEN, (box_x, box_y, box_w, box_h), border_thickness)
            
            size_lg = 18 if w_w >= native_box_w else max(10, int(18 * scale_factor))
            size_sm = 15 if w_w >= native_box_w else max(6, int(15 * scale_factor))
            size_info = 12 if w_w >= native_box_w else max(6, int(12 * scale_factor))
            
            font_lg = _cached_sys_font("Courier New", size_lg, bold=True)
            font_sm = _cached_sys_font("Courier New", size_sm, bold=True)
            font_info = _cached_sys_font("Courier New", size_info, bold=True)
            
            lbl_w1 = font_lg.render("RESTART IS REQUIRED TO", True, ARCADE_GOLD)
            lbl_w2 = font_lg.render("MAKE THIS CHANGE", True, ARCADE_GOLD)
            lbl_setup_warning = font_info.render("Make sure ES-DE.exe is already setup before turning on channel 03", True, ACTION_RED)
            
            padding_y1 = 20 if w_w >= native_box_w else max(5, int(20 * scale_factor))
            padding_y2 = 45 if w_w >= native_box_w else max(10, int(45 * scale_factor))
            padding_y3 = 75 if w_w >= native_box_w else max(15, int(75 * scale_factor))
            
            rs_surf.blit(lbl_w1, (box_x + (box_w // 2) - (lbl_w1.get_width() // 2), box_y + padding_y1))
            rs_surf.blit(lbl_w2, (box_x + (box_w // 2) - (lbl_w2.get_width() // 2), box_y + padding_y2))
            rs_surf.blit(lbl_setup_warning, (box_x + (box_w // 2) - (lbl_setup_warning.get_width() // 2), box_y + padding_y3))
            
            current_choice = app_state.get("restart_confirm_selection", "No")
            button_y = box_y + (135 if w_w >= native_box_w else max(25, int(135 * scale_factor)))
            # WARNING: every Yes/No popup draws its buttons through ui.draw_popup_yes_no: Yes green on the left, No red on the right (owner 2026-11-03).
            draw_popup_yes_no(rs_surf, box_x + box_w // 2, button_y, current_choice, True, font_sm, NEON_GREEN)
            
            time_left_sec = max(0, 20 - int(elapsed_popup_ms / 1000.0))
            lbl_foot = font_sm.render(f"AUTO-CLOSE IN {time_left_sec}S TO REVERT", True, ACTION_RED)
            footer_y = box_y + box_h - (25 if w_w >= native_box_w else max(5, int(25 * scale_factor)))
            rs_surf.blit(lbl_foot, (box_x + (box_w // 2) - (lbl_foot.get_width() // 2), footer_y))
            

    else:
        pass

    # WARNING: never draw a stale file-explorer UI on top of a DVD frame.
    _dvd_layer_active_now = (
        ch == "03"
        and game_deck is not None
        and (
            getattr(game_deck, "mode", "") == "DVD_PLAYER"
            or getattr(game_deck, "dvd_playback_active", False)
        )
    )
    if app_state.get("file_explorer_active", False) and not _dvd_layer_active_now:
        _fe_poll_scan()
        _fe_poll_expand()
        _fe_poll_bulkscan()
        _fe_x, _fe_y, _fe_w, _fe_h = _menu_panel_rect_on(screen)
        _fe_render(screen, active_theme, (_fe_x, _fe_y, _fe_w, _fe_h))

    # WARNING: the confirm popup and the Controls splash are drawn here, outside the show_menu branch above, so they show whether or not the Settings menu is open. The key handler swallows keys for them on the same flags, so a popup drawn only inside the menu branch is invisible on boot and eats C and M. The update popup wins over the splash; the splash shows again once it is answered.
    # WARNING: the update popup is drawn on top of the Controls splash, so a boot update prompt shows over it; every other confirm popup still replaces the splash.
    if app_state.get("show_splash", False) and (
            not app_state.get("show_clear_confirm", False)
            or app_state.get("clear_confirm_target") == "app_update"):
        render_controls_splash(_overlay_target_for_menu(screen), active_theme, db, app_state=app_state)
    if app_state.get("show_clear_confirm", False):
        _popup_target = _overlay_target(screen)
        render_clear_confirm_popup(_popup_target, active_theme, db, app_state)
        if app_state.get("update_install_active", False):
            _update_install_tick(now_ticks_ms)
            if app_state.get("update_install_active", False):
                _draw_update_install_overlay(_popup_target)

    if app_state.get("current_channel") == "03" and not app_state.get("is_loading", False) and game_deck is not None and not _surf_quiet:
        _mm_mode = getattr(game_deck, "mode", "BROWSE")
        _mm_dvd  = getattr(game_deck, "dvd_playback_active", False)
        _mm_prev = app_state.get("_ch03_mm_last_mode", "BROWSE")
        _mm_browsing      = _mm_mode in ("BROWSE", "ROMLIST")
        _mm_prev_browsing = _mm_prev in ("BROWSE", "ROMLIST")
        _mm_shield_active = pygame.time.get_ticks() < app_state.get("channel_switch_static_until", 0)
        if (_mm_mode in ("GAME", "DVD_PLAYER") or _mm_dvd) and _mm_prev_browsing:
            _stop_ch03_menu_music()
        elif _mm_browsing and not _mm_dvd and not _mm_prev_browsing and not _mm_shield_active:
            _start_ch03_menu_music()
        elif (_mm_browsing and not _mm_dvd and not _mm_shield_active
              and not _ch03_music_is_playing()
              and db is not None and db.config.get("ch03_menu_music")):
            _start_ch03_menu_music()
        elif (_mm_browsing and not _mm_dvd and not _mm_shield_active
              and db is not None and db.config.get("ch03_menu_music_enabled", True)
              and _ch03_music_is_stalled()):
            print("[CH03 MUSIC] Playback stalled in Opening/Buffering — forcing restart.")
            _stop_ch03_menu_music()
            _start_ch03_menu_music()
        app_state["_ch03_mm_last_mode"] = _mm_mode if not _mm_dvd else "DVD_PLAYER"

    if app_state.get("current_channel") == "03" and not app_state.get("is_loading", False):
        _dvd_playing = (
            game_deck is not None
            and getattr(game_deck, "dvd_playback_active", False)
            and not getattr(game_deck, "dvd_paused", True)
            and not getattr(game_deck, "dvd_in_menu", False)
        )
        _menu_overlay_active = (
            app_state.get("show_menu", False)
            or app_state.get("show_splash", False)
            or app_state.get("show_quit_confirm", False)
            or app_state.get("show_restart_confirm", False)
            or app_state.get("file_explorer_active", False)
        )
        _ss_enabled = db.config.get("ch03_screensaver_enabled", True) if db is not None else True
        if not _dvd_playing and not _menu_overlay_active and _ss_enabled:
            _ss_now = pygame.time.get_ticks()
            if app_state.get("ch03_screensaver_last_input", 0) == 0:
                app_state["ch03_screensaver_last_input"] = _ss_now

            _game_is_running = (
                game_deck is not None
                and getattr(game_deck, "mode", "BROWSE") == "GAME"
                and not getattr(game_deck, "emulator_loading", False)
                and game_deck.is_process_running()
            )

            if _game_is_running:
                _gp_last_input = getattr(game_deck, "last_gameplay_input_ticks", 0)
                if _gp_last_input > app_state["ch03_screensaver_last_input"]:
                    app_state["ch03_screensaver_last_input"] = _gp_last_input

            _ss_idle_ms = _ss_now - app_state["ch03_screensaver_last_input"]
            _ss_timeout_min = db.config.get("ch03_screensaver_timeout_min", 5) if db is not None else 5
            _SS_TIMEOUT_MS = _ss_timeout_min * 60_000

            _ss_key = (content_rect.width, content_rect.height)
            if (globals().get("_ch03_ss_surf_cache") is None
                    or globals().get("_ch03_ss_cache_key") != _ss_key):
                _ss_old_key = globals().get("_ch03_ss_cache_key")
                _raw = globals().get("_ch03_ss_raw")
                if _raw is None:
                    _ss_img_path = os.path.join(base_dir, "main", "images", "screensaver", "ScreenSaver.png")
                    try:
                        _raw = pygame.image.load(_ss_img_path).convert_alpha()
                    except Exception as _ss_load_err:
                        log.warning(f"[SCREENSAVER] Could not load ScreenSaver.png: {_ss_load_err}")
                        _raw = pygame.Surface((120, 60), pygame.SRCALPHA)
                        _raw.fill(COLOR_SCREENSAVER_FALLBACK)
                    globals()["_ch03_ss_raw"] = _raw
                _target_w = max(80, int(content_rect.width * 0.40))
                _aspect   = _raw.get_height() / max(1, _raw.get_width())
                _target_h = max(1, int(_target_w * _aspect))
                _scaled = pygame.transform.smoothscale(_raw, (_target_w, _target_h))
                globals()["_ch03_ss_surf_cache"] = _scaled
                globals()["_ch03_ss_vis"] = _screensaver_visible_rect(_scaled)
                globals()["_ch03_ss_cache_key"] = _ss_key
                if _ss_old_key and app_state.get("ch03_ss_x") is not None:
                    app_state["ch03_ss_x"] *= content_rect.width / max(1, _ss_old_key[0])
                    app_state["ch03_ss_y"] *= content_rect.height / max(1, _ss_old_key[1])

            if _ss_idle_ms >= _SS_TIMEOUT_MS:
                _ss_surf = globals()["_ch03_ss_surf_cache"]
                _ss_vis  = globals()["_ch03_ss_vis"]
                _scr_w, _scr_h = content_rect.width, content_rect.height

                if not app_state.get("ch03_screensaver_active", False) or app_state.get("ch03_ss_x") is None:
                    import random as _ssrand
                    import math   as _ssmath
                    _bx0, _bx1, _by0, _by1 = _screensaver_bounds(_scr_w, _scr_h, _ss_vis)
                    app_state["ch03_ss_x"] = float(_ssrand.uniform(_bx0 + (_bx1 - _bx0) / 4, _bx1 - (_bx1 - _bx0) / 4))
                    app_state["ch03_ss_y"] = float(_ssrand.uniform(_by0 + (_by1 - _by0) / 4, _by1 - (_by1 - _by0) / 4))
                    _ss_angle = _ssrand.uniform(28, 62)
                    app_state["ch03_ss_vx"] = _ssmath.cos(_ssmath.radians(_ss_angle)) * _ssrand.choice([-1, 1])
                    app_state["ch03_ss_vy"] = _ssmath.sin(_ssmath.radians(_ss_angle)) * _ssrand.choice([-1, 1])
                    app_state["ch03_ss_last_ms"]            = None
                    app_state["ch03_screensaver_active"]    = True
                    app_state["ch03_ss_was_game_running"]   = _game_is_running
                    if _game_is_running and game_deck is not None:
                        print("[SCREENSAVER] Freezing emulator.")
                        game_deck.set_paused(True, hard=True, reason="screensaver")

                _ss_tick = pygame.time.get_ticks()
                _ss_prev = app_state.get("ch03_ss_last_ms")
                _ss_dt = (1.0 / 60.0) if _ss_prev is None else min(_SS_MAX_DT_S, max(0.0, (_ss_tick - _ss_prev) / 1000.0))
                app_state["ch03_ss_last_ms"] = _ss_tick

                _new_x, _new_y, app_state["ch03_ss_vx"], app_state["ch03_ss_vy"] = _screensaver_step(
                    app_state["ch03_ss_x"], app_state["ch03_ss_y"],
                    app_state["ch03_ss_vx"], app_state["ch03_ss_vy"],
                    _ss_dt, _scr_w, _scr_h, _ss_vis)
                app_state["ch03_ss_x"] = _new_x
                app_state["ch03_ss_y"] = _new_y

                screen.fill((0, 0, 0), content_rect)
                screen.blit(_ss_surf, (content_rect.x + int(round(_new_x)), content_rect.y + int(round(_new_y))))

        else:
            app_state["ch03_screensaver_last_input"] = pygame.time.get_ticks()
            if app_state.get("ch03_screensaver_active", False):
                app_state["ch03_screensaver_active"] = False
                if app_state.get("ch03_ss_was_game_running", False) and game_deck is not None:
                    game_deck.set_paused(False, reason="screensaver", muted=False)
                app_state["ch03_ss_was_game_running"] = False

    elif app_state.get("current_channel") != "03":
        if app_state.get("ch03_screensaver_active", False):
            app_state["ch03_screensaver_active"] = False
        app_state["ch03_screensaver_last_input"] = 0
        app_state["ch03_ss_x"] = None
        app_state["ch03_ss_y"] = None
        app_state["ch03_ss_last_ms"] = None
        globals()["_ch03_ss_surf_cache"] = None
        globals()["_ch03_ss_cache_key"] = None

    try:
        from game_deck import xi_nav_sync as _xi_nav_sync
        _xi_nav_sync(
            ch03_active=(app_state.get("current_channel") == "03"
                         and not app_state.get("is_loading", False)
                         and not app_state.get("show_splash", False)
                         and not app_state.get("show_menu", False)
                         and not app_state.get("show_quit_confirm", False)
                         and not getattr(game_deck, "emulator_loading", False)
                         and not getattr(game_deck, "_libretro_loading", False)),
            game_running=(game_deck is not None
                          and getattr(game_deck, "mode", "BROWSE") == "GAME"
                          and not getattr(game_deck, "emulator_loading", False)),
            browse_mode=(game_deck is not None
                         and getattr(game_deck, "mode", "BROWSE") == "BROWSE"),
            dvd_active=(game_deck is not None
                        and (getattr(game_deck, "mode", "") == "DVD_PLAYER"
                             or getattr(game_deck, "dvd_playback_active", False))),
            dvd_in_menu=bool(game_deck is not None
                             and (getattr(game_deck, "dvd_in_menu", False)
                                  or getattr(game_deck, "dvd_exit_confirm", False)
                                  or getattr(game_deck, "dvd_return_menu_confirm", False))),
        )
    except Exception as e:
        _log_warn_throttled("xi_nav_state_sync", "Per-frame XInput nav-state sync failed: %s", e)

    _prof_mark("menus")

    # ========================================================================
    # SECTION: CRT power animation
    # ========================================================================

    _crt = app_state.get("crt_anim")
    if _crt is not None:
        _ct = pygame.time.get_ticks() - _crt["start_ms"]
        _ctot = _crt.get("total_ms", 900)
        _csw, _csh = screen.get_size()

        if _crt["phase"] == "off":
            if _crt.get("snapshot") is None:
                _crt["snapshot"] = screen.copy()
            _snap = _crt["snapshot"]

            if _ct < 450:
                _p = _ct / 450.0
                _bh = max(3, int(_csh * (1.0 - _p)))
                _by = (_csh - _bh) // 2
                _sc = pygame.transform.smoothscale(_snap, (_csw, _bh))
                screen.fill((0, 0, 0))
                screen.blit(_sc, (0, _by))
                _ga = min(210, int(_p * 230))
                _gs = pygame.Surface((_csw, _bh), pygame.SRCALPHA)
                _gs.fill((255, 255, 255, _ga))
                screen.blit(_gs, (0, _by))

            elif _ct < 700:
                _p = (_ct - 450) / 250.0
                _lw = max(2, int(_csw * (1.0 - _p)))
                _lx = (_csw - _lw) // 2
                _ly = _csh // 2 - 2
                _br = max(80, int(255 * (1.0 - _p * 0.55)))
                screen.fill((0, 0, 0))
                pygame.draw.rect(screen, (_br, _br, _br), (_lx, _ly, _lw, 4))
                for _gi in range(1, 6):
                    _ga = max(0, 170 - _gi * 35)
                    _gs2 = pygame.Surface((_lw, 4 + _gi * 3), pygame.SRCALPHA)
                    _gs2.fill((255, 255, 255, _ga))
                    screen.blit(_gs2, (_lx, _ly - (_gi * 3 // 2)))

            else:
                _p = (_ct - 700) / 200.0
                _da = max(0, int(255 * (1.0 - _p)))
                _dw = max(2, int(14 * (1.0 - _p)))
                _dh = max(1, int(4 * (1.0 - _p)))
                screen.fill((0, 0, 0))
                pygame.draw.ellipse(screen, (_da, _da, _da),
                                    (_csw // 2 - _dw, _csh // 2 - _dh, _dw * 2, _dh * 2))

        if _ct >= _ctot:
            _caction = _crt.get("action", "")
            app_state["crt_anim"] = None
            screen.fill((0, 0, 0))

            if _caction == "shutdown":
                log.info("[SHUTDOWN] power off chosen; shutting down")
                _composite_bezel_frame(_real_screen, screen)
                screen = _real_screen
                _present_cpu_window()
                _app_shutting_down.set()
                try: media.request_media_shutdown()
                except Exception as _swallowed_error:
                    _log_swallowed("main script: media.request_media_shutdown()", _swallowed_error)
                if db is not None and getattr(db, "server_listener", None) is not None:
                    try: db.server_listener.stop()
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: db.server_listener.stop()", _swallowed_error)
                if vlc_engine is not None:
                    try: vlc_engine.stop()
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: vlc_engine.stop()", _swallowed_error)
                    try: vlc_engine.close()
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: vlc_engine.close()", _swallowed_error)
                if dvd_engine is not None:
                    try: dvd_engine.stop()
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: dvd_engine.stop()", _swallowed_error)
                    try: dvd_engine.close()
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: dvd_engine.close()", _swallowed_error)
                if game_deck is not None and hasattr(game_deck, "shutdown_deck"):
                    try: game_deck.shutdown_deck()
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: game_deck.shutdown_deck()", _swallowed_error)
                try: _disconnect_remote_server("system shutdown")
                except Exception as _swallowed_error:
                    _log_swallowed("main script: _disconnect_remote_server('system shutdown')", _swallowed_error)
                if db is not None:
                    db.config["last_channel"] = app_state.get("pre_standby_channel", "05")
                    try: db.save_settings()
                    except Exception as _swallowed_error:
                        _log_swallowed("main script: db.save_settings()", _swallowed_error)
                if not app_state.get("shell_takeover_active", False):
                    log.warning("[SHUTDOWN] shutdown action reached without shell_takeover_active -- refusing to run shutdown /s /t 0.")
                elif os.name == "nt":
                    try: subprocess.Popen([_windows_system_exe("shutdown.exe", "System32"), "/s", "/t", "0"])
                    except Exception as _ce: log.warning(f"[SHUTDOWN] shutdown call failed: {_ce}")
                else:
                    print("[SHUTDOWN] Not Windows — power-off skipped.")
                pygame.quit()
                _hard_exit_process(0)

    # WARNING: thread this through to the shader branch, or toggling Scan Lines while Bezel is on is a silent no-op.

    _prof_mark("power_anim")

    # ========================================================================
    # SECTION: Final compositing & present
    # ========================================================================

    if (_surf_quiet
            and not app_state.get("show_menu", False)
            and not app_state.get("show_splash", False)
            and not app_state.get("show_quit_confirm", False)
            and not app_state.get("show_restart_confirm", False)
            and not app_state.get("file_explorer_active", False)):
        # WARNING: the grey cover is Black-style only; painting it in Static style hides the static the flip must show.
        if _configured_transition_style() != "static":
            screen.fill(COLOR_TRANSITION_GREY)
        elif ch in ("03", "04"):
            _render_transition_static(screen, _full_window_rect)

    _draw_channel_volume_osd("picture")

    _draw_status_banners(screen)

    _scanlines_wanted = _setting_on("fake_43_scanlines_enabled")
    _path_t0 = time.perf_counter()
    _gpu_frame_drawn = _gpu_draw_frame(
        _real_screen, screen,
        _content_ignores_package_aspect(w_w, w_h), _scanlines_wanted)
    if not _gpu_frame_drawn:
        _effect_mode = _crt_effect_mode(*screen.get_size(), _scanlines_wanted)
        _effect_rect = _effects_content_rect(*screen.get_size())
        if _effect_rect is not None:
            if _effect_mode == "warp":
                _apply_crt_shader(screen, _effect_rect, scanlines=_scanlines_wanted)
            elif _effect_mode == "plain":
                _apply_scanline_effect(screen, _effect_rect)

        _composite_bezel_frame(
            _real_screen, screen,
            ignore_package_aspect=_content_ignores_package_aspect(w_w, w_h))
    screen = _real_screen

    # WARNING: this call must stay last.
    if not _gpu_frame_drawn:
        _draw_channel_volume_osd("led")
    _path_draw_ms = (time.perf_counter() - _path_t0) * 1000.0
    _prof_mark("composite")

    _gov_flip_t0 = time.perf_counter()
    _frame_presented = _present_window(_gpu_frame_drawn)
    _path_present_ms = (time.perf_counter() - _gov_flip_t0) * 1000.0
    _governor_note_flip(_path_present_ms)
    _frame_path_note(_gpu_frame_drawn, _frame_presented, _path_draw_ms, _path_present_ms, screen.get_size(), _scanlines_wanted)
    _prof_mark("present")
    app_state["_chsurf_display_gate"] = False
    _gd = globals().get("game_deck", None)
    _tick_fps = _resolve_main_loop_tick_fps(_gd)

    _gov_tick_t0 = time.perf_counter()
    _prof_mark("tail")
    clock.tick(_tick_fps)
    _governor_note_tick_wait((time.perf_counter() - _gov_tick_t0) * 1000.0, _tick_fps, _governor_screen_kind(_gd))
    _prof_mark("wait")
    _prof_end()
